class MobileTouchController:
    def __init__(self, screen_w=1366, screen_h=768):
        self.screen_w = screen_w
        self.screen_h = screen_h
        
        # Virtual Joystick (bottom-left)
        self.joy_center_x = 155.0
        self.joy_center_y = screen_h - 155.0
        self.joy_radius = 72.0
        self.knob_radius = 32.0
        self.joy_knob_x = self.joy_center_x
        self.joy_knob_y = self.joy_center_y
        self.joy_active = False
        self.joy_touch_id = -1
        self.joy_val_x = 0.0  # -1.0 to 1.0
        self.joy_val_y = 0.0  # -1.0 to 1.0 (positive = forward)
        
        # Touch Camera Swipe Look (right half)
        self.look_touch_id = -1
        self.look_last_x = 0.0
        self.look_last_y = 0.0
        self.look_delta_x = 0.0
        self.look_delta_y = 0.0
        self.look_sensitivity = 0.0035
        
        # Action Buttons (right side)
        self.btn_use_x = screen_w - 110.0
        self.btn_use_y = screen_h - 130.0
        self.btn_use_r = 46.0
        self.btn_use_pressed = False
        
        self.btn_light_x = screen_w - 110.0
        self.btn_light_y = screen_h - 245.0
        self.btn_light_r = 34.0
        self.btn_light_pressed = False
        
        self.btn_run_x = screen_w - 215.0
        self.btn_run_y = screen_h - 130.0
        self.btn_run_r = 34.0
        self.btn_run_toggle = False
        self.btn_run_pressed = False
        
        self.btn_jump_x = screen_w - 215.0
        self.btn_jump_y = screen_h - 225.0
        self.btn_jump_r = 32.0
        self.btn_jump_pressed = False
        
        self.btn_menu_x = 48.0
        self.btn_menu_y = 48.0
        self.btn_menu_r = 24.0
        self.btn_menu_pressed = False
        
        self._down_touch_ids = set()
        self.is_mobile_mode = True

    def update(self):
        self.btn_use_pressed = False
        self.btn_light_pressed = False
        self.btn_jump_pressed = False
        self.btn_menu_pressed = False
        self.look_delta_x = 0.0
        self.look_delta_y = 0.0
        
        touch_count = get_touch_point_count()
        touches = []
        if touch_count > 0:
            for i in range(touch_count):
                pos = get_touch_position(i)
                tid = get_touch_point_id(i)
                touches.append((tid, float(pos.x), float(pos.y)))
        else:
            if is_mouse_button_down(MOUSE_BUTTON_LEFT):
                mpos = get_mouse_position()
                touches.append((999, float(mpos.x), float(mpos.y)))
                
        active_tids = {t[0] for t in touches}
        self._down_touch_ids = {tid for tid in self._down_touch_ids if tid in active_tids}
        
        if self.joy_touch_id not in active_tids:
            self.joy_active = False
            self.joy_touch_id = -1
            self.joy_knob_x = self.joy_center_x
            self.joy_knob_y = self.joy_center_y
            self.joy_val_x = 0.0
            self.joy_val_y = 0.0
            
        if self.look_touch_id not in active_tids:
            self.look_touch_id = -1

        for tid, tx, ty in touches:
            is_new = (tid not in self._down_touch_ids)
            
            # Button USE [E]
            if math.hypot(tx - self.btn_use_x, ty - self.btn_use_y) <= self.btn_use_r:
                if is_new:
                    self.btn_use_pressed = True
                    self._down_touch_ids.add(tid)
                continue
                
            # Button LIGHT [F]
            if math.hypot(tx - self.btn_light_x, ty - self.btn_light_y) <= self.btn_light_r:
                if is_new:
                    self.btn_light_pressed = True
                    self._down_touch_ids.add(tid)
                continue
                
            # Button RUN
            if math.hypot(tx - self.btn_run_x, ty - self.btn_run_y) <= self.btn_run_r:
                if is_new:
                    self.btn_run_toggle = not self.btn_run_toggle
                    self.btn_run_pressed = True
                    self._down_touch_ids.add(tid)
                continue
                
            # Button JUMP
            if math.hypot(tx - self.btn_jump_x, ty - self.btn_jump_y) <= self.btn_jump_r:
                if is_new:
                    self.btn_jump_pressed = True
                    self._down_touch_ids.add(tid)
                continue
                
            # Button MENU [ESC]
            if math.hypot(tx - self.btn_menu_x, ty - self.btn_menu_y) <= self.btn_menu_r:
                if is_new:
                    self.btn_menu_pressed = True
                    self._down_touch_ids.add(tid)
                continue

            # Virtual Joystick (left 45% of screen, lower half)
            if tx < self.screen_w * 0.45 and ty > self.screen_h * 0.35:
                if not self.joy_active and is_new:
                    self.joy_active = True
                    self.joy_touch_id = tid
                    self._down_touch_ids.add(tid)
                    
                if self.joy_touch_id == tid:
                    dx = tx - self.joy_center_x
                    dy = ty - self.joy_center_y
                    dist = math.hypot(dx, dy)
                    if dist > self.joy_radius:
                        dx = (dx / dist) * self.joy_radius
                        dy = (dy / dist) * self.joy_radius
                    self.joy_knob_x = self.joy_center_x + dx
                    self.joy_knob_y = self.joy_center_y + dy
                    self.joy_val_x = dx / self.joy_radius
                    self.joy_val_y = -dy / self.joy_radius
                continue

            # Swipe Look (right half)
            if tx >= self.screen_w * 0.45:
                if self.look_touch_id == -1 and is_new:
                    self.look_touch_id = tid
                    self.look_last_x = tx
                    self.look_last_y = ty
                    self._down_touch_ids.add(tid)
                elif self.look_touch_id == tid:
                    self.look_delta_x = tx - self.look_last_x
                    self.look_delta_y = ty - self.look_last_y
                    self.look_last_x = tx
                    self.look_last_y = ty
                continue

    def draw(self, hovered_object=None, torch_active=False):
        if not self.is_mobile_mode:
            return
            
        # Virtual Joystick
        draw_circle(int(self.joy_center_x), int(self.joy_center_y), int(self.joy_radius), Color(12, 22, 32, 130))
        draw_circle_lines(int(self.joy_center_x), int(self.joy_center_y), int(self.joy_radius), Color(0, 220, 255, 160))
        draw_line(int(self.joy_center_x - self.joy_radius + 8), int(self.joy_center_y),
                  int(self.joy_center_x + self.joy_radius - 8), int(self.joy_center_y), Color(0, 180, 220, 70))
        draw_line(int(self.joy_center_x), int(self.joy_center_y - self.joy_radius + 8),
                  int(self.joy_center_x), int(self.joy_center_y + self.joy_radius - 8), Color(0, 180, 220, 70))
        
        knob_col = Color(0, 240, 255, 220) if self.joy_active else Color(0, 180, 220, 150)
        draw_circle(int(self.joy_knob_x), int(self.joy_knob_y), int(self.knob_radius), knob_col)
        draw_circle_lines(int(self.joy_knob_x), int(self.joy_knob_y), int(self.knob_radius), Color(220, 250, 255, 240))
        
        # Button USE [E]
        is_interactive = (hovered_object is not None)
        use_bg = Color(245, 160, 30, 210) if is_interactive else Color(12, 22, 32, 130)
        use_border = Color(255, 210, 60, 255) if is_interactive else Color(0, 220, 255, 160)
        draw_circle(int(self.btn_use_x), int(self.btn_use_y), int(self.btn_use_r), use_bg)
        draw_circle_lines(int(self.btn_use_x), int(self.btn_use_y), int(self.btn_use_r), use_border)
        use_txt = "USE" if not is_interactive else "ACT"
        txt_w = measure_text(use_txt, 16)
        draw_text(use_txt, int(self.btn_use_x - txt_w // 2), int(self.btn_use_y - 8), 16, WHITE)
        
        # Button LIGHT [F]
        light_bg = Color(255, 220, 80, 200) if torch_active else Color(12, 22, 32, 130)
        light_border = Color(255, 240, 120, 255) if torch_active else Color(0, 220, 255, 140)
        draw_circle(int(self.btn_light_x), int(self.btn_light_y), int(self.btn_light_r), light_bg)
        draw_circle_lines(int(self.btn_light_x), int(self.btn_light_y), int(self.btn_light_r), light_border)
        light_txt = "LIGHT"
        lt_w = measure_text(light_txt, 14)
        draw_text(light_txt, int(self.btn_light_x - lt_w // 2), int(self.btn_light_y - 7), 14, WHITE if not torch_active else BLACK)
        
        # Button RUN
        run_bg = Color(0, 220, 150, 190) if self.btn_run_toggle else Color(12, 22, 32, 130)
        draw_circle(int(self.btn_run_x), int(self.btn_run_y), int(self.btn_run_r), run_bg)
        draw_circle_lines(int(self.btn_run_x), int(self.btn_run_y), int(self.btn_run_r), Color(0, 220, 255, 140))
        run_txt = "RUN"
        rn_w = measure_text(run_txt, 14)
        draw_text(run_txt, int(self.btn_run_x - rn_w // 2), int(self.btn_run_y - 7), 14, WHITE)
        
        # Button JUMP
        draw_circle(int(self.btn_jump_x), int(self.btn_jump_y), int(self.btn_jump_r), Color(12, 22, 32, 130))
        draw_circle_lines(int(self.btn_jump_x), int(self.btn_jump_y), int(self.btn_jump_r), Color(0, 220, 255, 140))
        jump_txt = "JUMP"
        jp_w = measure_text(jump_txt, 13)
        draw_text(jump_txt, int(self.btn_jump_x - jp_w // 2), int(self.btn_jump_y - 6), 13, WHITE)
        
        # Button MENU [ESC]
        draw_circle(int(self.btn_menu_x), int(self.btn_menu_y), int(self.btn_menu_r), Color(12, 22, 32, 160))
        draw_circle_lines(int(self.btn_menu_x), int(self.btn_menu_y), int(self.btn_menu_r), Color(0, 220, 255, 180))
        menu_txt = "ESC"
        mn_w = measure_text(menu_txt, 14)
        draw_text(menu_txt, int(self.btn_menu_x - mn_w // 2), int(self.btn_menu_y - 7), 14, WHITE)

mobile_ctrl = MobileTouchController()

class SpatialAudioSystem:
    def __init__(self):
        self.buffers = []
        self.sounds = {}
        self.emitters = []
        self._synthesize_procedural_soundscape()

    def _create_wave_sound(self, samples, sample_rate=44100):
        raw = bytearray()
        for s in samples:
            val = int(max(-1.0, min(1.0, s)) * 32767.0)
            raw.extend(pystruct.pack('<h', val))
        self.buffers.append(raw)
        w = Wave()
        w.frameCount = len(samples)
        w.sampleRate = sample_rate
        w.sampleSize = 16
        w.channels = 1
        w.data = ffi.from_buffer('void *', raw)
        return load_sound_from_wave(w)

    def _synthesize_procedural_soundscape(self):
        sr = 44100

        # 1. Flashlight Switch (tactile mechanical click)
        click = []
        for i in range(int(sr * 0.035)):
            t = i / float(sr)
            env = math.exp(-i / 140.0)
            sig = (random.random() * 2.0 - 1.0) * env * 0.7 + math.sin(2.0 * math.pi * 3400.0 * t) * env * 0.45
            click.append(sig * 0.8)
        self.sounds["torch_click"] = self._create_wave_sound(click)

        # 2. Footsteps - Concrete & Debris Crunch
        for var in range(3):
            step_creepy = []
            dur = 0.22
            for i in range(int(sr * dur)):
                t = i / float(sr)
                f_sub = 44.0 + var * 4.5
                env_thud = math.exp(-i / (sr * 0.042))
                sub = math.sin(2.0 * math.pi * f_sub * t) * env_thud * 0.42
                env_grit = math.exp(-i / (sr * 0.024)) * (0.8 + 0.2 * math.sin(2.0 * math.pi * 320.0 * t))
                grit = (random.random() * 2.0 - 1.0) * env_grit * 0.16
                env_ring = math.exp(-i / (sr * 0.085)) * min(1.0, i / 220.0)
                ring = (math.sin(2.0 * math.pi * 175.0 * t) * 0.5 +
                        math.sin(2.0 * math.pi * 275.0 * t) * 0.3) * env_ring * 0.11
                step_creepy.append((sub + grit + ring) * 0.36)
            self.sounds[f"step_creepy_{var}"] = self._create_wave_sound(step_creepy)
        self.sounds["step_concrete"] = self.sounds["step_creepy_0"]

        # 3. Footsteps - Viscous Sludge & Suction
        for var in range(2):
            sludge = []
            dur = 0.26
            for i in range(int(sr * dur)):
                t = i / float(sr)
                env_suction = math.exp(-i / (sr * 0.075)) * (1.0 - math.exp(-i / 140.0))
                freq_suck = 135.0 + (t / dur) * 360.0 + var * 25.0
                suck = math.sin(2.0 * math.pi * freq_suck * t) * env_suction * 0.32
                env_slop = math.exp(-i / (sr * 0.045))
                slop = (random.random() * 2.0 - 1.0) * env_slop * 0.20
                env_sub = math.exp(-i / (sr * 0.055))
                sub = math.sin(2.0 * math.pi * 50.0 * t) * env_sub * 0.28
                sludge.append((suck + slop + sub) * 0.38)
            self.sounds[f"step_sludge_{var}"] = self._create_wave_sound(sludge)
        self.sounds["step_puddle"] = self.sounds["step_sludge_0"]

        # 3b. Floor Creak / Rebar Stress Groan
        groan = []
        dur_g = 0.52
        for i in range(int(sr * dur_g)):
            t = i / float(sr)
            env_g = math.sin((i / float(sr * dur_g)) * math.pi) * math.exp(-i / (sr * 0.26))
            f_g = 78.0 + math.sin(2.0 * math.pi * 4.5 * t) * 5.0
            sig_g = (math.sin(2.0 * math.pi * f_g * t) * 0.60 +
                     math.sin(2.0 * math.pi * (f_g * 1.58) * t) * 0.35) * env_g
            groan.append(sig_g * 0.22)
        self.sounds["step_creak"] = self._create_wave_sound(groan)

        # 4. Glass Clink Impact
        glass = []
        for i in range(int(sr * 0.28)):
            t = i / float(sr)
            env = math.exp(-i / 1100.0)
            sig = (math.sin(2.0 * math.pi * 2150.0 * t) * 0.65 +
                   math.sin(2.0 * math.pi * 3380.0 * t) * 0.35 +
                   math.sin(2.0 * math.pi * 4820.0 * t) * 0.20) * env
            glass.append(sig * 0.65)
        self.sounds["glass_impact"] = self._create_wave_sound(glass)

        # 5. Plastic / Metal Impact
        tap = []
        for i in range(int(sr * 0.12)):
            t = i / float(sr)
            env = math.exp(-i / 380.0)
            sig = (math.sin(2.0 * math.pi * 460.0 * t) * 0.65 + (random.random() * 2.0 - 1.0) * 0.35) * env
            tap.append(sig * 0.55)
        self.sounds["plastic_impact"] = self._create_wave_sound(tap)

        # 6. Paper Rustle
        paper = []
        for i in range(int(sr * 0.16)):
            t = i / float(sr)
            env = math.exp(-i / 700.0)
            sig = (random.random() * 2.0 - 1.0) * env * 0.45
            paper.append(sig * 0.4)
        self.sounds["paper_rustle"] = self._create_wave_sound(paper)

        # 7. Item Pick Up Click
        pickup = []
        for i in range(int(sr * 0.05)):
            t = i / float(sr)
            env = math.exp(-i / 220.0)
            sig = (math.sin(2.0 * math.pi * 1800.0 * t) * 0.5 +
                   math.sin(2.0 * math.pi * 950.0 * t) * 0.5) * env
            pickup.append(sig * 0.6)
        self.sounds["item_pickup"] = self._create_wave_sound(pickup)

        # 8. High-Voltage Electric Arc Spark Burst
        spark = []
        for i in range(int(sr * 0.08)):
            t = i / float(sr)
            env = math.exp(-i / 320.0)
            sig = ((random.random() * 2.0 - 1.0) * 0.7 + math.sin(2.0 * math.pi * 4200.0 * t) * 0.4) * env
            spark.append(sig * 0.75)
        self.sounds["spark_burst"] = self._create_wave_sound(spark)

        # 9. Heavy Industrial Switch Clunk
        sw_clunk = []
        for i in range(int(sr * 0.14)):
            t = i / float(sr)
            env = math.exp(-i / 450.0)
            sig = (math.sin(2.0 * math.pi * 85.0 * t) * 0.7 + (random.random() * 2.0 - 1.0) * 0.35) * env
            sw_clunk.append(sig * 0.85)
        self.sounds["switch_clunk"] = self._create_wave_sound(sw_clunk)

        # 10. Breaker Blowout Pop & Arc
        breaker = []
        for i in range(int(sr * 0.32)):
            t = i / float(sr)
            env = math.exp(-i / 750.0)
            pop = math.sin(2.0 * math.pi * 65.0 * t) * math.exp(-i / 250.0) * 0.8
            arc = (random.random() * 2.0 - 1.0) * env * 0.65 + math.sin(2.0 * math.pi * 2800.0 * t) * env * 0.3
            breaker.append((pop + arc) * 0.9)
        self.sounds["breaker_blowout"] = self._create_wave_sound(breaker)

        # 11. Generator Startup Rev & Roar
        rev = []
        dur_rev = 1.85
        for i in range(int(sr * dur_rev)):
            t = i / float(sr)
            freq = 24.0 + (t / dur_rev) * 95.0
            env = min(1.0, t * 1.8)
            pulse = math.sin(2.0 * math.pi * freq * t) * 0.6 + math.sin(2.0 * math.pi * (freq * 0.5) * t) * 0.3
            noise = (random.random() * 2.0 - 1.0) * 0.25 * math.exp(-t * 0.8)
            rev.append((pulse + noise) * env * 0.85)
        self.sounds["generator_rev"] = self._create_wave_sound(rev)

        # 12. Power Surge Harmonic Swell
        surge = []
        dur_s = 1.2
        for i in range(int(sr * dur_s)):
            t = i / float(sr)
            f_hum = 60.0 + (t / dur_s) * 180.0
            env = math.sin((t / dur_s) * math.pi)
            sig = (math.sin(2.0 * math.pi * f_hum * t) * 0.6 +
                   math.sin(2.0 * math.pi * (f_hum * 2.0) * t) * 0.35 +
                   (random.random() * 2.0 - 1.0) * 0.12) * env
            surge.append(sig * 0.8)
        self.sounds["power_surge"] = self._create_wave_sound(surge)

        # 13. Heavy Hydraulic Door Slide
        door_s = []
        dur_d = 1.4
        for i in range(int(sr * dur_d)):
            t = i / float(sr)
            env = math.sin((t / dur_d) * math.pi)
            hiss = (random.random() * 2.0 - 1.0) * env * 0.35
            hum = math.sin(2.0 * math.pi * 88.0 * t) * env * 0.4
            door_s.append((hiss + hum) * 0.75)
        self.sounds["door_slide"] = self._create_wave_sound(door_s)

        # 13b. Heavy structural impacts for the ECHO door-breach cinematic.
        # These are synthesized as proper layered BANGS: an explosive transient, a
        # deep descending body hit, sub-bass pressure, and loose metallic frame rattle.
        def _make_breach_bang(duration, low_start, low_end, sub_gain, crack_gain, ring_gain, tail_gain):
            samples = []
            total = max(1, int(sr * duration))
            for i in range(total):
                t = i / float(sr)
                attack = min(1.0, t / 0.0018)
                progress = min(1.0, t / duration)
                body_phase = 2.0 * math.pi * (low_start * t + 0.5 * (low_end - low_start) * t * t / duration)
                body_env = math.exp(-t * 2.55)
                body = math.sin(body_phase) * body_env * 0.88
                sub = math.sin(2.0 * math.pi * (27.0 + 2.5 * progress) * t) * math.exp(-t * 5.6) * sub_gain
                sub += math.sin(2.0 * math.pi * 42.0 * t) * math.exp(-t * 8.5) * sub_gain * 0.36
                # Almost instantaneous broadband crack gives the sound its physical attack.
                crack_env = math.exp(-t * 54.0)
                crack = (random.random() * 2.0 - 1.0) * crack_gain * crack_env
                # A pair of decaying steel resonances suggest the door skin and frame ringing.
                ring_env = math.exp(-t * (5.8 + tail_gain * 1.7))
                ring = (math.sin(2.0 * math.pi * 118.0 * t) * 0.40 +
                        math.sin(2.0 * math.pi * 187.0 * t) * 0.32 +
                        math.sin(2.0 * math.pi * 307.0 * t) * 0.20) * ring_gain * ring_env
                delayed = 0.0
                if t > 0.028:
                    delayed_env = math.exp(-(t - 0.028) * 12.0)
                    delayed = (math.sin(2.0 * math.pi * 73.0 * t) * 0.34 +
                               (random.random() * 2.0 - 1.0) * 0.13) * tail_gain * delayed_env
                body_hit = body + sub + crack + ring + delayed
                samples.append(max(-0.985, min(0.985, body_hit * attack * 0.94)))
            return samples

        breach_thud = _make_breach_bang(0.92, 54.0, 32.0, 0.42, 0.28, 0.10, 0.22)
        self.sounds["door_breach_thud"] = self._create_wave_sound(breach_thud)
        # Bang 1: a massive distant hit that starts the camera whip toward the doorway.
        self.sounds["door_breach_bang_1"] = self._create_wave_sound(
            _make_breach_bang(1.38, 48.0, 23.0, 0.92, 0.66, 0.40, 0.58))
        # Bang 2: a closer, harsher strike; the door visibly buckles while this rings out.
        self.sounds["door_breach_bang_2"] = self._create_wave_sound(
            _make_breach_bang(1.32, 57.0, 27.0, 1.02, 0.76, 0.54, 0.72))
        # Final blast: the lock and frame fail and the panel is launched into the room.
        self.sounds["door_breach_blast"] = self._create_wave_sound(
            _make_breach_bang(1.62, 42.0, 18.0, 1.12, 0.94, 0.66, 0.92))

        # 14. Keypad Button Beep
        k_beep = []
        for i in range(int(sr * 0.045)):
            t = i / float(sr)
            env = math.exp(-i / 280.0)
            sig = math.sin(2.0 * math.pi * 1750.0 * t) * env * 0.45
            k_beep.append(sig)
        self.sounds["keypad_beep"] = self._create_wave_sound(k_beep)

        # 15. Access Granted Chime (Ascending two-tone)
        chime = []
        dur_c = 0.38
        for i in range(int(sr * dur_c)):
            t = i / float(sr)
            f = 1200.0 if t < 0.16 else 1850.0
            sub_t = t if t < 0.16 else (t - 0.16)
            env = math.exp(-sub_t / 0.055)
            sig = math.sin(2.0 * math.pi * f * t) * env * 0.55
            chime.append(sig)
        self.sounds["access_granted"] = self._create_wave_sound(chime)

        # 16. Access Denied Buzzer (Double low-freq buzz)
        buzz = []
        dur_b = 0.28
        for i in range(int(sr * dur_b)):
            t = i / float(sr)
            sub_t = t % 0.13
            env = math.exp(-sub_t / 0.045)
            sig = (math.sin(2.0 * math.pi * 160.0 * t) * 0.65 + (random.random() * 2.0 - 1.0) * 0.25) * env * 0.6
            buzz.append(sig)
        self.sounds["access_denied"] = self._create_wave_sound(buzz)

        # Gentle three-note mission-update chime shared with the Observation Room.
        mission_chime_samples = []
        note_len = int(sr * 0.145)
        for freq in (523.25, 659.25, 783.99):
            for i in range(note_len):
                t = i / float(sr)
                env = math.exp(-t * 8.8) * min(1.0, i / 120.0)
                fundamental = math.sin(2.0 * math.pi * freq * t)
                overtone = math.sin(2.0 * math.pi * freq * 2.0 * t) * 0.22
                mission_chime_samples.append((fundamental + overtone) * env * 0.25)
            mission_chime_samples.extend([0.0] * int(sr * 0.035))
        self.sounds["mission_chime"] = self._create_wave_sound(mission_chime_samples)

        # Soft, short typewriter tick for contextual player-thought text. This is
        # synthesized in the existing audio system, so no new module or external
        # asset is required. Playback volume is kept deliberately low by the caller.
        typewriter_tick = []
        typewriter_duration = 0.024
        for i in range(int(sr * typewriter_duration)):
            t = i / float(sr)
            envelope = math.exp(-t * 155.0)
            sweep = 2050.0 - 720.0 * (t / typewriter_duration)
            click = math.sin(2.0 * math.pi * sweep * t) * 0.48
            snap = (random.random() * 2.0 - 1.0) * 0.22
            typewriter_tick.append((click + snap) * envelope * 0.36)
        self.sounds["typewriter_tick"] = self._create_wave_sound(typewriter_tick)

        # Soft electronic objective-beacon ping. Replayed at a controlled interval by
        # the active objective logic, so volume can respond to player distance.
        waypoint_ping = []
        waypoint_ping_duration = 0.19
        for i in range(int(sr * waypoint_ping_duration)):
            t = i / float(sr)
            progress = t / waypoint_ping_duration
            freq = 880.0 + 115.0 * progress
            attack = min(1.0, t / 0.006)
            envelope = attack * math.exp(-t * 19.0)
            fundamental = math.sin(2.0 * math.pi * freq * t)
            overtone = math.sin(2.0 * math.pi * freq * 2.01 * t) * 0.22
            waypoint_ping.append((fundamental + overtone) * envelope * 0.23)
        self.sounds["waypoint_ping"] = self._create_wave_sound(waypoint_ping)

        # Distinct one-time arrival cue: a brighter ascending chime, separate from
        # the repetitive navigation ping and from the mission-completion sound.
        waypoint_arrival = []
        waypoint_arrival_duration = 0.58
        arrival_notes = ((659.25, 0.00, 0.30), (880.00, 0.12, 0.32), (1174.66, 0.27, 0.38))
        for i in range(int(sr * waypoint_arrival_duration)):
            t = i / float(sr)
            sig = 0.0
            for freq, start_t, note_dur in arrival_notes:
                local_t = t - start_t
                if 0.0 <= local_t <= note_dur:
                    attack = min(1.0, local_t / 0.014)
                    release = min(1.0, max(0.0, (note_dur - local_t) / 0.075))
                    envelope = attack * release * math.exp(-local_t * 1.65)
                    tone = math.sin(2.0 * math.pi * freq * local_t)
                    shimmer = math.sin(2.0 * math.pi * freq * 2.0 * local_t) * 0.18
                    sig += (tone + shimmer) * envelope * 0.18
            waypoint_arrival.append(max(-0.92, min(0.92, sig)))
        self.sounds["waypoint_arrival"] = self._create_wave_sound(waypoint_arrival)

        # Ambient Continuous Loops:
        # Loop 1: Fluorescent Ballast Hum
        hum = []
        for i in range(sr):
            t = i / float(sr)
            h = (math.sin(2.0 * math.pi * 60.0 * t) * 0.42 +
                 math.sin(2.0 * math.pi * 120.0 * t) * 0.34 +
                 math.sin(2.0 * math.pi * 180.0 * t) * 0.18 +
                 math.sin(2.0 * math.pi * 240.0 * t) * 0.09 +
                 (random.random() * 0.035 - 0.0175))
            hum.append(h * 0.30)
        self.sounds["loop_fluorescent"] = self._create_wave_sound(hum)

        # Loop 2: Stasis Pod Bubbler
        bub = []
        for i in range(sr):
            t = i / float(sr)
            s = 0.0
            for b in [0.08, 0.22, 0.41, 0.63, 0.84]:
                dt_b = (t - b) % 1.0
                if 0.0 <= dt_b < 0.04:
                    f = 320.0 + dt_b * 14000.0
                    env = math.sin(dt_b / 0.04 * math.pi)
                    s += math.sin(2.0 * math.pi * f * dt_b) * env * 0.38
            bub.append(s * 0.45)
        self.sounds["loop_bubbler"] = self._create_wave_sound(bub)

        # Loop 3: Ventilation Wall Fan
        fan = []
        for i in range(sr):
            t = i / float(sr)
            drone = (math.sin(2.0 * math.pi * 48.0 * t) * 0.48 +
                     math.sin(2.0 * math.pi * 96.0 * t) * 0.28 +
                     (random.random() * 0.06 - 0.03))
            fan.append(drone * 0.35)
        self.sounds["loop_fan"] = self._create_wave_sound(fan)

        # Loop 4: Running Main Generator Turbine
        gen_loop = []
        for i in range(sr):
            t = i / float(sr)
            rumble = (math.sin(2.0 * math.pi * 58.0 * t) * 0.45 +
                      math.sin(2.0 * math.pi * 116.0 * t) * 0.35 +
                      math.sin(2.0 * math.pi * 29.0 * t) * 0.25 +
                      (random.random() * 0.08 - 0.04))
            gen_loop.append(rumble * 0.40)
        self.sounds["loop_generator"] = self._create_wave_sound(gen_loop)

        # Personnel-card printer startup click and continuous 3D mechanism loop.
        # The loop combines a low drive motor, carriage whirr, and short stepper pulses.
        printer_start = []
        for i in range(int(sr * 0.34)):
            t = i / float(sr)
            env = math.exp(-t * 17.0)
            low = math.sin(2.0 * math.pi * (145.0 - 48.0 * t) * t) * 0.38
            clack_env = math.exp(-max(0.0, t - 0.055) * 55.0) if t >= 0.055 else 0.0
            clack = (math.sin(2.0 * math.pi * 1850.0 * t) * 0.35 +
                     (random.random() * 2.0 - 1.0) * 0.27) * clack_env
            printer_start.append((low * env + clack) * 0.50)
        self.sounds["printer_startup"] = self._create_wave_sound(printer_start)

        printer_loop = []
        for i in range(sr):
            t = i / float(sr)
            motor = (math.sin(2.0 * math.pi * 54.0 * t) * 0.24 +
                     math.sin(2.0 * math.pi * 108.0 * t) * 0.14 +
                     math.sin(2.0 * math.pi * 162.0 * t) * 0.07)
            # A carriage moves back and forth while the feeder steps once every 125 ms.
            sweep_phase = (t % 0.50) / 0.50
            sweep_cycles = 175.0 * (t % 0.50) + 170.0 * ((t % 0.50) ** 2) / 0.50
            carriage = math.sin(2.0 * math.pi * sweep_cycles) * (0.13 + 0.07 * sweep_phase)
            tick_phase = t % 0.125
            tick_env = math.exp(-tick_phase * 115.0)
            tick = (math.sin(2.0 * math.pi * 1420.0 * tick_phase) * 0.16 +
                    math.sin(2.0 * math.pi * 2310.0 * tick_phase) * 0.075) * tick_env
            texture = (random.random() * 2.0 - 1.0) * 0.022
            printer_loop.append((motor + carriage + tick + texture) * 0.62)
        self.sounds["loop_printer"] = self._create_wave_sound(printer_loop)

        # Register continuous 3D spatial emitters
        self.register_emitter("loop_fluorescent", Vector3(-4.5, 6.0, -2.0), base_volume=0.35, max_dist=12.0)
        self.register_emitter("loop_bubbler", Vector3(7.0, 1.8, 5.0), base_volume=0.45, max_dist=14.0)
        # Integrated Electricity Room fan: standalone-local X=21.65 plus the wing's +5.8 X offset.
        self.register_emitter("loop_fan", Vector3(27.45, 4.8, -2.5), base_volume=0.36, max_dist=15.0)

    def register_emitter(self, sound_name, pos, base_volume=0.4, max_dist=14.0):
        snd = self.sounds.get(sound_name)
        if snd:
            self.emitters.append({
                "sound": snd,
                "name": sound_name,
                "pos": pos,
                "base_volume": base_volume,
                "max_dist": max_dist
            })

    def unregister_emitter(self, sound_name):
        """Stop and remove a dynamically created continuous spatial sound emitter."""
        kept = []
        for em in self.emitters:
            if em.get("name") == sound_name:
                try:
                    if is_sound_playing(em["sound"]):
                        stop_sound(em["sound"])
                except Exception:
                    pass
            else:
                kept.append(em)
        self.emitters[:] = kept

    def compute_spatial_params(self, pos, cam, ref_dist=1.6, max_dist=16.0, base_vol=1.0):
        dx = pos.x - cam.position.x
        dy = pos.y - cam.position.y
        dz = pos.z - cam.position.z
        dist = math.sqrt(dx*dx + dy*dy + dz*dz)
        if dist < 0.001:
            return 0.5, base_vol

        atten = ref_dist / (ref_dist + 0.65 * dist + 0.08 * dist * dist)
        if dist > max_dist:
            atten = 0.0

        fwd = get_camera_forward(cam)
        rx = fwd.z
        rz = -fwd.x
        rlen = math.sqrt(rx*rx + rz*rz)
        if rlen > 0.0001:
            rx /= rlen
            rz /= rlen
        else:
            rx, rz = 1.0, 0.0

        dir_x = dx / dist
        dir_z = dz / dist
        pan_factor = dir_x * rx + dir_z * rz
        pan = 0.5 + 0.45 * pan_factor
        pan = max(0.05, min(0.95, pan))

        dot_fwd = dir_x * fwd.x + dir_z * fwd.z
        rear_muffle = 1.0 if dot_fwd >= 0.0 else (0.82 + 0.18 * (1.0 + dot_fwd))

        volume = max(0.0, min(1.0, base_vol * atten * rear_muffle))
        return pan, volume

    def play_spatial(self, sound_name, pos, cam, base_volume=1.0, max_dist=16.0, pitch_var=0.0):
        snd = self.sounds.get(sound_name)
        if not snd:
            return
        pan, vol = self.compute_spatial_params(pos, cam, max_dist=max_dist, base_vol=base_volume)
        if vol <= 0.005:
            return
        set_sound_volume(snd, vol)
        set_sound_pan(snd, pan)
        if pitch_var > 0.0:
            pitch = 1.0 + random.uniform(-pitch_var, pitch_var)
            set_sound_pitch(snd, pitch)
        play_sound(snd)

    def play_ui(self, sound_name, volume=0.5):
        snd = self.sounds.get(sound_name)
        if snd:
            set_sound_volume(snd, volume)
            set_sound_pan(snd, 0.5)
            play_sound(snd)

    def update_continuous_emitters(self, cam, is_paused=False):
        for em in self.emitters:
            snd = em["sound"]
            if is_paused:
                if is_sound_playing(snd):
                    stop_sound(snd)
                continue

            pan, vol = self.compute_spatial_params(em["pos"], cam, max_dist=em["max_dist"], base_vol=em["base_volume"])
            set_sound_volume(snd, vol)
            set_sound_pan(snd, pan)
            if not is_sound_playing(snd):
                play_sound(snd)

    def cleanup(self):
        for snd in self.sounds.values():
            if is_sound_playing(snd):
                stop_sound(snd)

spatial_audio = SpatialAudioSystem()

