try:
    _door_pcm_bytes = _door_audio_zlib.decompress(
        _door_audio_base64.b85decode(_DOOR_IMPACT_PCM_B85.encode("ascii")))
    _door_sample_count = len(_door_pcm_bytes) // 2
    _door_pcm_i16 = pystruct.unpack("<" + str(_door_sample_count) + "h", _door_pcm_bytes)
    _door_recorded_slam = [sample / 32768.0 for sample in _door_pcm_i16]
    # The first hit keeps the recording's natural pitch; later hits are slowed/pitched down
    # from that same real recording so the three events feel heavier without synthetic buzz.
    spatial_audio.sounds["door_breach_bang_1"] = spatial_audio._create_wave_sound(
        _door_recorded_slam, sample_rate=24000)
    spatial_audio.sounds["door_breach_bang_2"] = spatial_audio._create_wave_sound(
        _door_recorded_slam, sample_rate=21000)
    spatial_audio.sounds["door_breach_blast"] = spatial_audio._create_wave_sound(
        _door_recorded_slam, sample_rate=17500)
except Exception as _door_audio_embed_error:
    # Keep startup robust if the embedded sound is unavailable; the base game's sound
    # system remains usable, and the failure is visible in the runtime log.
    try:
        _runtime_diagnostic("Recorded door impact audio could not be loaded: " + repr(_door_audio_embed_error))
    except Exception:
        pass


# Procedural, repeating security siren for Protocol 04. The sound is attached to a 3D
# emitter only while lockdown is active, so it is spatial rather than a flat UI beep.
_lockdown_alarm_sr = 44100
_lockdown_alarm_samples = []
_lockdown_alarm_duration = 1.20
for _alarm_i in range(int(_lockdown_alarm_sr * _lockdown_alarm_duration)):
    _alarm_t = _alarm_i / float(_lockdown_alarm_sr)
    _alarm_phase = _alarm_t % 0.80
    _alarm_sweep = 0.5 - 0.5 * math.cos(2.0 * math.pi * (_alarm_phase / 0.80))
    _alarm_freq = 690.0 + 470.0 * _alarm_sweep
    _alarm_gate = 0.82 if _alarm_phase < 0.48 else 0.28
    _alarm_attack = min(1.0, _alarm_phase / 0.025)
    _alarm_signal = (math.sin(2.0 * math.pi * _alarm_freq * _alarm_t)
                     + 0.22 * math.sin(2.0 * math.pi * (_alarm_freq * 2.0) * _alarm_t))
    _lockdown_alarm_samples.append(0.36 * _alarm_gate * _alarm_attack * _alarm_signal)
spatial_audio.sounds["loop_security_alarm"] = spatial_audio._create_wave_sound(_lockdown_alarm_samples)
del _lockdown_alarm_samples

