# ============================================================
# ADVANCED SHADERS: PHYSICALLY BASED LIGHTING & POST PROCESSING
# ============================================================
VS_PBR_CODE = """#version 330
in vec3 vertexPosition;
in vec2 vertexTexCoord;
in vec3 vertexNormal;

out vec3 fragPosition;
out vec2 fragTexCoord;
out vec3 fragNormal;

uniform mat4 mvp;
uniform mat4 matModel;

void main() {
    fragPosition = vec3(matModel * vec4(vertexPosition, 1.0));
    fragTexCoord = vertexTexCoord;
    fragNormal = normalize(mat3(transpose(inverse(matModel))) * vertexNormal);
    gl_Position = mvp * vec4(vertexPosition, 1.0);
}
"""

FS_PBR_CODE = """#version 330
in vec3 fragPosition;
in vec2 fragTexCoord;
in vec3 fragNormal;

out vec4 finalColor;

uniform vec3 viewPos;
uniform vec3 ambientLight;
uniform vec4 objectColor;
uniform float roughness;
uniform float metallic;
uniform vec3 emissiveColor;

uniform vec3 torchPos;
uniform vec3 torchDir;
uniform float torchOn;
uniform float researchBlastMask;

uniform vec3 lightPos1;
uniform vec3 lightColor1;
uniform vec3 lightPos2;
uniform vec3 lightColor2;
uniform vec3 lightPos3;
uniform vec3 lightColor3;
uniform vec3 lightPos4;
uniform vec3 lightColor4;
uniform vec3 lightPos5;
uniform vec3 lightColor5;

const float PI = 3.14159265359;

float DistributionGGX(vec3 N, vec3 H, float r) {
    float a = r * r;
    float a2 = a * a;
    float NdotH = max(dot(N, H), 0.0);
    float NdotH2 = NdotH * NdotH;
    float denom = (NdotH2 * (a2 - 1.0) + 1.0);
    return a2 / (PI * denom * denom + 0.0001);
}

float GeometrySchlickGGX(float NdotV, float r) {
    float k = ((r + 1.0) * (r + 1.0)) / 8.0;
    return NdotV / (NdotV * (1.0 - k) + k);
}

float GeometrySmith(vec3 N, vec3 V, vec3 L, float r) {
    float NdotV = max(dot(N, V), 0.0);
    float NdotL = max(dot(N, L), 0.0);
    return GeometrySchlickGGX(NdotV, r) * GeometrySchlickGGX(NdotL, r);
}

vec3 FresnelSchlick(float cosTheta, vec3 F0) {
    return F0 + (1.0 - F0) * pow(clamp(1.0 - cosTheta, 0.0, 1.0), 5.0);
}

vec3 EvaluatePointLight(vec3 lightPos, vec3 lightColor, vec3 N, vec3 V, vec3 albedo, vec3 F0, float r, float m) {
    vec3 L = normalize(lightPos - fragPosition);
    vec3 H = normalize(V + L);
    float dist = length(lightPos - fragPosition);
    if (dist > 35.0) return vec3(0.0);
    float atten = 1.0 / (1.0 + 0.12 * dist + 0.028 * dist * dist);
    vec3 radiance = lightColor * atten;

    float NdotL = max(dot(N, L), 0.0);
    float NdotV = max(dot(N, V), 0.0);

    float NDF = DistributionGGX(N, H, r);
    float G = GeometrySmith(N, V, L, r);
    vec3 F = FresnelSchlick(max(dot(H, V), 0.0), F0);

    vec3 kS = F;
    vec3 kD = (vec3(1.0) - kS) * (1.0 - m);

    vec3 numerator = NDF * G * F;
    float denominator = 4.0 * NdotV * NdotL + 0.0001;
    vec3 specular = numerator / denominator;

    return (kD * albedo / PI + specular) * radiance * NdotL;
}

void main() {
    vec3 N = normalize(fragNormal);
    vec3 V = normalize(viewPos - fragPosition);
    vec3 albedo = pow(objectColor.rgb, vec3(2.2));
    vec3 F0 = mix(vec3(0.04), albedo, metallic);

    vec3 Lo = vec3(0.0);
    Lo += EvaluatePointLight(lightPos1, lightColor1, N, V, albedo, F0, roughness, metallic);
    Lo += EvaluatePointLight(lightPos2, lightColor2, N, V, albedo, F0, roughness, metallic);
    Lo += EvaluatePointLight(lightPos3, lightColor3, N, V, albedo, F0, roughness, metallic);
    Lo += EvaluatePointLight(lightPos4, lightColor4, N, V, albedo, F0, roughness, metallic);
    Lo += EvaluatePointLight(lightPos5, lightColor5, N, V, albedo, F0, roughness, metallic);

    // Realistic Flashlight Spotlight
    if (torchOn > 0.5) {
        vec3 L_torch = normalize(torchPos - fragPosition);
        vec3 H_torch = normalize(V + L_torch);
        float distTorch = length(torchPos - fragPosition);
        float theta = dot(normalize(-L_torch), normalize(torchDir));
        // A practical flashlight has a broad, readable centre beam with a soft outer edge.
        // The increased output and gentler falloff help the beam reach across larger rooms.
        float innerCut = 0.955;
        float outerCut = 0.77;
        
        if (theta > outerCut) {
            float spotIntensity = clamp((theta - outerCut) / (innerCut - outerCut), 0.0, 1.0);
            float attenTorch = 1.0 / (1.0 + 0.10 * distTorch + 0.018 * distTorch * distTorch);
            vec3 torchRadiance = vec3(1.00, 0.97, 0.90) * 6.2 * attenTorch * spotIntensity;

            float NdotL = max(dot(N, L_torch), 0.0);
            float NdotV = max(dot(N, V), 0.0);
            float NDF = DistributionGGX(N, H_torch, roughness);
            float G = GeometrySmith(N, V, L_torch, roughness);
            vec3 F = FresnelSchlick(max(dot(H_torch, V), 0.0), F0);
            vec3 kS = F;
            vec3 kD = (vec3(1.0) - kS) * (1.0 - metallic);
            vec3 spec = (NDF * G * F) / (4.0 * NdotV * NdotL + 0.0001);
            Lo += (kD * albedo / PI + spec) * torchRadiance * NdotL;
        }
    }

    vec3 ambient = ambientLight * albedo;
    vec3 color = ambient + Lo + emissiveColor;

    // General atmospheric depth fog keeps the normal abandoned-lab mood.
    float distCam = length(viewPos - fragPosition);
    float fogFactor = clamp((distCam - 6.0) / 34.0, 0.0, 0.78);
    vec3 fogColor = vec3(0.012, 0.015, 0.018);
    color = mix(color, fogColor, fogFactor);

    // When near/in the Electricity Room, fade Main Lab geometry to true black
    // before the far wall can appear as a pale rectangular render-limit. The amount
    // of this extra fog ramps smoothly across the doorway so it never switches on/off
    // in a single frame as the player enters or exits.
    if (fragPosition.x < 18.15) {
        float electricitySideFog = smoothstep(16.0, 20.5, viewPos.x);
        float distantMainLabFog = smoothstep(10.0, 20.0, distCam) * electricitySideFog;
        color = mix(color, vec3(0.0, 0.0, 0.0), distantMainLabFog);
    }

    // Matching Research Room exit treatment: when viewed from inside the north (+Z)
    // Research wing, distant fragments on the Main Lab side of the doorway fade to black.
    // The near doorway surround stays readable, but the far Main Lab does not bleed through
    // as a brightly detailed second room. This mirrors the Electricity Room's X-side mask.
    if (fragPosition.z < 18.15) {
        float researchSideFog = smoothstep(16.0, 20.5, viewPos.z);
        float distantResearchExitFog = smoothstep(10.0, 20.0, distCam) * researchSideFog;
        color = mix(color, vec3(0.0, 0.0, 0.0), distantResearchExitFog);
    }

    // Blast-only reciprocal dark-outside treatment: once both door leaves launch, the
    // distant Research Room backing fades quickly to near-black. This removes the pale
    // rectangular wall behind the opening while keeping the frame and nearer dust readable.
    if (researchBlastMask > 0.5 && viewPos.z < 18.15 && fragPosition.z > 18.15) {
        float distantInsideRoomFade = smoothstep(8.5, 14.5, distCam);
        color = mix(color, vec3(0.00012, 0.00018, 0.00024), distantInsideRoomFade);
    }

    finalColor = vec4(color, objectColor.a);
}
"""

VS_SCREEN_CODE = """#version 330
in vec3 vertexPosition;
in vec2 vertexTexCoord;
out vec2 fragTexCoord;
uniform mat4 mvp;
void main() {
    fragTexCoord = vertexTexCoord;
    gl_Position = mvp * vec4(vertexPosition, 1.0);
}
"""

FS_SCREEN_CODE = """#version 330
in vec2 fragTexCoord;
out vec4 finalColor;
uniform sampler2D texture0;
void main() {
    finalColor = texture(texture0, fragTexCoord);
}
"""

VS_PASSTHROUGH_CODE = """#version 330
in vec3 vertexPosition;
in vec2 vertexTexCoord;
out vec2 fragTexCoord;
uniform mat4 mvp;
void main() {
    fragTexCoord = vertexTexCoord;
    gl_Position = mvp * vec4(vertexPosition, 1.0);
}
"""

FS_CINEMATIC_POST_CODE = """#version 330
in vec2 fragTexCoord;
out vec4 finalColor;

uniform sampler2D texture0;
uniform float blurAmount;
uniform float time;
uniform float echoStrength;
uniform float echoTime;

vec3 ACESFilm(vec3 x) {
    float a = 2.51;
    float b = 0.03;
    float c = 2.43;
    float d = 0.59;
    float e = 0.14;
    return clamp((x*(a*x + b)) / (x*(c*x + d) + e), 0.0, 1.0);
}

float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    vec2 uv = fragTexCoord;
    vec2 texelSize = 1.0 / textureSize(texture0, 0);
    float echo = clamp(echoStrength, 0.0, 1.0);

    // ECHO no longer relies on a notice box: its signal physically tears the rendered
    // image, shifts colour channels and injects short, irregular luminance drops.
    float scanPhase = fract(uv.y * 41.0 + echoTime * 1.7);
    float tearBand = step(0.965, scanPhase) * echo;
    float horizontalTear = (sin(uv.y * 183.0 + echoTime * 31.0) * 0.0018
                            + tearBand * sin(echoTime * 37.0 + uv.y * 510.0) * 0.018) * echo;
    uv.x += horizontalTear;
    uv.y += sin(uv.x * 38.0 + echoTime * 15.0) * 0.0013 * echo;

    vec4 baseColor = texture(texture0, uv);
    if (echo > 0.001) {
        float split = 0.0018 * echo;
        float redChannel = texture(texture0, uv + vec2(split, 0.0)).r;
        float blueChannel = texture(texture0, uv - vec2(split, 0.0)).b;
        baseColor.rgb = vec3(redChannel, baseColor.g, blueChannel);
        float blink = step(0.91, fract(echoTime * 5.2 + sin(echoTime * 2.7) * 0.17)) * echo;
        baseColor.rgb *= 1.0 - blink * 0.76;
        baseColor.rgb += vec3(0.015, 0.035, 0.055) * tearBand;
    }

    // Performance-tuned restrained bloom: four neighbour samples instead of a 5x5
    // kernel at every pixel. It preserves a soft glint on LEDs and metal without the
    // large per-frame texture-sampling cost that was spiking frame time during turns.
    float bloomRadius = 1.35 + blurAmount * 2.0;
    vec3 bloomColor = vec3(0.0);
    vec3 sampleN = texture(texture0, uv + vec2(0.0, -texelSize.y * bloomRadius)).rgb;
    vec3 sampleS = texture(texture0, uv + vec2(0.0,  texelSize.y * bloomRadius)).rgb;
    vec3 sampleE = texture(texture0, uv + vec2( texelSize.x * bloomRadius, 0.0)).rgb;
    vec3 sampleW = texture(texture0, uv + vec2(-texelSize.x * bloomRadius, 0.0)).rgb;
    float lumN = dot(sampleN, vec3(0.2126, 0.7152, 0.0722));
    float lumS = dot(sampleS, vec3(0.2126, 0.7152, 0.0722));
    float lumE = dot(sampleE, vec3(0.2126, 0.7152, 0.0722));
    float lumW = dot(sampleW, vec3(0.2126, 0.7152, 0.0722));
    bloomColor += sampleN * max(lumN - 0.72, 0.0) * 0.32;
    bloomColor += sampleS * max(lumS - 0.72, 0.0) * 0.32;
    bloomColor += sampleE * max(lumE - 0.72, 0.0) * 0.32;
    bloomColor += sampleW * max(lumW - 0.72, 0.0) * 0.32;

    // Depth-of-field is only active while paused/inspecting; use a weighted 3x3 filter
    // instead of an expensive 9x9 kernel to keep modal camera turns responsive.
    vec3 blended = baseColor.rgb;
    if (blurAmount > 0.01) {
        vec3 dofSum = vec3(0.0);
        float dofWeight = 0.0;
        for (int x = -1; x <= 1; x++) {
            for (int y = -1; y <= 1; y++) {
                float wx = (x == 0) ? 2.0 : 1.0;
                float wy = (y == 0) ? 2.0 : 1.0;
                float w = wx * wy;
                vec2 off = vec2(float(x), float(y)) * texelSize * blurAmount * 4.2;
                dofSum += texture(texture0, uv + off).rgb * w;
                dofWeight += w;
            }
        }
        blended = dofSum / max(dofWeight, 0.001);
    }

    vec3 hdrColor = blended + bloomColor * 0.24;

    // ACES Tone Mapping
    vec3 ldrColor = ACESFilm(hdrColor * 1.20);

    // Vignette
    vec2 coord = (uv - 0.5) * 2.0;
    float vignette = 1.0 - dot(coord, coord) * 0.32;
    vignette = clamp(vignette, 0.0, 1.0);
    ldrColor *= vignette;

    // Camera sensor noise
    float grain = (rand(uv + vec2(time * 0.12, time * 0.07)) - 0.5) * 0.011;
    ldrColor += vec3(grain);

    // Gamma correction
    ldrColor = pow(clamp(ldrColor, 0.0, 1.0), vec3(1.0 / 2.2));

    finalColor = vec4(ldrColor, 1.0);
}
"""

pbr_shader = load_shader_from_memory(VS_PBR_CODE, FS_PBR_CODE)
