def generate_terminal_texture(main_text, sub_text="", bg_color=(18, 24, 20), text_color=(160, 240, 180)):
    img = PILImage.new("RGB", (1024, 512), bg_color)
    draw = PILImageDraw.Draw(img)
    # Scanline simulation
    for y in range(0, 512, 4):
        draw.line((0, y, 1023, y), fill=(int(bg_color[0]*0.7), int(bg_color[1]*0.7), int(bg_color[2]*0.7)))

    try:
        font_large = PILImageFont.truetype(r"C:\Windows\Fonts\arial.ttf", 64)
        font_sub = PILImageFont.truetype(r"C:\Windows\Fonts\arial.ttf", 36)
    except OSError:
        font_large = PILImageFont.load_default()
        font_sub = PILImageFont.load_default()

    draw.text((512, 210), main_text, font=font_large, fill=text_color, anchor="mm")
    if sub_text:
        draw.text((512, 290), sub_text, font=font_sub, fill=(text_color[0]//2, text_color[1]//2, text_color[2]//2), anchor="mm")

    # Flip horizontally for back-facing UV orientation
    img = img.transpose(PILImage.Transpose.FLIP_LEFT_RIGHT)
    buf = BytesIO()
    img.save(buf, format="PNG")
    raw = buf.getvalue()
    r_img = load_image_from_memory(b".png", raw, len(raw))
    tex = load_texture_from_image(r_img)
    unload_image(r_img)
    return tex

