def _echo_phase5_draw_monitor_text(text, x, y, font_size, color):
    """Draw legible standard-font text onto the in-world monitor, with a safe fallback."""
    try:
        if ECHO_PHASE5_UI_FONT is not None:
            draw_text_ex(ECHO_PHASE5_UI_FONT, str(text),
                         Vector2(float(x), float(y)), float(font_size), 0.25, color)
        else:
            draw_text(str(text), int(x), int(y), int(font_size), color)
    except Exception:
        draw_text(str(text), int(x), int(y), int(font_size), color)


def _echo_phase5_measure_monitor_text(text, font_size):
    try:
        if ECHO_PHASE5_UI_FONT is not None:
            return float(measure_text_ex(ECHO_PHASE5_UI_FONT, str(text), float(font_size), 0.25).x)
    except Exception:
        pass
    return float(measure_text(str(text), int(font_size)))


def _echo_phase5_wrap_monitor_text(text, font_size, max_width):
    """Wrap monitor text using the same font metrics used to render the letters."""
    words = str(text).split()
    if not words:
        return [""]
    lines = []
    current = ""
    for word in words:
        candidate = f"{current} {word}" if current else word
        if not current or _echo_phase5_measure_monitor_text(candidate, font_size) <= max_width:
            current = candidate
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
_phase5_terminal_mesh = gen_mesh_plane(2.58, 1.43, 1, 1)
for _phase5_v in range(_phase5_terminal_mesh.vertexCount):
    _phase5_vx = _phase5_terminal_mesh.vertices[_phase5_v * 3]
    _phase5_vz = _phase5_terminal_mesh.vertices[_phase5_v * 3 + 2]
    _phase5_u = (_phase5_vx + 1.29) / 2.58
    _phase5_vcoord = 0.5 - _phase5_vz / 1.43
    # RenderTexture2D needs a vertical correction, and this plane is viewed from the
    # monitor's -Z-facing side, so its horizontal U coordinate must also be reversed.
    # Without the U flip, every word appears mirrored left-to-right in the physical CRT.
    _phase5_terminal_mesh.texcoords[_phase5_v * 2] = 1.0 - _phase5_u
    _phase5_terminal_mesh.texcoords[_phase5_v * 2 + 1] = 1.0 - _phase5_vcoord
update_mesh_buffer(_phase5_terminal_mesh, 1, _phase5_terminal_mesh.texcoords,
                   _phase5_terminal_mesh.vertexCount * 2 * 4, 0)
