# ============================================================
# ISOLATED MAIN LAB FILTER + CENTRAL-HUB PERIMETER
# ============================================================
# Do not pull props from the neighbouring room source blocks into this isolated slice.
# Only the architectural boundary is enlarged; currently installed Main-Lab props and
# puzzle objects keep their known coordinates until the later furnishing pass.
_MAIN_LAB_MIN = -12.6
_MAIN_LAB_MAX = 12.6
_OFFROOM_INTERACTION_TYPES = {"master_terminal", "control_panel", "generator"}
major_solids[:] = [
    solid for solid in major_solids
    if (solid.item_type in {"light_switch", "archive_keypad"}
        or (_MAIN_LAB_MIN <= solid.pos.x <= _MAIN_LAB_MAX
            and _MAIN_LAB_MIN <= solid.pos.z <= _MAIN_LAB_MAX
            and solid.item_type not in _OFFROOM_INTERACTION_TYPES))
]
interactive_items[:] = [
    item for item in interactive_items
    if ((_MAIN_LAB_MIN < item.pos.x < _MAIN_LAB_MAX
         and _MAIN_LAB_MIN < item.pos.z < _MAIN_LAB_MAX)
        or item.name == "Emergency Cell B")
]
# Remove old 26 m perimeter colliders only, keeping switches, keypads and prop collisions.
major_solids[:] = [
    solid for solid in major_solids
    if not (abs(solid.pos.y - 3.5) < 0.01 and abs(solid.size.y - 7.0) < 0.01
            and (abs(abs(solid.pos.x) - 12.4) < 0.5 or abs(abs(solid.pos.z) - 12.4) < 0.5))
]
