# ============================================================
# PHYSICS SIMULATION STEP
# ============================================================
def step_physics_simulation(dt, cam):
    GRAVITY = -17.5
    for item in interactive_items:
        if item.picked_up or item.settled:
            continue

        item.vel.y += GRAVITY * dt
        air_drag = 0.98 if item.item_type != "doc" else 0.88
        item.vel.x *= air_drag
        item.vel.z *= air_drag

        new_x = item.pos.x + item.vel.x * dt
        new_y = item.pos.y + item.vel.y * dt
        new_z = item.pos.z + item.vel.z * dt

        item.rot.x += item.ang_vel.x * dt * 57.2958
        item.rot.y += item.ang_vel.y * dt * 57.2958
        item.rot.z += item.ang_vel.z * dt * 57.2958
        item.ang_vel.x *= 0.94
        item.ang_vel.y *= 0.94
        item.ang_vel.z *= 0.94

        half_h = item.size.y / 2.0
        half_w = max(item.size.x, item.size.z) / 2.0

        collided_surface_y = half_h
        for obs in major_solids:
            min_x = obs.bbox.min.x - half_w
            max_x = obs.bbox.max.x + half_w
            min_z = obs.bbox.min.z - half_w
            max_z = obs.bbox.max.z + half_w
            top_y = obs.bbox.max.y + half_h
            if min_x <= new_x <= max_x and min_z <= new_z <= max_z:
                if item.pos.y >= obs.bbox.max.y - 0.12 and top_y > collided_surface_y:
                    collided_surface_y = top_y

        if new_y <= collided_surface_y:
            new_y = collided_surface_y
            impact_speed = abs(item.vel.y)
            if impact_speed > 0.55:
                item.vel.y = -item.vel.y * item.restitution
                item.vel.x *= item.friction
                item.vel.z *= item.friction
                item.ang_vel.x = (random.random() - 0.5) * 5.0
                item.ang_vel.z = (random.random() - 0.5) * 5.0

                snd_vol = min(1.0, impact_speed / 5.5)
                if "Flask" in item.name or "Glass" in item.name:
                    spatial_audio.play_spatial("glass_impact", item.pos, cam, base_volume=snd_vol, pitch_var=0.08)
                elif item.item_type == "doc" or item.item_type == "photo":
                    spatial_audio.play_spatial("paper_rustle", item.pos, cam, base_volume=snd_vol * 0.7)
                else:
                    spatial_audio.play_spatial("plastic_impact", item.pos, cam, base_volume=snd_vol, pitch_var=0.1)
            else:
                item.vel.y = 0.0
                item.vel.x *= 0.82
                item.vel.z *= 0.82
                item.rot.x *= 0.82
                item.rot.z *= 0.82
                if abs(item.vel.x) < 0.06 and abs(item.vel.z) < 0.06 and abs(item.vel.y) < 0.06:
                    item.vel = Vector3(0.0, 0.0, 0.0)
                    item.ang_vel = Vector3(0.0, 0.0, 0.0)
                    item.rot.x = 0.0
                    item.rot.z = 0.0
                    item.settled = True

        item.pos = Vector3(new_x, new_y, new_z)
        item.recalculate_bbox()

def check_player_box_collision(pos):
    p_box = BoundingBox(
        Vector3(pos.x - LAB_PLAYER_RADIUS, pos.y - 1.3, pos.z - LAB_PLAYER_RADIUS),
        Vector3(pos.x + LAB_PLAYER_RADIUS, pos.y + 0.15, pos.z + LAB_PLAYER_RADIUS)
    )
    for solid in major_solids:
        if check_collision_boxes(p_box, solid.bbox):
            return True

    # Door leaves also block the player while shut. These virtual barriers sit inside
    # the visible panels; the physical room shells remain isolated until room merging.
    if 'archive_door_open' in globals() and archive_door_open < 0.96:
        if (p_box.max.z >= 17.20 and p_box.min.z <= 17.80
                and p_box.max.x >= -2.72 and p_box.min.x <= 2.72):
            return True
    if 'electrical_door_open' in globals() and electrical_door_open < 0.96:
        if (p_box.max.x >= 17.15 and p_box.min.x <= 17.75
                and p_box.max.z >= -4.70 and p_box.min.z <= 0.70):
            return True
    # Observation Room sliding-door collision. Keep the barrier on the actual door plane,
    # not almost a metre out into the Main Lab (the old wide barrier felt like an invisible wall).
    # Once E is used at the doorway, the leaves slide apart and this barrier is removed.
    if ('observation_door_open' not in globals() or observation_door_open < 0.96):
        if (p_box.min.x <= -17.82 and p_box.max.x >= -18.42
                and p_box.max.z >= -1.35 and p_box.min.z <= 1.35):
            return True
    return False

def _resolve_player_collision_step(old_pos, new_pos):
    # SECURITY ROOM OPEN-PORTAL TRAVERSAL FIX (v171).
    # The Security annex has two aligned wall segments and two short connector side-walls.
    # The generic axis-slide solver could catch the player against the overlapping AABBs at
    # the exact threshold, making the open doorway feel like an invisible/glitching wall.
    # While the player's movement path is within the connector's X band and is already
    # aligned with the shared clear lane, resolve the crossing directly. Normal collisions
    # resume as soon as the player clears the connector; this does not bypass furniture or
    # wall collisions elsewhere in the room.
    _sec_min_x = min(float(old_pos.x), float(new_pos.x))
    _sec_max_x = max(float(old_pos.x), float(new_pos.x))
    _sec_in_connector_x_band = (_sec_min_x <= -17.30 and _sec_max_x >= -19.35)
    # Intersect the Main Lab opening (z 9.7..12.9), annex opening (9.0..9.78 and
    # 12.82..21.4 are solid), and the connector partitions. Keep the body clear of jambs.
    _sec_safe_z_min = 10.30
    _sec_safe_z_max = 12.30
    _sec_old_z = float(old_pos.z)
    _sec_new_z = float(new_pos.z)
    # Both ends of this small movement step must already be inside the clear corridor.
    # This avoids snapping the player sideways into the lane or skipping other collisions.
    _sec_aligned = (_sec_safe_z_min <= _sec_old_z <= _sec_safe_z_max and
                    _sec_safe_z_min <= _sec_new_z <= _sec_safe_z_max and
                    abs(_sec_new_z - _sec_old_z) <= 0.35)
    if _sec_in_connector_x_band and _sec_aligned:
        return Vector3(float(new_pos.x), float(new_pos.y), float(new_pos.z))

    # Observation Room open-portal traversal fix (v73).
    # The video showed the player could pass through only by approaching at a particular
    # angle. The general axis-slide collision resolver can catch the player on adjacent
    # jamb/shelf-level colliders during a diagonal crossing, even though the door is open.
    # While the door is fully open, provide a short, explicit clearance corridor through
    # the doorway. This is limited to the portal's X band and physical Z opening; all
    # ordinary room/furniture collision remains active everywhere outside this crossing.
    _obs_portal_open = float(globals().get("observation_door_open", 0.0)) >= 0.96
    _obs_dx = float(new_pos.x) - float(old_pos.x)
    _obs_path_min_x = min(float(old_pos.x), float(new_pos.x))
    _obs_path_max_x = max(float(old_pos.x), float(new_pos.x))
    _obs_path_intersects_portal = (
        _obs_path_min_x <= -17.30 and _obs_path_max_x >= -19.35
    )
    _obs_path_overlaps_opening = (
        min(float(old_pos.z), float(new_pos.z)) <= 2.70
        and max(float(old_pos.z), float(new_pos.z)) >= -2.70
    )
    if (_obs_portal_open and abs(_obs_dx) > 1e-5
            and _obs_path_intersects_portal and _obs_path_overlaps_opening):
        # The aperture is 5.4 m wide, but the player's radius needs a small margin from
        # the jambs. Keep the player-centre within +/-2.18 m while traversing, preventing
        # a side-wall AABB from snagging the capsule during diagonal movement.
        # Do not clamp X to the portal-band edges: let the player actually clear the
        # threshold so the special path naturally stops on the next frame.
        _obs_portal_x = float(new_pos.x)
        _obs_portal_z = max(-2.18, min(2.18, float(new_pos.z)))
        return Vector3(_obs_portal_x, float(new_pos.y), _obs_portal_z)

    if not check_player_box_collision(new_pos):
        res = Vector3(new_pos.x, new_pos.y, new_pos.z)
    else:
        test_x = Vector3(new_pos.x, new_pos.y, old_pos.z)
        can_move_x = not check_player_box_collision(test_x)

        test_z = Vector3(old_pos.x, new_pos.y, new_pos.z)
        can_move_z = not check_player_box_collision(test_z)

        if can_move_x and not can_move_z:
            res = test_x
        elif can_move_z and not can_move_x:
            res = test_z
        elif can_move_x and can_move_z:
            dx = abs(new_pos.x - old_pos.x)
            dz = abs(new_pos.z - old_pos.z)
            res = test_x if dx >= dz else test_z
        else:
            res = Vector3(old_pos.x, new_pos.y, old_pos.z)

    # Continuous Main Lab + Security annex bounds.
    # IMPORTANT: detect a requested crossing into the open Security aperture BEFORE
    # clamping x to the Main Lab boundary. The old test only looked at the already-resolved
    # position, so the -17.42 clamp prevented the player ever reaching x < -18.24 and
    # created an invisible wall across the doorway.
    _sec_aperture = MAIN_LAB_ROOM_DEFINITION["walls"]["west"]["secondary_openings"][0]["opening_range_m"]
    _sec_entry_z_min = _sec_aperture[0] + LAB_PLAYER_RADIUS + 0.05
    _sec_entry_z_max = _sec_aperture[1] - LAB_PLAYER_RADIUS - 0.05
    _inside_security_entry_lane = (
        _sec_entry_z_min <= res.z <= _sec_entry_z_max
        and min(old_pos.x, new_pos.x, res.x) < -17.42
    )
    # Once the player has crossed into the Security annex, keep its expanded X bounds active.
    _already_in_security_extension = (res.x < -18.24 or old_pos.x < -18.24 or new_pos.x < -18.24)
    in_security_extension_span = _inside_security_entry_lane or _already_in_security_extension

    # Electricity is the symmetric east-side extension. Only the real open doorway lane can
    # extend the movement bounds from the Main Lab; the door-leaf collision above still blocks
    # the crossing until the sliding panels have fully cleared. No scene handoff or teleport occurs.
    _electric_entry_lane = (
        ELECTRICITY_ROOM_ENTRY_Z_MIN <= res.z <= ELECTRICITY_ROOM_ENTRY_Z_MAX
        and max(old_pos.x, new_pos.x, res.x) > 17.42
    )
    _already_in_electricity_extension = (
        res.x > 18.24 or old_pos.x > 18.24 or new_pos.x > 18.24
    )
    in_electricity_extension_span = _electric_entry_lane or _already_in_electricity_extension

    # Research Room is entered through the north (+Z) Main Lab door at x ~= 0.
    # Detect the crossing before the Main-Lab boundary clamp, just like the two existing annexes.
    _research_entry_lane = (
        RESEARCH_ROOM_ENTRY_X_MIN <= res.x <= RESEARCH_ROOM_ENTRY_X_MAX
        and max(old_pos.z, new_pos.z, res.z) > 17.42
    )
    # RESEARCH ROOM AND SECURITY ROOM BOTH HAVE NORTHWARD (+Z) SPANS. Do not classify
    # every point with z > 18.24 as Research: that used to capture the Security Room's
    # far cupboards (x around -25, z around 20) and clamp x to the Research Room limit,
    # which looked like a teleport toward the doorway. The room extension only remains
    # active when the whole movement segment is inside Research's lateral X envelope.
    _research_path_min_x = min(float(old_pos.x), float(new_pos.x), float(res.x))
    _research_path_max_x = max(float(old_pos.x), float(new_pos.x), float(res.x))
    _research_path_inside_x_span = (
        _research_path_min_x >= -RESEARCH_ROOM_PLAYER_X_LIMIT - 0.55
        and _research_path_max_x <= RESEARCH_ROOM_PLAYER_X_LIMIT + 0.55
    )
    _already_in_research_extension = (
        (res.z > 18.24 or old_pos.z > 18.24 or new_pos.z > 18.24)
        and _research_path_inside_x_span
    )
    in_research_extension_span = _research_entry_lane or _already_in_research_extension

    # Observation Room is the west (-X) extension. Keep the crossing lane aligned with
    # the physical opening; v73's fully-open portal path handles the actual threshold move.
    _observation_entry_lane = (
        -2.18 <= res.z <= 2.18
        and min(old_pos.x, new_pos.x, res.x) < -17.42
    )
    # The old test classified every position west of the Main Lab as Observation Room.
    # Security is also west of the Main Lab, but occupies z=[9, 21]; applying Observation
    # bounds there clamped z from the Security doorway to 7.78 and looked like a teleport.
    # Only retain Observation bounds while this movement step stays inside that room's z span.
    _obs_path_min_z = min(float(old_pos.z), float(new_pos.z), float(res.z))
    _obs_path_max_z = max(float(old_pos.z), float(new_pos.z), float(res.z))
    _obs_path_inside_observation_z_span = (_obs_path_min_z >= -16.20 and _obs_path_max_z <= 8.20)
    _already_in_observation_extension = (
        (res.x < -18.24 or old_pos.x < -18.24 or new_pos.x < -18.24)
        and _obs_path_inside_observation_z_span
    )
    in_observation_extension_span = _observation_entry_lane or _already_in_observation_extension

    if in_research_extension_span:
        res.x = max(-RESEARCH_ROOM_PLAYER_X_LIMIT,
                    min(RESEARCH_ROOM_PLAYER_X_LIMIT, res.x))
        # Allow backing through the doorway into the Main Lab; the next frame returns to
        # Main-Lab bounds unless the player is still inside the Research extension.
        res.z = max(RESEARCH_ROOM_PLAYER_Z_MIN,
                    min(RESEARCH_ROOM_PLAYER_Z_MAX, res.z))
    elif in_observation_extension_span:
        # Room walk limits sit just inside the solid perimeter walls. The east bound
        # reaches back through the shared doorway so the player can return to the Main Lab.
        res.x = max(-42.48, min(-17.42, res.x))
        res.z = max(-15.78, min(7.78, res.z))
    else:
        min_x = -30.42 if in_security_extension_span else -17.42
        max_x = ELECTRICITY_ROOM_PLAYER_X_MAX if in_electricity_extension_span else 17.42
        res.x = max(min_x, min(max_x, res.x))
        if res.x < -18.24:
            res.z = max(SECURITY_WALK_Z_MIN, min(SECURITY_WALK_Z_MAX, res.z))
        elif in_electricity_extension_span and (
                res.x > 17.42 or old_pos.x > 17.42 or new_pos.x > 17.42):
            res.z = max(ELECTRICITY_ROOM_WALK_Z_MIN,
                        min(ELECTRICITY_ROOM_WALK_Z_MAX, res.z))
        else:
            res.z = max(-17.42, min(17.42, res.z))
    return res


def resolve_player_collision(old_pos, new_pos):
    """Resolve movement with small swept steps and physical AABB collision only.

    Security Room movement must never be corrected by snapping the player to a room
    centre or doorway. Every substep is resolved by the same wall/furniture colliders
    used in the rest of the game; when an obstacle is contacted, movement stops on the
    blocked axis and can continue sliding along the wall on the free axis.
    """
    dx = float(new_pos.x) - float(old_pos.x)
    dy = float(new_pos.y) - float(old_pos.y)
    dz = float(new_pos.z) - float(old_pos.z)

    # Fine swept increments prevent tunnelling through thin architectural colliders.
    max_step = 0.10
    steps = max(1, int(math.ceil(max(abs(dx), abs(dz)) / max_step)))
    current = Vector3(float(old_pos.x), float(old_pos.y), float(old_pos.z))

    for step_i in range(1, steps + 1):
        t = step_i / float(steps)
        target = Vector3(
            float(old_pos.x) + dx * t,
            float(old_pos.y) + dy * t,
            float(old_pos.z) + dz * t,
        )
        # This existing resolver checks solid wall/prop AABBs and contains the narrowly
        # scoped, correctly aligned open-doorway traversals. Crucially, there is no later
        # Security-specific coordinate clamp that can move the player sideways to a door.
        stepped = _resolve_player_collision_step(current, target)
        current = Vector3(float(stepped.x), float(stepped.y), float(stepped.z))

    return current

def get_camera_forward(cam):
    dx = cam.target.x - cam.position.x
    dy = cam.target.y - cam.position.y
    dz = cam.target.z - cam.position.z
    length = math.sqrt(dx*dx + dy*dy + dz*dz)
    return Vector3(dx/length, dy/length, dz/length) if length > 0.0001 else Vector3(0.0, 0.0, 1.0)

def is_in_puddle(x, z):
    puddles = [(-4.5, -2.5, 3.5, 2.8), (3.5, 4.2, 4.2, 3.1), (1.0, -6.5, 2.4, 2.0)]
    for px, pz, sx, sz in puddles:
        if abs(x - px) <= sx / 2.0 and abs(z - pz) <= sz / 2.0:
            return True
    return False

# ============================================================
# COMPREHENSIVE 3D PROPS & ENVIRONMENT RENDERERS
# ============================================================
def draw_erlenmeyer_flask(pos, rot, fluid_level=0.72):
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot.x, 1, 0, 0)
    rl_rotatef(rot.y, 0, 1, 0)
    rl_rotatef(rot.z, 0, 0, 1)
    draw_pbr_cone(Vector3(0, 0.14, 0), 0.22, 0.28, C_GLASS_EDGE, roughness=0.10, metallic=0.05)
    draw_pbr_cylinder(Vector3(0, 0.02, 0), 0.22, 0.04, C_GLASS_EDGE, roughness=0.15, metallic=0.05)
    fluid_h = 0.22 * fluid_level
    draw_pbr_cone(Vector3(0, fluid_h/2.0 + 0.02, 0), 0.20, fluid_h, C_BEAKER_FLUID, roughness=0.15, emissive=Vector3(0.045, 0.30, 0.12))
    draw_pbr_cylinder(Vector3(0, 0.38, 0), 0.068, 0.20, C_GLASS_EDGE, roughness=0.10)
    draw_pbr_cone(Vector3(0, 0.51, 0), 0.065, 0.07, C_RUBBER, roughness=0.85)
    rl_pop_matrix()

def draw_keycard(pos, rot):
    """Detailed Level-4 access card: layered polymer, chip contacts, stripe and ID marks."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot.x, 1, 0, 0)
    rl_rotatef(rot.y, 0, 1, 0)
    rl_rotatef(rot.z, 0, 0, 1)
    # Dark polymer core and thin edge laminations create a visible physical thickness.
    draw_pbr_box(Vector3(0, 0, 0), Vector3(0.56, 0.030, 0.36), C_METAL_DARK, roughness=0.34, metallic=0.32)
    draw_pbr_box(Vector3(0, 0.017, 0), Vector3(0.545, 0.006, 0.345), Color(218, 226, 229, 255), roughness=0.29, metallic=0.12)
    draw_pbr_box(Vector3(0, 0.021, -0.122), Vector3(0.52, 0.004, 0.072), C_METAL_MID, roughness=0.48, metallic=0.72)
    # Gold smart-card contact plate, split into individual pads.
    draw_pbr_box(Vector3(-0.115, 0.023, 0.025), Vector3(0.145, 0.005, 0.115), C_BRASS, roughness=0.22, metallic=0.9)
    for cx in (-0.155, -0.115, -0.075):
        for cz in (-0.006, 0.025, 0.056):
            draw_pbr_box(Vector3(cx, 0.026, cz), Vector3(0.028, 0.002, 0.022),
                         Color(218, 183, 91, 255), roughness=0.22, metallic=0.92)
    # Printed ID panel, portrait block, fine registration bars and authority stripe.
    draw_pbr_box(Vector3(0.155, 0.023, 0.022), Vector3(0.105, 0.004, 0.115), C_METAL_EDGE, roughness=0.6, metallic=0.35)
    draw_pbr_box(Vector3(0.155, 0.026, 0.025), Vector3(0.070, 0.002, 0.075), C_METAL_DARK, roughness=0.8)
    for i, z in enumerate((0.075, 0.052, 0.029, 0.006, -0.017)):
        draw_pbr_box(Vector3(0.025, 0.024, z), Vector3(0.105 if i < 3 else 0.075, 0.002, 0.006),
                     C_METAL_MID, roughness=0.65, metallic=0.18)
    draw_pbr_box(Vector3(0.0, 0.024, 0.157), Vector3(0.47, 0.004, 0.018), C_CYAN,
                 roughness=0.25, metallic=0.38, emissive=Vector3(0.015, 0.12, 0.16))
    draw_pbr_box(Vector3(0.222, 0.024, -0.055), Vector3(0.055, 0.003, 0.018), C_GREEN_DIM,
                 roughness=0.18, emissive=Vector3(0.03, 0.35, 0.08))
    # Small corner markings and perimeter rim make the card read as a manufactured item.
    for x in (-0.265, 0.265):
        for z in (-0.165, 0.165):
            draw_pbr_box(Vector3(x, 0.022, z), Vector3(0.025, 0.003, 0.018), C_METAL_DARK, roughness=0.48, metallic=0.3)
    rl_pop_matrix()

