def draw_document_clipboard(pos, rot):
    """Aged spiral-bound research notepad, visually aligned with Observation Room notes."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot.x, 1, 0, 0)
    rl_rotatef(rot.y, 0, 1, 0)
    rl_rotatef(rot.z, 0, 0, 1)
    # Worn charcoal-green cover, exposed cream pages and slightly uneven page edges.
    draw_pbr_box(Vector3(0, 0, 0), Vector3(0.68, 0.045, 0.95), Color(43, 55, 49, 255), roughness=0.88, metallic=0.02)
    draw_pbr_box(Vector3(0.008, 0.027, 0.015), Vector3(0.62, 0.018, 0.86), Color(201, 188, 153, 255), roughness=0.97, metallic=0.0)
    draw_pbr_box(Vector3(0.008, 0.038, 0.015), Vector3(0.59, 0.006, 0.82), Color(230, 219, 186, 255), roughness=0.96, metallic=0.0)
    # Faint ruling, red margin, and small blocks stand in for printed headings and handwritten notes.
    draw_pbr_box(Vector3(-0.215, 0.042, 0.015), Vector3(0.006, 0.002, 0.74), Color(163, 91, 74, 255), roughness=0.96)
    for row in range(12):
        z = -0.32 + row * 0.061
        line_w = 0.42 if row not in (0, 5, 10) else 0.32
        line_col = Color(116, 124, 117, 255) if row > 0 else Color(82, 98, 85, 255)
        draw_pbr_box(Vector3(0.035, 0.043, z), Vector3(line_w, 0.002, 0.004), line_col, roughness=0.97)
    # Folded paper corner and a narrow fabric-reinforced spine.
    draw_pbr_box(Vector3(0.272, 0.044, -0.365), Vector3(0.045, 0.004, 0.045), Color(178, 164, 132, 255), roughness=0.98)
    draw_pbr_box(Vector3(-0.316, 0.021, 0.015), Vector3(0.035, 0.022, 0.90), C_METAL_DARK, roughness=0.82, metallic=0.12)
    # Visible wire binding loops along the spine.
    for z in (-0.36, -0.25, -0.14, -0.03, 0.08, 0.19, 0.30, 0.39):
        draw_pbr_cylinder(Vector3(-0.322, 0.033, z), 0.021, 0.035, C_CHROME, roughness=0.28, metallic=0.9)
    # Worn paper tape secures the upper edge, recalling the notes in the Observation Room.
    draw_pbr_box(Vector3(0.015, 0.047, -0.385), Vector3(0.18, 0.005, 0.065), Color(184, 169, 133, 210), roughness=0.98)
    draw_pbr_box(Vector3(0.15, 0.047, 0.37), Vector3(0.08, 0.005, 0.035), Color(153, 126, 102, 230), roughness=0.98)
    rl_pop_matrix()

def draw_photograph_3d(item, time_val=0.0):
    """Draws realistic vintage polaroid photographic card with photo plate, waveform, and bold colored status stamp."""
    pdata = item.photo_data
    rl_push_matrix()
    rl_translatef(item.pos.x, item.pos.y, item.pos.z)
    rl_rotatef(item.rot.x, 1, 0, 0)
    rl_rotatef(item.rot.y, 0, 1, 0)
    rl_rotatef(item.rot.z, 0, 0, 1)

    # White photo paper body
    draw_pbr_box(Vector3(0, 0, 0), Vector3(0.44, 0.018, 0.52), WHITE, roughness=0.35, metallic=0.0)

    # Exposed photo emulsion plate
    draw_pbr_box(Vector3(0, 0.011, -0.06), Vector3(0.38, 0.005, 0.34), Color(16, 22, 28, 255), roughness=0.18, metallic=0.1)

    # Stylized waveform / neural data on photo plate
    if pdata:
        is_succ = pdata["status"] == "SUCCESSFUL"
        is_class = pdata["status"] == "CLASSIFIED"
        wave_color = C_CYAN if is_succ else (C_AMBER if is_class else C_RED_DIM)
        wave_emiss = Vector3(0.2, 0.8, 0.9) if is_succ else (Vector3(0.8, 0.4, 0.1) if is_class else Vector3(0.8, 0.1, 0.1))
        for line in range(4):
            ly = -0.16 + line * 0.07
            lw = 0.28 if line % 2 == 0 else 0.20
            draw_pbr_box(Vector3(0, 0.014, ly), Vector3(lw, 0.003, 0.012), wave_color,
                         roughness=0.2, emissive=wave_emiss)

        # Bold Stamp at bottom of polaroid
        stamp_color = C_GREEN_DIM if is_succ else (C_AMBER if is_class else C_RED_DIM)
        stamp_emiss = Vector3(0.05, 0.65, 0.15) if is_succ else (Vector3(0.65, 0.35, 0.05) if is_class else Vector3(0.65, 0.05, 0.05))
        draw_pbr_box(Vector3(0, 0.012, 0.16), Vector3(0.34, 0.005, 0.08), stamp_color,
                     roughness=0.3, emissive=stamp_emiss)

    rl_pop_matrix()

def draw_research_microscope(pos, scale=1.0):
    if not _is_3d_primitive_visible(Vector3(pos.x, pos.y + 0.62 * scale, pos.z), 1.15 * scale):
        return
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    sc = scale
    draw_pbr_box(Vector3(0, 0.05*sc, 0), Vector3(0.65*sc, 0.10*sc, 0.52*sc), C_METAL_DARK, roughness=0.45, metallic=0.6)
    draw_pbr_box(Vector3(-0.16*sc, 0.48*sc, 0), Vector3(0.14*sc, 0.76*sc, 0.16*sc), C_METAL_DARK, roughness=0.45, metallic=0.6)
    draw_pbr_cylinder(Vector3(-0.06*sc, 0.82*sc, 0), 0.16*sc, 0.28*sc, C_STEEL, roughness=0.3, metallic=0.7)
    draw_pbr_box(Vector3(0.08*sc, 0.54*sc, 0), Vector3(0.52*sc, 0.045*sc, 0.44*sc), C_METAL_DARK, roughness=0.4, metallic=0.7)
    draw_pbr_cylinder(Vector3(0.12*sc, 0.78*sc, 0), 0.16*sc, 0.09*sc, C_CHROME, roughness=0.15, metallic=0.92)
    draw_pbr_cylinder(Vector3(0.20*sc, 1.15*sc, 0.08*sc), 0.042*sc, 0.28*sc, C_CHROME, roughness=0.15, metallic=0.9)
    draw_pbr_cylinder(Vector3(0.20*sc, 1.15*sc, -0.08*sc), 0.042*sc, 0.28*sc, C_CHROME, roughness=0.15, metallic=0.9)
    # Microscope slide stage, paired retaining clips, objective lens and focus controls.
    draw_pbr_box(Vector3(0.08*sc, 0.585*sc, 0.0), Vector3(0.30*sc, 0.014*sc, 0.22*sc),
                 C_CHAMBER_GLASS, roughness=0.18, metallic=0.10)
    for side_x in (-0.16, 0.16):
        draw_pbr_box(Vector3(side_x*sc, 0.605*sc, 0.0), Vector3(0.035*sc, 0.018*sc, 0.25*sc),
                     C_STEEL, roughness=0.30, metallic=0.84)
    draw_pbr_cylinder(Vector3(0.11*sc, 0.39*sc, 0.0), 0.065*sc, 0.16*sc, C_METAL_EDGE, roughness=0.22, metallic=0.85)
    draw_pbr_sphere(Vector3(-0.34*sc, 0.47*sc, 0.0), 0.065*sc, C_METAL_EDGE, roughness=0.28, metallic=0.78)
    draw_pbr_sphere(Vector3(0.24*sc, 0.43*sc, 0.0), 0.048*sc, C_METAL_MID, roughness=0.34, metallic=0.68)
    draw_pbr_box(Vector3(0.18*sc, 0.11*sc, 0.23*sc), Vector3(0.10*sc, 0.025*sc, 0.012*sc),
                 C_CYAN, roughness=0.18, emissive=Vector3(0.0, 0.10, 0.15))
    rl_pop_matrix()

# Removed the unused hazmat-drum and fallen-barrel renderers; these props are no longer part of the Main Lab scene.


def draw_oscilloscope(pos, rot_y=0.0, broken=False, time_val=0.0):
    if not _is_3d_primitive_visible(Vector3(pos.x, pos.y + 0.32, pos.z), 0.92):
        return
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot_y, 0, 1, 0)
    draw_pbr_box(Vector3(0, 0.32, 0), Vector3(1.05, 0.64, 0.78), C_METAL_MID, roughness=0.5, metallic=0.6)
    crt_color = Color(8, 28, 16, 255) if not broken else Color(18, 8, 8, 255)
    draw_pbr_box(Vector3(-0.16, 0.36, 0.41), Vector3(0.52, 0.38, 0.025), crt_color, roughness=0.1, metallic=0.1)
    if not broken:
        for seg in range(12):
            sx = -0.38 + seg * 0.04
            sy = 0.36 + math.sin(seg * 0.9 + time_val * 8.0) * 0.075
            draw_pbr_box(Vector3(sx, sy, 0.425), Vector3(0.035, 0.012, 0.008), C_CYAN,
                         roughness=0.1, emissive=Vector3(0.035, 0.36, 0.50))
    # Front control cluster: tactile dials, calibration buttons, label rail and side vents.
    draw_pbr_box(Vector3(-0.16, 0.09, 0.419), Vector3(0.53, 0.035, 0.018), C_METAL_DARK, roughness=0.55, metallic=0.45)
    for k, col in enumerate((C_METAL_EDGE, C_STEEL, C_METAL_EDGE)):
        draw_pbr_sphere(Vector3(0.22 + k * 0.12, 0.26, 0.435), 0.036, col, roughness=0.34, metallic=0.7)
    draw_pbr_sphere(Vector3(0.32, 0.10, 0.435), 0.025, C_CYAN, roughness=0.2, emissive=Vector3(0.01, 0.08, 0.12))
    for vent_i in range(3):
        draw_pbr_box(Vector3(0.535, 0.10 + vent_i * 0.055, -0.05), Vector3(0.012, 0.022, 0.38),
                     C_METAL_DARK, roughness=0.82, metallic=0.25)
    rl_pop_matrix()

def draw_stasis_chamber(pos, broken=False, time_val=0.0):
    # Test the whole chamber in world space; its internal pieces use local coordinates.
    if not _is_3d_primitive_visible(Vector3(pos.x, pos.y + 2.10, pos.z), 3.20):
        return
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    draw_pbr_cylinder(Vector3(0, 0.20, 0), 1.55, 0.40, C_METAL_DARK, roughness=0.4, metallic=0.7)
    draw_pbr_cylinder(Vector3(0, 3.85, 0), 1.55, 0.35, C_METAL_DARK, roughness=0.4, metallic=0.7)
    draw_pbr_cylinder(Vector3(0, 2.05, 0), 1.25, 3.25, C_CHAMBER_GLASS, roughness=0.08, metallic=0.05)
    pulse = 0.5 + 0.5 * math.sin(time_val * 2.5)
    draw_pbr_cylinder(Vector3(0, 1.85, 0), 1.15, 2.85, C_BEAKER_FLUID, roughness=0.15,
                      emissive=Vector3(0.035, 0.30 * pulse, 0.11 * pulse))
    beacon_flash = 0.5 + 0.5 * math.sin(time_val * 7.0)
    draw_pbr_cylinder(Vector3(0, 4.15, 0), 0.18, 0.25, C_AMBER, roughness=0.2,
                      emissive=Vector3(0.42 * beacon_flash, 0.24 * beacon_flash, 0.025 * beacon_flash))
    # Reinforced lower/upper collars and four restrained support struts.
    draw_pbr_torus(Vector3(0, 0.42, 0), 1.34, 0.045, C_STEEL, roughness=0.35, metallic=0.78)
    draw_pbr_torus(Vector3(0, 3.70, 0), 1.34, 0.045, C_STEEL, roughness=0.35, metallic=0.78)
    for rx, rz in ((1.28, 0.0), (-1.28, 0.0), (0.0, 1.28), (0.0, -1.28)):
        draw_pbr_box(Vector3(rx, 2.06, rz), Vector3(0.075, 3.02, 0.075), C_METAL_EDGE,
                     roughness=0.42, metallic=0.76)
    rl_pop_matrix()

def draw_server_cabinet(pos, height=3.8, damaged=False, time_val=0.0):
    width, depth = 1.25, 0.85
    draw_pbr_box(Vector3(pos.x, pos.y + height/2.0, pos.z), Vector3(width, height, depth),
                 C_METAL_DARK, roughness=0.5, metallic=0.6)
    bay_ys = [0.55, 1.15, 1.75, 2.35, 2.95, 3.45]
    for idx, y in enumerate(bay_ys):
        if y < height - 0.15:
            draw_pbr_box(Vector3(pos.x, pos.y + y, pos.z - depth/2.0 - 0.045),
                         Vector3(0.92, 0.46, 0.045), C_METAL_MID, roughness=0.35, metallic=0.7)
            for j in range(6):
                blink = math.sin(time_val * (12.0 + j * 3.5) + idx * 1.5) > 0.0
                led_col = C_CYAN if (j % 2 == 0 and blink) else (C_AMBER if blink else C_METAL_DARK)
                emiss = Vector3(0.2, 0.9, 1.0) if (j % 2 == 0 and blink) else (Vector3(0.9, 0.5, 0.1) if blink else Vector3(0,0,0))
                draw_pbr_box(Vector3(pos.x - 0.12 + j*0.065, pos.y + y + 0.10, pos.z - depth/2.0 - 0.075),
                             Vector3(0.022, 0.045, 0.015), led_col, roughness=0.3, emissive=emiss)
    front_z = pos.z - depth/2.0 - 0.085
    # Tall edge rails frame the rack bays like the Observation Room's modular equipment.
    for rail_x in (-0.53, 0.53):
        draw_pbr_box(Vector3(pos.x + rail_x, pos.y + height/2.0, front_z),
                     Vector3(0.055, height - 0.20, 0.028), C_METAL_EDGE, roughness=0.38, metallic=0.82)
    draw_pbr_box(Vector3(pos.x, pos.y + height - 0.20, front_z - 0.008),
                 Vector3(0.40, 0.105, 0.018), C_PAPER2, roughness=0.86, metallic=0.05)
    for slot_i in range(3):
        draw_pbr_box(Vector3(pos.x, pos.y + 0.24 + slot_i * 0.07, front_z - 0.010),
                     Vector3(0.48, 0.018, 0.012), C_METAL_DARK, roughness=0.78, metallic=0.22)

def draw_lab_table(pos, size, damaged=False):
    floor_y = pos.y
    top_y = floor_y + size.y
    top_thickness = min(0.18, size.y * 0.14)
    draw_pbr_box(Vector3(pos.x, top_y - top_thickness/2.0, pos.z),
                 Vector3(size.x, top_thickness, size.z), C_STEEL, roughness=0.22, metallic=0.88)
    leg_x = max(0.0, size.x/2.0 - 0.24)
    leg_z = max(0.0, size.z/2.0 - 0.24)
    leg_h = max(0.20, size.y - top_thickness - 0.06)
    leg_center_y = floor_y + leg_h/2.0
    for x in (-leg_x, leg_x):
        for z in (-leg_z, leg_z):
            draw_pbr_box(Vector3(pos.x+x, leg_center_y, pos.z+z),
                         Vector3(0.16, leg_h, 0.16), C_METAL_DARK, roughness=0.4, metallic=0.7)
    # Low cross-bracing and feet make the existing desks feel engineered rather than blocky.
    brace_y = floor_y + leg_h * 0.48
    for z in (-leg_z, leg_z):
        draw_pbr_box(Vector3(pos.x, brace_y, pos.z + z), Vector3(max(0.25, size.x - 0.34), 0.075, 0.075),
                     C_METAL_MID, roughness=0.56, metallic=0.62)

def draw_main_terminal_desk_details():
    """Visual-only detail pass for the central Main Lab workstation; no gameplay colliders."""
    # The bench top is the existing central table at (-1.2, 0, 1.8), with its surface at y=1.45.
    # A dark front apron, separate drawer faces, and restrained steel pulls add depth without
    # changing the table's footprint or its existing collision box.
    draw_pbr_box(Vector3(-1.2, 1.205, 0.245), Vector3(5.65, 0.31, 0.20),
                 C_METAL_DARK, roughness=0.58, metallic=0.72)
    for drawer_x in (-3.05, -1.20, 0.55):
        for drawer_y, drawer_w in ((1.235, 1.47), (0.985, 1.47)):
            draw_pbr_box(Vector3(drawer_x, drawer_y, 0.125), Vector3(drawer_w, 0.205, 0.055),
                         C_METAL_MID, roughness=0.47, metallic=0.70)
            draw_pbr_box(Vector3(drawer_x, drawer_y + 0.018, 0.091), Vector3(0.24, 0.024, 0.018),
                         C_METAL_EDGE, roughness=0.26, metallic=0.90)
            draw_pbr_box(Vector3(drawer_x, drawer_y - 0.025, 0.090), Vector3(0.13, 0.008, 0.012),
                         C_METAL_DARK, roughness=0.60, metallic=0.35)
    # Recessed utility rail and cable pass-through along the back edge of the workbench.
    draw_pbr_box(Vector3(-1.20, 1.375, 3.16), Vector3(5.35, 0.055, 0.12),
                 C_METAL_DARK, roughness=0.58, metallic=0.74)
    draw_pbr_cylinder(Vector3(-0.43, 1.468, 2.98), 0.075, 0.018, C_METAL_EDGE,
                      roughness=0.40, metallic=0.78)
    draw_pbr_cylinder(Vector3(-0.43, 1.479, 2.98), 0.043, 0.012, C_RUBBER,
                      roughness=0.82, metallic=0.12)

    # Compact keyboard, individual key rows, and a small wired mouse make the computer feel usable.
    kb_x, kb_z, kb_y = -2.0, 1.67, 1.478
    draw_pbr_box(Vector3(kb_x, kb_y, kb_z), Vector3(1.30, 0.055, 0.43), C_METAL_DARK,
                 roughness=0.46, metallic=0.55)
    draw_pbr_box(Vector3(kb_x, kb_y + 0.030, kb_z), Vector3(1.20, 0.012, 0.345),
                 Color(12, 18, 23, 255), roughness=0.65, metallic=0.22)
    for row_idx in range(3):
        z = kb_z - 0.105 + row_idx * 0.095
        for col_idx in range(10):
            x = kb_x - 0.51 + col_idx * 0.113
            key_w = 0.074 if row_idx != 2 or col_idx not in (4, 5, 6) else 0.10
            draw_pbr_box(Vector3(x, kb_y + 0.042, z), Vector3(key_w, 0.012, 0.052),
                         C_METAL_EDGE if (row_idx == 0 and col_idx == 0) else C_METAL_MID,
                         roughness=0.56, metallic=0.46)
    draw_pbr_box(Vector3(-0.98, 1.493, 1.68), Vector3(0.19, 0.065, 0.26),
                 C_METAL_MID, roughness=0.42, metallic=0.50)
    draw_pbr_box(Vector3(-0.98, 1.529, 1.66), Vector3(0.024, 0.010, 0.09),
                 C_METAL_EDGE, roughness=0.25, metallic=0.86)
    # Small status indicators on the bench edge; these are decorative, not interactable.
    for idx, led_col in enumerate((C_CYAN, C_AMBER, C_RED_DIM)):
        draw_pbr_sphere(Vector3(0.80 + idx * 0.12, 1.485, 0.72), 0.025, led_col,
                        roughness=0.20, metallic=0.10,
                        emissive=(Vector3(0.01, 0.20, 0.27) if idx == 0 else
                                  Vector3(0.18, 0.055, 0.005) if idx == 1 else
                                  Vector3(0.16, 0.012, 0.008)))

    # Central processing tower added for Phase 5: a substantial industrial unit with
    # a recessed module socket, cooling vents, front service panel and status lamps.
    _cpu_x, _cpu_y, _cpu_z = 0.58, 1.985, 2.55
    draw_pbr_box(Vector3(_cpu_x, _cpu_y, _cpu_z), Vector3(0.78, 1.00, 0.78),
                 C_METAL_DARK, roughness=0.42, metallic=0.84)
    draw_pbr_box(Vector3(_cpu_x, _cpu_y, _cpu_z - 0.402), Vector3(0.68, 0.91, 0.035),
                 C_METAL_MID, roughness=0.34, metallic=0.78)
    draw_pbr_box(Vector3(_cpu_x, 2.32, _cpu_z - 0.425), Vector3(0.44, 0.16, 0.018),
                 Color(7, 13, 17, 255), roughness=0.25, metallic=0.52)
