def draw_hanging_fluorescent(pos, damaged=False, flicker_val=1.0, time_val=0.0, cam=None, power_restored=False):
    # Keep the fitting level. The older sway tilted otherwise-straight fluorescent tubes
    # during every damaged-light cycle, which looked like slanted/vertical fixtures.
    swing = 0.0
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)

    # The chains/supports and body remain in their original positions.
    draw_pbr_cylinder(Vector3(-0.95, 0.65, 0), 0.018, 1.30, C_STEEL, roughness=0.3, metallic=0.8)
    draw_pbr_cylinder(Vector3(0.95, 0.65, 0), 0.018, 1.30, C_STEEL, roughness=0.3, metallic=0.8)
    draw_pbr_box(Vector3(0, 0, 0), Vector3(2.35, 0.12, 0.52), C_STEEL, roughness=0.25, metallic=0.85)

    if power_restored:
        f_glow = 2.4
    else:
        f_glow = flicker_val if not damaged else (flicker_val * 0.15)

    # Cylinder helper uses the Y axis for its length. Rotate each tube 90 degrees so
    # both fluorescent tubes are straight and horizontal along the fixture's X axis.
    for zo in (-0.12, 0.12):
        rl_push_matrix()
        rl_translatef(0.0, -0.08, zo)
        rl_rotatef(90.0, 0.0, 0.0, 1.0)
        draw_pbr_cylinder(Vector3(0.0, 0.0, 0.0), 0.038, 2.15, WHITE,
                          roughness=0.15, metallic=0.0,
                          emissive=Vector3(1.2 * f_glow, 1.3 * f_glow, 1.4 * f_glow))
        rl_pop_matrix()

    # Dangling severed wire with spark burst (the wire is intentionally vertical).
    if damaged and not power_restored:
        draw_pbr_cylinder(Vector3(-0.95, -0.40, 0), 0.012, 0.65, C_RUBBER, roughness=0.9)
        if random.random() < 0.06:
            draw_pbr_sphere(Vector3(-0.95, -0.72, 0), 0.08, C_CYAN, roughness=0.1,
                            emissive=Vector3(3.0, 3.5, 4.0))
            if cam:
                spark_pos = Vector3(pos.x - 0.95, pos.y - 0.72, pos.z)
                spatial_audio.play_spatial("spark_burst", spark_pos, cam, base_volume=0.55, pitch_var=0.15)
    rl_pop_matrix()

