# STORY SPECIFIC PROPS: SWITCH, GENERATOR, ARCHIVE CORE & DOORS
# ============================================================
def _primary_switch_flicker_level(time_val):
    """Irregular fluorescent output during the five-second primary-breaker failure."""
    t = float(time_val)
    level = 0.64 + 0.30 * math.sin(t * 15.7) + 0.22 * math.sin(t * 31.4 + 0.85)
    # Brief, irregular near-black dips followed by occasional harsh electrical flashes.
    if math.sin(t * 8.1 + 0.65) > 0.76:
        level *= 0.055
    if math.sin(t * 21.6 + 1.7) > 0.982:
        level = 1.55
    return max(0.025, min(1.60, level))


def spawn_primary_switch_sparks(origin, count=22):
    """Emit a short, lightweight shower of bright particles from the physical lever."""
    for _ in range(int(count)):
        life = random.uniform(0.22, 0.58)
        primary_switch_sparks.append({
            "pos": Vector3(origin.x + random.uniform(0.00, 0.055),
                           origin.y + random.uniform(-0.04, 0.10),
                           origin.z + random.uniform(-0.045, 0.045)),
            "vel": Vector3(random.uniform(0.25, 1.55), random.uniform(0.35, 1.75),
                           random.uniform(-1.35, 1.35)),
            "life": life,
            "max_life": life,
            "size": random.uniform(0.012, 0.026),
            "tone": random.uniform(0.72, 1.0),
        })


def update_primary_switch_sparks(dt):
    """Advance lever spark particles without touching the shared room particle system."""
    alive = []
    for particle in primary_switch_sparks:
        particle["life"] -= dt
        if particle["life"] <= 0.0:
            continue
        pos = particle["pos"]
        vel = particle["vel"]
        vel_y = vel.y - 4.2 * dt
        particle["pos"] = Vector3(pos.x + vel.x * dt,
                                  pos.y + (vel.y + vel_y) * 0.5 * dt,
                                  pos.z + vel.z * dt)
        particle["vel"] = Vector3(vel.x * max(0.0, 1.0 - 0.65 * dt), vel_y,
                                  vel.z * max(0.0, 1.0 - 0.65 * dt))
        alive.append(particle)
    primary_switch_sparks[:] = alive


def draw_primary_switch_sparks():
    """Render the brief, warm-white/amber electrical spark burst from the switchboard."""
    for particle in primary_switch_sparks:
        fade = max(0.0, min(1.0, particle["life"] / max(0.001, particle["max_life"])))
        tone = particle["tone"]
        draw_pbr_sphere(particle["pos"], particle["size"],
                        Color(255, int(145 + 80 * tone), int(48 + 42 * tone), 255),
                        roughness=0.12, metallic=0.02,
                        emissive=Vector3(1.55 * fade, 0.66 * fade, 0.10 * fade))


