# ELECTRICITY ROOM v38 // WALL & FLOOR ENVIRONMENT DRESSING
# ============================================================
def _draw_electricity_room_wall_stencil(word, center, width, height, side, color):
    """Draw a compact 5x3 stencil word directly onto a wall banner.
    Static geometry only: each letter is a few thin boxes, so it remains cheap.
    """
    patterns = {
        "A": ("111","101","111","101","101"),
        "C": ("111","100","100","100","111"),
        "D": ("110","101","101","101","110"),
        "E": ("111","100","110","100","111"),
        "G": ("111","100","101","101","111"),
        "H": ("101","101","111","101","101"),
        "I": ("111","010","010","010","111"),
        "N": ("101","111","111","101","101"),
        "O": ("111","101","101","101","111"),
        "R": ("110","101","110","101","101"),
        "T": ("111","010","010","010","010"),
        "U": ("101","101","101","101","111"),
        "V": ("101","101","101","101","010"),
    }
    word = ''.join(ch for ch in word.upper() if ch in patterns)
    if not word:
        return
    cols_total = len(word) * 3 + (len(word)-1)
    cell_w = width / max(cols_total, 1)
    cell_h = height / 5.0
    gap = cell_w
    start_x = center.x - width / 2.0
    start_y = center.y - height / 2.0
    for li, ch in enumerate(word):
        pat = patterns[ch]
        base_col = li * 4
        for row in range(5):
            for col in range(3):
                if pat[row][col] != "1":
                    continue
                px = start_x + (base_col + col + .5) * cell_w
                py = start_y + (4-row + .5) * cell_h
                if side == "north":
                    draw_pbr_box(Vector3(px, py, center.z),
                                 Vector3(cell_w*.82, cell_h*.82, .012), color,
                                 roughness=.88, metallic=.06)
                elif side == "south":
                    draw_pbr_box(Vector3(px, py, center.z),
                                 Vector3(cell_w*.82, cell_h*.82, .012), color,
                                 roughness=.88, metallic=.06)



def draw_electricity_room_source_wall_panels():
    """Modular cool-grey wall construction and restrained hazard bands for the electrical wing."""
    joint = C_WALL_TRIM
    hazard = Color(164, 126, 35, 255)  # muted yellow used by the Observation/Main Lab palette
    # Vertical recessed joints divide the broad north and south wall slabs into
    # different-width industrial panels rather than one uninterrupted concrete face.
    for x in (15.1, 18.9, 23.0, 26.8, 30.4, 34.2, 37.0):
        draw_pbr_box(Vector3(x, 3.5, -11.985), Vector3(0.032, 6.55, 0.035), joint,
                     roughness=0.90, metallic=0.02)
        draw_pbr_box(Vector3(x, 3.5, 11.985), Vector3(0.032, 6.55, 0.035), joint,
                     roughness=0.90, metallic=0.02)
    # Subtle horizontal panel joints; short sections avoid control screens and wall-mounted panels.
    for y in (1.42, 5.28):
        for x1, x2 in ((13.0, 19.1), (22.7, 24.0), (26.9, 30.3), (33.5, 37.9)):
            cx = (x1 + x2) * 0.5
            width = x2 - x1
            draw_pbr_box(Vector3(cx, y, -11.985), Vector3(width, 0.026, 0.035), joint,
                         roughness=0.92, metallic=0.02)
            draw_pbr_box(Vector3(cx, y, 11.985), Vector3(width, 0.026, 0.035), joint,
                         roughness=0.92, metallic=0.02)
    # Segmented yellow safety bands sit above the access panels, not across them.
    for x1, x2 in ((13.5, 18.7), (23.0, 24.0), (27.1, 30.2), (33.6, 37.7)):
        cx = (x1 + x2) * 0.5
        width = x2 - x1
        for z in (-11.985, 11.985):
            draw_pbr_box(Vector3(cx, 3.80, z), Vector3(width, 0.105, 0.028), hazard,
                         roughness=0.78, metallic=0.04)
            draw_pbr_box(Vector3(cx, 3.725, z), Vector3(width, 0.025, 0.028), joint,
                         roughness=0.92, metallic=0.02)
            draw_pbr_box(Vector3(cx, 3.875, z), Vector3(width, 0.025, 0.028), joint,
                         roughness=0.92, metallic=0.02)
    # Matching joints on the far east wall, leaving the East Control Panel face readable.
    for z in (-9.0, -5.0, -0.7, 4.5, 8.5):
        draw_pbr_box(Vector3(37.985, 3.5, z), Vector3(0.035, 6.55, 0.032), joint,
                     roughness=0.90, metallic=0.02)
    for y in (1.42, 5.28):
        draw_pbr_box(Vector3(37.985, y, 0.0), Vector3(0.035, 0.026, 25.0), joint,
                     roughness=0.92, metallic=0.02)
    # Muted hazard stripe segments on the east wall; gap around its control terminal.
    for z1, z2 in ((-11.2, -5.0), (-4.5, -0.6), (4.6, 11.2)):
        cz = (z1 + z2) * 0.5
        length = z2 - z1
        for x in (37.985,):
            draw_pbr_box(Vector3(x, 3.80, cz), Vector3(0.028, 0.105, length), hazard,
                         roughness=0.78, metallic=0.04)
            draw_pbr_box(Vector3(x, 3.725, cz), Vector3(0.028, 0.025, length), joint,
                         roughness=0.92, metallic=0.02)
            draw_pbr_box(Vector3(x, 3.875, cz), Vector3(0.028, 0.025, length), joint,
                         roughness=0.92, metallic=0.02)



def _draw_electricity_room_floor_detail_source():
    """Small grounded details to break up empty floor without clutter."""
    # Service cable loops / conduit offcuts.
    cable_color = Color(38, 42, 44, 255)
    for center, radius, rot in (
        (Vector3(23.5, 0.075, -6.9), 0.42, 18),
        (Vector3(34.8, 0.075, 5.9), 0.34, -24),
    ):
        draw_pbr_torus(center, radius, 0.045, cable_color, roughness=0.72, metallic=0.35)

    # Fallen conduit pieces.
    for p, s, r in (
        (Vector3(19.3, 0.10, 6.9), Vector3(1.45, 0.09, 0.09), 12),
        (Vector3(36.3, 0.10, -6.8), Vector3(1.10, 0.08, 0.08), -20),
    ):
        draw_pbr_cylinder(p, 0.07, s.x, C_STEEL, roughness=0.58, metallic=0.78)

    # Small maintenance debris clusters.
    for p in (
        Vector3(21.7, 0.045, 6.65),
        Vector3(31.8, 0.045, -6.55),
        Vector3(37.0, 0.045, 2.1),
    ):
        draw_pbr_box(p, Vector3(0.42, 0.06, 0.24), C_METAL_DARK,
                     roughness=0.84, metallic=0.28)
        draw_pbr_box(Vector3(p.x + 0.16, p.y + 0.04, p.z - 0.11),
                     Vector3(0.08, 0.04, 0.16), C_RUST2,
                     roughness=0.9, metallic=0.18)

    # Drain/service plate.
    draw_pbr_box(Vector3(27.2, 0.055, 6.65), Vector3(1.15, 0.08, 0.72),
                 C_METAL_DARK, roughness=0.88, metallic=0.62)
    for x in (-0.32, -0.11, 0.11, 0.32):
        draw_pbr_box(Vector3(27.2 + x, 0.105, 6.65),
                     Vector3(0.055, 0.025, 0.48), C_METAL_MID,
                     roughness=0.92, metallic=0.55)

    # Restrained floor stains / grime patches.
    for p, s in (
        (Vector3(24.8, 0.026, -6.15), Vector3(1.45, 0.012, 0.55)),
        (Vector3(35.4, 0.026, 6.45), Vector3(1.10, 0.012, 0.42)),
        (Vector3(20.2, 0.026, 1.8), Vector3(0.82, 0.012, 0.36)),
    ):
        draw_pbr_box(p, s, Color(48, 43, 37, 255), roughness=0.98, metallic=0.02)



def draw_electricity_room_static_shelving(pos, axis="x", variant=0, width=4.2):
    def point(u, y, v):
        return Vector3(pos.x + (u if axis == "x" else v), y,
                       pos.z + (v if axis == "x" else u))
    rust_colors = (C_RUST2, C_RUST, C_METAL_DARK, C_STEEL)
    for u in (-width/2 + 0.12, width/2 - 0.12):
        for v in (-0.34, 0.34):
            draw_pbr_box(point(u, 1.65, v), Vector3(0.10 if axis == "x" else 0.68, 3.3, 0.68 if axis == "x" else 0.10),
                         C_RUST2, roughness=0.82, metallic=0.55)
    for level, y in enumerate((0.35, 1.25, 2.15, 3.05)):
        dims = Vector3(width, 0.13, 0.82) if axis == "x" else Vector3(0.82, 0.13, width)
        draw_pbr_box(point(0, y, 0), dims, rust_colors[(level + variant) % len(rust_colors)],
                     roughness=0.8, metallic=0.55)
        for side in (-1, 1):
            draw_pbr_box(point(side * (width/2-0.16), y-0.12, 0),
                         Vector3(0.13, 0.08, 0.9) if axis == "x" else Vector3(0.9, 0.08, 0.13),
                         C_WARNING if level == 2 and side == 1 else C_RUST, roughness=0.85)

    for i, (u, y, v) in enumerate(((-1.15, .58, -.06), (.55, 1.48, .08), (-.65, 2.38, -.08))):
        dims = Vector3(.72, .44, .54) if i != 1 else Vector3(.92, .62, .58)
        draw_pbr_box(point(u, y, v), dims, (C_METAL_DARK, C_RUST2, C_STEEL)[(variant+i)%3],
                     roughness=.78, metallic=.45)
        draw_pbr_box(point(u, y+.07, v-.29), Vector3(.42, .035, .025), C_WARNING,
                     roughness=.6, metallic=.3)
    for u, y, v, color in ((1.05, 1.48, 0.05, C_BRASS), (1.35, 2.38, .10, C_RUST)):
        draw_pbr_torus(point(u, y, v), .25, .055, color, roughness=.72, metallic=.55)
    draw_pbr_box(point(-1.35, .48, .46), Vector3(.48, .08, .30), C_METAL_MID, roughness=.9, metallic=.4)



def draw_electricity_room_static_storage_cabinet(pos, time_val=0.0):
    """Tall two-door service cabinet beside the breaker panel; right door stands open."""
    cx, cz = pos.x, pos.z
    width, depth, height = 2.58, 1.08, 3.30
    center_y = height / 2.0
    front_z = cz - depth/2.0 - 0.025  # faces into the room, away from the south wall
    back_z = cz + depth/2.0
    dark_rust = Color(82, 55, 39, 255)

    # Heavy feet and lower plinth, with rubber isolation pads.
    for xoff in (-1.12, -0.36, 0.36, 1.12):
        draw_pbr_box(Vector3(cx+xoff, 0.10, cz), Vector3(0.30, 0.18, 0.34), C_METAL_DARK,
                     roughness=0.58, metallic=0.78)
        draw_pbr_box(Vector3(cx+xoff, 0.035, cz), Vector3(0.34, 0.07, 0.38), C_RUBBER,
                     roughness=0.94, metallic=0.08)
    draw_pbr_box(Vector3(cx, 0.23, cz), Vector3(width, 0.18, depth), C_STEEL,
                 roughness=0.42, metallic=0.88)
    draw_pbr_box(Vector3(cx, 0.34, cz), Vector3(width+0.05, 0.08, depth+0.05), C_METAL_DARK,
                 roughness=0.64, metallic=0.72)

    # Main case, rear shell and two deep side walls. Front remains an open cavity.
    draw_pbr_box(Vector3(cx, center_y, back_z-0.055), Vector3(width-0.10, height-0.20, 0.11), C_METAL_DARK,
                 roughness=0.63, metallic=0.76)
    for side in (-1, 1):
        sx = cx + side*(width/2.0 - 0.055)
        draw_pbr_box(Vector3(sx, center_y, cz), Vector3(0.11, height-0.20, depth), C_METAL_MID,
                     roughness=0.60, metallic=0.78)
        # Side stiffening ribs and small screw heads on the exposed cabinet flank.
        for zoff in (-0.32, 0.0, 0.32):
            draw_pbr_box(Vector3(sx + side*0.065, 1.68, cz+zoff), Vector3(0.045, 2.55, 0.065), C_METAL_DARK,
                         roughness=0.68, metallic=0.72)
        for yy in (0.55, 1.05, 1.55, 2.05, 2.55, 3.05):
            draw_pbr_sphere(Vector3(sx + side*0.075, yy, cz-0.34), 0.025, C_CHROME,
                            roughness=0.19, metallic=0.95)
            draw_pbr_sphere(Vector3(sx + side*0.075, yy, cz+0.34), 0.025, C_CHROME,
                            roughness=0.19, metallic=0.95)

    draw_pbr_box(Vector3(cx, height-0.08, cz), Vector3(width+0.08, 0.15, depth+0.10), C_STEEL,
                 roughness=0.40, metallic=0.88)
    draw_pbr_box(Vector3(cx, height-0.17, front_z-0.005), Vector3(width-0.03, 0.10, 0.10), C_METAL_EDGE,
                 roughness=0.36, metallic=0.9)
    # Internal back lining, rails, shelves, lip edges and brackets.
    draw_pbr_box(Vector3(cx, 1.70, back_z-0.125), Vector3(width-0.35, 2.75, 0.035), C_METAL_MID,
                 roughness=0.80, metallic=0.55)
    for level, yy in enumerate((0.62, 1.31, 2.04, 2.72)):
        draw_pbr_box(Vector3(cx, yy, cz), Vector3(width-0.28, 0.075, depth-0.22),
                     (C_METAL_DARK, C_STEEL, C_METAL_MID, C_METAL_DARK)[level],
                     roughness=0.62, metallic=0.78)
        draw_pbr_box(Vector3(cx, yy+0.045, front_z+0.12), Vector3(width-0.42, 0.055, 0.045), C_METAL_EDGE,
                     roughness=0.34, metallic=0.90)
        for xoff in (-0.95, -0.32, 0.32, 0.95):
            draw_pbr_box(Vector3(cx+xoff, yy-0.06, cz-0.23), Vector3(0.08, 0.12, 0.08), C_METAL_DARK,
                         roughness=0.52, metallic=0.80)

    # Interior pipework, cable hanger and backboard terminals.
    for xoff, col in ((-0.88, C_WARNING), (-0.70, C_CYAN), (0.80, C_RED_DIM)):
        draw_pbr_cylinder(Vector3(cx+xoff, 1.78, cz+0.30), 0.035, 2.40, C_RUBBER,
                          roughness=0.86, metallic=0.10)
        for yy in (0.75, 1.55, 2.35):
            draw_pbr_box(Vector3(cx+xoff, yy, cz+0.285), Vector3(0.11, 0.06, 0.07), C_METAL_EDGE,
                         roughness=0.38, metallic=0.88)
    # Upper left stock: stacked old parts cases, ceramic sleeves and a marked service pouch.
    draw_pbr_box(Vector3(cx-0.78, 2.88, cz+0.16), Vector3(0.54, 0.25, 0.52), C_RUST2,
                 roughness=0.88, metallic=0.42)
    draw_pbr_box(Vector3(cx-0.78, 3.02, cz+0.16), Vector3(0.48, 0.04, 0.45), C_METAL_DARK,
                 roughness=0.82, metallic=0.52)
    draw_pbr_box(Vector3(cx-0.78, 2.91, cz-0.11), Vector3(0.32, 0.07, 0.025), C_WARNING,
                 roughness=0.72, metallic=0.22)
    for n, col in enumerate((C_PAPER, C_METAL_DARK, C_STEEL)):
        xx = cx-0.30+n*0.18
        draw_pbr_cylinder(Vector3(xx, 2.88, cz+0.10), 0.065, 0.23, col,
                          roughness=0.45, metallic=0.58)
        draw_pbr_cylinder(Vector3(xx, 3.00, cz+0.10), 0.072, 0.045, C_CHROME,
                          roughness=0.22, metallic=0.94)
    # Open compartment miscellany on the two visible shelves: spare relay, ceramic collars,
    # small terminal blocks, coiled lead and an old handheld meter housing.
    draw_pbr_box(Vector3(cx+0.63, 1.64, cz+0.15), Vector3(0.38, 0.25, 0.34), C_METAL_DARK,
                 roughness=0.68, metallic=0.66)
    draw_pbr_box(Vector3(cx+0.63, 1.78, cz-0.03), Vector3(0.28, 0.06, 0.035), C_WARNING,
                 roughness=0.63, metallic=0.24)
    for n, col in enumerate((C_BRASS, C_CHROME, C_RUST2)):
        draw_pbr_cylinder(Vector3(cx+0.98+n*0.10, 1.64, cz+0.05), 0.045, 0.18, col,
                          roughness=0.36, metallic=0.84)
    draw_pbr_torus(Vector3(cx+0.78, 2.25, cz+0.10), 0.22, 0.035, C_RUBBER,
                   roughness=0.80, metallic=0.12)
    draw_pbr_torus(Vector3(cx+0.78, 2.25, cz+0.10), 0.14, 0.027, C_COPPER if 'C_COPPER' in globals() else C_RUST2,
                   roughness=0.36, metallic=0.80)
    draw_pbr_box(Vector3(cx+0.34, 2.38, cz+0.12), Vector3(0.36, 0.15, 0.28), C_METAL_DARK,
                 roughness=0.55, metallic=0.72)
    draw_pbr_box(Vector3(cx+0.34, 2.47, cz-0.03), Vector3(0.22, 0.025, 0.10), Color(36, 54, 50, 255),
                 roughness=0.26, metallic=0.32, emissive=Vector3(0.02, 0.15, 0.12))
    for n in range(5):
        draw_pbr_box(Vector3(cx+0.38+n*0.11, 0.78, cz+0.10), Vector3(0.055, 0.17, 0.15),
                     (C_WARNING, C_CYAN, C_GREEN_DIM, C_RED_DIM, C_STEEL)[n],
                     roughness=0.48, metallic=0.72)
    for n in range(3):
        draw_pbr_torus(Vector3(cx+0.93, 0.80, cz-0.03+n*0.12), 0.095, 0.024,
                       (C_RUST2, C_BRASS, C_STEEL)[n], roughness=0.50, metallic=0.76)

    # Static stock details remain in the open half while the three key loose items
    # below are still actual physics/interaction objects at matching shelf positions.
    # A battery service cradle and segmented charging leads on the bottom compartment.
    draw_pbr_box(Vector3(cx+0.60, 0.46, cz+0.19), Vector3(0.72, 0.18, 0.48), C_METAL_DARK,
                 roughness=0.58, metallic=0.78)
    for n, col in enumerate((C_CYAN, C_WARNING, C_GREEN_DIM, C_RED_DIM)):
        draw_pbr_box(Vector3(cx+0.35+n*0.16, 0.57, cz-0.04), Vector3(0.09, 0.13, 0.12), col,
                     roughness=0.45, metallic=0.55,
                     emissive=Vector3(0.02, 0.08, 0.08) if n == 0 else None)

    # Front frame rails and wear strips.
    for xoff in (-width/2.0+0.045, 0.0, width/2.0-0.045):
        draw_pbr_box(Vector3(cx+xoff, 1.72, front_z-0.025), Vector3(0.09, height-0.42, 0.10), C_STEEL,
                     roughness=0.38, metallic=0.9)
    draw_pbr_box(Vector3(cx, 0.48, front_z-0.035), Vector3(width-0.12, 0.12, 0.10), C_METAL_DARK,
                 roughness=0.62, metallic=0.76)

    # LEFT DOOR: closed, heavily reinforced, locked latch, chipped warning strip.
    door_w = width/2.0 - 0.075
    door_h = 2.82
    door_y = 1.76
    closed_x = cx - width/4.0
    door_z = front_z - 0.078
    draw_pbr_box(Vector3(closed_x, door_y, door_z), Vector3(door_w, door_h, 0.075), C_METAL_MID,
                 roughness=0.50, metallic=0.84)
    draw_pbr_box(Vector3(closed_x, door_y, door_z-0.043), Vector3(door_w-0.15, door_h-0.16, 0.025), C_METAL_DARK,
                 roughness=0.58, metallic=0.78)
    # Raised inset ribs and a small inspection window.
    for xoff in (-0.43, 0.43):
        draw_pbr_box(Vector3(closed_x+xoff, door_y, door_z-0.061), Vector3(0.055, 2.40, 0.022), C_STEEL,
                     roughness=0.42, metallic=0.88)
    draw_pbr_box(Vector3(closed_x, 2.62, door_z-0.062), Vector3(0.68, 0.28, 0.025), C_METAL_EDGE,
                 roughness=0.32, metallic=0.88)
    draw_pbr_box(Vector3(closed_x, 2.62, door_z-0.079), Vector3(0.52, 0.15, 0.018), Color(35, 48, 47, 255),
                 roughness=0.24, metallic=0.34,
                 emissive=Vector3(0.01, 0.10, 0.10) if int(time_val*2.5)%2 == 0 else Vector3(0.0,0.015,0.02))
    # Door ID plate with deliberately blocky micro-lines, so it reads as stamped service text.
    draw_pbr_box(Vector3(closed_x, 2.18, door_z-0.079), Vector3(0.58, 0.18, 0.022), C_WARNING,
                 roughness=0.64, metallic=0.25)
    draw_pbr_box(Vector3(closed_x-0.08, 2.18, door_z-0.094), Vector3(0.30, 0.025, 0.012), C_METAL_DARK,
                 roughness=0.82, metallic=0.12)
    draw_pbr_box(Vector3(closed_x+0.13, 2.18, door_z-0.094), Vector3(0.09, 0.025, 0.012), C_METAL_DARK,
                 roughness=0.82, metallic=0.12)
    # Handle/lock is on the door's right edge, away from the outer frame.
    handle_x = cx - 0.10
    draw_pbr_box(Vector3(handle_x, 1.63, door_z-0.095), Vector3(0.075, 0.30, 0.035), C_CHROME,
                 roughness=0.20, metallic=0.95)
    draw_pbr_cylinder(Vector3(handle_x-0.02, 1.83, door_z-0.11), 0.06, 0.045, C_METAL_DARK,
                      roughness=0.35, metallic=0.85)
    draw_pbr_sphere(Vector3(handle_x, 1.83, door_z-0.145), 0.034, C_WARNING,
                    roughness=0.20, metallic=0.72)
    for yy in (0.48, 1.42, 2.50, 3.02):
        draw_pbr_box(Vector3(cx-width/2.0+0.075, yy, door_z-0.02), Vector3(0.12, 0.07, 0.11), C_METAL_DARK,
                     roughness=0.62, metallic=0.78)

    # RIGHT DOOR: fixed open angle. The interior face gets braces, a document pocket,
    # vent cuts and exposed hinges. It is only dressing; it does not obstruct the panel.
    hinge_x = cx + width/2.0 - 0.065
    rl_push_matrix()
    rl_translatef(hinge_x, door_y, door_z)
    rl_rotatef(-98.0, 0.0, 1.0, 0.0)
    draw_pbr_box(Vector3(-door_w/2.0, 0, 0), Vector3(door_w, door_h, 0.075), C_METAL_MID,
                 roughness=0.48, metallic=0.86)
    # Outer armor and inner reinforcement on opposite faces.
    draw_pbr_box(Vector3(-door_w/2.0, 0, -0.043), Vector3(door_w-0.14, door_h-0.18, 0.022), C_METAL_DARK,
                 roughness=0.58, metallic=0.78)
    draw_pbr_box(Vector3(-door_w/2.0, 0.35, 0.044), Vector3(door_w-0.20, 0.62, 0.022), C_STEEL,
                 roughness=0.56, metallic=0.78)
    draw_pbr_box(Vector3(-door_w/2.0, 0.35, 0.059), Vector3(door_w-0.32, 0.42, 0.018), C_METAL_DARK,
                 roughness=0.72, metallic=0.58)
    draw_pbr_box(Vector3(-door_w/2.0, 1.22, 0.052), Vector3(door_w-0.20, 0.12, 0.025), C_WARNING,
                 roughness=0.70, metallic=0.22)
    for xx in (-door_w+0.14, -door_w*0.5, -0.14):
        draw_pbr_box(Vector3(xx, 0, 0.053), Vector3(0.045, door_h-0.34, 0.025), C_METAL_EDGE,
                     roughness=0.42, metallic=0.86)
    for yy in (0.54, 1.02, 1.50, 1.98, 2.46):
        draw_pbr_box(Vector3(-door_w/2.0, yy, 0.068), Vector3(door_w-0.26, 0.035, 0.018), C_METAL_DARK,
                     roughness=0.78, metallic=0.52)
    # Inner pocket / maintenance checklist with clipped page-like layers.
    draw_pbr_box(Vector3(-door_w/2.0, 2.30, 0.055), Vector3(0.52, 0.50, 0.035), C_METAL_DARK,
                 roughness=0.68, metallic=0.58)
    draw_pbr_box(Vector3(-door_w/2.0, 2.30, 0.078), Vector3(0.42, 0.39, 0.018), C_PAPER,
                 roughness=0.92, metallic=0.01)
    for yy, ww in ((2.40,0.29),(2.31,0.34),(2.22,0.25),(2.13,0.30)):
        draw_pbr_box(Vector3(-door_w/2.0, yy, 0.091), Vector3(ww, 0.018, 0.008), C_METAL_DARK,
                     roughness=0.92, metallic=0.01)
    # hinge barrels run along the cabinet stile and the open door edge
    for yy in (0.56, 1.72, 2.88):
        draw_pbr_cylinder(Vector3(0.0, yy, 0.015), 0.05, 0.21, C_CHROME,
                          roughness=0.24, metallic=0.94)
    rl_pop_matrix()

    # Fasteners, caution stripes and corrosion on the lower plinth.
    for xoff in (-1.05, -0.68, -0.31, 0.31, 0.68, 1.05):
        draw_pbr_box(Vector3(cx+xoff, 0.42, front_z-0.09), Vector3(0.25, 0.07, 0.025),
                     C_WARNING if int((xoff+2)*10)%2 == 0 else C_METAL_DARK,
                     roughness=0.88, metallic=0.1)
        draw_pbr_sphere(Vector3(cx+xoff, 0.42, front_z-0.11), 0.022, C_CHROME,
                        roughness=0.18, metallic=0.95)
    for xoff in (-1.13, -0.38, 0.38, 1.13):
        for yy in (0.53, 3.03):
            draw_pbr_sphere(Vector3(cx+xoff, yy, front_z-0.08), 0.025, C_CHROME,
                            roughness=0.18, metallic=0.95)



def _draw_electricity_room_mold_vines(pos, height=3.5):
    for i in range(6):
        vy = pos.y + i * (height / 6.0)
        vx = pos.x + math.sin(i * 1.8) * 0.22
        vz = pos.z + math.cos(i * 1.5) * 0.18
        draw_pbr_sphere(Vector3(vx, vy, vz), 0.12 + (6-i)*0.02, C_VINE, roughness=0.85,
                        emissive=Vector3(0.02, 0.12, 0.04))



def _draw_electricity_room_floor_puddle(pos, size):
    draw_pbr_box(Vector3(pos.x, 0.015, pos.z), Vector3(size.x, 0.010, size.y),
                 C_PUDDLE, roughness=0.08, metallic=0.15)



def _draw_electricity_room_static_utility_cabinet(time_val=0.0, is_powered=False):
    """Floor-standing service cabinet copied from the Electricity Room v38 environment."""
    draw_pbr_box(Vector3(35.0, 1.55, -8.5), Vector3(2.8, 3.0, 2.0), C_METAL_DARK,
                 roughness=0.48, metallic=0.72)
    draw_pbr_box(Vector3(35.0, 1.62, -7.47), Vector3(2.45, 2.05, 0.08), C_METAL_MID,
                 roughness=0.38, metallic=0.7)
    for i in range(8):
        draw_pbr_box(Vector3(33.95+i*0.30, 1.62, -7.405), Vector3(0.045, 1.5, 0.04), C_METAL_DARK,
                     roughness=0.52, metallic=0.62)
    pulse = 1.2 if is_powered else (0.55 + 0.45 * math.sin(time_val * 3.2))
    draw_pbr_box(Vector3(34.35, 2.62, -7.39), Vector3(0.18, 0.10, 0.035), C_CYAN,
                 roughness=0.15, emissive=Vector3(0.1*pulse, 0.8*pulse, 1.1*pulse))



def _draw_electricity_room_wall_floor_details_source():
    """Static Electricity Room wall/floor dressing copied from standalone v38.

    Ceiling pipes are intentionally deferred to a later detail pass.
    The source chamber's west-wall extinguisher/axe are omitted because they
    belong to the other room, not this appended wing.
    """
    # ========================================================
    # WALLS: only place details on the actual wall planes.
    # North/south walls: z = +/-12.2. East wall: x = 38.2.
    # ========================================================
    # North wall service strips.
    for x in (16.8,19.0,36.0):
        draw_pbr_box(Vector3(x,3.1,-11.96),Vector3(.10,3.5,.06),C_METAL_DARK,roughness=.72,metallic=.70)
        draw_pbr_box(Vector3(x,4.55,-11.91),Vector3(.34,.12,.035),C_WARNING,roughness=.68,metallic=.30)
    for x in (22.0,27.0,32.0):
        draw_pbr_box(Vector3(x,3.75,-11.91),Vector3(2.2,.07,.07),C_METAL_MID,roughness=.70,metallic=.62)

    # East wall vertical service spine.
    for z in (-7.0,-4.0,4.8,7.2):
        draw_pbr_box(Vector3(37.94,3.15,z),Vector3(.06,3.2,.10),C_STEEL,roughness=.58,metallic=.76)
        draw_pbr_box(Vector3(37.89,4.55,z),Vector3(.035,.16,.38),C_WARNING,roughness=.68,metallic=.30)

    # South wall details are kept away from the existing B panel.
    for x in (16.6,35.5):
        draw_pbr_box(Vector3(x,3.25,11.94),Vector3(.10,2.8,.06),C_METAL_DARK,roughness=.72,metallic=.70)
    for x in (18.5,29.0,35.5):
        draw_pbr_box(Vector3(x,4.65,11.90),Vector3(1.35,.55,.035),C_WARNING,roughness=.72,metallic=.28)

    # Real wall-mounted junction boxes.
    for p in (Vector3(18.5,3.8,-11.90),Vector3(34.5,3.8,-11.90),Vector3(37.90,3.8,-5.2),Vector3(37.90,3.8,5.6)):
        draw_pbr_box(p,Vector3(.48,.52,.10),C_METAL_DARK,roughness=.62,metallic=.74)
        draw_pbr_box(Vector3(p.x,p.y+.03,p.z+(.065 if abs(p.x-37.9)<.2 else 0)),Vector3(.27,.17,.025),C_RUST2,roughness=.86,metallic=.22)

    # Restrained rust/peeling strips, all flush to walls.
    for x,z,h in ((17.2,-11.89,1.15),(36.5,-11.89,.85),(16.9,11.89,1.0),(36.2,11.89,1.25)):
        draw_pbr_box(Vector3(x,2.1+h/2,z),Vector3(.08,h,.025),C_RUST2,roughness=.94,metallic=.12)
    for z,h in ((-7.0,1.0),(5.8,1.35)):
        draw_pbr_box(Vector3(37.89,2.0+h/2,z),Vector3(.025,h,.08),C_RUST2,roughness=.94,metallic=.12)

    # ========================================================
    # FLOOR: everything is <= 0.15 above the established floor.
    # No large covers or slabs.
    # ========================================================
    for p,s in ((Vector3(19.2,.045,6.8),Vector3(1.4,.07,.08)),
                (Vector3(35.5,.045,-6.8),Vector3(1.2,.07,.08))):
        draw_pbr_box(p,s,C_METAL_DARK,roughness=.84,metallic=.50)

    for p,s in ((Vector3(20.0,.055,2.3),Vector3(1.0,.07,.62)),
                (Vector3(35.7,.055,1.5),Vector3(.85,.07,.58)),
                (Vector3(27.0,.055,-6.4),Vector3(1.05,.07,.68))):
        draw_pbr_box(p,s,C_METAL_MID,roughness=.82,metallic=.62)
        for ox in (-.28,.28):
            draw_pbr_cylinder(Vector3(p.x+ox,.095,p.z),.025,.05,C_METAL_DARK,roughness=.62,metallic=.76)

    # Small grounded cable loops: thin and deliberately sparse.
    for center,radius in ((Vector3(23.5,.055,-6.9),.34),(Vector3(34.6,.055,6.0),.28)):
        draw_pbr_torus(center,radius,.035,C_RUBBER,roughness=.76,metallic=.25)

    # Subtle grime, flush rather than chunky.
    for p,s in ((Vector3(24.5,.022,-6.1),Vector3(2.2,.012,.48)),
                (Vector3(33.8,.022,6.0),Vector3(1.8,.012,.42)),
                (Vector3(28.5,.022,8.0),Vector3(2.0,.012,.40))):
        draw_pbr_box(p,s,Color(43,40,35,255),roughness=.99,metallic=.02)

    # ========================================================
    # WALL CHARACTER — layered stains, damaged panels, banners
    # ========================================================
    # Large old moisture/oil stains.  Built from several thin, overlapping
    # plates so they read as irregular grime rather than clean rectangles.
    north_stains = [
        (Vector3(19.0, 3.15, -11.905), Vector3(3.6, 2.0, .018)),
        (Vector3(34.8, 2.65, -11.905), Vector3(2.8, 2.7, .018)),
    ]
    south_stains = [
        (Vector3(17.9, 2.75, 11.905), Vector3(3.2, 2.35, .018)),
        (Vector3(35.6, 3.10, 11.905), Vector3(2.4, 2.65, .018)),
    ]
    east_stains = [
        (Vector3(37.905, 2.75, -8.0), Vector3(.018, 2.5, 3.1)),
        (Vector3(37.905, 3.25, 6.7), Vector3(.018, 2.8, 2.5)),
    ]
    stain_base = Color(42, 39, 34, 220)
    stain_dark = Color(27, 29, 28, 235)
    stain_rust = Color(70, 48, 35, 220)

    for p, sz in north_stains + south_stains:
        draw_pbr_box(p, sz, stain_base, roughness=.99, metallic=.01)
        draw_pbr_box(Vector3(p.x-.35, p.y+.25, p.z-.010),
                     Vector3(sz.x*.38, sz.y*.68, .010), stain_dark,
                     roughness=.99, metallic=.01)
        draw_pbr_box(Vector3(p.x+.52, p.y-.38, p.z-.011),
                     Vector3(sz.x*.24, sz.y*.36, .010), stain_rust,
                     roughness=.99, metallic=.01)

    for p, sz in east_stains:
        draw_pbr_box(p, sz, stain_base, roughness=.99, metallic=.01)
        draw_pbr_box(Vector3(p.x-.010, p.y+.18, p.z-.45),
                     Vector3(.010, sz.y*.58, sz.z*.35), stain_dark,
                     roughness=.99, metallic=.01)
        draw_pbr_box(Vector3(p.x-.011, p.y-.30, p.z+.38),
                     Vector3(.010, sz.y*.30, sz.z*.22), stain_rust,
                     roughness=.99, metallic=.01)

    # Vertical drip trails beneath the big stains.
    for x, top, bottom, z in (
        (18.25, 2.45, 0.92, -11.885),
        (19.15, 2.25, 1.20, -11.884),
        (34.45, 2.15, 0.78, -11.884),
        (35.20, 2.35, 1.05, 11.884),
        (17.55, 2.15, 0.88, 11.884),
    ):
        h = top-bottom
        draw_pbr_box(Vector3(x, bottom+h*.5, z),
                     Vector3(.10, h, .014), stain_dark,
                     roughness=.99, metallic=.01)

    # Broken paint chips around service areas.
    for x,y,z,sx,sy in (
        (21.2,4.2,-11.87,.42,.10),(22.0,4.0,-11.87,.20,.16),
        (31.6,2.2,-11.87,.58,.08),(33.0,2.6,-11.87,.26,.12),
        (18.0,4.3,11.87,.34,.12),(36.4,4.0,11.87,.48,.09),
        (37.87,2.0,-6.1,.10,.55),(37.87,3.0,6.0,.12,.42),
    ):
        draw_pbr_box(Vector3(x,y,z),Vector3(sx,sy,.016),C_RUST2,
                     roughness=.96,metallic=.08)

    # --------------------------------------------------------
    # RIPPED WARNING / MAINTENANCE BANNERS
    # --------------------------------------------------------
    # Layered cloth-like strips: solid backing + alternating torn ends.
    banner_specs = [
        # north wall
        (Vector3(29.0,4.35,-11.875), Vector3(3.5,1.15,.022), "north"),
        # east wall
        (Vector3(37.875,4.10,-2.2), Vector3(.022,1.25,3.4), "east"),
        # south wall, deliberately away from panel B
        (Vector3(18.7,4.05,11.875), Vector3(2.7,1.05,.022), "south"),
    ]
    for p, sz, side in banner_specs:
        draw_pbr_box(p, sz, C_RUST2, roughness=.90, metallic=.10)
        if side in ("north","south"):
            # dark inner stripe and warning blocks
            zoff = -.014 if side == "north" else .014
            draw_pbr_box(Vector3(p.x,p.y,p.z+zoff),
                         Vector3(sz.x*.82,.11,.012), C_WARNING,
                         roughness=.78,metallic=.18)
            for j in range(4):
                bx = p.x - sz.x*.30 + j*sz.x*.20
                draw_pbr_box(Vector3(bx,p.y+.16,p.z+zoff),
                             Vector3(.11,.34,.012), C_METAL_DARK,
                             roughness=.88,metallic=.08)
        else:
            xoff = .014
            draw_pbr_box(Vector3(p.x+xoff,p.y,p.z),
                         Vector3(.012,sz.y*.82,.11), C_WARNING,
                         roughness=.78,metallic=.18)

    # Torn ends are separated so the banner does not look like a perfect plane.
    for p, sz in (
        (Vector3(27.55,3.55,-11.855),Vector3(.42,.55,.018)),
        (Vector3(28.25,3.48,-11.856),Vector3(.24,.70,.018)),
        (Vector3(29.05,3.62,-11.857),Vector3(.35,.42,.018)),
        (Vector3(30.00,3.50,-11.858),Vector3(.48,.60,.018)),
        (Vector3(18.0,3.52,11.855),Vector3(.35,.50,.018)),
        (Vector3(19.0,3.45,11.856),Vector3(.28,.66,.018)),
        (Vector3(37.855,3.65,-3.65),Vector3(.018,.45,.62)),
        (Vector3(37.856,3.35,-2.85),Vector3(.018,.34,.46)),
    ):
        draw_pbr_box(p,sz,C_RUST2,roughness=.93,metallic=.08)

    # Faded lettering: the banners look like old warning notices rather than blank cloth.
    # The letters are intentionally chipped and uneven, as if most paint has weathered away.
    _draw_electricity_room_wall_stencil("DANGER", Vector3(29.0,4.36,-11.892), 2.55, .48, "north", Color(205,191,142,205))
    _draw_electricity_room_wall_stencil("CAUTION", Vector3(18.7,4.06,11.892), 2.05, .42, "south", Color(205,191,142,190))

    # Extra wall-mounted electrical service board: layered housing, vent slots,
    # fuse windows, cable glands, bolts and a small meter make it read as machinery.
    draw_pbr_box(Vector3(35.15,3.15,-8.85), Vector3(2.35,2.15,.16), C_METAL_DARK,
                 roughness=.58, metallic=.78)
    draw_pbr_box(Vector3(35.15,3.15,-8.74), Vector3(2.05,1.82,.06), C_METAL_MID,
                 roughness=.66, metallic=.68)
    draw_pbr_box(Vector3(34.38,3.55,-8.68), Vector3(.58,.88,.045), C_METAL_DARK,
                 roughness=.48, metallic=.82)
    for yy in (3.82,3.58,3.34,3.10):
        draw_pbr_box(Vector3(34.38,yy,-8.645), Vector3(.38,.055,.022), C_STEEL,
                     roughness=.46, metallic=.86)
    draw_pbr_box(Vector3(35.25,3.70,-8.66), Vector3(.58,.34,.035), Color(43,54,48,255),
                 roughness=.32, metallic=.35)
    draw_pbr_box(Vector3(35.25,3.70,-8.635), Vector3(.40,.10,.018), C_WARNING,
                 roughness=.72, metallic=.20)
    for bx in (34.18,36.12):
        for by in (2.42,3.88):
            draw_pbr_cylinder(Vector3(bx,by,-8.63),.045,.035,C_CHROME,
                              roughness=.18, metallic=.95)
    for bx in (35.82,36.18):
        draw_pbr_cylinder(Vector3(bx,2.62,-8.64),.055,.22,C_RUBBER,
                          roughness=.82, metallic=.18)
    draw_pbr_box(Vector3(35.98,2.36,-8.65),Vector3(.52,.18,.04),C_RUST2,
                 roughness=.88, metallic=.16)

    # A small wall tool rack: peg board, brackets, hooks and hanging hand tools.
    draw_pbr_box(Vector3(30.9,3.05,-11.88),Vector3(2.5,2.15,.10),C_METAL_DARK,
                 roughness=.72, metallic=.62)
    draw_pbr_box(Vector3(30.9,3.05,-11.805),Vector3(2.22,1.88,.025),C_METAL_MID,
                 roughness=.82, metallic=.38)
    for gx in (-.82,-.41,0,.41,.82):
        for gy in (2.35,2.76,3.17,3.58):
            draw_pbr_cylinder(Vector3(30.9+gx,gy,-11.77),.025,.025,C_CHROME,
                              roughness=.20, metallic=.95)
    # hanging tools
    draw_pbr_cylinder(Vector3(30.35,2.48,-11.73),.032,.62,C_STEEL,roughness=.25,metallic=.92)
    draw_pbr_box(Vector3(30.35,2.14,-11.73),Vector3(.14,.18,.14),C_WARNING,roughness=.62,metallic=.22)
    draw_pbr_box(Vector3(31.02,2.55,-11.73),Vector3(.55,.065,.10),C_CHROME,roughness=.20,metallic=.95)
    draw_pbr_box(Vector3(31.28,2.55,-11.73),Vector3(.16,.12,.16),C_CHROME,roughness=.18,metallic=.95)
    draw_pbr_cylinder(Vector3(31.65,2.48,-11.73),.035,.58,C_RUBBER,roughness=.80,metallic=.18)

    # Riveted mounting rails around the wall equipment.
    for x,z in ((18.5,-11.84),(34.5,-11.84),(18.7,11.84),(35.5,11.84)):
        draw_pbr_box(Vector3(x,2.65,z),Vector3(2.25,.075,.055),
                     C_METAL_EDGE,roughness=.42,metallic=.86)
        for bx in (-.9,-.3,.3,.9):
            draw_pbr_cylinder(Vector3(x+bx,2.72,z-.02),.025,.035,C_CHROME,
                              roughness=.18,metallic=.95)

    # A few short conduit branches actually terminate in the wall boxes.
    for x,z in ((18.5,-11.84),(34.5,-11.84),(18.7,11.84),(35.5,11.84)):
        draw_pbr_cylinder(Vector3(x,3.35,z),.035,1.05,C_STEEL,
                          roughness=.55,metallic=.80)

    # ========================================================
    # FLOOR — large stains + abandoned papers + real tool pile
    # ========================================================
    floor_stain = Color(39,35,30,225)
    floor_stain2 = Color(55,43,34,210)

    # Large irregular oil/water stains.
    for p, sz in (
        (Vector3(22.0,.021,-6.0),Vector3(4.2,.012,1.25)),
        (Vector3(31.8,.021,6.7),Vector3(4.8,.012,1.35)),
        (Vector3(35.0,.021,-4.2),Vector3(2.8,.012,1.55)),
    ):
        draw_pbr_box(p,sz,floor_stain,roughness=.995,metallic=.0)
    for p, sz in (
        (Vector3(20.9,.027,-5.72),Vector3(1.8,.010,.42)),
        (Vector3(23.1,.027,-6.25),Vector3(1.5,.010,.38)),
        (Vector3(31.0,.027,6.95),Vector3(1.9,.010,.46)),
        (Vector3(33.0,.027,6.35),Vector3(1.4,.010,.34)),
        (Vector3(35.5,.027,-4.55),Vector3(1.0,.010,.42)),
    ):
        draw_pbr_box(p,sz,floor_stain2,roughness=.995,metallic=.0)

    # Paper sheets: layered corners and folded-looking smaller pieces.
    paper = Color(166,158,139,255)
    paper_dark = Color(104,101,90,255)
    for p, sz in (
        (Vector3(24.2,.045,-5.35),Vector3(.82,.018,.58)),
        (Vector3(24.85,.046,-5.05),Vector3(.58,.018,.42)),
        (Vector3(31.0,.045,5.15),Vector3(.95,.018,.62)),
        (Vector3(31.55,.047,5.48),Vector3(.52,.018,.36)),
        (Vector3(35.0,.045,-5.25),Vector3(.72,.018,.50)),
    ):
        draw_pbr_box(p,sz,paper,roughness=.93,metallic=.02)
    for p, sz in (
        (Vector3(24.22,.058,-5.35),Vector3(.50,.012,.035)),
        (Vector3(31.0,.058,5.15),Vector3(.62,.012,.035)),
        (Vector3(35.0,.058,-5.25),Vector3(.44,.012,.035)),
    ):
        draw_pbr_box(p,sz,paper_dark,roughness=.95,metallic=.01)

    # Toolbox.
    draw_pbr_box(Vector3(21.4,.23,-6.8),Vector3(1.25,.38,.72),C_METAL_DARK,
                 roughness=.62,metallic=.62)
    draw_pbr_box(Vector3(21.4,.47,-6.8),Vector3(1.12,.10,.66),C_RUST2,
                 roughness=.88,metallic=.18)
    draw_pbr_box(Vector3(21.4,.70,-6.8),Vector3(.62,.08,.08),C_METAL_EDGE,
                 roughness=.42,metallic=.84)
    for bx in (21.05,21.75):
        draw_pbr_cylinder(Vector3(bx,.23,-6.8),.035,.40,C_CHROME,
                          roughness=.18,metallic=.95)

    # Wrench beside the toolbox: handle + jaw + bolt head.
    draw_pbr_box(Vector3(22.65,.09,-6.65),Vector3(.82,.055,.10),C_CHROME,
                 roughness=.20,metallic=.92)
    draw_pbr_box(Vector3(23.02,.09,-6.65),Vector3(.24,.07,.18),C_CHROME,
                 roughness=.18,metallic=.95)
    draw_pbr_box(Vector3(22.35,.09,-6.65),Vector3(.18,.065,.16),C_CHROME,
                 roughness=.18,metallic=.95)

    # Screwdriver and loose metal rod.
    draw_pbr_cylinder(Vector3(21.9,.10,-7.15),.035,.42,C_CHROME,
                      roughness=.20,metallic=.92)
    draw_pbr_box(Vector3(21.9,.07,-7.38),Vector3(.11,.14,.11),C_WARNING,
                 roughness=.60,metallic=.25)
    draw_pbr_cylinder(Vector3(22.65,.075,-7.25),.022,.58,C_RUST2,
                      roughness=.80,metallic=.55)

    # Loose bolts/nuts around the tool pile.
    for p in (Vector3(22.15,.075,-6.35),Vector3(22.45,.075,-6.25),
              Vector3(21.75,.075,-6.45),Vector3(23.1,.075,-6.92)):
        draw_pbr_torus(p,.055,.018,C_CHROME,roughness=.20,metallic=.95)

    # A fallen wall plate on the floor with screws still attached.
    draw_pbr_box(Vector3(27.5,.075,7.65),Vector3(1.35,.07,.82),C_METAL_DARK,
                 roughness=.78,metallic=.55)
    draw_pbr_box(Vector3(27.5,.115,7.65),Vector3(.82,.018,.48),C_RUST2,
                 roughness=.92,metallic=.18)
    for ox in (-.48,.48):
        for oz in (-.27,.27):
            draw_pbr_cylinder(Vector3(27.5+ox,.13,7.65+oz),.025,.035,C_CHROME,
                              roughness=.18,metallic=.95)

    # ========================================================
    # EMPTY WALL BAY — ELECTRICAL MAINTENANCE WORKBENCH
    # ========================================================
    # Deliberately placed in a quieter bay so it fills the empty section without
    # crowding the existing panels.
    bx, bz = 28.8, -10.15
    draw_pbr_box(Vector3(bx,.78,bz),Vector3(3.8,.16,1.35),C_METAL_DARK,
                 roughness=.62, metallic=.72)
    draw_pbr_box(Vector3(bx,.90,bz),Vector3(3.55,.12,1.18),C_DESK_TOP,
                 roughness=.52, metallic=.38)
    # Four heavy legs and cross braces.
    for lx in (bx-1.55,bx+1.55):
        for lz in (bz-.48,bz+.48):
            draw_pbr_box(Vector3(lx,.40,lz),Vector3(.16,.72,.16),C_METAL_DARK,
                         roughness=.58, metallic=.80)
    for lz in (bz-.48,bz+.48):
        draw_pbr_box(Vector3(bx,.48,lz),Vector3(3.15,.10,.10),C_STEEL,
                     roughness=.48, metallic=.82)
    # Backboard / small shelf.
    draw_pbr_box(Vector3(bx,1.72,bz-.46),Vector3(3.25,1.45,.10),C_METAL_DARK,
                 roughness=.72, metallic=.60)
    draw_pbr_box(Vector3(bx,2.48,bz-.42),Vector3(3.05,.10,.92),C_METAL_MID,
                 roughness=.74, metallic=.54)
    # Three labelled-looking electrical drawers.
    for i in range(3):
        xx=bx-1.0+i*1.0
        draw_pbr_box(Vector3(xx,1.96,bz-.35),Vector3(.78,.42,.10),C_METAL_EDGE,
                     roughness=.45, metallic=.82)
        draw_pbr_box(Vector3(xx,2.04,bz-.29),Vector3(.32,.07,.018),C_WARNING,
                     roughness=.72, metallic=.18)
        draw_pbr_cylinder(Vector3(xx,1.92,bz-.25),.035,.045,C_CHROME,
                          roughness=.18, metallic=.95)
    # Multimeter, test leads and a coil of cable.
    draw_pbr_box(Vector3(bx-.95,1.06,bz+.05),Vector3(.62,.13,.46),C_METAL_DARK,
                 roughness=.48, metallic=.76)
    draw_pbr_box(Vector3(bx-.95,1.135,bz+.02),Vector3(.42,.025,.22),Color(38,48,43,255),
                 roughness=.30, metallic=.32)
    for zz in (bz-.18,bz+.04):
        draw_pbr_cylinder(Vector3(bx-.95,1.17,zz),.018,.18,C_WARNING,
                          roughness=.70, metallic=.20)
    draw_pbr_torus(Vector3(bx+.35,1.03,bz+.05),.30,.045,C_RUBBER,
                   roughness=.78, metallic=.18)
    draw_pbr_torus(Vector3(bx+.35,1.05,bz+.05),.22,.032,C_RUBBER,
                   roughness=.78, metallic=.18)
    # Insulated screwdriver set and fuse tray.
    for i,col in enumerate((C_WARNING,C_RUST2,C_METAL_EDGE)):
        draw_pbr_cylinder(Vector3(bx+1.0+i*.24,1.05,bz-.16),.025,.36,C_CHROME,
                          roughness=.20, metallic=.92)
        draw_pbr_box(Vector3(bx+1.0+i*.24,.86,bz-.16),Vector3(.09,.16,.09),col,
                     roughness=.64, metallic=.22)
    draw_pbr_box(Vector3(bx+1.05,1.04,bz+.36),Vector3(.70,.10,.42),C_METAL_DARK,
                 roughness=.64, metallic=.68)
    for i in range(4):
        draw_pbr_cylinder(Vector3(bx+.82+i*.15,1.12,bz+.36),.045,.035,C_CHROME,
                          roughness=.18, metallic=.95)
    # Clipboard and insulated gloves.
    draw_pbr_box(Vector3(bx-1.55,1.05,bz-.28),Vector3(.48,.055,.65),paper,
                 roughness=.94, metallic=.01)
    draw_pbr_box(Vector3(bx-1.55,1.11,bz-.57),Vector3(.20,.04,.07),C_METAL_EDGE,
                 roughness=.40, metallic=.88)
    draw_pbr_box(Vector3(bx+1.35,1.05,bz-.28),Vector3(.46,.08,.30),C_WARNING,
                 roughness=.78, metallic=.18)
    draw_pbr_box(Vector3(bx+1.48,1.08,bz-.40),Vector3(.20,.12,.12),C_WARNING,
                 roughness=.78, metallic=.18)


    # ========================================================
    # V8 SMALL TOUCHES — SAFETY GEAR / FLOOR DAMAGE / FINAL BAY
    # ========================================================

    # Cracked / missing floor panels. These are shallow static details.
    crack_col = Color(42, 40, 36, 235)
    crack2 = Color(74, 67, 57, 210)
    for x,y,z,l,w in (
        (19.2,.028,-4.0,1.55,.035),(20.0,.029,-4.32,.90,.028),
        (26.0,.028,5.8,1.85,.035),(26.55,.029,6.12,.85,.028),
        (34.8,.028,1.8,1.40,.032),(35.35,.029,1.48,.75,.026),
        (23.5,.028,8.8,1.25,.03),
    ):
        draw_pbr_box(Vector3(x,y,z),Vector3(l,.012,w),crack_col,roughness=.99,metallic=.0)
    for x,z,sx,sz in (
        (20.6,-4.55,.90,.58),(27.4,6.35,1.10,.72),(35.8,1.10,.82,.60)
    ):
        draw_pbr_box(Vector3(x,.035,z),Vector3(sx,.018,sz),C_METAL_DARK,roughness=.88,metallic=.32)
        draw_pbr_box(Vector3(x,.047,z),Vector3(sx*.74,.012,sz*.58),C_RUST2,roughness=.94,metallic=.10)
        for ox in (-sx*.34,sx*.34):
            draw_pbr_cylinder(Vector3(x+ox,.06,z-sz*.23),.025,.035,C_CHROME,
                              roughness=.18,metallic=.95)

    # Old maintenance table removed; its parts are now arranged inside the new two-door cabinet.

    # Small debris: insulation chunks and cable ties.
    for x,y,z,sz in (
        (29.4,.06,7.4,.20),(29.9,.055,7.7,.16),(30.3,.055,7.35,.22),
    ):
        draw_pbr_box(Vector3(x,y,z),Vector3(sz,.06,sz*.65),
                     C_METAL_MID,roughness=.88,metallic=.28)




