def _draw_electricity_room_auxiliary_tube_visual_v38(pos, rot=None):
    """A distinctive hand-sized ceramic induction tube with copper windings and keyed metal ends."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    if rot is not None:
        rl_rotatef(rot.y, 0.0, 1.0, 0.0)
    # Local Y is turned horizontal so the assembly lies naturally across a shelf.
    rl_rotatef(90.0, 0.0, 0.0, 1.0)
    draw_pbr_cylinder(Vector3(0, 0.0, 0), 0.085, 0.58, C_METAL_DARK,
                      roughness=0.34, metallic=0.52)
    # Dark ceramic ribs and the copper induction coil windings.
    for yy in (-0.22, -0.15, -0.08, 0.0, 0.08, 0.15, 0.22):
        draw_pbr_torus(Vector3(0, yy, 0), 0.089, 0.014,
                       C_BRASS if yy in (-0.22, 0.22) else Color(174, 91, 47, 255),
                       roughness=0.28, metallic=0.84)
    # Machined metal end caps and keyed contact tips.
    draw_pbr_cylinder(Vector3(0, -0.225, 0), 0.105, 0.11, C_CHROME,
                      roughness=0.22, metallic=0.94)
    draw_pbr_cylinder(Vector3(0, 0.335, 0), 0.105, 0.11, C_CHROME,
                      roughness=0.22, metallic=0.94)
    draw_pbr_cylinder(Vector3(0, -0.32, 0), 0.045, 0.08, C_BRASS,
                      roughness=0.22, metallic=0.88)
    draw_pbr_cylinder(Vector3(0, 0.40, 0), 0.045, 0.08, C_BRASS,
                      roughness=0.22, metallic=0.88)
    # Identification stripe and live cyan diagnostic pip.
    draw_pbr_box(Vector3(0.044, 0.0, 0.076), Vector3(0.11, 0.16, 0.024), C_WARNING,
                 roughness=0.58, metallic=0.20)
    draw_pbr_box(Vector3(0.051, 0.01, 0.087), Vector3(0.045, 0.045, 0.010), C_METAL_DARK,
                 roughness=0.35, metallic=0.6)
    draw_pbr_sphere(Vector3(0.058, 0.075, 0.055), 0.018, C_CYAN,
                    roughness=0.12, metallic=0.0, emissive=Vector3(0.03, 0.45, 0.65))
    rl_pop_matrix()



def _draw_electricity_room_ceiling_panel_light_v38(pos, flicker_val=1.0, time_val=0.0,
                                    is_powered=False, recovery_intensity=0.0, phase=0.0):
    """Flush-mounted industrial ceiling fixture; follows the generator light-recovery pulse."""
    recovery_intensity = max(0.0, min(1.0, float(recovery_intensity)))
    phase_wave = 0.90 + 0.10 * math.sin(time_val * 16.0 + phase)
    flicker = max(0.0, min(1.45, float(flicker_val) * phase_wave))

    # Thin mount plate, end caps and suspension studs: these sit just below the ceiling underside.
    draw_pbr_box(Vector3(pos.x, pos.y, pos.z), Vector3(2.50, 0.10, 0.82),
                 C_METAL_DARK, roughness=0.38, metallic=0.78)
    draw_pbr_box(Vector3(pos.x, pos.y - 0.060, pos.z), Vector3(2.30, 0.035, 0.66),
                 C_METAL_EDGE, roughness=0.28, metallic=0.70)
    for ox in (-0.84, 0.84):
        draw_pbr_box(Vector3(pos.x + ox, pos.y + 0.065, pos.z),
                     Vector3(0.10, 0.10, 0.13), C_STEEL, roughness=0.30, metallic=0.82)

    if is_powered:
        tube_level = 2.05
    elif recovery_intensity > 0.001:
        tube_level = max(0.0, min(2.20, 2.05 * flicker * recovery_intensity))
    else:
        tube_level = 0.24 * flicker

    tube_emissive = Vector3(1.0 * tube_level, 0.94 * tube_level, 0.78 * tube_level)
    tube_colour = Color(178, 190, 181, 255) if tube_level < 0.8 else Color(220, 232, 220, 255)
    for zo in (-0.19, 0.0, 0.19):
        draw_pbr_box(Vector3(pos.x, pos.y - 0.090, pos.z + zo),
                     Vector3(2.15, 0.026, 0.105), tube_colour,
                     roughness=0.18, metallic=0.02, emissive=tube_emissive)

    # Four visible corner fasteners make the assembly read as fitted equipment, not a floating slab.
    for ox in (-1.13, 1.13):
        for oz in (-0.29, 0.29):
            draw_pbr_cylinder(Vector3(pos.x + ox, pos.y - 0.082, pos.z + oz),
                              0.027, 0.018, C_CHROME, roughness=0.22, metallic=0.86)



def _draw_electricity_room_pipe_axis_v38(pos, length, radius, color, axis="x", roughness=0.52, metallic=0.78):
    """Draw a pipe centered exactly on its requested world-space segment."""
    set_pbr_material(color, roughness, metallic)
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    if axis == "x":
        rl_rotatef(90, 0, 0, 1)
    elif axis == "z":
        rl_rotatef(90, 1, 0, 0)
    # gen_mesh_cylinder is bottom-anchored, so shift by half its length
    # after rotation. This prevents every horizontal/vertical pipe from
    # being displaced by half its own length.
    rl_translatef(0, -length / 2.0, 0)
    rl_scalef(radius, length, radius)
    draw_model(unit_cylinder_model, Vector3(0, 0, 0), 1.0, WHITE)
    rl_pop_matrix()



def _draw_electricity_room_wire_segment_v38(a, b, radius, color, roughness=0.82, metallic=0.05, emissive=None):
    """Low-cost round cable segment between two world-space points, with optional emissive glow."""
    dx = b.x - a.x
    dy = b.y - a.y
    dz = b.z - a.z
    length = math.sqrt(dx*dx + dy*dy + dz*dz)
    if length < 0.001:
        return

    # Cylinder meshes are aligned to +Y. Rotate that axis onto the segment.
    nx = dx / length
    ny = dy / length
    nz = dz / length

    ax = nz
    ay = 0.0
    az = -nx
    axis_len = math.sqrt(ax*ax + ay*ay + az*az)
    dot = max(-1.0, min(1.0, ny))
    angle = math.degrees(math.acos(dot))

    set_pbr_material(color, roughness, metallic, emissive)
    rl_push_matrix()
    rl_translatef((a.x + b.x) * 0.5, (a.y + b.y) * 0.5, (a.z + b.z) * 0.5)
    if axis_len > 0.0001:
        rl_rotatef(angle, ax / axis_len, ay / axis_len, az / axis_len)
    elif ny < 0.0:
        rl_rotatef(180.0, 1.0, 0.0, 0.0)
    rl_scalef(radius, length, radius)
    draw_model(unit_cylinder_model, Vector3(0, -0.5, 0), 1.0, WHITE)
    rl_pop_matrix()



def _draw_electricity_room_generator_visual_v38(pos, time_val=0.0, auxiliary_tube_installed=False, thermal_module_installed=False, powered=False, igniting=False, induction_aligned=False):
    """Large industrial generator with separate induction and thermal module bays."""
    # Heavy foundation and main graphite housing.
    draw_pbr_box(Vector3(pos.x, 0.22, pos.z), Vector3(5.15, 0.36, 3.05), C_METAL_DARK,
                 roughness=0.58, metallic=0.78)
    for x in (-2.18, -0.72, 0.72, 2.18):
        for z in (-1.22, 1.22):
            draw_pbr_box(Vector3(pos.x+x, 0.12, pos.z+z), Vector3(0.36, 0.22, 0.38), C_STEEL,
                         roughness=0.35, metallic=0.88)
    draw_pbr_box(Vector3(pos.x, 1.08, pos.z), Vector3(3.55, 1.65, 2.25), C_METAL_DARK,
                 roughness=0.46, metallic=0.82)
    # Front armored face, vent banks and central service display.
    draw_pbr_box(Vector3(pos.x, 1.10, pos.z-1.17), Vector3(3.20, 1.28, 0.12), C_METAL_MID,
                 roughness=0.43, metallic=0.76)
    for side_x in (-1.25, -0.95, -0.65, 0.65, 0.95, 1.25):
        draw_pbr_box(Vector3(pos.x+side_x, 0.90, pos.z-1.245), Vector3(0.075, 0.65, 0.035), C_METAL_DARK,
                     roughness=0.6, metallic=0.62)
    # Main diagnostic screen, framed and inset.
    draw_pbr_box(Vector3(pos.x, 1.52, pos.z-1.255), Vector3(1.02, 0.48, 0.10), C_METAL_DARK,
                 roughness=0.35, metallic=0.72)
    screen_glow = Vector3(0.02, 0.65, 0.78) if not powered else Vector3(0.10, 1.25, 0.48)
    draw_pbr_box(Vector3(pos.x, 1.53, pos.z-1.315), Vector3(0.82, 0.30, 0.025), C_CHAMBER_GLASS,
                 roughness=0.2, metallic=0.28, emissive=screen_glow if (powered or not igniting) else Vector3(0.05, 0.8, 1.0))
    # Two large side-mounted battery cradles: left induction bay and right thermal bay.
    for side, slot_idx in ((-1, 0), (1, 1)):
        sx = pos.x + side*2.32
        installed = (auxiliary_tube_installed and induction_aligned) if slot_idx == 0 else thermal_module_installed
        module_a_energized = auxiliary_tube_installed and induction_aligned
        bay_col = (C_GREEN_DIM if (installed or powered) else (C_CYAN if slot_idx == 0 and auxiliary_tube_installed else C_METAL_DARK))
        if installed or powered:
            bay_glow = Vector3(0.05, 0.85, 0.18)
        elif slot_idx == 0 and auxiliary_tube_installed:
            bay_glow = Vector3(0.0, 0.42, 0.62)
        else:
            bay_glow = Vector3(0.0, 0.0, 0.0)
        # Reinforced bracket and recessed cavity.
        draw_pbr_box(Vector3(sx, 1.02, pos.z), Vector3(1.18, 1.38, 1.76), C_METAL_MID,
                     roughness=0.48, metallic=0.82)
        draw_pbr_box(Vector3(sx, 1.06, pos.z), Vector3(1.02, 1.12, 1.52), C_METAL_DARK,
                     roughness=0.42, metallic=0.78)
        # rails and bottom guide tracks
        for zoff in (-0.57, 0.57):
            draw_pbr_box(Vector3(sx, 0.62, pos.z+zoff), Vector3(0.88, 0.10, 0.09), C_STEEL,
                         roughness=0.34, metallic=0.9)
        for xoff in (-0.42, 0.42):
            draw_pbr_box(Vector3(sx+xoff, 1.02, pos.z-0.69), Vector3(0.09, 0.94, 0.10), C_METAL_EDGE,
                         roughness=0.3, metallic=0.86)
        # Keyed auxiliary connector at the back of each slot.
        draw_pbr_cylinder(Vector3(sx, 1.08, pos.z-0.54), 0.19, 0.12, C_COPPER if 'C_COPPER' in globals() else C_RUST2,
                          roughness=0.38, metallic=0.78)
        draw_pbr_cylinder(Vector3(sx, 1.08, pos.z-0.63), 0.075, 0.12, C_CHROME,
                          roughness=0.22, metallic=0.92)
        # Two clamp arms and top latch.
        for xoff in (-0.43, 0.43):
            draw_pbr_box(Vector3(sx+xoff, 1.55, pos.z+0.02), Vector3(0.11, 0.20, 0.90), C_STEEL,
                         roughness=0.32, metallic=0.88)
        draw_pbr_box(Vector3(sx, 1.66, pos.z+0.02), Vector3(0.56, 0.12, 0.20), C_METAL_EDGE,
                     roughness=0.3, metallic=0.9)
        # Distinct bay labels and status lamps.
        draw_pbr_box(Vector3(sx, 1.79, pos.z-0.91), Vector3(0.84, 0.22, 0.055), C_WARNING if side < 0 else C_CYAN,
                     roughness=0.72, metallic=0.25)
        lamp = (C_GREEN_DIM if installed or powered else
                (C_CYAN if (igniting or (slot_idx == 0 and auxiliary_tube_installed)) else C_RED_DIM))
        if installed or powered:
            lamp_emission = bay_glow
        elif slot_idx == 0 and auxiliary_tube_installed:
            lamp_emission = Vector3(0.0, 0.32, 0.50)
        elif igniting:
            lamp_emission = Vector3(0.1, 0.7, 0.9)
        else:
            # pyray.Vector3 is a CFFI struct; scale its channels explicitly instead of
            # multiplying the vector object (which raises TypeError at runtime).
            blink = 0.55 + 0.45 * math.sin(time_val * 5.5)
            lamp_emission = Vector3(1.0 * blink, 0.08 * blink, 0.03 * blink)
        draw_pbr_sphere(Vector3(sx, 1.82, pos.z-0.98), 0.065, lamp, roughness=0.2, emissive=lamp_emission)
        # The recovered A-01 assembly is rendered as the actual tube, seated between
        # the guide rails, rather than disappearing into a generic battery-shaped block.
        if slot_idx == 0 and auxiliary_tube_installed:
            _draw_electricity_room_auxiliary_tube_visual_v38(Vector3(sx, 1.10, pos.z+0.02))
            draw_pbr_box(Vector3(sx, 1.59, pos.z-0.02), Vector3(0.56, 0.055, 0.18), C_GREEN_DIM,
                         roughness=0.38, metallic=0.68, emissive=Vector3(0.04, 0.55, 0.14))
        elif installed or powered:
            draw_pbr_box(Vector3(sx, 1.08, pos.z+0.05), Vector3(0.70, 0.74, 0.82), C_STEEL,
                         roughness=0.42, metallic=0.75, emissive=bay_glow)
            for coil in range(5):
                draw_pbr_box(Vector3(sx-0.28+coil*0.14, 1.08, pos.z+0.48), Vector3(0.045, 0.50, 0.035), C_RUST2,
                             roughness=0.45, metallic=0.7)
    # Upper engine housing, cooling fins, pipes and exhaust.
    draw_pbr_box(Vector3(pos.x, 2.12, pos.z+0.22), Vector3(2.15, 0.42, 1.42), C_METAL_MID,
                 roughness=0.5, metallic=0.78)
    for i in range(9):
        draw_pbr_box(Vector3(pos.x-0.92+i*0.23, 2.14, pos.z+0.98), Vector3(0.07, 0.30, 0.20), C_METAL_DARK,
                     roughness=0.55, metallic=0.68)
    draw_pbr_cylinder(Vector3(pos.x+1.22, 2.18, pos.z+0.70), 0.14, 1.15, C_CHROME,
                      roughness=0.28, metallic=0.9)
    draw_pbr_box(Vector3(pos.x+1.22, 2.78, pos.z+0.70), Vector3(0.42, 0.14, 0.42), C_METAL_DARK,
                 roughness=0.45, metallic=0.78)
    # Cable trunk and three incoming conduit glands retained for existing room routing.
    draw_pbr_box(Vector3(pos.x, 0.48, pos.z-1.30), Vector3(1.50, 0.42, 0.22), C_METAL_MID,
                 roughness=0.4, metallic=0.82)
    for i in range(4):
        draw_pbr_cylinder(Vector3(pos.x-0.50+i*0.33, 0.45, pos.z-1.43), 0.055, 0.22, C_STEEL,
                          roughness=0.3, metallic=0.9)
    # Small fasteners on the main face.
    for xoff in (-1.48, 1.48):
        for y in (0.62, 1.04, 1.46):
            draw_pbr_cylinder(Vector3(pos.x+xoff, y, pos.z-1.25), 0.035, 0.035, C_CHROME,
                              roughness=0.18, metallic=0.95)

    # NEW DETAIL PASS // reinforced armor, service hatches, bolts and warning band.
    # Corner ribs make the shell feel like a heavy, assembled industrial machine.
    for side in (-1, 1):
        sx = pos.x + side*1.62
        draw_pbr_box(Vector3(sx, 1.10, pos.z-1.205), Vector3(0.13, 1.38, 0.13), C_STEEL,
                     roughness=0.38, metallic=0.88)
        for by in (0.52, 0.86, 1.20, 1.54):
            draw_pbr_cylinder(Vector3(sx, by, pos.z-1.285), 0.035, 0.035, C_CHROME,
                              roughness=0.22, metallic=0.95)
        # Vertical electrical conduit runs down both outer sides of the case.
        draw_pbr_cylinder(Vector3(pos.x+side*1.83, 0.92, pos.z-0.45), 0.065, 1.15, C_RUBBER,
                          roughness=0.82, metallic=0.10)
        for cy in (0.55, 1.15, 1.65):
            draw_pbr_box(Vector3(pos.x+side*1.83, cy, pos.z-0.45), Vector3(0.16, 0.07, 0.18), C_METAL_EDGE,
                         roughness=0.35, metallic=0.88)

    # Two additional inset service doors with hinges and latch handles.
    for side in (-1, 1):
        hx = pos.x + side*1.13
        draw_pbr_box(Vector3(hx, 1.01, pos.z-1.255), Vector3(0.30, 0.46, 0.045), C_METAL_DARK,
                     roughness=0.52, metallic=0.65)
        draw_pbr_box(Vector3(hx, 1.01, pos.z-1.284), Vector3(0.23, 0.37, 0.018), C_METAL_MID,
                     roughness=0.62, metallic=0.52)
        for hy in (0.84, 1.18):
            draw_pbr_cylinder(Vector3(hx-side*0.105, hy, pos.z-1.305), 0.025, 0.035, C_CHROME,
                              roughness=0.2, metallic=0.94)
        draw_pbr_box(Vector3(hx+side*0.055, 1.02, pos.z-1.32), Vector3(0.035, 0.13, 0.025), C_BRASS,
                     roughness=0.28, metallic=0.82)

    # Dual analog meters mounted either side of the cyan diagnostic display.
    for gx in (pos.x-0.92, pos.x+0.92):
        rl_push_matrix()
        rl_translatef(gx, 1.52, pos.z-1.345)
        rl_rotatef(90.0, 1.0, 0.0, 0.0)
        draw_pbr_cylinder(Vector3(0, 0.055, 0), 0.125, 0.06, C_METAL_DARK,
                          roughness=0.42, metallic=0.72)
        draw_pbr_torus(Vector3(0, 0, 0), 0.12, 0.018, C_CHROME, roughness=0.22, metallic=0.92)
        draw_pbr_cylinder(Vector3(0, 0.025, 0), 0.082, 0.02, C_CHAMBER_GLASS,
                          roughness=0.24, metallic=0.3,
                          emissive=Vector3(0.02, 0.18, 0.20) if not powered else Vector3(0.08, 0.28, 0.12))
        # Small pale meter needle / calibration ticks.
        draw_pbr_box(Vector3(0.015, 0.018, 0.028), Vector3(0.014, 0.008, 0.060), C_WARNING,
                     roughness=0.35, metallic=0.25)
        rl_pop_matrix()

    # A strip of segmented hazard paint on the lower lip, chipped and interrupted like real wear.
    for i in range(11):
        stripe_x = pos.x - 1.25 + i*0.25
        stripe_col = C_WARNING if i % 2 == 0 else C_METAL_DARK
        draw_pbr_box(Vector3(stripe_x, 0.425, pos.z-1.285), Vector3(0.19, 0.075, 0.028), stripe_col,
                     roughness=0.82, metallic=0.08)
    draw_pbr_box(Vector3(pos.x, 0.54, pos.z-1.30), Vector3(0.76, 0.07, 0.045), C_METAL_DARK,
                 roughness=0.4, metallic=0.72)
    for i in range(5):
        draw_pbr_box(Vector3(pos.x-0.27+i*0.135, 0.54, pos.z-1.33), Vector3(0.075, 0.035, 0.018),
                     (C_RED_DIM, C_WARNING, C_GREEN_DIM, C_CYAN, C_RED_DIM)[i],
                     roughness=0.25, metallic=0.12,
                     emissive=Vector3(0.24, 0.015, 0.01) if i == 0 and not powered else None)

    # Heavy lower cable glands and looped service cabling on the machine's front edge.
    for i, col in enumerate((C_GREEN_DIM, C_WARNING, C_CYAN, C_RED_DIM)):
        cx = pos.x - 0.55 + i*0.36
        draw_pbr_cylinder(Vector3(cx, 0.42, pos.z-1.48), 0.075, 0.16, C_METAL_DARK,
                          roughness=0.4, metallic=0.8)
        draw_pbr_cylinder(Vector3(cx, 0.39, pos.z-1.57), 0.045, 0.12, col,
                          roughness=0.38, metallic=0.4)
        draw_pbr_box(Vector3(cx, 0.23, pos.z-1.76), Vector3(0.07, 0.30, 0.06), C_RUBBER,
                     roughness=0.88, metallic=0.08)

    # Upper housing gets ribbed side cooling fins, clamps and a second line of fasteners.
    for side in (-1, 1):
        for i in range(5):
            draw_pbr_box(Vector3(pos.x+side*(1.12+i*0.035), 2.12, pos.z+0.30+i*0.12),
                         Vector3(0.055, 0.30, 0.07), C_STEEL, roughness=0.47, metallic=0.82)
        draw_pbr_box(Vector3(pos.x+side*0.93, 2.38, pos.z+0.20), Vector3(0.32, 0.08, 0.85), C_METAL_DARK,
                     roughness=0.48, metallic=0.80)
        for bz in (-0.05, 0.45):
            draw_pbr_cylinder(Vector3(pos.x+side*1.00, 2.42, pos.z+bz), 0.035, 0.035, C_CHROME,
                              roughness=0.2, metallic=0.94)

    # Small shock mounts visible beneath the generator's reinforced base.
    for xoff in (-1.85, 1.85):
        draw_pbr_box(Vector3(pos.x+xoff, 0.30, pos.z+1.48), Vector3(0.38, 0.22, 0.22), C_METAL_MID,
                     roughness=0.52, metallic=0.74)
        draw_pbr_cylinder(Vector3(pos.x+xoff, 0.25, pos.z+1.49), 0.09, 0.07, C_RUBBER,
                          roughness=0.94, metallic=0.02)


    # INDUSTRIAL REAR + SIDE DETAIL PASS --------------------------------------
    # The front is already dressed; these attached panels make the machine read
    # as a serviceable generator when the player walks around either side.
    for side in (-1, 1):
        outer_x = pos.x + side * 2.955
        # Deep outer armor on each removable battery bay.
        draw_pbr_box(Vector3(outer_x, 1.03, pos.z + 0.02),
                     Vector3(0.055, 1.22, 1.62), C_METAL_DARK,
                     roughness=0.56, metallic=0.82)
        draw_pbr_box(Vector3(outer_x + side*0.034, 1.05, pos.z + 0.02),
                     Vector3(0.028, 0.92, 1.34), C_METAL_MID,
                     roughness=0.60, metallic=0.70)
        # Layered cooling louvers, recessed gaps, and edge protection.
        for i in range(7):
            yy = 0.69 + i*0.115
            draw_pbr_box(Vector3(outer_x + side*0.055, yy, pos.z - 0.28),
                         Vector3(0.034, 0.045, 0.78), C_METAL_DARK,
                         roughness=0.78, metallic=0.55)
        for zoff in (-0.68, 0.68):
            draw_pbr_box(Vector3(outer_x + side*0.06, 1.03, pos.z + zoff),
                         Vector3(0.045, 1.12, 0.075), C_STEEL,
                         roughness=0.38, metallic=0.88)
            for yy in (0.55, 0.84, 1.13, 1.42, 1.68):
                draw_pbr_sphere(Vector3(outer_x + side*0.09, yy, pos.z + zoff),
                                0.026, C_CHROME, roughness=0.20, metallic=0.94)
        # Small service hatch on each outer side with latch and warning marker.
        hatch_z = pos.z + 0.50
        draw_pbr_box(Vector3(outer_x + side*0.08, 1.62, hatch_z),
                     Vector3(0.05, 0.30, 0.46), C_METAL_DARK,
                     roughness=0.52, metallic=0.76)
        draw_pbr_box(Vector3(outer_x + side*0.11, 1.62, hatch_z),
                     Vector3(0.028, 0.21, 0.36), C_METAL_MID,
                     roughness=0.55, metallic=0.66)
        draw_pbr_box(Vector3(outer_x + side*0.13, 1.71, hatch_z),
                     Vector3(0.025, 0.045, 0.22), C_WARNING,
                     roughness=0.62, metallic=0.25)
        draw_pbr_box(Vector3(outer_x + side*0.13, 1.54, hatch_z + 0.12),
                     Vector3(0.027, 0.09, 0.035), C_CHROME,
                     roughness=0.23, metallic=0.94)
        # Exposed vertical conduit and cable clamps down the outer flank.
        conduit_x = outer_x + side*0.10
        draw_pbr_cylinder(Vector3(conduit_x, 0.97, pos.z - 0.50),
                          0.045, 0.94, C_RUBBER, roughness=0.84, metallic=0.12)
        for yy in (0.60, 0.98, 1.36):
            draw_pbr_box(Vector3(conduit_x + side*0.025, yy, pos.z - 0.50),
                         Vector3(0.10, 0.06, 0.16), C_METAL_EDGE,
                         roughness=0.42, metallic=0.88)
        # Top service rails and exposed tie-down loops on each side.
        for zoff in (-0.48, 0.40):
            draw_pbr_box(Vector3(pos.x + side*2.45, 1.88, pos.z + zoff),
                         Vector3(0.76, 0.075, 0.085), C_STEEL,
                         roughness=0.38, metallic=0.90)
            draw_pbr_box(Vector3(pos.x + side*2.70, 1.94, pos.z + zoff),
                         Vector3(0.10, 0.17, 0.10), C_METAL_DARK,
                         roughness=0.48, metallic=0.78)

    # Rear armored maintenance face (positive Z), with a service hatch and a
    # wider ventilation bank, distinct from the front display and cable glands.
    rear_z = pos.z + 1.175
    draw_pbr_box(Vector3(pos.x, 1.12, rear_z), Vector3(3.12, 1.22, 0.09), C_METAL_MID,
                 roughness=0.52, metallic=0.82)
    draw_pbr_box(Vector3(pos.x, 1.12, rear_z + 0.055), Vector3(2.86, 1.02, 0.035), C_METAL_DARK,
                 roughness=0.60, metallic=0.70)
    # Two vent banks with raised louvers and recessed dark slots.
    for bank_x in (pos.x - 0.78, pos.x + 0.78):
        draw_pbr_box(Vector3(bank_x, 1.15, rear_z + 0.085), Vector3(0.68, 0.82, 0.025), C_METAL_MID,
                     roughness=0.66, metallic=0.62)
        for i in range(6):
            yy = 0.83 + i*0.115
            draw_pbr_box(Vector3(bank_x, yy, rear_z + 0.112), Vector3(0.56, 0.045, 0.025), C_METAL_DARK,
                         roughness=0.74, metallic=0.52)
    # Centered access hatch, with overlapping lip plates, hinges, latch and status pips.
    draw_pbr_box(Vector3(pos.x, 1.20, rear_z + 0.085), Vector3(0.72, 0.92, 0.035), C_STEEL,
                 roughness=0.42, metallic=0.88)
    draw_pbr_box(Vector3(pos.x, 1.20, rear_z + 0.112), Vector3(0.59, 0.78, 0.028), C_METAL_DARK,
                 roughness=0.54, metallic=0.74)
    draw_pbr_box(Vector3(pos.x, 1.48, rear_z + 0.135), Vector3(0.42, 0.07, 0.018), C_WARNING,
                 roughness=0.62, metallic=0.24)
    draw_pbr_box(Vector3(pos.x + 0.20, 1.11, rear_z + 0.14), Vector3(0.035, 0.20, 0.018), C_CHROME,
                 roughness=0.22, metallic=0.95)
    for hx in (-0.27, 0.27):
        for hy in (0.84, 1.54):
            draw_pbr_sphere(Vector3(pos.x + hx, hy, rear_z + 0.14), 0.027, C_CHROME,
                            roughness=0.18, metallic=0.95)
    for i, lamp_col in enumerate((C_RED_DIM, C_WARNING, C_GREEN_DIM, C_CYAN)):
        draw_pbr_sphere(Vector3(pos.x - 0.21 + i*0.14, 0.78, rear_z + 0.145), 0.025,
                        lamp_col, roughness=0.16, metallic=0.2,
                        emissive=Vector3(0.22, 0.02, 0.01) if i == 0 and not powered else None)

    # Rear cable termination strip and heavy glands, visually tied to the routed runs.
    draw_pbr_box(Vector3(pos.x, 0.42, rear_z + 0.09), Vector3(2.30, 0.28, 0.12), C_METAL_DARK,
                 roughness=0.48, metallic=0.82)
    for i, col in enumerate((C_GREEN_DIM, C_WARNING, C_CYAN, C_RED_DIM, C_STEEL)):
        cx = pos.x - 0.78 + i*0.39
        draw_pbr_cylinder(Vector3(cx, 0.43, rear_z + 0.19), 0.073, 0.11, C_METAL_EDGE,
                          roughness=0.35, metallic=0.90)
        draw_pbr_sphere(Vector3(cx, 0.43, rear_z + 0.255), 0.045, col,
                        roughness=0.24, metallic=0.68)
        draw_pbr_box(Vector3(cx, 0.21, rear_z + 0.16), Vector3(0.075, 0.22, 0.075), C_RUBBER,
                     roughness=0.88, metallic=0.08)
    # Rear upper cooling manifold, rigid metal pipes, elbows and clamps.
    draw_pbr_box(Vector3(pos.x, 2.28, pos.z + 1.01), Vector3(2.12, 0.18, 0.16), C_METAL_DARK,
                 roughness=0.48, metallic=0.82)
    draw_pbr_box(Vector3(pos.x, 2.38, pos.z + 1.06), Vector3(1.88, 0.045, 0.11), C_METAL_EDGE,
                 roughness=0.34, metallic=0.90)
    for side in (-1, 1):
        px = pos.x + side*1.27
        draw_pbr_cylinder(Vector3(px, 1.82, pos.z + 1.16), 0.065, 1.24, C_STEEL,
                          roughness=0.36, metallic=0.88)
        draw_pbr_cylinder(Vector3(px, 2.40, pos.z + 1.16), 0.085, 0.17, C_CHROME,
                          roughness=0.22, metallic=0.94)
        for yy in (1.30, 1.75, 2.20):
            draw_pbr_box(Vector3(px, yy, pos.z + 1.21), Vector3(0.19, 0.055, 0.06), C_METAL_DARK,
                         roughness=0.48, metallic=0.78)
    # Reinforced lower cross-member and base fasteners visible from behind.
    draw_pbr_box(Vector3(pos.x, 0.26, pos.z + 1.15), Vector3(3.72, 0.18, 0.18), C_STEEL,
                 roughness=0.44, metallic=0.86)
    for xoff in (-1.62, -0.98, -0.33, 0.33, 0.98, 1.62):
        draw_pbr_sphere(Vector3(pos.x + xoff, 0.28, pos.z + 1.255), 0.032, C_CHROME,
                        roughness=0.18, metallic=0.95)



def _draw_electricity_room_generator_detail_overlay_v10(pos, time_val=0.0):
    """Additional static generator service details layered onto the v38 model."""
    pulse = 0.72 + 0.16 * math.sin(time_val * 3.1)
    # Accessible-side service module, mounted on the outer X face of the generator.
    side_x = pos.x + 3.075
    if _is_3d_primitive_visible(Vector3(side_x, 1.18, pos.z - 0.20), 1.0):
        draw_pbr_box(Vector3(side_x, 1.18, pos.z - 0.20),
                     Vector3(0.065, 0.72, 0.88), C_METAL_DARK,
                     roughness=0.48, metallic=0.82)
        draw_pbr_box(Vector3(side_x + 0.035, 1.18, pos.z - 0.20),
                     Vector3(0.025, 0.62, 0.76), C_METAL_MID,
                     roughness=0.52, metallic=0.72)
        # Small inset maintenance label bars (visual lettering surrogate).
        draw_pbr_box(Vector3(side_x + 0.052, 1.42, pos.z - 0.20),
                     Vector3(0.018, 0.045, 0.48), C_WARNING,
                     roughness=0.65, metallic=0.22)
        for i, col in enumerate((C_RED_DIM, C_WARNING, C_CYAN, C_GREEN_DIM)):
            yy = 1.23 - i * 0.145
            draw_pbr_sphere(Vector3(side_x + 0.065, yy, pos.z - 0.20), 0.043, col,
                            roughness=0.22, metallic=0.35,
                            emissive=Vector3(col.r / 255.0 * 0.10 * pulse,
                                             col.g / 255.0 * 0.10 * pulse,
                                             col.b / 255.0 * 0.10 * pulse))
        for zoff in (-0.49, 0.09):
            for yy in (0.94, 1.40):
                draw_pbr_cylinder(Vector3(side_x + 0.067, yy, pos.z + zoff),
                                  0.022, 0.025, C_CHROME,
                                  roughness=0.18, metallic=0.94)
    # Two small service clamps around the upper manifold/pipe feeds.
    for xoff in (-0.48, 0.48):
        draw_pbr_box(Vector3(pos.x + xoff, 2.42, pos.z + 1.02),
                     Vector3(0.13, 0.08, 0.20), C_METAL_EDGE,
                     roughness=0.38, metallic=0.88)
        draw_pbr_cylinder(Vector3(pos.x + xoff, 2.46, pos.z + 1.08),
                          0.027, 0.035, C_CHROME,
                          roughness=0.18, metallic=0.95)


def _draw_electricity_room_ceiling_generator_wiring_v38(time_val=0.0, cam=None):
    """Electricity Room ceiling, generator and cable dressing from v38.

    All coordinates are in the source wing's local space. The caller applies the
    existing +5.8 X placement transform, so this remains part of the Main Lab's
    one shared renderer. The induction/thermal flags and staged startup animate
    the existing visuals without adding a separate loop or scene.
    """
    _recovering_lights = bool(generator_igniting and generator_startup_stage == "lights_flicker")
    _light_recovery = (max(0.0, min(1.0, generator_light_recovery_intensity))
                       if _recovering_lights else (1.0 if generator_powered else 0.0))
    _cable_recovery = (max(0.0, min(1.0, generator_cable_progress))
                       if generator_igniting and generator_startup_stage in ("cable_rise", "lights_flicker")
                       else (1.0 if generator_powered else 0.0))
    # Ceiling cable trays and supports. These sit below the existing ceiling cap.
    for tray_z in (-6.65, 5.85):
        tray_center = Vector3(30.5, 6.28, tray_z)
        if _is_3d_primitive_visible(tray_center, 9.2):
            draw_pbr_box(tray_center, Vector3(15.4, 0.16, 0.34), C_METAL_DARK,
                         roughness=0.52, metallic=0.72)
            draw_pbr_box(Vector3(30.5, 6.37, tray_z), Vector3(15.0, 0.045, 0.26),
                         C_METAL_EDGE, roughness=0.45, metallic=0.75)
            for px in (23.0, 27.0, 31.0, 35.0, 38.0):
                draw_pbr_box(Vector3(px, 6.39, tray_z), Vector3(0.10, 0.22, 0.48),
                             C_METAL_MID, roughness=0.48, metallic=0.68)
            for px in (24.0, 28.0, 32.0, 36.0):
                draw_pbr_box(Vector3(px, 6.03, tray_z), Vector3(0.12, 0.48, 0.12),
                             C_STEEL, roughness=0.42, metallic=0.82)

    # Small ceiling junction boxes mounted at the tray intersections.
    for pos in (Vector3(18.5, 6.40, -6.65),
                Vector3(27.0, 6.40, -6.65),
                Vector3(35.0, 6.40, 5.85),
                Vector3(31.0, 6.40, 5.85)):
        if _is_3d_primitive_visible(pos, 0.75):
            draw_pbr_box(pos, Vector3(0.72, 0.30, 0.58), C_METAL_DARK,
                         roughness=0.58, metallic=0.72)
            draw_pbr_box(Vector3(pos.x, pos.y + 0.16, pos.z),
                         Vector3(0.42, 0.035, 0.36), C_WARNING,
                         roughness=0.62, metallic=0.36)
            for dx in (-0.20, 0.20):
                draw_pbr_cylinder(Vector3(pos.x + dx, pos.y - 0.17, pos.z),
                                  0.025, 0.035, C_CHROME,
                                  roughness=0.22, metallic=0.90)

    # Damaged/repaired ceiling inspection plates, flush with the cap.
    for pos, size in (
        (Vector3(17.0, 6.62, 1.7), Vector3(2.8, 0.035, 0.75)),
        (Vector3(38.0, 6.62, -4.0), Vector3(2.2, 0.035, 0.65)),
        (Vector3(29.0, 6.62, 1.0), Vector3(1.6, 0.035, 0.52)),
    ):
        if _is_3d_primitive_visible(pos, 1.7):
            draw_pbr_box(pos, size, C_METAL_MID, roughness=0.82, metallic=0.25)
            draw_pbr_box(Vector3(pos.x + 0.42, pos.y + 0.022, pos.z),
                         Vector3(0.62, 0.012, 0.06), C_RUST2,
                         roughness=0.92, metallic=0.18)

    # Source-v38 overhead steel pipes and cross-wall conduit runs.
    pipe_specs = (
        (Vector3(24.0, 6.48, -7.35), 13.0, 0.105, 'x', C_STEEL),
        (Vector3(29.0, 6.34, -5.85), 10.0, 0.085, 'x', C_METAL_MID),
        (Vector3(33.5, 6.50, 5.65), 9.0, 0.095, 'x', C_STEEL),
        (Vector3(21.0, 6.30, 4.95), 7.0, 0.075, 'x', C_METAL_MID),
        (Vector3(37.0, 6.38, -1.0), 6.0, 0.080, 'z', C_STEEL),
    )
    for pipe_pos, pipe_len, pipe_rad, pipe_axis, pipe_col in pipe_specs:
        if _is_3d_primitive_visible(pipe_pos, pipe_len * 0.62 + 0.8):
            _draw_electricity_room_pipe_axis_v38(pipe_pos, pipe_len, pipe_rad, pipe_col,
                                                  axis=pipe_axis, roughness=0.45, metallic=0.82)
            # Two end collars keep each section looking mechanically joined.
            for side in (-1.0, 1.0):
                if pipe_axis == 'x':
                    collar_pos = Vector3(pipe_pos.x + side * pipe_len * 0.46, pipe_pos.y, pipe_pos.z)
                else:
                    collar_pos = Vector3(pipe_pos.x, pipe_pos.y, pipe_pos.z + side * pipe_len * 0.46)
                draw_pbr_torus(collar_pos, pipe_rad * 1.14, 0.018, C_METAL_DARK,
                               roughness=0.48, metallic=0.78)

    # Short hanging brackets tie the large pipe runs to the ceiling.
    for x, z, py in ((18.5, -7.35, 6.48), (24.0, -7.35, 6.48),
                     (29.5, -7.35, 6.48), (25.0, -5.85, 6.34),
                     (30.0, -5.85, 6.34), (33.0, 5.65, 6.50),
                     (37.0, -3.5, 6.38), (37.0, 1.0, 6.38)):
        hanger_center = Vector3(x, 6.62, z)
        if _is_3d_primitive_visible(hanger_center, 0.65):
            draw_pbr_box(Vector3(x, 6.70, z), Vector3(0.12, 0.20, 0.12),
                         C_METAL_DARK, roughness=0.55, metallic=0.78)
            draw_pbr_box(Vector3(x, (6.70 + py) / 2.0, z),
                         Vector3(0.055, max(0.06, 6.70 - py), 0.055),
                         C_STEEL, roughness=0.55, metallic=0.78)

    # Four recessed ceiling-panel fluorescent fixtures copied from the standalone v38 layout.
    ceiling_lights = (
        (Vector3(20.5, 6.68, 7.8), 0.25),
        (Vector3(33.0, 6.68, -8.4), 1.15),
        (Vector3(22.5, 6.68, -10.0), 2.10),
        (Vector3(31.0, 6.68, 8.7), 2.80),
    )
    for light_pos, phase in ceiling_lights:
        if _is_3d_primitive_visible(light_pos, 1.8):
            flicker = 0.72 + 0.10 * math.sin(time_val * 4.2 + phase)
            if _recovering_lights:
                # A brief irregular pulse rides on the gradual recovery curve.
                flicker *= 0.68 + 0.32 * abs(math.sin(time_val * 17.0 + phase))
            _draw_electricity_room_ceiling_panel_light_v38(
                light_pos, flicker_val=flicker, time_val=time_val,
                is_powered=generator_powered,
                recovery_intensity=_light_recovery, phase=phase)

    # The Electricity Room uses the four flush ceiling-panel fluorescent fixtures above.
    # The three additional suspended tubes from the older pass were removed because they
    # appeared non-horizontal and caused stray bright bars as the camera turned.

    # A compact high-voltage manifold is fixed immediately below the ceiling over the generator.
    # The ceiling risers connect to it; no startup animation or puzzle state is attached yet.
    manifold = Vector3(30.5, 6.64, -2.5)
    if _is_3d_primitive_visible(manifold, 1.65):
        draw_pbr_box(manifold, Vector3(1.62, 0.34, 1.40), C_METAL_DARK,
                     roughness=0.42, metallic=0.82)
        draw_pbr_box(Vector3(30.5, 6.45, -2.5), Vector3(1.28, 0.045, 1.08),
                     C_METAL_MID, roughness=0.36, metallic=0.82)
        for offset in (-0.42, -0.14, 0.14, 0.42):
            draw_pbr_box(Vector3(30.5 + offset, 6.41, -2.5),
                         Vector3(0.07, 0.035, 0.72), C_WARNING,
                         roughness=0.58, metallic=0.25)

    # Generator: source v38's detailed static model, placed at the same local coordinate.
    # Keep this visual-only for now: no inserted tube, no startup, no interactions.
    generator_pos = Vector3(30.5, 0.0, -2.5)
    if _is_3d_primitive_visible(Vector3(generator_pos.x, 1.40, generator_pos.z), 4.35):
        _draw_electricity_room_generator_visual_v38(
            generator_pos, time_val=time_val,
            auxiliary_tube_installed=auxiliary_tube_installed,
            thermal_module_installed=thermal_module_complete,
            powered=generator_powered, igniting=generator_igniting,
            induction_aligned=induction_alignment_complete)
        _draw_electricity_room_generator_detail_overlay_v10(generator_pos, time_val=time_val)

    # Floor routes: 4 insulated conductors from each wall panel to the generator.
    # They sit just above the concrete and use subdued colours until puzzle logic is added.
    wire_cols = (
        Color(150, 48, 44, 255), Color(46, 99, 166, 255),
        Color(162, 126, 34, 255), Color(38, 132, 78, 255),
    )
    lane_offsets = (-0.48, -0.16, 0.16, 0.48)

    def draw_wire_path(points, color, radius=0.027, metallic=0.22):
        for a, b in zip(points[:-1], points[1:]):
            _draw_electricity_room_wire_segment_v38(a, b, radius, color,
                                                     roughness=0.56, metallic=metallic)
        # Small metal retaining clips along long floor runs.
        if len(points) >= 4:
            for clip_pt in (points[2], points[-2]):
                draw_pbr_box(Vector3(clip_pt.x, clip_pt.y + 0.028, clip_pt.z),
                             Vector3(0.12, 0.045, 0.11), C_METAL_EDGE,
                             roughness=0.42, metallic=0.82)

    # North console A → north edge of the generator's front service face.
    if _is_3d_primitive_visible(Vector3(25.6, 0.45, -7.9), 8.8):
        for lane, color in zip(lane_offsets, wire_cols):
            x0 = 21.0 + lane
            x1 = 30.0 + lane
            draw_wire_path((Vector3(x0, 1.12, -11.76), Vector3(x0, 0.065, -11.76),
                            Vector3(x1, 0.065, -11.76), Vector3(x1, 0.065, -3.91),
                            Vector3(30.0 + lane, 0.43, -3.91)), color)

    # South console B → rear/south service edge of the generator.
    if _is_3d_primitive_visible(Vector3(30.0, 0.45, 5.4), 8.7):
        for lane, color in zip(lane_offsets, wire_cols):
            x0 = 25.5 + lane
            x1 = 31.45 + lane
            draw_wire_path((Vector3(x0, 1.12, 11.76), Vector3(x0, 0.065, 11.76),
                            Vector3(x1, 0.065, 11.76), Vector3(x1, 0.065, -1.30),
                            Vector3(x1, 0.43, -1.30)), color)

    # East console C → east-side generator service glands.
    if _is_3d_primitive_visible(Vector3(35.2, 0.45, -0.1), 6.7):
        for lane, color in zip(lane_offsets, wire_cols):
            z0 = 2.5 + lane
            z1 = -2.5 + lane
            draw_wire_path((Vector3(37.72, 1.12, z0), Vector3(37.72, 0.065, z0),
                            Vector3(37.72, 0.065, z1), Vector3(32.30, 0.065, z1),
                            Vector3(32.15, 0.43, z1)), color)

    # Four riser conductors emerge from the top of the generator and disappear into the ceiling
    # manifold. The upper branches then run along the overhead tray; they do not cross the door.
    if _is_3d_primitive_visible(Vector3(30.5, 4.15, -2.5), 4.8):
        for (ox, oz), color in zip(((-0.16, -0.16), (0.16, -0.16),
                                    (-0.16, 0.16), (0.16, 0.16)), wire_cols):
            riser_x, riser_z = 30.5 + ox, -2.5 + oz
            draw_wire_path((Vector3(riser_x, 2.52, riser_z),
                            Vector3(riser_x, 6.48, riser_z),
                            Vector3(riser_x, 6.48, -6.48)), color, radius=0.032, metallic=0.25)
            draw_wire_path((Vector3(riser_x, 6.48, -6.48),
                            Vector3(27.0 + ox, 6.48, -6.48)), color, radius=0.022, metallic=0.20)
            if _cable_recovery > 0.001:
                _glow_end_y = 2.52 + (6.48 - 2.52) * _cable_recovery
                _pulse = 0.78 + 0.22 * abs(math.sin(time_val * 23.0 + riser_x))
                _emissive = Vector3(0.015*_pulse, 0.48*_pulse, 0.78*_pulse)
                _draw_electricity_room_wire_segment_v38(
                    Vector3(riser_x, 2.52, riser_z),
                    Vector3(riser_x, _glow_end_y, riser_z),
                    0.045, C_CYAN, roughness=0.30, metallic=0.20,
                    emissive=Vector3(_emissive.x*_cable_recovery,
                                     _emissive.y*_cable_recovery,
                                     _emissive.z*_cable_recovery))

    # Wall-to-ceiling service leads above each panel connect the panels visually to the trays.
    # These are fixed cables only; no old cable-routing minigame has been copied.
    service_colours = (Color(98, 36, 32, 255), Color(39, 78, 126, 255), Color(112, 88, 29, 255))
    if _is_3d_primitive_visible(Vector3(22.5, 4.9, -10.2), 5.3):
        for offset, col in zip((-0.36, 0.0, 0.36), service_colours):
            draw_wire_path((Vector3(21.0 + offset, 3.47, -11.76),
                            Vector3(21.0 + offset, 6.48, -11.76),
                            Vector3(21.0 + offset, 6.48, -6.65),
                            Vector3(29.0 + offset, 6.48, -6.65)), col, radius=0.022, metallic=0.16)
    if _is_3d_primitive_visible(Vector3(29.5, 4.9, 9.1), 5.2):
        for offset, col in zip((-0.36, 0.0, 0.36), service_colours):
            draw_wire_path((Vector3(25.5 + offset, 3.47, 11.76),
                            Vector3(25.5 + offset, 6.48, 11.76),
                            Vector3(25.5 + offset, 6.48, 5.85),
                            Vector3(31.0 + offset, 6.48, 5.85)), col, radius=0.022, metallic=0.16)
    if _is_3d_primitive_visible(Vector3(36.0, 4.8, 2.5), 4.9):
        for offset, col in zip((-0.36, 0.0, 0.36), service_colours):
            z = 2.5 + offset
            draw_wire_path((Vector3(37.72, 3.47, z),
                            Vector3(37.72, 6.48, z),
                            Vector3(33.0, 6.48, z),
                            Vector3(33.0, 6.48, 5.85),
                            Vector3(31.0 + offset, 6.48, 5.85)), col, radius=0.022, metallic=0.16)

    # Two intentionally slack, disconnected ceiling drops add the abandoned-service look.
    loose_wire_paths = (
        (Vector3(28.0, 6.48, -8.2), Vector3(28.12, 5.95, -8.12),
         Vector3(27.86, 5.16, -7.98), Vector3(27.94, 4.78, -8.04)),
        (Vector3(34.5, 6.48, 7.6), Vector3(34.38, 5.95, 7.50),
         Vector3(34.64, 5.12, 7.36), Vector3(34.54, 4.78, 7.44)),
    )
    for path in loose_wire_paths:
        if _is_3d_primitive_visible(path[0], 2.5):
            draw_pbr_cylinder(path[0], 0.047, 0.08, C_METAL_MID,
                              roughness=0.48, metallic=0.76)
            for a, b in zip(path[:-1], path[1:]):
                _draw_electricity_room_wire_segment_v38(a, b, 0.022, C_RUBBER,
                                                         roughness=0.78, metallic=0.08)
            draw_pbr_cylinder(path[-1], 0.031, 0.055, C_METAL_DARK,
                              roughness=0.55, metallic=0.55)


def _draw_electricity_room_induction_shelf_visual_v38(pos, time_val=0.0):
    """A new maintenance rack with varied abandoned stock and an emptyable tube cradle."""
    width = 4.25
    depth = 0.86
    # Industrial frame, back rails, and reinforced feet.
    for xoff in (-width/2 + 0.09, width/2 - 0.09):
        for zoff in (-0.34, 0.34):
            draw_pbr_box(Vector3(pos.x+xoff, 1.68, pos.z+zoff), Vector3(0.11, 3.34, 0.11), C_RUST2,
                         roughness=0.86, metallic=0.55)
            draw_pbr_box(Vector3(pos.x+xoff, 0.12, pos.z+zoff), Vector3(0.25, 0.20, 0.25), C_METAL_DARK,
                         roughness=0.56, metallic=0.76)
    shelf_cols = (C_METAL_DARK, C_RUST2, C_STEEL, C_METAL_MID)
    for level, y in enumerate((0.35, 1.25, 2.15, 3.05)):
        draw_pbr_box(Vector3(pos.x, y, pos.z), Vector3(width, 0.13, depth), shelf_cols[level],
                     roughness=0.76, metallic=0.62)
        # Front shelf lips and little bolts.
        draw_pbr_box(Vector3(pos.x, y+0.065, pos.z-depth/2+0.015), Vector3(width-0.18, 0.07, 0.035), C_METAL_EDGE,
                     roughness=0.36, metallic=0.85)
        for xoff in (-1.8, -0.9, 0.0, 0.9, 1.8):
            draw_pbr_cylinder(Vector3(pos.x+xoff, y+0.069, pos.z-depth/2-0.008), 0.022, 0.025, C_CHROME,
                              roughness=0.2, metallic=0.92)
    for xoff in (-1.45, 1.45):
        draw_pbr_box(Vector3(pos.x+xoff, 1.7, pos.z-0.41), Vector3(0.08, 3.0, 0.06), C_METAL_DARK,
                     roughness=0.6, metallic=0.72)
    # Two back braces add depth without filling the rack's opening.
    for xoff in (-1.75, 1.75):
        rl_push_matrix()
        rl_translatef(pos.x+xoff, 1.7, pos.z+0.37)
        rl_rotatef(14.0 if xoff < 0 else -14.0, 0, 0, 1)
        draw_pbr_box(Vector3(0, 0, 0), Vector3(0.07, 3.0, 0.07), C_RUST,
                     roughness=0.84, metallic=0.38)
        rl_pop_matrix()

    # Bottom bay: crushed shipping case, cable rings, and a few fallen connectors.
    draw_pbr_box(Vector3(pos.x-1.34, 0.62, pos.z-0.02), Vector3(0.92, 0.45, 0.55), C_METAL_DARK,
                 roughness=0.9, metallic=0.35)
    draw_pbr_box(Vector3(pos.x-1.34, 0.86, pos.z-0.02), Vector3(0.84, 0.035, 0.50), C_RUST2,
                 roughness=0.92, metallic=0.28)
    for n in range(3):
        draw_pbr_torus(Vector3(pos.x+0.35+n*0.22, 0.57, pos.z+0.01), 0.17, 0.035,
                       C_RUST if n % 2 == 0 else C_BRASS, roughness=0.76, metallic=0.52)
    for n in range(4):
        draw_pbr_cylinder(Vector3(pos.x+1.12+n*0.12, 0.51, pos.z-0.08), 0.035, 0.24,
                          C_CHROME if n % 2 else C_RUST2, roughness=0.44, metallic=0.82)

    # Second shelf: capped chemical jars, a labelled parts tin, and broken insulator stock.
    for xoff, color, jar_emissive in ((-1.47, C_CHAMBER_GLASS, None),
                                      (-1.10, C_GREEN_DIM, Vector3(0.01, 0.09, 0.06)),
                                      (1.42, C_RUST2, None)):
        draw_pbr_cylinder(Vector3(pos.x+xoff, 1.48, pos.z+0.02), 0.095, 0.35, color,
                          roughness=0.32, metallic=0.16, emissive=jar_emissive)
        draw_pbr_cylinder(Vector3(pos.x+xoff, 1.66, pos.z+0.02), 0.105, 0.055, C_METAL_DARK,
                          roughness=0.52, metallic=0.5)
    draw_pbr_box(Vector3(pos.x-0.30, 1.52, pos.z+0.02), Vector3(0.78, 0.43, 0.54), C_METAL_MID,
                 roughness=0.82, metallic=0.42)
    draw_pbr_box(Vector3(pos.x-0.30, 1.57, pos.z-0.265), Vector3(0.46, 0.16, 0.025), C_WARNING,
                 roughness=0.7, metallic=0.22)
    draw_pbr_box(Vector3(pos.x+0.52, 1.43, pos.z+0.10), Vector3(0.38, 0.10, 0.22), C_RUBBER,
                 roughness=0.92, metallic=0.04)

    # Main findable shelf: auxiliary induction tube is kept clear of surrounding clutter.
    # Soft cyan indicator makes the unique part readable in the dark, not a giant waypoint beacon.
    draw_pbr_box(Vector3(pos.x-0.48, 2.275, pos.z-0.15), Vector3(0.82, 0.035, 0.31), C_METAL_DARK,
                 roughness=0.52, metallic=0.8)
    draw_pbr_box(Vector3(pos.x-0.48, 2.298, pos.z-0.15), Vector3(0.72, 0.012, 0.22), C_METAL_MID,
                 roughness=0.58, metallic=0.6)
    draw_pbr_box(Vector3(pos.x-0.48, 2.322, pos.z-0.15), Vector3(0.46, 0.018, 0.055), C_WARNING,
                 roughness=0.65, metallic=0.2)
    # Static-only stage: leave the indicator unlit. No pickup marker or puzzle state.
    draw_pbr_sphere(Vector3(pos.x-0.10, 2.36, pos.z-0.18), 0.025, C_METAL_DARK,
                    roughness=0.15, metallic=0.0, emissive=Vector3(0.001, 0.001, 0.001))
    # Nearby miscellaneous parts: two ceramic bushings, a battered case, and a loose terminal block.
    draw_pbr_cylinder(Vector3(pos.x+1.48, 2.34, pos.z+0.07), 0.075, 0.22, C_PAPER,
                      roughness=0.72, metallic=0.1)
    draw_pbr_cylinder(Vector3(pos.x+1.48, 2.45, pos.z+0.07), 0.08, 0.045, C_CHROME,
                      roughness=0.24, metallic=0.9)
    draw_pbr_box(Vector3(pos.x+0.88, 2.34, pos.z+0.03), Vector3(0.48, 0.28, 0.50), C_RUST2,
                 roughness=0.9, metallic=0.42)
    draw_pbr_box(Vector3(pos.x+0.88, 2.49, pos.z+0.03), Vector3(0.40, 0.025, 0.43), C_METAL_DARK,
                 roughness=0.82, metallic=0.5)

    # Top shelf: battered electrical stock and an open organiser filled with odd components.
    draw_pbr_box(Vector3(pos.x-1.32, 3.29, pos.z), Vector3(0.82, 0.34, 0.55), C_RUST2,
                 roughness=0.9, metallic=0.35)
    draw_pbr_box(Vector3(pos.x-1.32, 3.47, pos.z), Vector3(0.84, 0.035, 0.57), C_METAL_MID,
                 roughness=0.8, metallic=0.44)
    draw_pbr_box(Vector3(pos.x+0.12, 3.27, pos.z+0.05), Vector3(0.76, 0.32, 0.58), C_METAL_DARK,
                 roughness=0.72, metallic=0.58)
    for n in range(5):
        draw_pbr_cylinder(Vector3(pos.x-0.17+n*0.14, 3.47, pos.z+0.04), 0.035, 0.15,
                          (C_CHROME, C_BRASS, C_RUST, C_CYAN, C_CHROME)[n],
                          roughness=0.42, metallic=0.72)
    # Faded inventory tab on the outer upright.
    draw_pbr_box(Vector3(pos.x+2.02, 2.66, pos.z-0.43), Vector3(0.22, 0.28, 0.025), C_WARNING,
                 roughness=0.78, metallic=0.12)
    draw_pbr_box(Vector3(pos.x+2.02, 2.66, pos.z-0.447), Vector3(0.14, 0.035, 0.012), C_METAL_DARK,
                 roughness=0.9, metallic=0.1)

