        draw_pbr_box(Vector3(mx, pos.y + 0.47, pos.z - 0.233), Vector3(0.29, 0.21, 0.02),
                     Color(30, 42, 39, 255), roughness=0.28, metallic=0.28,
                     emissive=Vector3(0.015, 0.035, 0.028))
