def draw_electricity_room_source_environment_details(time_val=0.0, cam=None, power_restored=False):
    """Draw the v38 Electricity Room environment inside the shared world.

    The standalone wing is shifted +5.8 on X. Panel interactions, the auxiliary tube and
    the integrated generator recovery sequence are controlled by the shared game loop.
    """
    # If the player is still on the Main Lab side of the threshold, only submit the
    # Electricity Room's many small details while looking generally toward its doorway.
    # Once inside the wing, per-primitive culling handles view direction and distance.
    if cam is not None and float(cam.position.x) < ELECTRICITY_ROOM_WEST_X:
        to_x = 18.2 - float(cam.position.x)
        to_z = -2.0 - float(cam.position.z)
        fwd_x = float(cam.target.x - cam.position.x)
        fwd_z = float(cam.target.z - cam.position.z)
        to_len = math.sqrt(to_x*to_x + to_z*to_z)
        fwd_len = math.sqrt(fwd_x*fwd_x + fwd_z*fwd_z)
        if to_len > 1e-6 and fwd_len > 1e-6:
            if (fwd_x*to_x + fwd_z*to_z) / (to_len*fwd_len) < 0.18:
                return

    room_center = Vector3(ELECTRICITY_ROOM_CENTER_X, 3.2, 0.0)
    # Coarse room-level visibility gate avoids running hundreds of detail calls when the
    # Electricity Room is completely behind/outside the camera view. Per-primitive culling
    # remains active within the source helpers.
    if not _is_3d_primitive_visible(room_center, 19.2):
        return

    rl_push_matrix()
    rl_translatef(5.8, 0.0, 0.0)
    try:
        # Original standalone wall seams, panel breaks, and segmented safety bands.
        draw_electricity_room_source_wall_panels()

        # Grime, conduit offcuts, floor debris, wall stains, maintenance banners, the wall
        # tool rack, service board, loose tools/paper, and floor workbench from standalone v38.
        _draw_electricity_room_floor_detail_source()
        _draw_electricity_room_wall_floor_details_source()

        # Static, non-puzzle storage and floor-standing equipment from standalone v38.
        if _is_3d_primitive_visible(Vector3(17.0, 1.65, -10.8), 2.8):
            draw_electricity_room_static_shelving(Vector3(17.0, 0.0, -10.8), "x", 0)
        if _is_3d_primitive_visible(Vector3(14.2, 1.65, 5.6), 2.8):
            draw_electricity_room_static_shelving(Vector3(14.2, 0.0, 5.6), "z", 1)
        if _is_3d_primitive_visible(Vector3(14.8, 1.65, 10.8), 2.8):
            draw_electricity_room_static_shelving(Vector3(14.8, 0.0, 10.8), "x", 2)
        # Standalone-v38 induction maintenance rack with richer stock and cradle details.
        # It is static-only: no auxiliary tube item, pickup marker, or puzzle state exists yet.
        if _is_3d_primitive_visible(Vector3(28.4, 1.65, -10.65), 3.2):
            _draw_electricity_room_induction_shelf_visual_v38(Vector3(28.4, 0.0, -10.65), time_val)
        # The collectible is part of the real room and disappears from the cradle after pickup.
        if (auxiliary_tube_item is not None and not auxiliary_tube_item.picked_up
                and not (is_holding_3d_item and current_3d_item_obj is auxiliary_tube_item)
                and _is_3d_primitive_visible(Vector3(27.92, 2.34, -10.48), 0.9)):
            _draw_electricity_room_auxiliary_tube_visual_v38(
                Vector3(27.92, 2.34, -10.48), auxiliary_tube_item.rot)
        if _is_3d_primitive_visible(Vector3(35.0, 1.65, 10.45), 2.4):
            draw_electricity_room_static_storage_cabinet(Vector3(35.0, 0.0, 10.45), time_val)
        if _is_3d_primitive_visible(Vector3(35.0, 1.6, -8.5), 2.7):
            _draw_electricity_room_static_utility_cabinet(time_val, power_restored)

        # --------------------------------------------------------
        # STATIC WORK TABLES from the standalone Electricity Room v38.
        # These are visuals only; the matching collision solids were already
        # positioned in the shared-world build. No generator is rendered here.
        # --------------------------------------------------------
        if _is_3d_primitive_visible(Vector3(20.8, 0.72, -8.5), 3.4):
            draw_lab_table(Vector3(20.8, 0.0, -8.5),
                           Vector3(4.4, 1.45, 1.8), damaged=True)
        if _is_3d_primitive_visible(Vector3(30.5, 0.72, 7.0), 3.8):
            draw_lab_table(Vector3(30.5, 0.0, 7.0),
                           Vector3(5.2, 1.45, 1.8), damaged=True)

        # --------------------------------------------------------
        # THREE WALL-MOUNTED CONTROL-PANEL ENCLOSURES from v38.
        # Appearance only for now: do not add the old cable-routing puzzle,
        # wire animations, generator cables, or generator model in this stage.
        # The source's local coordinates are transformed by the same +5.8 X
        # offset as the shelves and wall dressing, matching existing colliders.
        # --------------------------------------------------------
        panel_specs = (
            (Vector3(21.0, 2.25, -12.05), "north", 2.1),
            (Vector3(25.5, 2.25, 12.05), "south", 2.1),
            (Vector3(38.05, 2.25, 2.5), "east", 2.1),
        )
        for panel_pos, panel_wall, panel_radius in panel_specs:
            if _is_3d_primitive_visible(panel_pos, panel_radius):
                draw_cable_control_panel(panel_pos, panel_wall, time_val)

        # Separate south-wall breaker bank from standalone v38. Purely visual; it is not interactive.
        breaker_pos = Vector3(31.5, 2.25, 12.15)
        if _is_3d_primitive_visible(breaker_pos, 1.65):
            _draw_electricity_room_breaker_panel_visual_v38(breaker_pos)

        # Wall-mounted ventilation fan, loose hanging bulbs, and subtle surface wear.
        # These small groups use bounding visibility tests so they do not add work when unseen.
        _draw_electricity_room_ventilation_fan_visual_v38(time_val, cam)
        _draw_electricity_room_hanging_bulbs_visual_v38(time_val, power_restored, cam)
        _draw_electricity_room_surface_wear_detail_v8(cam)

        # Existing source-v38 generator visuals, panel-to-generator cables, ceiling risers,
        # overhead pipework, and fixtures. All remain static visual props, with no new minigames.
        _draw_electricity_room_ceiling_generator_wiring_v38(time_val, cam)

        # Source floor pools and the single east-corner wall vine cluster.
        _draw_electricity_room_floor_puddle(Vector3(17.0, 0.0, -7.1), Vector2(3.8, 2.4))
        _draw_electricity_room_floor_puddle(Vector3(33.2, 0.0, 9.1), Vector2(3.4, 2.0))
        if _is_3d_primitive_visible(Vector3(38.0, 1.9, -10.4), 3.2):
            _draw_electricity_room_mold_vines(Vector3(38.0, 0.0, -10.4), height=3.8)
    finally:
        rl_pop_matrix()


def draw_electricity_room_shell(time_val=0.0, cam=None, power_restored=False):
    """Draw the Electricity Room shell and detailed environment in the shared world.

    All geometry uses the Main Lab's PBR renderer; gameplay is handled by its shared loop.
    """
    cx = ELECTRICITY_ROOM_CENTER_X
    half_length = 13.0
    # Match the Main Lab floor slab and ceiling elevation; overlap the existing floor by 0.2
    # units so a seam cannot appear at the doorway threshold.
    draw_pbr_box(Vector3(cx, -0.12, 0.0), Vector3(26.4, 0.24, 26.0),
                 C_CONCRETE, roughness=0.86, metallic=0.08)

    # Floor joints continue the Main Lab's 3-unit grid into the new room wing.
    for tile_x in range(21, 44, 3):
        draw_pbr_box(Vector3(float(tile_x), 0.012, 0.0), Vector3(0.025, 0.016, 25.55),
                     C_TILE_LINE, roughness=0.95, metallic=0.0)
    for tile_z in range(-12, 13, 3):
        draw_pbr_box(Vector3(cx, 0.013, float(tile_z)), Vector3(25.8, 0.016, 0.025),
                     C_TILE_LINE, roughness=0.95, metallic=0.0)

    # Flat structural ceiling, aligned with the Main Lab cap at Y=6.95.
    draw_pbr_box(Vector3(cx, 6.95, 0.0), Vector3(26.4, 0.20, 26.0),
                 C_CEILING, roughness=0.92, metallic=0.04)

    # Three continuous room walls. The WEST side is intentionally not filled: the existing
    # Main Lab east-wall opening and sliding door are the only connection/entry to this wing.
    draw_pbr_box(Vector3(cx, 3.5, -ELECTRICITY_ROOM_WALL_Z), Vector3(26.0, 7.0, 0.8),
                 C_WALL, roughness=0.88, metallic=0.0)
    draw_pbr_box(Vector3(cx, 3.5, ELECTRICITY_ROOM_WALL_Z), Vector3(26.0, 7.0, 0.8),
                 C_WALL, roughness=0.88, metallic=0.0)
    draw_pbr_box(Vector3(ELECTRICITY_ROOM_EAST_WALL_CENTER_X, 3.5, 0.0), Vector3(0.8, 7.0, 26.0),
                 C_WALL, roughness=0.88, metallic=0.0)

    # Richer source-v38 modular wall seams and hazard bands are layered later by
    # draw_electricity_room_source_environment_details(); avoid double seams here.

    # Flush dark skirting trims; no sill, raised rectangle or blocking slab is placed across the door.
    draw_pbr_box(Vector3(cx, 0.25, -11.98), Vector3(25.6, 0.50, 0.12),
                 C_WALL_TRIM, roughness=0.55, metallic=0.70)
    draw_pbr_box(Vector3(cx, 0.25, 11.98), Vector3(25.6, 0.50, 0.12),
                 C_WALL_TRIM, roughness=0.55, metallic=0.70)
    draw_pbr_box(Vector3(43.78, 0.25, 0.0), Vector3(0.12, 0.50, 25.6),
                 C_WALL_TRIM, roughness=0.55, metallic=0.70)

    # Four simple ceiling cross-members define the room's length and scale without adding puzzle props.
    for beam_x in (23.8, 29.2, 34.6, 40.0):
        draw_pbr_box(Vector3(beam_x, 6.77, 0.0), Vector3(0.16, 0.14, 25.4),
                     C_BEAM, roughness=0.52, metallic=0.72)

    # Copy the standalone v38 wall/floor dressing into this single shared-world renderer.
    draw_electricity_room_source_environment_details(time_val, cam, power_restored)

    # Navigation is a real in-world beacon, not a HUD arrow. During the tube install, the
    # existing A-01 pickup mesh travels into the generator's left induction cradle.
    draw_electric_objective_waypoint(time_val)
    if electric_tube_mission_state == "tube_insert" and electric_tube_anim_start_position is not None:
        _insert_t = max(0.0, min(1.0, electric_tube_cutscene_elapsed / max(0.001, ELECTRIC_TUBE_INSERT_DURATION)))
        _insert_ease = _insert_t * _insert_t * (3.0 - 2.0 * _insert_t)
        _tube_start = electric_tube_anim_start_position
        _tube_end = electric_tube_anim_end_position
        _tube_x = _tube_start.x + (_tube_end.x - _tube_start.x) * _insert_ease
        _tube_y = _tube_start.y + (_tube_end.y - _tube_start.y) * _insert_ease + math.sin(_insert_t * math.pi) * 0.20
        _tube_z = _tube_start.z + (_tube_end.z - _tube_start.z) * _insert_ease
        _draw_electricity_room_auxiliary_tube_visual_v38(Vector3(_tube_x, _tube_y, _tube_z), Vector3(0.0, 0.0, 0.0))





