    _draw_box(Vector3(9.55, 0.025, -35.34), Vector3(0.26, 0.010, 0.18), C_OBS_PAPER_AGED, roughness=0.96)
    _draw_box(Vector3(9.71, 0.018, -35.29), Vector3(0.14, 0.008, 0.09), Color(190, 184, 166, 255), roughness=0.96)
    _draw_torus(Vector3(-10.05, 0.025, -35.27), 0.17, 0.018, C_OBS_RUBBER, roughness=0.9)
    # A couple of chipped-concrete pieces around the fallen panel.
