# The isolated printer helpers apply WORLD_DRAW_OFFSET_X while its grouped assembly is drawn.
# Keep the same behavior locally in this isolated namespace without shifting the host game's objects.
_OBS_HOST_DRAW_PBR_BOX = draw_pbr_box
_OBS_HOST_DRAW_PBR_BOX_ROTATED = draw_pbr_box_rotated
_OBS_HOST_DRAW_PBR_CYLINDER = draw_pbr_cylinder
_OBS_HOST_DRAW_PBR_SPHERE = draw_pbr_sphere
_OBS_HOST_DRAW_PBR_TORUS = draw_pbr_torus
_OBS_HOST_DRAW_PBR_CONE = draw_pbr_cone

def _obs_offset_pos(pos):
    return Vector3(pos.x + WORLD_DRAW_OFFSET_X, pos.y, pos.z) if WORLD_DRAW_OFFSET_X else pos

def draw_pbr_box(pos, size, color, roughness=0.5, metallic=0.0, emissive=None):
    adjusted_pos = _obs_offset_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(adjusted_pos, 0.5 * math.sqrt(size.x*size.x + size.y*size.y + size.z*size.z)):
        return None
    return _OBS_HOST_DRAW_PBR_BOX(adjusted_pos, size, color, roughness, metallic, emissive)

def draw_pbr_box_rotated(pos, size, color, angle_degrees=0.0, axis=Vector3(0.0, 1.0, 0.0),
                         roughness=0.5, metallic=0.0, emissive=None):
    adjusted_pos = _obs_offset_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(adjusted_pos, 0.5 * math.sqrt(size.x*size.x + size.y*size.y + size.z*size.z)):
        return None
    return _obs_room_detail_rotated_box(adjusted_pos, size, color,
           angle_degrees, axis=axis, roughness=roughness, metallic=metallic, emissive=emissive)

def draw_pbr_cylinder(pos, radius, height, color, roughness=0.5, metallic=0.0, emissive=None, centered=True):
    adjusted_pos = _obs_offset_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(adjusted_pos, max(float(radius), float(height) * 0.5)):
        return None
    return _OBS_HOST_DRAW_PBR_CYLINDER(adjusted_pos, radius, height, color, roughness, metallic, emissive, centered)

def draw_pbr_sphere(pos, radius, color, roughness=0.5, metallic=0.0, emissive=None):
    adjusted_pos = _obs_offset_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(adjusted_pos, float(radius)):
        return None
    return _OBS_HOST_DRAW_PBR_SPHERE(adjusted_pos, radius, color, roughness, metallic, emissive)

def draw_pbr_torus(pos, radius, tube_radius, color, roughness=0.5, metallic=0.0, emissive=None):
    adjusted_pos = _obs_offset_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(adjusted_pos, float(radius + tube_radius)):
        return None
    return _OBS_HOST_DRAW_PBR_TORUS(adjusted_pos, radius, tube_radius, color, roughness, metallic, emissive)

def draw_pbr_cone(pos, radius, height, color, roughness=0.5, metallic=0.0, emissive=None, centered=True):
    adjusted_pos = _obs_offset_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(adjusted_pos, max(float(radius), float(height) * 0.5)):
        return None
    return _OBS_HOST_DRAW_PBR_CONE(adjusted_pos, radius, height, color, roughness, metallic, emissive, centered)

# Render helper absent from the combined host but used by two isolated visual props.
def draw_pbr_ellipsoid(pos, scale, color, angle_degrees=0.0, roughness=0.5, metallic=0.0, emissive=None):
    pos = _obs_offset_pos(pos)
    radius = math.sqrt(scale.x * scale.x + scale.y * scale.y + scale.z * scale.z) * 0.5
    if _obs_rotated_content_hits_preserved_doorway(pos, radius):
        return
    if not _is_3d_primitive_visible(pos, radius):
        return
    set_pbr_material(color, roughness, metallic, emissive)
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    if angle_degrees:
        rl_rotatef(float(angle_degrees), 0.0, 1.0, 0.0)
    rl_scalef(scale.x, scale.y, scale.z)
    draw_model(unit_sphere_model, Vector3(0.0, 0.0, 0.0), 1.0, WHITE)
    rl_pop_matrix()

# Waypoint visuals belong to future interactions; leave them inert in this visual-only pass.
def draw_archive_waypoint_beacon(*args, **kwargs):
    return None


def draw_main_observation_workstation(time_val=0.0, is_powered=False):
    desk_cx = 5.2
    desk_cy = 0.0
    desk_cz = -16.0
    desk_w = 5.20
    desk_d = 1.95
    desk_h = 0.92

    # Structural Heavy Steel Leg Frame
    for lx in (desk_cx - desk_w * 0.46, desk_cx + desk_w * 0.46):
        for lz in (desk_cz - desk_d * 0.44, desk_cz + desk_d * 0.44):
            _draw_box(Vector3(lx, desk_cy + desk_h * 0.48, lz), Vector3(0.085, desk_h * 0.96, 0.085), C_OBS_METAL_DARK, roughness=0.45, metallic=0.8)
            _draw_cylinder(Vector3(lx, desk_cy + 0.02, lz), 0.065, 0.04, C_OBS_CHROME, roughness=0.2, metallic=0.92)
            _draw_box(Vector3(lx, desk_cy + 0.06, lz), Vector3(0.11, 0.02, 0.11), C_OBS_STEEL, roughness=0.3, metallic=0.85)

    # Frame crossbars
    _draw_box(Vector3(desk_cx, desk_cy + 0.18, desk_cz + desk_d * 0.44), Vector3(desk_w * 0.88, 0.05, 0.05), C_OBS_METAL_MID, roughness=0.45, metallic=0.75)
    _draw_box(Vector3(desk_cx, desk_cy + desk_h - 0.08, desk_cz), Vector3(desk_w * 0.88, 0.06, desk_d * 0.85), C_OBS_METAL_DARK, roughness=0.5, metallic=0.7)

    # Dual Modular Drawer Pedestals
    ped_w, ped_h, ped_d = 0.88, 0.70, 1.45
    ped_lx = desk_cx - 1.80
    _draw_box(Vector3(ped_lx, desk_cy + 0.18 + ped_h * 0.5, desk_cz), Vector3(ped_w, ped_h, ped_d), C_OBS_METAL_DARK, roughness=0.5, metallic=0.65)
    for di in range(3):
        dy = desk_cy + 0.22 + di * 0.22
        _draw_box(Vector3(ped_lx, dy + 0.09, desk_cz - ped_d * 0.505), Vector3(ped_w * 0.92, 0.19, 0.02), C_OBS_METAL_MID, roughness=0.45, metallic=0.7)
        _draw_box(Vector3(ped_lx, dy + 0.11, desk_cz - ped_d * 0.525), Vector3(0.24, 0.025, 0.03), C_OBS_CHROME, roughness=0.2, metallic=0.92)
        _draw_box(Vector3(ped_lx, dy + 0.06, desk_cz - ped_d * 0.520), Vector3(0.18, 0.045, 0.01), C_OBS_PAPER, roughness=0.9)

    # Right Pedestal - Middle drawer slightly ajar with color-coded files and keycard
    ped_rx = desk_cx + 1.80
    _draw_box(Vector3(ped_rx, desk_cy + 0.18 + ped_h * 0.5, desk_cz), Vector3(ped_w, ped_h, ped_d), C_OBS_METAL_DARK, roughness=0.5, metallic=0.65)
    for di in range(3):
        dy = desk_cy + 0.22 + di * 0.22
        ajar_z = 0.12 if di == 1 else 0.0
        _draw_box(Vector3(ped_rx, dy + 0.09, desk_cz - ped_d * 0.505 - ajar_z), Vector3(ped_w * 0.92, 0.19, 0.02), C_OBS_METAL_MID, roughness=0.45, metallic=0.7)
        _draw_box(Vector3(ped_rx, dy + 0.11, desk_cz - ped_d * 0.525 - ajar_z), Vector3(0.24, 0.025, 0.03), C_OBS_CHROME, roughness=0.2, metallic=0.92)
        _draw_box(Vector3(ped_rx, dy + 0.06, desk_cz - ped_d * 0.520 - ajar_z), Vector3(0.18, 0.045, 0.01), C_OBS_PAPER, roughness=0.9)
        if di == 1:
            _draw_box(Vector3(ped_rx - 0.22, dy + 0.16, desk_cz - ped_d * 0.505 - 0.06), Vector3(0.24, 0.08, 0.01), C_OBS_FOLDER_MANILA, roughness=0.85)
            _draw_box(Vector3(ped_rx + 0.05, dy + 0.17, desk_cz - ped_d * 0.505 - 0.06), Vector3(0.22, 0.09, 0.01), C_OBS_FOLDER_BLUE, roughness=0.85)
            _draw_box(Vector3(ped_rx + 0.28, dy + 0.16, desk_cz - ped_d * 0.505 - 0.06), Vector3(0.18, 0.07, 0.01), C_OBS_FOLDER_RED, roughness=0.85)
            # Security Level 4 Keycard dangling on yellow lanyard
            _draw_box(Vector3(ped_rx + 0.08, dy + 0.06, desk_cz - ped_d * 0.53 - 0.12), Vector3(0.12, 0.08, 0.005), Color(245, 215, 30, 255), roughness=0.6)
            _draw_box(Vector3(ped_rx + 0.08, dy + 0.08, desk_cz - ped_d * 0.53 - 0.12), Vector3(0.10, 0.02, 0.006), Color(215, 35, 25, 255), roughness=0.4)
            _draw_cylinder(Vector3(ped_rx + 0.08, dy + 0.10, desk_cz - ped_d * 0.53 - 0.06), 0.004, 0.12, Color(20, 20, 20, 255), roughness=0.85)

    # Worn Workstation Desktop Surface
    top_y = desk_cy + desk_h
    _draw_box(Vector3(desk_cx, top_y - 0.03, desk_cz), Vector3(desk_w, 0.06, desk_d), C_OBS_DESK_TOP, roughness=0.45, metallic=0.35)
    _draw_box(Vector3(desk_cx, top_y - 0.03, desk_cz), Vector3(desk_w + 0.04, 0.04, desk_d + 0.04), C_OBS_STEEL, roughness=0.35, metallic=0.85)

    # ==========================================================================
    # Left-hand investigation extension, joined to the existing workstation.
    # It creates a dedicated surface for the protocol clipboard, with the printer
    # side of the desk kept untouched for the later merge.
    ext_cx, ext_w, ext_d = 1.42, 2.50, desk_d
    ext_left, ext_right = ext_cx - ext_w * 0.44, ext_cx + ext_w * 0.49
    for lx in (ext_left, ext_right):
        for lz in (desk_cz - ext_d * 0.42, desk_cz + ext_d * 0.42):
            _draw_box(Vector3(lx, desk_cy + desk_h * 0.46, lz), Vector3(0.075, desk_h * 0.92, 0.075), C_OBS_METAL_DARK, roughness=0.48, metallic=0.78)
            _draw_box(Vector3(lx, 0.045, lz), Vector3(0.18, 0.07, 0.16), C_OBS_STEEL, roughness=0.42, metallic=0.82)
    _draw_box(Vector3(ext_cx, desk_cy + 0.18, desk_cz - ext_d * 0.42), Vector3(ext_w * 0.90, 0.05, 0.05), C_OBS_METAL_MID, roughness=0.48, metallic=0.72)
    _draw_box(Vector3(ext_cx, top_y - 0.03, desk_cz), Vector3(ext_w, 0.06, ext_d), C_OBS_DESK_TOP, roughness=0.46, metallic=0.32)
    _draw_box(Vector3(ext_cx, top_y - 0.03, desk_cz), Vector3(ext_w + 0.04, 0.04, ext_d + 0.04), C_OBS_STEEL, roughness=0.38, metallic=0.82)
    # Scuffed seam strip and exposed fasteners make the extension feel retrofitted.
    _draw_box(Vector3(2.61, top_y - 0.006, desk_cz), Vector3(0.055, 0.035, ext_d - 0.08), C_OBS_METAL_DARK, roughness=0.62, metallic=0.64)
    for z_fastener in (desk_cz - 0.72, desk_cz + 0.72):
        _draw_cylinder(Vector3(2.58, top_y + 0.004, z_fastener), 0.018, 0.010, C_OBS_CHROME, roughness=0.24, metallic=0.90)


    # MONITORING STATION: 3 SCREENS (Center + 2 Angled Secondary)
    # ==========================================================================
    mon_base_y = top_y + 0.01

    # Central Bulky CRT Monitor
    c_mon_x = desk_cx
    c_mon_z = desk_cz + 0.28
    c_mon_y = top_y + 0.55
    c_w, c_h, c_depth = 1.45, 0.90, 0.48

    _draw_box(Vector3(c_mon_x, mon_base_y + 0.02, c_mon_z), Vector3(0.48, 0.04, 0.36), C_OBS_METAL_DARK, roughness=0.5, metallic=0.7)
    _draw_box(Vector3(c_mon_x, mon_base_y + 0.14, c_mon_z), Vector3(0.14, 0.22, 0.12), C_OBS_STEEL, roughness=0.3, metallic=0.85)
    _draw_box(Vector3(c_mon_x, c_mon_y, c_mon_z), Vector3(c_w, c_h, c_depth), C_OBS_METAL_DARK, roughness=0.5, metallic=0.55)
    _draw_box(Vector3(c_mon_x, c_mon_y, c_mon_z + 0.12), Vector3(c_w * 0.88, c_h * 0.88, c_depth * 0.6), C_OBS_METAL_MID, roughness=0.55, metallic=0.5)
    _draw_box(Vector3(c_mon_x, c_mon_y + c_h * 0.505, c_mon_z + 0.05), Vector3(c_w * 0.75, 0.015, c_depth * 0.6), C_OBS_METAL_DARK, roughness=0.7)

    # Bezel borders
    bw_border = 0.07
    _draw_box(Vector3(c_mon_x, c_mon_y + (c_h - bw_border) * 0.5, c_mon_z - c_depth * 0.505), Vector3(c_w, bw_border, 0.03), C_OBS_METAL_EDGE, roughness=0.4, metallic=0.7)
    _draw_box(Vector3(c_mon_x, c_mon_y - (c_h - bw_border) * 0.5, c_mon_z - c_depth * 0.505), Vector3(c_w, bw_border, 0.03), C_OBS_METAL_EDGE, roughness=0.4, metallic=0.7)
    _draw_box(Vector3(c_mon_x - (c_w - bw_border) * 0.5, c_mon_y, c_mon_z - c_depth * 0.505), Vector3(bw_border, c_h - bw_border * 2.0, 0.03), C_OBS_METAL_EDGE, roughness=0.4, metallic=0.7)
    _draw_box(Vector3(c_mon_x + (c_w - bw_border) * 0.5, c_mon_y, c_mon_z - c_depth * 0.505), Vector3(bw_border, c_h - bw_border * 2.0, 0.03), C_OBS_METAL_EDGE, roughness=0.4, metallic=0.7)

    # Active Phosphor Screen Face
    crt_emissive = Vector3(0.08, 0.28, 0.38) if is_powered else Vector3(0.01, 0.02, 0.03)
    _draw_box(Vector3(c_mon_x, c_mon_y, c_mon_z - c_depth * 0.51), Vector3(c_w - 0.16, c_h - 0.16, 0.01), Color(20, 65, 80, 255), roughness=0.1, emissive=crt_emissive)

    # Animated oscilloscope until identity/design begins; after Generate, the CRT permanently
    # displays the chosen four-colour reference rather than returning to the old card preview.
    if is_powered and not computer_identity_imported:
        _draw_box(Vector3(c_mon_x, c_mon_y + 0.25, c_mon_z - c_depth * 0.515), Vector3(c_w - 0.24, 0.01, 0.005), Color(80, 220, 240, 255), roughness=0.2, emissive=Vector3(0.3, 0.8, 0.9))
        for si in range(16):
            sx = c_mon_x - (c_w - 0.28) * 0.5 + si * ((c_w - 0.28) / 15.0)
            wave_val = math.sin(si * 0.65 + time_val * 4.5) * 0.12
            _draw_box(Vector3(sx, c_mon_y + wave_val, c_mon_z - c_depth * 0.515), Vector3(0.045, 0.012, 0.005), Color(140, 245, 255, 255), roughness=0.2, emissive=Vector3(0.5, 0.95, 1.0))
        for bi in range(6):
            bx = c_mon_x - 0.40 + bi * 0.16
            bh = 0.06 + 0.09 * (1.0 + math.sin(bi * 1.2 + time_val * 2.8)) * 0.5
            _draw_box(Vector3(bx, c_mon_y - 0.20 + bh * 0.5, c_mon_z - c_depth * 0.515), Vector3(0.08, bh, 0.005), Color(60, 200, 220, 255), roughness=0.2, emissive=Vector3(0.2, 0.7, 0.8))
    elif card_design_saved:
        # The final reference is persistent world-state: it remains on this CRT after ESC
        # closes the fullscreen session and is shown again whenever the player returns.
        ref_z = c_mon_z - c_depth * 0.515 - 0.010
        draw_pbr_box(Vector3(c_mon_x, c_mon_y, ref_z), Vector3(1.16, 0.66, 0.012),
                     Color(8, 18, 24, 255), roughness=0.22, emissive=Vector3(0.03, 0.09, 0.12))
        zone_cols = [CARTRIDGE_COLOUR_BY_ID.get(cid, Color(40, 49, 54, 255)) for cid in card_selected_colour_ids]
        for ri, ref_col in enumerate(zone_cols):
            rx = c_mon_x - 0.435 + ri * 0.29
            draw_pbr_box(Vector3(rx, c_mon_y + 0.045, ref_z - 0.010),
                         Vector3(0.235, 0.30, 0.006), Color(22, 34, 40, 255), roughness=0.40, metallic=0.10)
            draw_pbr_box(Vector3(rx, c_mon_y + 0.055, ref_z - 0.015),
                         Vector3(0.190, 0.185, 0.006), ref_col, roughness=0.35, metallic=0.10,
                         emissive=Vector3(ref_col.r / 1600.0, ref_col.g / 1600.0, ref_col.b / 1600.0))
            # Small grey strokes stand in for each reference swatch's printed zone/colour label.
            draw_pbr_box(Vector3(rx, c_mon_y - 0.145, ref_z - 0.015),
                         Vector3(0.17, 0.012, 0.005), Color(164, 190, 198, 255), roughness=0.65)
            draw_pbr_box(Vector3(rx, c_mon_y - 0.178, ref_z - 0.015),
                         Vector3(0.13, 0.008, 0.005), Color(87, 125, 136, 255), roughness=0.7)
    elif computer_identity_imported:
        card_z = c_mon_z - c_depth * 0.515 - 0.010
        card_base = Color(31, 40, 47, 255)
        _draw_box(Vector3(c_mon_x, c_mon_y, card_z), Vector3(1.05, 0.62, 0.012), card_base, roughness=0.35, metallic=0.28)
        zone_cols = [CARTRIDGE_COLOUR_BY_ID.get(cid, Color(40, 49, 54, 255)) for cid in card_selected_colour_ids]
        _draw_box(Vector3(c_mon_x, c_mon_y + 0.224, card_z - 0.008), Vector3(0.98, 0.070, 0.006), zone_cols[0], roughness=0.46, metallic=0.10)
        _draw_box(Vector3(c_mon_x - 0.34, c_mon_y + 0.005, card_z - 0.008), Vector3(0.27, 0.30, 0.006), zone_cols[1], roughness=0.42, metallic=0.10)
        _draw_box(Vector3(c_mon_x - 0.34, c_mon_y + 0.005, card_z - 0.013), Vector3(0.215, 0.245, 0.004), Color(32, 43, 48, 255), roughness=0.60)
        # Tiny stylised profile portrait; Napoleon gets the bicorne silhouette as an Easter egg.
        face_col = Color(208, 169, 137, 255)
        _draw_box(Vector3(c_mon_x - 0.34, c_mon_y + 0.025, card_z - 0.018), Vector3(0.083, 0.115, 0.004), face_col, roughness=0.8)
        if card_profile_index == 2:
            _draw_box(Vector3(c_mon_x - 0.34, c_mon_y + 0.093, card_z - 0.020), Vector3(0.17, 0.035, 0.004), Color(17, 22, 27, 255), roughness=0.45, metallic=0.22)
            _draw_box(Vector3(c_mon_x - 0.34, c_mon_y - 0.068, card_z - 0.020), Vector3(0.15, 0.075, 0.004), Color(40, 57, 82, 255), roughness=0.55, metallic=0.25)
        else:
            _draw_box(Vector3(c_mon_x - 0.34, c_mon_y + 0.074, card_z - 0.020), Vector3(0.12, 0.036, 0.004), Color(47, 38, 33, 255), roughness=0.8)
            _draw_box(Vector3(c_mon_x - 0.34, c_mon_y - 0.085, card_z - 0.020), Vector3(0.15, 0.06, 0.004), Color(48, 78, 83, 255), roughness=0.55, metallic=0.15)
        _draw_box(Vector3(c_mon_x + 0.20, c_mon_y + 0.082, card_z - 0.009), Vector3(0.43, 0.036, 0.005), zone_cols[3], roughness=0.45)
        _draw_box(Vector3(c_mon_x + 0.20, c_mon_y + 0.030, card_z - 0.009), Vector3(0.38, 0.012, 0.005), Color(180, 194, 198, 255), roughness=0.75)
        _draw_box(Vector3(c_mon_x + 0.20, c_mon_y - 0.010, card_z - 0.009), Vector3(0.34, 0.012, 0.005), zone_cols[2], roughness=0.45)
        _draw_box(Vector3(c_mon_x + 0.20, c_mon_y - 0.073, card_z - 0.009), Vector3(0.42, 0.080, 0.005), Color(220, 222, 214, 255), roughness=0.85)
        barcode_seed = sum(ord(ch) for ch in (card_identity_name + card_identity_job + card_barcode_value))
        for bi in range(26):
            bw = 0.008 if ((barcode_seed >> (bi % 13)) & 1) else 0.004
            bx = c_mon_x + 0.01 + bi * 0.014
            _draw_box(Vector3(bx, c_mon_y - 0.073, card_z - 0.013), Vector3(bw, 0.050, 0.004), Color(20, 24, 28, 255), roughness=0.8)
        # A compact status line stays visible on the monitor after the player stands up.
        _draw_box(Vector3(c_mon_x, c_mon_y - 0.235, card_z - 0.008), Vector3(0.88, 0.018, 0.005), zone_cols[2], roughness=0.45)

    # Adhesive Notes pinned to CRT Monitor Bezel
    _draw_box(Vector3(c_mon_x + 0.58, c_mon_y + 0.38, c_mon_z - c_depth * 0.525), Vector3(0.09, 0.09, 0.003), Color(245, 230, 95, 255), roughness=0.9)
    _draw_box(Vector3(c_mon_x - 0.55, c_mon_y - 0.36, c_mon_z - c_depth * 0.525), Vector3(0.11, 0.08, 0.003), Color(250, 180, 195, 255), roughness=0.9)

    # Left Secondary Monitor (Angled 18 deg)
    l_mon_x = desk_cx - 1.55
    l_mon_z = desk_cz + 0.20
    l_mon_y = top_y + 0.44
    l_w, l_h, l_d = 1.15, 0.72, 0.32
    _draw_box(Vector3(l_mon_x, mon_base_y + 0.015, l_mon_z), Vector3(0.38, 0.03, 0.28), C_OBS_METAL_DARK, roughness=0.5, metallic=0.7)
    _draw_box(Vector3(l_mon_x, mon_base_y + 0.11, l_mon_z), Vector3(0.10, 0.16, 0.08), C_OBS_STEEL, roughness=0.3, metallic=0.85)
    _draw_box(Vector3(l_mon_x, l_mon_y, l_mon_z), Vector3(l_w, l_h, l_d), C_OBS_METAL_DARK, roughness=0.5, metallic=0.55)
    _draw_box(Vector3(l_mon_x, l_mon_y, l_mon_z - l_d * 0.51), Vector3(l_w - 0.12, l_h - 0.12, 0.01), Color(15, 50, 65, 255), roughness=0.15, emissive=Vector3(0.04, 0.18, 0.26))
    _draw_box(Vector3(l_mon_x, l_mon_y, l_mon_z - l_d * 0.515), Vector3(0.012, l_h - 0.14, 0.005), Color(30, 85, 110, 255), roughness=0.3)

    # Right Secondary Monitor (Angled -18 deg)
    r_mon_x = desk_cx + 1.55
    r_mon_z = desk_cz + 0.20
    r_mon_y = top_y + 0.44
    _draw_box(Vector3(r_mon_x, mon_base_y + 0.015, r_mon_z), Vector3(0.38, 0.03, 0.28), C_OBS_METAL_DARK, roughness=0.5, metallic=0.7)
    _draw_box(Vector3(r_mon_x, mon_base_y + 0.11, r_mon_z), Vector3(0.10, 0.16, 0.08), C_OBS_STEEL, roughness=0.3, metallic=0.85)
    _draw_box(Vector3(r_mon_x, r_mon_y, r_mon_z), Vector3(l_w, l_h, l_d), C_OBS_METAL_DARK, roughness=0.5, metallic=0.55)
    _draw_box(Vector3(r_mon_x, r_mon_y, r_mon_z - l_d * 0.51), Vector3(l_w - 0.12, l_h - 0.12, 0.01), Color(55, 42, 18, 255), roughness=0.15, emissive=Vector3(0.24, 0.16, 0.05))
    for li in range(4):
        _draw_box(Vector3(r_mon_x, r_mon_y + 0.16 - li * 0.11, r_mon_z - l_d * 0.515), Vector3(l_w - 0.24, 0.018, 0.005), Color(245, 185, 60, 255), roughness=0.2, emissive=Vector3(0.45, 0.32, 0.08))

    # ==========================================================================
    # WORKSTATION CONTROLS, PERIPHERALS & STORY PROPS
    # ==========================================================================
    work_y = top_y + 0.01

    # Keyboard & Wired Mouse
    _draw_box(Vector3(desk_cx, work_y + 0.012, desk_cz - 0.34), Vector3(0.58, 0.024, 0.22), Color(35, 38, 42, 255), roughness=0.6, metallic=0.2)
    _draw_box(Vector3(desk_cx, work_y + 0.026, desk_cz - 0.34), Vector3(0.54, 0.012, 0.18), Color(22, 24, 28, 255), roughness=0.7)
    _draw_box(Vector3(desk_cx + 0.42, work_y + 0.015, desk_cz - 0.34), Vector3(0.10, 0.028, 0.15), Color(30, 32, 36, 255), roughness=0.5)
    _draw_cylinder(Vector3(desk_cx + 0.42, work_y + 0.008, desk_cz - 0.18), 0.003, 0.32, Color(15, 15, 18, 255), roughness=0.85)

    # Tactile Physical Control Panel (Right desk side)
    # Relocate the old tactile desk control panel to the front-left desktop; the
    # security terminal now occupies the open right-hand work area.
    cp_x, cp_z = desk_cx - 2.00, desk_cz - 0.62
    _draw_box(Vector3(cp_x, work_y + 0.035, cp_z), Vector3(0.68, 0.07, 0.34), C_OBS_STEEL, roughness=0.35, metallic=0.85)
    for sw_i in range(5):
        _draw_cylinder(Vector3(cp_x - 0.22 + sw_i * 0.11, work_y + 0.075, cp_z + 0.06), 0.018, 0.035, C_OBS_CHROME, roughness=0.2, metallic=0.95)
        sw_col = (C_OBS_RED_LED, C_OBS_GREEN_LED, C_OBS_CYAN_LED, C_OBS_AMBER_LED, C_OBS_GREEN_LED)[sw_i]
        _draw_cylinder(Vector3(cp_x - 0.22 + sw_i * 0.11, work_y + 0.075, cp_z - 0.06), 0.014, 0.025, sw_col, roughness=0.2, emissive=Vector3(sw_col.r/350.0, sw_col.g/350.0, sw_col.b/350.0))

    # Rack-Mounted Frequency Signal Receiver Unit
    _draw_box(Vector3(desk_cx + 0.95, work_y + 0.045, desk_cz + 0.12), Vector3(0.48, 0.09, 0.28), C_OBS_METAL_DARK, roughness=0.5, metallic=0.7)
    _draw_cylinder(Vector3(desk_cx + 1.15, work_y + 0.24, desk_cz + 0.12), 0.005, 0.42, C_OBS_CHROME, roughness=0.2, metallic=0.95)
    _draw_box(Vector3(desk_cx + 0.88, work_y + 0.05, desk_cz - 0.025), Vector3(0.12, 0.04, 0.01), Color(20, 24, 28, 255), roughness=0.3)
    _draw_box(Vector3(desk_cx + 0.86, work_y + 0.05, desk_cz - 0.03), Vector3(0.04, 0.02, 0.005), C_OBS_GREEN_LED, roughness=0.2, emissive=Vector3(0.2, 0.8, 0.3))

    # Desktop Intercom / Communication Handset with Coiled Cord
    _draw_box(Vector3(desk_cx - 1.10, work_y + 0.03, desk_cz - 0.32), Vector3(0.22, 0.06, 0.26), Color(220, 215, 195, 255), roughness=0.6)
    _draw_cylinder(Vector3(desk_cx - 1.10, work_y + 0.07, desk_cz - 0.32), 0.03, 0.24, Color(210, 205, 185, 255), roughness=0.6)

    # Articulated Desk Lamp casting warm pool of light
    lamp_x, lamp_z = desk_cx - 0.95, desk_cz + 0.08
    _draw_cylinder(Vector3(lamp_x, work_y + 0.015, lamp_z), 0.11, 0.03, C_OBS_STEEL, roughness=0.4, metallic=0.85)
    _draw_cylinder(Vector3(lamp_x, work_y + 0.20, lamp_z), 0.014, 0.38, C_OBS_CHROME, roughness=0.2, metallic=0.95)
    _draw_cylinder(Vector3(lamp_x + 0.12, work_y + 0.38, lamp_z - 0.10), 0.014, 0.34, C_OBS_CHROME, roughness=0.2, metallic=0.95)
    _draw_cone(Vector3(lamp_x + 0.18, work_y + 0.44, lamp_z - 0.18), 0.14, 0.18, Color(30, 32, 36, 255), roughness=0.5, metallic=0.6)
    _draw_sphere(Vector3(lamp_x + 0.18, work_y + 0.38, lamp_z - 0.18), 0.045, Color(255, 235, 160, 255), roughness=0.2, emissive=Vector3(1.2, 0.9, 0.4))

    # Vintage Microcassette Voice Recorder with Blinking Red REC LED
    rec_x, rec_z = desk_cx - 0.75, desk_cz - 0.38
    _draw_box(Vector3(rec_x, work_y + 0.02, rec_z), Vector3(0.24, 0.038, 0.16), Color(185, 80, 25, 255), roughness=0.55, metallic=0.4)
    _draw_box(Vector3(rec_x, work_y + 0.038, rec_z), Vector3(0.14, 0.005, 0.10), Color(25, 25, 28, 255), roughness=0.3)
    rec_blink = math.sin(time_val * 4.0) > 0.0
    rec_col = C_OBS_RED_LED if rec_blink else Color(70, 15, 15, 255)
    _draw_cylinder(Vector3(rec_x - 0.08, work_y + 0.04, rec_z - 0.05), 0.010, 0.015, rec_col, roughness=0.2, emissive=Vector3(0.9, 0.1, 0.1) if rec_blink else Vector3(0.1, 0, 0))

    # Unrolled Blueprint with Brass Corner Weights
    bp_x, bp_z = desk_cx - 0.65, desk_cz - 0.42
    _draw_box(Vector3(bp_x, work_y + 0.003, bp_z), Vector3(0.72, 0.005, 0.52), Color(25, 85, 155, 255), roughness=0.85)
    _draw_box(Vector3(bp_x, work_y + 0.007, bp_z), Vector3(0.66, 0.003, 0.005), Color(220, 235, 255, 255), roughness=0.9)
    _draw_box(Vector3(bp_x, work_y + 0.007, bp_z), Vector3(0.005, 0.003, 0.46), Color(220, 235, 255, 255), roughness=0.9)
    for w_corner_x, w_corner_z in ((bp_x - 0.33, bp_z - 0.23), (bp_x + 0.33, bp_z + 0.23)):
        _draw_cylinder(Vector3(w_corner_x, work_y + 0.018, w_corner_z), 0.035, 0.03, Color(215, 185, 65, 255), roughness=0.25, metallic=0.92)

    # Chipped Ceramic Coffee Mug with Dried Ring & Runoff Stain
    # Move the mug to the rear-left edge so it doesn't sit inside the security
    # terminal mounting footprint after the workstation is moved right.
    mug_x, mug_z = desk_cx - 1.60, desk_cz + 0.55
    _draw_cylinder(Vector3(mug_x, work_y + 0.001, mug_z), 0.075, 0.003, Color(35, 22, 14, 230), roughness=0.9)
    _draw_box(Vector3(mug_x + 0.04, work_y + 0.001, mug_z + 0.06), Vector3(0.04, 0.002, 0.08), Color(42, 26, 16, 200), roughness=0.9)
    _draw_cylinder(Vector3(mug_x, work_y + 0.075, mug_z), 0.065, 0.15, Color(235, 235, 230, 255), roughness=0.45)
    _draw_cylinder(Vector3(mug_x, work_y + 0.085, mug_z), 0.052, 0.14, Color(30, 18, 12, 255), roughness=0.7)
    _draw_torus(Vector3(mug_x - 0.07, work_y + 0.075, mug_z), 0.042, 0.012, Color(235, 235, 230, 255), roughness=0.45)

    # Overturned Pen Cup with Scattered Pencils, Marker, and Ruler
    cup_x, cup_z = desk_cx - 1.45, desk_cz - 0.38
    _draw_cylinder(Vector3(cup_x, work_y + 0.045, cup_z), 0.045, 0.14, C_OBS_STEEL, roughness=0.35, metallic=0.85)
    _draw_cylinder(Vector3(cup_x + 0.12, work_y + 0.005, cup_z + 0.02), 0.004, 0.18, Color(215, 45, 35, 255), roughness=0.6)
    _draw_cylinder(Vector3(cup_x + 0.16, work_y + 0.005, cup_z - 0.04), 0.004, 0.18, Color(35, 85, 205, 255), roughness=0.6)
    _draw_box(Vector3(cup_x + 0.10, work_y + 0.003, cup_z + 0.10), Vector3(0.24, 0.004, 0.025), Color(210, 195, 140, 255), roughness=0.7)

    # Compact Desk Fan
    _draw_cylinder(Vector3(desk_cx + 2.25, work_y + 0.015, desk_cz + 0.15), 0.10, 0.03, Color(45, 50, 55, 255), roughness=0.5)
    _draw_cylinder(Vector3(desk_cx + 2.25, work_y + 0.14, desk_cz + 0.15), 0.016, 0.24, C_OBS_STEEL, roughness=0.35, metallic=0.85)
    _draw_sphere(Vector3(desk_cx + 2.25, work_y + 0.28, desk_cz + 0.15), 0.12, Color(55, 60, 65, 255), roughness=0.4)
    # Three small rotating blades on the desk fan, facing the player-side of the desk.
    desk_spin = 0.0  # Nonessential desk-fan animation disabled for performance
    for blade_i in range(3):
        ba = desk_spin + blade_i * 120.0
        br = math.radians(ba)
        draw_pbr_box_rotated(Vector3(desk_cx + 2.25 + math.cos(br) * 0.065,
                                     work_y + 0.28 + math.sin(br) * 0.065,
                                     desk_cz + 0.020),
                             Vector3(0.12, 0.035, 0.018), Color(104, 111, 114, 255),
                             ba, axis=Vector3(0.0, 0.0, 1.0), roughness=0.62, metallic=0.55)
    desk_hub_mark = math.radians(desk_spin)
    _draw_box(Vector3(desk_cx + 2.25 + math.cos(desk_hub_mark) * 0.024,
                      work_y + 0.28 + math.sin(desk_hub_mark) * 0.024,
                      desk_cz + 0.002),
              Vector3(0.018, 0.018, 0.008), C_OBS_WARNING, roughness=0.3, metallic=0.55)

    # Heavy Portable Rubberized Hand Lantern on Desk
    _draw_box(Vector3(desk_cx - 2.15, work_y + 0.065, desk_cz - 0.25), Vector3(0.14, 0.13, 0.28), Color(225, 95, 20, 255), roughness=0.6)
    _draw_cylinder(Vector3(desk_cx - 2.15, work_y + 0.065, desk_cz - 0.40), 0.065, 0.04, Color(25, 25, 28, 255), roughness=0.4)

    # Under-Desk Computer Infrastructure (Tower PC, UPS, Cables)
    pc_x, pc_z = desk_cx + 0.55, desk_cz + 0.18
    _draw_box(Vector3(pc_x, desk_cy + 0.32, pc_z), Vector3(0.24, 0.60, 0.58), Color(22, 25, 28, 255), roughness=0.5, metallic=0.6)
    _draw_box(Vector3(pc_x, desk_cy + 0.52, pc_z - 0.295), Vector3(0.20, 0.08, 0.01), Color(35, 40, 45, 255), roughness=0.6)
    _draw_box(Vector3(pc_x - 0.06, desk_cy + 0.58, pc_z - 0.295), Vector3(0.018, 0.018, 0.005), C_OBS_GREEN_LED, roughness=0.2, emissive=Vector3(0.2, 0.8, 0.2))
    _draw_box(Vector3(desk_cx + 0.95, desk_cy + 0.16, pc_z), Vector3(0.22, 0.30, 0.42), Color(40, 44, 48, 255), roughness=0.6)
    _draw_cylinder(Vector3(desk_cx + 0.25, top_y - 0.01, desk_cz + 0.35), 0.045, 0.04, Color(15, 18, 20, 255), roughness=0.8)
    _draw_cylinder(Vector3(desk_cx + 0.25, desk_cy + 0.45, desk_cz + 0.35), 0.028, 0.85, Color(18, 20, 22, 255), roughness=0.85)


    # Physical Archive Access Protocol clipboard. This is deliberately separate
    # from the other loose log cards and has a matching reachable inspection target.
    protocol_x, protocol_z = PROTOCOL_BOARD_X, PROTOCOL_BOARD_Z
    _draw_box(Vector3(protocol_x, top_y + 0.023, protocol_z), Vector3(0.48, 0.045, 0.34),
              Color(52, 58, 60, 255), roughness=0.58, metallic=0.48)
    _draw_box(Vector3(protocol_x, top_y + 0.048, protocol_z), Vector3(0.435, 0.008, 0.295),
              Color(194, 183, 154, 255), roughness=0.98)
    _draw_box(Vector3(protocol_x, top_y + 0.054, protocol_z - 0.135), Vector3(0.12, 0.010, 0.025),
              Color(111, 119, 118, 255), roughness=0.38, metallic=0.85)
    for line_i, line_w in enumerate((0.31, 0.35, 0.27, 0.33, 0.22)):
        _draw_box(Vector3(protocol_x - 0.02, top_y + 0.054, protocol_z - 0.07 + line_i * 0.043),
                  Vector3(line_w, 0.003, 0.005), Color(113, 106, 88, 255), roughness=0.98)

def draw_window_workstation_extra_clutter(time_val=0.0, is_powered=False):
    """Extra believable records and small equipment on the existing glass-side desk."""
    cx, cz = 5.2, -16.0
    top_y = 0.92
    paper = Color(225, 219, 198, 255)
    aged = Color(183, 172, 146, 255)
    dark = Color(24, 28, 32, 255)
    metal = Color(66, 72, 77, 255)
    # Front-edge records packet moved to the left of the relocated security console,
    # with a clear gap from its mounting plate and no overlap with the player's approach.
    fx, fz = 4.72, -16.68
    _draw_box(Vector3(fx, top_y + 0.025, fz), Vector3(0.46, 0.018, 0.30), C_OBS_FOLDER_BLUE,
              roughness=0.90)
    for layer in range(4):
        draw_pbr_box_rotated(Vector3(fx + (layer % 2) * 0.035, top_y + 0.039 + layer * 0.006,
                                     fz - (layer % 3) * 0.018),
                             Vector3(0.39, 0.005, 0.245), paper if layer % 2 else aged,
                             -5.0 + layer * 3.0, axis=Vector3(0.0, 1.0, 0.0), roughness=0.97)
    for line_i in range(4):
        _draw_box(Vector3(fx - 0.02, top_y + 0.064, fz - 0.075 + line_i * 0.035),
                  Vector3(0.22, 0.002, 0.004), Color(111, 105, 91, 255), roughness=0.98)
    # Metal clip and red pencil left on the documents.
    _draw_box(Vector3(fx + 0.13, top_y + 0.067, fz - 0.095), Vector3(0.055, 0.008, 0.014),
              C_OBS_CHROME, roughness=0.25, metallic=0.9)
    draw_pbr_box_rotated(Vector3(fx + 0.19, top_y + 0.028, fz + 0.015),
                         Vector3(0.26, 0.014, 0.018), C_OBS_EXTINGUISHER, 12.0,
                         axis=Vector3(0.0, 1.0, 0.0), roughness=0.72)
    # Small open cassette box with a half-removed telemetry tape.
    bx, bz = 6.72, -16.70
    _draw_box(Vector3(bx, top_y + 0.055, bz), Vector3(0.34, 0.10, 0.25), dark,
              roughness=0.65, metallic=0.48)
    _draw_box(Vector3(bx, top_y + 0.11, bz), Vector3(0.34, 0.018, 0.25), metal,
              roughness=0.6, metallic=0.58)
    _draw_box(Vector3(bx - 0.02, top_y + 0.124, bz + 0.015), Vector3(0.25, 0.008, 0.15),
              Color(18, 22, 26, 255), roughness=0.9)
    for spool_x in (bx - 0.075, bx + 0.075):
        _draw_cylinder(Vector3(spool_x, top_y + 0.13, bz + 0.015), 0.045, 0.012,
                       C_OBS_STEEL, roughness=0.38, metallic=0.85)
        _draw_cylinder(Vector3(spool_x, top_y + 0.139, bz + 0.015), 0.018, 0.014,
                       C_OBS_CHROME, roughness=0.26, metallic=0.9)
    # A little stack of colour-coded specimen log cards on the far corner.
    sx, sz = 7.42, -15.35
    for idx, col in enumerate((C_OBS_PAPER, aged, C_OBS_FOLDER_MANILA)):
        _draw_box(Vector3(sx, top_y + 0.012 + idx * 0.012, sz), Vector3(0.22, 0.008, 0.31), col,
                  roughness=0.97)
    _draw_box(Vector3(sx, top_y + 0.046, sz - 0.07), Vector3(0.16, 0.002, 0.004),
              Color(110, 101, 85, 255), roughness=0.98)
    # A loose metal clip and tiny status module by the CRT stand.
    _draw_box(Vector3(4.62, top_y + 0.018, -15.27), Vector3(0.19, 0.026, 0.12), dark,
              roughness=0.50, metallic=0.65)
    _draw_box(Vector3(4.62, top_y + 0.034, -15.205), Vector3(0.12, 0.01, 0.018),
              C_OBS_CYAN_LED, roughness=0.24,
              emissive=Vector3(0.02, 0.22, 0.28) if is_powered else None)
    # Extra observer work surface details: a second log stack, a portable meter,
    # a headset, and a clipped warning note. They are kept in the front strip of
    # the desk so they don't intersect the monitor bases or the physical controls.
    # This left-front desktop patch is reserved for the CMYK badge printer
    # added in draw_card_production_printer(); leaving the old binder here would
    # intersect the printer chassis and card output tray.
    # Portable vibration/frequency meter with recessed display, dial and connector ports.
    vx, vz = 5.78, -16.56
    _draw_box(Vector3(vx, top_y + 0.060, vz), Vector3(0.37, 0.105, 0.25), dark,
              roughness=0.52, metallic=0.70)
    _draw_box(Vector3(vx - 0.035, top_y + 0.117, vz - 0.055), Vector3(0.20, 0.009, 0.10),
              Color(8, 30, 35, 255), roughness=0.20,
              emissive=Vector3(0.02, 0.12, 0.15) if is_powered else None)
    for bi, bcol in enumerate((C_OBS_CYAN_LED, C_OBS_AMBER_LED, C_OBS_RED_LED)):
        _draw_box(Vector3(vx - 0.105 + bi * 0.065, top_y + 0.125, vz - 0.055),
                  Vector3(0.025, 0.004, 0.012), bcol, roughness=0.25)
    _draw_cylinder(Vector3(vx + 0.115, top_y + 0.125, vz + 0.025), 0.034, 0.018,
                   C_OBS_CHROME, roughness=0.24, metallic=0.92)
    _draw_cylinder(Vector3(vx - 0.13, top_y + 0.065, vz + 0.125), 0.018, 0.03,
                   C_OBS_STEEL, roughness=0.35, metallic=0.82)
    # Headset resting on its side beside the telemetry tapes.
    _draw_torus(Vector3(7.28, top_y + 0.045, -16.23), 0.145, 0.022,
                dark, roughness=0.72, metallic=0.28)
    for hx in (7.15, 7.41):
        _draw_box(Vector3(hx, top_y + 0.052, -16.23), Vector3(0.065, 0.095, 0.075),
                  metal, roughness=0.58, metallic=0.55)
        _draw_box(Vector3(hx, top_y + 0.052, -16.23), Vector3(0.035, 0.058, 0.018),
                  dark, roughness=0.86, metallic=0.18)
    # Tiny paper warning pinned beneath the right secondary monitor, curled edge implied by a fold.
    _draw_box(Vector3(7.45, top_y + 0.023, -15.76), Vector3(0.22, 0.009, 0.18),
              Color(198, 181, 131, 255), roughness=0.98)
    _draw_box(Vector3(7.45, top_y + 0.029, -15.76), Vector3(0.13, 0.002, 0.004),
              Color(120, 48, 38, 255), roughness=0.98)

    # Several used paper scraps just below the desk, not forming a movement barrier.
    for x, z, ang, col in ((3.05, -17.65, 18.0, paper), (3.42, -17.92, -22.0, aged),
                           (7.92, -16.90, 9.0, paper), (6.85, -17.12, -11.0, aged)):
        draw_pbr_box_rotated(Vector3(x, 0.018, z), Vector3(0.24, 0.006, 0.17), col, ang,
                             axis=Vector3(0.0, 1.0, 0.0), roughness=0.98)

def draw_observation_seating(time_val=0.0):
    ch_x, ch_y, ch_z = 5.2, 0.0, -17.4

    # Floor Scuff Mark beneath Chair
    _draw_cylinder(Vector3(ch_x, ch_y + 0.002, ch_z), 0.72, 0.003, Color(28, 32, 36, 180), roughness=0.95)

    # 5-Star Caster Base
    _draw_cylinder(Vector3(ch_x, ch_y + 0.09, ch_z), 0.07, 0.08, C_OBS_CHROME, roughness=0.2, metallic=0.92)
    for ci in range(5):
        c_ang = ci * (2.0 * math.pi / 5.0)
        c_deg = math.degrees(c_ang)
        # Each spoke is oriented radially out from the piston. The previous
        # version placed five spokes but left every box aligned to world X.
        c_leg_x = ch_x + math.cos(c_ang) * 0.235
        c_leg_z = ch_z + math.sin(c_ang) * 0.235
        draw_pbr_box_rotated(Vector3(c_leg_x, ch_y + 0.075, c_leg_z),
                             Vector3(0.37, 0.038, 0.055), C_OBS_CHROME,
                             -c_deg, axis=Vector3(0.0, 1.0, 0.0),
                             roughness=0.25, metallic=0.9)
        # Four intact casters and one missing caster. Each fork and wheel is
        # oriented tangentially to its spoke instead of using world-aligned blocks.
        if ci != 3:
            wx = ch_x + math.cos(c_ang) * 0.415
            wz = ch_z + math.sin(c_ang) * 0.415
            draw_pbr_box_rotated(Vector3(wx, ch_y + 0.070, wz),
                                 Vector3(0.075, 0.075, 0.058), C_OBS_METAL_DARK,
                                 -c_deg, axis=Vector3(0.0, 1.0, 0.0),
                                 roughness=0.56, metallic=0.75)
            draw_pbr_ellipsoid(Vector3(ch_x + math.cos(c_ang) * 0.445,
                                       ch_y + 0.045,
                                       ch_z + math.sin(c_ang) * 0.445),
                               Vector3(0.060, 0.038, 0.030), Color(22, 24, 26, 255),
                               angle_degrees=-(c_deg + 90.0), roughness=0.78, metallic=0.18)

    # Detached caster wheel lying on the floor nearby; the disc is horizontal-axis aligned.
    draw_pbr_ellipsoid(Vector3(ch_x - 0.58, ch_y + 0.040, ch_z + 0.25),
                       Vector3(0.060, 0.038, 0.030), Color(22, 24, 26, 255),
                       angle_degrees=-48.0, roughness=0.78, metallic=0.18)
    _draw_cylinder(Vector3(ch_x - 0.58, ch_y + 0.040, ch_z + 0.25),
                   0.008, 0.030, C_OBS_CHROME, roughness=0.2, metallic=0.9)

    # Central Piston & Seat Tilt Mechanism
    _draw_cylinder(Vector3(ch_x, ch_y + 0.28, ch_z), 0.038, 0.32, C_OBS_CHROME, roughness=0.15, metallic=0.95)
    _draw_box(Vector3(ch_x, ch_y + 0.44, ch_z), Vector3(0.24, 0.05, 0.22), C_OBS_METAL_DARK, roughness=0.4, metallic=0.8)

    # Seat Cushion
    _draw_box(Vector3(ch_x, ch_y + 0.49, ch_z), Vector3(0.54, 0.085, 0.52), Color(38, 44, 52, 255), roughness=0.75)

    # Backrest with Torn Upholstery Exposing Yellow Foam
    _draw_box(Vector3(ch_x, ch_y + 0.88, ch_z + 0.24), Vector3(0.50, 0.62, 0.08), Color(38, 44, 52, 255), roughness=0.75)
    _draw_box(Vector3(ch_x - 0.06, ch_y + 0.82, ch_z + 0.20), Vector3(0.18, 0.22, 0.015), Color(230, 205, 60, 255), roughness=0.9)
    _draw_box(Vector3(ch_x - 0.06, ch_y + 0.82, ch_z + 0.195), Vector3(0.22, 0.012, 0.01), Color(24, 28, 34, 255), roughness=0.8)

    # Armrests
    for ax in (ch_x - 0.31, ch_x + 0.31):
        _draw_cylinder(Vector3(ax, ch_y + 0.58, ch_z), 0.018, 0.22, C_OBS_CHROME, roughness=0.25, metallic=0.9)
        _draw_box(Vector3(ax, ch_y + 0.70, ch_z - 0.02), Vector3(0.07, 0.035, 0.32), Color(25, 28, 32, 255), roughness=0.6)

    # Tubular Steel Visitor Chair (West of desk)
    v_x, v_y, v_z = 1.2, 0.0, -19.5
    for vx in (v_x - 0.26, v_x + 0.26):
        for vz in (v_z - 0.24, v_z + 0.24):
            _draw_cylinder(Vector3(vx, v_y + 0.22, vz), 0.016, 0.44, C_OBS_CHROME, roughness=0.2, metallic=0.92)
    _draw_box(Vector3(v_x, v_y + 0.44, v_z), Vector3(0.52, 0.06, 0.48), Color(85, 92, 100, 255), roughness=0.8)
    _draw_box(Vector3(v_x, v_y + 0.74, v_z + 0.22), Vector3(0.48, 0.48, 0.05), Color(85, 92, 100, 255), roughness=0.8)

def draw_observation_storage(time_val=0.0, is_powered=False):
    # 3 Tall Metal Filing Cabinets (East Wall: X = 11.2). Lowered to the floor:
    # the cabinet shells now span Y=0.0..2.10 rather than visibly hovering a metre up.
    # Two drawers are pulled well clear of the front with record folders inside.
    for fi in range(3):
        fz = -25.5 + fi * 1.55
        cabinet_x = 11.2
        _draw_box(Vector3(cabinet_x, 1.05, fz), Vector3(0.85, 2.10, 1.25), C_OBS_METAL_MID,
                  roughness=0.58, metallic=0.65)
        # Toe plinth and small feet make contact with the floor visually explicit.
        _draw_box(Vector3(cabinet_x, 0.075, fz), Vector3(0.88, 0.15, 1.28), C_OBS_METAL_DARK,
                  roughness=0.75, metallic=0.58)
        for foot_z in (fz - 0.48, fz + 0.48):
            _draw_box(Vector3(cabinet_x, 0.025, foot_z), Vector3(0.60, 0.05, 0.12), C_OBS_RUBBER,
                      roughness=0.98, metallic=0.08)
        for d_idx in range(4):
            dy = 0.27 + d_idx * 0.51
            # One pulled drawer on the first unit, one on the middle unit.
            is_open = (fi == 0 and d_idx == 2) or (fi == 1 and d_idx == 1)
            pull = 0.48 if is_open else 0.0
            face_x = 10.74 - pull
            _draw_box(Vector3(face_x, dy, fz), Vector3(0.04, 0.42, 1.15),
                      C_OBS_METAL_DARK if is_open else C_OBS_METAL_MID,
                      roughness=0.52, metallic=0.70)
            _draw_box(Vector3(face_x - 0.035, dy, fz), Vector3(0.02, 0.035, 0.24),
                      C_OBS_CHROME, roughness=0.2, metallic=0.95)
            if is_open:
                # Drawer tray slides out along -X. The rails, sidewalls and files are visible.
                tray_x = 10.74 - pull * 0.50
                _draw_box(Vector3(tray_x, dy - 0.025, fz), Vector3(0.48, 0.34, 1.08),
                          Color(22, 26, 29, 255), roughness=0.78, metallic=0.50)
                for zz in (fz - 0.53, fz + 0.53):
                    _draw_box(Vector3(tray_x, dy + 0.06, zz), Vector3(0.45, 0.16, 0.035),
                              C_OBS_METAL_EDGE, roughness=0.58, metallic=0.66)
                # Distinct file folders and several paper records inside each open drawer.
                folder_cols = (C_OBS_FOLDER_MANILA, C_OBS_FOLDER_BLUE, C_OBS_FOLDER_RED,
                               Color(132, 145, 129, 255), C_OBS_PAPER_AGED)
                for r_i, folder_col in enumerate(folder_cols):
                    zz = fz - 0.36 + r_i * 0.17
                    _draw_box(Vector3(tray_x + 0.015, dy + 0.105 + (0.02 if r_i % 2 else 0.0), zz),
                              Vector3(0.025, 0.21, 0.135), folder_col,
                              roughness=0.91, metallic=0.04)
                    _draw_box(Vector3(tray_x - 0.002, dy + 0.19, zz), Vector3(0.012, 0.022, 0.060),
                              C_OBS_PAPER, roughness=0.96)
                _draw_box(Vector3(tray_x - 0.04, dy + 0.153, fz + 0.18),
                          Vector3(0.30, 0.008, 0.22), C_OBS_PAPER_AGED, roughness=0.98)
            # File-tab labels and worn drawer corners.
            _draw_box(Vector3(face_x - 0.026, dy + 0.12, fz - 0.38),
                      Vector3(0.012, 0.055, 0.14), C_OBS_PAPER_AGED,
                      roughness=0.95)
            if d_idx in (0, 3):
                _draw_box(Vector3(face_x - 0.026, dy - 0.17, fz + 0.49),
                          Vector3(0.012, 0.035, 0.08), Color(102, 57, 37, 255),
                          roughness=0.96, metallic=0.12)

    # 4-Tier Heavy Steel Equipment Shelving Unit (West Wall: X = -10.8)
    sh_x, sh_z = -10.8, -25.0
    for sx in (sh_x - 0.55, sh_x + 0.55):
        for sz in (sh_z - 1.85, sh_z + 1.85):
            _draw_box(Vector3(sx, 1.95, sz), Vector3(0.065, 3.90, 0.065), C_OBS_STEEL, roughness=0.4, metallic=0.85)
    for ti in range(4):
        ty = 0.35 + ti * 1.05
        _draw_box(Vector3(sh_x, ty, sh_z), Vector3(1.18, 0.05, 3.80), C_OBS_METAL_DARK, roughness=0.45, metallic=0.75)

    # Items on Shelving
    _draw_box(Vector3(sh_x, 0.58, sh_z - 0.90), Vector3(0.55, 0.38, 0.72), Color(35, 40, 48, 255), roughness=0.6)
    _draw_box(Vector3(sh_x, 1.62, sh_z + 0.85), Vector3(0.48, 0.35, 0.58), Color(65, 72, 80, 255), roughness=0.5, metallic=0.6)
    _draw_box(Vector3(sh_x - 0.22, 1.62, sh_z + 0.85), Vector3(0.01, 0.22, 0.32), Color(20, 55, 45, 255), roughness=0.2, emissive=Vector3(0.05, 0.35, 0.15))
    _draw_box(Vector3(sh_x, 2.68, sh_z - 0.50), Vector3(0.42, 0.44, 0.65), Color(185, 155, 115, 255), roughness=0.9)
    _draw_box(Vector3(sh_x - 0.22, 2.68, sh_z - 0.50), Vector3(0.01, 0.12, 0.28), C_OBS_PAPER, roughness=0.9)

    # Chemical Dual-Cartridge Half-Face Respirator (Gas Mask) hanging on shelf rack
    _draw_sphere(Vector3(sh_x + 0.20, 1.95, sh_z - 1.85), 0.11, Color(30, 32, 36, 255), roughness=0.6)
    _draw_cylinder(Vector3(sh_x + 0.28, 1.90, sh_z - 1.92), 0.045, 0.06, Color(225, 185, 35, 255), roughness=0.5)
    _draw_cylinder(Vector3(sh_x + 0.28, 1.90, sh_z - 1.78), 0.045, 0.06, Color(225, 185, 35, 255), roughness=0.5)

    # Overturned Archive Box #B-19 with Spilled Magnetic Tapes & Slides on Floor
    _draw_box(Vector3(-9.9, 0.22, -22.5), Vector3(0.48, 0.38, 0.58), Color(175, 145, 105, 255), roughness=0.9)
    _draw_box(Vector3(-9.6, 0.03, -22.1), Vector3(0.52, 0.04, 0.62), Color(165, 135, 95, 255), roughness=0.9)
    for sp_i in range(5):
        sp_x = -9.4 + 0.25 * math.cos(sp_i * 1.3)
        sp_z = -22.3 + 0.28 * math.sin(sp_i * 1.3)
        _draw_cylinder(Vector3(sp_x, 0.02, sp_z), 0.075, 0.025, Color(25, 28, 32, 255), roughness=0.4, metallic=0.7)
        _draw_cylinder(Vector3(sp_x, 0.025, sp_z), 0.025, 0.028, Color(220, 220, 225, 255), roughness=0.3, metallic=0.9)

    # Lowered, wall-spaced cartridge cabinet. The support brackets visibly reach
    # back to the wall, while the shell is pulled forward so its rear plate does not clip.
    rack_x, rack_y, rack_z = CARTRIDGE_RACK_X, CARTRIDGE_RACK_Y, CARTRIDGE_RACK_Z
    rack_dark = Color(26, 32, 36, 255)
    rack_mid = Color(42, 49, 53, 255)
    rack_edge = Color(91, 99, 102, 255)
    rack_inner = Color(7, 11, 14, 255)
    rack_front_x = rack_x + 0.36
    rack_back_x = rack_x - 0.31

    # Two genuine wall brackets and wall plates make the gap look intentional, not floating.
    for bracket_z in (rack_z - 1.16, rack_z + 1.16):
        _draw_box(Vector3(-11.69, rack_y - 0.30, bracket_z), Vector3(0.47, 0.075, 0.085),
                  rack_edge, roughness=0.54, metallic=0.80)
        _draw_box(Vector3(-11.91, rack_y - 0.30, bracket_z), Vector3(0.045, 0.20, 0.16),
                  rack_mid, roughness=0.58, metallic=0.76)
        for sy in (rack_y - 0.36, rack_y - 0.24):
            _draw_cylinder(Vector3(-11.93, sy, bracket_z), 0.018, 0.014, C_OBS_CHROME,
                           roughness=0.28, metallic=0.90)

    # Hollow cabinet shell: rear plate, side walls, top/bottom rails, and visible inner backing.
    _draw_box(Vector3(rack_back_x, rack_y, rack_z), Vector3(0.055, 1.25, 2.78), rack_inner,
              roughness=0.88, metallic=0.22)
    for z_edge in (rack_z - 1.38, rack_z + 1.38):
        _draw_box(Vector3(rack_x + 0.035, rack_y, z_edge), Vector3(0.67, 1.25, 0.075), rack_mid,
                  roughness=0.62, metallic=0.72)
        # Recessed rivets on both uprights.
        for rivet_y in (rack_y - 0.48, rack_y - 0.05, rack_y + 0.40, rack_y + 0.56):
            _draw_cylinder(Vector3(rack_front_x + 0.015, rivet_y, z_edge), 0.015, 0.014,
                           C_OBS_CHROME, roughness=0.28, metallic=0.90)
    _draw_box(Vector3(rack_x + 0.035, rack_y + 0.605, rack_z), Vector3(0.67, 0.065, 2.83),
              rack_edge, roughness=0.45, metallic=0.78)
    _draw_box(Vector3(rack_x + 0.035, rack_y - 0.605, rack_z), Vector3(0.67, 0.065, 2.83),
              rack_edge, roughness=0.52, metallic=0.75)
    _draw_box(Vector3(rack_x - 0.19, rack_y, rack_z), Vector3(0.025, 1.13, 2.62), rack_inner,
              roughness=0.96, metallic=0.08)

    # Three lower shelves with raised lips, separate bays, rubbed paint, and bolt heads.
    for shelf_y in CARTRIDGE_RACK_SHELF_YS:
        _draw_box(Vector3(rack_x + 0.055, shelf_y, rack_z), Vector3(0.58, 0.045, 2.59), rack_edge,
                  roughness=0.57, metallic=0.71)
        _draw_box(Vector3(rack_front_x - 0.025, shelf_y + 0.035, rack_z),
                  Vector3(0.045, 0.055, 2.56), rack_dark, roughness=0.70, metallic=0.52)
        for screw_z in (rack_z - 1.23, rack_z - 0.42, rack_z + 0.42, rack_z + 1.23):
            _draw_cylinder(Vector3(rack_front_x + 0.004, shelf_y + 0.01, screw_z), 0.014, 0.014,
                           C_OBS_CHROME, roughness=0.27, metallic=0.90)

    # Fifteen separate cartridge bodies: four required replacements mixed with eleven
    # unmarked red/blue/green/orange/violet/teal/pink/lime/white/brown/slate spares.
    # The props have colour windows and worn serial marks but NO printed colour names.
    for stock_id, stock_color, row_i, col_i, is_required in CARTRIDGE_STOCK_LAYOUT:
        shelf_y = CARTRIDGE_RACK_SHELF_YS[row_i]
        slot_z = CARTRIDGE_RACK_SLOT_ZS[col_i]
        is_taken = ((ink_cartridges_collected[stock_id] or ink_cartridges_installed[stock_id])
                    if is_required else (spare_cartridges_collected[stock_id] or spare_cartridges_installed[stock_id]))
        # Dark individual cradle remains after a cartridge is removed.
        _draw_box(Vector3(rack_x - 0.01, shelf_y + 0.12, slot_z), Vector3(0.36, 0.25, 0.27),
                  Color(15, 20, 23, 255), roughness=0.74, metallic=0.60)
        if not is_taken:
            cartridge_centre = Vector3(rack_x + 0.105, shelf_y + 0.157, slot_z)
            body = Color(49, 55, 59, 255) if stock_id == "BLACK" else stock_color
            _draw_box(cartridge_centre, Vector3(0.17, 0.235, 0.205), body,
                      roughness=0.48, metallic=0.30)
            # Raised grip cap and a narrow colour window, not a labelled nameplate.
            _draw_box(Vector3(cartridge_centre.x + 0.006, cartridge_centre.y + 0.123, slot_z),
                      Vector3(0.145, 0.023, 0.185), Color(66, 73, 77, 255),
                      roughness=0.43, metallic=0.68)
            _draw_box(Vector3(cartridge_centre.x + 0.091, cartridge_centre.y - 0.005, slot_z),
                      Vector3(0.012, 0.145, 0.14), stock_color,
                      roughness=0.33, metallic=0.18,
                      emissive=Vector3(0.0, 0.018, 0.024) if stock_id == "CYAN" else None)
            # Small worn serial bars communicate that the original labels are illegible.
            for mark_i in range(3):
                _draw_box(Vector3(cartridge_centre.x + 0.093,
                                  cartridge_centre.y - 0.035 - mark_i * 0.025,
                                  slot_z + 0.020),
                          Vector3(0.006, 0.004, 0.050 if mark_i != 1 else 0.031),
                          Color(24, 30, 33, 255), roughness=0.86)
            _draw_box(Vector3(cartridge_centre.x + 0.095, cartridge_centre.y + 0.061, slot_z - 0.073),
                      Vector3(0.006, 0.015, 0.028), Color(190, 193, 183, 255),
                      roughness=0.94)
        else:
            _draw_box(Vector3(rack_x + 0.205, shelf_y + 0.12, slot_z), Vector3(0.012, 0.045, 0.09),
                      Color(38, 45, 49, 255), roughness=0.78, metallic=0.40)

    # Both doors have been left open after evacuation, so the full rack can be inspected.
    draw_pbr_box_rotated(Vector3(rack_x + 0.33, rack_y, rack_z - 1.50),
                         Vector3(0.055, 1.13, 1.13), rack_mid, -73.0,
                         axis=Vector3(0.0, 1.0, 0.0), roughness=0.59, metallic=0.70)
    draw_pbr_box_rotated(Vector3(rack_x + 0.33, rack_y, rack_z + 1.50),
                         Vector3(0.055, 1.13, 1.13), rack_mid, 73.0,
                         axis=Vector3(0.0, 1.0, 0.0), roughness=0.59, metallic=0.70)
    for hinge_z in (rack_z - 1.34, rack_z + 1.34):
        for hinge_y in (rack_y - 0.43, rack_y, rack_y + 0.43):
            _draw_cylinder(Vector3(rack_x + 0.02, hinge_y, hinge_z), 0.023, 0.095, C_OBS_CHROME,
                           roughness=0.26, metallic=0.90)
    # A slim, faded inventory strip has no legible colour names.
    _draw_box(Vector3(rack_front_x + 0.008, rack_y + 0.52, rack_z), Vector3(0.012, 0.045, 0.92),
              Color(29, 35, 38, 255), roughness=0.85)
    for indicator_i in range(9):
        _draw_box(Vector3(rack_front_x + 0.016, rack_y + 0.52,
                          rack_z - 0.39 + indicator_i * 0.098),
                  Vector3(0.007, 0.012, 0.034), Color(86, 93, 92, 255), roughness=0.92)

    # Crusty Amber Chemical Spill Puddle on Floor beneath Cupboards
    _draw_cylinder(Vector3(-11.3, 0.003, -28.9), 0.65, 0.003, Color(165, 110, 25, 220), roughness=0.85)
    _draw_cylinder(Vector3(-11.1, 0.004, -28.7), 0.35, 0.003, Color(195, 135, 35, 240), roughness=0.7)

def draw_observation_calibration_trolley(time_val=0.0, is_powered=False):
    """Compact rolling cart with a live acoustic pickup and calibration display."""
    x, z = 8.00, -32.62
    # Four legs and a rigid frame.
    for ox in (-0.39, 0.39):
        for oz in (-0.31, 0.31):
            _draw_box(Vector3(x + ox, 0.51, z + oz), Vector3(0.055, 0.80, 0.055),
                      C_OBS_METAL_MID, roughness=0.42, metallic=0.80)
            _draw_sphere(Vector3(x + ox, 0.11, z + oz), 0.085, C_OBS_RUBBER, roughness=0.85)
            _draw_cylinder(Vector3(x + ox, 0.11, z + oz), 0.035, 0.09, C_OBS_CHROME,
                           roughness=0.28, metallic=0.88)
    _draw_box(Vector3(x, 0.84, z), Vector3(0.98, 0.075, 0.82), C_OBS_METAL_DARK,
              roughness=0.45, metallic=0.82)
    _draw_box(Vector3(x, 0.28, z), Vector3(0.88, 0.055, 0.72), C_OBS_METAL_MID,
              roughness=0.52, metallic=0.72)

    # Vented signal-processing unit on the lower shelf.
    _draw_box(Vector3(x, 0.53, z + 0.02), Vector3(0.62, 0.34, 0.48), C_OBS_METAL_DARK,
              roughness=0.42, metallic=0.70)
    for vi in range(6):
        _draw_box(Vector3(x - 0.22 + vi * 0.088, 0.54, z + 0.268),
                  Vector3(0.045, 0.12, 0.012), C_OBS_METAL_EDGE, roughness=0.65, metallic=0.45)

    # Portable display, tactile knobs and status lamps on the top surface.
    _draw_box(Vector3(x - 0.09, 1.13, z + 0.16), Vector3(0.58, 0.46, 0.11),
              C_OBS_METAL_DARK, roughness=0.4, metallic=0.8)
    _draw_box(Vector3(x - 0.09, 1.15, z + 0.221), Vector3(0.46, 0.30, 0.014),
              Color(3, 12, 16, 255), roughness=0.15,
              emissive=Vector3(0.015, 0.10, 0.13) if is_powered else None)
    if is_powered:
        for k in range(7):
            bar_h = 0.07 + 0.13 * (0.5 + 0.5 * math.sin(time_val * 2.8 + k * 0.8))
            _draw_box(Vector3(x - 0.25 + k * 0.052, 1.08 + bar_h * 0.5, z + 0.232),
                      Vector3(0.027, bar_h, 0.008),
                      C_OBS_AMBER_LED if k == 4 else C_OBS_CYAN_LED,
                      roughness=0.2, emissive=Vector3(0.15, 0.48, 0.55) if k != 4 else Vector3(0.52, 0.20, 0.015))
    for ki in range(3):
        _draw_cylinder(Vector3(x + 0.23, 0.99, z - 0.08 + ki * 0.16), 0.045, 0.035,
                       C_OBS_CHROME, roughness=0.24, metallic=0.92)
    # Upright calibration pickup mast and sensor head.
    _draw_cylinder(Vector3(x + 0.29, 1.38, z - 0.22), 0.026, 0.66,
                   C_OBS_CHROME, roughness=0.25, metallic=0.90)
    _draw_box(Vector3(x + 0.29, 1.76, z - 0.22), Vector3(0.20, 0.16, 0.22),
              C_OBS_METAL_MID, roughness=0.36, metallic=0.78)
    _draw_sphere(Vector3(x + 0.29, 1.76, z - 0.345), 0.055, C_OBS_CYAN_LED,
                 roughness=0.15, emissive=Vector3(0.02, 0.35, 0.45) if is_powered else None)
    # Coiled sensor lead secured to the trolley handle.
    _draw_torus(Vector3(x - 0.28, 0.98, z - 0.22), 0.16, 0.018,
                C_OBS_RUBBER, roughness=0.82)

def draw_observation_center_machinery(time_val=0.0, is_powered=False):
    """Two major mid-room observation machines and a smaller floor pickup mast."""
    dark = Color(20, 24, 28, 255)
    metal = Color(52, 59, 65, 255)
    edge = Color(94, 102, 107, 255)
    rust = Color(103, 56, 35, 255)
    display = Color(5, 22, 28, 255)
    cyan_glow = Vector3(0.02, 0.42, 0.50) if is_powered else None
    amber_glow = Vector3(0.42, 0.20, 0.02) if is_powered else None

    # MACHINE A: Resonance-field correlation platform, middle-left.
    ax, az = -3.80, -27.15
    _draw_box(Vector3(ax, 0.09, az), Vector3(2.62, 0.18, 1.94), dark,
              roughness=0.72, metallic=0.62)
    _draw_box(Vector3(ax, 0.22, az), Vector3(2.45, 0.14, 1.78), edge,
              roughness=0.44, metallic=0.8)
    # Heavy machine body and lower service fascia.
    _draw_box(Vector3(ax, 0.91, az - 0.02), Vector3(2.02, 1.20, 1.48), metal,
              roughness=0.54, metallic=0.68)
    _draw_box(Vector3(ax, 0.42, az + 0.75), Vector3(1.85, 0.24, 0.045), dark,
              roughness=0.7, metallic=0.52)
    for i in range(7):
        _draw_box(Vector3(ax - 0.70 + i * 0.23, 0.43, az + 0.78),
                  Vector3(0.09, 0.035, 0.018), edge, roughness=0.65, metallic=0.55)
    # Four structural posts form an instrument gantry above the cabinet.
    for dx in (-0.88, 0.88):
        for dz in (-0.55, 0.52):
            _draw_box(Vector3(ax + dx, 1.82, az + dz), Vector3(0.10, 1.52, 0.10), dark,
                      roughness=0.48, metallic=0.80)
            _draw_box(Vector3(ax + dx, 1.78, az + dz + 0.055), Vector3(0.025, 1.20, 0.018), edge,
                      roughness=0.36, metallic=0.86)
    _draw_box(Vector3(ax, 2.57, az - 0.02), Vector3(2.00, 0.12, 1.36), edge,
              roughness=0.46, metallic=0.8)
    _draw_box(Vector3(ax, 2.63, az - 0.02), Vector3(1.72, 0.045, 1.08), dark,
              roughness=0.58, metallic=0.65)
    # Resonance coils on both sides with stacked toroidal winding rings.
    for sx in (ax - 0.66, ax + 0.66):
        _draw_cylinder(Vector3(sx, 1.53, az + 0.03), 0.22, 0.76, dark,
                       roughness=0.45, metallic=0.76)
        for ry in (1.23, 1.40, 1.57, 1.74, 1.89):
            _draw_torus(Vector3(sx, ry, az + 0.03), 0.205, 0.026, C_OBS_CYAN_LED if ry == 1.57 and is_powered else edge,
                        roughness=0.25, metallic=0.78,
                        emissive=cyan_glow if ry == 1.57 else None)
    # Main front display and analogue controls.
    _draw_box(Vector3(ax, 1.31, az + 0.765), Vector3(0.94, 0.42, 0.035), dark,
              roughness=0.42, metallic=0.6)
    _draw_box(Vector3(ax, 1.32, az + 0.79), Vector3(0.82, 0.30, 0.015), display,
              roughness=0.2, metallic=0.25,
              emissive=Vector3(0.02, 0.12, 0.16) if is_powered else None)
    for i, h in enumerate((0.07, 0.14, 0.10, 0.21, 0.16, 0.25, 0.12, 0.18)):
        _draw_box(Vector3(ax - 0.33 + i * 0.095, 1.22 + h * 0.5, az + 0.802),
                  Vector3(0.035, h, 0.008), C_OBS_CYAN_LED if i % 3 else C_OBS_AMBER_LED,
                  roughness=0.25,
                  emissive=cyan_glow if i % 3 else amber_glow)
    for i in range(4):
        _draw_cylinder(Vector3(ax - 0.48 + i * 0.32, 0.62, az + 0.79), 0.045, 0.035,
                       C_OBS_STEEL, roughness=0.3, metallic=0.88)
    _draw_box(Vector3(ax - 0.84, 0.70, az + 0.80), Vector3(0.11, 0.06, 0.016), C_OBS_RED_LED,
              roughness=0.24, emissive=Vector3(0.5, 0.025, 0.02) if is_powered else None)
    # Cable glands at the rear and low bundled links to the floor trough.
    for side_dx in (-0.70, 0.70):
        _draw_cylinder(Vector3(ax + side_dx, 0.48, az - 0.79), 0.065, 0.18, dark,
                       roughness=0.83, metallic=0.3)
        _draw_box(Vector3(ax + side_dx, 0.06, az - 1.18), Vector3(0.08, 0.08, 0.68),
                  Color(15, 18, 20, 255), roughness=0.95)
    # Rust runoffs on casing and a small yellow service label.
    _draw_box(Vector3(ax - 0.96, 0.98, az + 0.756), Vector3(0.018, 0.34, 0.008), rust,
              roughness=0.98, metallic=0.15)
    _draw_box(Vector3(ax + 0.63, 1.66, az + 0.755), Vector3(0.24, 0.10, 0.012), C_OBS_WARNING,
              roughness=0.7)

    # MACHINE B: Optical triangulation / motion tracking assembly, middle-right.
    bx, bz = 3.78, -28.00
    _draw_box(Vector3(bx, 0.09, bz), Vector3(2.50, 0.18, 2.12), dark,
              roughness=0.72, metallic=0.65)
    _draw_box(Vector3(bx, 0.22, bz), Vector3(2.34, 0.13, 1.96), edge,
              roughness=0.45, metallic=0.8)
    for dx in (-0.92, 0.92):
        _draw_box(Vector3(bx + dx, 0.34, bz), Vector3(0.08, 0.20, 1.68), dark,
                  roughness=0.48, metallic=0.82)
    _draw_box(Vector3(bx, 0.85, bz), Vector3(1.56, 1.08, 1.24), metal,
              roughness=0.52, metallic=0.7)
    # Recessed front diagnostics panel with status bars.
    _draw_box(Vector3(bx, 0.93, bz + 0.638), Vector3(0.86, 0.48, 0.035), dark,
              roughness=0.4, metallic=0.65)
    _draw_box(Vector3(bx, 0.94, bz + 0.66), Vector3(0.72, 0.35, 0.012), display,
              roughness=0.2, metallic=0.25)
    for row in range(3):
        for col in range(5):
            led_col = C_OBS_CYAN_LED if (row + col) % 3 else C_OBS_AMBER_LED
            _draw_box(Vector3(bx - 0.24 + col * 0.12, 0.84 + row * 0.085, bz + 0.671),
                      Vector3(0.045, 0.025, 0.007), led_col, roughness=0.2,
                      emissive=cyan_glow if led_col == C_OBS_CYAN_LED else amber_glow)
    # Tracking mast and cross-arm.
    _draw_cylinder(Vector3(bx, 1.72, bz - 0.06), 0.13, 1.04, dark,
                   roughness=0.37, metallic=0.84)
    _draw_cylinder(Vector3(bx, 1.72, bz - 0.06), 0.07, 1.00, edge,
                   roughness=0.27, metallic=0.9)
    _draw_box(Vector3(bx, 2.25, bz - 0.06), Vector3(1.76, 0.14, 0.16), dark,
              roughness=0.43, metallic=0.8)
    _draw_box(Vector3(bx - 0.70, 2.25, bz - 0.06), Vector3(0.28, 0.20, 0.25), metal,
              roughness=0.42, metallic=0.72)
    _draw_box(Vector3(bx + 0.70, 2.25, bz - 0.06), Vector3(0.28, 0.20, 0.25), metal,
              roughness=0.42, metallic=0.72)
    # Two optical sensor heads facing the viewing-window axis.
    for sx in (bx - 0.72, bx + 0.72):
        _draw_cylinder(Vector3(sx, 2.12, bz + 0.10), 0.105, 0.26, dark,
                       roughness=0.38, metallic=0.75)
        _draw_cylinder(Vector3(sx, 2.12, bz + 0.245), 0.073, 0.045, C_OBS_CYAN_LED,
                       roughness=0.18, metallic=0.42, emissive=cyan_glow)
        _draw_torus(Vector3(sx, 2.12, bz + 0.17), 0.09, 0.014, edge,
                    roughness=0.22, metallic=0.9)
    _draw_sphere(Vector3(bx, 2.30, bz + 0.06), 0.15, metal, roughness=0.3, metallic=0.85)
    _draw_sphere(Vector3(bx, 2.30, bz + 0.18), 0.075, C_OBS_AMBER_LED,
                 roughness=0.18, emissive=amber_glow)
    # Rear cooling slots, service plugs, and a cable lead that stays at floor level.
    for i in range(5):
        _draw_box(Vector3(bx - 0.42 + i * 0.21, 0.57, bz - 0.63),
                  Vector3(0.11, 0.018, 0.012), dark, roughness=0.9)
    _draw_box(Vector3(bx - 0.75, 0.05, bz + 0.95), Vector3(0.07, 0.07, 0.62),
              Color(16, 19, 21, 255), roughness=0.94)
    _draw_box(Vector3(bx - 0.75, 0.05, bz + 1.22), Vector3(0.07, 0.07, 0.34),
              Color(42, 43, 41, 255), roughness=0.94)

    # MACHINE C: low central passive resonance pickup mast. It sits between
    # the two larger machines and is deliberately slim to retain circulation.
    px, pz = 0.10, -23.65
    _draw_box(Vector3(px, 0.08, pz), Vector3(1.10, 0.16, 0.92), dark,
              roughness=0.72, metallic=0.6)
    _draw_box(Vector3(px, 0.20, pz), Vector3(0.94, 0.10, 0.78), edge,
              roughness=0.44, metallic=0.8)
    _draw_cylinder(Vector3(px, 0.95, pz), 0.095, 1.45, metal,
                   roughness=0.36, metallic=0.84)
    _draw_cylinder(Vector3(px, 1.57, pz), 0.18, 0.18, dark,
                   roughness=0.4, metallic=0.78)
    for ry in (1.46, 1.58, 1.70):
        _draw_torus(Vector3(px, ry, pz), 0.20, 0.018,
                    C_OBS_CYAN_LED if ry == 1.58 else edge,
                    roughness=0.24, metallic=0.8,
                    emissive=cyan_glow if ry == 1.58 else None)
    _draw_box(Vector3(px, 1.83, pz), Vector3(0.86, 0.07, 0.09), metal,
              roughness=0.45, metallic=0.75)
    for dx in (-0.35, 0.35):
        _draw_sphere(Vector3(px + dx, 1.83, pz), 0.075, C_OBS_AMBER_LED,
                     roughness=0.2, emissive=amber_glow)

def draw_central_observation_desk_and_litter(time_val=0.0, is_powered=False):
    """A central incident-review table plus grounded scatter and two toppled chairs."""
    dark = Color(22, 26, 30, 255)
    metal = Color(54, 61, 67, 255)
    edge = Color(88, 94, 96, 255)
    wood = Color(49, 52, 51, 255)
    paper = Color(223, 217, 196, 255)
    aged = Color(183, 171, 144, 255)
    rubber = Color(19, 22, 24, 255)
    cx, cz = -3.72, -19.62
    # A larger workbench: longer in X, deeper in Z, and a little taller so it
    # reads as the room's main observation desk rather than a small side table.
    top_y = 1.06
    table_half_x, table_half_z = 2.67, 1.10
    leg_half_x, leg_half_z = 2.43, 0.86
    leg_height = top_y - 0.10
    leg_center_y = leg_height * 0.5
    # Heavy desk legs, cross-braces, foot plates and an aged desktop.
    for x in (cx - leg_half_x, cx + leg_half_x):
        for z in (cz - leg_half_z, cz + leg_half_z):
            _draw_box(Vector3(x, leg_center_y, z), Vector3(0.105, leg_height, 0.105), dark,
                      roughness=0.5, metallic=0.72)
            _draw_box(Vector3(x, 0.025, z), Vector3(0.25, 0.05, 0.22), edge,
                      roughness=0.35, metallic=0.84)
            # Visible mounting shoe and two small bolts on each support foot.
            for bolt_dx in (-0.065, 0.065):
                _draw_cylinder(Vector3(x + bolt_dx, 0.054, z), 0.014, 0.014,
                               C_OBS_CHROME, roughness=0.22, metallic=0.9)
    _draw_box(Vector3(cx, 0.72, cz - leg_half_z), Vector3(4.88, 0.075, 0.075), edge,
              roughness=0.48, metallic=0.72)
    _draw_box(Vector3(cx, 0.72, cz + leg_half_z), Vector3(4.88, 0.075, 0.075), edge,
              roughness=0.48, metallic=0.72)
    _draw_box(Vector3(cx, 0.72, cz), Vector3(0.075, 0.075, 1.65), dark,
              roughness=0.55, metallic=0.72)
    _draw_box(Vector3(cx, top_y, cz), Vector3(5.34, 0.12, 2.20), wood,
              roughness=0.86, metallic=0.14)
    _draw_box(Vector3(cx, top_y + 0.061, cz), Vector3(5.39, 0.025, 2.24), edge,
              roughness=0.56, metallic=0.58)
    # Scuffed front lip and segmented protective metal edge strip.
    _draw_box(Vector3(cx, top_y + 0.015, cz + 1.105), Vector3(5.18, 0.045, 0.045), dark,
              roughness=0.62, metallic=0.66)
    for bolt_x in [cx - 2.45 + i * 0.49 for i in range(11)]:
        _draw_cylinder(Vector3(bolt_x, top_y + 0.076, cz + 1.105), 0.012, 0.012,
                       C_OBS_CHROME, roughness=0.22, metallic=0.9)
    # Worn surface patches, scratches and a dried coffee ring.
    for x, z, w, d, ang in ((cx - 1.25, cz + 0.38, 0.52, 0.18, 14.0),
                            (cx + 0.70, cz - 0.43, 0.42, 0.16, -18.0),
                            (cx + 1.22, cz + 0.20, 0.30, 0.10, 31.0)):
        draw_pbr_box_rotated(Vector3(x, top_y + 0.076, z), Vector3(w, 0.003, d),
                             Color(73, 70, 62, 255), ang, axis=Vector3(0.0, 1.0, 0.0), roughness=0.98)
    _draw_torus(Vector3(cx + 1.16, top_y + 0.077, cz - 0.28), 0.105, 0.012,
                Color(87, 52, 31, 255), roughness=0.98)
    # Main record clipboard, clipped reports and printed observation lines.
    px, pz = cx - 1.03, cz - 0.23
    _draw_box(Vector3(px, top_y + 0.085, pz), Vector3(0.52, 0.028, 0.61), dark,
              roughness=0.63, metallic=0.56)
    _draw_box(Vector3(px, top_y + 0.103, pz), Vector3(0.45, 0.009, 0.54), paper,
              roughness=0.97)
    _draw_box(Vector3(px, top_y + 0.110, pz - 0.24), Vector3(0.17, 0.006, 0.025), edge,
              roughness=0.36, metallic=0.84)
    for i in range(7):
        _draw_box(Vector3(px - 0.04, top_y + 0.111, pz - 0.14 + i * 0.045),
                  Vector3(0.28 if i % 3 else 0.20, 0.002, 0.004),
                  Color(100, 98, 88, 255), roughness=0.98)
    # Loose aged folders, layered paperwork and a partly hanging page.
    fx, fz = cx - 0.70, cz - 0.23  # keep the folder pile left of the new terminal footprint
    for idx, col in enumerate((C_OBS_FOLDER_BLUE, C_OBS_FOLDER_MANILA, C_OBS_FOLDER_RED)):
        draw_pbr_box_rotated(Vector3(fx + idx * 0.045, top_y + 0.083 + idx * 0.012,
                                     fz + idx * 0.025), Vector3(0.42, 0.008, 0.30),
                             col, -8.0 + idx * 7.0, axis=Vector3(0.0, 1.0, 0.0), roughness=0.91)
    _draw_box(Vector3(fx + 0.18, top_y + 0.118, fz + 0.17), Vector3(0.18, 0.005, 0.19), paper,
              roughness=0.97)
    for i in range(4):
        _draw_box(Vector3(fx + 0.15, top_y + 0.122, fz + 0.11 + i * 0.025),
                  Vector3(0.10 + (i % 2) * 0.04, 0.002, 0.004), Color(112, 105, 91, 255), roughness=0.98)
    # Open desktop recorder and a portable resonance meter.
    rx, rz = cx + 0.73, cz + 0.20
    _draw_box(Vector3(rx, top_y + 0.14, rz), Vector3(0.42, 0.14, 0.29), dark,
              roughness=0.52, metallic=0.68)
    _draw_box(Vector3(rx, top_y + 0.215, rz - 0.04), Vector3(0.32, 0.01, 0.15),
              Color(4, 22, 27, 255), roughness=0.2,
              emissive=Vector3(0.02, 0.12, 0.16) if is_powered else None)
    for i in range(4):
        _draw_cylinder(Vector3(rx - 0.12 + i * 0.08, top_y + 0.22, rz + 0.09), 0.018, 0.02,
                       (C_OBS_RED_LED, C_OBS_AMBER_LED, C_OBS_GREEN_LED, C_OBS_CYAN_LED)[i],
                       roughness=0.22)
    # Pen cup, visible pens and a ruler.
    cup_x, cup_z = cx + 1.27, cz + 0.29
    _draw_cylinder(Vector3(cup_x, top_y + 0.17, cup_z), 0.09, 0.18, metal,
                   roughness=0.38, metallic=0.82)
    for i, col in enumerate((C_OBS_RED_LED, C_OBS_FOLDER_BLUE, C_OBS_WARNING, edge)):
        draw_pbr_box_rotated(Vector3(cup_x - 0.045 + i * 0.025, top_y + 0.31,
                                     cup_z - 0.025 + i * 0.012), Vector3(0.018, 0.23, 0.018),
                             col, -8.0 + i * 5.0, axis=Vector3(0.0, 0.0, 1.0), roughness=0.6)
    _draw_box(Vector3(cup_x - 0.20, top_y + 0.085, cup_z - 0.18), Vector3(0.38, 0.008, 0.025),
              C_OBS_CHROME, roughness=0.28, metallic=0.88)
    # Coffee mug and a small tipped sample bottle.
    mug_x, mug_z = cx + 1.20, cz - 0.34
    _draw_cylinder(Vector3(mug_x, top_y + 0.15, mug_z), 0.072, 0.14,
                   Color(180, 181, 174, 255), roughness=0.54)
    _draw_cylinder(Vector3(mug_x, top_y + 0.226, mug_z), 0.055, 0.008,
                   Color(35, 24, 17, 255), roughness=0.94)
    _draw_torus(Vector3(mug_x + 0.085, top_y + 0.16, mug_z), 0.045, 0.012,
                Color(181, 180, 171, 255), roughness=0.55)
    # Little observation sample jars, one with greenish residue, all static props.
    for i, col in enumerate((Color(36, 123, 92, 255), Color(170, 136, 38, 255), Color(65, 82, 137, 255))):
        sx, sz = cx + 0.22 + i * 0.16, cz + 0.47
        _draw_cylinder(Vector3(sx, top_y + 0.095, sz), 0.045, 0.075, col,
                       roughness=0.35, metallic=0.12)
        _draw_cylinder(Vector3(sx, top_y + 0.14, sz), 0.027, 0.025, metal,
                       roughness=0.43, metallic=0.58)
        _draw_cylinder(Vector3(sx, top_y + 0.157, sz), 0.031, 0.012, C_OBS_CHROME,
                       roughness=0.3, metallic=0.82)
    # Cracked sample case, loose access card and headphones.
    _draw_box(Vector3(cx - 0.63, top_y + 0.13, cz + 0.36), Vector3(0.40, 0.11, 0.29),
              Color(42, 47, 49, 255), roughness=0.7, metallic=0.62)
    _draw_box(Vector3(cx - 0.63, top_y + 0.188, cz + 0.36), Vector3(0.34, 0.008, 0.23),
              Color(73, 78, 77, 255), roughness=0.76, metallic=0.50)
    _draw_box(Vector3(cx + 0.18, top_y + 0.082, cz - 0.46), Vector3(0.12, 0.006, 0.08),
              Color(219, 194, 61, 255), roughness=0.86)
    _draw_torus(Vector3(cx + 0.54, top_y + 0.10, cz - 0.35), 0.105, 0.020,
                Color(29, 32, 34, 255), roughness=0.75)
    # Detailed low-poly optical observation microscope on the left end of the desk.
    # This is decorative equipment (no extra inspection prompt), positioned fully
    # inside the expanded desktop footprint.
    mx, mz = cx - 2.18, cz + 0.47
    microscope_black = Color(23, 27, 30, 255)
    microscope_metal = Color(91, 100, 104, 255)
    lens_glass = Color(22, 137, 154, 255)
    # Heavy cast base, rubber feet, and serial plate.
    _draw_box(Vector3(mx, top_y + 0.105, mz), Vector3(0.64, 0.075, 0.43), microscope_black,
              roughness=0.52, metallic=0.65)
    for fx in (-0.25, 0.25):
        for fz in (-0.15, 0.15):
            _draw_box(Vector3(mx + fx, top_y + 0.068, mz + fz), Vector3(0.09, 0.018, 0.08), rubber,
                      roughness=0.92, metallic=0.12)
    _draw_box(Vector3(mx - 0.18, top_y + 0.148, mz - 0.185), Vector3(0.22, 0.018, 0.025),
              C_OBS_WARNING, roughness=0.72)
    # Vertical stand and rear support column.
    _draw_box(Vector3(mx + 0.20, top_y + 0.345, mz - 0.055), Vector3(0.10, 0.48, 0.11),
              microscope_metal, roughness=0.42, metallic=0.82)
    draw_pbr_box_rotated(Vector3(mx + 0.105, top_y + 0.50, mz + 0.025),
                         Vector3(0.12, 0.43, 0.13), microscope_black, 12.0,
                         axis=Vector3(1.0, 0.0, 0.0), roughness=0.46, metallic=0.75)
    # Stage platform, slide clamp and glass sample slide.
    _draw_box(Vector3(mx + 0.015, top_y + 0.255, mz + 0.105), Vector3(0.40, 0.045, 0.35),
              microscope_metal, roughness=0.42, metallic=0.8)
    _draw_box(Vector3(mx + 0.015, top_y + 0.283, mz + 0.105), Vector3(0.24, 0.008, 0.19),
              Color(32, 49, 53, 255), roughness=0.22, metallic=0.35)
    _draw_box(Vector3(mx + 0.015, top_y + 0.290, mz + 0.105), Vector3(0.13, 0.006, 0.09),
              Color(100, 180, 167, 255), roughness=0.25, metallic=0.20)
    _draw_box(Vector3(mx - 0.18, top_y + 0.29, mz + 0.10), Vector3(0.045, 0.045, 0.16),
              C_OBS_CHROME, roughness=0.25, metallic=0.9)
    # Head housing and angled eyepiece tube.
    _draw_box(Vector3(mx + 0.015, top_y + 0.55, mz + 0.045), Vector3(0.40, 0.15, 0.25),
              microscope_black, roughness=0.48, metallic=0.64)
    draw_pbr_box_rotated(Vector3(mx + 0.015, top_y + 0.665, mz + 0.155),
                         Vector3(0.12, 0.26, 0.12), microscope_metal, 22.0,
                         axis=Vector3(1.0, 0.0, 0.0), roughness=0.36, metallic=0.82)
    _draw_cylinder(Vector3(mx + 0.015, top_y + 0.785, mz + 0.205), 0.074, 0.06,
                   microscope_black, roughness=0.40, metallic=0.7)
    _draw_cylinder(Vector3(mx + 0.015, top_y + 0.818, mz + 0.205), 0.052, 0.025,
                   lens_glass, roughness=0.18, metallic=0.42)
    # Revolving objective turret and three different objective barrels.
    _draw_cylinder(Vector3(mx + 0.02, top_y + 0.475, mz + 0.105), 0.105, 0.055,
                   C_OBS_STEEL, roughness=0.28, metallic=0.88)
    for oi, ox in enumerate((-0.075, 0.0, 0.075)):
        _draw_cylinder(Vector3(mx + 0.02 + ox, top_y + 0.405, mz + 0.13),
                       0.026 if oi != 1 else 0.032, 0.12,
                       C_OBS_CHROME if oi == 1 else microscope_metal,
                       roughness=0.24, metallic=0.84)
        _draw_cylinder(Vector3(mx + 0.02 + ox, top_y + 0.345, mz + 0.13), 0.018, 0.015,
                       lens_glass if oi == 1 else dark, roughness=0.2, metallic=0.42)
    # Focusing knobs on the side of the frame.
    for ky, kr in ((top_y + 0.36, 0.055), (top_y + 0.45, 0.038)):
        _draw_sphere(Vector3(mx + 0.275, ky, mz - 0.055), kr, C_OBS_STEEL,
                     roughness=0.32, metallic=0.85)
    _draw_box(Vector3(mx + 0.27, top_y + 0.31, mz - 0.05), Vector3(0.045, 0.09, 0.09), dark,
              roughness=0.72, metallic=0.58)
    # Nearby specimen slide rack, calibration ruler, and magnifier.
    rack_x, rack_z = cx + 0.70, cz + 0.68
    _draw_box(Vector3(rack_x, top_y + 0.10, rack_z), Vector3(0.57, 0.065, 0.24), dark,
              roughness=0.55, metallic=0.72)
    for ri, rcol in enumerate((Color(66, 133, 129, 255), Color(181, 173, 145, 255),
                               Color(97, 107, 143, 255), Color(57, 119, 104, 255))):
        _draw_box(Vector3(rack_x - 0.19 + ri * 0.125, top_y + 0.143, rack_z),
                  Vector3(0.085, 0.018, 0.15), rcol, roughness=0.34, metallic=0.22)
        _draw_box(Vector3(rack_x - 0.19 + ri * 0.125, top_y + 0.154, rack_z - 0.025),
                  Vector3(0.035, 0.003, 0.06), Color(210, 220, 210, 255), roughness=0.28)
    _draw_box(Vector3(cx + 1.72, top_y + 0.092, cz + 0.55), Vector3(0.44, 0.012, 0.055),
              C_OBS_CHROME, roughness=0.25, metallic=0.9)
    _draw_torus(Vector3(cx + 1.76, top_y + 0.13, cz + 0.39), 0.085, 0.012,
                C_OBS_CHROME, roughness=0.25, metallic=0.9)
    _draw_box(Vector3(cx + 1.90, top_y + 0.075, cz + 0.32), Vector3(0.24, 0.018, 0.13),
              C_OBS_FOLDER_MANILA, roughness=0.93)
    for line_i in range(3):
        _draw_box(Vector3(cx + 1.90, top_y + 0.086, cz + 0.28 + line_i * 0.028),
                  Vector3(0.16 - 0.02 * (line_i % 2), 0.002, 0.004),
                  Color(103, 99, 86, 255), roughness=0.98)

    # Tipped steel waste bin under table edge, with two crumpled-paper shapes.
    _draw_cylinder(Vector3(cx + 1.15, 0.20, cz + 0.92), 0.19, 0.38, dark,
                   roughness=0.8, metallic=0.55)
    _draw_cylinder(Vector3(cx + 1.15, 0.02, cz + 0.92), 0.20, 0.025, metal,
                   roughness=0.65, metallic=0.5)
    for i in range(2):
        _draw_sphere(Vector3(cx + 1.12 + i * 0.12, 0.10, cz + 0.91 + i * 0.07),
                     0.065, aged, roughness=0.98)

    # Two fallen operator chairs: low silhouettes, scuffed wheels and exposed seat foam.
    # Chair A lies beside the desk at the west edge; nothing is interactable.
    ax, az = -7.05, -21.05
    _draw_cylinder(Vector3(ax, 0.045, az), 0.07, 0.07, edge, roughness=0.30, metallic=0.82)
    for ang in (12.0, 84.0, 155.0, 226.0, 298.0):
        a = math.radians(ang)
        draw_pbr_box_rotated(Vector3(ax + math.cos(a) * 0.25, 0.045, az + math.sin(a) * 0.25),
                             Vector3(0.35, 0.035, 0.045), edge, -ang,
                             axis=Vector3(0.0, 1.0, 0.0), roughness=0.58, metallic=0.78)
        _draw_cylinder(Vector3(ax + math.cos(a) * 0.43, 0.028, az + math.sin(a) * 0.43),
                       0.036, 0.035, rubber, roughness=0.85)
    draw_pbr_box_rotated(Vector3(ax, 0.17, az), Vector3(0.60, 0.13, 0.56),
                         Color(37, 43, 49, 255), -9.0, axis=Vector3(0.0, 0.0, 1.0),
                         roughness=0.88)
    _draw_box(Vector3(ax - 0.08, 0.195, az + 0.06), Vector3(0.20, 0.015, 0.18),
              Color(204, 183, 60, 255), roughness=0.94)
    draw_pbr_box_rotated(Vector3(ax + 0.04, 0.12, az + 0.38), Vector3(0.52, 0.09, 0.65),
                         Color(29, 34, 39, 255), -16.0, axis=Vector3(1.0, 0.0, 0.0),
                         roughness=0.90)
    # Chair B is a visitor chair overturned onto its side near the east wall.
    bx, bz = 7.62, -23.0
    draw_pbr_box_rotated(Vector3(bx, 0.18, bz), Vector3(0.58, 0.11, 0.52), metal,
                         64.0, axis=Vector3(0.0, 0.0, 1.0), roughness=0.85, metallic=0.55)
    draw_pbr_box_rotated(Vector3(bx + 0.26, 0.31, bz + 0.06), Vector3(0.54, 0.10, 0.12),
                         edge, -18.0, axis=Vector3(0.0, 0.0, 1.0), roughness=0.65, metallic=0.7)
    for i in range(4):
        draw_pbr_box_rotated(Vector3(bx + (i % 2) * 0.34, 0.10, bz - 0.20 + (i // 2) * 0.37),
                             Vector3(0.05, 0.23, 0.05), edge, 18.0 + i * 7.0,
                             axis=Vector3(0.0, 0.0, 1.0), roughness=0.55, metallic=0.78)
    # More scattered abandoned papers and equipment cases around the floor perimeter.
    floor_scatter = [
        (-7.55, -20.30, 23.0, paper), (-6.86, -20.08, -16.0, aged),
        (-1.58, -18.62, 8.0, paper), (-1.22, -18.92, -27.0, aged),
        (-7.42, -23.10, -33.0, paper), (-7.10, -23.38, 12.0, aged),
        (7.95, -24.15, -22.0, paper), (8.32, -24.40, 19.0, aged),
        (6.88, -26.05, 31.0, paper), (7.12, -26.32, -8.0, aged),
        (4.95, -21.90, -11.0, paper), (-6.70, -26.10, 15.0, aged),
    ]
    for x, z, ang, col in floor_scatter:
        draw_pbr_box_rotated(Vector3(x, 0.018, z), Vector3(0.27, 0.006, 0.19), col,
                             ang, axis=Vector3(0.0, 1.0, 0.0), roughness=0.98)
        _draw_box(Vector3(x - 0.015, 0.022, z - 0.035), Vector3(0.14, 0.002, 0.004),
                  Color(104, 99, 87, 255), roughness=0.98)
    # Two little fallen cases and a bottle add a story without filling the traversal lane.
    _draw_box(Vector3(-7.18, 0.10, -24.08), Vector3(0.44, 0.18, 0.32), dark,
              roughness=0.70, metallic=0.48)
    _draw_box(Vector3(-7.18, 0.19, -24.08), Vector3(0.40, 0.018, 0.28), edge,
              roughness=0.62, metallic=0.60)
    draw_pbr_box_rotated(Vector3(8.55, 0.085, -25.63), Vector3(0.33, 0.16, 0.22),
                         Color(65, 55, 41, 255), -14.0, axis=Vector3(0.0, 1.0, 0.0),
                         roughness=0.88)
    draw_pbr_box_rotated(Vector3(8.25, 0.045, -25.92), Vector3(0.20, 0.02, 0.26),
                         Color(22, 25, 27, 255), 41.0, axis=Vector3(0.0, 1.0, 0.0),
                         roughness=0.92)
    _draw_cylinder(Vector3(8.64, 0.10, -25.32), 0.04, 0.16, C_OBS_GREEN_LED,
                   roughness=0.52, metallic=0.12)

def draw_observation_machine_detail_pass(time_val=0.0, is_powered=False):
    """Mechanical refinements for the three existing observation machines."""
    dark = Color(18, 22, 25, 255)
    metal = Color(71, 78, 83, 255)
    edge = Color(112, 120, 124, 255)
    rubber = Color(18, 20, 22, 255)
    rust = Color(112, 60, 35, 255)
    cyan = Vector3(0.02, 0.38, 0.46) if is_powered else None
    amber = Vector3(0.35, 0.16, 0.015) if is_powered else None

    # MACHINE A — resonance-field correlation platform (front faces +Z).
    ax, az = -3.80, -27.15
    # Heavy corner braces, bolt heads and a front service rail.
    for dx in (-1.12, -0.70, 0.70, 1.12):
        _draw_box(Vector3(ax + dx, 0.30, az + 0.80), Vector3(0.10, 0.055, 0.10), dark,
                  roughness=0.55, metallic=0.78)
        _draw_sphere(Vector3(ax + dx, 0.31, az + 0.858), 0.025, C_OBS_CHROME,
                     roughness=0.22, metallic=0.92)
    _draw_box(Vector3(ax, 0.55, az + 0.83), Vector3(1.78, 0.045, 0.04), edge,
              roughness=0.42, metallic=0.76)
    # Cooling fins across the two side panels.
    for side in (-1, 1):
        sx = ax + side * 1.03
        for vi in range(7):
            _draw_box(Vector3(sx, 0.62 + vi * 0.105, az - 0.27), Vector3(0.022, 0.035, 0.74),
                      dark, roughness=0.90, metallic=0.42)
        _draw_box(Vector3(sx + side * 0.012, 1.08, az - 0.27), Vector3(0.028, 0.035, 0.82), rust,
                  roughness=0.96, metallic=0.18)
        # Lower rubber vibration-isolator feet.
        for dz in (-0.53, 0.52):
            _draw_cylinder(Vector3(ax + side * 0.96, 0.20, az + dz), 0.085, 0.16, rubber,
                           roughness=0.92, metallic=0.2)
            _draw_cylinder(Vector3(ax + side * 0.96, 0.20, az + dz), 0.043, 0.17, edge,
                           roughness=0.32, metallic=0.85)
    # Fine control strip with switches, toggles and status indicators.
    for i in range(9):
        bx = ax - 0.72 + i * 0.18
        col = C_OBS_RED_LED if i in (2, 7) else (C_OBS_CYAN_LED if i % 2 else C_OBS_AMBER_LED)
        _draw_box(Vector3(bx, 0.69, az + 0.824), Vector3(0.075, 0.055, 0.020), dark,
                  roughness=0.45, metallic=0.7)
        _draw_box(Vector3(bx, 0.715, az + 0.840), Vector3(0.033, 0.018, 0.009), col,
                  roughness=0.2, emissive=cyan if col == C_OBS_CYAN_LED else amber if col == C_OBS_AMBER_LED else None)
        _draw_box(Vector3(bx, 0.79, az + 0.834), Vector3(0.018, 0.12, 0.018), edge,
                  roughness=0.42, metallic=0.84)
    # Instrument rating plate and a red isolation-stop paddle.
    _draw_box(Vector3(ax + 0.65, 1.72, az + 0.82), Vector3(0.36, 0.20, 0.022), metal,
              roughness=0.62, metallic=0.62)
    _draw_box(Vector3(ax + 0.65, 1.72, az + 0.836), Vector3(0.26, 0.035, 0.008),
              C_OBS_WARNING, roughness=0.68)
    _draw_box(Vector3(ax - 0.78, 0.98, az + 0.82), Vector3(0.14, 0.20, 0.05), dark,
              roughness=0.45, metallic=0.72)
    _draw_box(Vector3(ax - 0.78, 1.02, az + 0.86), Vector3(0.07, 0.12, 0.025), C_OBS_RED_LED,
              roughness=0.4, emissive=Vector3(0.28, 0.015, 0.01) if is_powered else None)
    # Extra gantry rails, clamp blocks and insulated leads feeding the coils.
    for side in (-1, 1):
        _draw_box(Vector3(ax + side * 0.90, 2.05, az + 0.58), Vector3(0.075, 0.12, 0.22), edge,
                  roughness=0.38, metallic=0.86)
        _draw_box(Vector3(ax + side * 0.90, 2.11, az + 0.68), Vector3(0.045, 0.035, 0.05), rust,
                  roughness=0.95, metallic=0.2)
        _draw_box(Vector3(ax + side * 0.52, 0.38, az - 0.88), Vector3(0.08, 0.075, 0.36), rubber,
                  roughness=0.94)
        _draw_box(Vector3(ax + side * 0.52, 0.15, az - 1.02), Vector3(0.08, 0.05, 0.48), metal,
                  roughness=0.62, metallic=0.5)

    # MACHINE B — optical triangulation / motion tracker.
    bx, bz = 3.78, -28.00
    # Armor corner plates and bolt heads on the chassis.
    for dx in (-1.05, 1.05):
        for dz in (-0.82, 0.82):
            _draw_box(Vector3(bx + dx, 0.36, bz + dz), Vector3(0.13, 0.20, 0.13), dark,
                      roughness=0.58, metallic=0.68)
            _draw_sphere(Vector3(bx + dx, 0.40, bz + dz + 0.075), 0.025, C_OBS_CHROME,
                         roughness=0.22, metallic=0.9)
    # Cooling louvers on each side of the lower housing.
    for side in (-1, 1):
        sx = bx + side * 0.80
        for li in range(6):
            _draw_box(Vector3(sx, 0.54 + li * 0.105, bz + 0.635), Vector3(0.06, 0.025, 0.012),
                      edge, roughness=0.74, metallic=0.52)
    # Detailed square optics on the forward faces of both tracking heads.
    for hx in (bx - 0.72, bx + 0.72):
        _draw_box(Vector3(hx, 2.12, bz + 0.30), Vector3(0.26, 0.27, 0.045), dark,
                  roughness=0.36, metallic=0.76)
        _draw_box(Vector3(hx, 2.12, bz + 0.326), Vector3(0.17, 0.18, 0.018), edge,
                  roughness=0.30, metallic=0.86)
        _draw_box(Vector3(hx, 2.12, bz + 0.338), Vector3(0.105, 0.12, 0.012),
                  Color(4, 24, 30, 255), roughness=0.18, metallic=0.32,
                  emissive=cyan)
        _draw_box(Vector3(hx, 2.12, bz + 0.346), Vector3(0.025, 0.085, 0.008),
                  C_OBS_CYAN_LED, roughness=0.18, emissive=cyan)
        for ox in (-0.095, 0.095):
            for oy in (-0.095, 0.095):
                _draw_sphere(Vector3(hx + ox, 2.12 + oy, bz + 0.355), 0.012, C_OBS_CHROME,
                             roughness=0.2, metallic=0.92)
    # Tracking arm collars, braces, cable conduit and a calibration scale on the beam.
    for hx in (bx - 0.70, bx + 0.70):
        _draw_box(Vector3(hx, 2.25, bz - 0.06), Vector3(0.34, 0.24, 0.22), metal,
                  roughness=0.48, metallic=0.78)
        _draw_box(Vector3(hx, 2.38, bz - 0.06), Vector3(0.22, 0.025, 0.18), rust,
                  roughness=0.94, metallic=0.24)
        _draw_box(Vector3(hx, 1.90, bz - 0.08), Vector3(0.07, 0.40, 0.07), edge,
                  roughness=0.35, metallic=0.85)
    for ti in range(9):
        _draw_box(Vector3(bx - 0.72 + ti * 0.18, 2.33, bz + 0.025), Vector3(0.018, 0.028, 0.012),
                  C_OBS_WARNING if ti in (0, 8) else edge, roughness=0.5, metallic=0.65)
    _draw_box(Vector3(bx + 0.52, 0.63, bz + 0.655), Vector3(0.28, 0.12, 0.025), dark,
              roughness=0.5, metallic=0.65)
    for bi in range(4):
        _draw_box(Vector3(bx + 0.43 + bi * 0.06, 0.64, bz + 0.672), Vector3(0.025, 0.045, 0.009),
                  C_OBS_CYAN_LED if bi != 2 else C_OBS_RED_LED, roughness=0.22,
                  emissive=cyan if bi != 2 else (Vector3(0.25, 0.01, 0.01) if is_powered else None))
    # A protected cable leaves the sensor frame and drops to a floor-level connector.
    _draw_box(Vector3(bx + 0.96, 1.36, bz - 0.40), Vector3(0.045, 0.60, 0.045), rubber,
              roughness=0.92)
    _draw_box(Vector3(bx + 0.82, 1.05, bz - 0.40), Vector3(0.30, 0.045, 0.045), rubber,
              roughness=0.92)
    _draw_box(Vector3(bx + 0.70, 0.28, bz - 0.40), Vector3(0.22, 0.13, 0.16), dark,
              roughness=0.62, metallic=0.62)
    _draw_box(Vector3(bx + 0.70, 0.32, bz - 0.315), Vector3(0.08, 0.04, 0.012), C_OBS_AMBER_LED,
              roughness=0.24, emissive=amber)

    # MACHINE C — passive resonance pickup mast.
    px, pz = 0.10, -23.65
    # Four base anchor bolts and protective corner blocks.
    for dx in (-0.42, 0.42):
        for dz in (-0.32, 0.32):
            _draw_box(Vector3(px + dx, 0.205, pz + dz), Vector3(0.15, 0.045, 0.15), dark,
                      roughness=0.58, metallic=0.76)
            _draw_sphere(Vector3(px + dx, 0.233, pz + dz), 0.027, C_OBS_CHROME,
                         roughness=0.22, metallic=0.92)
    # Segmented collars at mast joints and a small service plate on the base.
    for band_y, band_h in ((0.62, 0.065), (1.02, 0.045), (1.32, 0.055), (1.73, 0.045)):
        _draw_cylinder(Vector3(px, band_y + band_h * 0.5, pz), 0.115, band_h, edge,
                       roughness=0.34, metallic=0.88)
    _draw_box(Vector3(px + 0.02, 0.36, pz + 0.48), Vector3(0.48, 0.22, 0.025), dark,
              roughness=0.5, metallic=0.68)
    for led_i in range(4):
        _draw_box(Vector3(px - 0.13 + led_i * 0.085, 0.38, pz + 0.50), Vector3(0.035, 0.055, 0.012),
                  (C_OBS_GREEN_LED, C_OBS_CYAN_LED, C_OBS_AMBER_LED, C_OBS_RED_LED)[led_i],
                  roughness=0.22,
                  emissive=(Vector3(0.01, 0.18, 0.03) if led_i == 0 else cyan if led_i == 1 else amber if led_i == 2 else None))
    # Two short sensor arms on the mast with protective caps and cable entry ports.
    for side in (-1, 1):
        _draw_box(Vector3(px + side * 0.25, 1.58, pz), Vector3(0.42, 0.06, 0.08), metal,
                  roughness=0.45, metallic=0.76)
        _draw_box(Vector3(px + side * 0.46, 1.58, pz + 0.015), Vector3(0.11, 0.16, 0.16), dark,
                  roughness=0.42, metallic=0.75)
        _draw_box(Vector3(px + side * 0.46, 1.58, pz + 0.105), Vector3(0.06, 0.07, 0.015),
                  C_OBS_CYAN_LED if side < 0 else C_OBS_AMBER_LED, roughness=0.2,
                  emissive=cyan if side < 0 else amber)
        _draw_cylinder(Vector3(px + side * 0.46, 1.48, pz + 0.015), 0.025, 0.12, rubber,
                       roughness=0.90)
    # Shielded cable conduit from the mast base, with a connector plug and fasteners.
    _draw_box(Vector3(px + 0.38, 0.06, pz + 0.15), Vector3(0.07, 0.07, 0.48), rubber,
              roughness=0.94)
    _draw_box(Vector3(px + 0.38, 0.07, pz + 0.40), Vector3(0.12, 0.09, 0.12), metal,
              roughness=0.56, metallic=0.7)
    _draw_box(Vector3(px + 0.38, 0.105, pz + 0.465), Vector3(0.05, 0.03, 0.018), C_OBS_WARNING,
              roughness=0.7)

