    """Widen the workstation with a dedicated steel printer wing so the printer clears every monitor."""
    # Printer wing moved to the opposite end of the main desk (screen-right in the usual player view).
    cx, cz = 1.74, -16.03
    top_y = 0.92
    width, depth = 1.68, 2.12
    metal_dark = Color(27, 32, 36, 255)
    metal_mid = Color(56, 63, 67, 255)
    edge = Color(91, 99, 103, 255)
