    draw_pbr_box(Vector3(cx, top_y - 0.03, cz), Vector3(width, 0.06, depth), C_OBS_DESK_TOP,
                 roughness=0.46, metallic=0.33)
    draw_pbr_box(Vector3(cx, top_y - 0.04, cz), Vector3(width + 0.045, 0.035, depth + 0.045),
                 C_OBS_STEEL, roughness=0.37, metallic=0.82)
