    draw_pbr_box(Vector3(cx, 0.908, cz - depth * 0.505), Vector3(width - 0.08, 0.018, 0.018),
                 edge, roughness=0.32, metallic=0.84)
    # Four square steel legs with mounting plates and adjustable feet.
