        for lz in (cz - 0.82, cz + 0.82):
            draw_pbr_box(Vector3(lx, 0.43, lz), Vector3(0.075, 0.80, 0.075), metal_dark,
                         roughness=0.48, metallic=0.78)
            draw_pbr_box(Vector3(lx, 0.83, lz), Vector3(0.13, 0.035, 0.13), edge,
                         roughness=0.34, metallic=0.88)
            draw_pbr_cylinder(Vector3(lx, 0.035, lz), 0.052, 0.055, metal_mid,
                              roughness=0.38, metallic=0.82)
