# Exact supply-rack and printer-service UI helpers copied from the isolated Observation Room source.
# They execute inside the Observation Room namespace so cartridge, printer and card states stay linked.
_OBS_CARD_SERVICE_SOURCE = 'def _cartridge_is_collected(stock_id):\n    if stock_id in INK_CARTRIDGE_ORDER:\n        return ink_cartridges_collected.get(stock_id, False)\n    return spare_cartridges_collected.get(stock_id, False)\n\ndef _cartridge_is_installed(stock_id):\n    if stock_id in INK_CARTRIDGE_ORDER:\n        return ink_cartridges_installed.get(stock_id, False)\n    return spare_cartridges_installed.get(stock_id, False)\n\ndef _collect_cartridge(stock_id):\n    if stock_id in INK_CARTRIDGE_ORDER:\n        ink_cartridges_collected[stock_id] = True\n    else:\n        spare_cartridges_collected[stock_id] = True\n\ndef _consume_cartridge_into_printer(stock_id):\n    if stock_id in INK_CARTRIDGE_ORDER:\n        ink_cartridges_collected[stock_id] = False\n        ink_cartridges_installed[stock_id] = True\n    else:\n        spare_cartridges_collected[stock_id] = False\n        spare_cartridges_installed[stock_id] = True\n\ndef _required_colour_ids():\n    return [cid for cid in card_selected_colour_ids if cid in SPARE_CARTRIDGE_IDS]\n\ndef _required_colours_secured():\n    required = _required_colour_ids()\n    return len(required) == 4 and all(_cartridge_is_collected(cid) or _cartridge_is_installed(cid) for cid in required)\n\ndef _required_colours_installed():\n    required = _required_colour_ids()\n    return len(required) == 4 and all(spare_cartridges_installed.get(cid, False) for cid in required)\n\ndef _schedule_printer_print_after_close():\n    """Queue printing three seconds after the completed service panel is closed."""\n    global printer_print_pending, printer_print_wait_timer\n    if (printer_started and not card_keycard_printed and not keycard_inserted\n            and not printer_print_pending and not printer_print_animation_active):\n        printer_print_pending = True\n        printer_print_wait_timer = PRINTER_PRINT_SETTLE_DELAY\n\ndef _close_station_panel():\n    global is_inspecting, active_inspect_item\n    if active_inspect_item and active_inspect_item.get("interaction_kind") == "card_printer":\n        _schedule_printer_print_after_close()\n    is_inspecting = False\n    active_inspect_item = None\n    disable_cursor()\n    spatial_audio.play_ui("click", volume=0.38)\n\ndef _station_panel_frame(title, subtitle):\n    sw, sh = get_screen_width(), get_screen_height()\n    px, py, pw, ph = 36, 38, sw - 72, sh - 76\n    draw_rectangle(0, 0, sw, sh, Color(0, 0, 0, 172))\n    draw_rectangle(px + 5, py + 6, pw, ph, Color(0, 0, 0, 145))\n    draw_rectangle(px, py, pw, ph, Color(8, 17, 23, 252))\n    draw_rectangle_lines(px, py, pw, ph, Color(44, 100, 114, 255))\n    draw_rectangle(px + 1, py + 1, pw - 2, 58, Color(15, 31, 40, 255))\n    draw_rectangle(px + 1, py + 57, pw - 2, 2, Color(31, 192, 203, 255))\n    draw_text("ECHO // CREDENTIAL FABRICATION", px + 22, py + 12, 16, Color(221, 238, 241, 255))\n    draw_text(title, px + 23, py + 34, 10, Color(98, 220, 232, 255))\n    draw_text(subtitle, px + 25, py + 71, 10, Color(145, 172, 181, 255))\n    close_label = "CLOSE  [E / ESC]"\n    draw_text(close_label, px + pw - measure_text(close_label, 10) - 22, py + 19, 10, Color(157, 191, 199, 255))\n    return px, py, pw, ph\n\ndef draw_cartridge_shelf_ui():\n    """Rack inventory: all 15 physical cartridges can be collected, including decoys."""\n    global cartridge_ui_notice\n    mouse = get_mouse_position()\n    px, py, pw, ph = _station_panel_frame(\n        "SUPPLY RACK // 15 CARTRIDGES AVAILABLE",\n        "Every cartridge can be taken. Match the saved four-colour reference; empty cradles remain visible in the room."\n    )\n    margin_x = px + 22\n    top_y = py + 105\n    gap_x, gap_y = 10, 10\n    tile_w = int((pw - 44 - gap_x * 4) / 5)\n    tile_h = 102\n    for idx, (stock_id, swatch, shelf_row, shelf_col, is_base) in enumerate(CARTRIDGE_STOCK_LAYOUT):\n        col_i, row_i = idx % 5, idx // 5\n        x = margin_x + col_i * (tile_w + gap_x)\n        y = top_y + row_i * (tile_h + gap_y)\n        collected = _cartridge_is_collected(stock_id)\n        installed = _cartridge_is_installed(stock_id)\n        hover = x <= mouse.x <= x + tile_w and y <= mouse.y <= y + tile_h\n        fill = Color(16, 31, 39, 255) if not hover else Color(22, 42, 51, 255)\n        border = Color(50, 210, 218, 255) if hover else Color(44, 79, 89, 255)\n        if collected or installed:\n            fill = Color(13, 24, 29, 255)\n            border = Color(39, 66, 73, 255)\n        draw_rectangle(x, y, tile_w, tile_h, fill)\n        draw_rectangle_lines(x, y, tile_w, tile_h, border)\n        draw_rectangle(x + 10, y + 12, 35, 51, swatch)\n        draw_rectangle_lines(x + 10, y + 12, 35, 51, Color(125, 143, 149, 255))\n        name = CARTRIDGE_NAME_BY_ID.get(stock_id, stock_id)\n        draw_text(name, x + 55, y + 13, 10, Color(225, 238, 240, 255))\n        draw_text("BASE STOCK" if is_base else "COLOUR STOCK", x + 55, y + 29, 8, Color(122, 158, 167, 255))\n        if installed:\n            status, status_col = "INSTALLED", Color(88, 221, 167, 255)\n        elif collected:\n            status, status_col = "IN INVENTORY", Color(115, 195, 208, 255)\n        else:\n            status, status_col = "CLICK TO TAKE", Color(198, 211, 214, 255)\n        draw_text(status, x + 55, y + 51, 8, status_col)\n        if hover and is_mouse_button_pressed(MOUSE_BUTTON_LEFT):\n            if installed:\n                cartridge_ui_notice = f"{name} is already installed in the printer."\n            elif collected:\n                cartridge_ui_notice = f"{name} is already in your inventory."\n            else:\n                _collect_cartridge(stock_id)\n                cartridge_ui_notice = f"Collected {name}. Wrong colours can be carried, but the printer will reject them."\n                spatial_audio.play_ui("click", volume=0.47)\n\n    notice_y = py + ph - 42\n    draw_text(cartridge_ui_notice[:112], px + 23, notice_y, 9, Color(128, 204, 211, 255))\n    collected_count = sum(1 for item, _, _, _, _ in CARTRIDGE_STOCK_LAYOUT if _cartridge_is_collected(item) or _cartridge_is_installed(item))\n    counter = f"STOCK COLLECTED  {collected_count:02d} / 15"\n    draw_text(counter, px + pw - measure_text(counter, 9) - 23, notice_y, 9, Color(155, 184, 192, 255))\n\ndef draw_printer_service_ui():\n    """Insert a chosen cartridge into one selected slot; unmatched colours are refused."""\n    global selected_printer_slot, cartridge_ui_notice, printer_started, printer_start_sound_played\n    mouse = get_mouse_position()\n    px, py, pw, ph = _station_panel_frame(\n        "PRINTER SERVICE BAY // FOUR PROFILE-MATCHED RESERVOIRS",\n        "Select a reservoir and insert a carried cartridge. Wrong colours are rejected; when all four match, exit to start printing."\n    )\n    required = _required_colour_ids()\n    zone_names = CARD_COLOUR_ZONE_NAMES\n    slot_gap = 10\n    slot_margin = px + 22\n    slot_w = int((pw - 44 - slot_gap * 3) / 4)\n    slot_h = 100\n    slot_y = py + 96\n    for idx in range(4):\n        x = slot_margin + idx * (slot_w + slot_gap)\n        y = slot_y\n        valid_required = idx < len(required)\n        target_id = required[idx] if valid_required else None\n        target_col = CARTRIDGE_COLOUR_BY_ID.get(target_id, Color(36, 45, 50, 255))\n        fitted = bool(target_id and spare_cartridges_installed.get(target_id, False))\n        selected = selected_printer_slot == idx\n        hover = x <= mouse.x <= x + slot_w and y <= mouse.y <= y + slot_h\n        fill = Color(19, 56, 62, 255) if selected else Color(14, 29, 36, 255)\n        border = Color(68, 226, 233, 255) if selected else (Color(66, 132, 143, 255) if hover else Color(42, 78, 89, 255))\n        draw_rectangle(x, y, slot_w, slot_h, fill)\n        draw_rectangle_lines(x, y, slot_w, slot_h, border)\n        draw_text(f"RESERVOIR 0{idx + 1}", x + 12, y + 10, 9, Color(110, 185, 195, 255))\n        draw_text(zone_names[idx], x + 12, y + 27, 9, Color(224, 237, 239, 255))\n        # Keep the target swatch visible even while empty, matching the permanent terminal reference.\n        draw_rectangle(x + 12, y + 46, 27, 31, target_col)\n        draw_rectangle_lines(x + 12, y + 46, 27, 31, Color(112, 134, 141, 255))\n        name = CARTRIDGE_NAME_BY_ID.get(target_id, "AWAITING DESIGN") if target_id else "AWAITING DESIGN"\n        draw_text(name, x + 49, y + 48, 9, Color(219, 233, 236, 255))\n        state_text = "ACCEPTED" if fitted else ("SELECTED SLOT" if selected else "EMPTY")\n        state_col = Color(88, 222, 166, 255) if fitted else (Color(116, 214, 222, 255) if selected else Color(156, 174, 181, 255))\n        draw_text(state_text, x + 49, y + 64, 8, state_col)\n        if hover and is_mouse_button_pressed(MOUSE_BUTTON_LEFT):\n            selected_printer_slot = idx\n            cartridge_ui_notice = f"Reservoir {idx + 1}: insert the cartridge that matches {zone_names[idx].lower()}."\n            spatial_audio.play_ui("click", volume=0.30)\n\n    inv_title_y = slot_y + slot_h + 14\n    draw_text("CARRIED CARTRIDGES  //  CLICK ONE TO ATTEMPT INSERTION", px + 23, inv_title_y, 9, Color(108, 203, 214, 255))\n    tile_gap_x, tile_gap_y = 8, 7\n    tile_margin = px + 22\n    tile_w = int((pw - 44 - tile_gap_x * 4) / 5)\n    tile_h = 53\n    inv_top = inv_title_y + 20\n    for idx, (stock_id, swatch, shelf_row, shelf_col, is_base) in enumerate(CARTRIDGE_STOCK_LAYOUT):\n        col_i, row_i = idx % 5, idx // 5\n        x = tile_margin + col_i * (tile_w + tile_gap_x)\n        y = inv_top + row_i * (tile_h + tile_gap_y)\n        carried = _cartridge_is_collected(stock_id)\n        installed = _cartridge_is_installed(stock_id)\n        hover = x <= mouse.x <= x + tile_w and y <= mouse.y <= y + tile_h\n        clickable = carried and not installed and not printer_started\n        fill = Color(17, 42, 49, 255) if clickable and hover else (Color(14, 29, 36, 255) if clickable else Color(12, 21, 26, 255))\n        border = Color(56, 210, 218, 255) if clickable and hover else (Color(44, 83, 93, 255) if clickable else Color(34, 55, 62, 255))\n        draw_rectangle(x, y, tile_w, tile_h, fill)\n        draw_rectangle_lines(x, y, tile_w, tile_h, border)\n        draw_rectangle(x + 7, y + 9, 26, 34, swatch)\n        draw_rectangle_lines(x + 7, y + 9, 26, 34, Color(119, 139, 146, 255))\n        name = CARTRIDGE_NAME_BY_ID.get(stock_id, stock_id)\n        draw_text(name, x + 41, y + 8, 9, Color(220, 234, 236, 255) if carried else Color(113, 131, 137, 255))\n        status = "INSTALLED" if installed else ("CARRIED" if carried else "NOT CARRIED")\n        draw_text(status, x + 41, y + 25, 7, Color(86, 219, 164, 255) if installed else (Color(116, 196, 207, 255) if carried else Color(104, 120, 126, 255)))\n        if hover and is_mouse_button_pressed(MOUSE_BUTTON_LEFT) and clickable:\n            if selected_printer_slot >= len(required):\n                cartridge_ui_notice = "This printer requires four distinct custom colours from the saved design."\n            else:\n                target_id = required[selected_printer_slot]\n                expected_name = CARTRIDGE_NAME_BY_ID.get(target_id, "UNKNOWN")\n                if stock_id != target_id:\n                    cartridge_ui_notice = f"REJECTED // {name} does not match this reservoir. Required swatch: {expected_name}. Cartridge retained."\n                    spatial_audio.play_ui("click", volume=0.25)\n                else:\n                    _consume_cartridge_into_printer(stock_id)\n                    cartridge_ui_notice = f"ACCEPTED // {name} cartridge seated in reservoir {selected_printer_slot + 1}."\n                    spatial_audio.play_ui("click", volume=0.52)\n                    if _required_colours_installed() and not printer_started:\n                        # The mission-update chime plays as the objective changes, but the\n                        # printer itself stays quiet until the player exits this panel.\n                        # Startup audio is deliberately deferred until the print animation begins.\n                        printer_started = True\n                        cartridge_ui_notice = "ALL FOUR PROFILE COLOURS ACCEPTED // EXIT SERVICE BAY TO BEGIN PRINTING."\n\n    status_y = py + ph - 42\n    draw_text(cartridge_ui_notice[:132], px + 23, status_y, 9,\n              Color(86, 220, 164, 255) if ("ACCEPTED" in cartridge_ui_notice or "STARTUP" in cartridge_ui_notice) else Color(225, 186, 116, 255))\n    installed_count = sum(1 for cid in required if spare_cartridges_installed.get(cid, False))\n    counter = f"MATCHING RESERVOIRS  {installed_count} / 4"\n    draw_text(counter, px + pw - measure_text(counter, 9) - 23, status_y, 9,\n              Color(86, 220, 164, 255) if installed_count == 4 else Color(154, 184, 192, 255))\n    if printer_started:\n        draw_rectangle(px + pw // 2 - 202, py + ph - 82, 404, 26, Color(14, 61, 47, 255))\n        draw_rectangle_lines(px + pw // 2 - 202, py + ph - 82, 404, 26, Color(63, 205, 147, 255))\n        label = "PRINTER ONLINE // STARTUP COMPLETE"\n        draw_text(label, px + (pw - measure_text(label, 11)) // 2, py + ph - 75, 11, Color(111, 234, 181, 255))\n'
exec(compile(_OBS_CARD_SERVICE_SOURCE, "<observation-card-service-ui>", "exec"), _OBS_ROOM_DETAIL_NS)
_OBS_ROOM_DETAIL_NS.update({
    "selected_printer_slot": 0,
    "cartridge_ui_notice": "Select a cartridge to collect it from the rack.",
    "printer_print_pending": False,
    "printer_print_wait_timer": 0.0,
    "PRINTER_PRINT_SETTLE_DELAY": 3.0,
    "printer_start_sound_played": False,
    "printer_puzzle_started": False,
    "printer_started": False,
    "printer_print_animation_active": False,
    "printer_print_animation_timer": 0.0,
    "PRINTER_PRINT_DURATION": 8.0,
    "card_keycard_printed": False,
    "card_keycard_collected": False,
    "keycard_inserted": False,
    "is_inspecting": False,
    "active_inspect_item": None,
})

# First two computer screens are a custom high-detail presentation; selection/progression and all
# remaining profile/design/reference screens continue using the isolated source implementation.
_OBS_ORIGINAL_COMPUTER_UI = _OBS_ROOM_DETAIL_NS["draw_computer_session_ui"]


def _obs_terminal_button(x, y, w, h, label, mouse, enabled=True, accent=False, font_size=13):
    hover = enabled and x <= mouse.x <= x + w and y <= mouse.y <= y + h
    if not enabled:
        fill = Color(17, 26, 32, 255)
        edge = Color(46, 64, 72, 255)
        text_col = Color(86, 105, 113, 255)
    elif accent:
        fill = Color(22, 91, 77, 255) if hover else Color(13, 57, 51, 255)
        edge = Color(88, 239, 184, 255) if hover else Color(52, 178, 145, 255)
        text_col = Color(232, 255, 248, 255)
    else:
        fill = Color(24, 63, 76, 255) if hover else Color(12, 35, 45, 255)
        edge = Color(69, 223, 233, 255) if hover else Color(41, 106, 121, 255)
        text_col = Color(223, 243, 246, 255)
    draw_rectangle(int(x), int(y), int(w), int(h), fill)
    draw_rectangle(int(x + 1), int(y + 1), int(w - 2), 3, edge)
    draw_rectangle_lines(int(x), int(y), int(w), int(h), edge)
    tw = measure_text(label, font_size)
    draw_text(label, int(x + (w - tw) / 2), int(y + (h - font_size) / 2), font_size, text_col)
    return bool(enabled and hover and is_mouse_button_pressed(MOUSE_BUTTON_LEFT))


def _obs_terminal_base(title, step_index, mouse):
    sw, sh = get_screen_width(), get_screen_height()
    # Restrained interface grid and scanline texture, visible only during the seated interaction.
    draw_rectangle(0, 0, sw, sh, Color(3, 8, 12, 255))
    for gx in range(0, sw, 64):
        draw_line(gx, 78, gx, sh, Color(10, 27, 34, 255))
    for gy in range(88, sh, 40):
        draw_line(0, gy, sw, gy, Color(8, 21, 28, 255))
    draw_rectangle(0, 0, sw, 74, Color(10, 22, 29, 255))
    draw_rectangle(0, 72, sw, 3, Color(0, 203, 218, 255))
    # Left logo mark and terminal identity.
    draw_rectangle(24, 19, 34, 34, Color(10, 48, 58, 255))
    draw_rectangle_lines(24, 19, 34, 34, Color(57, 224, 234, 255))
    draw_line(31, 36, 51, 36, Color(79, 235, 229, 255))
    draw_line(41, 26, 41, 46, Color(79, 235, 229, 255))
    draw_circle_lines(41, 36, 7, Color(79, 235, 229, 255))
    draw_text("ECHO  /  PERSONNEL CREDENTIAL FABRICATOR", 72, 15, 20, Color(226, 242, 244, 255))
    draw_text("OBSERVATION POST  •  LOCAL WORKSTATION  •  SECURE OFFLINE SESSION", 74, 43, 10,
              Color(108, 175, 186, 255))
    # Hardware-style state indicators.
    draw_text("LOCAL LINK", sw - 236, 17, 9, Color(128, 165, 174, 255))
    draw_circle(sw - 164, 22, 4, Color(65, 224, 143, 255))
    draw_text("CONNECTED", sw - 153, 17, 9, Color(123, 221, 177, 255))
    draw_text("AUTH  /  L4", sw - 236, 42, 9, Color(128, 165, 174, 255))
    draw_circle(sw - 164, 47, 4, Color(244, 178, 61, 255))
    draw_text("CREDENTIAL BUILD", sw - 153, 42, 9, Color(218, 186, 117, 255))
    # Main frame, inset line, and breadcrumb.
    px, py, pw, ph = 28, 90, sw - 56, sh - 126
    draw_rectangle(px + 5, py + 7, pw, ph, Color(0, 0, 0, 170))
    draw_rectangle(px, py, pw, ph, Color(7, 17, 23, 250))
    draw_rectangle_lines(px, py, pw, ph, Color(40, 93, 107, 255))
    draw_rectangle_lines(px + 5, py + 5, pw - 10, ph - 10, Color(17, 45, 55, 255))
    # Left workflow rail.
    rail_x, rail_y, rail_w = px + 16, py + 17, 190
    draw_rectangle(rail_x, rail_y, rail_w, ph - 34, Color(8, 22, 29, 255))
    draw_rectangle_lines(rail_x, rail_y, rail_w, ph - 34, Color(33, 75, 87, 255))
    draw_text("WORKFLOW", rail_x + 15, rail_y + 16, 10, Color(77, 200, 211, 255))
    steps = (("01", "IDENTITY", step_index >= 1), ("02", "PORTRAIT", step_index >= 2),
             ("03", "CARD DESIGN", step_index >= 3), ("04", "FABRICATION", step_index >= 4))
    for i, (num, label, active) in enumerate(steps):
        yy = rail_y + 52 + i * 64
        draw_rectangle(rail_x + 12, yy, rail_w - 24, 48,
                       Color(14, 57, 65, 255) if active else Color(10, 29, 37, 255))
        draw_rectangle_lines(rail_x + 12, yy, rail_w - 24, 48,
                             Color(50, 219, 227, 255) if active else Color(29, 63, 73, 255))
        draw_text(num, rail_x + 23, yy + 8, 11, Color(84, 232, 224, 255) if active else Color(79, 119, 130, 255))
        draw_text(label, rail_x + 53, yy + 9, 9, Color(221, 241, 243, 255) if active else Color(114, 144, 153, 255))
        draw_rectangle(rail_x + 22, yy + 31, rail_w - 44, 2,
                       Color(42, 165, 162, 255) if active else Color(27, 49, 57, 255))
    draw_line(rail_x + 14, py + ph - 88, rail_x + rail_w - 14, py + ph - 88, Color(31, 70, 81, 255))
    draw_text("DEVICE ID", rail_x + 15, py + ph - 72, 8, Color(99, 150, 162, 255))
    draw_text("OBS-TERM-04", rail_x + 15, py + ph - 55, 10, Color(207, 226, 230, 255))
    draw_text("AIR-GAPPED", rail_x + 15, py + ph - 34, 8, Color(79, 218, 168, 255))
    # Main work area.
    mx, my, mw, mh = rail_x + rail_w + 18, py + 17, pw - rail_w - 50, ph - 34
    draw_text(title, mx + 6, my + 7, 18, Color(97, 226, 235, 255))
    draw_text("PERSONNEL DATABASE  /  ACCESS CREDENTIAL WORKBENCH", mx + 7, my + 34, 9,
              Color(122, 159, 168, 255))
    draw_line(mx + 6, my + 57, mx + mw - 6, my + 57, Color(37, 82, 94, 255))
    draw_text("SESSION 04.09", mx + mw - 126, my + 8, 8, Color(84, 131, 142, 255))
    # Small right-corner decorative data lines.
    for i, bw in enumerate((44, 28, 38, 22, 48, 31)):
        draw_rectangle(mx + mw - 128 + i * 15, my + 33, 9, 2, Color(33, 121 + i * 7, 133 + i * 5, 255))
    return sw, sh, px, py, pw, ph, rail_x, rail_y, rail_w, mx, my, mw, mh


def draw_observation_computer_ui_host():
    ns = _OBS_ROOM_DETAIL_NS
    stage = ns.get("computer_ui_stage", "home")
    if stage not in ("home", "identity", "profile"):
        _OBS_ORIGINAL_COMPUTER_UI()
        return
    mouse = get_mouse_position()
    if stage == "profile":
        # Dedicated profile-image selection UI, matching the upgraded terminal screens.
        sw, sh, px, py, pw, ph, rx, ry, rw, mx, my, mw, mh = _obs_terminal_base(
            "PORTRAIT  /  SELECT PROFILE IMAGE", 2, mouse)
        draw_text("Choose the employee portrait to encode into the Observation Archive keycard.",
                  mx + 8, my + 65, 10, Color(153, 181, 188, 255))

        profile_options = (
            ("STANDARD / MALE", "PERSONNEL PROFILE A", "BASELINE FACILITY IDENTITY", "PF-A / STANDARD"),
            ("STANDARD / FEMALE", "PERSONNEL PROFILE B", "BASELINE FACILITY IDENTITY", "PF-B / STANDARD"),
            ("NAPOLEON // LEGACY", "HISTORICAL PORTRAIT", "ARCHIVE LEGACY PROFILE", "PF-C / ARCHIVE"),
        )
        selected_idx = int(ns.get("computer_profile_highlight", -1))
        body_x, body_y = mx + 8, my + 91
        left_w = int(mw * 0.735) - 8
        right_x = body_x + left_w + 14
        right_w = mx + mw - right_x - 8
        tile_gap = 12
        tile_w = (left_w - 8 - tile_gap * 2) // 3
        tile_h = min(366, mh - 168)
        tile_y = body_y + 3

        for idx, (label, caption, descriptor, serial) in enumerate(profile_options):
            x = body_x + 3 + idx * (tile_w + tile_gap)
            y = tile_y
            hover = x <= mouse.x <= x + tile_w and y <= mouse.y <= y + tile_h
            selected = selected_idx == idx
            fill = Color(16, 39, 48, 255) if selected else (Color(12, 27, 35, 255) if not hover else Color(18, 38, 46, 255))
            edge = Color(55, 229, 235, 255) if selected else (Color(49, 148, 161, 255) if hover else Color(37, 78, 90, 255))
            draw_rectangle(x, y, tile_w, tile_h, fill)
            draw_rectangle_lines(x, y, tile_w, tile_h, edge)
            draw_rectangle(x + 1, y + 1, tile_w - 2, 29,
                           Color(15, 60, 68, 255) if selected else Color(11, 35, 44, 255))
            draw_text(f"PROFILE 0{idx + 1}", x + 11, y + 10, 8,
                      Color(103, 232, 231, 255) if selected else Color(104, 164, 175, 255))
            if selected:
                badge = "SELECTED"
                draw_text(badge, x + tile_w - measure_text(badge, 8) - 11, y + 10, 8,
                          Color(104, 244, 184, 255))

            portrait_x, portrait_y = x + 12, y + 42
            portrait_w, portrait_h = tile_w - 24, min(218, tile_h - 147)
            draw_rectangle(portrait_x - 5, portrait_y - 5, portrait_w + 10, portrait_h + 10,
                           Color(5, 14, 19, 255))
            draw_rectangle_lines(portrait_x - 5, portrait_y - 5, portrait_w + 10, portrait_h + 10,
                                 Color(60, 111, 123, 255) if selected else Color(31, 63, 73, 255))
            ns["draw_computer_avatar"](portrait_x, portrait_y, portrait_w, portrait_h, idx, hover)

            # Tiny registration marks give each portrait card a more deliberate terminal feel.
            for corner_x, corner_y, dx, dy in (
                (portrait_x - 3, portrait_y - 3, 1, 1),
                (portrait_x + portrait_w + 3, portrait_y - 3, -1, 1),
                (portrait_x - 3, portrait_y + portrait_h + 3, 1, -1),
                (portrait_x + portrait_w + 3, portrait_y + portrait_h + 3, -1, -1),
            ):
                draw_line(corner_x, corner_y, corner_x + 8 * dx, corner_y, edge)
                draw_line(corner_x, corner_y, corner_x, corner_y + 8 * dy, edge)

            name_y = portrait_y + portrait_h + 18
