                ns["computer_identity_imported"] = True
                ns["card_profile_index"] = 2
                ns["computer_profile_highlight"] = 2
                ns["computer_ui_stage"] = "design"
                ns["computer_ui_notice"] = "Napoleon legacy portrait selected. Assign the four custom card colours."
