    draw_text(preview_status, right_x + 15, status_y + 40, 8,
              Color(99, 226, 183, 255) if hovered_source == 2 else Color(140, 182, 190, 255))
    draw_rectangle(right_x + 15, status_y + 61, right_w - 30, 4, Color(19, 54, 63, 255))
    progress = 0.84 if hovered_source == 2 else (0.64 if hovered_source in (0, 1) else 0.34)
    draw_rectangle(right_x + 15, status_y + 61, int((right_w - 30) * progress), 4,
                   Color(66, 207, 197, 255) if hovered_source != 2 else Color(71, 232, 171, 255))
