# HOST RENDERER BRIDGE — v57
# The isolated Observation Room alarm was authored for a 10-light shader (light slots 1–10).
# The combined game shader exposes five shared point-light slots only. Rebind the alarm
# update to those supported slots and let the already-animated red beacon meshes supply
# the corner-siren flashes. This avoids missing `_ceiling_light_on_color`, slot 6, and
# slot 7–10 NameErrors when the five-second lockdown alarm activates.
def _obs_update_emergency_alarm_lighting_renderer(time_val):
    ns = _OBS_ROOM_DETAIL_NS
    if not ns.get("emergency_alarm_active", False):
        return

    shutdown_at = ns.get("security_alarm_shutdown_started_at")
    fade_seconds = max(0.001, float(ns.get("SECURITY_ALARM_FADE_SECONDS", 4.5)))
    if shutdown_at is not None:
        strength = 1.0 - min(1.0, max(0.0, (float(time_val) - float(shutdown_at)) / fade_seconds))
    else:
        strength = 1.0
    strength = max(0.0, min(1.0, strength))
    ns["emergency_alarm_strength"] = strength

    breathe = 0.5 + 0.5 * math.sin(float(time_val) * 3.0)
    strobe = max(0.0, math.sin(float(time_val) * 8.6 + 0.4)) ** 12
    alarm_ambient = Vector3(0.010 + 0.012 * breathe + 0.006 * strobe,
                            0.0010 + 0.0012 * breathe,
                            0.0018 + 0.0020 * breathe)
    normal_ambient = Vector3(0.046, 0.051, 0.060)
    blended_ambient = Vector3(
        normal_ambient.x * (1.0 - strength) + alarm_ambient.x * strength,
        normal_ambient.y * (1.0 - strength) + alarm_ambient.y * strength,
        normal_ambient.z * (1.0 - strength) + alarm_ambient.z * strength,
    )
    set_shader_value(pbr_shader, loc_ambient, blended_ambient, SHADER_UNIFORM_VEC3)

    # Five and only five point-light colour slots exist in the host PBR shader.
    light_colour_locations = (loc_lcol1, loc_lcol2, loc_lcol3, loc_lcol4, loc_lcol5)
    on_colours = (
        Vector3(0.98, 0.94, 0.87), Vector3(0.98, 0.94, 0.87),
        Vector3(0.98, 0.94, 0.87), Vector3(0.98, 0.94, 0.87),
        Vector3(1.02, 0.98, 0.90),
    )
    intensities = ns.get("CEILING_LIGHT_INTENSITIES", (1.0,) * 5)
    for i, light_loc in enumerate(light_colour_locations):
        pulse_a = 0.5 + 0.5 * math.sin(float(time_val) * 3.0 - i * 0.88)
        pulse_b = max(0.0, math.sin(float(time_val) * 8.6 + i * 1.11)) ** 10
        intensity = 0.28 + 0.68 * pulse_a + 0.52 * pulse_b
        alarm_colour = Vector3(1.8 * intensity, 0.008 * intensity, 0.016 * intensity)
        base_colour = on_colours[i]
        base_strength = float(intensities[i]) if i < len(intensities) else 1.0
        normal_colour = Vector3(base_colour.x * base_strength,
                                base_colour.y * base_strength,
                                base_colour.z * base_strength)
        blended_colour = Vector3(
            normal_colour.x * (1.0 - strength) + alarm_colour.x * strength,
            normal_colour.y * (1.0 - strength) + alarm_colour.y * strength,
            normal_colour.z * (1.0 - strength) + alarm_colour.z * strength,
        )
        set_shader_value(pbr_shader, light_loc, blended_colour, SHADER_UNIFORM_VEC3)

    # Siren housings, rotating lenses and red sweeps are rendered as emissive meshes
    # by draw_emergency_alarm_beacons(); no unsupported shader slots 6–10 are needed.
    if shutdown_at is not None and strength <= 0.001:
        ns["emergency_alarm_active"] = False
        ns["emergency_alarm_strength"] = 0.0
        set_shader_value(pbr_shader, loc_ambient, normal_ambient, SHADER_UNIFORM_VEC3)
        for i, light_loc in enumerate(light_colour_locations):
            base_colour = on_colours[i]
            base_strength = float(intensities[i]) if i < len(intensities) else 1.0
            set_shader_value(
                pbr_shader, light_loc,
                Vector3(base_colour.x * base_strength,
                        base_colour.y * base_strength,
                        base_colour.z * base_strength),
                SHADER_UNIFORM_VEC3,
            )

_OBS_ROOM_DETAIL_NS["update_emergency_alarm_lighting"] = _obs_update_emergency_alarm_lighting_renderer


# The original standalone build treats these six floor records as E-inspectable evidence.
