    OBS_PASSCODE_LOGS.append({
        "id": _obs_log_id,
        "time": _obs_record[1],
        "result": _obs_record[2],
        "world_pos": _obs_local_item_world_pos(_obs_log_x, 0.075, _obs_log_z),
    })

