def _obs_begin_archive_unlock_if_ready():
    """The correct two credentials trigger the source-authentic containment sequence.

    The archive does NOT open immediately: Protocol 04 rejects the combined credential,
    raises a lockdown warning, then activates the red emergency lights after two seconds.
    The security workstation must suspend the protocol before the locker can release.
    """
    global obs_locker_unlocking, obs_locker_unlock_elapsed, obs_locker_feedback
    global obs_locker_interface_open, obs_locker_interface_mode
    ns = _OBS_ROOM_DETAIL_NS
    both_credentials = bool(ns.get("keycard_inserted", False)) and bool(obs_locker_code_accepted)
    if not both_credentials or bool(ns.get("archive_locker_opened", False)):
        return

    if not bool(ns.get("lockdown_started", False)) and not bool(ns.get("security_protocol_suspended", False)):
        now = get_time()
        ns["passcode_solved"] = True
        ns["lockdown_started"] = True
        ns["lockdown_started_at"] = now
        ns["emergency_alarm_active"] = False
        ns["emergency_alarm_strength"] = 0.0
        ns["security_protocol_suspended"] = False
        ns["security_alarm_shutdown_started_at"] = None
        ns["locker_screen_mode"] = "lockdown"
        ns["mission_stage"] = "lockdown"
        obs_locker_unlocking = False
        obs_locker_unlock_elapsed = 0.0
        obs_locker_interface_open = True
        obs_locker_interface_mode = "lockdown"
        obs_locker_feedback = "PASSCODE ACCEPTED // AUTHORIZATION CONFLICT"
        enable_cursor()
        spatial_audio.play_ui("access_denied", volume=0.78)
        try:
            # The Observation Room entrance begins closing as soon as Protocol 04 rejects identity.
            spatial_audio.play_spatial("door_slide", Vector3(-18.95, 1.45, 0.0), camera,
                                       base_volume=0.88, max_dist=16.0)
        except Exception:
            pass


def _obs_update_archive_locker_progress(dt, paused=False):
    """Animate the real locker only after Security Protocol 04 has been suspended."""
    global obs_locker_unlocking, obs_locker_unlock_elapsed, obs_locker_feedback
    if not obs_locker_unlocking or paused:
        return
    ns = _OBS_ROOM_DETAIL_NS
    obs_locker_unlock_elapsed = min(2.2, obs_locker_unlock_elapsed + max(0.0, dt))
    progress = min(1.0, obs_locker_unlock_elapsed / 2.2)
    ns["archive_locker_open_progress"] = progress
    ns["archive_locker_open_started_at"] = ns.get("archive_locker_open_started_at") or get_time()
    if progress >= 1.0:
        ns["archive_locker_opened"] = True
        ns["archive_locker_waypoint_active"] = True
        ns["mission_stage"] = "inspect_archive"
        obs_locker_unlocking = False
        obs_locker_feedback = "ARCHIVE UNSEALED // ACCESS RESTORED"
        try:
            spatial_audio.play_spatial("switch_clunk", OBS_ARCHIVE_LOCKER_WORLD_TARGET, camera,
                                       base_volume=0.78, max_dist=12.0)
        except Exception:
            pass
        spatial_audio.play_ui("access_granted", volume=0.72)


def _obs_update_security_protocol(dt, paused=False):
    """Tick the two-second alarm delay, imported signal puzzle, two-pass symbol reveal, and fade."""
    global obs_security_console_open, obs_locker_unlocking, obs_locker_unlock_elapsed
    global obs_locker_interface_open, obs_locker_interface_mode, obs_locker_feedback
    ns = _OBS_ROOM_DETAIL_NS
    now = get_time()

    if not paused:
        # Original game behavior: warning first, pulsing red emergency lighting after two seconds.
        lockdown_at = ns.get("lockdown_started_at")
        if (ns.get("lockdown_started", False) and lockdown_at is not None
                and not ns.get("emergency_alarm_active", False)
                and not ns.get("security_protocol_suspended", False)
                and now - float(lockdown_at) >= float(ns.get("EMERGENCY_ALARM_DELAY_SECONDS", 5.0))):
            ns["emergency_alarm_active"] = True
            ns["emergency_alarm_strength"] = 1.0
            ns["security_alarm_shutdown_started_at"] = None
            spatial_audio.play_ui("access_denied", volume=0.82)
            ns["mission_stage"] = "disable_security"

        # Preserve the original minigame mechanics. Callback lookups are guarded so an
        # incomplete merge cannot terminate the entire frame loop with a KeyError.
        transition_update = ns.get("update_security_console_transition")
        if ns.get("security_camera_transition") is not None and callable(transition_update):
            transition_update(dt)
        calibration_update = ns.get("update_security_signal_calibration")
        if callable(calibration_update):
            calibration_update(dt)
        phase2_update = ns.get("update_security_phase2")
        if callable(phase2_update):
            phase2_update(dt)

    # Keep the actual alarm sound synchronized with the same state that drives the red beacons.
    # The emitter system restarts this short synthesized siren as it finishes, creating a continuous 3D loop.
    _alarm_sound_live = bool(ns.get("emergency_alarm_active", False))
    _alarm_sound_registered = bool(ns.get("lockdown_alarm_sound_registered", False))
    if _alarm_sound_live and not _alarm_sound_registered:
        try:
            _alarm_target = globals().get("OBS_ARCHIVE_LOCKER_WORLD_TARGET", Vector3(-30.0, 1.5, -26.0))
            _alarm_pos = Vector3(_alarm_target.x, max(3.1, _alarm_target.y + 1.4), _alarm_target.z)
            spatial_audio.unregister_emitter("loop_security_alarm")
            spatial_audio.register_emitter("loop_security_alarm", _alarm_pos,
                                           base_volume=0.72, max_dist=32.0)
            ns["lockdown_alarm_sound_registered"] = True
        except Exception:
            try: spatial_audio.play_ui("loop_security_alarm", volume=0.58)
            except Exception: pass
    elif not _alarm_sound_live and _alarm_sound_registered:
        try: spatial_audio.unregister_emitter("loop_security_alarm")
        except Exception: pass
        ns["lockdown_alarm_sound_registered"] = False

    # Drive the integrated five-light alarm renderer if it is registered.
    # Do not let a missing optional callback take down the game frame loop.
    alarm_update = ns.get("update_emergency_alarm_lighting")
    if ns.get("emergency_alarm_active", False) and callable(alarm_update):
        alarm_update(now)

    # Synchronise the host modal with the original source inspection state after entry/exit.
    active = ns.get("active_inspect_item")
    source_console_open = bool(ns.get("is_inspecting", False)) and isinstance(active, dict) and active.get("id") == "security_override_console"
    transitioning = ns.get("security_camera_transition") is not None
    if source_console_open:
        obs_security_console_open = True
    elif obs_security_console_open and not transitioning:
        obs_security_console_open = False

    # The original console starts the 4.5-second light fade when the player exits after success.
    # Once the fade completes, run the physical archive-locker opening animation.
    if (ns.get("security_protocol_suspended", False)
            and ns.get("security_alarm_shutdown_started_at") is not None
            and not ns.get("emergency_alarm_active", False)
            and not ns.get("archive_locker_opened", False)
            and not obs_locker_unlocking
            and _obs_player_near_archive_locker(4.35)):
        obs_locker_unlocking = True
        obs_locker_unlock_elapsed = 0.0
        obs_locker_interface_open = False
        obs_locker_interface_mode = "menu"
        ns["archive_locker_open_progress"] = 0.0
        ns["mission_stage"] = "archive_unlocking"
        obs_locker_feedback = "SECURITY PROTOCOL 04 SUSPENDED // RELEASING ARCHIVE LOCK"
        disable_cursor()
        try:
            spatial_audio.play_spatial("door_slide", OBS_ARCHIVE_LOCKER_WORLD_TARGET, camera,
                                       base_volume=0.76, max_dist=12.0)
        except Exception:
            pass
        spatial_audio.play_ui("access_granted", volume=0.60)


def _obs_close_locker_panel():
    """Close the locker panel and advance the alert into the terminal objective."""
    global obs_locker_interface_open, obs_locker_interface_mode, obs_locker_code_entry
    ns = _OBS_ROOM_DETAIL_NS
    if obs_locker_interface_mode == "lockdown" and ns.get("lockdown_started", False):
        ns["mission_stage"] = "disable_security"
    obs_locker_interface_open = False
    obs_locker_interface_mode = "menu"
    obs_locker_code_entry = ""
    disable_cursor()


def _obs_insert_archive_keycard():
    global keycard_inserted, keycard_accepted, keycard_objective_started, obs_locker_feedback
    ns = _OBS_ROOM_DETAIL_NS
    if not bool(ns.get("card_keycard_collected", False)):
        obs_locker_feedback = "NO KEYCARD IN INVENTORY // COLLECT THE FINISHED CARD FROM THE PRINTER"
        spatial_audio.play_ui("access_denied", volume=0.45)
        return
    if bool(ns.get("keycard_inserted", False)):
        obs_locker_feedback = "KEYCARD ALREADY ACCEPTED // YOU CAN STILL ENTER THE PASSCODE"
        return
    ns["keycard_inserted"] = True
    ns["keycard_accepted"] = True
    ns["keycard_objective_started"] = True
    if obs_locker_code_accepted:
        ns["mission_stage"] = "inspect_archive"
    elif not bool(ns.get("protocol_note_seen", False)):
        ns["mission_stage"] = "find_passcode"
    elif not bool(ns.get("experiment_log_seen", False)):
        ns["mission_stage"] = "search_papers"
    else:
        ns["mission_stage"] = "enter_passcode"
    ns["archive_locker_waypoint_active"] = False
    keycard_inserted = True
    keycard_accepted = True
    keycard_objective_started = True
    obs_locker_feedback = ("CARD READ // PASSCODE REQUIRED; IDENTITY CHECK RUNS AFTER SUBMISSION"
                           if not obs_locker_code_accepted
                           else "CARD READ // PASSCODE VERIFIED; CHECKING PERSONNEL REGISTRY")
    spatial_audio.play_ui("access_granted", volume=0.58)
    _obs_begin_archive_unlock_if_ready()


def _obs_submit_archive_code():
    global obs_locker_code_entry, obs_locker_code_accepted, obs_locker_feedback
    ns = _OBS_ROOM_DETAIL_NS
    entered = "".join(ch for ch in str(obs_locker_code_entry) if ch.isdigit())[:4]
    obs_locker_code_entry = entered
    if len(entered) != 4:
        obs_locker_feedback = "ENTER ALL FOUR DIGITS BEFORE SUBMITTING"
        spatial_audio.play_ui("access_denied", volume=0.35)
        return
    expected = str(ns.get("ARCHIVE_PASSCODE", "2748"))
    if entered == expected:
        obs_locker_code_accepted = True
        ns["passcode_solved"] = True
        ns["passcode_entry"] = ""
        ns["passcode_feedback"] = "PASSCODE ACCEPTED"
        obs_locker_feedback = ("PASSCODE ACCEPTED // INSERT THE KEYCARD WHEN READY"
                               if not bool(ns.get("keycard_inserted", False))
                               else "PASSCODE ACCEPTED // KEYCARD ALREADY VERIFIED")
        obs_locker_code_entry = ""
        spatial_audio.play_ui("access_granted", volume=0.62)
        _obs_begin_archive_unlock_if_ready()
    else:
        ns["wrong_passcode_attempts"] = int(ns.get("wrong_passcode_attempts", 0)) + 1
        obs_locker_code_entry = ""
        obs_locker_feedback = "INVALID PASSCODE // CHECK SUCCESS RECORDS IN TIMESTAMP ORDER"
        spatial_audio.play_ui("access_denied", volume=0.48)


def _obs_ui_button(x, y, w, h, label, mouse, enabled=True, accent=False, font_size=12):
    hover = x <= mouse.x <= x + w and y <= mouse.y <= y + h
    if not enabled:
        fill, edge, text_col = Color(17, 25, 30, 255), Color(39, 58, 65, 255), Color(98, 120, 127, 255)
    elif accent:
        fill = Color(15, 73, 61, 255) if hover else Color(12, 51, 45, 255)
        edge, text_col = Color(70, 231, 177, 255), Color(223, 248, 239, 255)
    else:
        fill = Color(18, 58, 68, 255) if hover else Color(12, 35, 44, 255)
        edge, text_col = (Color(66, 222, 232, 255) if hover else Color(44, 105, 119, 255)), Color(221, 239, 242, 255)
    draw_rectangle(int(x), int(y), int(w), int(h), fill)
    draw_rectangle_lines(int(x), int(y), int(w), int(h), edge)
    tw = measure_text(label, font_size)
    draw_text(label, int(x + (w - tw) / 2), int(y + (h - font_size) / 2 - 1), font_size, text_col)
    return enabled and hover and is_mouse_button_pressed(MOUSE_BUTTON_LEFT)


def _obs_draw_evidence_panel():
    global obs_evidence_panel_open, obs_evidence_record
    mouse = get_mouse_position()
    sw, sh = SCREEN_WIDTH, SCREEN_HEIGHT
    pw, ph = min(900, sw - 48), min(560, sh - 72)
    px, py = (sw - pw) // 2, (sh - ph) // 2
    draw_rectangle(0, 0, sw, sh, Color(0, 0, 0, 192))
    draw_rectangle(px + 6, py + 7, pw, ph, Color(0, 0, 0, 135))
    draw_rectangle(px, py, pw, ph, Color(7, 18, 24, 252))
    draw_rectangle_lines(px, py, pw, ph, Color(48, 125, 139, 255))
    draw_rectangle(px + 1, py + 1, pw - 2, 58, Color(15, 36, 44, 255))
    draw_rectangle(px + 1, py + 57, pw - 2, 3, UI_CYAN)
    record = obs_evidence_record or {"id": "ARCHIVE PROTOCOL", "title": "ARCHIVE ACCESS PROTOCOL", "time": "", "result": "", "text": ""}
    title = str(record.get("title", "RECOVERED ARCHIVE RECORD"))
    draw_text("ECHO // RECOVERED FIELD DOCUMENT", px + 24, py + 13, 17, Color(222, 239, 242, 255))
    draw_text(title[:64], px + 25, py + 76, 17, UI_CYAN)
    draw_line(px + 25, py + 106, px + pw - 25, py + 106, Color(42, 79, 91, 255))
    body_y = py + 132
    if record.get("kind") == "protocol":
        lines = [
            "ARCHIVE ACCESS // STAFF REMINDER",
            "1. Review the RESULT stamp on each recovered run.",
            "2. Set FAILED reports aside; only SUCCESS runs count.",
            "3. Sort the SUCCESS reports by timestamp, earliest first.",
            "4. Take the final digit from each selected Experiment ID.",
            "5. Enter those four digits in timestamp order at the locker.",
            "",
            "The timestamp determines order; the experiment ID supplies each digit.",
        ]
    else:
        lines = [
            "RECOVERED EXPERIMENT RUN RECORD",
            f"EXPERIMENT ID: {record.get('id', 'UNKNOWN')}",
            f"TIMESTAMP: {record.get('time', 'UNKNOWN')}",
            f"RESULT: {record.get('result', 'UNKNOWN')}",
            "",
            "The report is creased and dirty, but its ID, timestamp and result stamp are legible.",
        ]
    for i, line in enumerate(lines):
        col = Color(91, 225, 187, 255) if "SUCCESS" in line else Color(232, 237, 239, 255)
        if "FAILED" in line:
            col = Color(231, 133, 113, 255)
        draw_text(line, px + 34, body_y + i * 32, 13 if i else 15, col)
    seen_count = len(obs_passcode_logs_collected)
    foot = f"GROUND RECORDS RECOVERED  {seen_count}/6    //    E / ESC TO CLOSE"
    draw_text(foot, px + 25, py + ph - 36, 10, Color(111, 190, 202, 255))
    if _obs_ui_button(px + pw - 152, py + ph - 51, 126, 30, "CLOSE RECORD", mouse, True, True, 10):
        obs_evidence_panel_open = False
        obs_evidence_record = None
        disable_cursor()


def _obs_draw_locker_interface():
    """Polished ECHO two-factor locker terminal with the original Protocol 04 warning."""
    global obs_locker_interface_open, obs_locker_interface_mode, obs_locker_code_entry
    global obs_locker_feedback
    mouse = get_mouse_position()
    sw, sh = SCREEN_WIDTH, SCREEN_HEIGHT
    pw, ph = min(1020, sw - 44), min(640, sh - 32)
    px, py = (sw - pw) // 2, (sh - ph) // 2
    ns = _OBS_ROOM_DETAIL_NS
    unlocked = bool(ns.get("archive_locker_opened", False))
    alarm_live = bool(ns.get("emergency_alarm_active", False))
    lockdown = obs_locker_interface_mode == "lockdown"
    red = Color(255, 58, 66, 255)
    cyan = Color(61, 222, 235, 255)
    green = Color(87, 229, 174, 255)
    white = Color(226, 240, 243, 255)
    muted = Color(137, 177, 188, 255)

    draw_rectangle(0, 0, sw, sh, Color(0, 2, 5, 210))
    draw_rectangle(px + 7, py + 8, pw, ph, Color(0, 0, 0, 170))
    draw_rectangle(px, py, pw, ph, Color(5, 14, 20, 253))
    draw_rectangle_lines(px, py, pw, ph, red if lockdown else cyan)
    draw_rectangle_lines(px + 4, py + 4, pw - 8, ph - 8, Color(34, 72, 83, 255))
    header_bg = Color(38, 7, 13, 255) if lockdown else Color(13, 34, 43, 255)
    accent = red if lockdown else cyan
    draw_rectangle(px + 12, py + 12, pw - 24, 56, header_bg)
    draw_rectangle(px + 12, py + 12, 5, 56, accent)
    draw_text("ECHO  /  OBSERVATION ARCHIVE", px + 32, py + 20, 19, white)
    draw_text("SECURITY INTERLOCK  //  PROTOCOL 04", px + 33, py + 45, 10, accent)
    status_text = "CONTAINMENT ALERT" if lockdown else ("ARCHIVE OPEN" if unlocked else "TWO-FACTOR AUTHORIZATION")
    draw_text(status_text, px + pw - measure_text(status_text, 11) - 30, py + 32, 11, accent)

    card_ok = bool(ns.get("keycard_inserted", False))
    code_ok = bool(obs_locker_code_accepted)
    stock_card = bool(ns.get("card_keycard_collected", False))
    status_y = py + 82
    stat_gap = 16
    stat_w = (pw - 60 - stat_gap) // 2
    card_x, code_x = px + 22, px + 22 + stat_w + stat_gap
    for sx in (card_x, code_x):
        draw_rectangle(sx, status_y, stat_w, 58, Color(9, 25, 32, 255))
        draw_rectangle_lines(sx, status_y, stat_w, 58, Color(48, 90, 101, 255))
    draw_rectangle(card_x + 13, status_y + 15, 42, 27, Color(23, 49, 57, 255))
    draw_rectangle_lines(card_x + 13, status_y + 15, 42, 27, green if card_ok else muted)
    draw_rectangle(card_x + 19, status_y + 21, 9, 3, green if card_ok else cyan)
    draw_text("IDENTITY KEYCARD", card_x + 68, status_y + 10, 10, muted)
    draw_text("ACCEPTED" if card_ok else ("READY TO INSERT" if stock_card else "NOT IN INVENTORY"),
              card_x + 68, status_y + 30, 12, green if card_ok else white)
    draw_rectangle(code_x + 13, status_y + 15, 42, 27, Color(23, 49, 57, 255))
    draw_rectangle_lines(code_x + 13, status_y + 15, 42, 27, green if code_ok else muted)
    for dot_i in range(4):
        draw_circle(code_x + 21 + dot_i * 8, status_y + 28, 2, green if code_ok else cyan)
    draw_text("NUMERIC PASSCODE", code_x + 68, status_y + 10, 10, muted)
    draw_text("VERIFIED" if code_ok else "NOT VERIFIED", code_x + 68, status_y + 30, 12, green if code_ok else white)

    content_y = status_y + 76
    content_h = ph - 240
    content_bottom = content_y + content_h

    if lockdown:
        draw_rectangle(px + 22, content_y, pw - 44, content_h, Color(25, 3, 8, 255))
        draw_rectangle_lines(px + 22, content_y, pw - 44, content_h, Color(210, 35, 45, 255))
        for stripe_x in range(px + 30, px + pw - 38, 34):
            draw_rectangle(stripe_x, content_y + 8, 16, 5, red)
            draw_rectangle(stripe_x, content_bottom - 13, 16, 5, red)
        draw_text("ACCESS DENIED // IDENTITY UNREGISTERED", px + 46, content_y + 35, 24, red)
        draw_text("PERSONNEL RECORD NOT FOUND", px + 47, content_y + 82, 19, white)
        draw_text("The passcode is valid, but this printed card is not registered", px + 48, content_y + 131, 13, white)
        draw_text("in the ECHO personnel database. No authorised staff profile matches it.", px + 48, content_y + 153, 12, Color(200, 173, 179, 255))
        draw_text("SECURITY PROTOCOL 04 // LOCKDOWN INITIATED", px + 48, content_y + 204, 14, red)
        draw_text("ENTRY SEALING NOW // EMERGENCY LIGHTS IN 2 SECONDS", px + 48, content_y + 235, 12, red)
        lockdown_at = ns.get("lockdown_started_at")
        elapsed = max(0.0, get_time() - float(lockdown_at)) if lockdown_at is not None else 0.0
        remaining = max(0.0, float(ns.get("EMERGENCY_ALARM_DELAY_SECONDS", 5.0)) - elapsed)
        draw_rectangle(px + 48, content_y + content_h - 53, pw - 140, 8, Color(48, 17, 22, 255))
        draw_rectangle(px + 48, content_y + content_h - 53,
                       int((pw - 140) * min(1.0, elapsed / max(0.1, float(ns.get("EMERGENCY_ALARM_DELAY_SECONDS", 5.0))))),
                       8, red if alarm_live else Color(196, 90, 44, 255))
        countdown = "EMERGENCY LIGHTS ACTIVE // REACH THE COUNTERSIGNAL TERMINAL" if alarm_live else f"EMERGENCY LIGHTING ARMS IN {remaining:0.1f} SECONDS"
        draw_text(countdown, px + 48, content_y + content_h - 32, 11, red if alarm_live else Color(235, 173, 104, 255))

    elif unlocked:
        draw_rectangle(px + 22, content_y, pw - 44, content_h, Color(6, 31, 24, 255))
        draw_rectangle_lines(px + 22, content_y, pw - 44, content_h, green)
        draw_text("ARCHIVE UNSEALED // ACCESS RESTORED", px + 48, content_y + 58, 22, green)
        draw_text("SECURITY PROTOCOL 04  /  SUSPENDED", px + 49, content_y + 105, 14, white)
        draw_text("The reinforced locker has released. Inspect its contents to continue.", px + 49, content_y + 151, 13, muted)

    elif obs_locker_unlocking:
        draw_text("SECURITY PROTOCOL 04 SUSPENDED", px + 48, content_y + 62, 19, green)
        draw_text("RELEASING THE PHYSICAL ARCHIVE LOCK", px + 49, content_y + 101, 12, white)
        progress = min(1.0, obs_locker_unlock_elapsed / 2.2)
        draw_rectangle(px + 48, content_y + 146, pw - 96, 12, Color(14, 31, 38, 255))
        draw_rectangle_lines(px + 48, content_y + 146, pw - 96, 12, Color(56, 110, 121, 255))
        draw_rectangle(px + 51, content_y + 149, int((pw - 102) * progress), 6, green)

    elif obs_locker_interface_mode == "menu":
        panel_gap = 18
        panel_w = (pw - 70 - panel_gap) // 2
        panel_h = content_h - 8
        pcard_x = px + 22
        pcode_x = pcard_x + panel_w + panel_gap
        for bx in (pcard_x, pcode_x):
            draw_rectangle(bx, content_y, panel_w, panel_h, Color(8, 23, 30, 255))
            draw_rectangle_lines(bx, content_y, panel_w, panel_h, Color(44, 86, 98, 255))
        draw_text("01  /  CUSTOM IDENTITY", pcard_x + 18, content_y + 18, 12, cyan)
        # Minimal high-contrast card illustration with chip, portrait window and ID band.
        draw_rectangle(pcard_x + 20, content_y + 52, panel_w - 40, 90, Color(19, 44, 53, 255))
        draw_rectangle_lines(pcard_x + 20, content_y + 52, panel_w - 40, 90, green if card_ok else Color(68, 121, 133, 255))
        draw_rectangle(pcard_x + 31, content_y + 65, 48, 58, Color(42, 64, 70, 255))
        draw_rectangle_lines(pcard_x + 31, content_y + 65, 48, 58, Color(116, 151, 159, 255))
        draw_circle(pcard_x + 55, content_y + 82, 8, Color(148, 168, 174, 255))
        draw_rectangle(pcard_x + 43, content_y + 92, 24, 19, Color(106, 128, 136, 255))
        draw_text("INVESTIGATOR ID", pcard_x + 91, content_y + 69, 10, white)
        draw_text("OBSERVATION ARCHIVE", pcard_x + 91, content_y + 87, 8, muted)
        draw_text("025  /  LEVEL 4", pcard_x + 91, content_y + 104, 10, green if card_ok else cyan)
        draw_text("Use the card printed at the workstation.", pcard_x + 18, content_y + 155, 10, muted)
        card_btn_y = content_y + panel_h - 65
        if _obs_ui_button(pcard_x + 18, card_btn_y, panel_w - 36, 42,
                          "KEYCARD ACCEPTED" if card_ok else "INSERT CUSTOM KEYCARD",
                          mouse, (not card_ok and stock_card), not card_ok and stock_card, 12):
            _obs_insert_archive_keycard()

        draw_text("02  /  NUMERIC AUTHENTICATION", pcode_x + 18, content_y + 18, 12, cyan)
        draw_text("4-DIGIT ARCHIVE PASSCODE", pcode_x + 20, content_y + 60, 11, white)
        for digit_i in range(4):
            bx = pcode_x + 20 + digit_i * ((panel_w - 55) // 4)
            bw = (panel_w - 65) // 4
            draw_rectangle(bx, content_y + 91, bw, 46, Color(3, 11, 16, 255))
            draw_rectangle_lines(bx, content_y + 91, bw, 46, green if code_ok else Color(50, 103, 118, 255))
            draw_text("OK" if code_ok else "_", bx + (bw - measure_text("OK" if code_ok else "_", 18)) // 2,
                      content_y + 105, 18, green if code_ok else white)
        draw_text("Use the recovered SUCCESS reports in time order.", pcode_x + 18, content_y + 155, 10, muted)
        code_btn_y = content_y + panel_h - 65
        if _obs_ui_button(pcode_x + 18, code_btn_y, panel_w - 36, 42,
                          "PASSCODE VERIFIED" if code_ok else "ENTER NUMERIC PASSCODE",
                          mouse, not code_ok, not code_ok, 12):
            obs_locker_interface_mode = "keypad"
            spatial_audio.play_ui("click", volume=0.38)

    else:  # numeric keypad
        draw_text("ENTER THE FOUR-DIGIT ARCHIVE PASSCODE", px + 34, content_y + 12, 13, white)
        entry_x, entry_y, entry_w = px + 34, content_y + 42, pw - 68
        draw_rectangle(entry_x, entry_y, entry_w, 50, Color(2, 9, 13, 255))
        draw_rectangle_lines(entry_x, entry_y, entry_w, 50, cyan)
        for digit_i in range(4):
            slot_w = 42
            bx = px + pw // 2 - (4 * slot_w + 3 * 15) // 2 + digit_i * (slot_w + 15)
            draw_rectangle(bx, entry_y + 9, slot_w, 31, Color(12, 30, 38, 255))
            draw_rectangle_lines(bx, entry_y + 9, slot_w, 31, cyan if digit_i < len(obs_locker_code_entry) else Color(38, 77, 88, 255))
            ch = obs_locker_code_entry[digit_i] if digit_i < len(obs_locker_code_entry) else "_"
            draw_text(ch, bx + (slot_w - measure_text(ch, 20)) // 2, entry_y + 14, 20, white)
        labels = ("1", "2", "3", "4", "5", "6", "7", "8", "9", "BACK", "0", "ENTER")
        btn_w, btn_h, gap_x, gap_y = 78, 34, 12, 7
        keys_x = px + (pw - (btn_w * 3 + gap_x * 2)) // 2
        keys_y = content_y + 112
        for idx, label in enumerate(labels):
            row, col = divmod(idx, 3)
            bx = keys_x + col * (btn_w + gap_x)
            by = keys_y + row * (btn_h + gap_y)
            if _obs_ui_button(bx, by, btn_w, btn_h, label, mouse, True, label == "ENTER", 10):
                if label == "BACK":
                    obs_locker_code_entry = obs_locker_code_entry[:-1]
                elif label == "ENTER":
                    _obs_submit_archive_code()
                    if obs_locker_code_accepted and not ns.get("lockdown_started", False):
                        obs_locker_interface_mode = "menu"
                elif len(obs_locker_code_entry) < 4:
                    obs_locker_code_entry += label
                    spatial_audio.play_ui("keypad_beep", volume=0.24)

    # Status/feedback rail and context-aware close button.
    feedback_y = py + ph - 57
    feedback_col = red if lockdown or any(flag in str(obs_locker_feedback) for flag in ("INVALID", "CONFLICT", "REJECTED")) else (green if unlocked else muted)
    draw_text(str(obs_locker_feedback)[:112], px + 24, feedback_y, 10, feedback_col)
    close_label = "ACKNOWLEDGE ALERT" if lockdown else ("RETURN TO MENU" if obs_locker_interface_mode == "keypad" else "CLOSE PANEL")
    if _obs_ui_button(px + pw - 190, py + ph - 43, 166, 28, close_label, mouse, True, False, 9):
        if lockdown:
            ns["mission_stage"] = "disable_security"
        if obs_locker_interface_mode == "keypad" and not lockdown:
            obs_locker_interface_mode = "menu"
            obs_locker_code_entry = ""
        else:
            obs_locker_interface_open = False
            obs_locker_interface_mode = "menu"
            disable_cursor()




# Observation-only low-poly models. Dense decorative components do not need the
# host game's higher tessellation, and this avoids reducing quality in other rooms.
def _obs_make_detail_model(mesh):
    """Give each low-poly helper model its own Material/maps allocation.

    Do not copy the complete custom_material struct into multiple models: its maps
    pointer is shared, and UnloadModel can free the same allocation more than once.
    Sharing the shader handle is safe; each model keeps its own default material/maps.
    """
    model = load_model_from_mesh(mesh)
    if model.materialCount > 0:
        model.materials[0].shader = pbr_shader
    return model

_obs_room_low_cylinder_model = _obs_make_detail_model(gen_mesh_cylinder(1.0, 1.0, 10))
_obs_room_low_cone_model = _obs_make_detail_model(gen_mesh_cone(1.0, 1.0, 10))
_obs_room_low_sphere_model = _obs_make_detail_model(gen_mesh_sphere(1.0, 10, 8))
_obs_room_low_torus_model = _obs_make_detail_model(gen_mesh_torus(0.25, 1.0, 8, 12))

def _obs_detail_local_pos(pos):
    # Retain the isolated printer assembly's local draw offset exactly.
    try:
        return _OBS_ROOM_DETAIL_NS["_obs_offset_pos"](pos)
    except Exception:
        return pos

def _obs_fast_cylinder(pos, radius, height, color, roughness=0.5, metallic=0.0, emissive=None, centered=True):
    pos = _obs_detail_local_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(pos, max(float(radius), float(height) * 0.5)):
        return
    center = pos if centered else Vector3(pos.x, pos.y + height * 0.5, pos.z)
    bound = math.sqrt(radius * radius + (height * 0.5) * (height * 0.5))
    if not _is_3d_primitive_visible(center, bound):
        return
    set_pbr_material(color, roughness, metallic, emissive)
    rl_push_matrix()
    rl_translatef(pos.x, pos.y - height * 0.5 if centered else pos.y, pos.z)
    rl_scalef(radius, height, radius)
    draw_model(_obs_room_low_cylinder_model, Vector3(0.0, 0.0, 0.0), 1.0, WHITE)
    rl_pop_matrix()

def _obs_fast_cone(pos, radius, height, color, roughness=0.5, metallic=0.0, emissive=None, centered=True):
    pos = _obs_detail_local_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(pos, max(float(radius), float(height) * 0.5)):
        return
    center = pos if centered else Vector3(pos.x, pos.y + height * 0.5, pos.z)
    bound = math.sqrt(radius * radius + (height * 0.5) * (height * 0.5))
    if not _is_3d_primitive_visible(center, bound):
        return
    set_pbr_material(color, roughness, metallic, emissive)
    rl_push_matrix()
    rl_translatef(pos.x, pos.y - height * 0.5 if centered else pos.y, pos.z)
    rl_scalef(radius, height, radius)
    draw_model(_obs_room_low_cone_model, Vector3(0.0, 0.0, 0.0), 1.0, WHITE)
    rl_pop_matrix()

def _obs_fast_sphere(pos, radius, color, roughness=0.5, metallic=0.0, emissive=None):
    pos = _obs_detail_local_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(pos, float(radius) * 1.1):
        return
    if not _is_3d_primitive_visible(pos, radius * 1.1):
        return
    set_pbr_material(color, roughness, metallic, emissive)
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_scalef(radius, radius, radius)
    draw_model(_obs_room_low_sphere_model, Vector3(0.0, 0.0, 0.0), 1.0, WHITE)
    rl_pop_matrix()

def _obs_fast_torus(pos, radius, tube_radius, color, roughness=0.5, metallic=0.0, emissive=None):
    pos = _obs_detail_local_pos(pos)
    if _obs_rotated_content_hits_preserved_doorway(pos, float(radius + tube_radius * 2.0)):
        return
    bound = math.sqrt(radius * radius + (tube_radius * 2.0) * (tube_radius * 2.0))
    if not _is_3d_primitive_visible(pos, bound):
        return
    set_pbr_material(color, roughness, metallic, emissive)
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_scalef(radius, tube_radius * 4.0, radius)
    draw_model(_obs_room_low_torus_model, Vector3(0.0, 0.0, 0.0), 1.0, WHITE)
    rl_pop_matrix()

