    _OBS_ROOM_DETAIL_NS["draw_observation_ceiling_expansion"](time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_observation_camera_mount"](time_val=time_val, is_powered=power_restored)
    # Fixed wall equipment: noticeboard, safety utilities, monitor array, conduits and consoles.
    _OBS_ROOM_DETAIL_NS["draw_observation_noticeboard"](time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_observation_wall_utilities"](time_val=time_val, is_powered=power_restored)
