    _OBS_ROOM_DETAIL_NS["draw_observation_wall_expansion"](time_val=time_val, is_powered=power_restored)
    # Wall-adjacent environmental storage, loose floor clutter and ventilation hardware.
    _OBS_ROOM_DETAIL_NS["draw_observation_floor_storage_and_ventilation"](time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_observation_storage_expansion"](time_val=time_val, is_powered=power_restored)
    # Furniture, filing, workstation and equipment models are visual-only at this stage.
    # The puzzle screens/minigame handlers and their input state are intentionally not imported.
    _OBS_ROOM_DETAIL_NS["draw_observation_north_wall"](time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_main_observation_workstation"](time_val=time_val, is_powered=power_restored)
    # The security minigame had input/UI integration, but its 3D computer prop was missing.
    # Draw the original detailed oscilloscope workstation on the existing desk extension.
    _security_workstation_draw = _OBS_ROOM_DETAIL_NS.get("draw_security_override_workstation")
    if callable(_security_workstation_draw):
        _security_workstation_draw(time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_window_workstation_extra_clutter"](time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_shifted_printer_group"](time_val=time_val)
    _OBS_ROOM_DETAIL_NS["draw_observation_seating"](time_val=time_val)
