    _OBS_ROOM_DETAIL_NS["draw_observation_calibration_trolley"](time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_observation_center_machinery"](time_val=time_val, is_powered=power_restored)
    _OBS_ROOM_DETAIL_NS["draw_central_observation_desk_and_litter"](time_val=time_val, is_powered=power_restored)
