# Observation Room custom-card printing progression update (host-loop state, isolated renderer).
# Kept outside the room namespace to tick only once per main-game frame.
def _obs_update_printer_progress(dt, paused=False):
    """Advance the isolated printer animation once per host frame and mirror its public flags."""
    global printer_started, printer_print_pending, printer_print_wait_timer
    global printer_start_sound_played, printer_print_animation_active, printer_print_animation_timer
    global card_keycard_printed
    ns = _OBS_ROOM_DETAIL_NS
    printer_started = bool(ns.get("printer_started", False))
    printer_print_pending = bool(ns.get("printer_print_pending", False))
    printer_print_wait_timer = float(ns.get("printer_print_wait_timer", 0.0))
    printer_start_sound_played = bool(ns.get("printer_start_sound_played", False))
    printer_print_animation_active = bool(ns.get("printer_print_animation_active", False))
    printer_print_animation_timer = float(ns.get("printer_print_animation_timer", 0.0))

    if (ns.get("printer_print_pending", False) and not obs_service_panel_open and not paused
            and ns.get("computer_session_state") == "closed"):
        ns["printer_print_wait_timer"] = max(0.0, float(ns.get("printer_print_wait_timer", 0.0)) - dt)
        printer_print_wait_timer = ns["printer_print_wait_timer"]
        if ns["printer_print_wait_timer"] <= 0.0:
            ns["printer_print_pending"] = False
            printer_print_pending = False
            ns["printer_print_animation_active"] = True
            printer_print_animation_active = True
            ns["printer_print_animation_timer"] = 0.0
            printer_print_animation_timer = 0.0
            ns["printer_start_sound_played"] = True
            printer_start_sound_played = True
            # The motor/clack begins in the same frame as the animated gantry, positioned at the printer.
            # A dynamically registered 3D loop continues while the print carriage moves, then is removed at completion.
            try:
                spatial_audio.unregister_emitter("loop_printer")
                spatial_audio.play_spatial("printer_startup", OBS_PRINTER_WORLD_TARGET, camera,
                                            base_volume=0.88, max_dist=22.0)
                spatial_audio.register_emitter("loop_printer", OBS_PRINTER_WORLD_TARGET,
                                               base_volume=0.58, max_dist=22.0)
            except Exception:
                # Keep the animation working if a platform has an audio-device issue.
                try: spatial_audio.play_ui("printer_startup", volume=0.52)
                except Exception: pass

    if ns.get("printer_print_animation_active", False) and not paused:
        ns["printer_print_animation_timer"] = min(
            float(ns.get("PRINTER_PRINT_DURATION", 8.0)),
            float(ns.get("printer_print_animation_timer", 0.0)) + dt)
        printer_print_animation_timer = ns["printer_print_animation_timer"]
        if ns["printer_print_animation_timer"] >= float(ns.get("PRINTER_PRINT_DURATION", 8.0)):
            ns["printer_print_animation_active"] = False
            printer_print_animation_active = False
            ns["card_keycard_printed"] = True
            card_keycard_printed = True
            ns["printer_print_pending"] = False
            printer_print_pending = False
            spatial_audio.unregister_emitter("loop_printer")
            spatial_audio.play_spatial("access_granted", OBS_PRINTER_WORLD_TARGET, camera,
                                        base_volume=0.48, max_dist=12.0)


# Observation Room furniture collision pass v42. Decorative details remain non-solid; these
# boxes cover only the large desks, cabinet bodies and machines so the player cannot walk through them.
def _obs_add_local_furniture_solid(local_x, y, local_z, size_x, size_y, size_z):
    rotated_x, rotated_z = _obs_rotate_interior_local_xz(local_x, local_z)
    world_pos = Vector3(rotated_z + OBSERVATION_ROOM_WORLD_TRANSLATE_X,
                        y,
                        -rotated_x + OBSERVATION_ROOM_WORLD_TRANSLATE_Z)
    # A 180-degree yaw only reverses the horizontal axes; the existing 90-degree world
    # mapping still swaps local X/Z extents in the same way as before.
    world_size = Vector3(size_z, size_y, size_x)
    add_major_solid(world_pos, world_size)

