# v151: real 2-D curved door surface, rather than eight horizontal box slices.
# v154: crash fix for instant cave-in renderer. v155 synchronized the third recorded bang with the dent.
# v156: scripted retreat; door leaf launches through doorway while a small shard knocks player down.
# v158: both door leaves blast rapidly toward/past the player on divergent trajectories; add varied all-direction metal debris and dust bursts.
# v159: use blast-only dark-outside mask for the far Research Room wall, add an indistinct figure silhouette, and thicken the lingering doorway dust cloud.
# v160: fix silhouette rotated-box calls; pass valid material colour before angle/axis to prevent crash during door launch.
# v163: after instant fragment-hit fall, camera rolls sideways on the floor then sits up into a low seated view; door and dust continue moving.
_ECHO_PHASE5_CAVE_SURFACES = []
_ECHO_PHASE5_CAVE_MESH_CACHE = -1.0
_ECHO_PHASE5_CAVE_MODEL_ORIGIN = Vector3(0.0, 2.25, 18.12)


def _echo_phase5_make_dent_surface(x_min, x_max, y_min, y_max, columns, rows, z_base):
    width = float(x_max - x_min)
    height = float(y_max - y_min)
    mesh = gen_mesh_plane(width, height, int(columns), int(rows))
    mid_x = (float(x_min) + float(x_max)) * 0.5
    mid_y = (float(y_min) + float(y_max)) * 0.5
    dx = width / max(1, int(columns))
    dy = height / max(1, int(rows))
    coords = [None] * int(mesh.vertexCount)
    grid_cols = int(columns) + 1
    grid_rows = int(rows) + 1

    for vi in range(int(mesh.vertexCount)):
        plane_x = float(mesh.vertices[vi * 3])
        plane_z = float(mesh.vertices[vi * 3 + 2])
        x = mid_x + plane_x
        y = mid_y + plane_z
        col = max(0, min(grid_cols - 1, int(round((x - x_min) / max(dx, 1e-6)))) )
        row = max(0, min(grid_rows - 1, int(round((y - y_min) / max(dy, 1e-6)))) )
        mesh.vertices[vi * 3] = x
        mesh.vertices[vi * 3 + 1] = y
        mesh.vertices[vi * 3 + 2] = float(z_base)
        mesh.normals[vi * 3] = 0.0
        mesh.normals[vi * 3 + 1] = 0.0
        mesh.normals[vi * 3 + 2] = -1.0
        coords[vi] = (x, y, col, row)

    update_mesh_buffer(mesh, 0, mesh.vertices, int(mesh.vertexCount) * 3 * 4, 0)
    update_mesh_buffer(mesh, 2, mesh.normals, int(mesh.vertexCount) * 3 * 4, 0)
    model = load_model_from_mesh(mesh)
    if int(model.materialCount) > 0:
        model.materials[0].shader = pbr_shader
    # LoadModelFromMesh uploads a by-value Mesh copy; update through the Model's GPU-backed
    # mesh view so update_mesh_buffer addresses the actual VBO that draw_model will render.
    gpu_mesh = model.meshes[0]
    return {
        "mesh": gpu_mesh, "model": model, "coords": coords,
        "columns": grid_cols, "rows": grid_rows, "dx": dx, "dy": dy,
        "z_base": float(z_base), "width": width, "height": height,
        "x_min": float(x_min), "y_min": float(y_min),
    }


def _echo_phase5_dent_depth(x, y, progress):
    """Smooth, deep concave dent centred on the meeting handles, with small metal creases."""
    p = max(0.0, min(1.0, float(progress)))
    # Elliptical Gaussian profile gives a rounded cave-in, not a rectangular buckled slab.
    core = math.exp(-1.30 * (float(x) / 1.08) ** 2 - 1.05 * (float(y) / 1.18) ** 2)
    # Two narrow crease folds radiate above/below the latch as the doors collapse inward.
    fold_l = math.exp(-(((float(x) + 0.29) / 0.16) ** 2) - (((float(y) - 0.06) / 0.78) ** 2))
    fold_r = math.exp(-(((float(x) - 0.27) / 0.17) ** 2) - (((float(y) + 0.12) / 0.72) ** 2))
    depth = ECHO_PHASE5_BREACH_DENT_DEPTH * core + 0.075 * (fold_l + fold_r)
    return p * depth


def _echo_phase5_update_dent_meshes(progress):
    """Warp and upload the smooth door surfaces only while the breach is being shown."""
    global _ECHO_PHASE5_CAVE_MESH_CACHE
    p = max(0.0, min(1.0, float(progress)))
    if _ECHO_PHASE5_CAVE_MESH_CACHE >= 0.0 and abs(p - _ECHO_PHASE5_CAVE_MESH_CACHE) < 0.004:
        return
    for surf_index, surf in enumerate(_ECHO_PHASE5_CAVE_SURFACES):
        mesh = surf["mesh"]
        cols, rows = surf["columns"], surf["rows"]
        dx, dy = surf["dx"], surf["dy"]
        z_base = surf["z_base"]
        # Surface indices 0, 2, and 3 are the LEFT outer skin, inset, and glass.
        # Indices 1, 4, and 5 belong to the RIGHT leaf and remain perfectly flat.
        _left_leaf_surface = surf_index in (0, 2, 3)
        depths = [[0.0 for _ in range(cols)] for _ in range(rows)]
        for x, y, c, r in surf["coords"]:
            depths[r][c] = _echo_phase5_dent_depth(x, y, p) if _left_leaf_surface else 0.0
        for vi, (x, y, c, r) in enumerate(surf["coords"]):
            depth = depths[r][c]
            mesh.vertices[vi * 3 + 2] = z_base - depth
            c0, c1 = max(0, c - 1), min(cols - 1, c + 1)
            r0, r1 = max(0, r - 1), min(rows - 1, r + 1)
            span_x = max(dx, (c1 - c0) * dx)
            span_y = max(dy, (r1 - r0) * dy)
            z_left = z_base - depths[r][c0]
            z_right = z_base - depths[r][c1]
            z_down = z_base - depths[r0][c]
            z_up = z_base - depths[r1][c]
            dzdx = (z_right - z_left) / span_x
            dzdy = (z_up - z_down) / span_y
            inv_len = 1.0 / math.sqrt(dzdx * dzdx + dzdy * dzdy + 1.0)
            # Face the player, who is on the negative-Z side of this doorway.
            mesh.normals[vi * 3] = dzdx * inv_len
            mesh.normals[vi * 3 + 1] = dzdy * inv_len
            mesh.normals[vi * 3 + 2] = -inv_len
        update_mesh_buffer(mesh, 0, mesh.vertices, int(mesh.vertexCount) * 3 * 4, 0)
        update_mesh_buffer(mesh, 2, mesh.normals, int(mesh.vertexCount) * 3 * 4, 0)
    _ECHO_PHASE5_CAVE_MESH_CACHE = p


def _echo_phase5_build_cave_surfaces():
    """Build reusable low-poly grids with enough vertices for a rounded concave deformation."""
    if _ECHO_PHASE5_CAVE_SURFACES:
        return
    # Full door skins: a separate surface per sliding leaf so the meeting seam remains real.
    _ECHO_PHASE5_CAVE_SURFACES.append(_echo_phase5_make_dent_surface(-2.48, 0.0, -2.09, 2.09, 16, 24, -0.132))
    _ECHO_PHASE5_CAVE_SURFACES.append(_echo_phase5_make_dent_surface(0.0, 2.48, -2.09, 2.09, 16, 24, -0.132))
    # Recessed metal insets and cyan glass panels follow the exact same dent profile.
    for cx in (-1.24, 1.24):
        _ECHO_PHASE5_CAVE_SURFACES.append(_echo_phase5_make_dent_surface(cx - 0.96, cx + 0.96, -1.74, 1.74, 14, 20, -0.151))
        _ECHO_PHASE5_CAVE_SURFACES.append(_echo_phase5_make_dent_surface(cx - 0.74, cx + 0.74, -1.40, 1.40, 14, 20, -0.176))


_echo_phase5_build_cave_surfaces()


def _rr_make_target(pos, size, name, title, text, item_type="research_inspect"):
    """Create a non-rendering, non-blocking raycast target for an existing prop."""
    target = add_physics_item(Vector3(*pos), Vector3(*size), name, title, text,
                              item_type, mass=0.2, restitution=0.0, friction=1.0)
    target._research_room_item = True
    target._research_interaction_target = True
    target.settled = True
    target.vel = Vector3(0.0, 0.0, 0.0)
    target.ang_vel = Vector3(0.0, 0.0, 0.0)
    return target


