def _rr_mouse_in(rect, mx=None, my=None):
    if mx is None or my is None:
        m = get_mouse_position()
        mx, my = float(m.x), float(m.y)
    x, y, w, h = rect
    return x <= mx <= x + w and y <= my <= y + h


def _rr_transition_camera(phase, target_pos, target_target, duration=0.86):
    global rr_wall_camera_transitioning, rr_wall_camera_phase, rr_wall_camera_elapsed
    global rr_wall_camera_duration, rr_wall_camera_from_position, rr_wall_camera_from_target
    global rr_wall_camera_to_position, rr_wall_camera_to_target
    rr_wall_camera_phase = phase
    rr_wall_camera_transitioning = True
    rr_wall_camera_elapsed = 0.0
    rr_wall_camera_duration = max(0.12, float(duration))
    rr_wall_camera_from_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    rr_wall_camera_from_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    rr_wall_camera_to_position = Vector3(target_pos.x, target_pos.y, target_pos.z)
    rr_wall_camera_to_target = Vector3(target_target.x, target_target.y, target_target.z)


def rr_start_evidence_wall_inspection():
    global rr_wall_inspection_active, rr_wall_saved_position, rr_wall_saved_target
    global rr_wall_doc_preview_active, rr_wall_hovered_card, rr_wall_selected_card
    global rr_wall_doc_rotation_y, rr_wall_doc_rotation_x
    if rr_wall_inspection_active:
        return
    rr_wall_saved_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    rr_wall_saved_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    rr_wall_inspection_active = True
    rr_wall_doc_preview_active = False
    rr_wall_hovered_card = -1
    rr_wall_selected_card = -1
    rr_wall_doc_rotation_y = 0.0
    rr_wall_doc_rotation_x = 0.0
    disable_cursor()
    _rr_transition_camera("overview", Vector3(4.35, 4.12, 30.0), Vector3(11.5, 4.12, 30.0), 0.86)
    try:
        spatial_audio.play_ui("paper_rustle", volume=0.62)
    except Exception:
        pass


def rr_begin_evidence_wall_return():
    if not rr_wall_inspection_active or rr_wall_camera_transitioning:
        return
    _rr_transition_camera("return", rr_wall_saved_position, rr_wall_saved_target, 0.82)
    disable_cursor()


def rr_handle_evidence_wall_close_key():
    global rr_wall_doc_preview_active, rr_wall_selected_card
    if not rr_wall_inspection_active or rr_wall_camera_transitioning:
        return
    if rr_wall_doc_preview_active:
        rr_wall_doc_preview_active = False
        rr_wall_selected_card = -1
        try:
            spatial_audio.play_ui("paper_rustle", volume=0.42)
        except Exception:
            pass
    else:
        rr_begin_evidence_wall_return()


def _rr_evidence_board_point_under_mouse():
    """Return (board_local_x, board_y) under the mouse, or None off the board plane."""
    mouse = get_mouse_position()
    ray = get_screen_to_world_ray(Vector2(float(mouse.x), float(mouse.y)), camera)
    dx = float(ray.direction.x)
    if abs(dx) < 0.0001:
        return None
    # Board-paper face in world space; board-local X maps to reversed world Z.
    t = (11.535 - float(ray.position.x)) / dx
    if t < 0.0:
        return None
    hit_y = float(ray.position.y) + float(ray.direction.y) * t
    hit_z = float(ray.position.z) + float(ray.direction.z) * t
    local_x = 30.0 - hit_z
    return local_x, hit_y


def _rr_evidence_card_under_mouse():
    """Return the front-most evidence paper under the pointer."""
    point = _rr_evidence_board_point_under_mouse()
    if point is None:
        return -1
    local_x, hit_y = point
    # Later entries are rendered later, so test them first when papers overlap.
    for idx in range(len(RR_EVIDENCE_WALL_CARDS) - 1, -1, -1):
        card = RR_EVIDENCE_WALL_CARDS[idx]
        if (abs(local_x - float(card["x"])) <= float(card["w"]) * 0.5 and
                abs(hit_y - float(card["y"])) <= float(card["h"]) * 0.5):
            return idx
    return -1


def _rr_terminal_layout():
    """Shared terminal geometry. Hitboxes match the isolated desktop/file explorer."""
    bw = min(920, SCREEN_WIDTH - 36)
    bh = min(610, SCREEN_HEIGHT - 36)
    bx = (SCREEN_WIDTH - bw) // 2
    by = (SCREEN_HEIGHT - bh) // 2
    folder_rects = terminal_folder_rects()
    file_rects = terminal_file_row_rects()
    # Login buttons live directly below the access-string field.
    submit_rect = (bx + bw - 228, by + 300, 176, 42)
    clear_rect = (bx + 32, by + 300, 122, 42)
    back_rect = terminal_folder_back_rect()
    return bx, by, bw, bh, folder_rects, file_rects, submit_rect, clear_rect, back_rect


def _rr_memory_layout():
    """Responsive waveform-calibration layout; drawn rectangles and click targets share geometry."""
    bw = min(1120, SCREEN_WIDTH - 36)
    bh = min(670, SCREEN_HEIGHT - 36)
    bx = (SCREEN_WIDTH - bw) // 2
    by = (SCREEN_HEIGHT - bh) // 2
    row_x = bx + 24
    row_w = bw - 48
    row_h = 88
    row_y0 = by + 126
    rows = [(row_x, row_y0 + i * 99, row_w, row_h) for i in range(3)]
    button_y = by + 442
    button_h = 42
    button_gap = 8
    button_x0 = bx + 36
    button_w = (bw - 72 - button_gap * 3) // 4
    buttons = [(button_x0 + i * (button_w + button_gap), button_y, button_w, button_h) for i in range(4)]
    lock_w, lock_h = 270, 40
    lock_rect = (bx + (bw - lock_w) // 2, by + 498, lock_w, lock_h)
    return {
        "panel": (bx, by, bw, bh),
        "rows": rows,
        "buttons": buttons,
        "lock": lock_rect,
    }


def _rr_draw_memory_upload_waveform(x, y, w, h, height_value, spacing_value, color,
                                phase=0.0, instability=0.0):
    """Render a readable oscilloscope trace with a restrained grid and stable centreline."""
    if w < 2 or h < 2:
        return
    graph_bg = Color(5, 14, 20, 170)
    grid_col = Color(33, 61, 70, 155)
    centre_col = Color(53, 86, 95, 205)
    draw_rectangle(x, y, w, h, graph_bg)
    # Five vertical divisions and two faint amplitude guides help players compare shape.
    for i in range(1, 5):
        gx = x + int(w * i / 5.0)
        draw_line(gx, y + 2, gx, y + h - 2, grid_col)
    draw_line(x + 2, y + int(h * 0.25), x + w - 2, y + int(h * 0.25), Color(26, 49, 58, 145))
    draw_line(x + 2, y + int(h * 0.75), x + w - 2, y + int(h * 0.75), Color(26, 49, 58, 145))
    mid_y = y + h * 0.5
    draw_line(x + 1, int(mid_y), x + w - 1, int(mid_y), centre_col)
    amplitude = 2.3 + float(height_value) * 2.35
    period = 58.0 + float(spacing_value) * 17.0
    steps = max(48, min(120, int(w / 3)))
    px_prev = x + 1
    drift_phase = global_time * 4.2 if instability > 0.0 else 0.0
    py_prev = mid_y - math.sin(phase) * amplitude
    for index in range(1, steps + 1):
        px = x + (w - 2) * index / steps
        local = px - x
        drift = instability * (math.sin(local * 0.052 + drift_phase) * 0.55 +
                               math.sin(local * 0.087 - drift_phase * 0.72) * 0.22)
        wave = math.sin((2.0 * math.pi * local / period) + phase)
        py = mid_y - wave * amplitude + drift
        # A dim under-trace creates a soft oscilloscope glow without heavy effects.
        draw_line(int(px_prev), int(py_prev) + 1, int(px), int(py) + 1,
                  Color(color.r, color.g, color.b, 45))
        draw_line(int(px_prev), int(py_prev), int(px), int(py), color)
        px_prev, py_prev = px, py
    draw_rectangle_lines(x, y, w, h, Color(37, 72, 83, 205))

def _rr_terminal_submit():
    global rr_terminal_stage, rr_terminal_input, rr_terminal_notice
    global rr_terminal_notice_timer, rr_terminal_unlock_elapsed, rr_terminal_archive_unlocked
    if rr_terminal_stage != "locked":
        return
    if rr_terminal_input.upper() == RR_TERMINAL_ACCESS_CODE:
        rr_terminal_stage = "unlocking"
        rr_terminal_unlock_elapsed = 0.0
        rr_terminal_notice = "TOKEN ACCEPTED // OPENING ARCHIVE INDEX"
        rr_terminal_notice_timer = 3.0
        try:
            spatial_audio.play_ui("access_granted", volume=0.72)
        except Exception:
            pass
    else:
        rr_terminal_input = ""
        rr_terminal_notice = "ACCESS DENIED // CHECK THE GREEN-MARKED BOARD FRAGMENTS"
        rr_terminal_notice_timer = 3.0
        try:
            spatial_audio.play_ui("access_denied", volume=0.62)
        except Exception:
            pass


def rr_open_archive_terminal(target):
    global is_reading_doc, current_doc_title, current_doc_text, current_3d_item_obj
    is_reading_doc = True
    current_doc_title = getattr(target, "doc_title", "ECHO MEMORY ARCHIVE")
    current_doc_text = getattr(target, "doc_text", "Archive terminal.")
    current_3d_item_obj = target
    enable_cursor()
    try:
        spatial_audio.play_ui("access_granted" if rr_terminal_archive_unlocked else "item_pickup", volume=0.52)
    except Exception:
        pass


def rr_open_memory_station(target):
    global is_reading_doc, current_doc_title, current_doc_text, current_3d_item_obj
    global rr_memory_stage, rr_memory_intro_elapsed, rr_memory_notice, rr_memory_notice_timer
    global research_intro_state, research_waypoint_ping_timer, research_waypoint_arrival_played
    is_reading_doc = True
    current_doc_title = getattr(target, "doc_title", "MEMORY EXTRACTION STATION")
    current_doc_text = getattr(target, "doc_text", "Memory calibration interface.")
    current_3d_item_obj = target
    if research_intro_state == "chair_interaction_available":
        rr_memory_stage = "story_diagnostic"
        rr_memory_notice = "RESIDUAL SESSION DETECTED // EXP-09 INCOMPLETE"
        rr_memory_notice_timer = 0.0
        research_intro_state = "chair_diagnostic_open"
        research_waypoint_ping_timer = 0.0
        research_waypoint_arrival_played = False
    elif rr_memory_stage in ("idle", "needs_archive"):
        if rr_terminal_file_loaded:
            rr_memory_stage = "intro"
            rr_memory_intro_elapsed = 0.0
            rr_memory_notice = "ARCHIVE VERIFIED // STARTING CALIBRATION SEQUENCE"
            rr_memory_notice_timer = 3.0
        else:
            rr_memory_stage = "needs_archive"
            rr_memory_notice = "ARCHIVE DATA REQUIRED BEFORE CALIBRATION"
            rr_memory_notice_timer = 3.5
    enable_cursor()
    try:
        spatial_audio.play_ui("item_pickup", volume=0.52)
    except Exception:
        pass


def _rr_start_memory_transfer():
    global rr_memory_stage, rr_memory_transfer_elapsed, rr_memory_records
    global rr_memory_notice, rr_memory_notice_timer, memory_upload_stage
    rr_memory_stage = "transferring"
    rr_memory_transfer_elapsed = 0.0
    rr_memory_records = 0
    memory_upload_stage = "transferring"
    rr_memory_notice = "LOCKS ACCEPTED // INTEGRATING 24 ARCHIVE RECORDS"
    rr_memory_notice_timer = 4.0
    try:
        spatial_audio.play_ui("access_granted", volume=0.7)
    except Exception:
        pass


def _rr_lock_memory_channel():
    global rr_memory_stage, rr_memory_channel_index, rr_memory_channel_height
    global rr_memory_channel_spacing, rr_memory_channels_locked
    global rr_memory_notice, rr_memory_notice_timer
    if rr_memory_stage != "calibration":
        return
    spec = RR_MEMORY_UPLOAD_CHANNELS[rr_memory_channel_index]
    height_ok = abs(rr_memory_channel_height - spec["target_height"]) <= spec["height_tolerance"]
    spacing_ok = abs(rr_memory_channel_spacing - spec["target_spacing"]) <= spec["spacing_tolerance"]
    if not height_ok or not spacing_ok:
        if not height_ok and not spacing_ok:
            detail = "signal height and spacing are outside tolerance"
        elif not height_ok:
            detail = "signal height is outside tolerance"
        else:
            detail = "signal spacing is outside tolerance"
        rr_memory_notice = f"{spec['experiment']} REJECTED // {detail.upper()}"
        rr_memory_notice_timer = 2.8
        try:
            spatial_audio.play_ui("access_denied", volume=0.42)
        except Exception:
            pass
        return
    rr_memory_channels_locked[rr_memory_channel_index] = True
    try:
        spatial_audio.play_ui("access_granted", volume=0.55)
    except Exception:
        pass
    if rr_memory_channel_index >= len(RR_MEMORY_UPLOAD_CHANNELS) - 1:
        _rr_start_memory_transfer()
        return
    rr_memory_channel_index += 1
    next_spec = RR_MEMORY_UPLOAD_CHANNELS[rr_memory_channel_index]
    rr_memory_channel_height = next_spec["start_height"]
    rr_memory_channel_spacing = next_spec["start_spacing"]
    rr_memory_notice = f"{spec['experiment']} LOCKED // NEXT: {next_spec['label']} {next_spec['experiment']}"
    rr_memory_notice_timer = 3.2


def _rr_update_research_room_interactions(dt):
    """Run the small Research Room UI state machines inside the existing frame loop."""
    global rr_wall_inspection_active, rr_wall_camera_transitioning, rr_wall_camera_phase, rr_wall_camera_elapsed
    global rr_wall_overview_hold_remaining, rr_wall_hovered_card, rr_wall_selected_card, rr_wall_doc_preview_active
    global rr_wall_doc_rotation_y, rr_wall_doc_rotation_x, rr_wall_last_mouse_x, rr_wall_last_mouse_y
    global rr_wall_analysis_complete, rr_wall_analysis_completion_chime_played
    global rr_terminal_stage, rr_terminal_input, rr_terminal_notice, rr_terminal_notice_timer
    global rr_terminal_unlock_elapsed, rr_terminal_archive_unlocked, rr_terminal_open_folder
    global rr_terminal_selected_file, rr_terminal_transfer_active, rr_terminal_transfer_elapsed
    global rr_terminal_file_loaded
    global rr_memory_stage, rr_memory_intro_elapsed, rr_memory_channel_index, rr_memory_channel_height, rr_memory_channel_spacing
    global rr_memory_notice, rr_memory_notice_timer, rr_memory_transfer_elapsed, rr_memory_records
    global memory_upload_stage
    global research_intro_state, research_waypoint_ping_timer, research_waypoint_arrival_played

    # Camera transitions are separate from player locomotion; the normal frame loop is gated
    # whenever the board inspection is active, so mouse/keyboard look cannot fight the move.
    if rr_wall_inspection_active and rr_wall_camera_transitioning and not is_game_paused:
        rr_wall_camera_elapsed += dt
        duration = max(0.05, rr_wall_camera_duration)
        t = min(1.0, rr_wall_camera_elapsed / duration)
        eased = t * t * (3.0 - 2.0 * t)
        camera.position = Vector3(
            rr_wall_camera_from_position.x + (rr_wall_camera_to_position.x - rr_wall_camera_from_position.x) * eased,
            rr_wall_camera_from_position.y + (rr_wall_camera_to_position.y - rr_wall_camera_from_position.y) * eased,
            rr_wall_camera_from_position.z + (rr_wall_camera_to_position.z - rr_wall_camera_from_position.z) * eased)
        camera.target = Vector3(
            rr_wall_camera_from_target.x + (rr_wall_camera_to_target.x - rr_wall_camera_from_target.x) * eased,
            rr_wall_camera_from_target.y + (rr_wall_camera_to_target.y - rr_wall_camera_from_target.y) * eased,
            rr_wall_camera_from_target.z + (rr_wall_camera_to_target.z - rr_wall_camera_from_target.z) * eased)
        if t >= 1.0:
            rr_wall_camera_transitioning = False
            if rr_wall_camera_phase == "overview":
                rr_wall_camera_phase = "overview_hold"
                rr_wall_overview_hold_remaining = 0.48
            elif rr_wall_camera_phase == "close":
                rr_wall_camera_phase = "close"
                enable_cursor()
            elif rr_wall_camera_phase == "return":
                camera.position = Vector3(rr_wall_saved_position.x, rr_wall_saved_position.y, rr_wall_saved_position.z)
                camera.target = Vector3(rr_wall_saved_target.x, rr_wall_saved_target.y, rr_wall_saved_target.z)
                rr_wall_camera_phase = ""
                # End the inspection only after the return camera reached its saved pose.
                rr_wall_inspection_active = False
                disable_cursor()
                try:
                    set_mouse_position(SCREEN_WIDTH // 2, SCREEN_HEIGHT // 2)
                except Exception:
                    pass
    elif rr_wall_inspection_active and rr_wall_camera_phase == "overview_hold" and not is_game_paused:
        rr_wall_overview_hold_remaining -= dt
        if rr_wall_overview_hold_remaining <= 0.0:
            _rr_transition_camera("close", Vector3(9.08, 4.12, 30.0), Vector3(11.50, 4.12, 30.0), 0.92)

    if rr_wall_inspection_active and not rr_wall_camera_transitioning and rr_wall_camera_phase == "close" and not is_game_paused:
        if rr_wall_doc_preview_active:
            # Standalone behavior: drag rotates the inspected 3D paper in front of the camera.
            # The paper remains anchored to its board position; only the inspection model turns.
            mouse = get_mouse_position()
            mx, my = float(mouse.x), float(mouse.y)
            if is_mouse_button_down(MOUSE_BUTTON_LEFT):
                rr_wall_doc_rotation_y = (rr_wall_doc_rotation_y + (mx - rr_wall_last_mouse_x) * 0.78) % 360.0
                rr_wall_doc_rotation_x = max(-65.0, min(65.0,
                    rr_wall_doc_rotation_x + (my - rr_wall_last_mouse_y) * 0.48))
            rr_wall_last_mouse_x, rr_wall_last_mouse_y = mx, my
        else:
            # A click on any log, newspaper clipping, photo or memo opens its full inspection view.
            rr_wall_hovered_card = _rr_evidence_card_under_mouse()
            if rr_wall_hovered_card >= 0 and is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
                rr_wall_selected_card = rr_wall_hovered_card
                rr_wall_doc_preview_active = True
                rr_wall_doc_rotation_y = 0.0
                rr_wall_doc_rotation_x = 0.0
                mouse = get_mouse_position()
                rr_wall_last_mouse_x, rr_wall_last_mouse_y = float(mouse.x), float(mouse.y)
                try:
                    spatial_audio.play_ui("paper_rustle", volume=0.52)
                except Exception:
                    pass

        # Standalone Evidence Wall WASD pan, offset +6 on Z for the combined map.
        if not rr_wall_doc_preview_active:
            pan_x = 0.0
            pan_y = 0.0
            if is_key_down(KEY_W):
                pan_y += 1.0
            if is_key_down(KEY_S):
                pan_y -= 1.0
            if is_key_down(KEY_D):
                pan_x += 1.0
            if is_key_down(KEY_A):
                pan_x -= 1.0
            pan_len = math.sqrt(pan_x * pan_x + pan_y * pan_y)
            if pan_len > 0.001:
                pan_x /= pan_len
                pan_y /= pan_len
                pan_speed = 4.0 if (is_key_down(KEY_LEFT_SHIFT) or is_key_down(KEY_RIGHT_SHIFT)) else 2.7
                dz = pan_x * pan_speed * dt
                dy = pan_y * pan_speed * dt
                next_target_y = max(2.75, min(5.50, camera.target.y + dy))
                next_target_z = max(26.7, min(33.3, camera.target.z + dz))
                actual_dy = next_target_y - camera.target.y
                actual_dz = next_target_z - camera.target.z
                camera.position.y += actual_dy
                camera.position.z += actual_dz
                camera.target.y = next_target_y
                camera.target.z = next_target_z
    elif not rr_wall_inspection_active:
        rr_wall_hovered_card = -1

    # A record becomes investigated only while its reverse is actually visible.
    # The five green fragments are then automatically ordered by their EXP/RUN sequence number.
    if (rr_wall_inspection_active and not rr_wall_camera_transitioning and
            rr_wall_camera_phase == "close" and not is_game_paused and
            rr_wall_doc_preview_active and rr_wall_selected_card in RR_EVIDENCE_CODE_FRAGMENTS and
            math.cos(math.radians(rr_wall_doc_rotation_y)) < 0.0):
        rr_wall_seen_fragment_indices.add(rr_wall_selected_card)
        if (not rr_wall_analysis_complete and
                all(idx in rr_wall_seen_fragment_indices for idx in RR_VALID_EVIDENCE_FRAGMENT_INDICES)):
            rr_wall_analysis_complete = True
            if not rr_wall_analysis_completion_chime_played:
                rr_wall_analysis_completion_chime_played = True
                try:
                    spatial_audio.play_ui("access_granted", volume=0.78)
                except Exception:
                    pass

    if rr_terminal_notice_timer > 0.0 and not is_game_paused:
        rr_terminal_notice_timer = max(0.0, rr_terminal_notice_timer - dt)
    if rr_terminal_stage == "unlocking" and not is_game_paused and is_reading_doc and current_3d_item_obj is not None and getattr(current_3d_item_obj, "item_type", "") == "res_terminal":
        rr_terminal_unlock_elapsed += dt
        if rr_terminal_unlock_elapsed >= rr_terminal_unlock_duration:
            rr_terminal_stage = "folders"
            rr_terminal_archive_unlocked = True
            rr_terminal_open_folder = -1
            rr_terminal_selected_file = -1
            rr_terminal_notice = "ARCHIVE INDEX AVAILABLE // SELECT A DIRECTORY"
            rr_terminal_notice_timer = 3.0
            if research_intro_state == "terminal_code_waypoint":
                research_intro_state = "memory_archive_transfer"
                research_waypoint_ping_timer = 0.0
                research_waypoint_arrival_played = False
                try:
                    spatial_audio.play_ui("mission_chime", volume=0.62)
                except Exception:
                    pass
    if rr_terminal_transfer_active and not is_game_paused and is_reading_doc and current_3d_item_obj is not None and getattr(current_3d_item_obj, "item_type", "") == "res_terminal":
        rr_terminal_transfer_elapsed += dt
        if rr_terminal_transfer_elapsed >= rr_terminal_transfer_duration:
            rr_terminal_transfer_active = False
            rr_terminal_file_loaded = True
            rr_terminal_stage = "folders"
            rr_terminal_open_folder = 2
            rr_terminal_selected_file = 2
            rr_terminal_notice = "ARCHIVE LOADED // 24 RECORDS VERIFIED"
            rr_terminal_notice_timer = 5.0
            # The verified archive is the prerequisite for calibrating the memory link.
            # Advance only after the transfer has actually finished, not when the file is selected.
            if research_intro_state in ("terminal_code_waypoint", "memory_archive_transfer"):
                research_intro_state = "align_memory"
                research_waypoint_ping_timer = 0.0
                research_waypoint_arrival_played = False
            try:
                spatial_audio.play_ui("access_granted", volume=0.75)
                if research_intro_state == "align_memory":
                    spatial_audio.play_ui("mission_chime", volume=0.66)
            except Exception:
                pass

    terminal_active = (is_reading_doc and current_3d_item_obj is not None and
                       getattr(current_3d_item_obj, "item_type", "") == "res_terminal")
    if terminal_active and not is_game_paused and rr_terminal_stage == "locked":
        # Raylib character queue accepts letters and digits, so mixed keys such as 7E4C2 work.
        while True:
            ch = get_char_pressed()
            if not ch:
                break
            try:
                char = chr(int(ch)).upper()
            except (TypeError, ValueError, OverflowError):
                continue
            if char.isalnum() and len(rr_terminal_input) < 12:
                rr_terminal_input += char
                rr_terminal_notice = ""
                rr_terminal_notice_timer = 0.0
        if is_key_pressed(KEY_BACKSPACE) and rr_terminal_input:
            rr_terminal_input = rr_terminal_input[:-1]
            rr_terminal_notice = ""
            rr_terminal_notice_timer = 0.0
        if is_key_pressed(KEY_ENTER) or is_key_pressed(KEY_KP_ENTER):
            _rr_terminal_submit()
        if is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
            bx, by, bw, bh, folder_rects, file_rects, submit_rect, clear_rect, back_rect = _rr_terminal_layout()
            mouse = get_mouse_position(); mx, my = float(mouse.x), float(mouse.y)
            if _rr_mouse_in(submit_rect, mx, my):
                _rr_terminal_submit()
            elif _rr_mouse_in(clear_rect, mx, my):
                rr_terminal_input = ""
                rr_terminal_notice = "INPUT CLEARED"
                rr_terminal_notice_timer = 1.2
    elif terminal_active and not is_game_paused and not rr_terminal_transfer_active and rr_terminal_stage == "folders":
        if is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
            bx, by, bw, bh, folder_rects, file_rects, submit_rect, clear_rect, back_rect = _rr_terminal_layout()
            mouse = get_mouse_position(); mx, my = float(mouse.x), float(mouse.y)
            if rr_terminal_open_folder < 0:
                # Click one of the four real desktop shortcuts.
                for i, rect in enumerate(folder_rects):
                    if _rr_mouse_in(rect, mx, my):
                        rr_terminal_open_folder = i
                        rr_terminal_selected_file = -1
                        rr_terminal_notice = RR_TERMINAL_FOLDERS[i]["description"]
                        rr_terminal_notice_timer = 2.6
                        try:
                            spatial_audio.play_ui("paper_rustle", volume=0.38)
                        except Exception:
                            pass
                        break
            else:
                back_rect = terminal_folder_back_rect()
                load_rect = terminal_load_file_rect()
                if _rr_mouse_in(back_rect, mx, my):
                    rr_terminal_open_folder = -1
                    rr_terminal_selected_file = -1
                    rr_terminal_notice = ""
                    rr_terminal_notice_timer = 0.0
                    try:
                        spatial_audio.play_ui("paper_rustle", volume=0.34)
                    except Exception:
                        pass
                else:
                    clicked_file = False
                    for i, rect in enumerate(file_rects):
                        if _rr_mouse_in(rect, mx, my):
                            rr_terminal_selected_file = i
                            rr_terminal_notice = ""
                            rr_terminal_notice_timer = 0.0
                            clicked_file = True
                            try:
                                spatial_audio.play_ui("paper_rustle", volume=0.32)
                            except Exception:
                                pass
                            break
                    # Loading is only available for the verified memory archive in MEMORY ARCHIVES.
                    if not clicked_file and _rr_mouse_in(load_rect, mx, my) and rr_terminal_open_folder == 2:
                        if rr_terminal_file_loaded and rr_terminal_selected_file == 2:
                            rr_terminal_notice = "ARCHIVE ALREADY STAGED  //  24 RECORDS VERIFIED"
                            rr_terminal_notice_timer = 2.8
                        elif rr_terminal_selected_file == 2:
                            rr_terminal_transfer_active = True
                            rr_terminal_transfer_elapsed = 0.0
                            rr_terminal_notice = "TRANSFERRING ECHO_MEMORY_ARCHIVE_01-24 // DO NOT INTERRUPT"
                            rr_terminal_notice_timer = 5.0
                            try:
                                spatial_audio.play_ui("access_granted", volume=0.58)
                            except Exception:
                                pass
                        elif rr_terminal_selected_file in (0, 1):
                            rr_terminal_notice = "TRANSFER BLOCKED  //  ARCHIVE INCOMPLETE"
                            rr_terminal_notice_timer = 2.8
                            try:
                                spatial_audio.play_ui("access_denied", volume=0.38)
                            except Exception:
                                pass
                        else:
                            rr_terminal_notice = "SELECT A FILE TO INSPECT FIRST"
                            rr_terminal_notice_timer = 2.0


    station_active = (is_reading_doc and current_3d_item_obj is not None and
                      getattr(current_3d_item_obj, "item_type", "") == "station" and
                      getattr(current_3d_item_obj, "name", "") == "Memory Extraction Station")
    if station_active and not is_game_paused:
        if rr_memory_stage == "completed" and research_intro_state == "align_memory":
            research_intro_state = "memory_alignment_complete"
        if rr_memory_notice_timer > 0.0:
            rr_memory_notice_timer = max(0.0, rr_memory_notice_timer - dt)
        if rr_memory_stage == "intro":
            rr_memory_intro_elapsed += dt
            if rr_memory_intro_elapsed >= 2.8:
                rr_memory_stage = "calibration"
                rr_memory_channel_index = next((i for i, locked in enumerate(rr_memory_channels_locked) if not locked), 2)
                spec = RR_MEMORY_UPLOAD_CHANNELS[rr_memory_channel_index]
                rr_memory_channel_height = spec["start_height"]
                rr_memory_channel_spacing = spec["start_spacing"]
                rr_memory_notice = "ADJUST HEIGHT AND SPACING; THEN LOCK THE CHANNEL"
                rr_memory_notice_timer = 3.0
        elif rr_memory_stage == "transferring":
            rr_memory_transfer_elapsed += dt
            progress = min(1.0, rr_memory_transfer_elapsed / max(0.1, rr_memory_transfer_duration))
            rr_memory_records = min(24, int(progress * 24.0))
            if progress >= 1.0:
                rr_memory_stage = "completed"
                rr_memory_records = 24
                memory_upload_stage = "completed"
                rr_memory_notice = "MEMORY ARCHIVE INTEGRATED"
                rr_memory_notice_timer = 8.0
                try:
                    spatial_audio.play_ui("access_granted", volume=0.82)
                except Exception:
                    pass
        if rr_memory_stage == "calibration" and is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
            layout = _rr_memory_layout()
            mouse = get_mouse_position()
            mx, my = float(mouse.x), float(mouse.y)
            button_action = -1
            for button_index, rect in enumerate(layout["buttons"]):
                if _rr_mouse_in(rect, mx, my):
                    button_action = button_index
                    break

            if button_action == 0:
                if rr_memory_channel_height <= 1:
                    rr_memory_notice = "HEIGHT IS ALREADY AT MINIMUM"
                else:
                    rr_memory_channel_height -= 1
                    rr_memory_notice = "WAVE HEIGHT DECREASED"
                rr_memory_notice_timer = 1.25
                try:
                    spatial_audio.play_ui("paper_rustle", volume=0.26)
                except Exception:
                    pass
            elif button_action == 1:
                if rr_memory_channel_height >= 8:
                    rr_memory_notice = "HEIGHT IS ALREADY AT MAXIMUM"
                else:
                    rr_memory_channel_height += 1
                    rr_memory_notice = "WAVE HEIGHT INCREASED"
                rr_memory_notice_timer = 1.25
                try:
                    spatial_audio.play_ui("paper_rustle", volume=0.26)
                except Exception:
                    pass
            elif button_action == 2:
                if rr_memory_channel_spacing <= 3:
                    rr_memory_notice = "SPACING IS ALREADY AT MINIMUM"
                else:
                    rr_memory_channel_spacing -= 1
                    rr_memory_notice = "WAVE SPACING DECREASED"
                rr_memory_notice_timer = 1.25
                try:
                    spatial_audio.play_ui("paper_rustle", volume=0.26)
                except Exception:
                    pass
            elif button_action == 3:
                if rr_memory_channel_spacing >= 9:
                    rr_memory_notice = "SPACING IS ALREADY AT MAXIMUM"
                else:
                    rr_memory_channel_spacing += 1
                    rr_memory_notice = "WAVE SPACING INCREASED"
                rr_memory_notice_timer = 1.25
                try:
                    spatial_audio.play_ui("paper_rustle", volume=0.26)
                except Exception:
                    pass
            elif _rr_mouse_in(layout["lock"], mx, my):
                _rr_lock_memory_channel()

    memory_upload_stage = rr_memory_stage if rr_memory_stage in ("transferring", "completed") else "idle"


def rr_draw_evidence_progress_panel():
    """Show reverse-side discoveries and assemble the access token only when all valid fragments are found."""
    valid_count = sum(1 for idx in RR_VALID_EVIDENCE_FRAGMENT_INDICES if idx in rr_wall_seen_fragment_indices)
    ordered_slots = [data.get("fragment", "?") if idx in rr_wall_seen_fragment_indices else "_"
                     for idx, data in RR_VALID_EVIDENCE_FRAGMENT_ORDER]
    slots_text = "  ".join(ordered_slots)
    panel_w = min(350, SCREEN_WIDTH - 48)
    panel_h = 106
    panel_x, panel_y = 24, 88
    bg = Color(5, 12, 16, 235)
    edge = Color(65, 132, 143, 245) if not rr_wall_analysis_complete else Color(61, 223, 145, 255)
    draw_rectangle(panel_x + 4, panel_y + 5, panel_w, panel_h, Color(0, 0, 0, 150))
    draw_rectangle(panel_x, panel_y, panel_w, panel_h, bg)
    draw_rectangle_lines(panel_x, panel_y, panel_w, panel_h, edge)
    draw_rectangle(panel_x + 1, panel_y + 1, panel_w - 2, 4, edge)
    draw_text("EVIDENCE ANALYSIS", panel_x + 13, panel_y + 12, 15, WHITE)
    draw_text(f"VERIFIED REVERSE MARKS  {valid_count}/5", panel_x + 13, panel_y + 35, 12, Color(171, 194, 201, 255))
    draw_text("TOKEN ORDER  //  EXP NUMBER", panel_x + 13, panel_y + 55, 10, Color(143, 172, 180, 255))
    slot_color = Color(91, 235, 141, 255) if rr_wall_analysis_complete else Color(246, 193, 83, 255)
    draw_text(slots_text, panel_x + 13, panel_y + 73, 20, slot_color)
    if rr_wall_analysis_complete:
        draw_text("ANALYSIS COMPLETE  //  ACCESS TOKEN RECONSTRUCTED", panel_x + 13, panel_y + 94, 9, Color(91, 235, 141, 255))
    else:
        draw_text("FLIP GREEN-MARKED RECORDS; IGNORE RED DECOYS", panel_x + 13, panel_y + 94, 9, Color(197, 166, 107, 255))


def rr_draw_evidence_wall_overlay():
    """Complete Evidence Wall minigame: select pages, drag to flip, track valid fragments and solve.

    Keep the title as unobtrusive text; do not draw the old full-width cyan header band that
    covered the top of the gameplay view.
    """
    global rr_wall_doc_preview_active
    draw_text("PROJECT ECHO  //  EXPERIMENT EVIDENCE WALL", 28, 18, 20, UI_CYAN)
    if rr_wall_camera_transitioning or rr_wall_camera_phase in ("overview", "overview_hold"):
        status = "SCANNING RECORDS // MOVING TO BOARD POSITION"
        draw_text(status, 30, SCREEN_HEIGHT - 46, 16, LIGHTGRAY)
        return
    if rr_wall_camera_phase == "return":
        draw_text("RETURNING TO LAB...", 30, SCREEN_HEIGHT - 46, 16, LIGHTGRAY)
        return
    if not rr_wall_doc_preview_active:
        rr_draw_evidence_progress_panel()
        if 0 <= rr_wall_hovered_card < len(RR_EVIDENCE_WALL_CARDS):
            card = RR_EVIDENCE_WALL_CARDS[rr_wall_hovered_card]
            tag = "VERIFIED" if card.get("status") == "success" else ("FAILED / DECOY" if card.get("status") == "failed" else "UNVERIFIED")
            col = Color(64, 225, 151, 255) if card.get("status") == "success" else (Color(235, 80, 71, 255) if card.get("status") == "failed" else Color(245, 179, 63, 255))
            w = min(620, SCREEN_WIDTH - 40)
            x, y = SCREEN_WIDTH - w - 20, SCREEN_HEIGHT - 122
            draw_rectangle(x, y, w, 80, Color(5, 14, 19, 235))
            draw_rectangle_lines(x, y, w, 80, col)
            draw_text(card["title"], x + 16, y + 12, 17, WHITE)
            draw_text(tag + "  //  CLICK TO INSPECT DOCUMENT", x + 16, y + 45, 14, col)
        draw_text("WASD: PAN  |  SHIFT: FASTER  |  CLICK A LOG / CLIPPING TO INSPECT", 30, SCREEN_HEIGHT - 72, 15, WHITE)
        draw_text("E / ESC: CLOSE BOARD  //  METHOD NOTE: KEEP GREEN CHARACTERS FROM SUCCESSFUL EXP RECORDS", 30, SCREEN_HEIGHT - 43, 13, Color(168, 188, 196, 255))
        return

    idx = rr_wall_selected_card
    if not (0 <= idx < len(RR_EVIDENCE_WALL_CARDS)):
        rr_wall_doc_preview_active = False
        return
    card = RR_EVIDENCE_WALL_CARDS[idx]
    back_side = math.cos(math.radians(rr_wall_doc_rotation_y)) < 0.0
    panel_x, panel_y, panel_w = 28, 104, min(410, SCREEN_WIDTH - 56)
    panel_h = min(430, SCREEN_HEIGHT - 142)
    status = card.get("status", "unknown").upper()
    status_col = Color(61, 223, 145, 255) if status == "SUCCESS" else (Color(231, 74, 65, 255) if status == "FAILED" else Color(243, 178, 63, 255))
    draw_rectangle(panel_x + 7, panel_y + 8, panel_w, panel_h, Color(0, 0, 0, 180))
    draw_rectangle(panel_x, panel_y, panel_w, panel_h, Color(7, 15, 20, 246))
    draw_rectangle_lines(panel_x, panel_y, panel_w, panel_h, Color(63, 131, 144, 255))
    draw_rectangle(panel_x + 1, panel_y + 1, panel_w - 2, 5, UI_CYAN)
    draw_text("DOCUMENT INSPECTION", panel_x + 18, panel_y + 18, 13, Color(150, 180, 187, 255))
    draw_text(card["title"], panel_x + 18, panel_y + 42, 18, WHITE)
    draw_text(("REVERSE SIDE" if back_side else "FRONT SIDE") + "  //  " + status, panel_x + 18, panel_y + 72, 13, status_col)
    draw_line(panel_x + 18, panel_y + 98, panel_x + panel_w - 18, panel_y + 98, Color(43, 75, 84, 255))
    body = card.get("back" if back_side else "front", "No readable text remains on this page.")
    y = panel_y + 114
    for line in wrap_text(body, 15, panel_w - 36):
        if y > panel_y + panel_h - 102:
            break
        draw_text(line, panel_x + 18, y, 15, Color(220, 225, 218, 255))
        y += 22
    fragment = RR_EVIDENCE_CODE_FRAGMENTS.get(idx)
    if back_side and fragment:
        valid = bool(fragment.get("fragment_valid"))
        frag_col = Color(61, 223, 145, 255) if valid else Color(235, 76, 67, 255)
        frag_label = "KEEP THIS CHARACTER" if valid else "DECOY // DO NOT USE"
        chip_y = panel_y + panel_h - 90
        draw_rectangle(panel_x + 18, chip_y, panel_w - 36, 48, Color(12, 28, 29, 255) if valid else Color(35, 17, 18, 255))
        draw_rectangle_lines(panel_x + 18, chip_y, panel_w - 36, 48, frag_col)
        draw_text(f"MARK: {fragment.get('fragment', '?')}   //   {frag_label}", panel_x + 30, chip_y + 15, 15, frag_col)
    draw_text("HOLD LEFT MOUSE + DRAG HORIZONTALLY TO FLIP THE PAGE", 24, SCREEN_HEIGHT - 70, 13, WHITE)
    draw_text("E / ESC: RETURN TO BOARD", 24, SCREEN_HEIGHT - 44, 13, Color(168, 188, 196, 255))


def terminal_folder_rects():
    """Clickable rectangles for exactly four desktop folder icons."""
    box_w = min(920, SCREEN_WIDTH - 36)
    box_h = min(610, SCREEN_HEIGHT - 36)
    box_x = (SCREEN_WIDTH - box_w) // 2
    box_y = (SCREEN_HEIGHT - box_h) // 2
    return [(box_x + 12, box_y + 45 + i * 112, 126, 98) for i in range(4)]


def terminal_file_row_rects():
    """Clickable rows for the three candidate files in an open archive directory."""
    box_w = min(920, SCREEN_WIDTH - 36)
    box_h = min(610, SCREEN_HEIGHT - 36)
    box_x = (SCREEN_WIDTH - box_w) // 2
    box_y = (SCREEN_HEIGHT - box_h) // 2
    list_x = box_x + 30
    list_w = int((box_w - 75) * 0.54)
    list_y = box_y + 190
    return [(list_x, list_y + i * 52, list_w, 42) for i in range(3)]


def terminal_load_file_rect():
    """Hitbox for LOAD FILE in the Memory Archives details pane."""
    box_w = min(920, SCREEN_WIDTH - 36)
    box_h = min(610, SCREEN_HEIGHT - 36)
    box_x = (SCREEN_WIDTH - box_w) // 2
    box_y = (SCREEN_HEIGHT - box_h) // 2
    left_w = int((box_w - 75) * 0.54)
    details_x = box_x + 30 + left_w + 15
    details_w = box_x + box_w - 30 - details_x
    return (details_x + 10, box_y + 430, details_w - 20, 38)


def terminal_draw_desktop_wallpaper(box_x, box_y, box_w, box_h):
    """Draw a layered industrial research-wing wallpaper and exactly four desktop folders."""
    bg0 = Color(8, 16, 25, 255)
    wall = Color(17, 31, 43, 255)
    wall_mid = Color(22, 40, 53, 255)
    wall_light = Color(30, 51, 63, 255)
    edge = Color(43, 71, 83, 255)
    cyan_dim = Color(55, 120, 133, 255)
    cyan = Color(93, 196, 207, 255)
    amber = Color(188, 144, 69, 255)

    # Base and architectural planes: a service corridor receding into the wing.
    draw_rectangle(box_x, box_y, box_w, box_h, bg0)
    draw_rectangle(box_x, box_y + 33, box_w, int(box_h * 0.40), wall)
    horizon_x = int(box_x + box_w * 0.72)
    horizon_y = int(box_y + box_h * 0.51)
    draw_triangle(Vector2(box_x + 110, box_y + 34),
                  Vector2(box_x + box_w - 14, box_y + 34),
                  Vector2(horizon_x, horizon_y), Color(13, 25, 36, 255))
    draw_triangle(Vector2(box_x + 10, horizon_y),
                  Vector2(horizon_x, horizon_y),
                  Vector2(box_x + box_w - 10, box_y + box_h - 32), Color(23, 40, 52, 255))
    draw_triangle(Vector2(box_x + 10, horizon_y),
                  Vector2(horizon_x, horizon_y),
                  Vector2(box_x + 10, box_y + box_h - 32), Color(15, 29, 41, 255))
    draw_triangle(Vector2(horizon_x, horizon_y),
                  Vector2(box_x + box_w - 10, horizon_y - 12),
                  Vector2(box_x + box_w - 10, box_y + box_h - 32), Color(17, 31, 42, 255))

    # Left desktop-icon gutter stays deliberately dark so folder labels remain legible.
    draw_rectangle(box_x + 7, box_y + 35, 148, box_h - 67, Color(8, 17, 27, 168))
    draw_line(box_x + 158, box_y + 36, box_x + 158, box_y + box_h - 33, Color(39, 66, 78, 255))

    # Overhead beams and recessed lights.
    for i in range(5):
        x0 = int(box_x + box_w * (0.21 + i * 0.15))
        x1 = int(horizon_x + (x0 - horizon_x) * 0.10)
        draw_line(x0, box_y + 37, x1, horizon_y - 8, Color(35, 56, 67, 255))
    for i, frac in enumerate((0.30, 0.48, 0.66, 0.84)):
        lx = int(box_x + box_w * frac)
        ly = box_y + 54 + (i % 2) * 8
        lw = max(24, int(box_w * (0.048 - i * 0.003)))
        draw_rectangle(lx - 2, ly - 2, lw + 4, 9, Color(6, 14, 21, 255))
        draw_rectangle(lx, ly, lw, 4, Color(88, 134, 143, 255))
        draw_rectangle(lx, ly + 4, lw, 1, Color(151, 174, 169, 120))

    # Wall service panels, conduit runs and distant equipment alcoves.
    for i in range(4):
        px = int(box_x + box_w * (0.43 + i * 0.12))
        py = int(box_y + box_h * (0.28 + (i % 2) * 0.035))
        pw = max(28, int(box_w * 0.075))
        ph = int(box_h * 0.20)
        draw_rectangle(px, py, pw, ph, Color(12, 24, 34, 255))
        draw_rectangle_lines(px, py, pw, ph, Color(37, 61, 71, 255))
        draw_rectangle(px + 6, py + 8, pw - 12, 3, Color(44, 71, 80, 255))
        for vent in range(4):
            vy = py + 20 + vent * max(8, int(ph * 0.13))
            draw_line(px + 7, vy, px + pw - 7, vy, Color(28, 48, 59, 255))
        for light in range(3):
            draw_circle(px + pw - 7, py + 10 + light * 10, 1.8,
                        (cyan_dim, amber, Color(65, 117, 84, 255))[light])

    # Server racks at the right of the wallpaper; these are wallpaper geometry, not extra icons.
    rack_specs = [(0.70, 0.34, 0.060, 0.34), (0.785, 0.30, 0.072, 0.39), (0.885, 0.36, 0.060, 0.31)]
    for ri, (xf, yf, wf, hf) in enumerate(rack_specs):
        rx = int(box_x + box_w * xf)
        ry = int(box_y + box_h * yf)
        rw = max(24, int(box_w * wf))
        rh = int(box_h * hf)
        draw_rectangle(rx + 3, ry + 4, rw, rh, Color(4, 12, 18, 255))
        draw_rectangle(rx, ry, rw, rh, Color(13, 26, 36, 255))
        draw_rectangle_lines(rx, ry, rw, rh, Color(50, 78, 89, 255))
        draw_rectangle(rx + 4, ry + 5, rw - 8, 5, Color(28, 49, 59, 255))
        for slot in range(5):
            sy = ry + 15 + slot * max(12, (rh - 27) // 5)
            draw_rectangle(rx + 5, sy, rw - 10, max(7, int(rh * 0.075)), Color(7, 17, 24, 255))
            draw_rectangle(rx + 8, sy + 2, max(3, rw - 23), 2,
                           Color(37, 83, 93, 255) if slot % 2 == 0 else Color(42, 65, 72, 255))
            draw_circle(rx + rw - 7, sy + 4, 1.7,
                        (cyan_dim, Color(65, 117, 84, 255), amber)[(slot + ri) % 3])

    # Low console at the vanishing point, with a subtle monitor glow.
    console_x = int(box_x + box_w * 0.72)
    console_y = int(box_y + box_h * 0.51)
    console_w = max(86, int(box_w * 0.17))
    draw_rectangle(console_x - 12, console_y - 10, console_w, 28, Color(5, 14, 21, 255))
    draw_rectangle(console_x - 7, console_y - 7, console_w - 10, 19, Color(13, 30, 39, 255))
    draw_rectangle_lines(console_x - 7, console_y - 7, console_w - 10, 19, Color(48, 89, 100, 255))
    draw_rectangle(console_x + 4, console_y + 1, console_w - 32, 2, cyan_dim)
    draw_rectangle(console_x + 9, console_y + 23, console_w - 40, 16, Color(7, 16, 22, 255))

    # Floor panels and perspective seams leading toward the workstation.
    floor_top = horizon_y + 7
    for i in range(1, 8):
        t = (i / 8.0) ** 1.65
        yy = floor_top + int((box_y + box_h - 31 - floor_top) * t)
        draw_line(box_x + 160, yy, box_x + box_w - 12, yy, Color(37, 57, 69, 255))
    for i in range(8):
        bottom_x = int(box_x + box_w * (0.19 + i * 0.115))
        draw_line(horizon_x, floor_top, bottom_x, box_y + box_h - 31, Color(35, 54, 65, 255))
    # Thin cable route and a few worn floor reflectors.
    draw_line(box_x + int(box_w * 0.50), box_y + box_h - 32,
              box_x + int(box_w * 0.73), horizon_y + 8, Color(37, 83, 91, 255))
    for j in range(3):
        fx = int(box_x + box_w * (0.56 + j * 0.13))
        fy = int(box_y + box_h * (0.80 + (j % 2) * 0.045))
        draw_rectangle(fx, fy, max(12, int(box_w * 0.025)), 2, Color(73, 99, 103, 255))

    # Faint glass reflections / scan lines make it read as an old local monitor wallpaper.
    for i in range(1, 13):
        sy = box_y + 35 + i * int((box_h - 73) / 13)
        draw_line(box_x + 164, sy, box_x + box_w - 12, sy, Color(69, 109, 120, 14))

    # Header strip and exactly four desktop shortcuts.
    draw_rectangle(box_x, box_y, box_w, 33, Color(5, 12, 19, 245))
    draw_line(box_x, box_y + 33, box_x + box_w, box_y + 33, Color(50, 93, 106, 255))
    draw_text("PC-07  /  LOCAL WORKSTATION", box_x + 17, box_y + 10, 12, Color(177, 207, 210, 255))
    status = "SECTOR B  |  OFFLINE MODE"
    draw_text(status, box_x + box_w - measure_text(status, 11) - 18, box_y + 10, 11, Color(92, 157, 166, 255))

    folder_names = [("PERSONNEL", "RECORDS"), ("SECURITY", "FOOTAGE"),
                    ("MEMORY", "ARCHIVES"), ("SYSTEM", "BACKUPS")]
    mouse = get_mouse_position()
    for index, (rect, name_lines) in enumerate(zip(terminal_folder_rects(), folder_names)):
        fx, fy, fw, fh = rect
        hovered = fx <= mouse.x <= fx + fw and fy <= mouse.y <= fy + fh
        if hovered:
            draw_rectangle(fx - 3, fy - 3, fw + 6, fh + 6, Color(42, 101, 119, 115))
            draw_rectangle_lines(fx - 3, fy - 3, fw + 6, fh + 6, Color(90, 188, 201, 235))
        # Soft icon shadow plus a folder with a raised tab and a clean paper lip.
        draw_rectangle(fx + 29, fy + 17, 62, 37, Color(4, 9, 14, 100))
        folder_main = Color(214, 180, 96, 255) if hovered else Color(190, 154, 79, 255)
        folder_tab = Color(237, 207, 127, 255) if hovered else Color(218, 185, 104, 255)
        draw_rectangle(fx + 38, fy + 5, 40, 12, folder_tab)
        draw_rectangle(fx + 30, fy + 13, 58, 36, folder_main)
        draw_rectangle_lines(fx + 30, fy + 13, 58, 36, Color(246, 221, 160, 255) if hovered else Color(221, 196, 134, 255))
        draw_line(fx + 34, fy + 21, fx + 83, fy + 21, Color(244, 221, 164, 210))
        draw_line(fx + 34, fy + 24, fx + 83, fy + 24, Color(166, 130, 67, 170))
        for line_index, label in enumerate(name_lines):
            label_w = measure_text(label, 10)
            draw_text(label, fx + (fw - label_w) // 2, fy + 58 + line_index * 13, 10,
                      Color(245, 250, 250, 255) if hovered else Color(226, 237, 241, 255))
        if hovered:
            draw_text("OPEN", fx + 44, fy + fh - 15, 8, Color(125, 221, 231, 255))

    # Bottom taskbar: workstation identity and local-only status; no extra shortcuts.
    task_y = box_y + box_h - 30
    draw_rectangle(box_x, task_y, box_w, 30, Color(5, 11, 17, 245))
    draw_line(box_x, task_y, box_x + box_w, task_y, Color(54, 91, 105, 255))
    draw_rectangle(box_x + 12, task_y + 7, 16, 16, Color(66, 145, 174, 255))
    draw_line(box_x + 20, task_y + 8, box_x + 20, task_y + 22, Color(209, 235, 242, 255))
    draw_line(box_x + 13, task_y + 15, box_x + 27, task_y + 15, Color(209, 235, 242, 255))
    draw_text("PROJECT ECHO WORKSTATION", box_x + 39, task_y + 9, 11, Color(177, 205, 210, 255))
    task_status = "LOCAL STORAGE  /  SEC-B"
    draw_text(task_status, box_x + box_w - measure_text(task_status, 10) - 16,
              task_y + 9, 10, Color(111, 159, 169, 255))


def terminal_file_details(folder_index, file_index):
    """Metadata the player uses to compare candidate files against experiment clues."""
    if folder_index == 2:
        options = [
            {"status": "INCOMPLETE ARCHIVE", "summary": "Captured memory blocks exist, but the archive is missing later processing records.",
             "lines": ["EXP-09 / CAPTURE: FOUND", "EXP-12 / STORAGE INDEX: MISSING", "EXP-17 / RECONSTRUCTION: MISSING"], "valid": False},
            {"status": "LEGACY BACKUP", "summary": "An older snapshot taken before reconstruction was completed and verified.",
             "lines": ["CAPTURE: FOUND", "STORAGE: PARTIAL", "RECONSTRUCTION: NOT COMMITTED"], "valid": False},
            {"status": "VALIDATED / TRANSFER READY", "summary": "The complete EXP-01–24 archive. Its index confirms capture, storage, and reconstruction stages.",
             "lines": ["EXP-09 / CAPTURE: VERIFIED", "EXP-12 / STORAGE: VERIFIED", "EXP-17 / RECONSTRUCTION: VERIFIED"], "valid": True},
        ]
        return options[file_index] if 0 <= file_index < len(options) else None
    general = {
        0: [("STAFF REGISTRY", "Indexed personnel table. Read-only record."), ("CLEARANCE ROSTER", "Local staff clearance listing. Some entries are outdated."), ("ASSIGNMENT HISTORY", "Archived staff assignment changes for Sector B.")],
        1: [("CAMERA INDEX", "List of camera IDs and archived recording locations."), ("INCIDENT RECORDING", "Incident 03-14 recording index. Playback unavailable in offline mode."), ("CORRIDOR BACKUP", "Secondary corridor recording. Playback unavailable in offline mode.")],
        3: [("RESTORE POINT", "A saved local recovery point. Not required for the current task."), ("ARCHIVE CORE IMAGE", "A legacy system image used for workstation recovery."), ("BOOT RECOVERY LOG", "Startup diagnostics from the last successful boot.")],
    }
    records = general.get(folder_index, [])
    if 0 <= file_index < len(records):
        title, summary = records[file_index]
        return {"status": "INDEXED / READ ONLY", "summary": summary,
                "lines": [title, "LOCAL COPY AVAILABLE", "NO ACTION REQUIRED"], "valid": False}
    return None


def terminal_folder_back_rect():
    box_w = min(920, SCREEN_WIDTH - 36)
    box_h = min(610, SCREEN_HEIGHT - 36)
    box_x = (SCREEN_WIDTH - box_w) // 2
    box_y = (SCREEN_HEIGHT - box_h) // 2
    return (box_x + 24, box_y + box_h - 54, 166, 32)


def rr_draw_archive_terminal_ui():
    """Draw the ECHO Archive Computer with its industrial desktop and detailed file explorer."""
    bx, by, bw, bh, folder_rects, file_rects, submit_rect, clear_rect, back_rect = _rr_terminal_layout()
    mouse = get_mouse_position(); mx, my = float(mouse.x), float(mouse.y)
    bg = Color(5, 11, 15, 250)
    panel = Color(10, 23, 29, 255)
    panel2 = Color(15, 35, 42, 255)
    border = Color(58, 116, 129, 255)
    cyan = Color(0, 220, 238, 255)
    cyan_dim = Color(92, 154, 166, 255)
    text_main = Color(231, 241, 242, 255)
    text_muted = Color(151, 179, 187, 255)
    green = Color(82, 220, 145, 255)
    amber = Color(242, 182, 63, 255)

    draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 2, 5, 182))
    draw_rectangle(bx + 8, by + 10, bw, bh, Color(0, 0, 0, 225))
    draw_rectangle(bx, by, bw, bh, bg)
    draw_rectangle_lines(bx, by, bw, bh, border)
    draw_rectangle(bx + 1, by + 1, bw - 2, 5, cyan)
    draw_rectangle(bx + 16, by + 14, bw - 32, 72, panel)
    draw_text("ECHO ARCHIVE // SECURE WORKSTATION", bx + 32, by + 28, 20, cyan)
    draw_text("SECTOR B  •  LOCAL DATA VAULT  •  NODE ECHO-02", bx + 32, by + 56, 13, text_muted)

    if research_intro_state == "monitor_message":
        # First-visit briefing on the very same workstation used later for archive-token entry.
        draw_text("PROJECT ECHO  //  SESSION RECOVERY", bx + 32, by + 116, 20, cyan)
        draw_text("AUTOMATED RECOVERY NOTICE  /  NODE ECHO-02", bx + 32, by + 150, 13, text_muted)
        card_x, card_y, card_w, card_h = bx + 32, by + 185, bw - 64, 244
        draw_rectangle(card_x, card_y, card_w, card_h, panel)
        draw_rectangle_lines(card_x, card_y, card_w, card_h, border)
        draw_rectangle(card_x + 1, card_y + 1, 4, card_h - 2, cyan)
        status_lines = [
            ("LAST TRANSFER", "ABORTED", amber),
            ("SUBJECT RECORD", "EXP-09  /  INCOMPLETE", text_main),
            ("MEMORY DATA", "FRAGMENTED", amber),
            ("RECOVERY INDEX", "NOT MOUNTED", text_main),
        ]
        row_y = card_y + 24
        for label, value, value_color in status_lines:
            draw_text(label, card_x + 20, row_y, 12, text_muted)
            draw_text(value, card_x + 245, row_y - 1, 15, value_color)
            draw_line(card_x + 20, row_y + 26, card_x + card_w - 20, row_y + 26, Color(35, 65, 75, 255))
            row_y += 49
        draw_text("SYSTEM NOTE", card_x + 20, card_y + 219, 11, cyan)
        draw_text("Reconstruct the experiment sequence from the physical evidence wall before retrieving the archive.",
                  card_x + 118, card_y + 216, 12, text_main)
        draw_line(bx + 28, by + bh - 63, bx + bw - 28, by + bh - 63, Color(37, 65, 74, 255))
        footer = "E / ESC: CLOSE BRIEFING  //  AUTHENTICATION REMAINS AVAILABLE HERE LATER"
        draw_text(footer, bx + 32, by + bh - 39, 10, text_muted)

    elif rr_terminal_stage == "locked":
        draw_text("AUTHENTICATION REQUIRED", bx + 32, by + 116, 20, text_main)
        draw_text("Enter the five-character access string recovered from the Evidence Wall.",
                  bx + 32, by + 150, 15, text_muted)
        input_rect = (bx + 32, by + 204, bw - 64, 64)
        draw_rectangle(*input_rect, panel2)
        draw_rectangle_lines(*input_rect, Color(55, 135, 151, 255))
        draw_text("ACCESS STRING", bx + 48, by + 214, 12, cyan_dim)
        visible_input = rr_terminal_input + ("_" if int(get_time() * 2.0) % 2 == 0 else "")
        draw_text(visible_input, bx + 48, by + 238, 24, text_main)
        draw_text("KEYBOARD: A-Z / 0-9   •   BACKSPACE: DELETE   •   ENTER: AUTHENTICATE",
                  bx + 32, by + 282, 12, text_muted)

        draw_rectangle(*clear_rect, panel2)
        draw_rectangle_lines(*clear_rect, Color(74, 102, 112, 255))
        draw_text("CLEAR", clear_rect[0] + 35, clear_rect[1] + 13, 14, text_main)
        submit_color = Color(24, 70, 82, 255) if _rr_mouse_in(submit_rect, mx, my) else Color(15, 51, 62, 255)
        draw_rectangle(*submit_rect, submit_color)
        draw_rectangle_lines(*submit_rect, cyan)
        draw_text("AUTHENTICATE", submit_rect[0] + 20, submit_rect[1] + 13, 14, text_main)

        if rr_terminal_notice and rr_terminal_notice_timer > 0.0:
            notice_color = amber if ("DENIED" in rr_terminal_notice or "INVALID" in rr_terminal_notice) else cyan
            draw_text(rr_terminal_notice[:94], bx + 32, by + 350, 13, notice_color)
        else:
            draw_text("ARCHIVE STATUS: SEALED  //  AUTHENTICATION REQUIRED",
                      bx + 32, by + 350, 13, text_muted)
        status_y = by + bh - 63
        draw_rectangle(bx + 28, status_y, bw - 56, 1, Color(37, 65, 74, 255))
        draw_text("ENCRYPTED ARCHIVE  •  READ ACCESS LOCKED  •  LOCAL LOGIN ONLY",
                  bx + 32, status_y + 17, 12, text_muted)

    elif rr_terminal_stage == "unlocking":
        draw_text("TOKEN ACCEPTED // OPENING DIRECTORY", bx + 32, by + 150, 22, green)
        progress = max(0.0, min(1.0, rr_terminal_unlock_elapsed / max(0.01, rr_terminal_unlock_duration)))
        cx = SCREEN_WIDTH // 2
        cy = by + 275
        segments = 40
        lit = int(segments * progress)
        draw_circle_lines(cx, cy, 43, Color(34, 62, 72, 255))
        for i in range(segments):
            angle = (2.0 * math.pi * i / segments) - (math.pi / 2.0)
            dot_x = int(cx + math.cos(angle) * 35)
            dot_y = int(cy + math.sin(angle) * 35)
            draw_circle(dot_x, dot_y, 3.4, cyan if i < lit else Color(43, 69, 77, 255))
        label = "UNLOCKING ARCHIVE..."
        draw_text(label, cx - measure_text(label, 23) // 2, cy + 65, 23, cyan)
        sub = "Verifying access key and mounting memory database"
        draw_text(sub, cx - measure_text(sub, 14) // 2, cy + 105, 14, text_muted)
        track = (cx - min(210, (bw - 120) // 2), cy + 146, min(420, bw - 120), 6)
        draw_rectangle(*track, Color(29, 47, 55, 255))
        draw_rectangle(track[0], track[1], int(track[2] * progress), track[3], cyan)
        draw_text(f"{int(progress * 100):02d}%", cx - 18, track[1] + 18, 13, text_muted)

    elif rr_terminal_stage == "folders" and rr_terminal_open_folder < 0:
        # The four clickable folder hitboxes are drawn as actual desktop shortcuts over a
        # low-poly industrial workstation wallpaper, matching the isolated Research Room.
        terminal_draw_desktop_wallpaper(bx, by, bw, bh)
        draw_rectangle_lines(bx, by, bw, bh, border)
        draw_text("AUTHENTICATED", bx + bw - 156, by + 43, 10, green)
        if rr_terminal_notice and rr_terminal_notice_timer > 0.0:
            draw_text(rr_terminal_notice[:84], bx + 176, by + bh - 47, 10, cyan)
        draw_text("E / ESC  CLOSE COMPUTER", bx + bw - 202, by + bh - 47, 10, text_muted)

    elif rr_terminal_stage == "folders" and 0 <= rr_terminal_open_folder < len(RR_TERMINAL_FOLDERS):
        folder = RR_TERMINAL_FOLDERS[rr_terminal_open_folder]
        draw_rectangle(bx + 1, by + 1, bw - 2, bh - 2, bg)
        draw_rectangle(bx, by, bw, 37, Color(5, 12, 19, 255))
        draw_line(bx, by + 37, bx + bw, by + 37, Color(50, 93, 106, 255))
        draw_text("PC-07  /  FILE EXPLORER", bx + 17, by + 12, 12, Color(177, 207, 210, 255))
        draw_text("LOCAL WORKSTATION", bx + bw - 174, by + 12, 11, cyan_dim)
        draw_text("ACCESS GRANTED  /  FILE EXPLORER", bx + 30, by + 70, 14, green)
        draw_text(folder["name"], bx + 30, by + 99, 21, text_main)
        path = "LOCAL DISK (C:)  >  SECTOR_B  >  " + folder["name"].replace(" ", "_")
        draw_text(path, bx + 30, by + 130, 11, cyan_dim)

        left_x = bx + 30
        left_w = int((bw - 75) * 0.54)
        details_x = left_x + left_w + 15
        details_w = bx + bw - 30 - details_x
        list_y = by + 190
        draw_rectangle(left_x, list_y - 28, left_w, 22, panel2)
        draw_text("NAME", left_x + 12, list_y - 22, 10, text_muted)
        draw_text("STATUS", left_x + left_w - 86, list_y - 22, 10, text_muted)

        for file_index, (filename, rect) in enumerate(zip(folder["files"], file_rects)):
            rx, ry, rw, rh = rect
            selected = rr_terminal_selected_file == file_index
            row_bg = Color(29, 62, 72, 255) if selected else (panel if file_index % 2 == 0 else panel2)
            row_border = cyan if selected else Color(35, 72, 82, 255)
            draw_rectangle(rx, ry, rw, rh, row_bg)
            draw_rectangle_lines(rx, ry, rw, rh, row_border)
            draw_rectangle(rx + 10, ry + 10, 16, 21, Color(133, 166, 166, 255))
            draw_line(rx + 14, ry + 16, rx + 23, ry + 16, Color(17, 37, 44, 255))
            draw_line(rx + 14, ry + 20, rx + 23, ry + 20, Color(17, 37, 44, 255))
            draw_line(rx + 14, ry + 24, rx + 21, ry + 24, Color(17, 37, 44, 255))
            name_font = 12 if len(filename) > 22 else 14
            draw_text(filename, rx + 36, ry + 13, name_font, text_main)
            row_status = "VERIFIED" if (rr_terminal_file_loaded and rr_terminal_open_folder == 2 and file_index == 2) else "INDEXED"
            status_color = green if row_status == "VERIFIED" else cyan_dim
            draw_text(row_status, rx + rw - measure_text(row_status, 9) - 10, ry + 15, 9, status_color)

        details_y = list_y - 28
        details_h = 218
        draw_rectangle(details_x, details_y, details_w, details_h, panel)
        draw_rectangle_lines(details_x, details_y, details_w, details_h, border)
        draw_rectangle(details_x, details_y, details_w, 26, panel2)
        draw_text("FILE DETAILS", details_x + 12, details_y + 8, 11, cyan)
        detail = terminal_file_details(rr_terminal_open_folder, rr_terminal_selected_file)
        if detail:
            status_col = green if detail["valid"] else (amber if "INCOMPLETE" in detail["status"] or "LEGACY" in detail["status"] else cyan_dim)
            sy = details_y + 39
            for line in wrap_text(detail["status"], 12, details_w - 24)[:2]:
                draw_text(line, details_x + 12, sy, 12, status_col)
                sy += 15
            sy += 5
            for line in wrap_text(detail["summary"], 11, details_w - 24)[:3]:
                draw_text(line, details_x + 12, sy, 11, text_muted)
                sy += 14
            sy += 5
            for line in detail["lines"][:3]:
                line_col = green if (rr_terminal_open_folder == 2 and detail["valid"]) else text_muted
                draw_text(line, details_x + 12, sy, 10, line_col)
                sy += 14
        else:
            draw_text("Select a file to inspect its metadata.", details_x + 12, details_y + 48, 11, text_muted)
            draw_text("Compare the records before loading.", details_x + 12, details_y + 66, 11, text_muted)

        if rr_terminal_open_folder == 2:
            clue_y = list_y + 3 * 52 + 4
            draw_rectangle(left_x, clue_y, left_w, 78, Color(12, 23, 29, 255))
            draw_rectangle_lines(left_x, clue_y, left_w, 78, Color(51, 91, 98, 255))
            draw_text("ARCHIVE INTEGRITY CHECK", left_x + 12, clue_y + 10, 11, cyan)
            draw_text("EXP-09  MEMORY CAPTURE", left_x + 12, clue_y + 31, 10, text_muted)
            draw_text("EXP-12  MEMORY STORAGE", left_x + 12, clue_y + 45, 10, text_muted)
            draw_text("EXP-17  PATTERN RECONSTRUCTION", left_x + 12, clue_y + 59, 10, text_muted)
            load_x, load_y, load_w, load_h = terminal_load_file_rect()
            if rr_terminal_transfer_active:
                button_fill, button_edge = Color(18, 55, 68, 255), cyan
                button_label, button_text = "TRANSFERRING ARCHIVE...", text_main
            elif rr_terminal_file_loaded and rr_terminal_selected_file == 2:
                button_fill, button_edge = Color(22, 70, 48, 255), green
                button_label, button_text = "TRANSFER COMPLETE", text_main
            else:
                button_fill = Color(22, 65, 60, 255) if rr_terminal_selected_file >= 0 else panel2
                button_edge = cyan if rr_terminal_selected_file >= 0 else border
                button_label, button_text = "TRANSFER FILE  >", cyan
            draw_rectangle(load_x, load_y, load_w, load_h, button_fill)
            draw_rectangle_lines(load_x, load_y, load_w, load_h, button_edge)
            if rr_terminal_transfer_active:
                draw_rectangle(load_x + 11, load_y + 10, 13, 16, Color(92, 157, 166, 255))
                draw_rectangle_lines(load_x + 11, load_y + 10, 13, 16, Color(185, 226, 232, 255))
                draw_line(load_x + 27, load_y + 18, load_x + 39, load_y + 18, cyan)
                draw_triangle(Vector2(load_x + 39, load_y + 14), Vector2(load_x + 45, load_y + 18),
                              Vector2(load_x + 39, load_y + 22), cyan)
                draw_rectangle(load_x + 47, load_y + 10, 13, 16, Color(36, 88, 95, 255))
                draw_rectangle_lines(load_x + 47, load_y + 10, 13, 16, cyan)
                label_w = measure_text(button_label, 12)
                draw_text(button_label, load_x + (load_w - label_w) // 2 + 18, load_y + 12, 12, button_text)
            else:
                draw_text(button_label, load_x + (load_w - measure_text(button_label, 12)) // 2,
                          load_y + 12, 12, button_text)

        back_rect = terminal_folder_back_rect()
        hover_back = _rr_mouse_in(back_rect, mx, my)
        draw_rectangle(*back_rect, Color(20, 48, 57, 255) if hover_back else panel2)
        draw_rectangle_lines(*back_rect, cyan if hover_back else border)
        draw_text("<  BACK TO DESKTOP", back_rect[0] + 12, back_rect[1] + 9, 12, cyan)

    # Timed transfer progress remains visible and locked until all 24 records are staged.
    if rr_terminal_transfer_active:
        track = (bx + 32, by + bh - 82, bw - 64, 10)
        draw_rectangle(*track, Color(20, 39, 44, 255))
        progress = max(0.0, min(1.0, rr_terminal_transfer_elapsed / max(0.1, rr_terminal_transfer_duration)))
        draw_rectangle(track[0], track[1], int(track[2] * progress), track[3], green)
        draw_text(f"TRANSFERRING ARCHIVE RECORDS  //  {int(progress * 24):02d}/24",
                  bx + 32, by + bh - 109, 13, green)
    if rr_terminal_notice and (rr_terminal_notice_timer > 0.0 or rr_terminal_transfer_active):
        # Keep notices away from the BACK TO DESKTOP hitbox and the transfer bar.
        if rr_terminal_stage == "folders" and rr_terminal_open_folder >= 0:
            note_y = by + bh - (138 if rr_terminal_transfer_active else 120)
            note_color = green if ("LOADED" in rr_terminal_notice or "ACCEPTED" in rr_terminal_notice or "VERIFIED" in rr_terminal_notice) else amber
            draw_text(rr_terminal_notice[:105], bx + 32, note_y, 11, note_color)
        elif rr_terminal_stage != "folders":
            note_color = green if ("LOADED" in rr_terminal_notice or "ACCEPTED" in rr_terminal_notice or "VERIFIED" in rr_terminal_notice) else amber
            draw_text(rr_terminal_notice[:105], bx + 32, by + bh - 36, 11, note_color)
    if rr_terminal_file_loaded:
        draw_text("24 RECORDS VERIFIED", bx + bw - 190, by + 60, 11, green)
    footer = "E / ESC: CLOSE TERMINAL" if not rr_terminal_transfer_active else "TRANSFER LOCKED // DO NOT INTERRUPT"
    if not (rr_terminal_stage == "folders" and rr_terminal_open_folder < 0):
        draw_text(footer, bx + 32, by + bh - 18, 10, text_muted)


def rr_draw_memory_station_ui():
    mouse_pos = get_mouse_position()
    layout = _rr_memory_layout()
    box_x, box_y, box_w, box_h = layout["panel"]
    ui_bg = Color(7, 13, 18, 250)
    panel = Color(14, 27, 34, 255)
    panel2 = Color(18, 36, 44, 255)
    border = Color(52, 111, 126, 255)
    cyan = Color(105, 225, 235, 255)
    cyan_dim = Color(66, 146, 160, 255)
    text_main = Color(227, 238, 236, 255)
    text_muted = Color(141, 169, 174, 255)
    green = Color(105, 231, 151, 255)
    amber = Color(233, 184, 91, 255)
    red = Color(235, 102, 87, 255)

    draw_rectangle(box_x, box_y, box_w, box_h, ui_bg)
    draw_rectangle_lines(box_x, box_y, box_w, box_h, border)
    draw_rectangle_lines(box_x + 4, box_y + 4, box_w - 8, box_h - 8, Color(30, 61, 71, 255))
    # Inset corner markers and a restrained header rail match the archive computer UI.
    draw_rectangle(box_x + 10, box_y + 10, box_w - 20, 55, panel)
    draw_rectangle(box_x + 10, box_y + 65, box_w - 20, 2, border)
    draw_rectangle(box_x + 12, box_y + 12, 3, 49, cyan_dim)
    draw_rectangle(box_x + 20, box_y + 12, 22, 3, Color(89, 163, 174, 255))
    draw_text("MNEMOSYNE-IV  //  ECHO TRANSFER INTERFACE", box_x + 27, box_y + 18, 20, cyan)
    draw_text("NEURAL MEMORY INTEGRATION ARRAY  |  LOCAL CONTROL", box_x + 29, box_y + 43, 12, cyan_dim)
    led = green if rr_memory_stage == "completed" else amber if rr_memory_stage in ("needs_archive", "intro", "calibration") else cyan
    draw_circle(box_x + box_w - 34, box_y + 31, 7, Color(30, 55, 62, 255))
    draw_circle(box_x + box_w - 34, box_y + 31, 3, led)

    draw_line(box_x + 22, box_y + box_h - 39, box_x + box_w - 22, box_y + box_h - 39, Color(32, 61, 70, 220))

    if rr_memory_stage == "story_diagnostic":
        draw_text("RESIDUAL SESSION DETECTED", box_x + 46, box_y + 105, 24, cyan)
        draw_text("SUBJECT RECORD  //  EXP-09", box_x + 46, box_y + 147, 18, text_main)
        diagnostic_rows = [
            ("CAPTURE", "DAMAGED", red),
            ("STORAGE", "CORRUPTED", amber),
            ("RECONSTRUCTION", "INCOMPLETE", red),
        ]
        row_y = box_y + 194
        for label, value, value_col in diagnostic_rows:
            draw_rectangle(box_x + 46, row_y, box_w - 92, 38, panel)
            draw_rectangle_lines(box_x + 46, row_y, box_w - 92, 38, Color(43, 76, 87, 255))
            draw_text(label, box_x + 60, row_y + 11, 13, text_muted)
            draw_text(value, box_x + box_w - 230, row_y + 10, 14, value_col)
            row_y += 49
        draw_rectangle(box_x + 46, row_y + 3, box_w - 92, 50, Color(32, 24, 13, 255))
        draw_rectangle_lines(box_x + 46, row_y + 3, box_w - 92, 50, amber)
        draw_text("MANUAL RECOVERY REQUIRED", box_x + 62, row_y + 20, 15, amber)
        draw_text("The session cannot be reconstructed until the missing experiment sequence is recovered.",
                  box_x + 46, row_y + 68, 12, text_muted)
        draw_text("E / ESC: CLOSE DIAGNOSTIC  //  RETURN TO THE EVIDENCE BOARD",
                  box_x + 42, box_y + box_h - 23, 10, cyan_dim)

    elif rr_memory_stage == "needs_archive":
        draw_text("MEMORY ARCHIVE NOT STAGED", box_x + 46, box_y + 145, 25, red)
        draw_text("Return to workstation PC-07 and transfer ECHO_MEMORY_ARCHIVE_01-24 first.",
                  box_x + 46, box_y + 193, 15, text_muted)
        draw_rectangle(box_x + 46, box_y + 239, box_w - 92, 86, panel)
        draw_rectangle_lines(box_x + 46, box_y + 239, box_w - 92, 86, border)
        draw_text("REQUIRED INPUT  //  24 VERIFIED MEMORY RECORDS", box_x + 66, box_y + 271, 16, cyan)
        draw_text("TRANSFER LINK: OFFLINE", box_x + 66, box_y + 296, 13, red)

    elif rr_memory_stage == "intro":
        cx = box_x + box_w // 2
        draw_text("ARCHIVE DETECTED", cx - measure_text("ARCHIVE DETECTED", 27) // 2, box_y + 126, 27, cyan)
        draw_text("24 MEMORY RECORDS READ", cx - measure_text("24 MEMORY RECORDS READ", 20) // 2,
                  box_y + 174, 20, text_main)
        draw_text("TRANSFER LINK: UNSTABLE", cx - measure_text("TRANSFER LINK: UNSTABLE", 19) // 2,
                  box_y + 211, 19, amber)
        ring_cx, ring_cy = cx, box_y + 335
        draw_circle_lines(ring_cx, ring_cy, 39, Color(35, 66, 76, 255))
        ring_progress = min(1.0, rr_memory_intro_elapsed / 2.8)
        lit = int(36 * ring_progress)
        for segment in range(36):
            angle = (2.0 * math.pi * segment / 36.0) - math.pi / 2.0
            px = int(ring_cx + math.cos(angle) * 31)
            py = int(ring_cy + math.sin(angle) * 31)
            draw_circle(px, py, 2.8, cyan if segment < lit else Color(37, 61, 70, 255))
        draw_text("INITIALISING SIGNAL DIAGNOSTICS...",
                  cx - measure_text("INITIALISING SIGNAL DIAGNOSTICS...", 13) // 2,
                  ring_cy + 57, 13, text_muted)

    elif rr_memory_stage == "calibration":
        draw_text("ARCHIVE DETECTED", box_x + 28, box_y + 82, 12, green)
        draw_text("24 RECORDS READ", box_x + 190, box_y + 82, 12, cyan)
        draw_text("TRANSFER LINK: UNSTABLE", box_x + box_w - 250, box_y + 82, 12, amber)
        active_channel = RR_MEMORY_UPLOAD_CHANNELS[rr_memory_channel_index]
        calibration_title = f"SIGNAL CALIBRATION  //  CHANNEL {rr_memory_channel_index + 1} OF 3"
        draw_text(calibration_title, box_x + 28, box_y + 101, 14, text_main)
        # Compact three-step progress rail: channels already stabilised, current, and pending.
        step_names = ["09 CAPTURE", "12 STORAGE", "17 REBUILD"]
        step_total_w = 258
        step_gap = 6
        step_w = (step_total_w - step_gap * 2) // 3
        step_x0 = box_x + box_w - step_total_w - 28
        step_y = box_y + 98
        for step_i, step_name in enumerate(step_names):
            step_x = step_x0 + step_i * (step_w + step_gap)
            is_done = rr_memory_channels_locked[step_i]
            is_current = step_i == rr_memory_channel_index
            step_bg = Color(19, 57, 43, 255) if is_done else Color(24, 54, 63, 255) if is_current else Color(9, 21, 28, 255)
            step_edge = green if is_done else cyan if is_current else Color(39, 68, 78, 255)
            draw_rectangle(step_x, step_y, step_w, 20, step_bg)
            draw_rectangle_lines(step_x, step_y, step_w, 20, step_edge)
            label_text = step_name if step_w >= 78 else step_name[:6]
            label_size = 9
            label_width = measure_text(label_text, label_size)
            draw_text(label_text, step_x + (step_w - label_width) // 2, step_y + 6, label_size,
                      green if is_done else cyan if is_current else text_muted)

        for idx, (rx, ry, rw, rh) in enumerate(layout["rows"]):
            channel = RR_MEMORY_UPLOAD_CHANNELS[idx]
            locked = rr_memory_channels_locked[idx]
            is_active = idx == rr_memory_channel_index
            awaiting = idx > rr_memory_channel_index
            card_bg = panel if is_active else Color(10, 20, 26, 255)
            card_border = green if locked else cyan if is_active else Color(33, 66, 75, 255)
            draw_rectangle(rx, ry, rw, rh, card_bg)
            draw_rectangle_lines(rx, ry, rw, rh, card_border)
            stripe_col = green if locked else cyan if is_active else Color(38, 67, 75, 255)
            draw_rectangle(rx + 1, ry + 3, 3, rh - 6, stripe_col)
            # Small numbered badge separates the process stage from its experiment reference.
            badge_col = Color(19, 67, 48, 255) if locked else Color(17, 43, 51, 255) if is_active else Color(10, 22, 28, 255)
            badge_border = green if locked else cyan_dim if is_active else Color(37, 63, 71, 255)
            draw_rectangle(rx + 11, ry + 10, 25, 24, badge_col)
            draw_rectangle_lines(rx + 11, ry + 10, 25, 24, badge_border)
            draw_text(f"{idx + 1:02d}", rx + 15, ry + 16, 11, green if locked else cyan if is_active else text_muted)

            title_color = green if locked else text_main if is_active else text_muted
            draw_text(channel["label"], rx + 43, ry + 10, 14, title_color)
            draw_text(channel["experiment"], rx + 43, ry + 31, 12, cyan_dim if not locked else green)
            height_in_range = abs(rr_memory_channel_height - channel["target_height"]) <= channel["height_tolerance"]
            spacing_in_range = abs(rr_memory_channel_spacing - channel["target_spacing"]) <= channel["spacing_tolerance"]
            current_match = is_active and height_in_range and spacing_in_range
            if locked:
                state_label, state_col = "STABLE / LOCKED", green
            elif is_active and current_match:
                state_label, state_col = "MATCH CLOSE  /  READY", green
            elif is_active:
                state_label, state_col = "TUNE SIGNAL", amber
            else:
                state_label, state_col = "AWAITING", text_muted
            draw_text(state_label, rx + 12, ry + 58, 10, state_col)

            label_w = 188
            wave_gap = 18
            wave_left = rx + label_w
            wave_w = max(70, (rw - label_w - 22 - wave_gap) // 2)
            wave_right = wave_left + wave_w + wave_gap
            draw_text("TARGET  /  REFERENCE", wave_left + 2, ry + 7, 9, cyan_dim)
            draw_text("LIVE SIGNAL", wave_right + 2, ry + 7, 9, green if locked or current_match else amber if is_active else text_muted)
            wave_y = ry + 24
            wave_h = rh - 29
            _rr_draw_memory_upload_waveform(wave_left, wave_y, wave_w, wave_h,
                                        channel["target_height"], channel["target_spacing"], cyan_dim)
            if locked:
                live_height = channel["target_height"]
                live_spacing = channel["target_spacing"]
                live_col = green
                jitter = 0.0
            elif is_active:
                live_height = rr_memory_channel_height
                live_spacing = rr_memory_channel_spacing
                close_enough = (abs(rr_memory_channel_height - channel["target_height"]) <= channel["height_tolerance"] and
                                abs(rr_memory_channel_spacing - channel["target_spacing"]) <= channel["spacing_tolerance"])
                live_col = green if close_enough else amber
                jitter = 0.22 if close_enough else 0.72
            else:
                live_height = channel["start_height"]
                live_spacing = channel["start_spacing"]
                live_col = Color(58, 91, 95, 255)
                jitter = 0.28
            _rr_draw_memory_upload_waveform(wave_right, wave_y, wave_w, wave_h,
                                        live_height, live_spacing, live_col,
                                        phase=(math.sin(global_time * 2.2) * 0.025 if is_active else 0.0),
                                        instability=jitter)

        button_labels = ["−  DECREASE HEIGHT", "+  INCREASE HEIGHT",
                         "−  DECREASE SPACING", "+  INCREASE SPACING"]
        if layout["buttons"]:
            first_bx, first_by, first_bw, _ = layout["buttons"][0]
            second_group_x = layout["buttons"][2][0]
            group_y = first_by - 20
            draw_text("AMPLITUDE / WAVE HEIGHT", first_bx + 2, group_y, 9, cyan_dim)
            draw_text("WAVELENGTH / WAVE SPACING", second_group_x + 2, group_y, 9, cyan_dim)
        for idx, (bx, by, bw, bh) in enumerate(layout["buttons"]):
            hovered = bx <= mouse_pos.x <= bx + bw and by <= mouse_pos.y <= by + bh
            at_limit = ((idx == 0 and rr_memory_channel_height <= 1) or
                        (idx == 1 and rr_memory_channel_height >= 8) or
                        (idx == 2 and rr_memory_channel_spacing <= 3) or
                        (idx == 3 and rr_memory_channel_spacing >= 9))
            btn_bg = Color(24, 53, 62, 255) if hovered and not at_limit else Color(10, 22, 28, 255) if at_limit else panel2
            btn_border = cyan if hovered and not at_limit else Color(31, 56, 63, 255) if at_limit else border
            draw_rectangle(bx, by, bw, bh, btn_bg)
            draw_rectangle_lines(bx, by, bw, bh, btn_border)
            label = button_labels[idx]
            label_size = 13 if bw >= 200 else 11
            label_w = measure_text(label, label_size)
            label_color = Color(73, 107, 113, 255) if at_limit else text_main if hovered else cyan
            draw_text(label, bx + (bw - label_w) // 2, by + (bh - label_size) // 2 - 1,
                      label_size, label_color)

        # Two compact parameter meters flank the lock button; they stay out of its hitbox.
        meter_y = box_y + 491
        left_meter_x = box_x + 28
        meter_w = 205
        draw_rectangle(left_meter_x, meter_y - 2, meter_w, 42, Color(10, 21, 27, 255))
        draw_rectangle_lines(left_meter_x, meter_y - 2, meter_w, 42, Color(39, 72, 82, 255))
        draw_text(f"HEIGHT  {rr_memory_channel_height}/8", left_meter_x + 9, meter_y + 3, 11, cyan)
        for step in range(8):
            seg_x = left_meter_x + 10 + step * 23
            seg_col = cyan if step < rr_memory_channel_height else Color(34, 55, 63, 255)
            draw_rectangle(seg_x, meter_y + 21, 18, 7, seg_col)

        right_meter_x = box_x + box_w - 28 - meter_w
        draw_rectangle(right_meter_x, meter_y - 2, meter_w, 42, Color(10, 21, 27, 255))
        draw_rectangle_lines(right_meter_x, meter_y - 2, meter_w, 42, Color(39, 72, 82, 255))
        draw_text(f"SPACING  {rr_memory_channel_spacing}/9", right_meter_x + 9, meter_y + 3, 11, cyan)
        for step in range(7):
            seg_x = right_meter_x + 10 + step * 26
            seg_col = amber if step < max(0, rr_memory_channel_spacing - 2) else Color(34, 55, 63, 255)
            draw_rectangle(seg_x, meter_y + 21, 21, 7, seg_col)

        # Live tuning guide makes the target understandable without exposing
        # exact target numbers; it tells the player which direction to adjust.
        guide_height_ok = abs(rr_memory_channel_height - active_channel["target_height"]) <= active_channel["height_tolerance"]
        guide_spacing_ok = abs(rr_memory_channel_spacing - active_channel["target_spacing"]) <= active_channel["spacing_tolerance"]
        if guide_height_ok:
            height_guide = "HEIGHT: WITHIN RANGE"
        elif rr_memory_channel_height < active_channel["target_height"]:
            height_guide = "HEIGHT TOO LOW / INCREASE"
        else:
            height_guide = "HEIGHT TOO HIGH / DECREASE"
        if guide_spacing_ok:
            spacing_guide = "SPACING: WITHIN RANGE"
        elif rr_memory_channel_spacing < active_channel["target_spacing"]:
            spacing_guide = "SPACING TOO TIGHT / INCREASE"
        else:
            spacing_guide = "SPACING TOO WIDE / DECREASE"
        guide_y = box_y + 574
        guide_color = green if guide_height_ok and guide_spacing_ok else amber
        guide_panel_w = (box_w - 76) // 2
        guide_items = [(height_guide, guide_height_ok), (spacing_guide, guide_spacing_ok)]
        for gi, (guide_label, guide_ok) in enumerate(guide_items):
            gx = box_x + 28 + gi * (guide_panel_w + 20)
            gcol = green if guide_ok else amber
            gbg = Color(12, 36, 28, 255) if guide_ok else Color(40, 31, 15, 255)
            draw_rectangle(gx, guide_y - 4, guide_panel_w, 23, gbg)
            draw_rectangle_lines(gx, guide_y - 4, guide_panel_w, 23, Color(gcol.r, gcol.g, gcol.b, 155))
            short_label = ("HEIGHT  /  MATCH" if guide_ok and gi == 0 else
                           "SPACING  /  MATCH" if guide_ok else guide_label)
            draw_text(short_label, gx + 8, guide_y + 2, 10, gcol)

        lx, ly, lw, lh = layout["lock"]
        lock_hovered = lx <= mouse_pos.x <= lx + lw and ly <= mouse_pos.y <= ly + lh
        draw_rectangle(lx, ly, lw, lh, Color(25, 72, 48, 255) if lock_hovered else Color(16, 48, 37, 255))
        draw_rectangle_lines(lx, ly, lw, lh, green if lock_hovered else Color(67, 153, 96, 255))
        lock_label = "LOCK CHANNEL  /  TEST STABILITY"
        draw_text(lock_label, lx + (lw - measure_text(lock_label, 14)) // 2, ly + 12, 14, green)

        if rr_memory_notice and rr_memory_notice_timer > 0.0:
            notice_col = red if "OUT OF RANGE" in rr_memory_notice else green if "STABLE" in rr_memory_notice else cyan_dim
            notice_y = box_y + 548
            draw_text(rr_memory_notice,
                      box_x + (box_w - measure_text(rr_memory_notice, 12)) // 2,
                      notice_y, 12, notice_col)
        draw_text("TUNE BOTH PROPERTIES; A CLOSE MATCH IS ENOUGH. A FAILED TEST DOES NOT RESET PREVIOUS CHANNELS.",
                  box_x + 28, box_y + box_h - 48, 10, text_muted)

    elif rr_memory_stage == "transferring":
        progress = max(0.0, min(1.0, rr_memory_transfer_elapsed / max(0.01, rr_memory_transfer_duration)))
        cx = box_x + box_w // 2
        draw_text("MEMORY ARCHIVE INTEGRATION IN PROGRESS", cx - measure_text("MEMORY ARCHIVE INTEGRATION IN PROGRESS", 22) // 2,
                  box_y + 121, 22, cyan)
        draw_text("ALL THREE CHANNELS STABLE  //  NEURAL LINK ONLINE",
                  cx - measure_text("ALL THREE CHANNELS STABLE  //  NEURAL LINK ONLINE", 13) // 2,
                  box_y + 158, 13, green)
        # Animated link nodes imitate the chair's transfer hardware engaging while
        # batches move through the neural interface.
        node_y = box_y + 224
        node_w = min(500, box_w - 140)
        node_x = cx - node_w // 2
        for i in range(11):
            nx = node_x + int(node_w * i / 10)
            active_node = i <= int(progress * 10) or (i == int((global_time * 4.0) % 11))
            node_col = cyan if active_node else Color(34, 66, 74, 255)
            draw_circle(nx, node_y, 5 if active_node else 3, node_col)
            if i > 0:
                draw_line(node_x + int(node_w * (i - 1) / 10), node_y, nx, node_y, Color(44, 94, 105, 255))
        bar_w = min(700, box_w - 150)
        bar_x = cx - bar_w // 2
        bar_y = box_y + 286
        draw_rectangle(bar_x, bar_y, bar_w, 18, Color(7, 17, 23, 255))
        draw_rectangle_lines(bar_x, bar_y, bar_w, 18, border)
        fill_w = int((bar_w - 2) * progress)
        if fill_w > 0:
            draw_rectangle(bar_x + 1, bar_y + 1, fill_w, 16, cyan)
        for tick in range(1, 24):
            tx = bar_x + int(bar_w * tick / 24)
            draw_line(tx, bar_y + 1, tx, bar_y + 17, Color(15, 40, 48, 255))
        percent_text = f"{int(progress * 100):02d}%"
        count_text = f"{rr_memory_records:02d} / 24 RECORDS INTEGRATED"
        draw_text(count_text, bar_x, bar_y + 31, 15, text_main)
        draw_text(percent_text, bar_x + bar_w - measure_text(percent_text, 15), bar_y + 31, 15, cyan)
        if progress < 0.25:
            status_text = "ESTABLISHING NEURAL HANDSHAKE..."
        elif progress < 0.66:
            status_text = "TRANSFERRING MEMORY BATCHES..."
        elif progress < 0.88:
            status_text = "RECONSTRUCTING PATTERN INDEX..."
        else:
            status_text = "VERIFYING ALL MEMORY RECORDS..."
        draw_text(status_text, cx - measure_text(status_text, 15) // 2, bar_y + 76, 15, amber)
        # Channel lamps light together while the memory batches are integrated.
        lamp_y = box_y + 423
        for i, channel in enumerate(RR_MEMORY_UPLOAD_CHANNELS):
            lamp_x = cx - 210 + i * 210
            draw_circle(lamp_x, lamp_y, 7, cyan if (int(global_time * 5.0) + i) % 3 else green)
            draw_text(channel["label"], lamp_x - measure_text(channel["label"], 11) // 2, lamp_y + 18, 11, text_muted)

    elif rr_memory_stage == "completed":
        cx = box_x + box_w // 2
        success_y = box_y + 135
        draw_circle(cx, success_y + 28, 35, Color(17, 62, 43, 255))
        draw_circle_lines(cx, success_y + 28, 35, green)
        draw_line(cx - 15, success_y + 28, cx - 4, success_y + 40, green)
        draw_line(cx - 4, success_y + 40, cx + 18, success_y + 14, green)
        title = "MEMORY ARCHIVE INTEGRATED"
        draw_text(title, cx - measure_text(title, 24) // 2, success_y + 83, 24, green)
        result = "24 / 24 RECORDS LOADED"
        draw_text(result, cx - measure_text(result, 22) // 2, success_y + 126, 22, text_main)
        draw_text("TRANSFER COMPLETE  //  ALL THREE MEMORY CHANNELS STABLE",
                  cx - measure_text("TRANSFER COMPLETE  //  ALL THREE MEMORY CHANNELS STABLE", 13) // 2,
                  success_y + 169, 13, cyan)

    else:
        # Defensive fallback: do not show generic document text if a state changes unexpectedly.
        draw_text("ECHO TRANSFER INTERFACE INITIALISING...", box_x + 40, box_y + 125, 19, cyan)

    if rr_memory_stage == "transferring":
        footer = "MEMORY INTEGRATION IN PROGRESS  //  PLEASE WAIT"
    else:
        footer = "E / ESC  CLOSE INTERFACE"
    draw_text(footer, box_x + box_w - measure_text(footer, 11) - 26, box_y + box_h - 25, 11, text_muted)


def rr_draw_erlenmeyer_flask(pos, rot, fluid_level=0.72):
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot.x, 1, 0, 0)
    rl_rotatef(rot.y, 0, 1, 0)
    rl_rotatef(rot.z, 0, 0, 1)
    draw_pbr_cone(Vector3(0, 0.14, 0), 0.22, 0.28, C_GLASS_EDGE, roughness=0.1, metallic=0.05)
    draw_pbr_cylinder(Vector3(0, 0.02, 0), 0.22, 0.04, C_GLASS_EDGE, roughness=0.15, metallic=0.05)
    fluid_h = 0.22 * fluid_level
    draw_pbr_cone(Vector3(0, fluid_h / 2.0 + 0.02, 0), 0.2, fluid_h, C_BEAKER_FLUID, roughness=0.15, metallic=0.0, emissive=Vector3(0.12, 0.85, 0.35))
    draw_pbr_cylinder(Vector3(0, fluid_h + 0.02, 0), 0.2 * (1.0 - fluid_level * 0.45), 0.02, C_BEAKER_FLUID, roughness=0.1, metallic=0.0, emissive=Vector3(0.18, 0.95, 0.4))
    for i in range(4):
        ty = 0.06 + i * 0.05
        tw = 0.05 - i * 0.008
        draw_pbr_box(Vector3(0.15 - i * 0.025, ty, 0), Vector3(tw, 0.005, 0.01), WHITE, roughness=0.4)
    draw_pbr_cylinder(Vector3(0, 0.38, 0), 0.068, 0.2, C_GLASS_EDGE, roughness=0.1, metallic=0.05)
    draw_pbr_torus(Vector3(0, 0.48, 0), 0.072, 0.012, C_GLASS_EDGE, roughness=0.12, metallic=0.05)
    draw_pbr_cone(Vector3(0, 0.51, 0), 0.065, 0.07, C_RUBBER, roughness=0.85, metallic=0.0)
    draw_pbr_cylinder(Vector3(0, 0.58, 0), 0.012, 0.12, C_GLASS, roughness=0.15, metallic=0.1)
    rl_pop_matrix()

def rr_draw_research_microscope(pos, scale=1.0):
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    sc = scale
    draw_pbr_box(Vector3(0, 0.05 * sc, 0), Vector3(0.65 * sc, 0.1 * sc, 0.52 * sc), C_METAL_DARK, roughness=0.45, metallic=0.6)
    draw_pbr_cylinder(Vector3(0, 0.08 * sc, 0.08 * sc), 0.12 * sc, 0.06 * sc, C_CHROME, roughness=0.18, metallic=0.92)
    draw_pbr_box(Vector3(-0.16 * sc, 0.48 * sc, 0), Vector3(0.14 * sc, 0.76 * sc, 0.16 * sc), C_METAL_DARK, roughness=0.45, metallic=0.6)
    draw_pbr_cylinder(Vector3(-0.06 * sc, 0.82 * sc, 0), 0.16 * sc, 0.28 * sc, C_STEEL, roughness=0.3, metallic=0.7)
    draw_pbr_cylinder(Vector3(-0.16 * sc, 0.35 * sc, 0.14 * sc), 0.09 * sc, 0.08 * sc, C_METAL_DARK, roughness=0.35, metallic=0.8)
    draw_pbr_cylinder(Vector3(-0.16 * sc, 0.35 * sc, -0.14 * sc), 0.09 * sc, 0.08 * sc, C_METAL_DARK, roughness=0.35, metallic=0.8)
    draw_pbr_cylinder(Vector3(-0.16 * sc, 0.35 * sc, 0.19 * sc), 0.05 * sc, 0.05 * sc, C_CHROME, roughness=0.15, metallic=0.95)
    draw_pbr_cylinder(Vector3(-0.16 * sc, 0.35 * sc, -0.19 * sc), 0.05 * sc, 0.05 * sc, C_CHROME, roughness=0.15, metallic=0.95)
    draw_pbr_cylinder(Vector3(0.08 * sc, 0.42 * sc, 0), 0.095 * sc, 0.12 * sc, C_STEEL, roughness=0.25, metallic=0.85)
    draw_pbr_box(Vector3(0.08 * sc, 0.54 * sc, 0), Vector3(0.52 * sc, 0.045 * sc, 0.44 * sc), C_METAL_DARK, roughness=0.4, metallic=0.7)
    draw_pbr_box(Vector3(0.08 * sc, 0.57 * sc, 0), Vector3(0.28 * sc, 0.012 * sc, 0.1 * sc), C_GLASS_EDGE, roughness=0.1, metallic=0.1)
    draw_pbr_cylinder(Vector3(0.12 * sc, 0.78 * sc, 0), 0.16 * sc, 0.09 * sc, C_CHROME, roughness=0.15, metallic=0.92)
    obj_colors = [C_RED_DIM, C_AMBER, Color(30, 100, 220, 255), WHITE]
    for i in range(4):
        ang = i * 90.0
        rad = math.radians(ang)
        ox = 0.12 * sc + math.cos(rad) * 0.075 * sc
        oz = math.sin(rad) * 0.075 * sc
        draw_pbr_cylinder(Vector3(ox, 0.68 * sc, oz), 0.032 * sc, 0.14 * sc, C_CHROME, roughness=0.15, metallic=0.92)
        draw_pbr_cylinder(Vector3(ox, 0.64 * sc, oz), 0.034 * sc, 0.025 * sc, obj_colors[i], roughness=0.3)
    draw_pbr_box(Vector3(0.04 * sc, 0.94 * sc, 0), Vector3(0.32 * sc, 0.16 * sc, 0.26 * sc), C_METAL_DARK, roughness=0.4)
    draw_pbr_cylinder(Vector3(0.2 * sc, 1.15 * sc, 0.08 * sc), 0.042 * sc, 0.28 * sc, C_CHROME, roughness=0.15, metallic=0.9)
    draw_pbr_cylinder(Vector3(0.2 * sc, 1.15 * sc, -0.08 * sc), 0.042 * sc, 0.28 * sc, C_CHROME, roughness=0.15, metallic=0.9)
    draw_pbr_torus(Vector3(0.2 * sc, 1.28 * sc, 0.08 * sc), 0.048 * sc, 0.012 * sc, C_RUBBER, roughness=0.85)
    draw_pbr_torus(Vector3(0.2 * sc, 1.28 * sc, -0.08 * sc), 0.048 * sc, 0.012 * sc, C_RUBBER, roughness=0.85)
    rl_pop_matrix()

def rr_draw_oscilloscope(pos, rot_y=0.0, broken=False, time_val=0.0, is_powered=False):
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot_y, 0, 1, 0)
    draw_pbr_box(Vector3(0, 0.32, 0), Vector3(1.05, 0.64, 0.78), C_METAL_MID, roughness=0.5, metallic=0.6)
    for l in range(5):
        draw_pbr_box(Vector3(0.53, 0.22 + l * 0.05, 0), Vector3(0.015, 0.022, 0.45), C_METAL_DARK, roughness=0.8)
    draw_pbr_box(Vector3(0, 0.32, 0.395), Vector3(0.98, 0.58, 0.025), C_METAL_EDGE, roughness=0.4, metallic=0.7)
    active = is_powered or not broken
    crt_color = Color(8, 28, 16, 255) if active else Color(18, 8, 8, 255)
    draw_pbr_box(Vector3(-0.16, 0.36, 0.41), Vector3(0.52, 0.38, 0.025), crt_color, roughness=0.1, metallic=0.1)
    if active:
        glow_intensity = 1.8 if is_powered else 1.2
        pulse_y = math.sin(time_val * 8.0) * 0.04
        draw_pbr_box(Vector3(-0.16, 0.36 + pulse_y, 0.425), Vector3(0.44, 0.02, 0.008), C_CYAN, roughness=0.1, emissive=Vector3(0.2 * glow_intensity, glow_intensity, 0.5 * glow_intensity))
    draw_pbr_cylinder(Vector3(0.25, 0.2, 0.43), 0.032, 0.055, C_CHROME, roughness=0.2, metallic=0.95)
    draw_pbr_cylinder(Vector3(0.38, 0.2, 0.43), 0.032, 0.055, C_CHROME, roughness=0.2, metallic=0.95)
    draw_pbr_cylinder(Vector3(0.25, 0.36, 0.42), 0.055, 0.045, C_METAL_DARK, roughness=0.3, metallic=0.7)
    draw_pbr_cylinder(Vector3(0.38, 0.36, 0.42), 0.055, 0.045, C_METAL_DARK, roughness=0.3, metallic=0.7)
    draw_pbr_cylinder(Vector3(0.25, 0.48, 0.42), 0.042, 0.04, C_AMBER, roughness=0.4)
    draw_pbr_cylinder(Vector3(0.4, 0.48, 0.42), 0.018, 0.025, C_GREEN_DIM if active else C_RED_DIM, roughness=0.2, emissive=Vector3(0.1, 0.8, 0.2) if active else Vector3(0.8, 0.1, 0.1))
    draw_pbr_box(Vector3(0, 0.04, 0.15), Vector3(1.1, 0.025, 0.035), C_CHROME, roughness=0.2, metallic=0.9)
    rl_pop_matrix()

