def rr_draw_server_cabinet(pos, height=3.8, damaged=False, time_val=0.0, is_powered=False):
    """Modular genome-sequencer rack: open chassis, separated compute drawers and visible cooling."""
    width, depth = (1.25, 0.85)
    front_z = pos.z - depth / 2.0 - 0.035
    dark, mid, steel = (C_METAL_DARK, C_METAL_MID, C_STEEL)
    for x in (-width * 0.46, width * 0.46):
        for z in (-depth * 0.4, depth * 0.4):
            draw_pbr_box(Vector3(pos.x + x, pos.y + height / 2, pos.z + z), Vector3(0.085, height, 0.085), steel, roughness=0.32, metallic=0.88)
    draw_pbr_box(Vector3(pos.x, pos.y + 0.12, pos.z), Vector3(width, 0.2, depth), dark, roughness=0.55, metallic=0.7)
    draw_pbr_box(Vector3(pos.x, pos.y + height - 0.1, pos.z), Vector3(width, 0.18, depth), dark, roughness=0.48, metallic=0.75)
    draw_pbr_box(Vector3(pos.x, pos.y + height * 0.52, pos.z + depth * 0.37), Vector3(width - 0.2, height - 0.55, 0.045), C_RUBBER, roughness=0.82)
    bay_count = 6
    usable = height - 0.62
    bay_h = usable / bay_count
    for idx in range(bay_count):
        y = pos.y + 0.36 + idx * bay_h + bay_h / 2
        draw_pbr_box(Vector3(pos.x, y, front_z), Vector3(width - 0.24, bay_h - 0.055, 0.105), dark if not (damaged and idx == 3) else C_RUST2, roughness=0.42, metallic=0.78)
        draw_pbr_box(Vector3(pos.x, y + bay_h * 0.12, front_z - 0.06), Vector3(width - 0.34, bay_h * 0.45, 0.025), mid, roughness=0.3, metallic=0.78)
        for sl in range(4):
            sx = pos.x - 0.29 + sl * 0.095
            draw_pbr_box(Vector3(sx, y - bay_h * 0.18, front_z - 0.078), Vector3(0.055, 0.018, 0.012), C_STEEL, roughness=0.3, metallic=0.85)
        for k in range(3):
            col = (C_CYAN, C_GREEN_DIM, C_AMBER)[(idx + k) % 3]
            draw_pbr_box(Vector3(pos.x + 0.28, y + bay_h * 0.1, front_z - 0.08 + k * 0.001), Vector3(0.075, bay_h * 0.2, 0.016), col, roughness=0.2, emissive=Vector3(0.02, 0.22, 0.28) if is_powered else Vector3(0.005, 0.025, 0.03))
        draw_pbr_box(Vector3(pos.x - 0.43, y, front_z - 0.083), Vector3(0.045, bay_h * 0.34, 0.018), C_CHROME, roughness=0.22, metallic=0.92)
        for sx in (-0.48, 0.48):
            draw_pbr_sphere(Vector3(pos.x + sx, y, front_z - 0.082), 0.022, C_CHROME, roughness=0.2, metallic=0.95)
    for x in (-0.3, 0.0, 0.3):
        draw_pbr_cylinder(Vector3(pos.x + x, pos.y + height - 0.19, pos.z - depth * 0.08), 0.095, 0.035, dark, roughness=0.55, metallic=0.65)
        draw_pbr_torus(Vector3(pos.x + x, pos.y + height - 0.165, pos.z - depth * 0.08), 0.065, 0.009, steel, roughness=0.3, metallic=0.85)
    draw_pbr_box(Vector3(pos.x, pos.y + height - 0.34, front_z - 0.075), Vector3(0.48, 0.075, 0.018), dark, roughness=0.4, metallic=0.7)
    draw_pbr_box(Vector3(pos.x, pos.y + height - 0.34, front_z - 0.087), Vector3(0.3, 0.018, 0.008), C_CYAN if not damaged else C_AMBER, roughness=0.2, emissive=Vector3(0.06, 0.35, 0.45) if is_powered else Vector3(0.01, 0.04, 0.05))
    for y in (pos.y + 0.55, pos.y + height * 0.5, pos.y + height - 0.55):
        draw_pbr_cylinder(Vector3(pos.x + width * 0.51, y, pos.z + 0.12), 0.045, 0.2, C_CHROME, roughness=0.25, metallic=0.9)
        draw_pbr_torus(Vector3(pos.x + width * 0.51, y, pos.z + 0.12), 0.055, 0.012, C_RUST2 if damaged else steel, roughness=0.45, metallic=0.8)

