    draw_pbr_cylinder(Vector3(pos.x, 1.25, pos.z), 0.034, 0.06, Color(35, 38, 42, 255), roughness=0.4)
    draw_pbr_cylinder(Vector3(pos.x, 1.7, pos.z), 0.016, 0.86, C_CHROME, roughness=0.15, metallic=0.95)
    draw_pbr_cylinder(Vector3(pos.x, 2.12, pos.z), 0.024, 0.04, C_CHROME, roughness=0.2, metallic=0.9)
    draw_pbr_cylinder(Vector3(pos.x - 0.12, 2.12, pos.z), 0.008, 0.22, C_CHROME, roughness=0.15, metallic=0.95)
    draw_pbr_cylinder(Vector3(pos.x + 0.12, 2.12, pos.z), 0.008, 0.22, C_CHROME, roughness=0.15, metallic=0.95)
    bag1_pos = Vector3(pos.x - 0.14, 1.88, pos.z)
    draw_pbr_cylinder(Vector3(bag1_pos.x, 2.05, bag1_pos.z), 0.005, 0.12, C_CHROME, roughness=0.2, metallic=0.9)
    draw_pbr_box(bag1_pos, Vector3(0.12, 0.26, 0.04), Color(185, 28, 32, 220), roughness=0.15, metallic=0.05, emissive=Vector3(0.35, 0.04, 0.04))
    draw_pbr_cylinder(Vector3(bag1_pos.x, 1.7, bag1_pos.z), 0.016, 0.08, C_GLASS, roughness=0.1, emissive=Vector3(0.1, 0.02, 0.02))
    bag2_pos = Vector3(pos.x + 0.14, 1.86, pos.z)
