    draw_pbr_cylinder(Vector3(bag2_pos.x, 1.69, bag2_pos.z), 0.016, 0.08, C_GLASS, roughness=0.1)
    draw_pbr_cylinder(Vector3(pos.x + 0.1, 1.45, pos.z), 0.006, 0.45, Color(220, 235, 245, 180), roughness=0.2)
    draw_pbr_cylinder(Vector3(pos.x + 0.35, 1.15, pos.z), 0.006, 0.55, Color(220, 235, 245, 180), roughness=0.2)

