def rr_draw_research_diagnostic_terminal_desk(pos=Vector3(1.85, 0.0, 23.6), time_val=0.0, is_powered=False, is_active=False):
    """
    Research Diagnostic Telemetry Terminal Desk.
    Faithfully matching Picture 2 right workstation:
    - Sturdy industrial steel table frame with lower electronics rack.
    - Large Widescreen Telemetry Display:
      Glowing bright cyan screen (#00E5FF) with live neural EEG waveform traces,
      biometric vital signs, and sector telemetry data.
    - Secondary Square Amber/Yellow Diagnostic Display:
      Mounted to the left of the widescreen monitor, glowing bright yellow/amber (#FFCC00)
      with neural frequency calibration readouts.
    - Desk surface with industrial keyboard, trackball console, and wire bundles.
    - The Clinical Memory Extraction Record sits firmly on this desk at Y = 0.95m!
    """
    desk_w, desk_h, desk_d = (1.65, 0.92, 1.05)
    for lx in (pos.x - desk_w * 0.45, pos.x + desk_w * 0.45):
        for lz in (pos.z - desk_d * 0.45, pos.z + desk_d * 0.45):
            draw_pbr_box(Vector3(lx, desk_h * 0.5, lz), Vector3(0.07, desk_h, 0.07), C_STEEL, roughness=0.35, metallic=0.85)
            draw_pbr_box(Vector3(lx, 0.04, lz), Vector3(0.12, 0.06, 0.12), C_METAL_DARK, roughness=0.5, metallic=0.7)
    draw_pbr_box(Vector3(pos.x, 0.2, pos.z - desk_d * 0.45), Vector3(desk_w * 0.9, 0.05, 0.05), C_STEEL, roughness=0.35, metallic=0.85)
    draw_pbr_box(Vector3(pos.x, 0.2, pos.z + desk_d * 0.45), Vector3(desk_w * 0.9, 0.05, 0.05), C_STEEL, roughness=0.35, metallic=0.85)
    draw_pbr_box(Vector3(pos.x - desk_w * 0.45, 0.2, pos.z), Vector3(0.05, 0.05, desk_d * 0.9), C_STEEL, roughness=0.35, metallic=0.85)
    draw_pbr_box(Vector3(pos.x + desk_w * 0.45, 0.2, pos.z), Vector3(0.05, 0.05, desk_d * 0.9), C_STEEL, roughness=0.35, metallic=0.85)
    draw_pbr_box(Vector3(pos.x, 0.22, pos.z), Vector3(desk_w * 0.88, 0.03, desk_d * 0.88), C_METAL_DARK, roughness=0.6, metallic=0.6)
    draw_pbr_box(Vector3(pos.x + 0.25, 0.38, pos.z), Vector3(0.55, 0.26, 0.55), C_METAL_DARK, roughness=0.45, metallic=0.75)
    led_blink = 1.0 if time_val * 3.0 % 2.0 > 1.0 else 0.3
    draw_pbr_sphere(Vector3(pos.x + 0.05, 0.44, pos.z - 0.27), 0.012, C_GREEN_DIM, roughness=0.1, emissive=Vector3(0.1, 1.2 * led_blink, 0.2))
    draw_pbr_sphere(Vector3(pos.x + 0.12, 0.44, pos.z - 0.27), 0.012, C_CYAN, roughness=0.1, emissive=Vector3(0.1, 0.9, 1.2))
    draw_pbr_box(Vector3(pos.x, desk_h - 0.02, pos.z), Vector3(desk_w, 0.05, desk_d), C_DESK_TOP, roughness=0.35, metallic=0.4)
    draw_pbr_box(Vector3(pos.x, desk_h - 0.02, pos.z), Vector3(desk_w + 0.03, 0.03, desk_d + 0.03), C_STEEL, roughness=0.3, metallic=0.85)
    mon_center_x = pos.x + 0.2
    mon_center_y = desk_h + 0.58
    mon_center_z = pos.z
    draw_pbr_box(Vector3(mon_center_x, desk_h + 0.02, mon_center_z), Vector3(0.38, 0.03, 0.28), C_STEEL, roughness=0.25, metallic=0.9)
    draw_pbr_cylinder(Vector3(mon_center_x, desk_h + 0.28, mon_center_z), 0.045, 0.52, C_CHROME, roughness=0.15, metallic=0.95)
    draw_pbr_box(Vector3(mon_center_x, mon_center_y, mon_center_z), Vector3(1.36, 0.74, 0.06), C_METAL_DARK, roughness=0.4, metallic=0.8)
    draw_pbr_box(Vector3(mon_center_x, mon_center_y, mon_center_z), Vector3(1.38, 0.76, 0.03), C_STEEL, roughness=0.3, metallic=0.85)
    cyan_glow = Vector3(0.25, 1.45, 1.85) if is_powered or is_active else Vector3(0.05, 0.35, 0.45)
    draw_pbr_box(Vector3(mon_center_x, mon_center_y, mon_center_z - 0.032), Vector3(1.3, 0.68, 0.008), C_CYAN, roughness=0.12, emissive=cyan_glow)
    draw_pbr_box(Vector3(mon_center_x, mon_center_y + 0.28, mon_center_z - 0.038), Vector3(1.24, 0.04, 0.005), Color(10, 45, 75, 255), roughness=0.4)
    for seg in range(14):
        wx = mon_center_x - 0.55 + seg * 0.085
        t_phase = time_val * 6.0 + seg * 0.65
        wy = mon_center_y + math.sin(t_phase) * 0.08 + (0.05 if seg in (6, 7) else 0.0)
        draw_pbr_box(Vector3(wx, wy, mon_center_z - 0.038), Vector3(0.075, 0.008, 0.004), Color(230, 255, 255, 255), roughness=0.1, emissive=Vector3(0.4, 1.8, 2.0))
    for b in range(5):
        bx = mon_center_x - 0.45 + b * 0.22
        draw_pbr_box(Vector3(bx, mon_center_y - 0.22, mon_center_z - 0.038), Vector3(0.16, 0.035, 0.004), Color(0, 160, 210, 255), roughness=0.2, emissive=Vector3(0.1, 1.1, 1.4))
    sub_mon_x = pos.x - 0.55
    sub_mon_y = desk_h + 0.45
    sub_mon_z = pos.z - 0.06
    rl_push_matrix()
    rl_translatef(sub_mon_x, sub_mon_y, sub_mon_z)
    rl_rotatef(18.0, 0, 1, 0)
    draw_pbr_box(Vector3(0.0, -0.25, 0.0), Vector3(0.06, 0.5, 0.06), C_STEEL, roughness=0.3, metallic=0.85)
    draw_pbr_box(Vector3(0.0, 0.0, 0.0), Vector3(0.44, 0.42, 0.05), C_METAL_DARK, roughness=0.4, metallic=0.75)
    amber_glow = Vector3(1.6, 1.15, 0.12) if is_powered or is_active else Vector3(0.45, 0.25, 0.05)
    draw_pbr_box(Vector3(0.0, 0.0, -0.028), Vector3(0.39, 0.37, 0.008), C_AMBER, roughness=0.15, emissive=amber_glow)
    draw_pbr_box(Vector3(0.0, 0.08, -0.034), Vector3(0.32, 0.08, 0.004), Color(65, 45, 5, 255), roughness=0.5)
    for ab in range(3):
        draw_pbr_box(Vector3(-0.1 + ab * 0.1, -0.08, -0.034), Vector3(0.07, 0.1, 0.004), Color(255, 180, 20, 255), roughness=0.2, emissive=Vector3(1.8, 1.2, 0.1))
    rl_pop_matrix()
    draw_pbr_box(Vector3(pos.x + 0.15, desk_h + 0.015, pos.z - 0.24), Vector3(0.48, 0.025, 0.18), C_METAL_MID, roughness=0.45, metallic=0.7)
    draw_pbr_box(Vector3(pos.x + 0.15, desk_h + 0.028, pos.z - 0.24), Vector3(0.44, 0.008, 0.15), Color(22, 24, 26, 255), roughness=0.7)
    draw_pbr_box(Vector3(pos.x + 0.48, desk_h + 0.018, pos.z - 0.24), Vector3(0.12, 0.024, 0.14), C_METAL_DARK, roughness=0.5)
    draw_pbr_sphere(Vector3(pos.x + 0.48, desk_h + 0.032, pos.z - 0.24), 0.022, C_CHROME, roughness=0.15, metallic=0.95)
    draw_pbr_cylinder(Vector3(mon_center_x, desk_h * 0.5, pos.z + desk_d * 0.42), 0.032, desk_h * 0.95, C_RUBBER, roughness=0.85)

def rr_draw_salmon_curved_umbilical_hose():
    """
    Ribbed salmon/orange heavy industrial floor umbilical conduit hose.
    Faithfully matching Picture 2:
    Curves smoothly along the floor from the chair base past the terminal desk to the right.
    """
    c_hose = Color(225, 120, 90, 255)
    c_rib = Color(30, 32, 35, 255)
    hose_points = [(0.32, 23.85), (0.68, 23.55), (1.15, 23.35), (1.68, 23.25), (2.25, 23.32), (2.82, 23.6), (3.38, 24.12), (3.92, 24.8), (4.45, 25.6)]
    for seg in range(len(hose_points) - 1):
        x1, z1 = hose_points[seg]
        x2, z2 = hose_points[seg + 1]
        mx = (x1 + x2) * 0.5
        mz = (z1 + z2) * 0.5
        slen = math.sqrt((x2 - x1) ** 2 + (z2 - z1) ** 2)
        ang = math.atan2(x2 - x1, z2 - z1) * 57.2958
        rl_push_matrix()
        rl_translatef(mx, 0.035, mz)
        rl_rotatef(ang, 0, 1, 0)
        draw_pbr_cylinder(Vector3(0.0, 0.0, 0.0), 0.045, slen * 1.05, c_hose, roughness=0.55, metallic=0.15)
        draw_pbr_torus(Vector3(0.0, 0.0, 0.0), 0.048, 0.008, c_rib, roughness=0.85)
        rl_pop_matrix()

def rr_draw_backwall_telemetry_readouts(time_val=0.0, is_powered=False):
    """
    Four glowing horizontal telemetry LED display units on the back wall.
    Matches Picture 2 background:
    - Panel 1 & 2: Yellow/Amber LED telemetry matrix panels (#FFCC00)
    - Panel 3 & 4: Cyan LED vital statistics strips (#00E5FF)
    """
    wall_z = 35.95
    panel_y = 3.65
    panel_w, panel_h = (1.25, 0.48)
    panels = [(-0.9, C_AMBER, Vector3(1.5, 0.95, 0.1)), (0.7, C_AMBER, Vector3(1.5, 0.95, 0.1)), (2.45, C_CYAN, Vector3(0.2, 1.35, 1.75)), (4.05, C_CYAN, Vector3(0.2, 1.35, 1.75))]
    for px, col, emiss in panels:
        draw_pbr_box(Vector3(px, panel_y, wall_z), Vector3(panel_w, panel_h, 0.12), C_METAL_DARK, roughness=0.45, metallic=0.75)
        draw_pbr_box(Vector3(px, panel_y, wall_z), Vector3(panel_w + 0.04, panel_h + 0.04, 0.04), C_METAL_EDGE, roughness=0.4, metallic=0.8)
        glow = emiss if is_powered else Vector3(0.1, 0.08, 0.05)
        draw_pbr_box(Vector3(px, panel_y, wall_z - 0.065), Vector3(panel_w - 0.08, panel_h - 0.08, 0.01), col, roughness=0.15, emissive=glow)
        for row in range(3):
            ry = panel_y - 0.12 + row * 0.12
            draw_pbr_box(Vector3(px, ry, wall_z - 0.072), Vector3(panel_w - 0.16, 0.02, 0.005), Color(20, 22, 26, 255), roughness=0.6)

def rr_draw_cryogenic_stasis_cylinder_tank(pos=Vector3(4.2, 0.0, 28.5), time_val=0.0, is_powered=False):
    """
    Tall pressurized cryogenic stasis capsule / cylinder tank.
    Matches Picture 2 background right:
    - Heavy octagonal industrial steel base.
    - Dark lower cylinder jacket (Y: 0.2 to 1.2m).
    - Smooth vertical stasis capsule body in clinical light cyan-gray (Y: 1.2 to 3.4m).
    - Hemispherical capsule dome on top (Y: 3.4 to 3.98m).
    - Frosted observation window slit with cyan cryogenic luminescence.
    - Pressure regulator dials, chrome valve wheels, and overhead exhaust conduit.
    """
    draw_pbr_box(Vector3(pos.x, 0.12, pos.z), Vector3(1.4, 0.24, 1.4), C_METAL_DARK, roughness=0.5, metallic=0.7)
    draw_pbr_box(Vector3(pos.x, 0.24, pos.z), Vector3(1.25, 0.08, 1.25), C_STEEL, roughness=0.35, metallic=0.85)
    draw_pbr_cylinder(Vector3(pos.x, 0.78, pos.z), 0.62, 1.02, Color(28, 32, 36, 255), roughness=0.55, metallic=0.7)
    draw_pbr_torus(Vector3(pos.x, 1.3, pos.z), 0.63, 0.024, C_STEEL, roughness=0.3, metallic=0.85)
    c_capsule = Color(160, 180, 192, 255)
    draw_pbr_cylinder(Vector3(pos.x, 2.35, pos.z), 0.58, 2.1, c_capsule, roughness=0.35, metallic=0.45)
    draw_pbr_sphere(Vector3(pos.x, 3.4, pos.z), 0.58, c_capsule, roughness=0.35, metallic=0.45)
