def rr_draw_rod_between(a, b, radius, color, roughness=0.35, metallic=0.85, emissive=None):
    """Draw a slim cylinder between two world-space points, aligned to the segment."""
    dx, dy, dz = (b.x - a.x, b.y - a.y, b.z - a.z)
    length = math.sqrt(dx * dx + dy * dy + dz * dz)
    if length < 0.001:
        return
    dot = max(-1.0, min(1.0, dy / length))
    angle = math.degrees(math.acos(dot))
    ax, ay, az = (dz, 0.0, -dx)
    axis_len = math.sqrt(ax * ax + ay * ay + az * az)
    mid = Vector3((a.x + b.x) * 0.5, (a.y + b.y) * 0.5, (a.z + b.z) * 0.5)
    rl_push_matrix()
    rl_translatef(mid.x, mid.y, mid.z)
    if axis_len > 0.0001:
        rl_rotatef(angle, ax / axis_len, ay, az / axis_len)
    draw_pbr_cylinder(Vector3(0, 0, 0), radius, length, color, roughness=roughness, metallic=metallic, emissive=emissive)
    rl_pop_matrix()

