def rr__lamp_hash01(bucket, seed):
    """Deterministic pseudo-random value in [0,1); no per-frame random flicker jitter."""
    v = math.sin((float(bucket) + 1.0) * 127.1 + (float(seed) + 1.0) * 311.7) * 43758.5453
    return v - math.floor(v)

def rr_lab_lamp_spark_progress(time_val, lamp_index, phase=0.0):
    """Occasional stable spark event; returns 0..1 while a short arc falls to the floor."""
    clock = max(0.0, float(time_val)) + lamp_index * 1.37 + phase * 0.19
    period = 0.82
    bucket = int(clock / period)
    if rr__lamp_hash01(bucket + 1103, lamp_index * 17 + 29) < 0.976:
        return None
    return clock % period / period

def rr_incandescent_lamp_intensity(time_val, phase, is_powered=True, lamp_index=None):
    """Shared natural flicker profile for visible white lamps and their shader light pools.

    Mostly steady incandescent/ballast output, tiny slow breathing, intermittent short
    voltage flutter, and very rare deeper dips. The waveform is deterministic by time.
    """
    t = max(0.0, float(time_val))
    pulse = 0.955 + 0.023 * math.sin(t * 1.47 + phase)
    pulse += 0.012 * math.sin(t * 6.6 + phase * 1.73)
    flutter_bucket = int((t + phase * 1.13) / 0.105)
    flutter = rr__lamp_hash01(flutter_bucket + 211, int((phase + 2.0) * 971))
    if flutter > 0.972:
        pulse *= 0.56 + 0.34 * rr__lamp_hash01(flutter_bucket + 877, int((phase + 4.0) * 619))
    sag_clock = t + phase * 2.23
    sag_bucket = int(sag_clock / 0.67)
    sag_roll = rr__lamp_hash01(sag_bucket + 431, int((phase + 5.0) * 887))
    if sag_roll > 0.988 and sag_clock % 0.67 < 0.075:
        pulse *= 0.07
    elif sag_roll > 0.976 and sag_clock % 0.67 < 0.06:
        pulse *= 0.48
    if lamp_index is not None and 0 <= lamp_index < 4:
        spark_p = rr_lab_lamp_spark_progress(t, lamp_index, phase)
        if spark_p is not None and spark_p < 0.065:
            pulse *= 0.34
    if not is_powered:
        pulse *= 0.88
    return max(0.0, min(1.0, pulse))

def rr_draw_lab_lamp_sparks(x, z, time_val, lamp_index, phase):
    """Low-cost, occasional white-hot sparks streak down from a pendant and scatter at floor level."""
    progress = rr_lab_lamp_spark_progress(time_val, lamp_index, phase)
    if progress is None:
        return
    hot_white = Color(224, 244, 255, 255)
    spark_glow = Vector3(2.1, 2.35, 2.75)
    for strand in range(3):
        p = progress - strand * 0.075
        if p < 0.0 or p > 1.0:
            continue
        sway_x = math.sin(p * 9.1 + lamp_index * 1.7 + strand * 2.3) * (0.018 + 0.11 * p)
        sway_z = math.cos(p * 10.7 + lamp_index * 2.1 + strand * 1.6) * (0.018 + 0.095 * p)
        sy = max(0.035, 5.08 - p * 5.0)
        sx = x + sway_x
        sz = z + sway_z
        end_y = max(0.028, sy - (0.09 + 0.035 * (1.0 - p)))
        rr_draw_rod_between(Vector3(sx, sy + 0.035, sz), Vector3(sx + 0.025 * math.sin(p * 14.0 + strand), end_y, sz + 0.018 * math.cos(p * 12.0 + strand)), 0.008 if strand == 0 else 0.0055, hot_white, roughness=0.12, metallic=0.0, emissive=spark_glow)
        draw_pbr_sphere(Vector3(sx, sy, sz), 0.014 if strand == 0 else 0.01, hot_white, roughness=0.08, metallic=0.0, emissive=spark_glow)
    if progress > 0.91:
        flash = max(0.08, (1.0 - progress) / 0.09)
        floor_glow = Vector3(1.6 * flash, 1.9 * flash, 2.3 * flash)
        draw_pbr_sphere(Vector3(x, 0.028, z), 0.024 * flash, hot_white, roughness=0.1, metallic=0.0, emissive=floor_glow)
        for angle in (0.3, 2.15, 4.1, 5.4):
            ex = x + math.cos(angle + progress * 2.0) * (0.07 + 0.06 * flash)
            ez = z + math.sin(angle + progress * 2.0) * (0.07 + 0.06 * flash)
            rr_draw_rod_between(Vector3(x, 0.024, z), Vector3(ex, 0.022, ez), 0.0045, hot_white, roughness=0.1, metallic=0.0, emissive=floor_glow)

def rr_draw_hanging_lab_lamps(time_val=0.0, is_powered=False):
    """Four detailed, neutral-white hanging laboratory bulbs with independent flicker and falling sparks."""
    fixtures = ((-5.2, 18.8, 0.2), (5.2, 18.8, 1.7), (-5.2, 29.5, 3.1), (5.2, 29.5, 4.5))
    live_white = Color(228, 240, 255, 255)
    dim_glass = Color(51, 59, 70, 255)
    steel = C_STEEL
    dark = C_METAL_DARK
    for index, (x, z, phase) in enumerate(fixtures):
        pulse = rr_incandescent_lamp_intensity(time_val, phase, is_powered, index)
        globe_emissive = Vector3(1.38 * pulse, 1.5 * pulse, 1.68 * pulse)
        filament_emissive = Vector3(1.62 * pulse, 1.73 * pulse, 1.92 * pulse)
        globe_colour = live_white if pulse > 0.035 else dim_glass
        filament_colour = Color(230, 246, 255, 255) if pulse > 0.035 else Color(63, 73, 83, 255)
        draw_pbr_box(Vector3(x, 6.79, z), Vector3(0.5, 0.09, 0.43), dark, roughness=0.57, metallic=0.72)
        draw_pbr_box(Vector3(x, 6.735, z), Vector3(0.33, 0.035, 0.29), steel, roughness=0.34, metallic=0.88)
        for dx in (-0.18, 0.18):
            for dz in (-0.14, 0.14):
                draw_pbr_cylinder(Vector3(x + dx, 6.705, z + dz), 0.018, 0.022, C_CHROME, roughness=0.22, metallic=0.94)
        rr_draw_rod_between(Vector3(x, 6.68, z), Vector3(x, 5.63, z), 0.026, C_RUBBER, roughness=0.9, metallic=0.1)
        rr_draw_rod_between(Vector3(x + 0.055, 6.66, z + 0.025), Vector3(x + 0.055, 5.66, z + 0.025), 0.01, C_CHROME, roughness=0.28, metallic=0.88)
        for ly in (6.49, 6.28, 6.07, 5.86):
            draw_pbr_torus(Vector3(x, ly, z), 0.042, 0.008, steel, roughness=0.34, metallic=0.84)
        draw_pbr_cylinder(Vector3(x, 5.61, z), 0.14, 0.13, C_METAL_MID, roughness=0.43, metallic=0.68)
        draw_pbr_torus(Vector3(x, 5.57, z), 0.15, 0.022, C_CHROME, roughness=0.23, metallic=0.92)
        draw_pbr_cone(Vector3(x, 5.47, z), 0.265, 0.25, dark, roughness=0.48, metallic=0.78)
        draw_pbr_torus(Vector3(x, 5.345, z), 0.255, 0.02, steel, roughness=0.28, metallic=0.92)
        draw_pbr_cylinder(Vector3(x, 5.338, z), 0.2, 0.028, C_METAL_MID, roughness=0.34, metallic=0.68)
        draw_pbr_sphere(Vector3(x, 5.245, z), 0.083, globe_colour, roughness=0.24, metallic=0.02, emissive=globe_emissive)
        rr_draw_rod_between(Vector3(x - 0.027, 5.245, z - 0.019), Vector3(x + 0.027, 5.245, z + 0.019), 0.0065, filament_colour, roughness=0.18, metallic=0.1, emissive=filament_emissive)
        rr_draw_rod_between(Vector3(x - 0.027, 5.245, z + 0.019), Vector3(x + 0.027, 5.245, z - 0.019), 0.006, filament_colour, roughness=0.18, metallic=0.1, emissive=filament_emissive)
        for dx in (-0.145, 0.145):
            for dz in (-0.145, 0.145):
                rr_draw_rod_between(Vector3(x + dx, 5.2, z + dz), Vector3(x + dx, 5.48, z + dz), 0.009, steel, roughness=0.31, metallic=0.88)
        draw_pbr_torus(Vector3(x, 5.46, z), 0.205, 0.012, steel, roughness=0.29, metallic=0.9)
        draw_pbr_torus(Vector3(x, 5.2, z), 0.205, 0.012, steel, roughness=0.29, metallic=0.9)
        draw_pbr_box(Vector3(x + 0.17, 5.61, z), Vector3(0.075, 0.055, 0.12), Color(218, 233, 249, 255), roughness=0.2, metallic=0.05, emissive=Vector3(0.1 * pulse, 0.12 * pulse, 0.15 * pulse))
        rr_draw_lab_lamp_sparks(x, z, time_val, index, phase)

def rr_draw_floor_crack(pos, length=3.2, rot_deg=0.0, variant=0):
    """Draws jagged structural cracks directly traversing concrete floor tiles."""
    rl_push_matrix()
    rl_translatef(pos.x, 0.015, pos.z)
    rl_rotatef(rot_deg, 0, 1, 0)
    nodes = [(-length * 0.48, math.sin(variant * 1.5) * 0.16), (-length * 0.22, math.cos(variant * 2.1) * 0.2), (0.04, -0.06), (length * 0.25, 0.16), (length * 0.48, -0.1)]
    for k in range(len(nodes) - 1):
        x1, z1 = nodes[k]
        x2, z2 = nodes[k + 1]
        mx, mz = ((x1 + x2) / 2.0, (z1 + z2) / 2.0)
        dx, dz = (x2 - x1, z2 - z1)
        seg_len = math.hypot(dx, dz)
        ang = math.degrees(math.atan2(dz, dx))
        rl_push_matrix()
        rl_translatef(mx, 0, mz)
        rl_rotatef(ang, 0, 1, 0)
        draw_pbr_box(Vector3(0, -0.001, 0), Vector3(seg_len + 0.03, 0.006, 0.065), C_BROKEN_CONCRETE, roughness=0.92, metallic=0.0)
        draw_pbr_box(Vector3(0, 0.001, 0), Vector3(seg_len + 0.01, 0.01, 0.028), C_WALL_CRACK, roughness=0.98, metallic=0.0)
        rl_pop_matrix()
    bx1, bz1 = nodes[2]
    bx2, bz2 = (bx1 + length * 0.2, bz1 - 0.26)
    bmx, bmz = ((bx1 + bx2) / 2.0, (bz1 + bz2) / 2.0)
    bang = math.degrees(math.atan2(bz2 - bz1, bx2 - bx1))
    blen = math.hypot(bx2 - bx1, bz2 - bz1)
    rl_push_matrix()
    rl_translatef(bmx, 0, bmz)
    rl_rotatef(bang, 0, 1, 0)
    draw_pbr_box(Vector3(0, 0.001, 0), Vector3(blen, 0.01, 0.022), C_WALL_CRACK, roughness=0.98, metallic=0.0)
    rl_pop_matrix()
    rl_pop_matrix()

def rr_draw_fallen_ceiling_tile(pos, rot_deg=12.0, broken=False):
    """Draws fallen, shattered acoustic ceiling tiles on the floor with rubble fragments."""
    rl_push_matrix()
    rl_translatef(pos.x, 0.016, pos.z)
    rl_rotatef(rot_deg, 0, 1, 0)
    if not broken:
        draw_pbr_box(Vector3(0, 0, 0), Vector3(0.95, 0.024, 0.95), C_PAPER2, roughness=0.92, metallic=0.0)
        draw_pbr_box(Vector3(0, 0.013, 0), Vector3(0.88, 0.006, 0.88), C_DEBRIS_DUST, roughness=0.96)
    else:
        draw_pbr_box(Vector3(-0.25, 0, 0), Vector3(0.44, 0.024, 0.88), C_PAPER2, roughness=0.92)
        draw_pbr_box(Vector3(0.26, 0.008, 0.06), Vector3(0.42, 0.024, 0.75), C_PAPER2, roughness=0.92)
        draw_pbr_box(Vector3(0, 0.005, 0), Vector3(0.12, 0.018, 0.9), C_RUBBLE, roughness=0.95)
    rl_pop_matrix()

def rr_draw_wall_crack_network(pos, wall_plane='north', height=3.6, width=2.2, variant=0):
    """Draws deep structural wall fissures, concrete spalling, exposed rusted rebar mesh, and damp water seepage streaks."""
    if wall_plane in ('north', 'south'):
        norm_sign = 1.0 if wall_plane == 'north' else -1.0

        def pt(u, y, n=0.015):
            return Vector3(pos.x + u, pos.y + y, pos.z + norm_sign * n)
        is_z = True
    else:
        norm_sign = 1.0 if wall_plane == 'west' else -1.0

        def pt(u, y, n=0.015):
            return Vector3(pos.x + norm_sign * n, pos.y + y, pos.z + u)
        is_z = False
    streak_len = max(1.5, pos.y)
    st_dim = Vector3(width * 0.45, streak_len, 0.012) if is_z else Vector3(0.012, streak_len, width * 0.45)
    draw_pbr_box(pt(0.0, -streak_len / 2.0 + 0.2, 0.005), st_dim, C_WALL_STAIN, roughness=0.35, metallic=0.1)
    spall_dim = Vector3(width * 0.65, height * 0.45, 0.018) if is_z else Vector3(0.018, height * 0.45, width * 0.65)
    draw_pbr_box(pt(0.05, 0.0, 0.008), spall_dim, C_BROKEN_CONCRETE, roughness=0.92, metallic=0.05)
    rb_dim_h = Vector3(width * 0.55, 0.024, 0.024) if is_z else Vector3(0.024, 0.024, width * 0.55)
    rb_dim_v = Vector3(0.024, height * 0.38, 0.024)
    draw_pbr_box(pt(0.0, 0.08, 0.014), rb_dim_h, C_EXPOSED_REBAR, roughness=0.75, metallic=0.6)
    draw_pbr_box(pt(-0.15, 0.0, 0.014), rb_dim_v, C_EXPOSED_REBAR, roughness=0.75, metallic=0.6)
    crack_nodes = [(-width * 0.35, height * 0.48), (-width * 0.18, height * 0.22), (0.02, 0.05), (-0.06, -0.22), (width * 0.15, -height * 0.35), (width * 0.28, -height * 0.48)]
    if variant % 2 == 1:
        crack_nodes = [(-x, y) for x, y in crack_nodes]
    for k in range(len(crack_nodes) - 1):
        x1, y1 = crack_nodes[k]
        x2, y2 = crack_nodes[k + 1]
        mx, my = ((x1 + x2) / 2.0, (y1 + y2) / 2.0)
        thick = 0.028 + k % 2 * 0.012
        seg_dim = Vector3(abs(x2 - x1) + thick, abs(y2 - y1) + thick, thick) if is_z else Vector3(thick, abs(y2 - y1) + thick, abs(x2 - x1) + thick)
        draw_pbr_box(pt(mx, my, 0.02), seg_dim, C_WALL_CRACK, roughness=0.98, metallic=0.0)
    b_nodes = [(0.02, 0.05), (width * 0.24, 0.18), (width * 0.42, 0.32)]
    for k in range(len(b_nodes) - 1):
        x1, y1 = b_nodes[k]
        x2, y2 = b_nodes[k + 1]
        mx, my = ((x1 + x2) / 2.0, (y1 + y2) / 2.0)
        b_dim = Vector3(abs(x2 - x1) + 0.018, abs(y2 - y1) + 0.018, 0.018) if is_z else Vector3(0.018, abs(y2 - y1) + 0.018, abs(x2 - x1) + 0.018)
        draw_pbr_box(pt(mx, my, 0.02), b_dim, C_WALL_CRACK, roughness=0.98, metallic=0.0)

def rr_draw_broken_floor_crater(pos, size=Vector2(2.6, 2.2), rot_deg=4.5, variant=0):
    """Draws fractured buckled concrete floor slabs with exposed rubble pit and bent rebar (pure concrete/debris, NO grass)."""
    draw_pbr_box(Vector3(pos.x, 0.005, pos.z), Vector3(size.x, 0.012, size.y), C_DIRT, roughness=0.96, metallic=0.0)
    rl_push_matrix()
    rl_translatef(pos.x - size.x * 0.15, 0.045, pos.z)
    rl_rotatef(rot_deg, 0, 0, 1)
    draw_pbr_box(Vector3(0, 0, 0), Vector3(size.x * 0.65, 0.08, size.y * 0.88), C_CONCRETE, roughness=0.88, metallic=0.05)
    draw_pbr_box(Vector3(size.x * 0.32, 0, 0), Vector3(0.06, 0.09, size.y * 0.85), C_BROKEN_CONCRETE, roughness=0.95, metallic=0.0)
    rl_pop_matrix()
    rl_push_matrix()
    rl_translatef(pos.x + size.x * 0.28, 0.015, pos.z + 0.1)
    rl_rotatef(-rot_deg * 0.65, 1, 0, 0)
    draw_pbr_box(Vector3(0, 0, 0), Vector3(size.x * 0.42, 0.065, size.y * 0.75), C_CONCRETE, roughness=0.9, metallic=0.05)
    rl_pop_matrix()
    draw_pbr_box(Vector3(pos.x + 0.02, 0.022, pos.z), Vector3(0.12, 0.035, size.y * 0.95), C_WALL_CRACK, roughness=0.98, metallic=0.0)
    rebar_angles = (15.0, -22.0, 35.0)
    for r_idx, r_z in enumerate((-size.y * 0.32, 0.0, size.y * 0.3)):
        rl_push_matrix()
        rl_translatef(pos.x + 0.04, 0.065, pos.z + r_z)
        rl_rotatef(rebar_angles[r_idx % len(rebar_angles)], 0, 1, 0)
        draw_pbr_cylinder(Vector3(0, 0, 0), 0.014, 0.32, C_EXPOSED_REBAR, roughness=0.7, metallic=0.65)
        rl_pop_matrix()
    rubble_offsets = [(0.12, -size.y * 0.38, 0.16, 0.08, 0.14), (-size.x * 0.32, size.y * 0.35, 0.18, 0.11, 0.15), (size.x * 0.35, -size.y * 0.22, 0.14, 0.07, 0.12), (0.04, size.y * 0.42, 0.16, 0.09, 0.13), (-0.25, -0.15, 0.1, 0.05, 0.09)]
    for rx, rz, sx, sy, sz in rubble_offsets:
        draw_pbr_box(Vector3(pos.x + rx, sy / 2.0 + 0.015, pos.z + rz), Vector3(sx, sy, sz), C_RUBBLE, roughness=0.92, metallic=0.05)

def rr_draw_rubble_debris_pile(pos, scale=1.0, variant=0):
    """Draws realistic piles of broken concrete chunks, gravel, and fallen structural masonry."""
    draw_pbr_cylinder(Vector3(pos.x, 0.012, pos.z), 0.65 * scale, 0.024, C_DIRT, roughness=0.96)
    rubble_items = [(0.0, 0.0, 0.32, 0.16, 0.26, C_BROKEN_CONCRETE, 15.0), (-0.22, 0.12, 0.22, 0.12, 0.18, C_RUBBLE, -25.0), (0.18, -0.15, 0.26, 0.14, 0.2, C_CONCRETE, 35.0), (-0.15, -0.18, 0.16, 0.09, 0.14, C_BROKEN_CONCRETE, 10.0), (0.24, 0.16, 0.18, 0.1, 0.15, C_RUBBLE, -40.0), (0.05, 0.22, 0.12, 0.06, 0.1, C_DEBRIS_DUST, 20.0), (-0.3, -0.05, 0.14, 0.07, 0.11, C_RUBBLE, 5.0)]
    for rx, rz, sx, sy, sz, col, rot in rubble_items:
        rl_push_matrix()
        rl_translatef(pos.x + rx * scale, sy * scale / 2.0 + 0.015, pos.z + rz * scale)
        rl_rotatef(rot + variant * 30.0, 0, 1, 0)
        draw_pbr_box(Vector3(0, 0, 0), Vector3(sx * scale, sy * scale, sz * scale), col, roughness=0.92, metallic=0.05)
        rl_pop_matrix()

def rr_draw_severed_ceiling_cables(pos, time_val=0.0, variant=0):
    """Draws dangling severed industrial power cables with exposed frayed copper wires."""
    for i in range(4):
        sway = math.sin(time_val * 1.5 + i * 1.2 + variant) * 0.035
        c_len = 1.3 + i % 3 * 0.5
        cx = pos.x + (i - 1.5) * 0.12 + sway
        cz = pos.z + math.cos(i * 2.0) * 0.07
        draw_pbr_cylinder(Vector3(cx, pos.y - c_len / 2.0, cz), 0.018, c_len, C_RUBBER, roughness=0.85, metallic=0.0)
        draw_pbr_cylinder(Vector3(cx, pos.y - c_len - 0.04, cz), 0.007, 0.08, C_BRASS, roughness=0.35, metallic=0.85)

