def draw_emergency_battery(pos, rot, time_val=0.0):
    """Detailed industrial backup cell with terminals, casing seams, warning bands and label plate."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot.x, 1, 0, 0)
    rl_rotatef(rot.y, 0, 1, 0)
    rl_rotatef(rot.z, 0, 0, 1)
    body = Vector3(0.46, 0.27, 0.34)
    # Rugged steel shell with inset front panel and protective end caps.
    draw_pbr_box(Vector3(0, 0, 0), body, C_METAL_DARK, roughness=0.39, metallic=0.72)
    draw_pbr_box(Vector3(0, 0.006, 0.176), Vector3(0.39, 0.205, 0.018), C_METAL_MID, roughness=0.48, metallic=0.62)
    draw_pbr_box(Vector3(0, 0.006, 0.188), Vector3(0.30, 0.145, 0.008), C_METAL_DARK, roughness=0.56, metallic=0.38)
    # Positive/negative terminal bases and metal caps.
    for x, col in ((-0.125, C_RED_DIM), (0.125, C_CHROME)):
        draw_pbr_cylinder(Vector3(x, 0.151, -0.015), 0.058, 0.045, C_METAL_EDGE, roughness=0.34, metallic=0.88)
        draw_pbr_cylinder(Vector3(x, 0.176, -0.015), 0.039, 0.026, col, roughness=0.22, metallic=0.85)
        draw_pbr_box(Vector3(x, 0.194, -0.015), Vector3(0.055, 0.006, 0.055), C_BRASS if x < 0 else C_CHROME,
                     roughness=0.24, metallic=0.9)
    # Reinforcement ribs along side panels, casing screws and a restrained hazard stripe.
    for x in (-0.198, 0.198):
        draw_pbr_box(Vector3(x, 0, 0.015), Vector3(0.025, 0.23, 0.27), C_METAL_EDGE, roughness=0.43, metallic=0.75)
        for y in (-0.085, 0.085):
            draw_pbr_cylinder(Vector3(x, y, 0.155), 0.012, 0.008, C_CHROME, roughness=0.3, metallic=0.9)
    draw_pbr_box(Vector3(0, -0.105, 0.189), Vector3(0.33, 0.022, 0.009), C_AMBER, roughness=0.34, metallic=0.2)
    for x in (-0.135, -0.09, -0.045, 0.0, 0.045, 0.09, 0.135):
        draw_pbr_box(Vector3(x, -0.105, 0.195), Vector3(0.018, 0.022, 0.004), C_METAL_DARK, roughness=0.58, metallic=0.2)
    # Raised label, serial bars, status strip and battery indicator.
    draw_pbr_box(Vector3(0, 0.055, 0.196), Vector3(0.245, 0.075, 0.012), Color(190, 199, 199, 255), roughness=0.62, metallic=0.1)
    for i in range(7):
        draw_pbr_box(Vector3(-0.09 + i*0.03, 0.055, 0.204), Vector3(0.012, 0.034 if i % 2 == 0 else 0.024, 0.004),
                     C_METAL_DARK, roughness=0.78)
    pulse = 0.55 + 0.45 * math.sin(time_val * 2.0)
    draw_pbr_box(Vector3(0.16, 0.103, 0.197), Vector3(0.035, 0.018, 0.006), C_GREEN_DIM,
                 roughness=0.22, emissive=Vector3(0.02*pulse, 0.22*pulse, 0.06*pulse))
    draw_pbr_box(Vector3(-0.16, 0.103, 0.197), Vector3(0.035, 0.018, 0.006), C_AMBER,
                 roughness=0.25, emissive=Vector3(0.20, 0.07, 0.005))
    # Recessed lower seams and front corner guards.
    for y in (-0.125, 0.125):
        draw_pbr_box(Vector3(0, y, 0.175), Vector3(0.34, 0.008, 0.012), C_METAL_EDGE, roughness=0.48, metallic=0.7)
    rl_pop_matrix()



def draw_research_pickup_visual(item, time_val=0.0):
    """Distinct industrial visuals for pickup props imported from the Research Room source."""
    kind = item.item_type
    pos = item.pos
    rot = item.rot
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot.x, 1, 0, 0)
    rl_rotatef(rot.y, 0, 1, 0)
    rl_rotatef(rot.z, 0, 0, 1)

    if kind == "bio_canister":
        draw_pbr_cylinder(Vector3(0, 0, 0), 0.115, 0.44, C_GLASS_EDGE, roughness=0.12, metallic=0.10)
        draw_pbr_cylinder(Vector3(0, -0.015, 0), 0.081, 0.31, C_MUTAGEN_GLOW, roughness=0.18, emissive=Vector3(0.03, 0.48, 0.10))
        draw_pbr_cylinder(Vector3(0, 0.235, 0), 0.125, 0.055, C_METAL_DARK, roughness=0.35, metallic=0.82)
        draw_pbr_cylinder(Vector3(0, -0.235, 0), 0.125, 0.045, C_METAL_MID, roughness=0.35, metallic=0.80)
        for yy in (-0.14, -0.04, 0.06, 0.15):
            draw_pbr_box(Vector3(0, yy, 0.116), Vector3(0.12, 0.009, 0.008), C_GLASS_EDGE, roughness=0.2, metallic=0.2)
        draw_pbr_box(Vector3(0, 0.02, 0.121), Vector3(0.105, 0.09, 0.012), C_PAPER, roughness=0.88)
        draw_pbr_box(Vector3(0, 0.022, 0.129), Vector3(0.072, 0.010, 0.006), C_RED_DIM, roughness=0.55)
        draw_pbr_box(Vector3(0, -0.055, 0.129), Vector3(0.072, 0.008, 0.006), C_METAL_DARK, roughness=0.8)
    elif kind == "spectrometer":
        draw_pbr_box(Vector3(0, 0, 0), Vector3(0.34, 0.10, 0.25), C_METAL_DARK, roughness=0.36, metallic=0.66)
        draw_pbr_box(Vector3(0, 0.056, -0.012), Vector3(0.22, 0.012, 0.13), C_METAL_MID, roughness=0.4, metallic=0.55)
        draw_pbr_box(Vector3(-0.045, 0.065, -0.01), Vector3(0.12, 0.006, 0.07), Color(10, 25, 27, 255), roughness=0.2, emissive=Vector3(0.0, 0.12, 0.14))
        for i in range(3):
            draw_pbr_box(Vector3(-0.075 + i*0.07, 0.07, -0.012), Vector3(0.027, 0.003, 0.004), C_CYAN, roughness=0.2, emissive=Vector3(0.0, 0.12, 0.15))
        draw_pbr_cylinder(Vector3(0.11, 0.01, 0.075), 0.045, 0.025, C_CHROME, roughness=0.14, metallic=0.92)
        draw_pbr_cylinder(Vector3(0.11, 0.01, 0.075), 0.027, 0.027, C_GLASS, roughness=0.1, metallic=0.08, emissive=Vector3(0.02, 0.13, 0.17))
        for xx in (-0.13, -0.09, -0.05):
            draw_pbr_box(Vector3(xx, 0.057, 0.077), Vector3(0.018, 0.008, 0.018), C_AMBER if xx == -0.09 else C_METAL_EDGE, roughness=0.4, metallic=0.6)
    elif kind == "dictaphone":
        draw_pbr_box(Vector3(0, 0, 0), Vector3(0.30, 0.075, 0.19), C_METAL_DARK, roughness=0.34, metallic=0.72)
        draw_pbr_box(Vector3(0, 0.041, -0.01), Vector3(0.22, 0.008, 0.12), C_METAL_MID, roughness=0.42, metallic=0.6)
        for i in range(5):
            draw_pbr_box(Vector3(-0.075 + i*0.034, 0.047, -0.012), Vector3(0.018, 0.003, 0.065), C_METAL_DARK, roughness=0.65)
        draw_pbr_box(Vector3(0.105, 0.049, 0.055), Vector3(0.032, 0.006, 0.026), C_RED_DIM, roughness=0.2, emissive=Vector3(0.6, 0.018, 0.008) if int(time_val*3.5)%2 == 0 else Vector3(0.06, 0.002, 0.001))
        draw_pbr_box(Vector3(-0.08, 0.043, 0.065), Vector3(0.07, 0.004, 0.022), C_CYAN_DIM, roughness=0.48, metallic=0.35)
    elif kind == "archive_box":
        draw_pbr_box(Vector3(0, 0, 0), Vector3(0.65, 0.43, 0.55), Color(83, 72, 52, 255), roughness=0.95, metallic=0.02)
        draw_pbr_box(Vector3(0, 0.219, 0), Vector3(0.66, 0.018, 0.56), Color(103, 91, 67, 255), roughness=0.94)
        draw_pbr_box(Vector3(0, 0.229, 0), Vector3(0.11, 0.006, 0.56), Color(163, 148, 113, 255), roughness=0.9)
        draw_pbr_box(Vector3(0, 0.233, 0), Vector3(0.08, 0.008, 0.31), C_WARNING, roughness=0.8)
        draw_pbr_box(Vector3(0, 0.24, 0), Vector3(0.055, 0.004, 0.20), C_METAL_DARK, roughness=0.8)
        for xx in (-0.29, 0.29):
            for zz in (-0.24, 0.24):
                draw_pbr_box(Vector3(xx, 0.012, zz), Vector3(0.035, 0.42, 0.035), C_RUST, roughness=0.88)
        draw_pbr_box(Vector3(0, 0.105, 0.283), Vector3(0.28, 0.12, 0.012), C_PAPER, roughness=0.97)
        draw_pbr_box(Vector3(0, 0.135, 0.292), Vector3(0.18, 0.012, 0.006), C_METAL_DARK, roughness=0.8)
    else:
        rl_pop_matrix()
        return False
    rl_pop_matrix()
    return True


def render_physics_item(item, time_val=0.0):
    # Security Room props share the continuous scene and normal primitive culling.
    # Their physics/inventory state continues to update independently of rendering.
    if item.item_type in {"bio_canister", "spectrometer", "dictaphone", "archive_box"}:
        if draw_research_pickup_visual(item, time_val):
            return
    if item.item_type == "auxiliary_tube":
        _draw_electricity_room_auxiliary_tube_visual_v38(item.pos, item.rot)
    elif item.item_type == "photo":
        draw_photograph_3d(item, time_val)
    elif item.item_type == "doc":
        draw_document_clipboard(item.pos, item.rot)
    elif item.item_type == "security_fob":
        draw_security_fob(item.pos, item.rot)
    elif item.item_type == "stun_baton":
        draw_stun_baton(item.pos, item.rot)
    elif item.item_type == "coffee_mug":
        draw_coffee_mug(item.pos, item.rot)
    elif "Flask" in item.name:
        draw_erlenmeyer_flask(item.pos, item.rot)
    elif "Keycard" in item.name:
        draw_keycard(item.pos, item.rot)
    elif "Syringe" in item.name:
        draw_syringe(item.pos, item.rot)
    elif "Glass" in item.name:
        draw_glass_shard(item.pos, item.rot)
    elif item.item_type == "battery":
        draw_emergency_battery(item.pos, item.rot, time_val)
    else:
        draw_pbr_box(item.pos, item.size, GOLD, roughness=0.3, metallic=0.8)

