def _waypoint_interval_from_distance(distance, audio_range, near_interval=0.22, far_interval=0.90):
    """Make locator pings increasingly frequent as the player approaches the beacon."""
    safe_range = max(0.001, float(audio_range))
    progress = max(0.0, min(1.0, float(distance) / safe_range))
    return near_interval + (far_interval - near_interval) * (progress ** 1.20)


