def _research_story_waypoint_target():
    """Return the beacon for the currently active Research Room / Observation transition."""
    if globals().get("echo_awakening_state", "idle") not in ("idle", "complete"):
        return None
    if (globals().get("research_exit_sequence_state", "inactive") == "active"
            and globals().get("observation_entry_mission_state", "inactive") == "inactive"):
        return OBSERVATION_SIGNAL_WAYPOINT_POS
    if research_intro_state == "monitor_waypoint":
        return RESEARCH_TERMINAL_WAYPOINT_POS
    if research_intro_state == "board_waypoint":
        return RESEARCH_INTRO_BOARD_WAYPOINT
    if research_intro_state == "chair_waypoint":
        return RESEARCH_INTRO_CHAIR_WAYPOINT
    if research_intro_state in ("chair_interaction_available", "align_memory"):
        # After the archive has been transferred, guide the player back to the chair
        # for the next explicitly requested memory-alignment objective.
        return RESEARCH_INTRO_CHAIR_WAYPOINT
    if research_intro_state == "board_minigame_waypoint":
        return RESEARCH_INTRO_BOARD_WAYPOINT
    if research_intro_state in ("terminal_code_waypoint", "memory_archive_transfer"):
        # Once the player leaves the evidence-wall interface, remove all guidance
        # beacons. The player is expected to navigate back to the workstation unaided.
        return None
    if research_intro_state in ("monitor_message", "board_camera_in", "board_dialogue", "board_camera_out",
                                "chair_camera_in", "chair_dialogue", "chair_camera_out",
                                "chair_diagnostic_open", "board_minigame_active"):
        return None
    if research_story_state == "check_terminal":
        return RESEARCH_TERMINAL_WAYPOINT_POS
    if research_story_state == "approach_door":
        return RESEARCH_DOOR_WAYPOINT_POS
    # No beacon for the floor log: the player must search the area themselves.
    if research_story_state == "enter_code":
        return RESEARCH_READER_WAYPOINT_POS
    return None


def _begin_research_access_cutscene():
    """Record the player's view and start a crisp, eased push-in toward the Research reader."""
    global research_story_state, research_cutscene_elapsed
    global research_cutscene_from_position, research_cutscene_from_target, research_cutscene_from_fovy
    global research_cutscene_dialogue_elapsed, research_cutscene_last_sound_index
    if research_story_state != "approach_door":
        return
    research_cutscene_from_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    research_cutscene_from_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    research_cutscene_from_fovy = camera.fovy
    research_cutscene_elapsed = 0.0
    research_cutscene_dialogue_elapsed = 0.0
    research_cutscene_last_sound_index = 0
    research_story_state = "cutscene_camera_in"
    spatial_audio.play_ui("access_denied", volume=0.40)


def _research_intro_player_looking_at(world_target, max_distance=6.0, min_facing=0.72):
    """Require both proximity and a deliberate camera view before starting a gaze cutscene."""
    dx = float(world_target.x - camera.position.x)
    dy = float(world_target.y - camera.position.y)
    dz = float(world_target.z - camera.position.z)
    distance = math.sqrt(dx*dx + dy*dy + dz*dz)
    if distance > max_distance or distance < 0.001:
        return False
    fx = float(camera.target.x - camera.position.x)
    fy = float(camera.target.y - camera.position.y)
    fz = float(camera.target.z - camera.position.z)
    forward_len = math.sqrt(fx*fx + fy*fy + fz*fz)
    if forward_len < 0.001:
        return False
    facing = (fx*dx + fy*dy + fz*dz) / (forward_len * distance)
    return facing >= min_facing


def _begin_research_intro_focus(kind):
    """Save the current view and ease the camera toward the board or the chair's diagnostic screen."""
    global research_intro_state, research_intro_timer, research_intro_camera_elapsed
    global research_intro_camera_from_position, research_intro_camera_from_target, research_intro_camera_from_fovy
    global research_intro_camera_to_position, research_intro_camera_to_target, research_intro_camera_to_fovy
    global research_intro_saved_position, research_intro_saved_target, research_intro_saved_fovy
    global research_intro_dialogue_elapsed, research_intro_dialogue_last_sound_index
    research_intro_saved_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    research_intro_saved_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    research_intro_saved_fovy = float(camera.fovy)
    research_intro_camera_from_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    research_intro_camera_from_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    research_intro_camera_from_fovy = float(camera.fovy)
    focus_target = RESEARCH_INTRO_BOARD_FOCUS if kind == "board" else RESEARCH_INTRO_CHAIR_FOCUS
    if kind == "chair":
        # The chair monitor faces the chair's local +Z side after its -155 degree world rotation.
        # Set the end view on the monitor normal so the physical glass fills the shot, not the head cradle.
        _screen_yaw = math.radians(-155.0)
        _screen_normal_x = math.sin(_screen_yaw)
        _screen_normal_z = math.cos(_screen_yaw)
        _screen_camera_distance = 0.72
        research_intro_camera_to_position = Vector3(
            focus_target.x + _screen_normal_x * _screen_camera_distance,
            focus_target.y,
            focus_target.z + _screen_normal_z * _screen_camera_distance,
        )
        research_intro_camera_to_fovy = 32.0
    else:
        research_intro_camera_to_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
        research_intro_camera_to_fovy = 51.0
    research_intro_camera_to_target = Vector3(focus_target.x, focus_target.y, focus_target.z)
    research_intro_camera_elapsed = 0.0
    research_intro_timer = 0.0
    research_intro_dialogue_elapsed = 0.0
    research_intro_dialogue_last_sound_index = 0
    research_intro_state = "board_camera_in" if kind == "board" else "chair_camera_in"
    research_waypoint_ping_timer = 0.0
    research_waypoint_arrival_played = False
    try:
        spatial_audio.play_ui("access_granted", volume=0.38 if kind == "board" else 0.42)
    except Exception:
        pass



# The attached diagnostic screen is part of the station's local model at (1.22, 1.63, 0.298).
# draw_research_room_contents adds 6m to Z, and the chair itself is placed at Z=24m.
RESEARCH_CHAIR_SCREEN_LOCAL_CENTER = (1.22, 1.63, 0.298)
RESEARCH_CHAIR_SCREEN_LOCAL_HALF_WIDTH = 0.300
RESEARCH_CHAIR_SCREEN_LOCAL_HALF_HEIGHT = 0.170
RESEARCH_CHAIR_SCREEN_YAW = math.radians(-155.0)


def _research_chair_screen_world_point(local_x, local_y, local_z=0.306):
    """Project a point from the chair model into the shared world, respecting its Y rotation."""
    yaw = RESEARCH_CHAIR_SCREEN_YAW
    # Equivalent to the OpenGL Y rotation used by rr_draw_memory_extraction_station.
    world_x = float(local_x) * math.cos(yaw) + float(local_z) * math.sin(yaw)
    world_z = 30.0 - float(local_x) * math.sin(yaw) + float(local_z) * math.cos(yaw)
    return Vector3(world_x, float(local_y), world_z)


def _draw_research_chair_screen_overlay():
    """Draw the EXP-09 readout only inside the projection of the physical chair monitor's glass."""
    projector = globals().get("get_world_to_screen")
    if not callable(projector):
        return

    local_x, local_y, local_z = RESEARCH_CHAIR_SCREEN_LOCAL_CENTER
    half_w = RESEARCH_CHAIR_SCREEN_LOCAL_HALF_WIDTH
    half_h = RESEARCH_CHAIR_SCREEN_LOCAL_HALF_HEIGHT
    # Only show the text from the actual front side of the screen.
    nx = math.sin(RESEARCH_CHAIR_SCREEN_YAW)
    nz = math.cos(RESEARCH_CHAIR_SCREEN_YAW)
    screen_center = _research_chair_screen_world_point(local_x, local_y, local_z)
    camera_side = ((camera.position.x - screen_center.x) * nx
                   + (camera.position.z - screen_center.z) * nz)
    if camera_side <= 0.0:
        return

    local_corners = (
        (local_x-half_w, local_y+half_h),
        (local_x+half_w, local_y+half_h),
        (local_x-half_w, local_y-half_h),
        (local_x+half_w, local_y-half_h),
    )
    try:
        points = [projector(_research_chair_screen_world_point(px, py, 0.306), camera)
                  for px, py in local_corners]
        xs = [float(p.x) for p in points]
        ys = [float(p.y) for p in points]
        left, right = min(xs), max(xs)
        top, bottom = min(ys), max(ys)
        if (right-left < 35 or bottom-top < 28 or right < 0 or left > SCREEN_WIDTH
                or bottom < 0 or top > SCREEN_HEIGHT):
            return
        left = max(0.0, left)
        right = min(float(SCREEN_WIDTH), right)
        top = max(0.0, top)
        bottom = min(float(SCREEN_HEIGHT), bottom)
    except Exception:
        # Never draw a substitute HUD panel if projection fails: keeping the text unattached would
        # recreate the original bug. The model screen remains visible as a cyan diagnostic display.
        return

    x0, y0 = int(left), int(top)
    w, h = max(1, int(right-left)), max(1, int(bottom-top))
    inset_x = max(3, int(w * 0.035))
    inset_y = max(3, int(h * 0.035))
    sx, sy = x0 + inset_x, y0 + inset_y
    sw, sh = max(12, w - inset_x*2), max(12, h - inset_y*2)

    # This dark field replaces the decorative model bars but remains clipped to the glass projection.
    draw_rectangle(sx, sy, sw, sh, Color(2, 13, 18, 255))
    draw_rectangle_lines(sx, sy, sw, sh, Color(39, 205, 225, 255))
    draw_rectangle(sx + 4, sy + 4, max(2, sw - 8), max(2, int(sh * 0.018)), Color(26, 175, 198, 255))

    header_size = max(8, min(22, int(sh * 0.050)))
    body_size = max(8, min(20, int(min(sh * 0.043, sw * 0.028))))
    pad_x = max(7, int(sw * 0.055))
    draw_text("MNEMOSYNE-IV // ECHO TRANSFER", sx + pad_x, sy + max(7, int(sh * 0.07)),
              header_size, Color(72, 229, 244, 255))
    draw_rectangle(sx + pad_x, sy + int(sh * 0.19), max(8, sw - pad_x*2), max(1, int(sh * 0.006)),
                   Color(24, 91, 105, 255))
    lines = (
        ("SUBJECT: EXP-09", Color(235, 244, 246, 255)),
        ("SESSION: INCOMPLETE", Color(245, 189, 63, 255)),
        ("CAPTURE: DAMAGED", Color(255, 112, 91, 255)),
        ("STORAGE: CORRUPTED", Color(245, 189, 63, 255)),
        ("RECONSTRUCTION: NOT COMMITTED", Color(255, 112, 91, 255)),
    )
    start_y = sy + int(sh * 0.255)
    line_step = max(body_size + 2, int(sh * 0.132))
    for line_idx, (line_text, line_color) in enumerate(lines):
        draw_text(line_text, sx + pad_x, start_y + line_idx * line_step, body_size, line_color)

def _draw_echo_host_report_screen_overlay():
    """Overlay the compatibility report only inside the projection of the real workstation glass."""
    projector = globals().get("get_world_to_screen")
    if not callable(projector):
        return
    center_x, center_y, center_z = (2.05, 1.50, 29.568)
    half_w, half_h = 0.64, 0.32
    corners = (Vector3(center_x-half_w, center_y+half_h, center_z),
               Vector3(center_x+half_w, center_y+half_h, center_z),
               Vector3(center_x-half_w, center_y-half_h, center_z),
               Vector3(center_x+half_w, center_y-half_h, center_z))
    try:
        points = [projector(point, camera) for point in corners]
        xs = [float(p.x) for p in points]
        ys = [float(p.y) for p in points]
        left, right, top, bottom = min(xs), max(xs), min(ys), max(ys)
        if (right-left < 36 or bottom-top < 32 or right < 0 or left > SCREEN_WIDTH
                or bottom < 0 or top > SCREEN_HEIGHT):
            return
        left, right = max(0.0, left), min(float(SCREEN_WIDTH), right)
        top, bottom = max(0.0, top), min(float(SCREEN_HEIGHT), bottom)
    except Exception:
        return
    x0, y0 = int(left), int(top)
    w, h = max(1, int(right-left)), max(1, int(bottom-top))
    inset_x, inset_y = max(3, int(w*0.035)), max(3, int(h*0.04))
    sx, sy = x0+inset_x, y0+inset_y
    sw, sh = max(14, w-inset_x*2), max(14, h-inset_y*2)
    elapsed = float(globals().get("echo_awakening_elapsed", 0.0))
    fade = max(0.0, min(1.0, elapsed / 0.42))
    alpha = int(255 * fade)
    draw_rectangle(sx, sy, sw, sh, Color(1, 7, 10, alpha))
    draw_rectangle_lines(sx, sy, sw, sh, Color(35, 182, 193, alpha))
    draw_rectangle(sx+4, sy+4, max(1, sw-8), max(1, int(sh*0.018)), Color(23, 99, 112, alpha))
    title_size = max(7, min(13, int(sh*0.085)))
    body_size = max(7, min(12, int(sh*0.070)))
    pad_x = max(5, int(sw*0.045))
    if elapsed >= 0.20:
        _title_alpha = int(255 * min(1.0, (elapsed - 0.20) / 0.35))
        draw_text("PROJECT ECHO // HOST REPORT", sx+pad_x, sy+max(6, int(sh*0.075)),
                  title_size, Color(90, 231, 239, _title_alpha))
        draw_line(sx+pad_x, sy+int(sh*0.25), sx+sw-pad_x, sy+int(sh*0.25), Color(24, 84, 94, _title_alpha))
    lines = (
        ("NEW HOST LOCATED", Color(240, 250, 249, 255)),
        ("COMPATIBILITY: EXCEPTIONAL", Color(135, 231, 203, 255)),
        ("MEMORY SYNC: ACCEPTED", Color(135, 231, 203, 255)),
        ("RECONSTRUCTION: OPTIMAL", Color(135, 231, 203, 255)),
        ("DESIGNATION: PERFECT HOST", Color(245, 206, 112, 255)),
    )
    line_step = max(body_size+1, int(sh*0.132))
    start_y = sy+int(sh*0.30)
    line_start = 0.46
    line_stagger = 0.39
    char_interval = 0.018
    for index, (line, color) in enumerate(lines):
        line_elapsed = elapsed - (line_start + index * line_stagger)
        if line_elapsed <= 0.0:
            continue
        visible_count = min(len(line), max(1, int(line_elapsed / char_interval) + 1))
        line_alpha = int(255 * min(1.0, line_elapsed / 0.22))
        draw_text(line[:visible_count], sx+pad_x, start_y+index*line_step, body_size,
                  Color(color.r, color.g, color.b, line_alpha))
    footer = "E / ESC   CONTINUE" if elapsed >= ECHO_HOST_REPORT_MIN_HOLD else "ANALYSING HOST SIGNATURE..."
    footer_size = max(7, min(10, int(sh*0.06)))
    draw_text(footer, sx+pad_x, sy+sh-footer_size-max(4, int(sh*0.045)), footer_size,
              Color(73, 194, 205, alpha))


def _research_close_chair_diagnostic():
    """Return from the first chair diagnostic and reveal the evidence-board objective."""
    global is_reading_doc, current_3d_item_obj, rr_memory_stage, rr_memory_intro_elapsed
    global research_intro_state, research_waypoint_ping_timer, research_waypoint_arrival_played
    global research_intro_afterthought_active, research_intro_afterthought_elapsed, research_intro_afterthought_last_sound_index
    if not (is_reading_doc and current_3d_item_obj is not None
            and getattr(current_3d_item_obj, "item_type", "") == "station"
            and getattr(current_3d_item_obj, "name", "") == "Memory Extraction Station"
            and research_intro_state == "chair_diagnostic_open"):
        return False
    is_reading_doc = False
    current_3d_item_obj = None
    rr_memory_stage = "needs_archive"
    rr_memory_intro_elapsed = 0.0
    research_intro_state = "board_minigame_waypoint"
    research_intro_afterthought_active = True
    research_intro_afterthought_elapsed = 0.0
    research_intro_afterthought_last_sound_index = 0
    research_waypoint_ping_timer = 0.0
    research_waypoint_arrival_played = False
    disable_cursor()
    try:
        spatial_audio.play_ui("mission_chime", volume=0.58)
    except Exception:
        pass
    return True


def _echo_copy_vec3(value):
    """Copy a camera/vector value so camera interpolation never retains a mutable alias."""
    return Vector3(float(value.x), float(value.y), float(value.z))


def _echo_helmet_target_pose(state):
    """Return a small pose target for the continuous articulated awakening motion."""
    return {
        "helmet_wake": (0.0, 0.0, -4.0),
        "helmet_approach": (7.0, 2.0, -3.0),
        "helmet_impact": (12.0, 3.0, 0.0),
        "camera_fall": (10.0, -2.0, 0.0),
        "helmet_look_up": (8.0, 0.0, 0.0),
        "helmet_side_reach": (6.0, 2.0, 4.0),
        "helmet_scan": (5.0, 0.0, 3.0),
        "helmet_return": (0.0, 0.0, 0.0),
        "helmet_look_down": (-28.0, 0.0, 0.0),
        "helmet_dormant": (-28.0, 0.0, 0.0),
    }.get(state, (0.0, 0.0, 0.0))


def _echo_set_cutscene_phase(state, duration, target_position=None, target_target=None):
    """Start an eased cinematic phase from the camera's exact current pose."""
    ns = globals()
    cam = ns.get("camera")
    if cam is None:
        return False
    ns["echo_awakening_state"] = state
    ns["echo_awakening_elapsed"] = 0.0
    ns["echo_awakening_phase_duration"] = max(0.05, float(duration))
    ns["echo_awakening_phase_from_position"] = _echo_copy_vec3(cam.position)
    ns["echo_awakening_phase_from_target"] = _echo_copy_vec3(cam.target)
    ns["echo_awakening_phase_to_position"] = _echo_copy_vec3(target_position if target_position is not None else cam.position)
    ns["echo_awakening_phase_to_target"] = _echo_copy_vec3(target_target if target_target is not None else cam.target)
    current_pose = ns.get("echo_helmet_pose_current", (0.0, 0.0, 0.0))
    ns["echo_helmet_pose_from"] = tuple(float(v) for v in current_pose)
    ns["echo_helmet_pose_to"] = _echo_helmet_target_pose(state)
    return True


def _begin_echo_awakening_cutscene():
    """Close the completed alignment UI, then begin the suspended helmet's unsettling scan."""
    ns = globals()
    if ns.get("echo_awakening_state", "idle") not in ("idle", "complete"):
        return False
    cam = ns.get("camera")
    if cam is None:
        return False
    ns["echo_awakening_saved_position"] = _echo_copy_vec3(cam.position)
    ns["echo_awakening_saved_target"] = _echo_copy_vec3(cam.target)
    # Latch the rig awake now; its sensor must stay lit and track the player after the scene.
    ns["echo_helmet_awakened"] = True
    ns["echo_helmet_dormant"] = False
    ns["echo_helmet_pose_current"] = (0.0, 0.0, 0.0)
    ns["echo_helmet_pose_from"] = (0.0, 0.0, 0.0)
    ns["echo_helmet_pose_to"] = (0.0, 0.0, 0.0)
    # The return destination is the actual screen of the workstation behind the chair.
    ns["echo_awakening_return_position"] = Vector3(2.05, 1.72, 27.05)
    ns["echo_awakening_return_target"] = Vector3(2.05, 1.50, 29.56)
    ns["is_reading_doc"] = False
    ns["current_3d_item_obj"] = None
    ns["research_intro_state"] = "echo_awakening"
    ns["research_waypoint_ping_timer"] = 0.0
    ns["research_waypoint_arrival_played"] = True
    ns["rr_memory_notice"] = "MEMORY RECONSTRUCTION ACCEPTED"
    try:
        disable_cursor()
    except Exception:
        pass
    # Keep the initial look brief so the impact and player fall happen soon after the claw is noticed.
    return _echo_set_cutscene_phase(
        "helmet_wake", 0.42, _echo_copy_vec3(cam.position), Vector3(0.0, 2.15, 29.95))


def _begin_echo_robot_camera_cutscene():
    """After the report closes, hold briefly before beginning the safe overhead robot reveal."""
    ns = globals()
    if ns.get("echo_awakening_state") != "host_report":
        return False
    if float(ns.get("echo_awakening_elapsed", 0.0)) < ECHO_HOST_REPORT_MIN_HOLD:
        return False
    cam = ns.get("camera")
    if cam is None:
        return False
    ns["echo_awakening_saved_position"] = _echo_copy_vec3(cam.position)
    ns["echo_awakening_saved_target"] = _echo_copy_vec3(cam.target)
    try:
        disable_cursor()
    except Exception:
        pass
    # Keep the monitor view still for 2–3 seconds after E/ESC, then lift the camera.
    return _echo_set_cutscene_phase(
        "robot_post_report_wait", ECHO_ROBOT_POST_REPORT_DELAY,
        _echo_copy_vec3(cam.position), _echo_copy_vec3(cam.target))


def _echo_start_next_phase(state):
    """Set a deterministic destination for the next shot in the awakening sequence."""
    ns = globals()
    cam = ns.get("camera")
    if cam is None:
        return
    saved_pos = ns.get("echo_awakening_saved_position") or _echo_copy_vec3(cam.position)
    saved_target = ns.get("echo_awakening_saved_target") or _echo_copy_vec3(cam.target)
    terminal_pos = ns.get("echo_awakening_return_position") or Vector3(2.05, 1.72, 27.05)
    terminal_target = ns.get("echo_awakening_return_target") or Vector3(2.05, 1.50, 29.56)
    phases = {
        # First cinematic: wake -> forward reach -> impact -> sudden fall -> look up -> safe side scan -> retract.
        "helmet_wake": (0.42, None, Vector3(0.0, 2.15, 29.95)),
        "helmet_approach": (0.82, None, Vector3(0.0, 2.24, 28.66)),
        "helmet_impact": (0.15, None, Vector3(-0.025, 2.14, 28.36)),
        "camera_fall": (0.12, Vector3(saved_pos.x, 0.34, saved_pos.z), Vector3(-0.025, 2.14, 28.36)),
        "helmet_look_up": (1.15, None, Vector3(-0.025, 2.14, 28.36)),
        "helmet_side_reach": (1.60, None, Vector3(0.675, 2.14, 28.34)),
        "helmet_scan": (3.85, None, Vector3(0.675, 2.14, 28.34)),
        "helmet_return": (2.15, None, Vector3(0.0, 2.50, 29.72)),
        "helmet_look_down": (0.72, None, Vector3(0.0, 2.50, 29.72)),
        "camera_stand": (2.10, saved_pos, saved_target),
        "walk_to_terminal": (3.55, terminal_pos, terminal_target),
        # The host report's timer is deliberately separate from its readable hold interval.
        "host_report": (1.0e6, terminal_pos, terminal_target),
        # Second cinematic: rise below the ceiling and move toward the dormant robot.
        "robot_camera_raise": (2.85, Vector3(2.10, 6.08, 28.30), Vector3(2.05, 0.45, 29.80)),
        "robot_camera_move": (5.10, Vector3(0.82, 6.08, 36.10), Vector3(-0.16, 0.72, 38.96)),
        "robot_settle": (1.80, Vector3(0.78, 5.92, 36.00), Vector3(-0.16, 0.72, 38.92)),
        "robot_transfer": (6.20, None, None),
        "robot_jolt": (1.75, None, None),
        "robot_screen_flicker": (1.95, None, None),
        "robot_screen_lit": (3.20, None, None),
        "camera_return": (2.75, terminal_pos, terminal_target),
        # Keep the cinematic/input lock active while the single terminal access message appears.
        "terminal_access_notice": (RESEARCH_EXIT_ACCESS_NOTICE_DURATION, terminal_pos, terminal_target),
    }
    if state == "complete":
        ns["echo_awakening_state"] = "complete"
        ns["echo_awakening_elapsed"] = 0.0
        ns["research_intro_state"] = "robot_awake_complete"
        ns["echo_helmet_pose_current"] = (0.0, 0.0, 0.0)
        ns["echo_helmet_pose_from"] = (0.0, 0.0, 0.0)
        ns["echo_helmet_pose_to"] = (0.0, 0.0, 0.0)
        cam.up = Vector3(0.0, 1.0, 0.0)
        try:
            disable_cursor()
        except Exception:
            pass
        return
    if state not in phases:
        return
    duration, position, target = phases[state]
    if state == "host_report":
        _echo_set_cutscene_phase(state, duration, terminal_pos, terminal_target)
        return
    if state in ("helmet_approach", "helmet_impact", "helmet_look_up", "helmet_side_reach",
                 "helmet_scan", "helmet_return", "helmet_look_down"):
        position = _echo_copy_vec3(cam.position)
    if state in ("robot_transfer", "robot_jolt", "robot_screen_flicker", "robot_screen_lit"):
        position, target = _echo_copy_vec3(cam.position), _echo_copy_vec3(cam.target)
    elif state in ("camera_return", "terminal_access_notice"):
        position, target = terminal_pos, terminal_target
    _echo_set_cutscene_phase(state, duration, position, target)


def _update_echo_awakening_cutscene(dt):
    """Advance both connected story cinematics without letting player-look fight the camera."""
    ns = globals()
    state = ns.get("echo_awakening_state", "idle")
    if state in ("idle", "complete", "host_report"):
        if state == "host_report" and not ns.get("is_game_paused", False):
            ns["echo_awakening_elapsed"] = float(ns.get("echo_awakening_elapsed", 0.0)) + dt
        return
    if ns.get("is_game_paused", False):
        return
    cam = ns.get("camera")
    if cam is None:
        return
    ns["echo_awakening_elapsed"] = float(ns.get("echo_awakening_elapsed", 0.0)) + dt
    elapsed = float(ns["echo_awakening_elapsed"])
    duration = max(0.05, float(ns.get("echo_awakening_phase_duration", 0.05)))
    t = min(1.0, elapsed / duration)
    # The fall is intentionally a fast drop; all other camera moves stay cinematic and smooth.
    if state == "camera_fall":
        # Short, sharp drop: most of the height change happens immediately, not as a glide.
        eased = 1.0 - (1.0 - t)**3.0
    else:
        # Quintic smoothstep has zero velocity and acceleration at both ends.
        eased = t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
    pose_from = ns.get("echo_helmet_pose_from", (0.0, 0.0, 0.0))
    pose_to = ns.get("echo_helmet_pose_to", (0.0, 0.0, 0.0))
    ns["echo_helmet_pose_current"] = tuple(
        float(pose_from[i]) + (float(pose_to[i]) - float(pose_from[i])) * eased for i in range(3)
    )
    p0 = ns.get("echo_awakening_phase_from_position") or _echo_copy_vec3(cam.position)
    p1 = ns.get("echo_awakening_phase_to_position") or _echo_copy_vec3(cam.position)
    q0 = ns.get("echo_awakening_phase_from_target") or _echo_copy_vec3(cam.target)
    q1 = ns.get("echo_awakening_phase_to_target") or _echo_copy_vec3(cam.target)
    cam.position = Vector3(p0.x + (p1.x - p0.x) * eased,
                           p0.y + (p1.y - p0.y) * eased,
                           p0.z + (p1.z - p0.z) * eased)
    cam.target = Vector3(q0.x + (q1.x - q0.x) * eased,
                         q0.y + (q1.y - q0.y) * eased,
                         q0.z + (q1.z - q0.z) * eased)
    # A brief impact roll accompanies the sudden drop; the camera no longer swings side-to-side.
    roll = 0.0
    if state == "camera_fall":
        roll = math.sin(t * math.pi) * 0.13
    elif state == "robot_camera_raise":
        roll = math.sin(t * math.pi) * 0.018
    cam.up = Vector3(math.sin(roll), math.cos(roll), 0.0)
    if elapsed < duration:
        return

    # Clamp precisely to the endpoint before defining the next phase.
    cam.position = _echo_copy_vec3(p1)
    cam.target = _echo_copy_vec3(q1)
    next_state = {
        "helmet_wake": "helmet_approach",
        "helmet_approach": "helmet_impact",
        "helmet_impact": "camera_fall",
        "camera_fall": "helmet_look_up",
        "helmet_look_up": "helmet_side_reach",
        "helmet_side_reach": "helmet_scan",
        "helmet_scan": "helmet_return",
        "helmet_return": "helmet_look_down",
        "helmet_look_down": "camera_stand",
        "camera_stand": "walk_to_terminal",
        "walk_to_terminal": "host_report",
        "robot_post_report_wait": "robot_camera_raise",
        "robot_camera_raise": "robot_camera_move",
        "robot_camera_move": "robot_settle",
        "robot_settle": "robot_transfer",
        "robot_transfer": "robot_jolt",
        "robot_jolt": "robot_screen_flicker",
        "robot_screen_flicker": "robot_screen_lit",
        "robot_screen_lit": "camera_return",
        "camera_return": "terminal_access_notice",
        "terminal_access_notice": "complete",
    }.get(state)
    if next_state:
        if state == "helmet_look_down" and next_state == "camera_stand":
            # The arm has retracted, looked down, and powered off. Freeze it before the player rises.
            ns["echo_helmet_dormant"] = True
            ns["echo_helmet_awakened"] = False
        _echo_start_next_phase(next_state)


def _update_research_exit_sequence(dt):
    """Unlock Observation during the final terminal message, then run its 15-second entry objective."""
    global research_exit_sequence_state, research_exit_sequence_timer
    global research_exit_notice_kind, research_exit_notice_timer
    global observation_door_unlocked, research_waypoint_ping_timer, research_waypoint_arrival_played
    global observation_entry_mission_state, observation_entry_mission_timer
    global observation_entry_mission_slide_elapsed

    if globals().get("is_game_paused", False):
        return

    echo_state = globals().get("echo_awakening_state", "idle")
    intro_state = globals().get("research_intro_state", "inactive")

    # As soon as the camera returns to the workstation, show the single access message
    # and release the Observation Room's door interlock. Player control remains locked
    # because echo_awakening_state is still terminal_access_notice.
    if research_exit_sequence_state == "inactive" and echo_state == "terminal_access_notice":
        research_exit_sequence_state = "access_message"
        observation_door_unlocked = True
        research_exit_sequence_timer = RESEARCH_EXIT_ACCESS_NOTICE_DURATION
        research_exit_notice_kind = ""
        research_exit_notice_timer = 0.0
        research_waypoint_ping_timer = 0.0
        research_waypoint_arrival_played = False
        try:
            spatial_audio.play_ui("access_granted", volume=0.68)
            spatial_audio.play_spatial(
                "door_slide",
                Vector3(OBSERVATION_ROOM_DOOR_WORLD_X, 2.0, OBSERVATION_ROOM_DOOR_WORLD_Z),
                camera, base_volume=0.86, max_dist=16.0)
        except Exception:
            pass

    # Only after the access message has finished does the main objective switch to Investigate.
    if (research_exit_sequence_state == "access_message"
            and echo_state == "complete" and intro_state == "robot_awake_complete"):
        research_exit_sequence_state = "active"
        research_exit_sequence_timer = 0.0
        research_waypoint_ping_timer = 0.0
        research_waypoint_arrival_played = False
        try:
            spatial_audio.play_ui("mission_chime", volume=0.54)
        except Exception:
            pass

    if research_exit_sequence_state != "active":
        return

    # Detect crossing the Observation Room threshold, not merely standing near its door.
    min_x, max_x, min_z, max_z = OBSERVATION_ROOM_WORLD_BOUNDS
    inside_observation_room = (
        camera.position.x < -18.65
        and min_x <= camera.position.x <= max_x
        and min_z <= camera.position.z <= max_z
    )

    if observation_entry_mission_state == "inactive":
        if inside_observation_room:
            observation_entry_mission_state = "active"
            observation_entry_mission_timer = OBSERVATION_ENTRY_EXPLORE_DURATION
            observation_entry_mission_slide_elapsed = 0.0
            try:
                spatial_audio.play_ui("mission_chime", volume=0.48)
            except Exception:
                pass
    elif observation_entry_mission_state == "active":
        observation_entry_mission_timer = max(0.0, observation_entry_mission_timer - dt)
        if observation_entry_mission_timer <= 0.0:
            observation_entry_mission_state = "slide_out"
            observation_entry_mission_slide_elapsed = 0.0
    elif observation_entry_mission_state == "slide_out":
        observation_entry_mission_slide_elapsed += dt
        if observation_entry_mission_slide_elapsed >= OBSERVATION_ENTRY_MISSION_SLIDE_DURATION:
            observation_entry_mission_state = "hidden"
            observation_entry_mission_timer = 0.0


def _show_observation_story_notice(message, duration=4.4):
    """Show a typed player field note using the shared Observation Room dialogue panel."""
    global observation_locker_notice_text, observation_locker_notice_timer
    global observation_locker_notice_elapsed, observation_locker_notice_last_sound_index
    observation_locker_notice_text = str(message)
    observation_locker_notice_timer = max(0.5, float(duration))
    observation_locker_notice_elapsed = 0.0
    observation_locker_notice_last_sound_index = 0


def _obs_open_passcode_log(log_index):
    """Open a recovered experiment log and update the existing passcode-puzzle progress."""
    global obs_evidence_panel_open, obs_evidence_record, obs_passcode_logs_collected
    try:
        idx = int(log_index)
        if idx < 0 or idx >= len(OBS_PASSCODE_LOGS):
            return False
        record = dict(OBS_PASSCODE_LOGS[idx])
    except (TypeError, ValueError, IndexError):
        return False
    record["kind"] = "experiment"
    record["title"] = f"RECOVERED EXPERIMENT RECORD // {record['id']}"
    obs_evidence_record = record
    obs_evidence_panel_open = True
    obs_passcode_logs_collected.add(record["id"])
    detail = globals().get("_OBS_ROOM_DETAIL_NS", {})
    _papers = detail.get("experiment_papers_seen", set())
    if not isinstance(_papers, set):
        _papers = set(_papers or ())
    _papers.add(record["id"])
    detail["experiment_papers_seen"] = _papers
    detail["experiment_log_seen"] = len(_papers) >= len(OBS_PASSCODE_LOGS)
    if not detail.get("protocol_note_seen", False):
        detail["mission_stage"] = "find_passcode"
    else:
        detail["mission_stage"] = "enter_passcode" if detail["experiment_log_seen"] else "search_papers"
    enable_cursor()
    spatial_audio.play_ui("item_pickup", volume=0.48)
    return True


def _obs_player_near_archive_locker(radius=4.35):
    """True when the player has walked close enough for the archive lock to release."""
    cam = globals().get("camera")
    target = globals().get("OBS_ARCHIVE_LOCKER_WORLD_TARGET")
    if cam is None or target is None:
        return False
    try:
        dx = float(target.x) - float(cam.position.x)
        dz = float(target.z) - float(cam.position.z)
        return cam.position.x < -18.65 and (dx * dx + dz * dz) <= float(radius) * float(radius)
    except Exception:
        return False


def _begin_observation_locker_cinematic():
    """Focus the camera on the locked archive locker, then wait for the two E-advanced lines."""
    global observation_locker_cinematic_state, observation_locker_cinematic_timer, blur_amount
    # Reset stale modal depth blur before the scripted locker focus begins.
    blur_amount = 0.0
    global observation_locker_camera_from_position, observation_locker_camera_from_target
    global observation_locker_camera_to_position, observation_locker_camera_to_target
    global observation_locker_camera_from_fovy, observation_locker_camera_to_fovy
    global observation_locker_cinematic_dialogue_elapsed, observation_locker_cinematic_last_sound_index
    observation_locker_camera_from_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    observation_locker_camera_from_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    observation_locker_camera_from_fovy = float(camera.fovy)
    # The locker face is on the +Z side after the interior transform, so look toward -Z.
    target = OBS_ARCHIVE_LOCKER_WORLD_TARGET
    observation_locker_camera_to_position = Vector3(target.x, 1.72, target.z + 2.35)
    observation_locker_camera_to_target = Vector3(target.x, 1.48, target.z - 0.05)
    observation_locker_camera_to_fovy = 52.0
    observation_locker_cinematic_timer = 0.0
    observation_locker_cinematic_dialogue_elapsed = 0.0
    observation_locker_cinematic_last_sound_index = 0
    observation_locker_cinematic_state = "camera_in"
    try:
        spatial_audio.play_spatial("door_slide", Vector3(target.x, 1.5, target.z), camera,
                                   base_volume=0.36, max_dist=7.0)
        spatial_audio.play_ui("click", volume=0.34)
    except Exception:
        pass


def _update_observation_story(dt):
    """Advance the Observation Room side quest and the short locker camera/dialogue beat."""
    global observation_story_stage, observation_locker_cinematic_state, observation_locker_cinematic_timer
    global observation_locker_camera_from_position, observation_locker_camera_from_target
    global observation_locker_camera_to_position, observation_locker_camera_to_target
    global observation_locker_camera_from_fovy, observation_locker_camera_to_fovy
    global observation_locker_notice_timer, observation_canisters_complete_timer
    global observation_locker_notice_elapsed, observation_locker_notice_last_sound_index
    global observation_locker_cinematic_dialogue_elapsed, observation_locker_cinematic_last_sound_index
    global observation_ransacked_locker_checked

    if observation_locker_notice_timer > 0.0 and not globals().get("is_game_paused", False):
        observation_locker_notice_timer = max(0.0, observation_locker_notice_timer - dt)
        observation_locker_notice_elapsed += dt
        _notice_visible_count = min(
            len(observation_locker_notice_text),
            int(observation_locker_notice_elapsed / OBSERVATION_LOCKER_DIALOGUE_CHAR_INTERVAL) + 1,
        )
        while observation_locker_notice_last_sound_index < _notice_visible_count:
            _notice_char = observation_locker_notice_text[observation_locker_notice_last_sound_index]
            observation_locker_notice_last_sound_index += 1
            if _notice_char.isalnum():
                _notice_sound = spatial_audio.sounds.get("typewriter_tick")
                if _notice_sound:
                    set_sound_volume(_notice_sound, 0.047)
                    set_sound_pan(_notice_sound, 0.5)
                    set_sound_pitch(_notice_sound, random.uniform(0.97, 1.03))
                    play_sound(_notice_sound)

    if globals().get("is_game_paused", False):
        return

    # Type the two reinforced-locker thoughts and the first-log discovery through one shared typewriter sound.
    if (observation_passcode_intro_state in ("line_one", "line_two")
            or observation_locker_cinematic_state in ("dialogue_one", "dialogue_two")):
        if observation_passcode_intro_state in ("line_one", "line_two"):
            _locker_dialogue_full_text = (
                "These reports have marks at the end... SUCCESS and FAILED. That cannot be accidental."
                if observation_passcode_intro_state == "line_one"
                else "I need the successful runs only. Sort them by timestamp, then take the final digit of each experiment ID in that order."
            )
        else:
            _locker_dialogue_full_text = (
                "Looks like this locker is still locked."
                if observation_locker_cinematic_state == "dialogue_one"
                else "If I can create an access card and find the correct code, I should be able to open it."
            )
        observation_locker_cinematic_dialogue_elapsed += dt
        _locker_dialogue_visible_count = min(
            len(_locker_dialogue_full_text),
            int(observation_locker_cinematic_dialogue_elapsed / OBSERVATION_LOCKER_DIALOGUE_CHAR_INTERVAL) + 1,
        )
        while observation_locker_cinematic_last_sound_index < _locker_dialogue_visible_count:
            _locker_dialogue_char = _locker_dialogue_full_text[observation_locker_cinematic_last_sound_index]
            observation_locker_cinematic_last_sound_index += 1
            if _locker_dialogue_char.isalnum():
                _locker_dialogue_sound = spatial_audio.sounds.get("typewriter_tick")
                if _locker_dialogue_sound:
                    set_sound_volume(_locker_dialogue_sound, 0.047)
                    set_sound_pan(_locker_dialogue_sound, 0.5)
                    set_sound_pitch(_locker_dialogue_sound, random.uniform(0.97, 1.03))
                    play_sound(_locker_dialogue_sound)

    # Cinematic camera interpolation is independent of locomotion; input is locked via any_modal_open.
    if observation_locker_cinematic_state in ("camera_in", "camera_out"):
        observation_locker_cinematic_timer += dt
        t = min(1.0, observation_locker_cinematic_timer / 0.92)
        ease = t * t * (3.0 - 2.0 * t)
        a = observation_locker_camera_from_position
        b = observation_locker_camera_to_position
        at = observation_locker_camera_from_target
        bt = observation_locker_camera_to_target
        if a is not None and b is not None and at is not None and bt is not None:
            camera.position.x = a.x + (b.x - a.x) * ease
            camera.position.y = a.y + (b.y - a.y) * ease
            camera.position.z = a.z + (b.z - a.z) * ease
            camera.target.x = at.x + (bt.x - at.x) * ease
            camera.target.y = at.y + (bt.y - at.y) * ease
            camera.target.z = at.z + (bt.z - at.z) * ease
            camera.fovy = observation_locker_camera_from_fovy + (observation_locker_camera_to_fovy - observation_locker_camera_from_fovy) * ease
        if t >= 1.0:
            observation_locker_cinematic_timer = 0.0
            if observation_locker_cinematic_state == "camera_in":
                observation_locker_cinematic_state = "dialogue_one"
                observation_locker_cinematic_dialogue_elapsed = 0.0
                observation_locker_cinematic_last_sound_index = 0
            else:
                # Give control back where the player was standing before inspecting the locker.
                observation_locker_cinematic_state = "inactive"
                camera.fovy = observation_locker_camera_to_fovy
                observation_story_stage = "create_card"
                detail = globals().get("_OBS_ROOM_DETAIL_NS", {})
                detail["mission_stage"] = "locker_found"
                detail["keycard_objective_started"] = True
                detail["printer_intro_complete"] = True
                detail["printer_puzzle_started"] = True
                detail["archive_locker_waypoint_active"] = False
                detail["ransacked_locker_waypoint_active"] = False
                globals()["mission_stage"] = "locker_found"
                try:
                    spatial_audio.play_ui("mission_chime", volume=0.56)
                except Exception:
                    pass

    # The room-entry survey is still the existing 15-second timed objective.
    if globals().get("research_exit_sequence_state", "inactive") == "active":
        if observation_entry_mission_state in ("active", "slide_out"):
            if observation_story_stage in ("not_started", "investigate_lockers"):
                observation_story_stage = "explore"
        elif observation_entry_mission_state == "hidden" and observation_story_stage in ("not_started", "explore"):
            observation_story_stage = "investigate_lockers"
            detail = globals().get("_OBS_ROOM_DETAIL_NS", {})
            detail["mission_stage"] = "locate"
            detail["archive_locker_waypoint_active"] = True
            detail["ransacked_locker_waypoint_active"] = True
            detail["emergency_alarm_active"] = False
            detail["emergency_alarm_strength"] = 0.0
            globals()["mission_stage"] = "locate"
            try:
                spatial_audio.play_ui("mission_chime", volume=0.58)
            except Exception:
                pass

    detail = globals().get("_OBS_ROOM_DETAIL_NS", {})
    computer_closed = detail.get("computer_session_state", "closed") == "closed"

    # Only after the player saves and exits the computer does the cartridge collection mission begin.
    if (observation_story_stage == "create_card" and detail.get("card_design_saved", False)
            and computer_closed):
        observation_story_stage = "find_canisters"
        detail["mission_stage"] = "locker_found"
        detail["keycard_objective_started"] = True
        detail["printer_intro_complete"] = True
        detail["printer_puzzle_started"] = True
        try:
            spatial_audio.play_ui("mission_chime", volume=0.58)
        except Exception:
            pass

    required_ids = []
    required_fn = detail.get("_required_colour_ids")
    if callable(required_fn):
        try:
            required_ids = list(required_fn())
        except Exception:
            required_ids = []
    collected_map = detail.get("spare_cartridges_collected", {}) or {}
    installed_map = detail.get("spare_cartridges_installed", {}) or {}

    if observation_story_stage == "find_canisters" and len(required_ids) == 4:
        if all(bool(collected_map.get(cid, False) or installed_map.get(cid, False)) for cid in required_ids):
            observation_story_stage = "canisters_complete"
            observation_canisters_complete_timer = 1.35
            try:
                spatial_audio.play_ui("mission_chime", volume=0.58)
            except Exception:
                pass
    elif observation_story_stage == "canisters_complete":
        observation_canisters_complete_timer = max(0.0, observation_canisters_complete_timer - dt)
        if observation_canisters_complete_timer <= 0.0:
            observation_story_stage = "load_canisters"
            try:
                spatial_audio.play_ui("mission_chime", volume=0.54)
            except Exception:
                pass

    # The printer begins only when the player leaves the service UI; pending then turns into a sound-backed animation.
    if (observation_story_stage == "load_canisters"
            and (detail.get("printer_print_pending", False) or detail.get("printer_print_animation_active", False))):
        observation_story_stage = "wait_print"
    if observation_story_stage == "wait_print" and detail.get("card_keycard_printed", False):
        observation_story_stage = "collect_keycard"
        try:
            spatial_audio.play_ui("mission_chime", volume=0.58)
        except Exception:
            pass
    if observation_story_stage == "collect_keycard" and detail.get("card_keycard_collected", False):
        observation_story_stage = "access_locker"
        detail["mission_stage"] = "find_passcode"
        globals()["mission_stage"] = "find_passcode"
        try:
            spatial_audio.play_ui("mission_chime", volume=0.56)
        except Exception:
            pass
    if observation_story_stage == "access_locker" and detail.get("archive_locker_opened", False):
        observation_story_stage = "complete"
        try:
            spatial_audio.play_ui("mission_chime", volume=0.58)
        except Exception:
            pass



def _update_research_room_intro(dt):
    """Gaze-triggered Research Room story: workstation message -> board -> chair -> board minigame."""
    global research_intro_state, research_intro_timer, research_intro_camera_elapsed
    global research_intro_camera_from_position, research_intro_camera_from_target, research_intro_camera_from_fovy
    global research_intro_camera_to_position, research_intro_camera_to_target, research_intro_camera_to_fovy
    global research_intro_dialogue_elapsed, research_intro_dialogue_last_sound_index
    global research_waypoint_ping_timer, research_waypoint_arrival_played
    global research_intro_afterthought_active, research_intro_afterthought_elapsed, research_intro_afterthought_last_sound_index
    if is_game_paused:
        return

    if research_intro_afterthought_active:
        research_intro_afterthought_elapsed += dt
        _afterthought_visible = min(len(RESEARCH_AFTER_CHAIR_THOUGHT),
                                    int(research_intro_afterthought_elapsed / RESEARCH_INTRO_DIALOGUE_CHAR_INTERVAL) + 1)
        while research_intro_afterthought_last_sound_index < _afterthought_visible:
            _afterthought_char = RESEARCH_AFTER_CHAIR_THOUGHT[research_intro_afterthought_last_sound_index]
            research_intro_afterthought_last_sound_index += 1
            if _afterthought_char.isalnum():
                _afterthought_sound = spatial_audio.sounds.get("typewriter_tick")
                if _afterthought_sound:
                    set_sound_volume(_afterthought_sound, 0.045)
                    set_sound_pan(_afterthought_sound, 0.5)
                    set_sound_pitch(_afterthought_sound, random.uniform(0.97, 1.03))
                    play_sound(_afterthought_sound)
        if research_intro_afterthought_elapsed >= RESEARCH_AFTER_CHAIR_THOUGHT_DURATION:
            research_intro_afterthought_active = False

    # Start only after the room's silent 15-second free-roam period has finished.
    if research_intro_state == "inactive" and research_story_state == "explore_done":
        research_intro_state = "monitor_waypoint"
        research_intro_timer = 0.0
        research_waypoint_ping_timer = 0.0
        research_waypoint_arrival_played = False
        try:
            spatial_audio.play_ui("mission_chime", volume=0.62)
        except Exception:
            pass
        return

    # Leaving the Evidence Wall ends the board waypoint. The mission then asks the
    # player to test the recovered token at the ECHO workstation; no replacement
    # beacon is shown for this manual-navigation segment. If the evidence is incomplete,
    # the terminal will reject the token and the player can revisit the board unaided.
    if research_intro_state == "board_minigame_active" and not rr_wall_inspection_active:
        research_intro_state = "terminal_code_waypoint"
        try:
            spatial_audio.play_ui("mission_chime", volume=0.66)
        except Exception:
            pass
        research_waypoint_ping_timer = 0.0
        research_waypoint_arrival_played = False
        return

    # Only camera-in/camera-out states interpolate the camera. Dialogue states remain
    # input-locked, but must reach the typewriter timer below instead of returning here.
    if research_intro_state in RESEARCH_INTRO_CAMERA_ANIMATION_STATES:
        research_intro_camera_elapsed += dt
        duration = max(0.05, RESEARCH_INTRO_CAMERA_DURATION)
        t = min(1.0, research_intro_camera_elapsed / duration)
        eased = t*t*(3.0 - 2.0*t)
        a, b = research_intro_camera_from_position, research_intro_camera_to_position
        at, bt = research_intro_camera_from_target, research_intro_camera_to_target
        if a is not None and b is not None:
            camera.position = Vector3(a.x + (b.x-a.x)*eased, a.y + (b.y-a.y)*eased, a.z + (b.z-a.z)*eased)
        if at is not None and bt is not None:
            camera.target = Vector3(at.x + (bt.x-at.x)*eased, at.y + (bt.y-at.y)*eased, at.z + (bt.z-at.z)*eased)
        camera.fovy = research_intro_camera_from_fovy + (research_intro_camera_to_fovy-research_intro_camera_from_fovy)*eased
        if t >= 1.0:
            camera.position = Vector3(b.x, b.y, b.z)
            camera.target = Vector3(bt.x, bt.y, bt.z)
            camera.fovy = research_intro_camera_to_fovy
            if research_intro_state == "board_camera_in":
                research_intro_state = "board_dialogue"
                research_intro_dialogue_elapsed = 0.0
                research_intro_dialogue_last_sound_index = 0
            elif research_intro_state == "chair_camera_in":
                research_intro_state = "chair_dialogue"
                research_intro_dialogue_elapsed = 0.0
                research_intro_dialogue_last_sound_index = 0
            elif research_intro_state == "board_camera_out":
                if research_intro_saved_position is not None:
                    camera.position = Vector3(research_intro_saved_position.x, research_intro_saved_position.y, research_intro_saved_position.z)
                if research_intro_saved_target is not None:
                    camera.target = Vector3(research_intro_saved_target.x, research_intro_saved_target.y, research_intro_saved_target.z)
                camera.fovy = research_intro_saved_fovy
                research_intro_state = "chair_waypoint"
                research_waypoint_ping_timer = 0.0
                research_waypoint_arrival_played = False
                try:
                    spatial_audio.play_ui("mission_chime", volume=0.52)
                except Exception:
                    pass
            elif research_intro_state == "chair_camera_out":
                if research_intro_saved_position is not None:
                    camera.position = Vector3(research_intro_saved_position.x, research_intro_saved_position.y, research_intro_saved_position.z)
                if research_intro_saved_target is not None:
                    camera.target = Vector3(research_intro_saved_target.x, research_intro_saved_target.y, research_intro_saved_target.z)
                camera.fovy = research_intro_saved_fovy
                research_intro_state = "chair_interaction_available"
                research_waypoint_ping_timer = 0.0
                research_waypoint_arrival_played = False
                try:
                    spatial_audio.play_ui("mission_chime", volume=0.52)
                except Exception:
                    pass
        return

    if research_intro_state in ("board_dialogue", "chair_dialogue"):
        dialogue_text = RESEARCH_BOARD_INTRO_DIALOGUE if research_intro_state == "board_dialogue" else RESEARCH_CHAIR_INTRO_DIALOGUE
        research_intro_dialogue_elapsed += dt
        visible = min(len(dialogue_text), int(research_intro_dialogue_elapsed / RESEARCH_INTRO_DIALOGUE_CHAR_INTERVAL) + 1)
        while research_intro_dialogue_last_sound_index < visible:
            char = dialogue_text[research_intro_dialogue_last_sound_index]
            research_intro_dialogue_last_sound_index += 1
            if char.isalnum():
                sound = spatial_audio.sounds.get("typewriter_tick")
                if sound:
                    set_sound_volume(sound, 0.052)
                    set_sound_pan(sound, 0.5)
                    set_sound_pitch(sound, random.uniform(0.96, 1.04))
                    play_sound(sound)
        if research_intro_dialogue_elapsed >= len(dialogue_text)*RESEARCH_INTRO_DIALOGUE_CHAR_INTERVAL + RESEARCH_INTRO_DIALOGUE_HOLD:
            research_intro_camera_from_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
            research_intro_camera_from_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
            research_intro_camera_from_fovy = float(camera.fovy)
            if research_intro_saved_position is not None:
                research_intro_camera_to_position = Vector3(research_intro_saved_position.x, research_intro_saved_position.y, research_intro_saved_position.z)
            else:
                research_intro_camera_to_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
            if research_intro_saved_target is not None:
                research_intro_camera_to_target = Vector3(research_intro_saved_target.x, research_intro_saved_target.y, research_intro_saved_target.z)
            else:
                research_intro_camera_to_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
            research_intro_camera_to_fovy = research_intro_saved_fovy
            research_intro_camera_elapsed = 0.0
            research_intro_state = "board_camera_out" if research_intro_state == "board_dialogue" else "chair_camera_out"
        return

    # The view must be intentionally aimed at the board/chair; distance alone never starts a scene.
    if not is_cursor_hidden() or is_reading_doc or is_holding_3d_item or is_keypad_open or is_master_terminal_open:
        return
    if research_intro_state == "board_waypoint" and _research_intro_player_looking_at(RESEARCH_INTRO_BOARD_FOCUS, 6.25, 0.68):
        _begin_research_intro_focus("board")
    elif research_intro_state == "chair_waypoint" and _research_intro_player_looking_at(RESEARCH_INTRO_CHAIR_FOCUS, 5.9, 0.62):
        _begin_research_intro_focus("chair")


def _research_accept_correct_code():
    """Unlock the Research door once the post-cutscene reader is available."""
    global archive_door_unlocked, story_phase, research_story_state, research_story_timer, keypad_code_buffer
    global research_waypoint_ping_timer, research_waypoint_arrival_played
    # After the reveal cutscene, the player may try the keypad at any time. Reading
    # the incident log is the intended clue, not a hard gate on keypad interaction.
    if research_story_state not in ("log_thought_wait", "log_thought_dialogue", "find_log", "enter_code"):
        return False
    archive_door_unlocked = True
    keypad_code_buffer = ""
    story_phase = 4
    set_material_texture(terminal_screen_model.materials[0], MATERIAL_MAP_ALBEDO, tex_screen_archive)
    spatial_audio.play_ui("access_granted", volume=0.80)
    spatial_audio.play_spatial("door_slide", Vector3(0.0, 2.5, 18.2), camera, base_volume=0.85)
    research_story_state = "code_check"
    research_story_timer = RESEARCH_ACCESS_CODE_CHECK_DURATION
    research_waypoint_ping_timer = 0.0
    research_waypoint_arrival_played = False
    return True


def _update_research_room_story(dt):
    """Update the Research Room story, its timed terminal read, crisp camera cutscene and 15s survey."""
    global research_story_state, research_story_timer, research_access_log_read, research_terminal_report_dismissed
    global research_cutscene_elapsed, research_cutscene_dialogue_elapsed, research_cutscene_last_sound_index
    global research_cutscene_from_position, research_cutscene_from_target, research_cutscene_from_fovy
    global research_log_thought_elapsed, research_log_thought_last_sound_index
    global research_waypoint_ping_timer, research_waypoint_arrival_played
    global is_reading_doc, current_3d_item_obj, current_doc_title, current_doc_text
    if is_game_paused:
        return

    if research_story_state == "inactive" and generator_powered:
        research_story_state = "power_wait"
        research_story_timer = RESEARCH_POWER_WAIT_DURATION
        research_waypoint_ping_timer = 0.0
        research_waypoint_arrival_played = False
        return

    if research_story_state == "power_wait":
        research_story_timer = max(0.0, research_story_timer - dt)
        if research_story_timer <= 0.0:
            research_story_state = "check_terminal"
            research_story_timer = 0.0
            set_material_texture(terminal_screen_model.materials[0], MATERIAL_MAP_ALBEDO, tex_screen_research_alert)
            research_waypoint_ping_timer = 0.0
            research_waypoint_arrival_played = False
            # The shared story-phase tracker emits the single mission cue this frame.
        return

    if research_story_state == "terminal_reading":
        # The report remains on screen by default, but E or ESC can dismiss it early.
        # The original five-second briefing timer continues in the background and advances
        # the mission once its reading window has elapsed; a manual close is never undone.
        if (not research_terminal_report_dismissed
                and (not is_reading_doc or current_3d_item_obj is None
                     or getattr(current_3d_item_obj, "item_type", "") != "welcome_terminal")):
            central = next((obj for obj in major_solids if getattr(obj, "name", "") == "Central Terminal"), None)
            if central is not None:
                current_3d_item_obj = central
                current_doc_title = research_terminal_original_doc_title
                current_doc_text = research_terminal_original_doc_text
                is_reading_doc = True
                enable_cursor()
        research_story_timer = max(0.0, research_story_timer - dt)
        if research_story_timer <= 0.0:
            is_reading_doc = False
            current_3d_item_obj = None
            disable_cursor()
            research_story_state = "approach_door"
            research_story_timer = 0.0
            research_terminal_report_dismissed = False
            research_waypoint_ping_timer = 0.0
            research_waypoint_arrival_played = False
            spatial_audio.play_ui("mission_chime", volume=0.62)
        return

    if research_story_state == "cutscene_camera_in":
        research_cutscene_elapsed += dt
        t = min(1.0, research_cutscene_elapsed / max(0.001, RESEARCH_ACCESS_CAMERA_IN_DURATION))
        ease = t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
        a, b = research_cutscene_from_position, research_cutscene_to_position
        at, bt = research_cutscene_from_target, research_cutscene_to_target
        camera.position = Vector3(a.x + (b.x-a.x)*ease, a.y + (b.y-a.y)*ease, a.z + (b.z-a.z)*ease)
        camera.target = Vector3(at.x + (bt.x-at.x)*ease, at.y + (bt.y-at.y)*ease, at.z + (bt.z-at.z)*ease)
        camera.fovy = research_cutscene_from_fovy + (research_cutscene_to_fovy-research_cutscene_from_fovy)*ease
        if t >= 1.0:
            research_story_state = "cutscene_dialogue"
            research_cutscene_dialogue_elapsed = 0.0
            research_cutscene_last_sound_index = 0
            research_cutscene_elapsed = 0.0
        return

    if research_story_state == "cutscene_dialogue":
        research_cutscene_dialogue_elapsed += dt
        visible = min(len(RESEARCH_ACCESS_DIALOGUE),
                      int(research_cutscene_dialogue_elapsed / RESEARCH_ACCESS_CHAR_INTERVAL) + 1)
        while research_cutscene_last_sound_index < visible:
            typed = RESEARCH_ACCESS_DIALOGUE[research_cutscene_last_sound_index]
            research_cutscene_last_sound_index += 1
            if typed.isalnum():
                sound = spatial_audio.sounds.get("typewriter_tick")
                if sound:
                    set_sound_volume(sound, 0.068)
                    set_sound_pan(sound, 0.5)
                    set_sound_pitch(sound, random.uniform(0.95, 1.05))
                    play_sound(sound)
        if research_cutscene_dialogue_elapsed >= len(RESEARCH_ACCESS_DIALOGUE)*RESEARCH_ACCESS_CHAR_INTERVAL + 1.05:
            research_story_state = "cutscene_camera_out"
            research_cutscene_elapsed = 0.0
        return

    if research_story_state == "cutscene_camera_out":
        research_cutscene_elapsed += dt
        t = min(1.0, research_cutscene_elapsed / max(0.001, RESEARCH_ACCESS_CAMERA_OUT_DURATION))
        ease = t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
        a, b = research_cutscene_to_position, research_cutscene_from_position
        at, bt = research_cutscene_to_target, research_cutscene_from_target
        camera.position = Vector3(a.x + (b.x-a.x)*ease, a.y + (b.y-a.y)*ease, a.z + (b.z-a.z)*ease)
        camera.target = Vector3(at.x + (bt.x-at.x)*ease, at.y + (bt.y-at.y)*ease, at.z + (bt.z-at.z)*ease)
        camera.fovy = research_cutscene_to_fovy + (research_cutscene_from_fovy-research_cutscene_to_fovy)*ease
        if t >= 1.0:
            camera.position = Vector3(b.x, b.y, b.z)
            camera.target = Vector3(bt.x, bt.y, bt.z)
            camera.fovy = research_cutscene_from_fovy
            research_story_state = "log_thought_wait"
            research_story_timer = RESEARCH_LOG_THOUGHT_DELAY
            research_log_thought_elapsed = 0.0
            research_log_thought_last_sound_index = 0
            research_waypoint_ping_timer = 0.0
            research_waypoint_arrival_played = False
        return

    if research_story_state == "log_thought_wait":
        # Let the player absorb the keypad reveal before the character thinks aloud.
        research_story_timer = max(0.0, research_story_timer - dt)
        if research_story_timer <= 0.0:
            research_story_state = "log_thought_dialogue"
            research_log_thought_elapsed = 0.0
            research_log_thought_last_sound_index = 0
            spatial_audio.play_ui("mission_chime", volume=0.42)
        return

    if research_story_state == "log_thought_dialogue":
        research_log_thought_elapsed += dt
        _thought_visible = min(len(RESEARCH_LOG_THOUGHT),
                               int(research_log_thought_elapsed / RESEARCH_LOG_THOUGHT_CHAR_INTERVAL) + 1)
        while research_log_thought_last_sound_index < _thought_visible:
            _thought_char = RESEARCH_LOG_THOUGHT[research_log_thought_last_sound_index]
            research_log_thought_last_sound_index += 1
            if _thought_char.isalnum():
                _thought_sound = spatial_audio.sounds.get("typewriter_tick")
                if _thought_sound:
                    set_sound_volume(_thought_sound, 0.055)
                    set_sound_pan(_thought_sound, 0.5)
                    set_sound_pitch(_thought_sound, random.uniform(0.96, 1.04))
                    play_sound(_thought_sound)
        if research_log_thought_elapsed >= len(RESEARCH_LOG_THOUGHT) * RESEARCH_LOG_THOUGHT_CHAR_INTERVAL + 1.15:
            research_story_state = "find_log"
            research_story_timer = 0.0
            research_waypoint_ping_timer = 0.0
            research_waypoint_arrival_played = False
            spatial_audio.play_ui("mission_chime", volume=0.54)
        return

    if research_story_state == "code_check":
        research_story_timer = max(0.0, research_story_timer - dt)
        if research_story_timer <= 0.0:
            research_story_state = "enter_room"
            research_story_timer = 0.0
            spatial_audio.play_ui("mission_chime", volume=0.48)
        return

    if research_story_state == "enter_room":
        # Start the silent 15-second roam only after the player has actually crossed the open threshold.
        if (archive_door_open >= 0.90 and RESEARCH_ROOM_ENTRY_X_MIN <= camera.position.x <= RESEARCH_ROOM_ENTRY_X_MAX
                and camera.position.z >= 19.0):
            research_story_state = "explore"
            research_story_timer = RESEARCH_ROOM_EXPLORE_DURATION
            spatial_audio.play_ui("mission_chime", volume=0.52)
        return

    if research_story_state == "explore":
        # Exploration is free-roam: no timer text or control restriction is displayed.
        if (RESEARCH_ROOM_ENTRY_X_MIN - 3.0 <= camera.position.x <= RESEARCH_ROOM_PLAYER_X_LIMIT
                and 19.0 <= camera.position.z <= RESEARCH_ROOM_BACK_WALL_Z - 0.2):
            research_story_timer = max(0.0, research_story_timer - dt)
            if research_story_timer <= 0.0:
                research_story_state = "explore_done"
                research_story_timer = 0.0
                spatial_audio.play_ui("mission_chime", volume=0.66)


def draw_research_story_waypoint(time_val=0.0):
    """Compact cyan in-world waypoint for the computer, Research entrance, log or keypad."""
    if globals().get("echo_awakening_state", "idle") not in ("idle", "complete"):
        return
    target = _research_story_waypoint_target()
    if target is None:
        return
    global _RENDER_MAX_VISIBLE_DISTANCE
    saved = _RENDER_MAX_VISIBLE_DISTANCE
    _RENDER_MAX_VISIBLE_DISTANCE = max(saved, 50.0)
    try:
        pulse = 0.70 + 0.30 * math.sin(float(time_val) * 3.6)
        x, y, z = target.x, target.y, target.z
        # Keep the beacon large enough to spot from the hub; all markers sit on the
        # player-facing side of their targets so the wall or keypad casing cannot hide them.
        stem_height = 0.42 if target.y < 1.4 else 0.62
        draw_pbr_cylinder(Vector3(x, y - stem_height*0.5, z), 0.032, stem_height, C_CYAN,
                          roughness=0.18, metallic=0.20,
                          emissive=Vector3(0.012, 0.72*pulse, 1.02*pulse))
        draw_pbr_sphere(target, 0.17, Color(54, 220, 255, 255), roughness=0.10, metallic=0.03,
                        emissive=Vector3(0.06, 1.18*pulse, 1.85*pulse))
        draw_pbr_sphere(Vector3(x + 0.012, y + 0.008, z - 0.012), 0.052,
                        Color(196, 248, 255, 255), roughness=0.08, metallic=0.0,
                        emissive=Vector3(0.16, 1.55*pulse, 2.20*pulse))
    finally:
        _RENDER_MAX_VISIBLE_DISTANCE = saved


def _electric_panel_completion_map():
    """Read the actual puzzle completion state for the three physical distribution panels."""
    routes = globals().get("panel_wires", {})
    route_a = routes.get("CABLE ROUTING CONSOLE A", set())
    route_b = routes.get("CABLE ROUTING CONSOLE B", set())
    route_c = routes.get("CABLE ROUTING CONSOLE C", set())
    return {
        "A": len(route_a) >= 4,
        "B": bool(globals().get("panel_b_complete", False) or len(route_b) >= 4),
        "C": bool(globals().get("panel_c_complete", False) or len(route_c) >= 4),
    }


def _electric_all_panels_connected():
    return all(_electric_panel_completion_map().values())


def _electric_room_systems_interactive():
    # The generator can be inspected at the end of the room survey; panel terminals stay
    # explicitly gated until that first generator inspection starts the nested tasks.
    return electric_room_entry_state in ("generator_waypoint", "active")


def _electric_objective_waypoint_target():
    """Return (kind, world position) for the current Electricity Room navigation objective."""
    if electric_room_entry_state == "generator_waypoint":
        return "generator", ELECTRIC_ROOM_GENERATOR_WAYPOINT_POS
    if (electric_return_to_generator and electric_panel_mission_dismissed
            and electric_tube_mission_state == "inactive" and not auxiliary_tube_installed):
        return "generator", ELECTRIC_ROOM_GENERATOR_WAYPOINT_POS
    if electric_tube_mission_state == "find_tube":
        return "tube", ELECTRIC_TUBE_WAYPOINT_POS
    if electric_tube_mission_state == "install_tube":
        return "generator", ELECTRIC_ROOM_GENERATOR_WAYPOINT_POS
    return None, None


def _begin_electric_room_cutscene():
    """Save the live FPS view, then begin a short camera move toward the physical reader."""
    global electric_room_mission_state, electric_cutscene_elapsed
    global electric_cutscene_from_position, electric_cutscene_from_target, electric_cutscene_from_fovy
    global electric_cutscene_dialogue_elapsed, electric_cutscene_last_sound_index
    if electric_room_mission_state != "approach":
        return
    electric_cutscene_from_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    electric_cutscene_from_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    electric_cutscene_from_fovy = camera.fovy
    electric_cutscene_elapsed = 0.0
    electric_cutscene_dialogue_elapsed = 0.0
    electric_cutscene_last_sound_index = 0
    electric_room_mission_state = "camera_in"
    spatial_audio.play_ui("access_denied", volume=0.48)


def _begin_auxiliary_tube_install_cutscene():
    """Take control of the camera for a close-up A-01 installation animation."""
    global electric_tube_mission_state, electric_tube_cutscene_elapsed
    global electric_tube_install_camera_from_position, electric_tube_install_camera_from_target
    global electric_tube_install_camera_from_fovy, electric_tube_anim_start_position
    global is_reading_doc, is_holding_3d_item, is_inventory_open, current_3d_item_obj
    if electric_tube_mission_state != "install_tube":
        return False
    if not any(getattr(item, "item_type", "") == "auxiliary_tube" for item in inventory):
        return False
    electric_tube_install_camera_from_position = Vector3(camera.position.x, camera.position.y, camera.position.z)
    electric_tube_install_camera_from_target = Vector3(camera.target.x, camera.target.y, camera.target.z)
    electric_tube_install_camera_from_fovy = camera.fovy
    _fwd = get_camera_forward(camera)
    electric_tube_anim_start_position = Vector3(
        camera.position.x + _fwd.x * 0.82,
        camera.position.y - 0.12 + _fwd.y * 0.82,
        camera.position.z + _fwd.z * 0.82,
    )
    electric_tube_cutscene_elapsed = 0.0
    electric_tube_mission_state = "tube_camera_in"
    is_reading_doc = False
    is_holding_3d_item = False
    is_inventory_open = False
    current_3d_item_obj = None
    enable_cursor()
    spatial_audio.play_ui("switch_clunk", volume=0.62)
    return True


def _register_electric_tube_pickup(item):
    """Advance the A-01 find task only when the physical tube has entered inventory."""
    global electric_tube_mission_state, electric_tube_mission_timer
    global electric_objective_waypoint_ping_timer, electric_objective_waypoint_arrival_played
    if (item is not None and getattr(item, "item_type", "") == "auxiliary_tube"
            and electric_tube_mission_state == "find_tube"):
        electric_tube_mission_state = "find_check"
        electric_tube_mission_timer = ELECTRIC_TUBE_CHECK_DURATION
        electric_objective_waypoint_ping_timer = 0.0
        electric_objective_waypoint_arrival_played = False
        spatial_audio.play_ui("mission_chime", volume=0.68)


def _update_electric_room_mission(dt):
    """Update Electricity Room story beats, nested checks, and the A-01 camera sequence."""
    global electric_room_mission_state, electric_cutscene_elapsed
    global electric_cutscene_dialogue_elapsed, electric_cutscene_last_sound_index
    global electric_keycard_check_timer, electric_room_waypoint_ping_timer
    global electric_room_entry_state, electric_room_explore_timer
    global electric_panel_done_timer, electric_panel_dismissal_pending, electric_panel_mission_dismissed
    global electric_panel_completion_seen, electric_return_to_generator
    global electric_tube_mission_state, electric_tube_mission_timer, electric_tube_cutscene_elapsed
    global electric_objective_waypoint_ping_timer, electric_objective_waypoint_arrival_played, electric_objective_waypoint_kind
    global electric_modules_auto_exit_armed, electric_modules_auto_exit_timer
    if is_game_paused:
        return

    if electric_room_mission_state == "camera_in":
        electric_cutscene_elapsed += dt
        t = min(1.0, electric_cutscene_elapsed / max(0.001, ELECTRIC_CUTSCENE_CAMERA_IN_DURATION))
        # Smootherstep is gentler at both ends than a basic smoothstep; keep the reader
        # reveal cinematic but avoid a visibly abrupt camera acceleration/deceleration.
        ease = t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
        a, b = electric_cutscene_from_position, electric_cutscene_to_position
        at, bt = electric_cutscene_from_target, electric_cutscene_to_target
        camera.position = Vector3(a.x + (b.x - a.x) * ease,
                                  a.y + (b.y - a.y) * ease,
                                  a.z + (b.z - a.z) * ease)
        camera.target = Vector3(at.x + (bt.x - at.x) * ease,
                               at.y + (bt.y - at.y) * ease,
                               at.z + (bt.z - at.z) * ease)
        camera.fovy = electric_cutscene_from_fovy + (electric_cutscene_to_fovy - electric_cutscene_from_fovy) * ease
        if t >= 1.0:
            electric_room_mission_state = "dialogue"
            electric_cutscene_dialogue_elapsed = 0.0
            electric_cutscene_last_sound_index = 0
            electric_cutscene_elapsed = 0.0

    elif electric_room_mission_state == "dialogue":
        electric_cutscene_dialogue_elapsed += dt
        visible = min(len(ELECTRIC_CUTSCENE_DIALOGUE),
                      int(electric_cutscene_dialogue_elapsed / ELECTRIC_CUTSCENE_CHAR_INTERVAL) + 1)
        while electric_cutscene_last_sound_index < visible:
            typed = ELECTRIC_CUTSCENE_DIALOGUE[electric_cutscene_last_sound_index]
            electric_cutscene_last_sound_index += 1
            if typed.isalnum():
                sound = spatial_audio.sounds.get("typewriter_tick")
                if sound:
                    set_sound_volume(sound, 0.070)
                    set_sound_pan(sound, 0.5)
                    set_sound_pitch(sound, random.uniform(0.94, 1.06))
                    play_sound(sound)
        dialogue_duration = len(ELECTRIC_CUTSCENE_DIALOGUE) * ELECTRIC_CUTSCENE_CHAR_INTERVAL
        if electric_cutscene_dialogue_elapsed >= dialogue_duration + 1.05:
            electric_room_mission_state = "camera_out"
            electric_cutscene_elapsed = 0.0

    elif electric_room_mission_state == "camera_out":
        electric_cutscene_elapsed += dt
        t = min(1.0, electric_cutscene_elapsed / max(0.001, ELECTRIC_CUTSCENE_CAMERA_OUT_DURATION))
        ease = t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
        a, b = electric_cutscene_to_position, electric_cutscene_from_position
        at, bt = electric_cutscene_to_target, electric_cutscene_from_target
        camera.position = Vector3(a.x + (b.x - a.x) * ease,
                                  a.y + (b.y - a.y) * ease,
                                  a.z + (b.z - a.z) * ease)
        camera.target = Vector3(at.x + (bt.x - at.x) * ease,
                               at.y + (bt.y - at.y) * ease,
                               at.z + (bt.z - at.z) * ease)
        camera.fovy = electric_cutscene_to_fovy + (electric_cutscene_from_fovy - electric_cutscene_to_fovy) * ease
        if t >= 1.0:
            camera.position = Vector3(b.x, b.y, b.z)
            camera.target = Vector3(bt.x, bt.y, bt.z)
            camera.fovy = electric_cutscene_from_fovy
            electric_room_mission_state = "find_keycard"
            electric_room_waypoint_ping_timer = 0.0
            spatial_audio.play_ui("mission_chime", volume=0.52)

    elif electric_room_mission_state == "card_check":
        electric_keycard_check_timer = max(0.0, electric_keycard_check_timer - dt)
        if electric_keycard_check_timer <= 0.0:
            electric_room_mission_state = "card_done"

    # Ten-second quiet survey. Do not print a countdown; once it ends, the world beacon
    # and soft positional pings guide the player to inspect the generator.
    if electric_room_entry_state == "exploring":
        electric_room_explore_timer = max(0.0, electric_room_explore_timer - dt)
        if electric_room_explore_timer <= 0.0:
            electric_room_entry_state = "generator_waypoint"
            electric_room_explore_timer = 0.0
            electric_objective_waypoint_ping_timer = 0.0
            electric_objective_waypoint_arrival_played = False
            electric_objective_waypoint_kind = None
            spatial_audio.play_ui("mission_chime", volume=0.58)

    # Keep one persistent check per solved panel, but only after the first generator inspection.
    if (electric_room_entry_state == "active" and electric_panel_mission_started
            and not electric_panel_mission_dismissed):
        _panel_completion = _electric_panel_completion_map()
        for _panel_id, _is_done in _panel_completion.items():
            if _is_done and not electric_panel_completion_seen.get(_panel_id, False):
                electric_panel_completion_seen[_panel_id] = True
                spatial_audio.play_ui("mission_chime", volume=0.46)
        if all(_panel_completion.values()) and not electric_panel_dismissal_pending:
            electric_panel_dismissal_pending = True
            electric_panel_done_timer = ELECTRIC_PANEL_CHECK_HOLD_DURATION
            spatial_audio.play_ui("mission_chime", volume=0.70)
        elif electric_panel_dismissal_pending:
            electric_panel_done_timer = max(0.0, electric_panel_done_timer - dt)
            if electric_panel_done_timer <= 0.0:
                electric_panel_mission_dismissed = True
                electric_return_to_generator = True
                electric_objective_waypoint_ping_timer = 0.0
                electric_objective_waypoint_arrival_played = False
                electric_objective_waypoint_kind = None

    # A-01 pickup/install checks each hold their green tick for 1.5 seconds.
    if electric_tube_mission_state == "find_check":
        electric_tube_mission_timer = max(0.0, electric_tube_mission_timer - dt)
        if electric_tube_mission_timer <= 0.0:
            electric_tube_mission_state = "install_tube"
            electric_tube_mission_timer = 0.0
            electric_objective_waypoint_ping_timer = 0.0
            electric_objective_waypoint_arrival_played = False
            electric_objective_waypoint_kind = None
            spatial_audio.play_ui("mission_chime", volume=0.48)
    elif electric_tube_mission_state == "install_check":
        electric_tube_mission_timer = max(0.0, electric_tube_mission_timer - dt)
        if electric_tube_mission_timer <= 0.0:
            electric_tube_mission_state = "installed"
            electric_tube_mission_timer = 0.0
            electric_modules_auto_exit_armed = True
            electric_modules_auto_exit_timer = -1.0
            electric_objective_waypoint_kind = None
            open_generator_module_selector()
            spatial_audio.play_ui("mission_chime", volume=0.58)

    # Tube installation camera: smooth push-in, physical mesh animation, then return to FPS.
    elif electric_tube_mission_state in ("tube_camera_in", "tube_insert", "tube_camera_out"):
        electric_tube_cutscene_elapsed += dt
        if electric_tube_mission_state == "tube_camera_in":
            t = min(1.0, electric_tube_cutscene_elapsed / max(0.001, ELECTRIC_TUBE_CAMERA_IN_DURATION))
            ease = t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
            a, b = electric_tube_install_camera_from_position, electric_tube_install_camera_to_position
            at, bt = electric_tube_install_camera_from_target, electric_tube_install_camera_to_target
            camera.position = Vector3(a.x+(b.x-a.x)*ease, a.y+(b.y-a.y)*ease, a.z+(b.z-a.z)*ease)
            camera.target = Vector3(at.x+(bt.x-at.x)*ease, at.y+(bt.y-at.y)*ease, at.z+(bt.z-at.z)*ease)
            camera.fovy = electric_tube_install_camera_from_fovy + (electric_tube_install_camera_to_fovy-electric_tube_install_camera_from_fovy)*ease
            if t >= 1.0:
                electric_tube_mission_state = "tube_insert"
                electric_tube_cutscene_elapsed = 0.0
        elif electric_tube_mission_state == "tube_insert":
            if electric_tube_cutscene_elapsed >= ELECTRIC_TUBE_INSERT_DURATION + 0.12:
                if install_auxiliary_induction_tube():
                    electric_tube_mission_state = "tube_camera_out"
                    electric_tube_cutscene_elapsed = 0.0
                    spatial_audio.play_spatial("spark_burst", Vector3(33.98, 1.1, -2.48), camera,
                                               base_volume=0.62, pitch_var=0.08)
                    spatial_audio.play_spatial("switch_clunk", Vector3(33.98, 1.1, -2.48), camera,
                                               base_volume=0.55)
                else:
                    # If inventory was changed while the cinematic began, return safely to the world.
                    electric_tube_mission_state = "install_tube"
                    electric_tube_cutscene_elapsed = 0.0
                    disable_cursor()
        elif electric_tube_mission_state == "tube_camera_out":
            t = min(1.0, electric_tube_cutscene_elapsed / max(0.001, ELECTRIC_TUBE_CAMERA_OUT_DURATION))
            ease = t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
            a, b = electric_tube_install_camera_to_position, electric_tube_install_camera_from_position
            at, bt = electric_tube_install_camera_to_target, electric_tube_install_camera_from_target
            camera.position = Vector3(a.x+(b.x-a.x)*ease, a.y+(b.y-a.y)*ease, a.z+(b.z-a.z)*ease)
            camera.target = Vector3(at.x+(bt.x-at.x)*ease, at.y+(bt.y-at.y)*ease, at.z+(bt.z-at.z)*ease)
            camera.fovy = electric_tube_install_camera_to_fovy + (electric_tube_install_camera_from_fovy-electric_tube_install_camera_to_fovy)*ease
            if t >= 1.0:
                camera.position = Vector3(b.x, b.y, b.z)
                camera.target = Vector3(bt.x, bt.y, bt.z)
                camera.fovy = electric_tube_install_camera_from_fovy
                electric_tube_mission_state = "install_check"
                electric_tube_mission_timer = ELECTRIC_TUBE_CHECK_DURATION
                electric_tube_cutscene_elapsed = 0.0
                disable_cursor()
                spatial_audio.play_ui("mission_chime", volume=0.72)


def _register_electric_keycard_pickup(item):
    """Complete the nested Find Key Card task only when its physical card enters inventory."""
    global electric_room_mission_state, electric_keycard_check_timer
    if (item is not None and getattr(item, "name", "") == "Security Keycard"
            and electric_room_mission_state == "find_keycard"):
        electric_room_mission_state = "card_check"
        electric_keycard_check_timer = ELECTRIC_KEYCARD_CHECK_DURATION
        spatial_audio.play_ui("mission_chime", volume=0.62)

# Wire Routing Consoles Data
WIRE_COLORS = [Color(238, 65, 62, 255), Color(60, 145, 255, 255), Color(245, 195, 45, 255), Color(45, 210, 135, 255)]
WIRE_NAMES = ["RED", "BLUE", "YELLOW", "GREEN"]
PANEL_RIGHT_ORDERS = {
    "CABLE ROUTING CONSOLE A": [3, 0, 2, 1],
    "CABLE ROUTING CONSOLE B": [1, 3, 0, 2],
    "CABLE ROUTING CONSOLE C": [2, 0, 3, 1],
}
panel_wires = {title: set() for title in PANEL_RIGHT_ORDERS}
dragging_wire = None

# Restore shared Main Lab gameplay defaults that were accidentally omitted while
# the standalone-v38 generator puzzles were integrated. These states are read by
# the shared frame loop and renderer before some interactions can assign them.
electrical_door_unlocked = False
electrical_door_open = 0.0
card_swipe_timer = 0.0
CARD_SWIPE_DURATION = 0.85
archive_door_unlocked = False
archive_door_open = 0.0
# Observation Room door is story-gated by the Research Room anomaly sequence.
observation_door_unlocked = False
