def generate_panel_c_sequences():
    """Create a fresh randomized sequence set, never identical to the prior attempt."""
    previous_signature = tuple(tuple(sequence) for sequence in panel_c_sequences)
    while True:
        patterns = []
        for low, high in PANEL_C_LEVEL_LENGTH_RANGES:
            length = random.randint(low, high)
            pattern = []
            for _ in range(length):
                choices = [switch for switch in range(4) if not pattern or switch != pattern[-1]]
                pattern.append(random.choice(choices))
            patterns.append(pattern)
        if tuple(tuple(sequence) for sequence in patterns) != previous_signature:
            return patterns


def panel_c_ui_layout():
    """Responsive, shared bounds for four bulb-over-switch controls and hit testing."""
    box_w = min(1120, max(320, SCREEN_WIDTH - 28))
    box_h = min(650, max(420, SCREEN_HEIGHT - 24))
    box_x = max(12, (SCREEN_WIDTH - box_w) // 2)
    box_y = max(12, (SCREEN_HEIGHT - box_h) // 2)
    margin = 30
    gap = 14
    pad_w = max(58, (box_w - margin * 2 - gap * 3) // 4)
    pad_h = 224
    start_x = box_x + (box_w - (pad_w * 4 + gap * 3)) // 2
    start_y = box_y + 218
    pads = [(start_x + i * (pad_w + gap), start_y, pad_w, pad_h) for i in range(4)]
    button_w = min(420, box_w - 80)
    start_button = (box_x + (box_w - button_w) // 2, box_y + box_h - 98, button_w, 46)
    return box_x, box_y, box_w, box_h, pads, start_button


def begin_panel_c_playback_level():
    global panel_c_game_state, panel_c_playback_index, panel_c_active_pad
    global panel_c_flash_on, panel_c_playback_timer, panel_c_input_index, panel_c_feedback_message
    panel_c_game_state = "playback"
    panel_c_playback_index = -1
    panel_c_active_pad = -1
    panel_c_flash_on = False
    panel_c_playback_timer = 0.38
    panel_c_input_index = 0
    if panel_c_sequences:
        panel_c_feedback_message = f"WATCH THE BULBS // LEVEL {panel_c_level} OF 4"
    else:
        panel_c_feedback_message = "BULB SEQUENCE INITIALIZING"


def start_panel_c_challenge():
    global panel_c_sequences, panel_c_level, panel_c_complete
    global panel_c_feedback_message, panel_c_transition_timer
    if panel_c_complete:
        return
    panel_c_sequences = generate_panel_c_sequences()
    panel_c_level = 1
    panel_c_transition_timer = 0.0
    panel_c_feedback_message = "WATCH THE BULBS // LEVEL 1 OF 4"
    begin_panel_c_playback_level()


def submit_panel_c_pad(pad_index):
    """Validate one player press and advance/reset the memory challenge as needed."""
    global panel_c_game_state, panel_c_input_index, panel_c_level
    global panel_c_transition_timer, panel_c_feedback_message, panel_c_complete
    global panel_c_active_pad, panel_c_input_flash_timer, panel_c_complete_feedback_timer
    if panel_c_game_state != "input" or not (0 <= pad_index < 4):
        return
    if not panel_c_sequences:
        return
    pattern = panel_c_sequences[panel_c_level - 1]
    if pattern[panel_c_input_index] != pad_index:
        panel_c_game_state = "mistake"
        panel_c_level = 1
        panel_c_transition_timer = 1.65
        panel_c_active_pad = -1
        panel_c_input_flash_timer = 0.0
        panel_c_feedback_message = "WRONG SWITCH // RESETTING THE RUN TO LEVEL 1"
        spatial_audio.play_ui("plastic_impact", volume=0.60)
        return

    panel_c_input_index += 1
    panel_c_active_pad = pad_index
    panel_c_input_flash_timer = 0.26
    spatial_audio.play_ui("item_pickup", volume=0.34)
    if panel_c_input_index >= len(pattern):
        if panel_c_level < 4:
            panel_c_level += 1
            panel_c_game_state = "advance"
            panel_c_transition_timer = 1.40
            panel_c_feedback_message = f"LEVEL VERIFIED // PREPARING LEVEL {panel_c_level}"
        else:
            panel_c_game_state = "complete"
            panel_c_complete = True
            panel_c_complete_feedback_timer = 3.2
            panel_c_active_pad = -1
            panel_c_feedback_message = "MEMORY INTERLOCK DEFEATED // ROUTE C ENERGIZED"
            panel_wires["CABLE ROUTING CONSOLE C"].update(range(4))
            spatial_audio.play_ui("spark_burst", volume=0.85)
    else:
        panel_c_feedback_message = f"CORRECT INPUT // {panel_c_input_index}/{len(pattern)}"

