def open_generator_start_prompt():
    """Open the persistent E/ESC generator decision prompt once both modules are restored."""
    global generator_start_prompt_open, generator_start_prompt_dismissed, generator_minigame_open, generator_active_module
    global is_reading_doc, is_holding_3d_item, is_inventory_open, current_3d_item_obj
    global electrical_access_message, electrical_access_message_timer, generator_event_message_timer
    if (generator_powered or generator_igniting or not generator_ready_to_ignite):
        return False
    generator_start_prompt_open = True
    generator_start_prompt_dismissed = False
    generator_minigame_open = False
    generator_active_module = None
    enable_cursor()
    # The startup prompt replaces the old transient bottom-centre status captions.
    electrical_access_message = ""
    electrical_access_message_timer = 0.0
    generator_event_message_timer = 0.0
    if is_reading_doc or is_holding_3d_item or is_inventory_open:
        is_reading_doc = False
        is_holding_3d_item = False
        is_inventory_open = False
        current_3d_item_obj = None
        disable_cursor()
    return True

def start_generator_ignition():
    """Start the one-shot staged generator sequence after the player confirms with E."""
    global generator_igniting, generator_ignition_timer, is_reading_doc, current_3d_item_obj
    global electrical_access_message, electrical_access_message_timer
    global generator_start_prompt_open, generator_start_prompt_dismissed
    global generator_startup_stage, generator_startup_stage_timer
    global generator_cable_progress, generator_light_recovery_intensity
    global power_intensity, generator_event_message_timer
    if generator_powered or generator_igniting or not generator_ready_to_ignite:
        return

    generator_start_prompt_open = False
    generator_start_prompt_dismissed = False
    generator_igniting = True
    disable_cursor()
    generator_startup_stage = "cranking"
    generator_startup_stage_timer = GENERATOR_CRANK_DURATION
    generator_ignition_timer = generator_startup_stage_timer
    generator_cable_progress = 0.0
    generator_light_recovery_intensity = 0.0
    power_intensity = 0.0
    # Clear stale one-shot recovery captions so the startup can breathe visually.
    electrical_access_message = ""
    electrical_access_message_timer = 0.0
    generator_event_message_timer = 0.0
    if is_reading_doc:
        is_reading_doc = False
        current_3d_item_obj = None
        disable_cursor()
    spatial_audio.play_spatial("generator_rev", Vector3(36.3, 1.2, -2.5), camera, base_volume=1.0)

def announce_generator_event(title, subtitle, success=True, duration=4.6):
    """Queue a readable, temporary on-screen message for recovery milestones."""
    global generator_event_message, generator_event_subtitle
    global generator_event_message_timer, generator_event_success
    generator_event_message = title
    generator_event_subtitle = subtitle
    generator_event_message_timer = duration
    generator_event_success = success

def install_auxiliary_induction_tube():
    """Install A-01 silently; the persistent mission tracker reflects the updated state."""
    global auxiliary_tube_installed, is_reading_doc, current_3d_item_obj
    global selected_inv_index
    if auxiliary_tube_installed:
        return False
    tube = next((item for item in inventory if getattr(item, "item_type", "") == "auxiliary_tube"), None)
    if tube is None:
        return False
    inventory.remove(tube)
    tube.picked_up = True
    auxiliary_tube_installed = True
    selected_inv_index = -1
    if is_reading_doc and current_3d_item_obj and getattr(current_3d_item_obj, "item_type", "") == "generator":
        is_reading_doc = False
        current_3d_item_obj = None
        disable_cursor()
    # Intentionally no bottom-centre COMPONENT STATUS toast for this component.
    spatial_audio.play_ui("item_pickup", volume=0.75)
    return True

def _handle_electric_generator_interaction():
    """Advance the current generator story beat without bypassing the tube animation."""
    global electric_room_entry_state, electric_generator_inspection_seen
    global electric_panel_mission_started, electric_return_to_generator
    global electric_tube_mission_state, electric_objective_waypoint_ping_timer
    global electric_objective_waypoint_arrival_played, electric_objective_waypoint_kind
    global generator_start_prompt_open, generator_start_prompt_dismissed

    if electric_room_entry_state == "generator_waypoint":
        electric_room_entry_state = "active"

    has_tube = any(getattr(item, "item_type", "") == "auxiliary_tube" for item in inventory)
    if not electric_generator_inspection_seen:
        electric_generator_inspection_seen = True
        electric_panel_mission_started = True
        electric_return_to_generator = False
        spatial_audio.play_ui("mission_chime", volume=0.66)
        return open_generator_module_selector()

    if (_electric_all_panels_connected() and electric_panel_mission_dismissed
            and electric_tube_mission_state == "inactive" and not auxiliary_tube_installed):
        electric_return_to_generator = False
        electric_tube_mission_state = "find_tube"
        electric_objective_waypoint_ping_timer = 0.0
        electric_objective_waypoint_arrival_played = False
        electric_objective_waypoint_kind = None
        spatial_audio.play_ui("mission_chime", volume=0.70)
        return open_generator_module_selector()

    if electric_tube_mission_state == "install_tube" and has_tube:
        return _begin_auxiliary_tube_install_cutscene()

    if auxiliary_tube_installed and induction_alignment_complete and thermal_module_complete and not generator_powered:
        _close_generator_module_selector() if generator_minigame_open else None
        generator_start_prompt_open = True
        generator_start_prompt_dismissed = False
        enable_cursor()
        spatial_audio.play_ui("item_pickup", volume=0.48)
        return True

    return open_generator_module_selector()


