def induction_alignment_layout():
    """Responsive geometry for the premium induction-core console.

    The left half is reserved for the live radial stability visualiser and coil
    stack. The right half holds one physical-looking rotary screw control per ring.
    Screw rectangles are also used for mouse-wheel / click input hit testing.
    """
    box_w = min(1400, max(320, SCREEN_WIDTH - 28))
    box_h = min(700, max(420, SCREEN_HEIGHT - 24))
    box_x = (SCREEN_WIDTH - box_w) // 2
    box_y = (SCREEN_HEIGHT - box_h) // 2
    ring_count = len(induction_alignment_positions)
    center_x = box_x + 17 + int(box_w * 0.23)
    center_y = box_y + int(box_h * 0.472)
    radii_by_count = {
        3: (48, 88, 126),
        5: (42, 66, 90, 114, 138),
        7: (34, 54, 74, 94, 114, 134, 154),
    }
    radii = radii_by_count.get(ring_count, tuple(34 + i * 20 for i in range(ring_count)))
    control_x = box_x + int(box_w * 0.50)
    right_w = box_x + box_w - 22 - control_x
    rows = []
    if ring_count <= 3:
        row_h, row_step, row_start = 78, 100, 140
        knob_size = 58
    elif ring_count <= 5:
        row_h, row_step, row_start = 54, 61, 139
        knob_size = 48
    else:
        row_h, row_step, row_start = 46, 49, 140
        knob_size = 42
    for i in range(ring_count):
        row_y = box_y + row_start + i * row_step
        row = (control_x, row_y, right_w, row_h)
        knob_rect = (int(control_x + right_w * 0.29 - knob_size / 2),
                     int(row_y + (row_h - knob_size) / 2), knob_size, knob_size)
        rows.append((row, knob_rect))
    meter_label_y = box_y + box_h - 153
    meter_rect = (control_x, meter_label_y + 21, right_w, 10)
    test_rect = (control_x, box_y + box_h - 82, right_w, 42)
    close_rect = (box_x + box_w - 112, box_y + 17, 88, 25)
    return (box_x, box_y, box_w, box_h, center_x, center_y, radii,
            control_x, right_w, rows, meter_label_y, meter_rect, test_rect, close_rect)

def induction_alignment_menu_layout():
    """Responsive geometry for the industrial level-select / completion console."""
    box_w = min(1240, max(320, SCREEN_WIDTH - 28))
    box_h = min(660, max(420, SCREEN_HEIGHT - 24))
    box_x = (SCREEN_WIDTH - box_w) // 2
    box_y = (SCREEN_HEIGHT - box_h) // 2
    close_rect = (box_x + box_w - 112, box_y + 17, 88, 27)
    card_y = box_y + 145
    card_h = min(282, max(192, box_h - 305))
    gap = 17
    card_w = (box_w - 72 - gap * 2) // 3
    cards = [(box_x + 36 + i * (card_w + gap), card_y, card_w, card_h) for i in range(3)]
    continue_rect = (box_x + box_w // 2 - 180, box_y + box_h - 94, 360, 42)
    menu_rect = (box_x + box_w // 2 - 118, box_y + box_h - 44, 236, 26)
    return box_x, box_y, box_w, box_h, close_rect, cards, continue_rect, menu_rect

def induction_alignment_decrease_rect(row, ring_count):
    """Hit box for the dedicated reverse/DEC screw on the far side of each track."""
    rx, ry, rw, rh = row
    size = 38 if ring_count <= 3 else (31 if ring_count <= 5 else 27)
    cx = int(rx + rw * 0.815)
    cy = int(ry + rh / 2)
    return (cx - size // 2, cy - size // 2, size, size)

def draw_induction_decrease_screw(cx, cy, radius, detent, hovered, live_correct):
    """Render the matching industrial reverse adjuster with a clear minus engraving."""
    cx, cy, radius = int(cx), int(cy), int(radius)
    accent = Color(99, 255, 177, 255) if live_correct else Color(92, 186, 145, 255)
    draw_circle(cx + 2, cy + 3, radius + 7, Color(0, 0, 0, 150))
    draw_circle(cx, cy, radius + 6, Color(19, 27, 28, 255))
    draw_circle_lines(cx, cy, radius + 6, Color(106, 126, 123, 255))
    draw_circle(cx, cy, radius + 3, Color(53, 65, 65, 255))
    draw_circle_lines(cx, cy, radius + 3, Color(149, 163, 156, 255))
    # Four tiny mounting rivets make it read as installed hardware.
    for a in (-math.pi / 4, math.pi / 4, 3 * math.pi / 4, 5 * math.pi / 4):
        bx = int(cx + math.cos(a) * (radius + 4))
        by = int(cy + math.sin(a) * (radius + 4))
        draw_circle(bx, by, 1.7, Color(24, 32, 32, 255))
        draw_circle_lines(bx, by, 1.7, Color(136, 151, 144, 255))
    draw_circle(cx - 1, cy - 2, radius, Color(116, 130, 126, 255))
    draw_circle(cx, cy, radius - 2, Color(71, 83, 81, 255))
    draw_circle_lines(cx, cy, radius - 2, Color(174, 187, 178, 255))
    draw_circle(cx - 2, cy - 3, max(3, radius - 5), Color(91, 103, 99, 255))
    # Slotted screw groove turns as a reminder this is a physical adjuster.
    a = -math.pi / 2.0 + (int(detent) % 8) * math.pi / 4.0
    dx, dy = math.cos(a) * radius * 0.62, math.sin(a) * radius * 0.62
    px, py = -math.sin(a), math.cos(a)
    for offset in (-1, 0, 1):
        shade = Color(150, 164, 157, 255) if offset == -1 else Color(39, 48, 47, 255)
        ox, oy = px * offset, py * offset
        draw_line(int(cx - dx + ox), int(cy - dy + oy), int(cx + dx + ox), int(cy + dy + oy), shade)
    # Engraved reverse indicator sits on the face and remains legible at 7-ring size.
    draw_line(cx - max(3, int(radius * 0.34)), cy + max(2, int(radius * 0.22)),
              cx + max(3, int(radius * 0.34)), cy + max(2, int(radius * 0.22)), accent)
    if hovered:
        draw_circle_lines(cx, cy, radius + 9, Color(105, 255, 186, 210))

def next_induction_alignment_level():
    """Return the first not-yet-completed level, or 4 when all are complete."""
    for level_num, done in enumerate(induction_alignment_levels_complete, start=1):
        if not done:
            return level_num
    return 4

def start_induction_alignment_level(level_num):
    """Enter the currently unlocked level without discarding its previous settings."""
    global induction_alignment_screen, induction_alignment_active_level
    global induction_alignment_positions, induction_alignment_targets
    global induction_ring_feedback, induction_alignment_tested
    global induction_alignment_feedback, induction_alignment_feedback_timer
    if level_num not in (1, 2, 3) or level_num != next_induction_alignment_level():
        return False
    induction_alignment_active_level = level_num
    induction_alignment_positions = induction_alignment_level_positions[level_num]
    induction_alignment_targets = induction_alignment_level_targets[level_num]
    induction_ring_feedback = ["untested"] * len(induction_alignment_positions)
    induction_alignment_tested = False
    induction_alignment_feedback = f"LEVEL {level_num:02d} // Align all {len(induction_alignment_positions)} induction rings, then test."
    induction_alignment_feedback_timer = 0.0
    induction_alignment_screen = "game"
    spatial_audio.play_ui("item_pickup", volume=0.42)
    return True

def open_induction_alignment():
    global induction_alignment_open, induction_alignment_screen
    global is_reading_doc, is_holding_3d_item, is_inventory_open, current_3d_item_obj
    if not auxiliary_tube_installed or induction_alignment_complete:
        return False
    is_reading_doc = False
    is_holding_3d_item = False
    is_inventory_open = False
    current_3d_item_obj = None
    induction_alignment_open = True
    induction_alignment_screen = "menu"
    enable_cursor()
    spatial_audio.play_ui("item_pickup", volume=0.50)
    return True

def close_induction_alignment():
    global induction_alignment_open, current_3d_item_obj
    induction_alignment_open = False
    current_3d_item_obj = None
    disable_cursor()
    spatial_audio.play_ui("item_pickup", volume=0.42)

def induction_energy_percent():
    """Live, non-verbal transfer efficiency based on every ring in this level."""
    if not induction_alignment_positions:
        return 0
    quality = []
    for pos, target in zip(induction_alignment_positions, induction_alignment_targets):
        delta = (target - pos) % 8
        distance = min(delta, 8 - delta)
        quality.append(max(0.0, 1.0 - distance / 4.0))
    return int(round(sum(quality) / len(quality) * 100))

def draw_induction_radial_waveform(cx, cy, base_radius, locked_count, ring_count, time_seconds):
    """Draw an animated AI-voice-style radial waveform tied to actual ring state.

    Incorrect layers retain strong, irregular movement. Each correctly configured
    layer reduces the movement amplitude; when every layer is correct the radial
    trace resolves into a clean, stable halo. This is pure 2D drawing and has no
    external texture/model dependency, so the console stays lightweight.
    """
    ring_count = max(1, int(ring_count))
    stability = max(0.0, min(1.0, float(locked_count) / ring_count))
    disturbance = 1.0 - stability
    cx, cy = int(cx), int(cy)

    # Quiet instrument-grid circles remain behind the live trace at every stage.
    draw_circle_lines(cx, cy, int(base_radius + 17), Color(21, 95, 68, 95))
    draw_circle_lines(cx, cy, int(base_radius + 11), Color(24, 125, 80, 110))
    draw_circle_lines(cx, cy, int(base_radius - 10), Color(20, 93, 63, 115))

    # The subtle halo brightens as the core becomes more stable.
    halo_alpha = int(36 + stability * 105)
    draw_circle_lines(cx, cy, int(base_radius + 2), Color(54, 244, 157, halo_alpha))
    draw_circle_lines(cx, cy, int(base_radius + 5), Color(22, 179, 105, int(22 + stability * 49)))

    spoke_count = 192
    for i in range(spoke_count):
        angle = -math.pi / 2.0 + (2.0 * math.pi * i / spoke_count)
        # Several incommensurate frequencies create organic, non-loop-obvious
        # irregularity without random jitter or allocations in the render loop.
        n1 = math.sin(time_seconds * 4.7 + i * 1.91)
        n2 = math.sin(time_seconds * 8.3 - i * 2.37 + 0.8)
        n3 = math.sin(time_seconds * 13.1 + i * 0.73 + math.sin(i * 0.17))
        noise = (n1 * 0.48 + n2 * 0.34 + n3 * 0.18)
        fine_noise = math.sin(time_seconds * 18.0 + i * 3.7) * 0.5
        spike_len = 2.2 + disturbance * (7.0 + (noise + 1.0) * 7.8 + max(0.0, fine_noise) * 7.0)
        inward = disturbance * max(0.0, -noise) * 2.2
        r1 = base_radius - 3.0 - inward
        r2 = base_radius + spike_len
        x1 = int(cx + math.cos(angle) * r1)
        y1 = int(cy + math.sin(angle) * r1)
        x2 = int(cx + math.cos(angle) * r2)
        y2 = int(cy + math.sin(angle) * r2)

        if stability >= 0.999:
            # Uniform short ticks and the clean outline become a steady circular halo.
            line_col = Color(92, 255, 175, 220 if i % 3 == 0 else 165)
        elif i % 9 == 0:
            line_col = Color(103, 255, 180, int(165 + 65 * disturbance))
        elif i % 3 == 0:
            line_col = Color(41, 221, 135, int(145 + 70 * disturbance))
        else:
            line_col = Color(24, 168, 100, int(105 + 75 * disturbance))
        draw_line(x1, y1, x2, y2, line_col)

    if stability >= 0.999:
        # A brighter, smooth outline is the unambiguous final-state visual reward.
        draw_circle_lines(cx, cy, int(base_radius + 1), Color(119, 255, 187, 245))
        draw_circle_lines(cx, cy, int(base_radius + 7), Color(65, 237, 151, 145))

def draw_induction_screw_control(cx, cy, radius, detent, hovered, live_correct, feedback_state):
    """Render a metal screw-head adjuster with a slot that physically rotates."""
    cx, cy, radius = int(cx), int(cy), int(radius)
    accent = Color(91, 255, 171, 255) if live_correct else Color(45, 180, 129, 255)
    if feedback_state == "near" and not live_correct:
        accent = Color(238, 187, 76, 255)
    elif feedback_state == "wrong" and not live_correct:
        accent = Color(225, 83, 80, 255)

    # Cast shadow, mounting seat, machined bezel and raised screw face.
    draw_circle(cx + 2, cy + 3, radius + 9, Color(0, 0, 0, 155))
    draw_circle(cx, cy, radius + 8, Color(16, 22, 24, 255))
    draw_circle_lines(cx, cy, radius + 8, Color(92, 111, 111, 255))
    draw_circle(cx, cy, radius + 5, Color(47, 58, 59, 255))
    draw_circle_lines(cx, cy, radius + 5, Color(124, 143, 140, 255))

    # Machined detent marks around the collar: the selected detent lights green.
    for tick in range(16):
        a = -math.pi / 2.0 + tick * (2.0 * math.pi / 16.0)
        long_tick = (tick % 2 == 0)
        r_outer = radius + (7 if long_tick else 5)
        r_inner = radius + (3 if long_tick else 3.5)
        tx1 = int(cx + math.cos(a) * r_inner)
        ty1 = int(cy + math.sin(a) * r_inner)
        tx2 = int(cx + math.cos(a) * r_outer)
        ty2 = int(cy + math.sin(a) * r_outer)
        color = accent if tick == (int(detent) * 2) % 16 else Color(100, 120, 119, 210)
        if hovered and tick == (int(detent) * 2) % 16:
            color = Color(163, 255, 202, 255)
        draw_line(tx1, ty1, tx2, ty2, color)

    # Layered steel face gives a bevelled, tactile look without heavy geometry.
    draw_circle(cx - 1, cy - 2, radius + 1, Color(112, 126, 125, 255))
    draw_circle(cx, cy, radius - 2, Color(70, 83, 84, 255))
    draw_circle_lines(cx, cy, radius - 2, Color(166, 184, 179, 255))
    draw_circle(cx - 2, cy - 3, max(3, radius - 6), Color(89, 103, 102, 255))
    draw_circle(cx + 2, cy + 3, max(2, radius - 8), Color(63, 74, 74, 255))

    # A slotted screw groove rotates with the selected calibration detent.
    slot_angle = -math.pi / 2.0 + int(detent) * (math.pi / 4.0)
    dx = math.cos(slot_angle) * (radius * 0.62)
    dy = math.sin(slot_angle) * (radius * 0.62)
    px, py = -math.sin(slot_angle), math.cos(slot_angle)
    for offset in (-2, -1, 0, 1, 2):
        shade = Color(42, 51, 52, 255) if offset != -2 else Color(143, 157, 151, 255)
        ox, oy = px * offset, py * offset
        draw_line(int(cx - dx + ox), int(cy - dy + oy),
                  int(cx + dx + ox), int(cy + dy + oy), shade)
    # Tiny centre bore plus an engraved ADVANCE mark, so this control's direction is clear.
    draw_circle(cx, cy, 2.3, Color(35, 45, 46, 255))
    mark_x, mark_y = cx + int(radius * 0.37), cy + int(radius * 0.35)
    mark_half = max(2, int(radius * 0.17))
    draw_line(mark_x - mark_half, mark_y, mark_x + mark_half, mark_y, Color(123, 255, 184, 235))
    draw_line(mark_x, mark_y - mark_half, mark_x, mark_y + mark_half, Color(123, 255, 184, 235))
    if hovered:
        draw_circle_lines(cx, cy, radius + 10, Color(91, 255, 181, 175))

def test_induction_alignment():
    """Validate the active level; level completion unlocks the next stage."""
    global induction_alignment_complete, induction_alignment_tested, generator_ready_to_ignite
    global induction_alignment_feedback, induction_alignment_feedback_timer
    global induction_alignment_screen
    global electrical_access_message, electrical_access_message_timer
    if induction_alignment_complete or induction_alignment_screen != "game":
        return induction_alignment_complete
    base_names = ("DRIVE COIL", "COUPLING COIL", "FIELD STABILISER")
    names = [base_names[i] if i < len(base_names) else f"AUXILIARY COIL {i + 1:02d}"
             for i in range(len(induction_alignment_positions))]
    guidance = []
    for i, (position, target) in enumerate(zip(induction_alignment_positions, induction_alignment_targets)):
        if position == target:
            induction_ring_feedback[i] = "correct"
            continue
        clockwise_steps = (target - position) % 8
        distance = min(clockwise_steps, 8 - clockwise_steps)
        induction_ring_feedback[i] = "near" if distance == 1 else "wrong"
        direction = "CLOCKWISE" if clockwise_steps <= 4 else "COUNTER-CLOCKWISE"
        guidance.append(f"{names[i]}: ROTATE {direction}")
    induction_alignment_tested = True
    induction_alignment_feedback_timer = 5.0
    if all(state == "correct" for state in induction_ring_feedback):
        level_num = induction_alignment_active_level
        induction_alignment_levels_complete[level_num - 1] = True
        induction_alignment_feedback = f"LEVEL {level_num:02d} COMPLETE // INDUCTION FIELD STABLE"
        induction_alignment_feedback_timer = 5.0
        spatial_audio.play_ui("spark_burst", volume=0.78)
        if level_num < 3:
            # A transition screen gives the player a clear next step. The following
            # level remains playable from the menu if they close the console here.
            induction_alignment_screen = "level_complete"
        else:
            induction_alignment_complete = True
            generator_ready_to_ignite = bool(auxiliary_tube_installed and induction_alignment_complete and thermal_module_complete)
            induction_alignment_screen = "level_complete"
            induction_alignment_feedback = "ALL THREE LEVELS COMPLETE // BATTERY A RESTORED"
            electrical_access_message = "MODULE A ONLINE // INDUCTION ALIGNMENT STABLE"
            electrical_access_message_timer = 4.5
            announce_generator_event("BATTERY A RESTORED",
                                     "ALL THREE INDUCTION LEVELS COMPLETE // MODULE A OUTPUT STABLE", True, 5.5)
        return True
    induction_alignment_feedback = "ALIGNMENT FAILED // " + "  |  ".join(guidance)
    if not guidance:
        induction_alignment_feedback = "ALIGNMENT TEST FAILED // REVIEW COIL INDICATORS"
    spatial_audio.play_ui("plastic_impact", volume=0.48)
    return False

