    box_h = min(640, max(470, SCREEN_HEIGHT - 24))
    box_x = (SCREEN_WIDTH - box_w) // 2
    box_y = (SCREEN_HEIGHT - box_h) // 2
    close_rect = (box_x + box_w - 112, box_y + 17, 88, 27)
    left_x = box_x + 22
    left_y = box_y + 91
    left_w = int((box_w - 66) * 0.43)
    panel_h = box_h - 129
    right_x = left_x + left_w + 18
    right_w = box_x + box_w - 22 - right_x
    valve_card = (right_x, box_y + 112, right_w, 158)
    pressure_card = (right_x, box_y + 286, right_w, 158)
    button_size = 38
    valve_minus = (right_x + right_w - 100, valve_card[1] + 48, button_size, button_size)
    valve_plus = (right_x + right_w - 53, valve_card[1] + 48, button_size, button_size)
    pressure_minus = (right_x + right_w - 100, pressure_card[1] + 48, button_size, button_size)
    pressure_plus = (right_x + right_w - 53, pressure_card[1] + 48, button_size, button_size)
