    draw_rectangle(bx + 15, by + 12, bw - 30, 86, panel)
    draw_rectangle(bx + 15, by + 12, 5, 86, cyan)

    # Header: indexed display, status lamps, and warning state.
    _draw_calibration_text("SECTOR B  /  AUXILIARY POWER SYSTEMS", bx + 31, by + 21, 9, cyan)
    _draw_calibration_text("GENERATOR DIAGNOSTIC CONSOLE", bx + 31, by + 39, 23, white)
