                draw_rectangle_lines(plaque_x, plaque_y, plaque_w, plaque_h, Color(43, 120, 81, 255))
                _draw_calibration_text("A-01  //  TUBE ONLINE", plaque_x + 10, plaque_y + 5, 8, Color(103, 207, 150, 255))
                _draw_calibration_text("FIELD CALIBRATION", plaque_x + 10, plaque_y + 18, 9, green)
