                # Keep a compact target reminder at the right edge of the plate.
                status_size = 9 if _measure_calibration_text(thermal_state_text, 9) <= status_rect[2]-12 else 8
                _draw_calibration_text(thermal_state_text, status_rect[0]+8, status_rect[1]+7, status_size, state_text_col)
                gauge_x = left_x+18
                gauge_y = left_y+152
                gauge_w = left_w-36
                gauge_h = 16
                draw_rectangle(gauge_x, gauge_y, gauge_w, gauge_h, Color(11, 22, 30, 255))
                safe_x = gauge_x + int(gauge_w*(58.0-35.0)/80.0)
                safe_w = max(3, int(gauge_w*(68.0-58.0)/80.0))
                # Distinct cold-blue, safe-green, and hot-orange regions stay visible even before the needle moves.
                draw_rectangle(gauge_x+1, gauge_y+2, max(1, safe_x-gauge_x-1), gauge_h-4, Color(18, 70, 118, 255))
                draw_rectangle(safe_x, gauge_y+1, safe_w, gauge_h-2, Color(35, 193, 113, 255))
                hot_x = safe_x + safe_w
                draw_rectangle(hot_x, gauge_y+2, max(1, gauge_x+gauge_w-hot_x-1), gauge_h-4, Color(150, 48, 11, 255))
                temp_norm = max(0.0, min(1.0, (coolant_core_temperature-35.0)/80.0))
                marker_x = gauge_x + int(gauge_w*temp_norm)
                draw_rectangle(marker_x-4, gauge_y-6, 8, gauge_h+12, Color(245, 250, 255, 255))
                draw_rectangle(marker_x-2, gauge_y-4, 4, gauge_h+8, temp_color)
                draw_rectangle_lines(gauge_x, gauge_y, gauge_w, gauge_h, thermal_edge)
                draw_line(safe_x, gauge_y-4, safe_x, gauge_y+gauge_h+4, Color(121, 255, 171, 255))
                draw_line(safe_x+safe_w, gauge_y-4, safe_x+safe_w, gauge_y+gauge_h+4, Color(121, 255, 171, 255))
                _draw_calibration_text("35 C", gauge_x, gauge_y+23, 9, muted)
                max_txt = "115 C"
                _draw_calibration_text(max_txt, gauge_x+gauge_w-_measure_calibration_text(max_txt, 9), gauge_y+23, 9, muted)

                flow_pct = max(0, min(100, int(round(coolant_valve_setting*coolant_pump_pressure/60.0))))
                _draw_calibration_text("COOLANT FLOW", left_x+18, gauge_y+63, 11, white)
                flow_x, flow_y, flow_w, flow_h = left_x+18, gauge_y+86, gauge_w, 12
                draw_rectangle(flow_x, flow_y, flow_w, flow_h, Color(27, 43, 51, 255))
                draw_rectangle(flow_x, flow_y, int(flow_w*flow_pct/100.0), flow_h, temp_color)
                draw_rectangle_lines(flow_x, flow_y, flow_w, flow_h, thermal_edge)
                _draw_calibration_text(f"{flow_pct:02d}%  //  RETURN LOOP CAPACITY", flow_x, flow_y+20, 10, ice)

                _draw_calibration_text("STABILITY LOCK", left_x+18, flow_y+59, 10, muted)
                # Compact hold meter: approximately half the old width, matching the requested [-----] look.
                stability_w = max(110, int(gauge_w * 0.54))
                stability_x, stability_y, stability_h = left_x+18, flow_y+80, 10
                draw_rectangle(stability_x, stability_y, stability_w, stability_h, Color(27, 43, 51, 255))
                draw_rectangle(stability_x, stability_y, int(stability_w*min(1.0, coolant_stability_timer/2.8)), stability_h,
                               green if coolant_stability_timer > 0 else Color(53, 77, 87, 255))
                draw_rectangle_lines(stability_x, stability_y, stability_w, stability_h, thermal_edge)
                _draw_calibration_text(f"HOLD SAFE CONDITIONS  //  {min(2.8, coolant_stability_timer):.1f}/2.8 SEC",
                                       stability_x, stability_y+17, 9, muted)

                # Clickable valve/pump controls: buttons and direct track interaction.
                valve_accent = temp_color
                pump_accent = _blend_thermal_color(temp_color, Color(229, 241, 245, 255), 0.16)
                for card, title, value, unit, minus_rect, plus_rect, track, accent in (
                    (valve_card, "COOLANT VALVE", coolant_valve_setting, "% OPEN", valve_minus, valve_plus, valve_track, valve_accent),
                    (pressure_card, "COOLING PUMP PRESSURE", coolant_pump_pressure, "% OUTPUT", pressure_minus, pressure_plus, pressure_track, pump_accent),
                ):
                    cx, cy, cw, ch = card
                    draw_rectangle(cx, cy, cw, ch, panel)
                    draw_rectangle_lines(cx, cy, cw, ch, thermal_edge)
                    draw_rectangle(cx+1, cy+1, cw-2, 4, accent)
                    _draw_calibration_text(title, cx+18, cy+17, 13, white)
                    val_label = f"{value:03d}{unit}"
                    _draw_calibration_text(val_label, cx+18, cy+48, 21, accent)
                    for rect, label in ((minus_rect, "-"), (plus_rect, "+")):
                        rx, ry, rw, rh = rect
                        hovered = rx <= mouse_pos.x <= rx+rw and ry <= mouse_pos.y <= ry+rh
                        draw_rectangle(rx, ry, rw, rh, Color(24, 51, 61, 255) if hovered else Color(9, 20, 27, 255))
                        draw_rectangle_lines(rx, ry, rw, rh, accent if hovered else Color(55, 91, 103, 255))
                        label_size = 22
                        _draw_calibration_text(label, rx+(rw-_measure_calibration_text(label, label_size))//2, ry+7, label_size, white)
                    tx, ty, tw, th = track
                    draw_rectangle(tx, ty, tw, th, Color(17, 29, 36, 255))
                    draw_rectangle(tx+1, ty+1, max(1, int((tw-2)*value/100.0)), th-2, accent)
                    safe_low, safe_high = ((45, 80) if title == "COOLANT VALVE" else (42, 72))
                    draw_pressure_safe_band(tx, ty, tw, th, safe_low, safe_high)
                    marker_x = tx + int(tw*value/100.0)
                    draw_circle(marker_x, ty+th//2, 9, Color(4, 12, 15, 255))
                    draw_circle(marker_x, ty+th//2, 6, white)
                    draw_circle_lines(marker_x, ty+th//2, 8, accent)
                    draw_rectangle_lines(tx, ty, tw, th, Color(59, 88, 99, 255))
                    instruction = f"GREEN BAND {safe_low}-{safe_high}%  //  +/- 5% PER STEP"
                    _draw_calibration_text(instruction, tx, ty+19, 9, muted)

                feedback_col = green if coolant_stability_timer > 0 else (red if coolant_core_temperature >= 105 else temp_color)
                feedback_text = coolant_recovery_feedback
                feedback_w = _measure_calibration_text(feedback_text, 11)
                max_feedback_w = box_w-52
                if feedback_w > max_feedback_w:
                    feedback_text = "ADJUST COOLANT VALVE AND PUMP PRESSURE TO HOLD 58–68 C"
                    feedback_w = _measure_calibration_text(feedback_text, 11)
                feedback_x = box_x + (box_w-feedback_w)//2
                feedback_y = box_y + box_h - 61
                draw_rectangle(box_x+22, feedback_y-8, box_w-44, 30, Color(13, 27, 34, 255))
                draw_rectangle_lines(box_x+22, feedback_y-8, box_w-44, 30, Color(43, 75, 87, 255))
                _draw_calibration_text(feedback_text, feedback_x, feedback_y+1, 11, feedback_col)
                _draw_calibration_text("TARGET: 58–68 C  //  VALVE: 45–80%  //  PRESSURE: 42–72%  //  SMALL IN-BAND MOVEMENT IS OK", box_x+25, box_y+box_h-22, 9, muted)



