def _alt_ending_panel_rect():
    """Responsive final-boss panel with safe margins on 720p through ultrawide displays."""
    sw, sh = max(320, int(SCREEN_WIDTH)), max(320, int(SCREEN_HEIGHT))
    width = min(1180, sw - 24)
    height = min(790, sh - 24)
    width = max(296, width)
    height = max(296, height)
    return ((sw - width) // 2, (sh - height) // 2, width, height)


def _alt_ending_fit_font(text, max_width, font_size, min_size=9):
    """Find a readable single-line size that cannot exceed its UI region."""
    size = max(min_size, int(font_size))
    limit = max(1, int(max_width))
    while size > min_size and measure_text(str(text), size) > limit:
        size -= 1
    return size


def _alt_ending_draw_fit_text(text, x, y, width, height, font_size, color,
                              min_size=9, align="left", padding=0):
    """Draw a genuinely contained single line; never let text escape its allocated box.

    Raylib's draw_text does not clip to a rectangle. If the requested text is still wider
    than the available area at min_size, the old implementation measured a clipped width
    but drew the *entire* string, allowing long puzzle instructions to run past the panel.
    Shrink first, then ellipsize as a final safety net. Long instructions should use the
    wrapped helper instead so their full wording remains visible.
    """
    text = str(text)
    box_x, box_y, box_w, box_h = int(x), int(y), max(1, int(width)), max(1, int(height))
    pad = max(0, int(padding))
    inner_w = max(1, box_w - pad * 2)
    size = _alt_ending_fit_font(text, inner_w, font_size, min_size)
    if measure_text(text, size) > inner_w:
        ellipsis = "..."
        trimmed = text
        while trimmed and measure_text(trimmed + ellipsis, size) > inner_w:
            trimmed = trimmed[:-1]
        text = (trimmed.rstrip() + ellipsis) if trimmed else ellipsis
    tw = min(inner_w, measure_text(text, size))
    if align == "center":
        tx = box_x + (box_w - tw) // 2
    elif align == "right":
        tx = box_x + box_w - pad - tw
    else:
        tx = box_x + pad
    ty = box_y + max(0, (box_h - size) // 2)
    draw_text(text, tx, ty, size, color)
    return size


def _alt_ending_wrap_lines(text, max_width, font_size):
    """Word-wrap copy for card bodies so a long sentence stays inside its card."""
    words = str(text).split()
    if not words:
        return [""]
    lines, current = [], ""
    for word in words:
        candidate = word if not current else current + " " + word
        if current and measure_text(candidate, font_size) > max_width:
            lines.append(current)
            current = word
        else:
            current = candidate
    if current:
        lines.append(current)
    return lines


def _alt_ending_draw_wrapped(text, x, y, width, height, font_size, color,
                             min_size=9, max_lines=2, line_gap=3):
    """Draw wrapped lines inside a fixed text region, reducing size before clipping."""
    width, height = max(1, int(width)), max(1, int(height))
    size = int(font_size)
    while size > min_size:
        lines = _alt_ending_wrap_lines(text, width, size)
        if len(lines) <= max_lines and len(lines) * (size + line_gap) - line_gap <= height:
            break
        size -= 1
    lines = _alt_ending_wrap_lines(text, width, size)
    line_height = size + line_gap
    max_visible = max(1, min(max_lines, (height + line_gap) // line_height))
    if len(lines) > max_visible:
        lines = lines[:max_visible]
        if lines:
            last = lines[-1]
            while last and measure_text(last + "…", size) > width:
                last = last[:-1]
            lines[-1] = (last.rstrip() + "…") if last else "…"
    y0 = int(y)
    for index, line in enumerate(lines):
        draw_text(line, int(x), y0 + index * line_height, size, color)
    return len(lines)


def _alt_ending_control_rects(panel=None):
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    x, w, h = px + 38, pw - 76, 72
    return tuple((x, py + 116 + i * 86, w, h) for i in range(4))


def _alt_ending_button_rect(panel=None):
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    return (px + pw - 282, py + ph - 58, 244, 38)


def _alt_ending_back_rect(panel=None):
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    return (px + 38, py + ph - 58, 232, 38)


def _alt_ending_security_rects(panel=None):
    """Six camera cards laid out to match the six physical CCTV monitors in Security."""
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    margin = 32
    gap_x = 10
    gap_y = 10
    card_w = max(1, (pw - margin * 2 - gap_x * 2) // 3)
    card_h = 88
    start_x = px + margin
    start_y = py + 184
    return tuple((start_x + (i % 3) * (card_w + gap_x),
                  start_y + (i // 3) * (card_h + gap_y), card_w, card_h)
                 for i in range(6))

def _alt_ending_hack_node_rects(panel=None):
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    node_w, node_h, gap = 68, 58, 24
    total_w = node_w * 3 + gap * 2
    start_x = px + (pw - total_w) // 2
    start_y = py + 208
    return tuple((start_x + (i % 3) * (node_w + gap),
                  start_y + (i // 3) * (node_h + gap), node_w, node_h)
                 for i in range(9))


def _alt_ending_delete_lock_rects(panel=None):
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    gap = 14
    card_w = min(270, (pw - 110 - 2 * gap) // 3)
    card_h = 82
    total_w = card_w * 3 + gap * 2
    start_x = px + (pw - total_w) // 2
    y = py + 146
    return tuple((start_x + i * (card_w + gap), y, card_w, card_h) for i in range(3))


def _alt_ending_delete_keypad_rects(panel=None):
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    key_w = min(58, max(38, (pw - 110) // 5))
    key_h = min(40, max(30, int((ph - 420) / 4)))
    gap = max(6, min(10, (pw - key_w * 3) // 10))
    total_w = key_w * 3 + gap * 2
    start_x = px + (pw - total_w) // 2
    # Place the keypad relative to the panel bottom so it remains inside compact screens.
    start_y = min(py + 348, py + ph - (key_h * 4 + gap * 4 + 105))
    digits = {}
    for digit in range(1, 10):
        i = digit - 1
        digits[digit] = (start_x + (i % 3) * (key_w + gap),
                         start_y + (i // 3) * (key_h + gap), key_w, key_h)
    clear_y = start_y + 3 * (key_h + gap) + 2
    clear = (px + pw // 2 - 96, clear_y, 192, 30)
    confirm = (px + pw // 2 - min(190, (pw - 56) // 2), py + ph - 64,
               min(380, pw - 56), 38)
    return digits, clear, confirm


