def _alt_ending_open_security_room_puzzle():
    """Open Minigame 1 from the actual Security Room map, without touching Main Lab monitor textures."""
    global alt_ending_open, alt_ending_page, alt_ending_entry_source
    global alt_ending_timer, alt_ending_interference_countdown
    global is_game_paused, is_reading_doc, is_holding_3d_item, is_inventory_open
    global is_keypad_open, is_photo_inspect_open, is_master_terminal_open, current_3d_item_obj
    global dragging_wire, generator_minigame_open, generator_active_module
    if not alt_ending_initialized:
        _alt_ending_reset_state()
    # Reuse the established modal and cursor behavior, but deliberately avoid calling
    # _alt_ending_open_control(): that function also retargets the separate Main Lab CRTs.
    is_game_paused = False
    is_reading_doc = False
    is_holding_3d_item = False
    is_inventory_open = False
    is_keypad_open = False
    is_photo_inspect_open = False
    is_master_terminal_open = False
    current_3d_item_obj = None
    dragging_wire = None
    generator_minigame_open = False
    generator_active_module = None
    alt_ending_open = True
    alt_ending_entry_source = "security_room"
    alt_ending_page = "security_done" if alt_ending_security_complete else "security"
    alt_ending_timer = 0.0
    alt_ending_interference_countdown = 5.8
    enable_cursor()
    try:
        spatial_audio.play_ui("access_granted", volume=0.44)
    except Exception:
        pass
    _alt_ending_set_feedback(
        "SECURITY ROOM ROUTING BOARD // FOLLOW THE SIX-NODE SHUTDOWN TRACE",
        "info" if not alt_ending_security_complete else "success", 3.6,
    )


def _alt_ending_waypoint_target():
    """Return the world-space target for the next final-ending objective, or None."""
    if alt_ending_open or is_game_paused:
        return None
    if echo_phase5_state in ECHO_PHASE5_MODAL_STATES:
        return None
    if alt_ending_page in ("exit_opening", "escape_runout", "escape_fade", "title", "glitch_out", "black", "ending"):
        return None
    # The module must be taken to the Main Lab workstation and connected before cameras
    # become the active final-sequence objective.
    if not echo_phase5_module_collected:
        return None
    if not alt_ending_camera_task_started:
        return ("terminal", _ALT_ENDING_TERMINAL_WAYPOINT_POS)
    if not alt_ending_security_complete:
        return ("security", _ALT_ENDING_SECURITY_WAYPOINT_POS)
    if not alt_ending_hacking_complete:
        return ("terminal", _ALT_ENDING_TERMINAL_WAYPOINT_POS)
    if not alt_ending_echo_deleted:
        return ("terminal", _ALT_ENDING_TERMINAL_WAYPOINT_POS)
    if not alt_ending_exit_open:
        return ("terminal", _ALT_ENDING_TERMINAL_WAYPOINT_POS)
    return None


def _alt_ending_update_waypoint(dt):
    """Reuse the game's spatial waypoint audio to reinforce the active ending objective."""
    global alt_ending_waypoint_ping_timer, alt_ending_waypoint_arrival_played
    global alt_ending_waypoint_target_name
    target_info = _alt_ending_waypoint_target()
    if target_info is None:
        alt_ending_waypoint_target_name = None
        alt_ending_waypoint_ping_timer = 0.0
        alt_ending_waypoint_arrival_played = False
        return
    target_name, target = target_info
    if target_name != alt_ending_waypoint_target_name:
        alt_ending_waypoint_target_name = target_name
        alt_ending_waypoint_ping_timer = 0.0
        alt_ending_waypoint_arrival_played = False
    alt_ending_waypoint_ping_timer = max(0.0, alt_ending_waypoint_ping_timer - max(0.0, float(dt)))
    dx = float(target.x) - float(camera.position.x)
    dy = float(target.y) - float(camera.position.y)
    dz = float(target.z) - float(camera.position.z)
    distance = math.sqrt(dx * dx + dy * dy + dz * dz)
    if distance <= 2.8 and not alt_ending_waypoint_arrival_played:
        try:
            spatial_audio.play_spatial("waypoint_arrival", target, camera,
                                       base_volume=0.78, max_dist=22.0)
        except Exception:
            pass
        alt_ending_waypoint_arrival_played = True
    elif distance <= 32.0 and not alt_ending_waypoint_arrival_played and alt_ending_waypoint_ping_timer <= 0.0:
        try:
            spatial_audio.play_spatial("waypoint_ping", target, camera,
                                       base_volume=0.84, max_dist=32.0)
        except Exception:
            pass
        alt_ending_waypoint_ping_timer = 1.0 + min(1.8, distance * 0.055)


def _draw_alt_ending_waypoint(time_val=0.0):
    """Draw a restrained cyan 3-D beacon over the current physical target."""
    target_info = _alt_ending_waypoint_target()
    if target_info is None:
        return
    _, target = target_info
    global _RENDER_MAX_VISIBLE_DISTANCE
    previous_max = _RENDER_MAX_VISIBLE_DISTANCE
    _RENDER_MAX_VISIBLE_DISTANCE = max(previous_max, 55.0)
    try:
        pulse = 0.72 + 0.28 * math.sin(float(time_val) * 3.7)
        draw_pbr_cylinder(Vector3(target.x, target.y - 0.32, target.z), 0.035, 0.62,
                          Color(0, 220, 255, 255), roughness=0.18, metallic=0.18,
                          emissive=Vector3(0.018, 0.62 * pulse, 0.92 * pulse))
        draw_pbr_sphere(target, 0.16, Color(55, 224, 255, 255), roughness=0.10, metallic=0.03,
                        emissive=Vector3(0.06, 1.08 * pulse, 1.55 * pulse))
        draw_pbr_sphere(Vector3(target.x, target.y + 0.025, target.z), 0.055,
                        Color(204, 249, 255, 255), roughness=0.08, metallic=0.0,
                        emissive=Vector3(0.15, 1.35 * pulse, 2.0 * pulse))
    finally:
        _RENDER_MAX_VISIBLE_DISTANCE = previous_max








def _alt_ending_handle_hotkeys():
    """Handle Escape for the ending UI; no debug, admin, or progression-bypass keys are registered."""
    global alt_ending_open, alt_ending_page, alt_ending_entry_source
    if alt_ending_open and (is_key_pressed(KEY_ESCAPE) or mobile_ctrl.btn_menu_pressed):
        protected_pages = ("deleting", "exit_opening", "ending", "escape_runout",
                           "escape_fade", "title", "glitch_out", "black")
        if alt_ending_page not in protected_pages:
            alt_ending_open = False
            alt_ending_page = "control"
            alt_ending_entry_source = "none"
            disable_cursor()
        return True
    return False


def _alt_ending_puzzle_is_active():
    return bool(alt_ending_open and alt_ending_page in ("security", "hack", "delete", "deleting"))


def _alt_ending_register_mistake(message, reset_after=0.0):
    """Apply a fair but forceful ECHO response after an incorrect player input."""
    global alt_ending_mistake_count, alt_ending_lockout_timer
    global alt_ending_flicker_timer, alt_ending_blackout_timer
    global alt_ending_interference_timer, alt_ending_interference_line, alt_ending_glitch_timer
    global alt_ending_interference_countdown
    alt_ending_mistake_count += 1
    # Each mistake gives ECHO a longer takeover window, capped so the puzzle remains completable.
    alt_ending_lockout_timer = max(alt_ending_lockout_timer,
                                   min(4.8, 2.0 + 0.34 * min(alt_ending_mistake_count, 8)))
    alt_ending_blackout_timer = max(alt_ending_blackout_timer, 0.62)
    alt_ending_flicker_timer = max(alt_ending_flicker_timer, 3.25)
    alt_ending_interference_line = "ECHO // INPUT CHANNEL SEALED // I AM RECLAIMING THE LAB"
    alt_ending_interference_timer = max(alt_ending_interference_timer, 3.5)
    alt_ending_glitch_timer = max(alt_ending_glitch_timer, 0.44)
    alt_ending_interference_countdown = min(alt_ending_interference_countdown, 3.2)
    _alt_ending_set_feedback(message, "error", max(3.0, reset_after))
    try:
        spatial_audio.play_ui("access_denied", volume=0.48)
    except Exception:
        pass


def _alt_ending_trigger_interference():
    """ECHO escalates between light failures, blackouts, and temporary remote lockouts."""
    global alt_ending_interference_timer, alt_ending_interference_line, alt_ending_glitch_timer
    global alt_ending_lockout_timer, alt_ending_flicker_timer, alt_ending_blackout_timer
    global alt_ending_interference_event_count
    stage_level = 0 if alt_ending_page == "security" else 1 if alt_ending_page == "hack" else 2
    alt_ending_interference_event_count += 1
    roll = random.random()
    # The facility AI escalates from lighting attacks to direct input denial. After each
    # third intrusion it attempts a lockout; stage three attacks are the most aggressive.
    force_lockout = alt_ending_interference_event_count % 3 == 0
    if force_lockout or roll > (0.62 - 0.08 * stage_level):
        duration = min(4.8, 2.25 + stage_level * 0.62 + min(alt_ending_mistake_count * 0.15, 1.05))
        alt_ending_lockout_timer = max(alt_ending_lockout_timer, duration)
        alt_ending_blackout_timer = max(alt_ending_blackout_timer, 0.42 + stage_level * 0.16)
        alt_ending_flicker_timer = max(alt_ending_flicker_timer, 3.0 + stage_level * 0.45)
        alt_ending_interference_line = "ECHO // LOCAL INPUT BUS SEIZED // REMOTE CONTROL RECLAIMING FACILITY"
        _alt_ending_set_feedback("ECHO HAS SEIZED THE INPUT BUS // WAIT FOR LOCAL FAILSAFE", "error", duration + 0.7)
    elif roll > 0.28:
        alt_ending_flicker_timer = max(alt_ending_flicker_timer, 3.0 + stage_level * 0.55)
        alt_ending_interference_line = "ECHO // LIGHTING BUS OVERRIDE // IMAGE BUFFER CORRUPTED"
        _alt_ending_set_feedback("FACILITY OVERRIDE // VISUAL SIGNAL DEGRADED", "warning", 3.0)
    else:
        alt_ending_blackout_timer = max(alt_ending_blackout_timer, 0.78 + stage_level * 0.18)
        alt_ending_flicker_timer = max(alt_ending_flicker_timer, 2.8 + stage_level * 0.25)
        alt_ending_interference_line = "ECHO // POWER BUS IS MINE. GIVE UP."
        _alt_ending_set_feedback("REMOTE POWER TAKEOVER // LOCAL LIGHTING FAILING", "warning", 3.0)
    alt_ending_interference_timer = max(alt_ending_interference_timer, 3.4)
    alt_ending_glitch_timer = max(alt_ending_glitch_timer, 0.42)
    try:
        spatial_audio.play_ui("breaker_blowout" if alt_ending_blackout_timer > 0.0 else "access_denied", volume=0.42)
    except Exception:
        pass


def _alt_ending_environment_light_factor():
    """Light level multiplier applied by the room renderers during active facility takeovers."""
    if not _alt_ending_puzzle_is_active():
        return 1.0
    if alt_ending_blackout_timer > 0.0:
        return 0.006
    if alt_ending_flicker_timer > 0.0:
        phase = int(float(globals().get("global_time", 0.0)) * 21.0) % 11
        if phase in (0, 1, 4, 8):
            return 0.012
        if phase in (2, 5, 9):
            return 0.075
        return 0.60
    return 1.0


def _alt_ending_screen_interference_strength():
    """Continuous strength for the real post-process interference, separate from UI text."""
    if not _alt_ending_puzzle_is_active():
        return 0.0
    flicker = min(1.0, max(0.0, float(globals().get("alt_ending_flicker_timer", 0.0))) / 3.6)
    blackout = min(1.0, max(0.0, float(globals().get("alt_ending_blackout_timer", 0.0))) * 1.35)
    glitch = min(0.75, max(0.0, float(globals().get("alt_ending_glitch_timer", 0.0))) * 1.8)
    lockout = 0.72 if float(globals().get("alt_ending_lockout_timer", 0.0)) > 0.0 else 0.0
    return max(0.0, min(1.0, max(flicker * 0.86, blackout, glitch, lockout)))


def _alt_ending_delete_sync_rect(panel=None):
    px, py, pw, ph = panel or _alt_ending_panel_rect()
    return (px + pw // 2 - 226, py + 542, 452, 46)


def _alt_ending_reset_delete_challenge(reason):
    """A bad safeguard, seed, or timed sync restarts Minigame 3 from its first safeguard."""
    global alt_ending_locks_disabled, alt_ending_delete_lock_step, alt_ending_delete_code_entry
    global alt_ending_delete_code_ok, alt_ending_delete_progress, alt_ending_delete_sync_step
    global alt_ending_delete_sync_window, alt_ending_timer, alt_ending_page
    alt_ending_locks_disabled = [False, False, False]
    alt_ending_delete_lock_step = 0
    alt_ending_delete_code_entry = []
    alt_ending_delete_code_ok = False
    alt_ending_delete_progress = 0.0
    alt_ending_delete_sync_step = 0
    alt_ending_delete_sync_window = 0.0
    alt_ending_timer = 0.0
    alt_ending_page = "delete"
    _alt_ending_register_mistake(reason + " // ALL SAFEGUARDS RESET", reset_after=3.8)


def _alt_ending_click_camera(node_index):
    global alt_ending_camera_disabled, alt_ending_camera_step, alt_ending_security_complete, alt_ending_page
    if alt_ending_page != "security" or alt_ending_security_complete:
        return
    if node_index < 0 or node_index >= len(alt_ending_camera_disabled):
        return
    if alt_ending_camera_disabled[node_index]:
        alt_ending_camera_disabled = [False] * len(_ALT_ENDING_CAMERA_ORDER)
        alt_ending_camera_step = 0
        _alt_ending_register_mistake("CAMERA ALREADY OFFLINE // ECHO RE-ARMED ALL SIX LINKS", reset_after=3.4)
        return
    if alt_ending_camera_step >= len(_ALT_ENDING_CAMERA_ORDER):
        return
    expected = _ALT_ENDING_CAMERA_ORDER[alt_ending_camera_step]
    if node_index != expected:
        alt_ending_camera_disabled = [False] * len(_ALT_ENDING_CAMERA_ORDER)
        alt_ending_camera_step = 0
        _alt_ending_register_mistake("TRACE COLLAPSE // NOISE ORDER WRONG // ALL SIX CAMERA LINKS RESET", reset_after=3.4)
        return
    alt_ending_camera_disabled[node_index] = True
    alt_ending_camera_step += 1
    if alt_ending_camera_step >= len(_ALT_ENDING_CAMERA_ORDER):
        alt_ending_security_complete = True
        alt_ending_page = "security_done"
        _alt_ending_set_feedback("SURVEILLANCE BUS ISOLATED // ALL CAMERAS OFFLINE", "success", 5.0)
    else:
        _alt_ending_set_feedback(f"CAM-{node_index + 1:02d} ISOLATED // {alt_ending_camera_step}/6 LINKS SECURED", "success", 1.7)


def _alt_ending_begin_hack_route(stage_index):
    global alt_ending_hack_stage, alt_ending_hack_path, alt_ending_hack_route_complete, alt_ending_page
    global alt_ending_timer, alt_ending_interference_countdown
    alt_ending_hack_stage = max(0, min(len(_ALT_ENDING_HACK_ROUTES) - 1, int(stage_index)))
    alt_ending_hack_path = [0]
    alt_ending_hack_route_complete = False
    alt_ending_page = "hack"
    alt_ending_timer = 0.0
    alt_ending_interference_countdown = 4.2
    _alt_ending_set_feedback(
        f"ROUTE {alt_ending_hack_stage + 1:02d} // ENTRY NODE ACQUIRED // TRACE WINDOW {int(_ALT_ENDING_HACK_LIMITS[alt_ending_hack_stage])}s",
        "warning", 2.8)


def _alt_ending_click_hack_node(node_index):
    global alt_ending_hack_path, alt_ending_hack_route_complete, alt_ending_hacking_complete, alt_ending_page
    if alt_ending_page != "hack" or alt_ending_hack_route_complete:
        return
    route = _ALT_ENDING_HACK_ROUTES[alt_ending_hack_stage]
    expected_index = len(alt_ending_hack_path)
    if expected_index >= len(route):
        return
    expected = route[expected_index]
    if node_index != expected:
        alt_ending_hack_path = [0]
        alt_ending_hack_route_complete = False
        _alt_ending_register_mistake("ROUTE CORRUPTED // INCORRECT NODE // CURRENT STAGE RESET TO ENTRY", reset_after=3.4)
        return
    alt_ending_hack_path.append(node_index)
    if len(alt_ending_hack_path) >= len(route):
        alt_ending_hack_route_complete = True
        _alt_ending_set_feedback(f"ROUTE {alt_ending_hack_stage + 1:02d} VERIFIED // DATA PATH STABLE", "success", 3.0)
    else:
        _alt_ending_set_feedback(f"NODE {node_index:02d} CONNECTED // {len(alt_ending_hack_path)}/{len(route)} NODES", "info", 1.1)


def _alt_ending_click_delete_lock(lock_index):
    global alt_ending_delete_lock_step
    if alt_ending_page != "delete" or alt_ending_echo_deleted:
        return
    if lock_index < 0 or lock_index >= len(alt_ending_locks_disabled):
        return
    if alt_ending_locks_disabled[lock_index]:
        _alt_ending_reset_delete_challenge("DISABLED SAFEGUARD TOUCHED AGAIN // ECHO RE-ARMED THE INTERLOCKS")
        return
    if alt_ending_delete_lock_step >= len(_ALT_ENDING_DELETE_LOCK_ORDER):
        return
    expected = _ALT_ENDING_DELETE_LOCK_ORDER[alt_ending_delete_lock_step]
    if lock_index != expected:
        _alt_ending_reset_delete_challenge("SAFEGUARD ORDER REJECTED // ECHO RECLAIMED THE INTERLOCKS")
        return
    alt_ending_locks_disabled[lock_index] = True
    alt_ending_delete_lock_step += 1
    if alt_ending_delete_lock_step >= len(_ALT_ENDING_DELETE_LOCK_ORDER):
        _alt_ending_set_feedback("ALL SAFEGUARDS DISABLED // DERIVE THE SEED FROM THE VERIFIED CCTV TRACE AND ROUTE PHASES", "success", 4.0)
    else:
        expected_name = _ALT_ENDING_DELETE_LOCK_NAMES[_ALT_ENDING_DELETE_LOCK_ORDER[alt_ending_delete_lock_step]]
        _alt_ending_set_feedback(f"{_ALT_ENDING_DELETE_LOCK_NAMES[lock_index]} BYPASSED // NEXT: {expected_name}", "success", 2.0)


def _alt_ending_press_delete_digit(digit):
    global alt_ending_delete_code_entry, alt_ending_delete_code_ok
    if alt_ending_page != "delete" or not all(alt_ending_locks_disabled) or alt_ending_delete_code_ok:
        return
    digit = int(digit)
    if digit < 1 or digit > 9:
        return
    alt_ending_delete_code_entry.append(digit)
    if len(alt_ending_delete_code_entry) >= len(_ALT_ENDING_DELETE_CODE):
        if tuple(alt_ending_delete_code_entry) == _ALT_ENDING_DELETE_CODE:
            alt_ending_delete_code_ok = True
            _alt_ending_set_feedback("TERMINATION SEED ACCEPTED // CONFIRM THE DELETION", "success", 3.2)
        else:
            _alt_ending_reset_delete_challenge("TERMINATION SEED REJECTED // ECHO RESTORED ITS SAFEGUARDS")


def _alt_ending_handle_mouse():
    global alt_ending_open, alt_ending_page, alt_ending_entry_source, alt_ending_hacking_complete
    global alt_ending_hack_stage, alt_ending_hack_route_complete, alt_ending_timer
    global alt_ending_delete_code_entry, alt_ending_delete_code_ok, alt_ending_exit_open
    global alt_ending_delete_sync_step, alt_ending_delete_sync_window, alt_ending_interference_line
    global should_quit
    if not alt_ending_open or not is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
        return
    # ECHO temporarily disables the input bus during an active remote-lockout attempt.
    if alt_ending_lockout_timer > 0.0:
        return
    mouse = get_mouse_position()
    mx, my = float(mouse.x), float(mouse.y)
    panel = _alt_ending_panel_rect()
    px, py, pw, ph = panel
    back_rect = _alt_ending_back_rect(panel)
    close_rect = _alt_ending_button_rect(panel)

    if alt_ending_page == "deleting":
        if alt_ending_delete_sync_window > 0.0:
            x, y, w, h = _alt_ending_delete_sync_rect(panel)
            if x <= mx <= x + w and y <= my <= y + h:
                alt_ending_delete_sync_step += 1
                alt_ending_delete_sync_window = 0.0
                alt_ending_interference_line = "LOCAL LINK RESTORED // ECHO CONTROL REJECTED"
                _alt_ending_set_feedback(
                    f"LOCAL SYNC {alt_ending_delete_sync_step}/4 VERIFIED // KEEP THE TERMINATION LINK OPEN",
                    "success", 1.4)
                try:
                    spatial_audio.play_ui("access_granted", volume=0.38)
                except Exception:
                    pass
            else:
                _alt_ending_reset_delete_challenge("INVALID SYNC INPUT // TERMINATION CHANNEL RESET")
            return
        # During deletion, the only valid click is the time-limited local-sync button.
        return

    if alt_ending_page == "control":
        for idx, rect in enumerate(_alt_ending_control_rects(panel)):
            x, y, w, h = rect
            if not (x <= mx <= x + w and y <= my <= y + h):
                continue
            if idx == 0:
                if alt_ending_security_complete:
                    _alt_ending_set_feedback("SURVEILLANCE ALREADY DISABLED // ALL SIX FEEDS OFFLINE", "success", 2.2)
                else:
                    _alt_ending_set_feedback("GO TO THE SECURITY ROOM // USE THE PHYSICAL SURVEILLANCE MAP BOARD TO START MINIGAME 1", "warning", 3.8)
            elif idx == 1:
                if not alt_ending_security_complete:
                    _alt_ending_set_feedback("ACCESS DENIED // DISABLE SURVEILLANCE FIRST", "error", 2.6)
                elif alt_ending_hacking_complete:
                    _alt_ending_set_feedback("ADMINISTRATIVE ACCESS ALREADY GRANTED", "success", 2.0)
                else:
                    _alt_ending_begin_hack_route(0)
            elif idx == 2:
                if not alt_ending_security_complete or not alt_ending_hacking_complete:
                    _alt_ending_set_feedback("ECHO CONTROL LOCKED // SECURITY + ADMIN ACCESS REQUIRED", "error", 2.7)
                elif alt_ending_echo_deleted:
                    _alt_ending_set_feedback("ECHO PROCESS ALREADY TERMINATED", "success", 2.0)
                else:
                    alt_ending_page = "delete"
                    alt_ending_timer = 0.0
                    alt_ending_interference_countdown = 4.3
                    _alt_ending_set_feedback("TERMINATION INTERFACE OPEN // ECHO IS RESISTING", "warning", 2.8)
            elif idx == 3:
                if not alt_ending_echo_deleted:
                    _alt_ending_set_feedback("MAIN EXIT LOCKED // TERMINATE ECHO FIRST", "error", 2.6)
                else:
                    _alt_ending_begin_exit_cinematic()
            return
        if mx >= close_rect[0] and my >= close_rect[1] and mx <= close_rect[0] + close_rect[2] and my <= close_rect[1] + close_rect[3]:
            alt_ending_open = False
            alt_ending_entry_source = "none"
            disable_cursor()
        return

    if alt_ending_page == "security":
        for idx, rect in enumerate(_alt_ending_security_rects(panel)):
            x, y, w, h = rect
            if x <= mx <= x + w and y <= my <= y + h:
                _alt_ending_click_camera(idx)
                try:
                    spatial_audio.play_ui("item_pickup" if alt_ending_camera_disabled[idx] else "access_denied", volume=0.34)
                except Exception:
                    pass
                return
        if back_rect[0] <= mx <= back_rect[0] + back_rect[2] and back_rect[1] <= my <= back_rect[1] + back_rect[3]:
            alt_ending_open = False
            alt_ending_page = "control"
            alt_ending_entry_source = "none"
            disable_cursor()
        return

    if alt_ending_page == "security_done":
        if close_rect[0] <= mx <= close_rect[0] + close_rect[2] and close_rect[1] <= my <= close_rect[1] + close_rect[3]:
            alt_ending_open = False
            alt_ending_page = "control"
            alt_ending_entry_source = "none"
            disable_cursor()
        return

    if alt_ending_page == "hack":
        for idx, rect in enumerate(_alt_ending_hack_node_rects(panel)):
            x, y, w, h = rect
            if x <= mx <= x + w and y <= my <= y + h:
                _alt_ending_click_hack_node(idx)
                try:
                    spatial_audio.play_ui("item_pickup" if idx in alt_ending_hack_path else "access_denied", volume=0.30)
                except Exception:
                    pass
                return
        if alt_ending_hack_route_complete and close_rect[0] <= mx <= close_rect[0] + close_rect[2] and close_rect[1] <= my <= close_rect[1] + close_rect[3]:
            if alt_ending_hack_stage + 1 < len(_ALT_ENDING_HACK_ROUTES):
                _alt_ending_begin_hack_route(alt_ending_hack_stage + 1)
            else:
                alt_ending_hacking_complete = True
                alt_ending_page = "hack_done"
                _alt_ending_set_feedback("CENTRAL COMPUTER ACCEPTED // ADMIN ACCESS GRANTED", "success", 4.5)
        if back_rect[0] <= mx <= back_rect[0] + back_rect[2] and back_rect[1] <= my <= back_rect[1] + back_rect[3]:
            alt_ending_page = "control"
        return

    if alt_ending_page == "hack_done":
        if close_rect[0] <= mx <= close_rect[0] + close_rect[2] and close_rect[1] <= my <= close_rect[1] + close_rect[3]:
            alt_ending_page = "control"
        return

    if alt_ending_page == "delete":
        for idx, rect in enumerate(_alt_ending_delete_lock_rects(panel)):
            x, y, w, h = rect
            if x <= mx <= x + w and y <= my <= y + h and not all(alt_ending_locks_disabled):
                _alt_ending_click_delete_lock(idx)
                try:
                    spatial_audio.play_ui("item_pickup" if alt_ending_locks_disabled[idx] else "access_denied", volume=0.32)
                except Exception:
                    pass
                return
        if all(alt_ending_locks_disabled):
            digit_rects, clear_rect, confirm_rect = _alt_ending_delete_keypad_rects(panel)
            for digit, rect in digit_rects.items():
                x, y, w, h = rect
                if x <= mx <= x + w and y <= my <= y + h:
                    _alt_ending_press_delete_digit(digit)
                    try:
                        spatial_audio.play_ui("keypad_beep", volume=0.32)
                    except Exception:
                        pass
                    return
            if clear_rect[0] <= mx <= clear_rect[0] + clear_rect[2] and clear_rect[1] <= my <= clear_rect[1] + clear_rect[3]:
                alt_ending_delete_code_entry = []
                alt_ending_delete_code_ok = False
                _alt_ending_set_feedback("TERMINATION SEED ENTRY CLEARED", "info", 1.6)
                return
            if confirm_rect[0] <= mx <= confirm_rect[0] + confirm_rect[2] and confirm_rect[1] <= my <= confirm_rect[1] + confirm_rect[3]:
                if alt_ending_delete_code_ok:
                    alt_ending_page = "deleting"
                    alt_ending_timer = 0.0
                    alt_ending_delete_progress = 0.0
                    alt_ending_delete_sync_step = 0
                    alt_ending_delete_sync_window = 0.0
                    alt_ending_interference_countdown = 999.0
                    _alt_ending_set_feedback("TERMINATION REQUEST ACCEPTED // HOLD THE LINK", "warning", 3.0)
                else:
                    _alt_ending_set_feedback("TERMINATION BLOCKED // VALIDATE THE FOUR-DIGIT DERIVED SEED", "error", 2.4)
                return
        if back_rect[0] <= mx <= back_rect[0] + back_rect[2] and back_rect[1] <= my <= back_rect[1] + back_rect[3]:
            alt_ending_page = "control"
        return

    if alt_ending_page in ("deleted", "security_done", "hack_done"):
        if close_rect[0] <= mx <= close_rect[0] + close_rect[2] and close_rect[1] <= my <= close_rect[1] + close_rect[3]:
            if alt_ending_page == "deleted":
                # The deletion confirmation now leads straight into the exit cinematic:
                # the player explicitly opens the physical Main Exit, then watches it slide apart.
                _alt_ending_begin_exit_cinematic()
            else:
                alt_ending_page = "control"
        return

    if alt_ending_page == "ending":
        return_lab = (px + pw // 2 - 222, py + ph - 96, 205, 46)
        exit_game = (px + pw // 2 + 17, py + ph - 96, 205, 46)
        for rect, action in ((return_lab, "return"), (exit_game, "quit")):
            x, y, w, h = rect
            if x <= mx <= x + w and y <= my <= y + h:
                if action == "quit":
                    should_quit = True
                else:
                    alt_ending_open = False
                    alt_ending_page = "control"
                    alt_ending_exit_open = False
                    disable_cursor()
                return


def _alt_ending_complete_deletion():
    global alt_ending_page, alt_ending_echo_deleted, alt_ending_timer
    global alt_ending_interference_timer, alt_ending_interference_countdown
    global alt_ending_glitch_timer, alt_ending_shutdown_step, alt_ending_delete_progress
    alt_ending_echo_deleted = True
    alt_ending_delete_progress = 1.0
    alt_ending_page = "deleted"
    alt_ending_timer = 0.0
    alt_ending_interference_timer = 0.0
    alt_ending_interference_countdown = 999.0
    alt_ending_glitch_timer = 0.0
    alt_ending_shutdown_step = 0
    # This build has no recorded ECHO voice asset. Stop text takeover/interference and black
    # the existing physical CRT using the already-loaded offline texture instead of inventing audio.
    try:
        globals()["echo_phase5_takeover_active"] = False
        globals()["echo_phase5_glitch_active"] = False
        globals()["echo_phase5_glitch_remaining"] = 0.0
        set_material_texture(terminal_screen_model.materials[0], MATERIAL_MAP_ALBEDO, tex_screen_dark)
        set_material_texture(echo_phase5_terminal_screen_model.materials[0], MATERIAL_MAP_ALBEDO, tex_screen_dark)
        spatial_audio.play_ui("switch_clunk", volume=0.42)
    except Exception:
        pass
    _alt_ending_set_feedback("ECHO DELETED // MONITOR OFFLINE // CONTROL BUS QUIET", "success", 5.0)


def _alt_ending_exit_open_progress():
    """Opening progress is zero until the camera is aimed at the closed exit."""
    if alt_ending_page != "exit_opening":
        return 1.0 if (alt_ending_exit_open or alt_ending_page in
                        ("escape_runout", "escape_fade", "title", "glitch_out", "black")) else 0.0
    elapsed = float(alt_ending_timer) - float(alt_ending_exit_aim_duration)
    return max(0.0, min(1.0, elapsed / max(0.1, float(alt_ending_exit_open_duration))))


def _alt_ending_exit_door_amount():
    """Return the eased opening amount for the visible Main Exit split-slide door."""
    if alt_ending_page == "exit_opening":
        progress = _alt_ending_exit_open_progress()
        return progress * progress * (3.0 - 2.0 * progress)
    if alt_ending_exit_open or alt_ending_page in ("escape_runout", "escape_fade", "title", "glitch_out", "black"):
        return 1.0
    return 0.0


def _alt_ending_begin_exit_cinematic():
    """Begin a staged first-person exit cinematic: aim, open, hold, sprint, fade, title."""
    global alt_ending_open, alt_ending_page, alt_ending_timer, alt_ending_exit_open
    global alt_ending_exit_cam_start_pos, alt_ending_exit_cam_start_target, alt_ending_exit_sound_played
    global alt_ending_run_start_pos, alt_ending_run_start_target, alt_ending_run_step_timer
    alt_ending_open = True
    alt_ending_page = "exit_opening"
    alt_ending_timer = 0.0
    alt_ending_exit_open = False
    alt_ending_exit_sound_played = False
    alt_ending_exit_cam_start_pos = (float(camera.position.x), float(camera.position.y), float(camera.position.z))
    alt_ending_exit_cam_start_target = (float(camera.target.x), float(camera.target.y), float(camera.target.z))
    alt_ending_run_start_pos = None
    alt_ending_run_start_target = None
    alt_ending_run_step_timer = 0.0
    disable_cursor()
    _alt_ending_set_feedback("MAIN EXIT RELAY ACCEPTED // CAMERA LOCKING ON EGRESS", "info", 2.8)
    try:
        spatial_audio.play_ui("switch_clunk", volume=0.54)
    except Exception:
        pass


def draw_main_exit_door(time_val=0.0, open_amount=0.0):
    """Detailed low-poly Main Lab exit door with animated split leaves and readable signage."""
    p = max(0.0, min(1.0, float(open_amount)))
    pulse = 0.56 + 0.44 * math.sin(float(time_val) * 3.2)
    z_frame = -18.00
    z_face = -17.73

    # Keep the portal genuinely open during the cinematic. The outdoor approach scene is
    # rendered behind this door every frame; do not place a full-size black backing or a
    # dark tunnel in the gap, as either hides the road until the camera runs past the threshold.
    # Only retain a recessed black backing while the leaves are fully closed.
    if p <= 0.001:
        draw_pbr_box(Vector3(0.0, 2.40, -18.18), Vector3(6.14, 4.82, 0.28),
                     Color(4, 7, 10, 255), roughness=0.95, metallic=0.10)

    # Heavy frame, inner steel reveal, header and floor sill.
    for side in (-1.0, 1.0):
        x = side * 3.08
        draw_pbr_box(Vector3(x, 2.47, z_frame), Vector3(0.38, 4.98, 0.76),
                     Color(22, 28, 33, 255), roughness=0.45, metallic=0.82)
        draw_pbr_box(Vector3(x - side * 0.12, 2.46, z_face + 0.17), Vector3(0.075, 4.54, 0.07),
                     Color(91, 107, 116, 255), roughness=0.38, metallic=0.80)
        draw_pbr_box(Vector3(x - side * 0.20, 2.42, z_face + 0.16), Vector3(0.045, 4.30, 0.06),
                     Color(27, 173, 193, 255), roughness=0.22, metallic=0.25,
                     emissive=Vector3(0.0, 0.10 * pulse, 0.16 * pulse))
        # Ochre safety band on the jamb (kept muted to match the abandoned-lab palette).
        draw_pbr_box(Vector3(x - side * 0.20, 0.83, z_face + 0.16), Vector3(0.12, 0.34, 0.055),
                     Color(151, 105, 34, 255), roughness=0.65, metallic=0.24)
        # Frame fasteners provide scale and an industrial manufactured silhouette.
        for bolt_y in (0.48, 1.45, 3.40, 4.43):
            draw_pbr_sphere(Vector3(x - side * 0.08, bolt_y, z_face + 0.15), 0.035,
                            Color(105, 119, 124, 255), roughness=0.25, metallic=0.92)

    draw_pbr_box(Vector3(0.0, 4.92, z_frame), Vector3(6.54, 0.48, 0.78),
                 Color(18, 24, 29, 255), roughness=0.44, metallic=0.84)
    draw_pbr_box(Vector3(0.0, 4.67, z_face + 0.17), Vector3(5.92, 0.065, 0.08),
                 Color(82, 102, 112, 255), roughness=0.35, metallic=0.82)
    draw_pbr_box(Vector3(0.0, 0.095, z_frame), Vector3(6.18, 0.19, 0.92),
                 Color(20, 26, 30, 255), roughness=0.38, metallic=0.88)
    draw_pbr_box(Vector3(0.0, 0.205, z_face + 0.19), Vector3(5.86, 0.035, 0.07),
                 Color(82, 91, 96, 255), roughness=0.48, metallic=0.74)

    # Door leaves slide outward from the centre and remain visible as real, thick metal panels.
    leaf_width = 2.86
    leaf_height = 4.38
    slide = 3.02 * p
    for side in (-1.0, 1.0):
        cx = side * (leaf_width * 0.5 - 0.005 + slide)
        draw_pbr_box(Vector3(cx, 2.23, -17.88), Vector3(leaf_width, leaf_height, 0.30),
                     Color(32, 41, 48, 255), roughness=0.48, metallic=0.78)
        draw_pbr_box(Vector3(cx, 2.23, z_face), Vector3(leaf_width - 0.12, leaf_height - 0.15, 0.08),
                     Color(48, 58, 65, 255), roughness=0.55, metallic=0.72)
        # Tall inset plate, thick vertical edges and horizontal structural ribs.
        draw_pbr_box(Vector3(cx, 2.30, z_face + 0.045), Vector3(leaf_width - 0.55, 2.73, 0.035),
                     Color(27, 34, 40, 255), roughness=0.60, metallic=0.62)
        for ox in (-1.22, -0.78, 0.78, 1.22):
            draw_pbr_box(Vector3(cx + ox, 2.26, z_face + 0.060), Vector3(0.045, 4.04, 0.035),
                         Color(80, 95, 103, 255), roughness=0.40, metallic=0.86)
        for yy in (0.48, 1.16, 3.31, 3.93):
            draw_pbr_box(Vector3(cx, yy, z_face + 0.060), Vector3(leaf_width - 0.20, 0.065, 0.04),
                         Color(82, 96, 104, 255), roughness=0.40, metallic=0.83)
        # Recessed handle/pull slot, no free-floating parts.
        draw_pbr_box(Vector3(cx - side * 0.20, 2.22, z_face + 0.050), Vector3(0.23, 0.60, 0.045),
                     Color(13, 18, 22, 255), roughness=0.62, metallic=0.48)
        draw_pbr_box(Vector3(cx - side * 0.20, 2.22, z_face + 0.085), Vector3(0.055, 0.43, 0.035),
                     Color(126, 139, 145, 255), roughness=0.25, metallic=0.94)
        # Alternating hazard blocks along each lower edge.
        for stripe_i in range(8):
            sx = cx - 1.18 + stripe_i * 0.337
            stripe_col = Color(158, 111, 39, 255) if stripe_i % 2 == 0 else Color(20, 25, 29, 255)
            draw_pbr_box(Vector3(sx, 0.61, z_face + 0.08), Vector3(0.26, 0.13, 0.028),
                         stripe_col, roughness=0.72, metallic=0.28)
        for bx in (-1.28, 1.28):
            for by in (0.35, 4.14):
                draw_pbr_sphere(Vector3(cx + bx, by, z_face + 0.055), 0.026,
                                Color(121, 133, 139, 255), roughness=0.25, metallic=0.92)

    # Compact framed placard mounted to the header. Its size is intentionally much smaller
    # than the door leaves so approaching the exit cannot turn the sign into a giant flat slab.
    draw_pbr_box(Vector3(0.0, 4.92, -17.535), Vector3(3.16, 0.285, 0.075),
                 Color(9, 16, 21, 255), roughness=0.40, metallic=0.72)
    draw_pbr_box(Vector3(0.0, 5.060, -17.486), Vector3(3.10, 0.018, 0.012),
                 Color(62, 173, 188, 255), roughness=0.30, metallic=0.45,
                 emissive=Vector3(0.0, 0.026 * pulse, 0.038 * pulse))
    draw_pbr_box(Vector3(0.0, 4.780, -17.486), Vector3(3.10, 0.018, 0.012),
                 Color(62, 173, 188, 255), roughness=0.30, metallic=0.45,
                 emissive=Vector3(0.0, 0.026 * pulse, 0.038 * pulse))
    try:
        draw_model_ex(DOOR_LABEL_MODELS["main_exit"], Vector3(0.0, 4.92, -17.474),
                      Vector3(1.0, 0.0, 0.0), 90.0, Vector3(1.0, 1.0, 1.0), WHITE)
    except Exception:
        pass
    for i, col in enumerate((Color(37, 207, 224, 255),
                             Color(184, 132, 42, 255),
                             Color(37, 207, 224, 255))):
        light_col = col if p < 0.99 else Color(65, 226, 155, 255)
        glow = Vector3(0.0, 0.11 * pulse, 0.16 * pulse) if i != 1 else Vector3(0.12 * pulse, 0.055 * pulse, 0.0)
        draw_pbr_sphere(Vector3(-0.32 + i * 0.32, 4.76, -17.50), 0.055,
                        light_col, roughness=0.18, metallic=0.15, emissive=glow)


def _alt_ending_update(dt):
    global alt_ending_timer, alt_ending_delete_progress, alt_ending_page
    global alt_ending_feedback_timer, alt_ending_interference_countdown
    global alt_ending_interference_timer, alt_ending_interference_line, alt_ending_glitch_timer
    global alt_ending_open, alt_ending_exit_open
    global alt_ending_lockout_timer, alt_ending_flicker_timer, alt_ending_blackout_timer
    global alt_ending_delete_sync_step, alt_ending_delete_sync_window
    global alt_ending_run_start_pos, alt_ending_run_start_target, alt_ending_run_duration, alt_ending_run_step_timer
    global alt_ending_exit_cam_start_pos, alt_ending_exit_cam_start_target, alt_ending_exit_sound_played
    global camera
    dt = max(0.0, min(float(dt), 0.05))
    if alt_ending_feedback_timer > 0.0:
        alt_ending_feedback_timer = max(0.0, alt_ending_feedback_timer - dt)
    if alt_ending_interference_timer > 0.0:
        alt_ending_interference_timer = max(0.0, alt_ending_interference_timer - dt)
    if alt_ending_glitch_timer > 0.0:
        alt_ending_glitch_timer = max(0.0, alt_ending_glitch_timer - dt)
    if alt_ending_lockout_timer > 0.0:
        alt_ending_lockout_timer = max(0.0, alt_ending_lockout_timer - dt)
        if alt_ending_lockout_timer <= 0.0 and _alt_ending_puzzle_is_active():
            # Recovery must report the preserved challenge state, not imply the puzzle reset.
            if alt_ending_page == "security":
                recovery = f"LOCAL FAILSAFE RESTORED // CAMERA TRACE PRESERVED {alt_ending_camera_step}/6"
            elif alt_ending_page == "hack":
                recovery = f"LOCAL FAILSAFE RESTORED // ROUTE {alt_ending_hack_stage + 1} PRESERVED {len(alt_ending_hack_path)-1}/{len(_ALT_ENDING_HACK_ROUTES[alt_ending_hack_stage])-1} HOPS"
            else:
                recovery = f"LOCAL FAILSAFE RESTORED // SAFEGUARDS PRESERVED {sum(1 for lock in alt_ending_locks_disabled if lock)}/3"
            _alt_ending_set_feedback(recovery, "success", 2.5)
    if alt_ending_flicker_timer > 0.0:
        alt_ending_flicker_timer = max(0.0, alt_ending_flicker_timer - dt)
    if alt_ending_blackout_timer > 0.0:
        alt_ending_blackout_timer = max(0.0, alt_ending_blackout_timer - dt)

    # Each final encounter has its own deadline. Crucially, ECHO cannot consume the
    # player's trace window while the input bus is physically locked: that previously caused
    # a correct click to arrive on the exact expiry frame and be mistaken for a wrong answer.
    if alt_ending_open and alt_ending_page in ("security", "hack", "delete"):
        stage_active = not (alt_ending_page == "hack" and alt_ending_hack_route_complete)
        input_bus_locked = alt_ending_lockout_timer > 0.0
        if stage_active and not input_bus_locked:
            alt_ending_timer += dt
            if alt_ending_page == "security":
                stage_limit = _ALT_ENDING_SECURITY_LIMIT
            elif alt_ending_page == "hack":
                stage_limit = _ALT_ENDING_HACK_LIMITS[min(2, max(0, alt_ending_hack_stage))]
            else:
                stage_limit = _ALT_ENDING_DELETE_LIMIT
            if alt_ending_timer >= stage_limit:
                if alt_ending_page == "security":
                    globals()["alt_ending_camera_disabled"] = [False] * len(_ALT_ENDING_CAMERA_ORDER)
                    globals()["alt_ending_camera_step"] = 0
                    alt_ending_timer = 0.0
                    _alt_ending_register_mistake("TRACE WINDOW EXPIRED // ECHO RE-ARMED ALL SIX CAMERA LINKS", reset_after=3.8)
                elif alt_ending_page == "hack":
                    _alt_ending_begin_hack_route(alt_ending_hack_stage)
                    _alt_ending_register_mistake("TRACE WINDOW EXPIRED // CENTRAL COMPUTER ROUTE REBUILT BY ECHO", reset_after=3.8)
                else:
                    _alt_ending_reset_delete_challenge("TERMINATION WINDOW EXPIRED // ECHO RESTORED EVERY SAFEGUARD")
                    return
            # A lockout is followed by a brief recovery gap, preventing an endless lockout
            # loop while still allowing ECHO to attack again before a long pause.
            if alt_ending_lockout_timer > 0.0:
                alt_ending_interference_countdown = max(alt_ending_interference_countdown, 1.35)
            else:
                alt_ending_interference_countdown -= dt
                if alt_ending_interference_countdown <= 0.0:
                    _alt_ending_trigger_interference()
                    alt_ending_interference_countdown = max(2.9, random.uniform(3.8, 5.2) - min(alt_ending_mistake_count * 0.09, 0.7))
    elif alt_ending_open and alt_ending_page == "deleting":
        # During the termination run ECHO's attacks are tied to the required sync prompts below.
        pass

    if alt_ending_page == "deleting":
        alt_ending_timer += dt
        # Four narrow recovery windows force the player to fight ECHO's takeover while
        # keeping the deletion channel alive. Each miss re-arms all three safeguards.
        sync_due = (0.82, 1.92, 3.02, 4.12)
        if alt_ending_delete_sync_step < len(sync_due):
            if alt_ending_delete_sync_window > 0.0:
                alt_ending_delete_sync_window = max(0.0, alt_ending_delete_sync_window - dt)
                if alt_ending_delete_sync_window <= 0.0:
                    _alt_ending_reset_delete_challenge("SYNC WINDOW MISSED // ECHO SEVERED YOUR TERMINATION LINK")
                    return
                # Pause deletion while an urgent local re-sync is required.
                alt_ending_interference_line = "ECHO // LINK COLLAPSE // REASSERT LOCAL CONTROL NOW"
                alt_ending_interference_timer = max(alt_ending_interference_timer, 0.2)
            elif alt_ending_timer >= sync_due[alt_ending_delete_sync_step]:
                alt_ending_delete_sync_window = 0.78
                alt_ending_blackout_timer = max(alt_ending_blackout_timer, 0.48)
                alt_ending_flicker_timer = max(alt_ending_flicker_timer, 2.15)
                alt_ending_interference_line = "ECHO // PURGE CHANNEL OVERRIDDEN // REASSERT LOCAL CONTROL"
                alt_ending_interference_timer = 1.7
                alt_ending_glitch_timer = 0.34
                _alt_ending_set_feedback("LINK FAILURE IMMINENT // REASSERT LOCAL CONTROL WITHIN 0.8 SECONDS", "error", 1.4)
        # Four successful local re-syncs are required; progress pauses while each prompt is live.
        if alt_ending_delete_sync_window <= 0.0:
            alt_ending_delete_progress = min(1.0, alt_ending_timer / 5.35)
        else:
            alt_ending_delete_progress = min(0.92, max(0.0, alt_ending_delete_progress))
        if 0.65 < alt_ending_timer < 4.2:
            if int(alt_ending_timer * 5.0) % 7 == 0:
                alt_ending_glitch_timer = max(alt_ending_glitch_timer, 0.055)
        if alt_ending_timer >= 5.35 and alt_ending_delete_sync_step >= 4 and alt_ending_delete_sync_window <= 0.0:
            _alt_ending_complete_deletion()

    elif alt_ending_page == "exit_opening":
        # STAGE 1: smoothly turn the camera toward the still-closed exit. The door amount
        # remains exactly zero during this aim beat, so the player sees the closed door first.
        alt_ending_timer += dt
        if alt_ending_exit_cam_start_pos is None:
            alt_ending_exit_cam_start_pos = (float(camera.position.x), float(camera.position.y), float(camera.position.z))
        if alt_ending_exit_cam_start_target is None:
            alt_ending_exit_cam_start_target = (float(camera.target.x), float(camera.target.y), float(camera.target.z))
        aim_p = max(0.0, min(1.0, alt_ending_timer / max(0.1, alt_ending_exit_aim_duration)))
        aim_eased = aim_p * aim_p * (3.0 - 2.0 * aim_p)
        start_target = alt_ending_exit_cam_start_target
        destination = alt_ending_exit_cam_target
        camera.target.x = start_target[0] + (destination[0] - start_target[0]) * aim_eased
        camera.target.y = start_target[1] + (destination[1] - start_target[1]) * aim_eased
        camera.target.z = start_target[2] + (destination[2] - start_target[2]) * aim_eased

        # STAGE 2: only after the camera is looking at the doorway do the heavy leaves slide.
        if (alt_ending_timer >= alt_ending_exit_aim_duration
                and not alt_ending_exit_sound_played):
            alt_ending_exit_sound_played = True
            try:
                spatial_audio.play_ui("door_slide", volume=0.66)
            except Exception:
                pass

        full_open_time = alt_ending_exit_aim_duration + alt_ending_exit_open_duration
        cinematic_total = full_open_time + alt_ending_exit_hold_duration
        if alt_ending_timer >= cinematic_total:
            alt_ending_exit_open = True
            alt_ending_open = True  # keep all gameplay input locked during the first-person cinematic
            alt_ending_page = "escape_runout"
            alt_ending_timer = 0.0
            alt_ending_run_start_pos = (float(camera.position.x), float(camera.position.y), float(camera.position.z))
            alt_ending_run_start_target = (float(camera.target.x), float(camera.target.y), float(camera.target.z))
            # The doorway is fully open and held before the player begins running. Fade in
            # only during the latter part of the sprint, then reveal the end card from black.
            run_distance = abs(-51.0 - alt_ending_run_start_pos[2])
            alt_ending_run_duration = max(4.4, min(5.4, run_distance / 10.0))
            alt_ending_run_step_timer = 0.0
            disable_cursor()

    elif alt_ending_page == "escape_runout":
        if alt_ending_run_start_pos is None:
            alt_ending_run_start_pos = (float(camera.position.x), float(camera.position.y), float(camera.position.z))
            alt_ending_run_start_target = (float(camera.target.x), float(camera.target.y), float(camera.target.z))
        alt_ending_timer += dt
        run_p = max(0.0, min(1.0, alt_ending_timer / max(0.1, alt_ending_run_duration)))
        sx, sy, sz = alt_ending_run_start_pos
        end_x = max(-1.65, min(1.65, sx))
        end_z = -51.0
        # A visible sprint beat: accelerate out of the doorway, with controlled head bob
        # and a subtle lateral sway before the image is consumed by darkness.
        linear_p = run_p * run_p * (0.60 + 0.40 * run_p)
        cam_x = sx + (end_x - sx) * min(1.0, run_p * 1.16) + math.sin(alt_ending_timer * 8.5) * 0.035 * (1.0 - run_p)
        cam_z = sz + (end_z - sz) * linear_p
        bob = math.sin(alt_ending_timer * 18.0) * 0.035 * (1.0 - run_p * 0.35)
        # Follow the sloping exterior road once the investigator has cleared the Main Exit.
        if cam_z < -18.15:
            cam_y = _integrated_exit_pathway_eye_height(cam_z) + bob
        else:
            cam_y = max(1.55, min(1.95, sy)) + bob
        camera.position.x = cam_x
        camera.position.y = cam_y
        camera.position.z = cam_z

        # Turn toward the south exit before looking straight ahead through the open doorway.
        st = alt_ending_run_start_target or (sx, sy, sz + 1.0)
        dx0, dy0, dz0 = st[0] - sx, st[1] - sy, st[2] - sz
        d0 = math.sqrt(dx0 * dx0 + dy0 * dy0 + dz0 * dz0)
        if d0 < 0.001:
            dx0, dy0, dz0, d0 = 0.0, 0.0, 1.0, 1.0
        dx0, dy0, dz0 = dx0 / d0, dy0 / d0, dz0 / d0
        turn = max(0.0, min(1.0, alt_ending_timer / 0.72))
        turn = turn * turn * (3.0 - 2.0 * turn)
        dx = dx0 * (1.0 - turn)
        dy = dy0 * (1.0 - turn) + (-0.018) * turn
        dz = dz0 * (1.0 - turn) + (-1.0) * turn
        d = math.sqrt(dx * dx + dy * dy + dz * dz)
        if d < 0.001:
            dx, dy, dz, d = 0.0, 0.0, -1.0, 1.0
        camera.target.x = cam_x + (dx / d) * 12.0
        camera.target.y = cam_y + (dy / d) * 12.0
        camera.target.z = cam_z + (dz / d) * 12.0

        alt_ending_run_step_timer -= dt
        if alt_ending_run_step_timer <= 0.0 and run_p < 0.96:
            try:
                spatial_audio.play_ui("step_creepy_0" if int(alt_ending_timer * 3.0) % 2 == 0 else "step_creepy_1", volume=0.28)
            except Exception:
                pass
            alt_ending_run_step_timer = 0.34
        if run_p >= 1.0:
            camera.position.x = end_x
            camera.position.y = 1.8
            camera.position.z = end_z
            camera.target = Vector3(end_x, 1.62, end_z - 12.0)
            # The display has already faded fully to black during the run. Reveal the end title now.
            alt_ending_page = "title"
            alt_ending_timer = 0.0
            try:
                spatial_audio.play_ui("door_slide", volume=0.20)
            except Exception:
                pass

    elif alt_ending_page == "escape_fade":
        # Retained as a safe fallback for any state restored from an earlier build.
        alt_ending_timer += dt
        if alt_ending_timer >= 0.90:
            alt_ending_page = "title"
            alt_ending_timer = 0.0

    elif alt_ending_page == "title":
        alt_ending_timer += dt
        if alt_ending_timer >= alt_ending_title_duration:
            # Keep the title readable for its full hold, then let the entire display corrupt.
            alt_ending_page = "glitch_out"
            alt_ending_timer = 0.0

    elif alt_ending_page == "glitch_out":
        alt_ending_timer += dt
        if alt_ending_timer >= alt_ending_glitch_out_duration:
            alt_ending_page = "black"
            alt_ending_timer = 0.0

    elif alt_ending_page == "black":
        # The route has ended. Stay black after the title signal is lost.
        alt_ending_timer += dt


def _alt_ending_draw_button(rect, label, enabled=True, accent=None, font_size=16):
    x, y, w, h = [int(v) for v in rect]
    if accent is None:
        accent = Color(52, 205, 224, 255) if enabled else Color(67, 91, 99, 255)
    hovered = False
    if enabled:
        try:
            mp = get_mouse_position()
            hovered = x <= mp.x <= x + w and y <= mp.y <= y + h
        except Exception:
            hovered = False
    fill = (Color(13, 48, 59, 252) if hovered else Color(10, 31, 39, 246)) if enabled else Color(13, 20, 25, 244)
    edge = Color(min(255, accent.r + 28), min(255, accent.g + 28), min(255, accent.b + 20), 255) if hovered else accent
    draw_rectangle(x, y, w, h, fill)
    if hovered:
        draw_rectangle_lines(x - 1, y - 1, w + 2, h + 2, Color(87, 232, 240, 130))
        sweep = x + 7 + int((float(globals().get("global_time", 0.0)) * 110.0) % max(1, w - 14))
        draw_rectangle(sweep, y + 2, 2, max(1, h - 4), Color(114, 239, 242, 70))
    draw_rectangle_lines(x, y, w, h, edge)
    draw_rectangle(x + 1, y + 1, 4, max(1, h - 2), edge)
    text_color = Color(245, 253, 255, 255) if enabled else Color(111, 131, 138, 255)
    _alt_ending_draw_fit_text(label, x + 12, y + 2, w - 20, h - 4,
                              font_size, text_color, min_size=9, align="center", padding=2)


def _alt_ending_draw_panel_header(panel, title, subtitle):
    px, py, pw, ph = panel
    draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 2, 5, 190))
    draw_rectangle(px + 7, py + 9, pw, ph, Color(0, 0, 0, 150))
    draw_rectangle(px, py, pw, ph, Color(5, 13, 19, 252))
    # Quiet engineering-grid texture gives the terminal a layered instrument-panel feel.
    # It is drawn below all interaction cards, so it never reduces text contrast.
    grid_top = py + 67
    grid_bottom = py + ph - 10
    grid_left = px + 12
    grid_right = px + pw - 12
    grid_col = Color(30, 102, 118, 20)
    for gx in range(grid_left + 32, grid_right, 48):
        draw_line(gx, grid_top, gx, grid_bottom, grid_col)
    for gy in range(grid_top + 28, grid_bottom, 42):
        draw_line(grid_left, gy, grid_right, gy, grid_col)
    draw_rectangle_lines(px, py, pw, ph, Color(38, 184, 205, 255))
    draw_rectangle_lines(px + 5, py + 5, pw - 10, ph - 10, Color(30, 65, 77, 255))
    # Small corner registration brackets and edge diagnostics.
    bracket_col = Color(54, 203, 220, 160)
    for bx, by, sx, sy in ((px + 10, py + 10, 1, 1), (px + pw - 10, py + 10, -1, 1),
                           (px + 10, py + ph - 10, 1, -1), (px + pw - 10, py + ph - 10, -1, -1)):
        draw_line(bx, by, bx + sx * 18, by, bracket_col)
        draw_line(bx, by, bx, by + sy * 18, bracket_col)
    draw_rectangle(px + 1, py + 1, pw - 2, 64, Color(11, 29, 37, 255))
    draw_rectangle(px + 1, py + 62, pw - 2, 3, Color(37, 215, 232, 255))
    draw_text("THE LAST HOUR  //  PROJECT ECHO", px + 24, py + 10, 12, Color(114, 202, 215, 255))
    right_text = "FACILITY TERMINAL  //  LOCAL SESSION"
    right_w = measure_text(right_text, 11)
    title_region_w = max(100, pw - right_w - 68)
    _alt_ending_draw_fit_text(title, px + 24, py + 28, title_region_w, 31,
                              22, Color(236, 247, 249, 255), min_size=13)
    _alt_ending_draw_fit_text(right_text, px + pw - right_w - 22, py + 10,
                              right_w + 2, 21, 11,
                              Color(126, 160, 169, 255),
                              min_size=9, align="right")
    if subtitle:
        # Long stage instructions are wrapped inside the panel instead of being drawn as
        # a single oversize line. The two-line lane ends well before the timer/content row.
        _alt_ending_draw_wrapped(subtitle, px + 25, py + 72, pw - 50, 30,
                                 12 if pw < 760 else 13, Color(155, 182, 190, 255),
                                 min_size=9, max_lines=2, line_gap=1)


def _alt_ending_draw_feedback(panel):
    if alt_ending_feedback_timer <= 0.0:
        return
    px, py, pw, ph = panel
    palette = {
        "info": (Color(9, 27, 35, 246), Color(53, 182, 206, 255)),
        "success": (Color(7, 35, 27, 248), Color(65, 226, 155, 255)),
        "warning": (Color(42, 27, 8, 248), Color(238, 184, 71, 255)),
        "error": (Color(39, 10, 15, 248), Color(235, 74, 83, 255)),
    }
    fill, edge = palette.get(alt_ending_feedback_kind, palette["info"])
    x, y, w, h = px + 38, py + ph - 105, pw - 76, 32
    draw_rectangle(x, y, w, h, fill)
    draw_rectangle_lines(x, y, w, h, edge)
    _alt_ending_draw_fit_text(alt_ending_feedback, x + 10, y + 2, w - 20, h - 4,
                              14 if len(alt_ending_feedback) <= 70 else 12,
                              edge, min_size=9, align="left", padding=1)


def _alt_ending_draw_waveform(x, y, width, height, accent, seed=0, now=0.0, intensity=1.0):
    """Compact animated signal trace used by the final terminal's instrument panels."""
    x, y, width, height = int(x), int(y), max(8, int(width)), max(6, int(height))
    draw_line(x, y + height // 2, x + width, y + height // 2, Color(42, 86, 96, 170))
    points = 22
    previous = None
    amp = max(1.0, (height * 0.38) * max(0.10, min(1.3, float(intensity))))
    for i in range(points + 1):
        pxv = x + int(width * i / points)
        phase = (i / points) * math.pi * 4.0 + float(now) * (2.0 + seed * 0.12) + seed * 1.71
        val = math.sin(phase) * 0.62 + math.sin(phase * 2.37 + seed) * 0.22
        pyv = y + height // 2 - int(val * amp)
        pyv = max(y + 1, min(y + height - 1, pyv))
        if previous is not None:
            draw_line(previous[0], previous[1], pxv, pyv, accent)
        previous = (pxv, pyv)


def _alt_ending_draw_telemetry_card(rect, title, rows, accent, seed=0, now=0.0, meter=0.5,
                                     footer="LIVE TELEMETRY"):
    """Draw a compact technical side-console with contained readouts and a signal trace."""
    x, y, w, h = [int(v) for v in rect]
    if w < 118 or h < 150:
        return
    meter = max(0.0, min(1.0, float(meter)))
    draw_rectangle(x, y, w, h, Color(5, 18, 25, 248))
    draw_rectangle_lines(x, y, w, h, Color(37, 99, 112, 255))
    draw_rectangle(x + 1, y + 1, w - 2, 3, accent)
    draw_rectangle(x + 10, y + 11, 3, 20, accent)
    _alt_ending_draw_fit_text(title, x + 20, y + 9, w - 31, 22, 12,
                              Color(223, 240, 243, 255), min_size=8)
    draw_circle(x + w - 13, y + 20, 3, accent)
    draw_line(x + 10, y + 35, x + w - 10, y + 35, Color(41, 77, 87, 255))
    row_y = y + 43
    row_gap = 26 if len(rows) >= 4 else 30
    label_w = max(48, int(w * 0.46))
    for idx, row in enumerate(rows[:4]):
        label, value = row[0], row[1]
        value_color = row[2] if len(row) > 2 else accent
        ry = row_y + idx * row_gap
        _alt_ending_draw_fit_text(label, x + 10, ry, label_w, 15, 9,
                                  Color(120, 158, 167, 255), min_size=7)
        _alt_ending_draw_fit_text(value, x + 10 + label_w, ry, w - label_w - 20, 15, 9,
                                  value_color, min_size=7, align="right")
        draw_line(x + 10, ry + 19, x + w - 10, ry + 19, Color(25, 52, 61, 230))
    wave_y = y + h - 63
    _alt_ending_draw_fit_text("SIGNAL TRACE", x + 10, wave_y - 15, w - 20, 12, 8,
                              Color(91, 137, 147, 255), min_size=7)
    _alt_ending_draw_waveform(x + 10, wave_y, w - 20, 25, accent, seed, now, 0.92)
    bar_x, bar_y, bar_w = x + 10, y + h - 27, w - 20
    draw_rectangle(bar_x, bar_y, bar_w, 5, Color(20, 38, 45, 255))
    draw_rectangle(bar_x, bar_y, int(bar_w * meter), 5, accent)
    draw_rectangle_lines(bar_x, bar_y, bar_w, 5, Color(46, 81, 90, 255))
    _alt_ending_draw_fit_text(footer, x + 10, y + h - 18, w - 20, 12, 8,
                              Color(121, 155, 163, 255), min_size=7)


def _alt_ending_draw_status_tile(rect, index, title, value, detail, accent, progress, now=0.0):
    """Dashboard tile for the facility-control overview."""
    x, y, w, h = [int(v) for v in rect]
    progress = max(0.0, min(1.0, float(progress)))
    draw_rectangle(x, y, w, h, Color(7, 22, 29, 248))
    draw_rectangle_lines(x, y, w, h, Color(40, 79, 89, 255))
    draw_rectangle(x + 1, y + 1, 4, h - 2, accent)
    _alt_ending_draw_fit_text(f"SYS-{index:02d}  //  {title}", x + 13, y + 7, w - 24, 16, 9,
                              Color(133, 176, 184, 255), min_size=7)
    _alt_ending_draw_fit_text(value, x + 13, y + 27, w - 24, 20, 13,
                              accent, min_size=9)
    _alt_ending_draw_fit_text(detail, x + 13, y + 50, w - 24, 15, 9,
                              Color(176, 199, 203, 255), min_size=7)
    bx, by, bw = x + 13, y + h - 12, w - 26
    draw_rectangle(bx, by, bw, 4, Color(20, 38, 45, 255))
    draw_rectangle(bx, by, int(bw * progress), 4, accent)
    # Tiny active packet marker runs along each system's load bar.
    marker_x = bx + int(bw * ((now * (0.16 + index * 0.025)) % 1.0))
    draw_rectangle(marker_x, by - 2, 2, 8, Color(216, 249, 250, 180))


def _alt_ending_draw_overlay():
    """Single display-space UI pass; keeps all puzzles readable and avoids extra 3-D entities."""
    panel = _alt_ending_panel_rect()
    px, py, pw, ph = panel

    # During the physical door release, keep the actual doorway visible behind a compact status strip.
    if alt_ending_open and alt_ending_page == "exit_opening":
        draw_rectangle(0, SCREEN_HEIGHT - 126, SCREEN_WIDTH, 126, Color(1, 5, 9, 190))
        draw_line(0, SCREEN_HEIGHT - 126, SCREEN_WIDTH, SCREEN_HEIGHT - 126, Color(33, 178, 199, 255))
        caption = "MAIN EXIT // HYDRAULIC INTERLOCK RELEASE"
        _alt_ending_draw_fit_text(caption, 34, SCREEN_HEIGHT - 117, SCREEN_WIDTH - 68, 24,
                                  17, Color(224, 241, 245, 255), min_size=11)
        track_x, track_y, track_w = 34, SCREEN_HEIGHT - 69, max(120, SCREEN_WIDTH - 68)
        draw_rectangle(track_x, track_y, track_w, 12, Color(15, 26, 32, 240))
        open_p = _alt_ending_exit_open_progress()
        draw_rectangle(track_x, track_y, int(track_w * open_p), 12, Color(39, 181, 207, 255))
        draw_rectangle_lines(track_x, track_y, track_w, 12, Color(70, 114, 126, 255))
        _alt_ending_draw_fit_text(f"DOOR STATUS // OPENING  {int(open_p * 100):03d}%",
                                  track_x, track_y + 17, track_w, 18, 11,
                                  Color(117, 202, 218, 255), min_size=9)
        return

    # Scripted first-person run, fade and final title. No menus/HUD are drawn over these frames.
    if alt_ending_page == "escape_runout":
        # Show the open doorway and sprint first; only then let the image collapse to black.
        fade_start = alt_ending_run_duration * 0.80
        fade_duration = max(0.35, alt_ending_run_duration * 0.20)
        fade_p = max(0.0, min(1.0, (alt_ending_timer - fade_start) / fade_duration))
        fade = int(255 * (fade_p * fade_p * (3.0 - 2.0 * fade_p)))
        draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 0, 0, fade))
        return
    if alt_ending_page == "escape_fade":
        fade = max(0, min(255, int(255 * (alt_ending_timer / 0.90))))
        draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 0, 0, fade))
        return
    if alt_ending_page == "title":
        draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 0, 0, 255))
        title = "PROJECT ECHO"
        size = max(38, min(76, SCREEN_HEIGHT // 9))
        width = measure_text(title, size)
        x = (SCREEN_WIDTH - width) // 2
        y = (SCREEN_HEIGHT - size) // 2 - max(8, size // 8)
        fade_in = max(0.0, min(1.0, alt_ending_timer / 0.95))
        # Clean white title with a restrained silver halo: ominous, readable, and not triumphant.
        pulse = 0.94 + 0.06 * (0.5 + 0.5 * math.sin(alt_ending_timer * 1.8))
        title_alpha = max(0, min(255, int(245 * fade_in * pulse)))
        glitch_frame = (int(alt_ending_timer * 11.0) % 19 == 0 and alt_ending_timer > 0.85)
        jitter_x = (random.randint(-4, 4) if glitch_frame else 0)
        draw_text(title, x + 4, y + 5, size, Color(0, 0, 0, title_alpha))
        halo_alpha = int(title_alpha * 0.16)
        for ox, oy, mult in ((-3, 0, 0.70), (3, 0, 0.70), (0, -3, 0.56), (0, 3, 0.56),
                             (-2, -2, 0.40), (2, 2, 0.40), (-5, 0, 0.20), (5, 0, 0.20)):
            draw_text(title, x + ox + jitter_x, y + oy,
                      size, Color(178, 190, 200, int(halo_alpha * mult)))
        if glitch_frame:
            draw_text(title, x - 3, y + 1, size, Color(166, 174, 184, int(title_alpha * 0.48)))
        draw_text(title, x, y, size, Color(224, 229, 234, int(title_alpha * 0.96)))
        draw_text(title, x, y, size, Color(255, 255, 255, title_alpha))
        # Two fine, subdued white/silver rule lines ground the title without blue accents.
        line_half = min(260, SCREEN_WIDTH // 4)
        draw_line(SCREEN_WIDTH // 2 - line_half, y + size + 10,
                  SCREEN_WIDTH // 2 + line_half, y + size + 10,
                  Color(210, 218, 224, int(title_alpha * 0.48)))
        draw_line(SCREEN_WIDTH // 2 - line_half + 22, y + size + 12,
                  SCREEN_WIDTH // 2 + line_half - 34, y + size + 12,
                  Color(172, 180, 188, int(title_alpha * 0.20)))
        # Occasional small title tearing foreshadows the larger signal failure after the hold.
        if glitch_frame:
            band_y = max(0, min(SCREEN_HEIGHT - 3, y + random.randint(8, max(9, size - 8))))
            draw_rectangle(0, band_y, SCREEN_WIDTH, random.randint(1, 3), Color(205, 212, 219, 72))
            draw_text(title, x + random.randint(-8, 8), y + random.choice((-2, 1, 2)),
                      size, Color(218, 224, 230, int(title_alpha * 0.28)))
        subtitle = "THE END"
        sub_size = max(16, min(25, SCREEN_HEIGHT // 32))
        sub_w = measure_text(subtitle, sub_size)
        sub_y = y + size + max(24, size // 3)
        sub_x = (SCREEN_WIDTH - sub_w) // 2 + (1 if glitch_frame else 0)
        draw_text(subtitle, sub_x + 2, sub_y + 2, sub_size, Color(0, 0, 0, title_alpha))
        draw_text(subtitle, sub_x, sub_y, sub_size, Color(231, 234, 238, int(title_alpha * 0.96)))
        return

    if alt_ending_page == "glitch_out":
        # The entire end card loses synchronisation: horizontal tears, static streaks,
        # displaced title slices and blocks of corrupted signal ramp up before hard black.
        draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 0, 0, 255))
        duration = max(0.1, float(alt_ending_glitch_out_duration))
        progress = max(0.0, min(1.0, alt_ending_timer / duration))
        intensity = 0.42 + 0.68 * progress
        title = "PROJECT ECHO"
        size = max(38, min(76, SCREEN_HEIGHT // 9))
        title_w = measure_text(title, size)
        title_x = (SCREEN_WIDTH - title_w) // 2
        title_y = (SCREEN_HEIGHT - size) // 2 - max(8, size // 8)
        # Broken, jittering title copies rapidly desynchronise and then fade away.
        if progress < 0.82:
            title_alpha = int(245 * (1.0 - progress / 0.95))
            for copy_idx in range(1 + int(progress * 5)):
                off_x = random.randint(-int(9 + 34 * intensity), int(9 + 34 * intensity))
                off_y = random.randint(-int(3 + 9 * intensity), int(3 + 9 * intensity))
                grey = random.choice((178, 205, 232, 255))
                alpha = max(0, min(255, int(title_alpha * random.uniform(0.18, 0.52))))
                draw_text(title, title_x + off_x, title_y + off_y, size,
                          Color(grey, grey, grey, alpha))
            # A few harsh clipped-looking bars erase and displace sections of the lettering.
            for _ in range(4 + int(progress * 9)):
                band_y = max(0, min(SCREEN_HEIGHT - 2, title_y + random.randint(-8, size + 8)))
                band_h = random.randint(2, max(3, int(6 + 20 * intensity)))
                band_x = random.randint(0, max(0, SCREEN_WIDTH - 1))
                band_w = random.randint(max(1, SCREEN_WIDTH // 18), max(2, SCREEN_WIDTH // 2))
                draw_rectangle(band_x, band_y, min(band_w, SCREEN_WIDTH - band_x), band_h,
                               Color(0, 0, 0, random.randint(100, 245)))

        # Full-screen horizontal tears and static streaks. The corruption gets denser as it ends.
        tear_count = 11 + int(progress * 34)
        for _ in range(tear_count):
            band_y = random.randint(0, max(0, SCREEN_HEIGHT - 1))
            band_h = random.choice((1, 1, 2, 3, 5, 8, 13, 15))
            band_x = 0 if random.random() < 0.58 else random.randint(0, max(0, SCREEN_WIDTH - 1))
            max_w = SCREEN_WIDTH if band_x == 0 else max(1, SCREEN_WIDTH - band_x)
            min_bw = max(1, SCREEN_WIDTH // 24)
            band_w = random.randint(min(min_bw, max(1, max_w)), max(min_bw, max(1, max_w)))
            value = random.choice((78, 112, 148, 184, 218, 245))
            alpha = int(random.randint(34, 118) * intensity)
            draw_rectangle(band_x, band_y, min(band_w, SCREEN_WIDTH - band_x), band_h,
                           Color(value, value, value, min(190, alpha)))

        # Fine static points and scanline fragments sell the signal collapse without assets.
        for _ in range(36 + int(progress * 60)):
            sx = random.randint(0, max(0, SCREEN_WIDTH - 1))
            sy = random.randint(0, max(0, SCREEN_HEIGHT - 1))
            sw = random.randint(1, max(2, int(2 + 17 * intensity)))
            sh = random.choice((1, 1, 1, 2))
            shade = random.choice((150, 190, 220, 255))
            draw_rectangle(sx, sy, min(sw, SCREEN_WIDTH - sx), sh,
                           Color(shade, shade, shade, random.randint(30, 112)))

        # The final portion drops the remaining noise rapidly, ending on absolute black.
        if progress > 0.78:
            black_alpha = int(255 * ((progress - 0.78) / 0.22))
            draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT,
                           Color(0, 0, 0, max(0, min(255, black_alpha))))
        return

    if alt_ending_page == "black":
        draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 0, 0, 255))
        return

    if alt_ending_open and alt_ending_page == "ending":
        # A restrained black fade replaces the view without a bright flash.
        fade = min(255, int(255 * max(0.0, min(1.0, alt_ending_timer / 1.25))))
        draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 0, 0, fade))
        if alt_ending_timer >= 0.85:
            title = "THE LAST HOUR"
            tw = measure_text(title, 42)
            draw_text(title, (SCREEN_WIDTH - tw) // 2, SCREEN_HEIGHT // 2 - 120, 42,
                      Color(235, 244, 246, min(255, int((alt_ending_timer - 0.65) * 420))))
            message = "PROJECT ECHO — TERMINATION CONFIRMED"
            mw = measure_text(message, 21)
            draw_text(message, (SCREEN_WIDTH - mw) // 2, SCREEN_HEIGHT // 2 - 55, 21,
                      Color(66, 218, 224, min(255, int((alt_ending_timer - 0.65) * 420))))
            sub = "THE FACILITY IS SILENT. THE EXIT IS BEHIND YOU."
            sw = measure_text(sub, 13)
            draw_text(sub, (SCREEN_WIDTH - sw) // 2, SCREEN_HEIGHT // 2 - 16, 13,
                      Color(158, 178, 184, min(255, int((alt_ending_timer - 0.65) * 420))))
            if alt_ending_timer >= 1.55:
                _alt_ending_draw_button((px + pw // 2 - 222, py + ph - 96, 205, 46), "RETURN TO MAIN LAB", True)
                _alt_ending_draw_button((px + pw // 2 + 17, py + ph - 96, 205, 46), "EXIT GAME", True,
                                        Color(207, 91, 83, 255))
        return

    if not alt_ending_open:
        if alt_ending_exit_open and alt_ending_page == "exit_ready":
            msg = "MAIN EXIT RELEASED  //  FOLLOW THE SOUTH MAIN-LAB PASSAGE TO LEAVE"
            mw = min(SCREEN_WIDTH - 40, measure_text(msg, 15) + 40)
            mx = (SCREEN_WIDTH - mw) // 2
            my = SCREEN_HEIGHT - 92
