        _alt_ending_draw_fit_text("SORT THE SIX CORRECTED VALUES HIGH → LOW // ONE WRONG PICK RESETS ALL LINKS",
                                  px + 38, py + 137, max(140, pw - 320), 20, 11,
                                  Color(153, 184, 190, 255), min_size=9)
        for idx, rect in enumerate(_alt_ending_security_rects(panel)):
            x, y, w, h = [int(v) for v in rect]
            try:
                mp = get_mouse_position()
                hovered = x <= mp.x <= x + w and y <= mp.y <= y + h
            except Exception:
                hovered = False
            disabled = bool(alt_ending_camera_disabled[idx])
            edge = Color(63, 226, 154, 255) if disabled else Color(61, 88, 98, 255)
            fill = Color(8, 36, 29, 250) if disabled else Color(9, 24, 31, 250)
            if hovered and not disabled:
                edge = Color(78, 221, 231, 255)
                fill = Color(10, 37, 46, 255)
                draw_rectangle(x - 1, y - 1, w + 2, h + 2, Color(37, 199, 220, 35))
            draw_rectangle(x, y, w, h, fill)
            draw_rectangle_lines(x, y, w, h, edge)
            feed_x, feed_y = x + 7, y + 8
            feed_w = max(44, min(82, int(w * 0.32)))
            draw_rectangle(feed_x, feed_y, feed_w, h - 16,
                           Color(2, 10, 14, 255) if not disabled else Color(3, 20, 14, 255))
            # Static-feed scan lines stay in display-space and do not add scene geometry.
            for line_i in range(3):
                yy = feed_y + 15 + line_i * 22
                draw_line(feed_x + 5, yy, feed_x + feed_w - 5, yy,
                          Color(19, 83 + line_i * 8, 96 + line_i * 8, 255) if not disabled
                          else Color(30, 111, 75, 255))
            # Animated waveform makes each card read as a live digital CCTV feed.
            _alt_ending_draw_waveform(feed_x + 5, feed_y + 26, max(18, feed_w - 10), 18,
                                      Color(38, 173, 185, 210) if not disabled else Color(65, 226, 155, 210),
                                      idx + 2, float(globals().get("global_time", 0.0)),
                                      0.18 if disabled else 0.95)
            indicator_col = Color(63, 226, 154, 255) if disabled else Color(219, 73, 75, 255)
            draw_circle(feed_x + feed_w - 8, feed_y + 10, 3, indicator_col)
            text_x = feed_x + feed_w + 7
            text_w = max(38, x + w - text_x - 7)
            label_size = 13 if w < 220 else 16
            _alt_ending_draw_fit_text(f"CAM-{idx + 1:02d}", text_x, y + 7, text_w, 20,
                                      label_size, Color(236, 245, 247, 255), min_size=10)
            _alt_ending_draw_fit_text(f"RAW {_ALT_ENDING_CAMERA_NOISE[idx]:02d} dB",
                                      text_x, y + 29, text_w, 17, 11,
                                      Color(238, 196, 95, 255), min_size=9)
            cal = _ALT_ENDING_CAMERA_CALIBRATION[idx]
            cal_text = f"CAL {cal:+03d}  //  {'CUT' if disabled else 'LIVE'}"
            _alt_ending_draw_fit_text(cal_text, text_x, y + 49, text_w, 17, 10,
                                      edge, min_size=8)
            # Six-segment signal meter uses RAW amplitude only; it does not reveal corrected rank.
            meter_w = max(24, text_w - 4)
            meter_y = y + 72
            draw_rectangle(text_x, meter_y, meter_w, 5, Color(20, 37, 44, 255))
            raw_level = max(0.0, min(1.0, _ALT_ENDING_CAMERA_NOISE[idx] / 100.0))
            draw_rectangle(text_x, meter_y, int(meter_w * raw_level), 5,
                           Color(65, 226, 155, 255) if disabled else Color(48, 191, 206, 255))
        remaining = max(0.0, _ALT_ENDING_SECURITY_LIMIT - alt_ending_timer)
        _alt_ending_draw_fit_text(f"TRACE WINDOW  //  {remaining:04.1f}s",
                                  px + pw - 252, py + 111, 216, 20, 11,
                                  Color(238, 184, 71, 255), min_size=9, align="right", padding=2)
        # Persistent progress display means success is visible even after brief feedback fades.
