        for n1, n2 in zip(alt_ending_hack_path, alt_ending_hack_path[1:]):
            draw_line(centers[n1][0], centers[n1][1], centers[n2][0], centers[n2][1], Color(57, 221, 202, 255))
        for idx, rect in enumerate(nodes):
            x, y, w, h = [int(v) for v in rect]
            try:
                mp = get_mouse_position()
                hovered = x <= mp.x <= x + w and y <= mp.y <= y + h
            except Exception:
                hovered = False
            connected = idx in alt_ending_hack_path
            if connected:
                edge = Color(65, 226, 155, 255)
            elif idx == 0:
                edge = Color(65, 202, 222, 255)
            elif idx == 8:
                edge = Color(238, 184, 71, 255)
            else:
                edge = Color(52, 80, 89, 255)
            fill = Color(8, 47, 37, 255) if connected else Color(8, 26, 35, 255)
