        draw_text(f"ROUTE PROGRESS  {len(alt_ending_hack_path)}/{len(route)} NODES", track_x, track_y - 24, 12, Color(146, 181, 190, 255))
        draw_rectangle(track_x, track_y, track_w, 8, Color(21, 39, 46, 255))
        draw_rectangle(track_x, track_y, int(track_w * progress), 8, Color(57, 221, 202, 255))
