                accent_cyan = Color(75, 192, 199, 255)
                muted = Color(153, 174, 181, 255)
                panel_edge = Color(45, 66, 73, 255)
                draw_rectangle(box_x+20, box_y+88, box_w-40, 2, panel_edge)

                # One clear instruction instead of three repetitive instruction tiles.
                draw_rectangle(box_x+30, box_y+101, 174, 28, Color(56, 43, 20, 255))
                draw_rectangle(box_x+30, box_y+101, 3, 28, Color(240, 184, 62, 255))
                _draw_calibration_text("SYSTEM DIAGNOSTIC", box_x+42, box_y+108, 15, Color(245, 198, 91, 255))
                _draw_calibration_text("MATCH THE LIVE METERS TO THE TARGET OUTPUT.", box_x+222, box_y+106, 16, WHITE)
                _draw_calibration_text("Toggle breakers to change the load. Test when every meter aligns.",
                                       box_x+30, box_y+137, 15, muted)

                # Three wide, high-contrast bank modules are the primary focus.
                card_w, card_h, gap = 270, 280, 16
