    if induction_alignment_open or thermal_stabilisation_open:
        _draw_original_generator_puzzle_overlays()
    if generator_start_prompt_open:
        _draw_generator_start_prompt()
    _draw_generator_event_banner()

    # Generator ignition status during the in-world startup cinematic.
    if generator_igniting and not generator_minigame_open:
        _startup_label = {"cranking":"GENERATOR STARTER CRANKING",
                          "engine_catch":"IGNITION SURGE",
                          "cable_rise":"HIGH-VOLTAGE CABLES ENERGISING",
                          "ceiling_delay":"CEILING BUS ENERGISING",
                          "lights_flicker":"FACILITY LIGHTS STABILISING"}.get(generator_startup_stage, "GENERATOR STARTING")
        _startup_w = measure_text(_startup_label, 14)
        draw_rectangle((SCREEN_WIDTH-_startup_w)//2-18, SCREEN_HEIGHT-94, _startup_w+36, 30, Color(6,14,19,220))
        draw_rectangle_lines((SCREEN_WIDTH-_startup_w)//2-18, SCREEN_HEIGHT-94, _startup_w+36, 30, Color(0,190,211,230))
        draw_text(_startup_label, (SCREEN_WIDTH-_startup_w)//2, SCREEN_HEIGHT-87, 14, UI_CYAN)

    # Pause Menu Modal
    if is_game_paused:
        menu_w, menu_h = 480, 360
        menu_x, menu_y = (SCREEN_WIDTH - menu_w) // 2, (SCREEN_HEIGHT - menu_h) // 2
        draw_rectangle(menu_x, menu_y, menu_w, menu_h, Color(8, 10, 14, 245))
        draw_rectangle_lines(menu_x, menu_y, menu_w, menu_h, UI_CYAN)

        title_txt = "THE LAST HOUR // PAUSED"
        tw = measure_text(title_txt, 22)
        draw_text(title_txt, (SCREEN_WIDTH - tw) // 2, menu_y + 35, 22, UI_CYAN)

        sub_txt = "SECTOR B RESEARCH FACILITY // LOCKDOWN ACTIVE"
        sw = measure_text(sub_txt, 14)
        draw_text(sub_txt, (SCREEN_WIDTH - sw) // 2, menu_y + 70, 14, LIGHTGRAY)

        btn_w, btn_h = 320, 52
        play_btn_x = (SCREEN_WIDTH - btn_w) // 2
        play_btn_y = menu_y + 120
        exit_btn_x = (SCREEN_WIDTH - btn_w) // 2
        exit_btn_y = menu_y + 195

        play_h = (play_btn_x <= mouse_pos.x <= play_btn_x + btn_w) and (play_btn_y <= mouse_pos.y <= play_btn_y + btn_h)
        exit_h = (exit_btn_x <= mouse_pos.x <= exit_btn_x + btn_w) and (exit_btn_y <= mouse_pos.y <= exit_btn_y + btn_h)

        draw_rectangle(play_btn_x, play_btn_y, btn_w, btn_h, Color(28, 55, 38, 255) if play_h else Color(18, 24, 22, 255))
        draw_rectangle_lines(play_btn_x, play_btn_y, btn_w, btn_h, Color(60, 220, 110, 255) if play_h else C_METAL_EDGE)
        play_lbl = "RESUME EXPLORATION"
        pw = measure_text(play_lbl, 16)
        draw_text(play_lbl, (SCREEN_WIDTH - pw) // 2, play_btn_y + 17, 16, WHITE if play_h else LIGHTGRAY)

        draw_rectangle(exit_btn_x, exit_btn_y, btn_w, btn_h, Color(65, 20, 20, 255) if exit_h else Color(24, 18, 18, 255))
        draw_rectangle_lines(exit_btn_x, exit_btn_y, btn_w, btn_h, Color(240, 60, 60, 255) if exit_h else C_METAL_EDGE)
        exit_lbl = "EXIT TO DESKTOP"
        ew = measure_text(exit_lbl, 16)
        draw_text(exit_lbl, (SCREEN_WIDTH - ew) // 2, exit_btn_y + 17, 16, WHITE if exit_h else LIGHTGRAY)

        if play_h and is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
            is_game_paused = False
            disable_cursor()
            spatial_audio.play_ui("item_pickup", volume=0.6)
        if exit_h and is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
            should_quit = True

    if lab_fade_in_alpha > 0.0:
        lab_fade_in_alpha = max(0.0, lab_fade_in_alpha - dt * 1.25)
        draw_rectangle(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, Color(0, 0, 0, int(255 * lab_fade_in_alpha)))

    # Security terminal uses the original isolated counter-signal + two-pass symbol puzzle.
    _obs_active_security_item = _OBS_ROOM_DETAIL_NS.get("active_inspect_item")
    _obs_security_ui_is_active = (obs_security_console_open
        and bool(_OBS_ROOM_DETAIL_NS.get("is_inspecting", False))
        and isinstance(_obs_active_security_item, dict)
        and _obs_active_security_item.get("id") == "security_override_console")
    if _obs_security_ui_is_active:
        _security_draw_cb = _OBS_ROOM_DETAIL_NS.get("draw_security_signal_console_ui")
        if callable(_security_draw_cb):
            _security_draw_cb(global_time)
        else:
            # Fail open to the 3D room rather than crashing the renderer on a missing UI hook.
            obs_security_console_open = False
            _OBS_ROOM_DETAIL_NS["is_inspecting"] = False
            _OBS_ROOM_DETAIL_NS["active_inspect_item"] = None
            disable_cursor()
    elif obs_evidence_panel_open:
        _obs_draw_evidence_panel()
    elif obs_locker_interface_open:
        _obs_draw_locker_interface()

    # Detailed home/identity screens, then the original isolated profile/design/reference screens.
    if not _obs_security_ui_is_active and not obs_evidence_panel_open and not obs_locker_interface_open and obs_service_panel_open:
        if obs_service_panel_kind == "ink_supply":
            _OBS_ROOM_DETAIL_NS["draw_cartridge_shelf_ui"]()
        elif obs_service_panel_kind == "card_printer":
            _OBS_ROOM_DETAIL_NS["draw_printer_service_ui"]()
    elif not _obs_security_ui_is_active and not obs_evidence_panel_open and not obs_locker_interface_open and _OBS_ROOM_DETAIL_NS.get("computer_session_state") == "active":
        draw_observation_computer_ui_host()

    # Opening contextual thought: polished dark glass panel, cyan telemetry accents,
    # and a typewriter cursor. Text progression and its per-character sound are unchanged.
    if opening_mission_state == "dialogue" and not is_game_paused and not any_modal_open:
        _thought_width = min(900, max(340, SCREEN_WIDTH - 48))
        _thought_height = 128
        _thought_x = (SCREEN_WIDTH - _thought_width) // 2
        _thought_y = SCREEN_HEIGHT - _thought_height - 38
        _thought_visible_count = min(
            len(OPENING_PLAYER_THOUGHT),
            int(opening_dialogue_elapsed / OPENING_THOUGHT_CHAR_INTERVAL) + 1,
        )
        _thought_visible = OPENING_PLAYER_THOUGHT[:_thought_visible_count]
        _thought_lines = _thought_visible.split("\n", 1)
        _thought_complete = _thought_visible_count >= len(OPENING_PLAYER_THOUGHT)

        # Soft shadow, dark layered panel, double border, and a slim cyan left rail.
        draw_rectangle(_thought_x + 5, _thought_y + 6, _thought_width, _thought_height, Color(0, 0, 0, 142))
        draw_rectangle(_thought_x, _thought_y, _thought_width, _thought_height, Color(4, 9, 14, 246))
        draw_rectangle(_thought_x + 5, _thought_y + 5, _thought_width - 10, _thought_height - 10,
                       Color(9, 18, 25, 246))
        draw_rectangle_lines(_thought_x, _thought_y, _thought_width, _thought_height, Color(43, 133, 155, 255))
        draw_rectangle_lines(_thought_x + 4, _thought_y + 4, _thought_width - 8, _thought_height - 8,
                            Color(28, 59, 72, 255))
        draw_rectangle(_thought_x + 1, _thought_y + 1, 4, _thought_height - 2, UI_CYAN)

        # Header strip with a simple thought-status emblem and a quiet metadata label.
        draw_rectangle(_thought_x + 9, _thought_y + 8, _thought_width - 18, 25, Color(14, 31, 41, 255))
        draw_rectangle(_thought_x + 10, _thought_y + 8, 3, 25, UI_CYAN)
        draw_circle(_thought_x + 27, _thought_y + 20, 4, UI_CYAN)
        draw_circle_lines(_thought_x + 27, _thought_y + 20, 7, Color(66, 193, 217, 255))
        draw_text("INTERNAL MONOLOGUE", _thought_x + 42, _thought_y + 12, 12, UI_CYAN)
        _thought_meta = "INVESTIGATOR // FIELD NOTE 001"
        _thought_meta_w = measure_text(_thought_meta, 9)
        draw_text(_thought_meta, _thought_x + _thought_width - 23 - _thought_meta_w,
                  _thought_y + 15, 9, Color(111, 153, 166, 255))
        draw_line(_thought_x + 20, _thought_y + 40, _thought_x + _thought_width - 20, _thought_y + 40,
                  Color(32, 75, 89, 255))

        # The two-line thought is larger and has generous breathing room.
        draw_text(_thought_lines[0], _thought_x + 24, _thought_y + 49, 20, Color(239, 246, 249, 255))
        if len(_thought_lines) > 1:
            draw_text(_thought_lines[1], _thought_x + 24, _thought_y + 74, 20, Color(239, 246, 249, 255))

        draw_line(_thought_x + 20, _thought_y + 101, _thought_x + _thought_width - 20, _thought_y + 101,
                  Color(29, 55, 66, 255))
        draw_rectangle(_thought_x + 24, _thought_y + 111, 4, 4, UI_CYAN if not _thought_complete else Color(75, 232, 179, 255))
        _thought_footer = "THOUGHT IN PROGRESS" if not _thought_complete else "THOUGHT RECORDED"
        draw_text(_thought_footer, _thought_x + 36, _thought_y + 106, 9, Color(133, 166, 176, 255))

        # Small blinking caret follows the end of the line currently being typed.
        if not _thought_complete and int(global_time * 3.4) % 2 == 0:
            _cursor_line = _thought_lines[-1]
            _cursor_y = _thought_y + (74 if len(_thought_lines) > 1 else 49)
            _cursor_x = _thought_x + 24 + measure_text(_cursor_line, 20) + 3
            if _cursor_x < _thought_x + _thought_width - 26:
                draw_rectangle(_cursor_x, _cursor_y + 2, 3, 18, UI_CYAN)

    # Shared player dialogue panel for Observation Room locker thoughts and investigation notes.
    # It uses one consistent layout and the typewriter timing/audio advanced by _update_observation_story.
    _observation_dialogue_kind = None
    _observation_dialogue_full_text = ""
    _observation_dialogue_visible_count = 0
    if observation_passcode_intro_state in ("line_one", "line_two"):
        _observation_dialogue_kind = "passcode_intro"
        _observation_dialogue_full_text = (
            "These reports have marks at the end... SUCCESS and FAILED. That cannot be accidental."
            if observation_passcode_intro_state == "line_one"
            else "I need the successful runs only. Sort them by timestamp, then take the final digit of each experiment ID in that order."
        )
        _observation_dialogue_visible_count = min(
            len(_observation_dialogue_full_text),
            int(observation_locker_cinematic_dialogue_elapsed / OBSERVATION_LOCKER_DIALOGUE_CHAR_INTERVAL) + 1,
        )
    elif observation_locker_cinematic_state in ("dialogue_one", "dialogue_two"):
        _observation_dialogue_kind = "cinematic"
        _observation_dialogue_full_text = (
            "Looks like this locker is still locked."
            if observation_locker_cinematic_state == "dialogue_one"
            else "If I can create an access card and find the correct code, I should be able to open it."
        )
        _observation_dialogue_visible_count = min(
            len(_observation_dialogue_full_text),
            int(observation_locker_cinematic_dialogue_elapsed / OBSERVATION_LOCKER_DIALOGUE_CHAR_INTERVAL) + 1,
        )
    elif observation_locker_notice_timer > 0.0:
        _observation_dialogue_kind = "notice"
        _observation_dialogue_full_text = observation_locker_notice_text
        _observation_dialogue_visible_count = min(
            len(_observation_dialogue_full_text),
            int(observation_locker_notice_elapsed / OBSERVATION_LOCKER_DIALOGUE_CHAR_INTERVAL) + 1,
        )

    if _observation_dialogue_kind is not None:
        _observation_dialogue_visible_text = _observation_dialogue_full_text[:_observation_dialogue_visible_count]
        _observation_dialogue_width = min(900, max(340, SCREEN_WIDTH - 48))
        _observation_dialogue_inner_width = _observation_dialogue_width - 54
        _observation_dialogue_layout_lines = wrap_text(
            _observation_dialogue_full_text.replace("\n", " "), 18, _observation_dialogue_inner_width
        ) or [""]
        _observation_dialogue_visible_lines = wrap_text(
            _observation_dialogue_visible_text.replace("\n", " "), 18, _observation_dialogue_inner_width
        ) or [""]
        _observation_dialogue_rule_y = max(101, 49 + 23 * len(_observation_dialogue_layout_lines) + 6)
        _observation_dialogue_height = max(132, _observation_dialogue_rule_y + 31)
        _observation_dialogue_x = (SCREEN_WIDTH - _observation_dialogue_width) // 2
        _observation_dialogue_y = SCREEN_HEIGHT - _observation_dialogue_height - 38
        draw_rectangle(_observation_dialogue_x + 5, _observation_dialogue_y + 6,
                       _observation_dialogue_width, _observation_dialogue_height, Color(0, 0, 0, 142))
        draw_rectangle(_observation_dialogue_x, _observation_dialogue_y,
                       _observation_dialogue_width, _observation_dialogue_height, Color(4, 9, 14, 246))
        draw_rectangle(_observation_dialogue_x + 5, _observation_dialogue_y + 5,
                       _observation_dialogue_width - 10, _observation_dialogue_height - 10,
                       Color(9, 18, 25, 246))
        draw_rectangle_lines(_observation_dialogue_x, _observation_dialogue_y,
                             _observation_dialogue_width, _observation_dialogue_height,
                             Color(43, 133, 155, 255))
        draw_rectangle_lines(_observation_dialogue_x + 4, _observation_dialogue_y + 4,
                             _observation_dialogue_width - 8, _observation_dialogue_height - 8,
                             Color(28, 59, 72, 255))
        draw_rectangle(_observation_dialogue_x + 1, _observation_dialogue_y + 1, 4,
                       _observation_dialogue_height - 2, UI_CYAN)
        draw_rectangle(_observation_dialogue_x + 9, _observation_dialogue_y + 8,
                       _observation_dialogue_width - 18, 25, Color(14, 31, 41, 255))
        draw_rectangle(_observation_dialogue_x + 10, _observation_dialogue_y + 8, 3, 25, UI_CYAN)
        draw_circle(_observation_dialogue_x + 27, _observation_dialogue_y + 20, 4, UI_CYAN)
        draw_circle_lines(_observation_dialogue_x + 27, _observation_dialogue_y + 20, 7,
                          Color(66, 193, 217, 255))
        draw_text("FIELD NOTE // OBSERVATION ARCHIVE", _observation_dialogue_x + 42,
                  _observation_dialogue_y + 12, 12, UI_CYAN)
        for _dialogue_line_i, _dialogue_line in enumerate(_observation_dialogue_visible_lines):
            draw_text(_dialogue_line, _observation_dialogue_x + 24,
                      _observation_dialogue_y + 49 + _dialogue_line_i * 23,
                      18, Color(239, 246, 249, 255))
        draw_line(_observation_dialogue_x + 20, _observation_dialogue_y + _observation_dialogue_rule_y,
                  _observation_dialogue_x + _observation_dialogue_width - 20,
                  _observation_dialogue_y + _observation_dialogue_rule_y, Color(32, 75, 89, 255))
        draw_rectangle(_observation_dialogue_x + 24, _observation_dialogue_y + _observation_dialogue_rule_y + 11,
                       4, 4, UI_CYAN if _observation_dialogue_visible_count < len(_observation_dialogue_full_text)
                       else Color(75, 232, 179, 255))
        if _observation_dialogue_kind in ("cinematic", "passcode_intro"):
            _observation_dialogue_footer = "[E] CONTINUE"
        else:
            _observation_dialogue_footer = "INVESTIGATION NOTE // AUTO-CLEAR"
        draw_text(_observation_dialogue_footer, _observation_dialogue_x + 36,
                  _observation_dialogue_y + _observation_dialogue_rule_y + 6,
                  9, Color(133, 166, 176, 255))
        if (_observation_dialogue_visible_count < len(_observation_dialogue_full_text)
                and int(global_time * 3.4) % 2 == 0):
            _cursor_line = _observation_dialogue_visible_lines[-1]
            _cursor_x = _observation_dialogue_x + 24 + measure_text(_cursor_line, 18) + 3
            _cursor_y = _observation_dialogue_y + 49 + (len(_observation_dialogue_visible_lines) - 1) * 23
            if _cursor_x < _observation_dialogue_x + _observation_dialogue_width - 26:
                draw_rectangle(_cursor_x, _cursor_y + 2, 3, 18, UI_CYAN)

    _draw_echo_phase5_overlay()
    _alt_ending_draw_overlay()


    # Mobile Touch Controls Overlay
    if not any_modal_open:
        mobile_ctrl.draw(hovered_object, torch_active)

    end_drawing()



