# SECURITY ROOM INTEGRATION // OPEN EXTENSION OF MAIN LAB // V22
# Uses Main Lab's shared Observation Room palette, PBR renderer, FPS optimizations,
# camera-frustum culling and shader material cache. The standalone Security Room loop
# is intentionally NOT imported; this room is part of the existing Main Lab application.
# ============================================================================
SECURITY_ROOM_OFFSET_X = -6.9
SECURITY_ROOM_OFFSET_Z = 15.2
# The opening stays at its existing Main Lab wall coordinates; only the room shell is offset.
SECURITY_ENTRY_X = -18.2
SECURITY_ENTRY_Z = 11.3
SECURITY_WALK_Z_MIN = 9.63
SECURITY_WALK_Z_MAX = 20.77
SECURITY_ROOM_WORLD_X_MIN = -31.10
SECURITY_ROOM_WORLD_X_MAX = -18.70

# Shared-material aliases/colours needed by Security-only props, kept in the same
# charcoal/steel palette as the Observation Room rather than the standalone palette.
C_DESK_TOP = Color(38, 44, 48, 255)
C_FLOOR_MOTTLE_A = Color(9, 11, 13, 255)
C_FLOOR_MOTTLE_B = Color(20, 19, 18, 255)
C_FLOOR_MOTTLE_C = Color(24, 26, 27, 255)
C_FLOOR_CRACK = Color(7, 8, 9, 255)
C_SIDE_DESK_TOP_DARK = Color(26, 30, 33, 255)
C_SIDE_DESK_BODY_DARK = Color(16, 19, 22, 255)
C_SIDE_DESK_EDGE_DARK = Color(48, 54, 58, 255)

# A tiny dedicated triangle model is required by the Security Room's broken-glass shards.
unit_triangle_model = load_model_from_mesh(gen_mesh_poly(3, 1.0))
unit_triangle_model.materials[0] = custom_material


# SURVEILLANCE CCTV SYSTEM & CAMERA TEXTURE SYNTHESIZER
# ============================================================
cctv_textures = {}
cctv_screen_models = {}

def _build_cctv_texture(cam_id, title, status_text, sector_type):
    width, height = 1024, 576
    img = PILImage.new("RGB", (width, height), (4, 14, 10))
    draw = PILImageDraw.Draw(img)
    
    # CRT scanlines
    for y in range(0, height, 4):
        draw.line([(0, y), (width, y)], fill=(2, 8, 6), width=1)
        
    c_line = (35, 185, 140)
    c_dim = (18, 95, 70)
    c_bright = (140, 255, 210)
    c_alert = (235, 75, 60)
    
    draw.rectangle([12, 12, width - 12, height - 12], outline=c_dim, width=2)
    bk = 36
    for cx, cy, sx, sy in [(24, 24, 1, 1), (width - 24, 24, -1, 1), (24, height - 24, 1, -1), (width - 24, height - 24, -1, -1)]:
        draw.line([(cx, cy), (cx + bk * sx, cy)], fill=c_bright, width=3)
        draw.line([(cx, cy), (cx, cy + bk * sy)], fill=c_bright, width=3)
        
    # Crosshair
    mid_x, mid_y = width // 2, height // 2
    draw.line([(mid_x - 45, mid_y), (mid_x - 12, mid_y)], fill=c_line, width=2)
    draw.line([(mid_x + 12, mid_y), (mid_x + 45, mid_y)], fill=c_line, width=2)
    draw.line([(mid_x, mid_y - 45), (mid_x, mid_y - 12)], fill=c_line, width=2)
    draw.line([(mid_x, mid_y + 12), (mid_x, mid_y + 45)], fill=c_line, width=2)
    draw.ellipse([mid_x - 6, mid_y - 6, mid_x + 6, mid_y + 6], outline=c_line, width=1)
    
    # REC Indicator
    draw.ellipse([34, 28, 48, 42], fill=c_alert)
    
    try:
        f_large = PILImageFont.truetype(r"C:\Windows\Fonts\arial.ttf", 26)
        f_mid = PILImageFont.truetype(r"C:\Windows\Fonts\arial.ttf", 20)
        f_mono = PILImageFont.truetype(r"C:\Windows\Fonts\consola.ttf", 18)
    except OSError:
        f_large = f_mid = f_mono = PILImageFont.load_default()
        
    draw.text((58, 24), "REC  [LIVE]", font=f_large, fill=c_bright)
    draw.text((width - 320, 26), f"02:44:19 UTC // CH-0{cam_id}", font=f_mono, fill=c_line)
    draw.text((36, 62), f"CAM {cam_id:02d} // {title}", font=f_mid, fill=c_bright)
    
    if sector_type == "lab":
        for i in range(-5, 6):
            draw.line([(mid_x + i * 28, mid_y + 40), (mid_x + i * 115, height - 70)], fill=c_dim, width=1)
        for d in [90, 150, 220, 310]:
            y_pos = mid_y + 40 + int(d * 0.6)
            draw.line([(60, y_pos), (width - 60, y_pos)], fill=c_dim, width=1)
        draw.ellipse([mid_x + 90, mid_y - 45, mid_x + 190, mid_y + 110], outline=c_line, width=2)
        draw.ellipse([mid_x + 110, mid_y - 25, mid_x + 170, mid_y + 90], outline=c_bright, width=2)
        draw.text((mid_x + 105, mid_y + 118), "[TARGET: POD 09]", font=f_mono, fill=c_bright)
        draw.rectangle([mid_x - 240, mid_y + 80, mid_x - 80, mid_y + 180], outline=c_dim, width=2)
    elif sector_type == "stasis":
        for r in [60, 110, 160, 210]:
            draw.ellipse([mid_x - r, mid_y - r - 20, mid_x + r, mid_y + r - 20], outline=c_dim, width=1)
        draw.ellipse([mid_x - 85, mid_y - 105, mid_x + 85, mid_y + 65], outline=c_bright, width=3)
        prev_pt = (50, height - 120)
        for x in range(50, width - 50, 15):
            wy = height - 120 + int(math.sin(x * 0.08) * 12 + (math.sin(x * 0.35) * 35 if 400 < x < 550 else 0))
            draw.line([prev_pt, (x, wy)], fill=c_bright, width=2)
            prev_pt = (x, wy)
        draw.text((60, height - 90), "SPECIMEN 09 // NEURAL FREQ: 440 Hz // BIO-PRESSURE: 1.4 BAR", font=f_mono, fill=c_line)
    elif sector_type == "generator":
        draw.ellipse([mid_x - 110, mid_y - 90, mid_x + 110, mid_y + 130], outline=c_bright, width=3)
        for a in range(8):
            rad = a * (math.pi / 4.0)
            draw.line([(mid_x, mid_y + 20), (mid_x + int(math.cos(rad) * 95), mid_y + 20 + int(math.sin(rad) * 95))], fill=c_line, width=2)
        for i in range(4):
            dx = (i - 1.5) * 35
            draw.line([(mid_x + dx, 50), (mid_x + dx, mid_y - 90)], fill=(225, 175, 45), width=3)
        draw.text((60, height - 90), "AUXILIARY GENERATOR // OUTPUT: STANDBY // BUSBAR: 4160V", font=f_mono, fill=c_line)
    elif sector_type == "obs":
        draw.rectangle([80, 110, width - 80, height - 150], outline=c_line, width=3)
        draw.line([(mid_x - 140, 110), (mid_x - 140, height - 150)], fill=c_dim, width=2)
        draw.line([(mid_x + 140, 110), (mid_x + 140, height - 150)], fill=c_dim, width=2)
        draw.rectangle([mid_x - 85, mid_y + 20, mid_x + 85, mid_y + 70], outline=c_bright, width=2)
        draw.ellipse([mid_x - 40, mid_y - 40, mid_x + 40, mid_y + 40], outline=c_dim, width=2)
        draw.text((60, height - 90), "OBSERVATION THEATER // SPECIMEN ISOLATION ZONE // PROTOCOL DELTA-9", font=f_mono, fill=c_line)
    elif sector_type == "airlock":
        draw.rectangle([140, 90, width - 140, height - 120], outline=c_dim, width=3)
        draw.line([(mid_x, 90), (mid_x, height - 120)], fill=c_bright, width=4)
        for h in range(120, height - 150, 45):
            draw.line([(160, h), (mid_x - 20, h)], fill=(220, 160, 30), width=3)
            draw.line([(mid_x + 20, h), (width - 160, h)], fill=(220, 160, 30), width=3)
        draw.text((60, height - 90), "SECTOR B PRIMARY AIRLOCK // DECON CYCLE: LOCKED", font=f_mono, fill=c_line)
    elif sector_type == "research":
        draw.ellipse([mid_x - 90, mid_y - 90, mid_x + 90, mid_y + 90], outline=c_bright, width=3)
        draw.ellipse([mid_x - 30, mid_y - 30, mid_x + 30, mid_y + 30], outline=c_dim, width=2)
        for a in range(8):
            rad = a * (math.pi / 4.0)
            draw.line([(mid_x, mid_y), (mid_x + int(math.cos(rad) * 65), mid_y + int(math.sin(rad) * 65))], fill=c_line, width=2)
            draw.ellipse([mid_x + int(math.cos(rad) * 65) - 8, mid_y + int(math.sin(rad) * 65) - 8,
                          mid_x + int(math.cos(rad) * 65) + 8, mid_y + int(math.sin(rad) * 65) + 8], fill=c_bright)
        draw.text((60, height - 90), "GENOME EDITING WING // CAROUSEL: ACTIVE // PATHOGEN: CH-09", font=f_mono, fill=c_line)
    elif sector_type == "matrix":
        draw.line([(mid_x, 50), (mid_x, height - 60)], fill=c_bright, width=2)
        draw.line([(20, mid_y), (width - 20, mid_y)], fill=c_bright, width=2)
        draw.text((40, 70), "CH-01: MAIN LAB [LIVE]", font=f_mono, fill=c_bright)
        draw.text((mid_x + 30, 70), "CH-02: STASIS POD [LIVE]", font=f_mono, fill=c_bright)
        draw.text((40, mid_y + 20), "CH-03: ELEC BAY [LIVE]", font=f_mono, fill=c_bright)
        draw.text((mid_x + 30, mid_y + 20), "CH-04: OBS DECK [LIVE]", font=f_mono, fill=c_bright)
        draw.text((mid_x - 170, height - 42), "MASTER CCTV QUAD-PROCESSOR // 4-CH OK", font=f_mono, fill=c_bright)
        
    if sector_type != "matrix":
        draw.text((36, height - 52), f"STATUS: {status_text}", font=f_mono, fill=c_bright)
        
    img = img.transpose(PILImage.Transpose.FLIP_LEFT_RIGHT)
    b = BytesIO()
    img.save(b, format="PNG")
    png_bytes = b.getvalue()
    ray_img = load_image_from_memory(b".png", png_bytes, len(png_bytes))
    tex = load_texture_from_image(ray_img)
    unload_image(ray_img)
    return tex

