def _create_cctv_mesh_model(w, h, tex):
    mesh = gen_mesh_plane(w, h, 1, 1)
    for v in range(mesh.vertexCount):
        vx = mesh.vertices[v*3]
        vz = mesh.vertices[v*3 + 2]
        mesh.texcoords[v*2] = (vx + w/2.0) / w
        mesh.texcoords[v*2 + 1] = 0.5 - vz / h
    update_mesh_buffer(mesh, 1, mesh.texcoords, mesh.vertexCount * 2 * 4, 0)
    model = load_model_from_mesh(mesh)
    model.materials[0].shader = terminal_screen_shader
    set_material_texture(model.materials[0], MATERIAL_MAP_ALBEDO, tex)
    return model

