def _build_security_sector_map_texture():
    """Create a muted, readable printed Sector B camera/facility plan for the wall-mounted map."""
    width, height = 1024, 640
    img = PILImage.new("RGB", (width, height), (82, 80, 65))
    d = PILImageDraw.Draw(img)
    rng = random.Random(7124)
    # Paper grain and old water marks, baked once into the texture (not per frame).
    for _ in range(460):
        x, y = rng.randrange(width), rng.randrange(height)
        r = rng.randrange(1, 6)
        shade = rng.choice(((67,67,57),(97,92,73),(110,101,78),(74,73,62)))
        d.ellipse((x-r,y-r,x+r,y+r), fill=shade)
    try:
        f_title = PILImageFont.truetype(r"C:\Windows\Fonts\consola.ttf", 31)
        f_head = PILImageFont.truetype(r"C:\Windows\Fonts\consola.ttf", 20)
        f_body = PILImageFont.truetype(r"C:\Windows\Fonts\consola.ttf", 16)
        f_small = PILImageFont.truetype(r"C:\Windows\Fonts\consola.ttf", 13)
    except OSError:
        f_title = f_head = f_body = f_small = PILImageFont.load_default()

    paper=(147,139,111); ink=(37,42,37); pale=(188,181,151)
    cyan=(74,143,151); amber=(177,119,43); red=(151,57,43); green=(84,120,83)
    d.rectangle((18,18,width-18,height-18), outline=(35,39,34), width=7)
    d.rectangle((30,30,width-30,height-30), outline=(142,128,98), width=2)
    d.rectangle((42,42,width-42,104), fill=(47,50,42), outline=(27,30,26), width=2)
    d.text((60,51), "SECTOR B // CCTV FIELD MAP", font=f_title, fill=(188,177,136))
    d.text((62,84), "SECURITY OPERATIONS  /  REV 04  /  ROUTING DATA UNVERIFIED", font=f_small, fill=(143,158,137))

    # Floor-plan field and subdued grid.
    plan=(58,127,688,548)
    d.rectangle(plan, fill=(118,116,94), outline=ink, width=4)
    for gx in range(plan[0]+20, plan[2]-10, 24):
        d.line((gx,plan[1]+5,gx,plan[3]-6), fill=(104,105,87), width=1)
    for gy in range(plan[1]+20, plan[3]-10, 24):
        d.line((plan[0]+5,gy,plan[2]-6,gy), fill=(104,105,87), width=1)

    # Rooms: mapped facility areas; cyan and amber routes indicate existing camera-coverage paths.
    rooms = [
        ((115,183,305,302), "MAIN LAB", (101,119,101)),
        ((325,176,455,268), "STASIS POD", (102,120,124)),
        ((474,174,634,267), "GENERATOR", (127,104,70)),
        ((112,333,302,431), "OBSERVATION", (111,118,102)),
        ((326,297,455,397), "SECURITY", (91,116,110)),
        ((477,322,633,443), "RESEARCH ARCHIVE", (122,102,76)),
    ]
    for rect,label,fill in rooms:
        d.rectangle(rect, fill=fill, outline=(36,41,34), width=5)
        x0,y0,x1,y1=rect
        d.rectangle((x0+6,y0+6,x1-6,y0+31), fill=(59,63,52))
        d.text((x0+12,y0+10), label, font=f_small, fill=(194,183,146))
        # Room-specific utility marks.
        for k in range(3):
            yy=y0+45+k*13
            if yy < y1-8:
                d.line((x0+13,yy,x0+min(x1-x0-12,52+k*17),yy), fill=(75,80,65), width=2)

    # Connecting corridors and camera coverage routes.
    d.rectangle((302,224,325,376), fill=(82,85,69), outline=ink, width=3)
    d.rectangle((433,268,494,297), fill=(82,85,69), outline=ink, width=3)
    d.line(((210,242),(315,242),(315,350),(386,350),(386,278),(544,278)), fill=cyan, width=6, joint="curve")
    d.line(((210,380),(272,380),(272,418),(377,418),(377,361),(552,361)), fill=amber, width=5, joint="curve")
    d.line(((386,350),(433,350),(433,374),(510,374)), fill=red, width=3, joint="curve")

    # Numbered camera markers with simple directional cones.
    cams=[(150,160,"C01"),(350,155,"C02"),(590,155,"C03"),(150,452,"C04"),(352,460,"C05"),(604,464,"C06")]
    for i,(x,y,label) in enumerate(cams):
        col=cyan if i%3!=2 else amber
        d.ellipse((x-10,y-10,x+10,y+10), fill=col, outline=(29,35,31), width=3)
        d.polygon(((x,y-2),(x+20,y-12),(x+20,y+8)), fill=(42,47,39))
        d.text((x+13,y-21),label,font=f_small,fill=(229,211,158))

    # Legend and future-puzzle fields.
    d.rectangle((716,127,966,548), fill=(65,68,55), outline=(33,37,31), width=4)
    d.text((738,145), "CAMERA LEGEND", font=f_head, fill=(189,177,139))
    for idx,(label,sub,col) in enumerate((
        ("C01-C02", "MAIN LAB / STASIS", cyan),
        ("C03-C04", "POWER / OBSERVATION", amber),
        ("C05-C06", "SECURITY / ARCHIVE", green),
    )):
        yy=193+idx*56
        d.ellipse((738,yy,754,yy+16),fill=col,outline=ink,width=2)
        d.text((768,yy-2),label,font=f_body,fill=(202,190,152))
        d.text((768,yy+22),sub,font=f_small,fill=(144,151,126))
    d.line((736,431,946,431),fill=(122,112,85),width=2)
    d.text((738,444), "ROUTE STATUS: TRACE LOADED", font=f_small, fill=amber)
    d.text((738,465), "CONTROL BUS: ONLINE", font=f_small, fill=green)
    d.text((738,486), "SYNC CHECK: READY", font=f_small, fill=(180,177,143))
    d.text((738,518), "PRESS E // OPEN ROUTING", font=f_small, fill=(201,174,113))

    # Tiny registration marks / coffee-wear rubs on the lower edge.
    d.rectangle((60,564,680,600), fill=(54,57,47))
    d.text((74,574), "LIVE CCTV ROUTING // DISCONNECT ALL SIX CAMERA RELAYS", font=f_small, fill=(157,145,111))
    img = img.transpose(PILImage.Transpose.FLIP_LEFT_RIGHT)
    buf=BytesIO()
    img.save(buf,format="PNG")
    png=buf.getvalue()
    ray_img=load_image_from_memory(b".png",png,len(png))
    tex=load_texture_from_image(ray_img)
    unload_image(ray_img)
    return tex


VS_SECURITY_MAP_CODE = VS_PBR_CODE
FS_SECURITY_MAP_CODE = """#version 330
in vec3 fragPosition;
in vec2 fragTexCoord;
in vec3 fragNormal;
out vec4 finalColor;
uniform sampler2D texture0;
uniform vec3 mapLightPos;
uniform vec3 mapLightColor;
uniform vec3 mapAmbient;
uniform vec3 mapTint;
void main() {
    vec3 N = normalize(fragNormal);
    vec3 delta = mapLightPos - fragPosition;
    float distanceToLamp = length(delta);
    vec3 L = normalize(delta);
    float diffuse = max(dot(N, L), 0.0);
    float attenuation = 1.0 / (1.0 + 0.12*distanceToLamp + 0.030*distanceToLamp*distanceToLamp);
    vec3 printColor = texture(texture0, fragTexCoord).rgb * mapTint;
    vec3 shaded = printColor * (mapAmbient + mapLightColor * diffuse * attenuation);
    finalColor = vec4(shaded, 1.0);
}
"""
security_map_texture = _build_security_sector_map_texture()
security_map_shader = load_shader_from_memory(VS_SECURITY_MAP_CODE, FS_SECURITY_MAP_CODE)
security_map_model = gen_mesh_plane(1.81, 1.08, 1, 1)
for v in range(security_map_model.vertexCount):
    vx=security_map_model.vertices[v*3]
    vz=security_map_model.vertices[v*3+2]
    security_map_model.texcoords[v*2]=(vx+1.81/2.0)/1.81
    security_map_model.texcoords[v*2+1]=0.5-vz/1.08
update_mesh_buffer(security_map_model,1,security_map_model.texcoords,security_map_model.vertexCount*2*4,0)
security_map_model = load_model_from_mesh(security_map_model)
security_map_model.materials[0].shader = security_map_shader
set_material_texture(security_map_model.materials[0],MATERIAL_MAP_ALBEDO,security_map_texture)
security_map_light_pos_loc=get_shader_location(security_map_shader,"mapLightPos")
security_map_light_col_loc=get_shader_location(security_map_shader,"mapLightColor")
security_map_ambient_loc=get_shader_location(security_map_shader,"mapAmbient")
security_map_tint_loc=get_shader_location(security_map_shader,"mapTint")


