def draw_coffee_mug(pos, rot):
    """Broken ceramic mug with a missing chunk and dark dried coffee residue."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot.x, 1, 0, 0)
    rl_rotatef(rot.y, 0, 1, 0)
    rl_rotatef(rot.z, 0, 0, 1)

    # Main cracked body, intentionally irregular-looking through layered pieces.
    draw_pbr_cylinder(Vector3(0, 0.085, 0), 0.095, 0.17, WHITE,
                      roughness=0.40, metallic=0.05)
    draw_pbr_cylinder(Vector3(0, 0.166, 0), 0.096, 0.018, WHITE,
                      roughness=0.38, metallic=0.05)
    draw_pbr_cylinder(Vector3(0, 0.015, 0), 0.078, 0.018, C_DIRT,
                      roughness=0.58)

    # Broken / chipped rim sections.
    draw_pbr_box(Vector3(-0.045, 0.176, 0.075), Vector3(0.070, 0.026, 0.035),
                 C_DIRT, roughness=0.80)
    draw_pbr_box(Vector3(0.045, 0.170, -0.080), Vector3(0.065, 0.025, 0.035),
                 C_DIRT, roughness=0.80)

    # Handle, with a visibly broken end.
    draw_pbr_torus(Vector3(0.098, 0.10, 0), 0.058, 0.017, WHITE,
                   roughness=0.40)
    draw_pbr_box(Vector3(0.143, 0.055, 0.0), Vector3(0.030, 0.045, 0.050),
                 C_DIRT, roughness=0.85)

    # Dark dried coffee left around the rim and inside the cup.
    draw_pbr_torus(Vector3(0, 0.173, 0), 0.070, 0.010, C_RUST2,
                   roughness=0.72)
    rl_pop_matrix()

def draw_security_pen_holder(pos, rot_y=0.0):
    """High-detail hollow metal pen cup tipped onto its side."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot_y, 0, 1, 0)
    rl_rotatef(90.0, 0, 0, 1)

    # Hollow cylindrical shell: dark interior is recessed behind the rim.
    draw_pbr_cylinder(Vector3(0, 0.0, 0), 0.115, 0.34, C_METAL_MID,
                      roughness=0.42, metallic=0.62)
    draw_pbr_cylinder(Vector3(0, 0.172, 0), 0.092, 0.012, C_RUBBER,
                      roughness=0.92, metallic=0.05)
    draw_pbr_torus(Vector3(0, 0.176, 0), 0.112, 0.016, C_METAL_EDGE,
                   roughness=0.28, metallic=0.86)
    draw_pbr_torus(Vector3(0, -0.176, 0), 0.108, 0.012, C_METAL_EDGE,
                   roughness=0.32, metallic=0.78)

    # Vertical reinforcement ribs and worn lower band.
    for a in (-55, -18, 18, 55):
        rad = math.radians(a)
        draw_pbr_box(Vector3(math.sin(rad)*0.106, 0.0, math.cos(rad)*0.106),
                     Vector3(0.018, 0.31, 0.018), C_STEEL,
                     roughness=0.30, metallic=0.84)
    draw_pbr_torus(Vector3(0, -0.105, 0), 0.111, 0.010, C_RUST2,
                   roughness=0.72, metallic=0.62)
    rl_pop_matrix()

def draw_security_desk_pen(pos, angle_y, color, length=0.30):
    """Grounded low-poly pen: all parts sit on the desk; no floating dark cylinders."""
    rl_push_matrix()
