def draw_security_coffee_spill():
    """Lighter, clearly readable dried coffee spill without overpowering the desk."""
    coffee_light = Color(122, 76, 38, 255)
    coffee_mid = Color(102, 58, 28, 255)
    patches = [
        (Vector3(-18.28, 1.487, 1.93), Vector3(0.58, 0.008, 0.34)),
        (Vector3(-18.62, 1.488, 1.76), Vector3(0.34, 0.008, 0.22)),
        (Vector3(-17.98, 1.488, 2.02), Vector3(0.30, 0.008, 0.18)),
        (Vector3(-18.05, 1.489, 1.72), Vector3(0.18, 0.008, 0.12)),
    ]
    for pos, size in patches:
        draw_pbr_box(pos, size, coffee_light, roughness=0.90)
    draw_pbr_cylinder(Vector3(-18.30, 1.494, 1.88), 0.18, 0.006, coffee_mid, roughness=0.92)
    for x, z, r in [(-18.82,1.91,0.035), (-18.98,1.78,0.022), (-17.72,2.08,0.028),
                    (-17.62,1.84,0.018), (-18.54,2.12,0.024)]:
        draw_pbr_cylinder(Vector3(x, 1.495, z), r, 0.005, coffee_light, roughness=0.94)
    draw_pbr_torus(Vector3(-18.40, 1.497, 1.85), 0.145, 0.014, coffee_mid, roughness=0.92)
    draw_pbr_torus(Vector3(-18.05, 1.497, 1.98), 0.082, 0.010, coffee_light, roughness=0.92)

def draw_cctv_monitor(pos, rot_y=0.0, width=1.4, height=0.85, tex_key="matrix", is_crt=False, is_powered=False):
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot_y, 0, 1, 0)

    if is_crt:
        depth = 0.65
        draw_pbr_box(Vector3(0, 0, 0), Vector3(width + 0.12, height + 0.12, depth), C_METAL_DARK, roughness=0.55, metallic=0.45)
        draw_pbr_box(Vector3(0, 0, depth/2.0 + 0.02), Vector3(width + 0.06, height + 0.06, 0.04), C_METAL_EDGE, roughness=0.4, metallic=0.6)
        draw_pbr_cylinder(Vector3(0, -height/2.0 - 0.12, 0), 0.16, 0.20, C_METAL_MID, roughness=0.4, metallic=0.7)
        draw_pbr_box(Vector3(0, -height/2.0 - 0.22, 0), Vector3(width * 0.65, 0.04, 0.40), C_METAL_DARK, roughness=0.6)
        screen_z = depth/2.0 + 0.042
    else:
        depth = 0.08
        draw_pbr_box(Vector3(0, 0, 0), Vector3(width + 0.08, height + 0.08, depth), C_METAL_DARK, roughness=0.45, metallic=0.75)
        draw_pbr_box(Vector3(0, 0, depth/2.0 + 0.005), Vector3(width + 0.04, height + 0.04, 0.02), C_METAL_EDGE, roughness=0.35, metallic=0.8)
        draw_pbr_box(Vector3(0, -height/2.0 - 0.10, -0.04), Vector3(0.06, 0.20, 0.05), C_STEEL, roughness=0.25, metallic=0.85)
        draw_pbr_box(Vector3(0, -height/2.0 - 0.20, 0.04), Vector3(0.44, 0.03, 0.28), C_METAL_DARK, roughness=0.5, metallic=0.6)
        screen_z = depth/2.0 + 0.016

    if is_powered:
        model_key = tex_key if width < 1.8 else (tex_key + "_large" if (tex_key + "_large") in cctv_screen_models else tex_key)
        model = cctv_screen_models.get(model_key, cctv_screen_models.get("matrix"))
        if model:
            rl_push_matrix()
            rl_translatef(0, 0, screen_z)
            rl_rotatef(-90, 1, 0, 0)
            base_w = 2.0 if "large" in model_key else 1.4
            base_h = 1.25 if "large" in model_key else 0.85
            rl_scalef(width / base_w, 1.0, height / base_h)
            draw_model(model, Vector3(0, 0, 0), 1.0, WHITE)
            rl_pop_matrix()
    else:
        # Powered-down CRT/LCD glass: keep a visible physical screen, but no active camera feed.
        draw_pbr_box(Vector3(0, 0, screen_z), Vector3(max(0.10, width - 0.10), max(0.10, height - 0.10), 0.012),
                     Color(2, 4, 5, 255), roughness=0.48, metallic=0.08)

    rl_pop_matrix()

def draw_security_keyboard(pos, rot_y=0.0):
    """Recognizable full-size security keyboard with individual low-poly keys."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot_y, 0, 1, 0)

    # Sloped keyboard shell.
    draw_pbr_box(Vector3(0, 0.045, 0), Vector3(0.98, 0.075, 1.12), C_RUBBER,
                 roughness=0.86, metallic=0.05)
    draw_pbr_box(Vector3(0, 0.083, -0.015), Vector3(0.91, 0.028, 1.02), C_METAL_MID,
                 roughness=0.62, metallic=0.28)

    # Function row.
    for k in range(10):
        x = -0.39 + k * 0.087
        draw_pbr_box(Vector3(x, 0.108, 0.40), Vector3(0.062, 0.028, 0.075),
                     C_PAPER2, roughness=0.82)

    # Main typing area: four clearly separated rows.
    row_counts = [11, 11, 10, 9]
    row_z = [0.25, 0.08, -0.09, -0.26]
    for row_i, (count, z) in enumerate(zip(row_counts, row_z)):
        spacing = 0.075
        start = -((count - 1) * spacing) / 2.0
        offset = 0.018 if row_i in (1, 2) else (0.035 if row_i == 3 else 0.0)
        for k in range(count):
            x = start + k * spacing + offset
            col = C_PAPER2
            if (row_i == 0 and k in (0, 9)) or (row_i == 3 and k == 0):
                col = C_AMBER
            draw_pbr_box(Vector3(x, 0.111, z), Vector3(0.060, 0.030, 0.105),
                         col, roughness=0.80)

    # Bottom modifier / spacebar row.
    for x, w in [(-0.37, 0.13), (-0.22, 0.10), (0.0, 0.40), (0.22, 0.10), (0.37, 0.13)]:
        draw_pbr_box(Vector3(x, 0.111, -0.405), Vector3(w, 0.030, 0.10),
                     C_PAPER2, roughness=0.80)

    # Small status light and worn edge.
    draw_pbr_box(Vector3(0.405, 0.118, 0.40), Vector3(0.045, 0.012, 0.020),
                 C_RED_DIM, roughness=0.25, emissive=Vector3(0.45, 0.03, 0.02))
    draw_pbr_box(Vector3(-0.30, 0.112, -0.49), Vector3(0.30, 0.008, 0.018),
                 C_DIRT, roughness=0.90)
    rl_pop_matrix()

def draw_security_main_monitor(pos, rot_y=90.0, is_powered=False):
    """Prominent modern security workstation monitor with layered 3D construction."""
    rl_push_matrix()
    rl_translatef(pos.x, pos.y, pos.z)
    rl_rotatef(rot_y, 0, 1, 0)

    # Heavy rear housing, intentionally narrow to read as a real flat-panel monitor.
    draw_pbr_box(Vector3(0, 0, 0), Vector3(1.82, 1.08, 0.095),
                 C_METAL_DARK, roughness=0.30, metallic=0.82)
    draw_pbr_box(Vector3(0, 0, 0.058), Vector3(1.70, 0.97, 0.030),
                 C_METAL_EDGE, roughness=0.22, metallic=0.86)
    draw_pbr_box(Vector3(0, 0, 0.078), Vector3(1.57, 0.84, 0.018),
                 C_RUBBER, roughness=0.58, metallic=0.02)

    # Existing cached CCTV image, embedded flush into the bezel.
    model = cctv_screen_models.get("matrix")
    if model:
        rl_push_matrix()
        rl_translatef(0, 0, 0.092)
        rl_rotatef(-90, 1, 0, 0)
        rl_scalef(1.14, 1.0, 1.10)
        draw_model(model, Vector3(0, 0, 0), 1.0, WHITE)
        rl_pop_matrix()

    # Lower chin with inset service badge.
    draw_pbr_box(Vector3(0, -0.495, 0.028), Vector3(1.70, 0.075, 0.090),
                 C_METAL_DARK, roughness=0.34, metallic=0.78)
    draw_pbr_box(Vector3(0, -0.495, 0.078), Vector3(0.56, 0.028, 0.018),
                 C_METAL_MID, roughness=0.34, metallic=0.62)

    # Status strip and physical buttons.
    led = C_GREEN_DIM if is_powered else C_RED_DIM
    led_emissive = Vector3(0.02, 0.55, 0.09) if is_powered else Vector3(0.50, 0.02, 0.01)
    draw_pbr_box(Vector3(0.63, -0.493, 0.090), Vector3(0.12, 0.018, 0.012),
                 led, roughness=0.18, emissive=led_emissive)
    for i, bx in enumerate((-0.48, -0.40, -0.32)):
        draw_pbr_cylinder(Vector3(bx, -0.493, 0.090), 0.018, 0.010,
                          C_STEEL if i != 2 else C_AMBER,
                          roughness=0.28, metallic=0.86,
                          emissive=Vector3(0.22, 0.09, 0.01) if i == 2 else None)

    # Split-hinge stand and weighted base.
    draw_pbr_box(Vector3(0, -0.60, 0.0), Vector3(0.34, 0.12, 0.16),
                 C_METAL_DARK, roughness=0.34, metallic=0.80)
    draw_pbr_box(Vector3(0, -0.77, 0.0), Vector3(0.105, 0.26, 0.105),
                 C_STEEL, roughness=0.24, metallic=0.90)
    draw_pbr_box(Vector3(0, -0.91, 0.0), Vector3(0.62, 0.050, 0.34),
                 C_METAL_DARK, roughness=0.35, metallic=0.80)
    draw_pbr_box(Vector3(-0.20, -0.94, 0.0), Vector3(0.12, 0.025, 0.24),
                 C_RUBBER, roughness=0.92)
    draw_pbr_box(Vector3(0.20, -0.94, 0.0), Vector3(0.12, 0.025, 0.24),
                 C_RUBBER, roughness=0.92)

    # Rear ventilation fins visible around the housing edge.
    for i in range(6):
        draw_pbr_box(Vector3(-0.58 + i*0.23, 0.20, -0.058),
                     Vector3(0.13, 0.020, 0.018), C_RUBBER, roughness=0.95)

    rl_pop_matrix()

