def draw_security_desk_cables(time_val=0.0):
    """Low-poly fixed cable runs; static geometry, no per-frame allocation."""
    cable = C_RUBBER
    # Monitor power/signal leads disappearing behind the desk.
    runs = [
        [Vector3(-18.48, 1.94, 0.00), Vector3(-18.48, 1.55, 0.00), Vector3(-18.32, 1.50, -0.35), Vector3(-18.32, 1.47, -0.95)],
        [Vector3(-17.52, 1.50, 0.00), Vector3(-17.52, 1.50, 0.92), Vector3(-17.70, 1.48, 1.45)],
        [Vector3(-17.50, 1.50, -0.30), Vector3(-17.50, 1.48, -0.92), Vector3(-17.68, 1.47, -1.35)],
        [Vector3(-17.70, 1.50, 1.35), Vector3(-17.70, 1.42, 1.70)]
    ]
    for run in runs:
        for a, b in zip(run, run[1:]):
            dx = b.x - a.x
            dy = b.y - a.y
            dz = b.z - a.z
            if abs(dx) >= abs(dz) and abs(dx) >= abs(dy):
                draw_pbr_box(Vector3((a.x+b.x)/2, (a.y+b.y)/2, (a.z+b.z)/2),
                             Vector3(abs(dx)+0.035, 0.035, 0.035), cable, roughness=0.92)
            elif abs(dz) >= abs(dy):
                draw_pbr_box(Vector3((a.x+b.x)/2, (a.y+b.y)/2, (a.z+b.z)/2),
                             Vector3(0.035, 0.035, abs(dz)+0.035), cable, roughness=0.92)
            else:
                draw_pbr_box(Vector3((a.x+b.x)/2, (a.y+b.y)/2, (a.z+b.z)/2),
                             Vector3(0.035, abs(dy)+0.035, 0.035), cable, roughness=0.92)

    # A few loose loops at the rear edge to sell neglect without cluttering the player path.
    for i in range(3):
        draw_pbr_torus(Vector3(-17.70, 1.475, 1.62 + i*0.075), 0.045, 0.010, C_RUBBER,
                       roughness=0.92)

def draw_security_broken_screen_cracks(center, width=1.10, height=0.66, z_offset=0.35):
    """Cracked-glass layer for a damaged CRT; subtle and clearly visible in the flashlight."""
    draw_pbr_box(Vector3(center.x, center.y, center.z + z_offset),
                 Vector3(width, height, 0.014), C_CHAMBER_GLASS,
                 roughness=0.18, metallic=0.08)

    impact = Vector3(center.x - 0.07, center.y + 0.05, center.z + z_offset + 0.008)
    draw_pbr_cylinder(impact, 0.045, 0.010, C_METAL_DARK, roughness=0.9)

    segs = [
        (-0.07, 0.05, -0.36, 0.28), (-0.07, 0.05, -0.48, 0.02),
        (-0.07, 0.05, -0.28, -0.23), (-0.07, 0.05, 0.13, 0.30),
        (-0.07, 0.05, 0.34, 0.15),  (-0.07, 0.05, 0.29, -0.18),
        (-0.36, 0.28, -0.52, 0.42),  (-0.36, 0.28, -0.27, 0.45),
        (-0.48, 0.02, -0.65, -0.10), (-0.28, -0.23, -0.45, -0.36),
        (0.13, 0.30, 0.09, 0.43),    (0.34, 0.15, 0.52, 0.21),
        (0.29, -0.18, 0.44, -0.36),
    ]
    for ax, ay, bx, by in segs:
        dx, dy = bx-ax, by-ay
        length = math.sqrt(dx*dx + dy*dy)
        angle = math.degrees(math.atan2(dy, dx))
        mid = Vector3(center.x + (ax+bx)*0.5,
                      center.y + (ay+by)*0.5,
                      center.z + z_offset + 0.010)
        rl_push_matrix()
        rl_translatef(mid.x, mid.y, mid.z)
        rl_rotatef(angle, 0, 0, 1)
        draw_pbr_box(Vector3(0,0,0), Vector3(length,0.011,0.006), C_METAL_DARK,
                     roughness=0.92)
        rl_pop_matrix()

def draw_security_side_workstation_monitor(local_pos, tex_key="lab", is_powered=False, broken=False):
    """Twin CRT computer monitor for the formerly blank north-wall side table."""
    draw_cctv_monitor(local_pos, rot_y=0.0, width=1.26, height=0.80,
                      tex_key=tex_key, is_crt=True, is_powered=is_powered)

    # Model-specific rear/top service detailing.
