def draw_security_wall_surface_texture():
    """Subtle concrete seams and fine cracking; no large wallpaper-like rectangular panels."""
    # Thin construction seams reveal how the concrete wall sections were assembled.
    for z in (-3.95, -1.95, 1.95, 3.95):
        draw_pbr_box(Vector3(-23.948,3.45,z),Vector3(0.018,6.35,0.010),
                     C_FLOOR_CRACK,roughness=1.0,metallic=0.0)
