def draw_security_side_workstation(time_val=0.0, is_powered=False):
    """Fully dressed secondary/north-wall workstation: twin computers, lean, wiring and hardware."""
    rl_push_matrix()
    # Pivot at table center, north-wall workstation at (-18.5, -5.2).
    rl_translatef(-18.5, 0.0, -5.2)
    # Subtle overall sag: the support failure is visible, but the desk still feels heavy and planted.
    rl_rotatef(-2.0, 0, 0, 1)

    # Structural frame: heavy top, under-frame, two pedestals and a deliberately damaged support.
    # Real open carcass: rear panel + top/bottom structure, leaving the
    # two side storage pedestals physically hollow rather than overlaying
    # open frames on top of a solid rectangular volume.
    draw_pbr_box(Vector3(0,0.56,-0.54), Vector3(3.76,1.00,0.08),
                 C_SIDE_DESK_BODY_DARK, roughness=0.76, metallic=0.50)
    draw_pbr_box(Vector3(0,0.10,0.0), Vector3(3.76,0.08,1.34),
                 C_SIDE_DESK_BODY_DARK, roughness=0.78, metallic=0.54)
    draw_pbr_box(Vector3(0,1.29,0.18), Vector3(3.76,0.09,0.74),
                 C_SIDE_DESK_EDGE_DARK, roughness=0.50, metallic=0.76)
    draw_pbr_box(Vector3(0,1.445,0), Vector3(3.94,0.090,1.48),
                 C_SIDE_DESK_TOP_DARK, roughness=0.42, metallic=0.42)
    # Slightly dropped right edge sells the broken-support failure more naturally.
    draw_pbr_box(Vector3(1.18,1.415,0), Vector3(1.38,0.045,1.49),
                 C_SIDE_DESK_TOP_DARK, roughness=0.45, metallic=0.42)
    draw_pbr_box(Vector3(0,1.405,0), Vector3(4.02,0.044,1.53),
                 C_SIDE_DESK_EDGE_DARK, roughness=0.46, metallic=0.76)

    # Full outer end panels: substantial side cheeks matching the main desk.
    for side_x in (-1.94, 1.94):
        draw_pbr_box(Vector3(side_x, 0.76, 0.0), Vector3(0.16, 1.30, 1.43),
                     C_SIDE_DESK_BODY_DARK, roughness=0.66, metallic=0.58)
