def update_security_room_visibility(cam):
    """Compatibility no-op: neither room is hidden based on player position or camera direction."""
    global security_hides_main_lab
    security_hides_main_lab = False
    return False


def security_room_should_render(cam):
    """Render Security Room details only when nearby or when its doorway is in view."""
    # Electricity Room is far from Security Room; skip the entire costly Security detail pass.
    if cam.position.x > 18.24:
        return False

    # Absolute Security Room bounds after applying SECURITY_ROOM_OFFSET_*.
    sx_min, sx_max = -31.5, -18.8
    sz_min, sz_max = 8.8, 21.8
    px, pz = float(cam.position.x), float(cam.position.z)
    near_x = 0.0 if sx_min <= px <= sx_max else min(abs(px - sx_min), abs(px - sx_max))
    near_z = 0.0 if sz_min <= pz <= sz_max else min(abs(pz - sz_min), abs(pz - sz_max))
    if near_x*near_x + near_z*near_z <= 12.0*12.0:
        return True

    # From the Main Lab, only run the Security Room draw pass when looking near its open
    # west-wall aperture. Collision and interactable updates remain outside this draw gate.
    dx = -18.0 - px
    dz = 11.3 - pz
    d2 = dx*dx + dz*dz
    if d2 > 32.0*32.0:
        return False
    fwd_x = float(cam.target.x - cam.position.x)
    fwd_z = float(cam.target.z - cam.position.z)
    fwd_len = math.sqrt(fwd_x*fwd_x + fwd_z*fwd_z)
    dlen = math.sqrt(d2)
    if fwd_len < 1e-6 or dlen < 1e-6:
        return True
    return (fwd_x*dx + fwd_z*dz) / (fwd_len*dlen) >= 0.42


def update_security_lighting(dt, generator_powered, paused=False):
    global security_light_intensity, _security_flicker_event_timer
    global _security_flicker_hold_timer, _security_flicker_dip_value, _security_power_was_on
    if not generator_powered:
        security_light_intensity = 0.0
        # Reset the flicker schedule only on power-down, rather than consuming random
        # values every frame while the room is intentionally unpowered.
        if _security_power_was_on:
            _security_flicker_event_timer = random.uniform(2.5, 5.5)
        _security_power_was_on = False
        _security_flicker_hold_timer = 0.0
        return
    if not _security_power_was_on:
        _security_power_was_on = True
        security_light_intensity = 0.88
        _security_flicker_event_timer = random.uniform(2.0, 4.0)
        _security_flicker_hold_timer = 0.0
    if paused:
        return

    if _security_flicker_hold_timer > 0.0:
        _security_flicker_hold_timer = max(0.0, _security_flicker_hold_timer - max(0.0, dt))
        security_light_intensity = _security_flicker_dip_value
        return

    _security_flicker_event_timer -= max(0.0, dt)
    if _security_flicker_event_timer <= 0.0:
        if random.random() < 0.44:
            # Synchronized blackout: room-wide point lights AND emissive props go dark together.
            _security_flicker_dip_value = 0.0
            _security_flicker_hold_timer = random.uniform(0.10, 0.26)
        else:
            _security_flicker_dip_value = random.uniform(0.13, 0.30)
            _security_flicker_hold_timer = random.uniform(0.08, 0.18)
        _security_flicker_event_timer = random.uniform(2.8, 6.4)
        security_light_intensity = _security_flicker_dip_value
    else:
        # Mostly steady incandescent output with low-level variation between fault events.
        security_light_intensity = 0.88 + 0.08 * math.sin(global_time * 5.2)
        security_light_intensity = max(0.70, min(1.0, security_light_intensity))


def _apply_security_room_lighting(generator_powered, intensity):
    """Temporarily repurpose the five cached point-light slots for warm Security Room light."""
    value = max(0.0, min(1.0, float(intensity))) if generator_powered else 0.0
    if value > 0.05:
        ambient = Vector3(0.010 * value, 0.0078 * value, 0.0045 * value)
    else:
        ambient = Vector3(0.0012, 0.0015, 0.0020)  # truly dark until the shared generator mission
    set_shader_value(pbr_shader, loc_ambient, ambient, SHADER_UNIFORM_VEC3)
    for pos_loc, col_loc, pos, base_col in zip(
            _MAIN_LAB_LIGHT_POS_LOCS, _MAIN_LAB_LIGHT_COL_LOCS,
            _SECURITY_LIGHT_POSITIONS, _SECURITY_LIGHT_COLOURS):
        set_shader_value(pbr_shader, pos_loc, pos, SHADER_UNIFORM_VEC3)
        set_shader_value(pbr_shader, col_loc,
                         Vector3(base_col.x * value, base_col.y * value, base_col.z * value),
                         SHADER_UNIFORM_VEC3)


def _restore_main_lab_shader_lighting(generator_powered, surge_timer):
    # Restore the shared shader after a connected-room pass without undoing the Main Lab blackout.
    if generator_powered:
        ambient = Vector3(0.046, 0.051, 0.060)
        _restore_level = 0.98
    elif surge_timer > 0.0:
        _restore_level = 1.22 * _primary_switch_flicker_level(global_time)
        ambient = Vector3(0.003 + 0.018 * _restore_level,
                          0.004 + 0.020 * _restore_level,
                          0.005 + 0.022 * _restore_level)
    elif story_phase >= 1 or (story_phase == 0 and not generator_igniting):
        ambient = Vector3(0.0012, 0.0015, 0.0020)
        _restore_level = 0.0
    else:
        ambient = Vector3(0.046, 0.051, 0.060)
        _restore_level = 0.42
    set_shader_value(pbr_shader, loc_ambient, ambient, SHADER_UNIFORM_VEC3)
    for pos_loc, col_loc, pos in zip(_MAIN_LAB_LIGHT_POS_LOCS, _MAIN_LAB_LIGHT_COL_LOCS, MAIN_LAB_LIGHT_POSITIONS):
        set_shader_value(pbr_shader, pos_loc, pos, SHADER_UNIFORM_VEC3)
        if generator_powered:
            col = Vector3(0.98, 0.94, 0.87)
        else:
            col = Vector3(_restore_level, _restore_level * 1.02, _restore_level * 1.06)
        set_shader_value(pbr_shader, col_loc, col, SHADER_UNIFORM_VEC3)





# ============================================================================
# INTEGRATED INTRO / EXTERIOR HANDOFF
# The intro module has an isolated namespace, but uses the same already-open Raylib window.
# Its low-poly abandoned-lab exterior is reused outside the second code's Main Exit.
# ============================================================================

def _integrated_exit_pathway_transform():
    intro_ns = globals().get("_PROJECT_ECHO_INTRO_NS")
    if not isinstance(intro_ns, dict):
        return 0.0, 0.0, -61.0
    cx = float(intro_ns.get("LAB_CX", 0.0))
    base_y = float(intro_ns.get("LAB_BASE_Y", 0.0))
    front_z = float(intro_ns.get("LAB_FRONT_Z", 43.15))
    # Align the intro's exterior airlock plane just outside the second game's Main Exit.
    z_offset = -18.42 - front_z
    return -cx, -base_y, z_offset


def _integrated_exit_pathway_eye_height(world_z):
    intro_ns = globals().get("_PROJECT_ECHO_INTRO_NS")
    if not isinstance(intro_ns, dict):
        return 1.8
    _, base_y_offset, z_offset = _integrated_exit_pathway_transform()
    try:
        local_z = float(world_z) - z_offset
        h_fn = intro_ns.get("entrance_path_height")
        base_y = float(intro_ns.get("LAB_BASE_Y", 0.0))
        if callable(h_fn):
            # Standard first-person eye height follows the actual outdoor grade.
            return max(-2.0, min(4.0, 1.8 + float(h_fn(local_z)) - base_y))
    except Exception:
        pass
    return 1.8


def _draw_integrated_exterior_pathway_background():
    """Render the old approach road beyond the Main Exit during opening and escape sprint."""
    intro_ns = globals().get("_PROJECT_ECHO_INTRO_NS")
    if not isinstance(intro_ns, dict):
        return
    matrix_pushed = False
    try:
        cache = intro_ns.get("entrance_cache")
        if cache is None:
            builder = intro_ns.get("build_entrance_scene_cache")
            if not callable(builder):
                return
            cache = builder()
            intro_ns["entrance_cache"] = cache
        translate_x, translate_y, translate_z = _integrated_exit_pathway_transform()
        front_z = float(intro_ns.get("LAB_FRONT_Z", 43.15))
        local_cam_z = float(camera.position.z) - translate_z
        draw_range_min = local_cam_z - 180.0
        draw_range_max = local_cam_z + 100.0
        # Use the same low-poly night sky and ground from the menu/pathway scene.
        rl_push_matrix()
        matrix_pushed = True
        rl_translatef(float(translate_x), float(translate_y), float(translate_z))
        draw_cube(Vector3(0.0, -0.92, 20.0), 260.0, 1.0, 90.0, Color(30, 24, 18, 255))
        for pos, radius, col in getattr(cache, "sky_spheres", []):
            draw_sphere(pos, radius, col)
        for pos, w, h, d, col in getattr(cache, "sky_cubes", []):
            draw_cube(pos, w, h, d, col)

        # Animate the four path lamps without mutating the cached scenery arrays.
        lamp_colors = {}
        lamp_indices = intro_ns.get("PATH_LAMP_LIGHT_INDICES", [])
        lamps = intro_ns.get("PATH_LAMPS", [])
        now = float(globals().get("global_time", 0.0))
        for lamp_index, cube_index in enumerate(lamp_indices):
            if not (0 <= cube_index < len(getattr(cache, "world_cubes", []))):
                continue
            lamp = lamps[lamp_index % len(lamps)] if lamps else {"seed": 0.0}
            seed = float(lamp.get("seed", 0.0))
            t = now * 7.5 + seed * 0.731
            brightness = 0.72 + 0.13 * math.sin(t) + 0.09 * math.sin(t * 2.37 + 1.4) + 0.06 * math.sin(t * 6.10 + 0.8)
            dip = math.sin(now * 12.5 + seed * 1.83)
            if dip > 0.965:
                brightness *= 0.22
            elif dip > 0.91:
                brightness *= 0.48
            brightness = max(0.10, min(1.0, brightness))
            base = (255, 190, 50) if lamp_index % 2 == 0 else (255, 225, 105)
            low = (48, 34, 12) if lamp_index % 2 == 0 else (58, 44, 18)
            lamp_colors[cube_index] = Color(
                int(low[0] + (base[0] - low[0]) * brightness),
                int(low[1] + (base[1] - low[1]) * brightness),
                int(low[2] + (base[2] - low[2]) * brightness), 255)

        # The source cache contains the laboratory's front wall at the far end; omit that wall
        # so the Main Exit's open leaves reveal the path rather than another sealed facade.
        outside_limit = front_z - 0.55
        for idx, (pos, w, h, d, col, item_z) in enumerate(getattr(cache, "world_cubes", [])):
            if item_z >= outside_limit or not (draw_range_min <= item_z <= draw_range_max):
                continue
            draw_cube(pos, w, h, d, lamp_colors.get(idx, col))
        for pos, radius, col, item_z in getattr(cache, "world_spheres", []):
            if item_z < outside_limit and draw_range_min <= item_z <= draw_range_max:
                draw_sphere(pos, radius, col)
        for p0, p1, col, item_z in getattr(cache, "world_lines", []):
            if item_z < outside_limit and draw_range_min <= item_z <= draw_range_max:
                draw_line_3d(p0, p1, col)
        for p0, p1, r0, r1, segs, col, item_z in getattr(cache, "world_cylinders_ex", []):
            if item_z < outside_limit and draw_range_min <= item_z <= draw_range_max:
                draw_cylinder_ex(p0, p1, r0, r1, segs, col)
        for pos, r_top, r_bot, height, segs, col, item_z in getattr(cache, "world_cylinders", []):
            if item_z < outside_limit and draw_range_min <= item_z <= draw_range_max:
                draw_cylinder(pos, r_top, r_bot, height, segs, col)
        for p0, p1, p2, col, item_z in getattr(cache, "world_triangles", []):
            if item_z < outside_limit and draw_range_min <= item_z <= draw_range_max:
                draw_triangle_3d(p0, p1, p2, col)
        rl_pop_matrix()
        matrix_pushed = False
    except Exception:
        if matrix_pushed:
            try:
                rl_pop_matrix()
            except Exception:
                pass
        # A missing optional backdrop must not crash the actual ending/cinematic.
        return


