_PROJECT_ECHO_INTRO_NS["_intro_enter_original"] = _intro_enter_original
_PROJECT_ECHO_INTRO_NS["pytraceback"] = pytraceback
_handoff_setup = r"""
def enter_integrated_laboratory_state():
    _intro_enter_original()
    lab_app_ns["should_quit"] = False
    lab_app_ns["enter_laboratory_state"]()
    globals()["_integrated_lab_active"] = True

"""
exec(compile(_handoff_setup, "<project_echo_handoff>", "exec"), _PROJECT_ECHO_INTRO_NS)
